INSERT INTO knowledge_quiz VALUES(1,'Which scripture is considered the oldest of the Vedas?','वेदों में सबसे प्राचीन ग्रंथ कौन सा है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "C", "en": "Samaveda", "hi": "सामवेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','A');
INSERT INTO knowledge_quiz VALUES(2,'How many Vedas are there in Hinduism?','हिंदू धर्म में कितने वेद हैं?','[{"key": "A", "en": "Two", "hi": "दो"}, {"key": "B", "en": "Three", "hi": "तीन"}, {"key": "C", "en": "Four", "hi": "चार"}, {"key": "D", "en": "Five", "hi": "पाँच"}]','C');
INSERT INTO knowledge_quiz VALUES(3,'Who composed the Mahabharata?','महाभारत के रचयिता कौन माने जाते हैं?','[{"key": "A", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Kalidasa", "hi": "कालिदास"}, {"key": "D", "en": "Tulsidas", "hi": "तुलसीदास"}]','B');
INSERT INTO knowledge_quiz VALUES(4,'The Navalakha Temple, one of the oldest in Gujarat (11th century), is located in which mountain range?','नवलखा मंदिर, जो गुजरात के सबसे पुराने मंदिरों (11वीं शताब्दी) में से एक है, किस पर्वत श्रृंखला में स्थित है?','[{"key": "A", "en": "Barda Hills (Ghumli)", "hi": "बरडा हिल्स (घुमली)"}, {"key": "B", "en": "Girnar", "hi": "गिरनार"}, {"key": "C", "en": "Shetrunjaya", "hi": "शत्रुंजय"}, {"key": "D", "en": "Saputara", "hi": "सापुतारा"}]','A');
INSERT INTO knowledge_quiz VALUES(5,'Who is the preserver in the Hindu Trinity?','हिंदू त्रिमूर्ति में पालनकर्ता कौन हैं?','[{"key": "A", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','C');
INSERT INTO knowledge_quiz VALUES(6,'Who is known as the remover of obstacles?','विघ्नहर्ता कौन कहलाते हैं?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Hanuman", "hi": "हनुमान"}]','B');
INSERT INTO knowledge_quiz VALUES(7,'Which river is considered the holiest in Hinduism?','हिंदू धर्म में सबसे पवित्र नदी कौन सी है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','C');
INSERT INTO knowledge_quiz VALUES(8,'Who wrote the Ramayana?','रामायण के रचयिता कौन हैं?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "C", "en": "Kalidasa", "hi": "कालिदास"}, {"key": "D", "en": "Surdas", "hi": "सूरदास"}]','B');
INSERT INTO knowledge_quiz VALUES(9,'What does the word ''Yoga'' mean?','''योग'' शब्द का अर्थ क्या है?','[{"key": "A", "en": "Exercise", "hi": "व्यायाम"}, {"key": "B", "en": "Union", "hi": "संयोग"}, {"key": "C", "en": "Meditation", "hi": "ध्यान"}, {"key": "D", "en": "Breathing", "hi": "श्वास"}]','B');
INSERT INTO knowledge_quiz VALUES(10,'Which god is known as the destroyer?','संहारकर्ता कौन से देवता हैं?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','C');
INSERT INTO knowledge_quiz VALUES(11,'How many Upanishads are traditionally counted as principal?','मुख्य उपनिषदों की संख्या कितनी मानी जाती है?','[{"key": "A", "en": "8", "hi": "8"}, {"key": "B", "en": "10", "hi": "10"}, {"key": "C", "en": "11", "hi": "11"}, {"key": "D", "en": "13", "hi": "13"}]','C');
INSERT INTO knowledge_quiz VALUES(12,'Which temple in Bali, Indonesia, is known as the ''Mother Temple''?','बाली, इंडोनेशिया के किस मंदिर को ''मदर टेंपल'' (मातृ मंदिर) के रूप में जाना जाता है?','[{"key": "A", "en": "Tanah Lot", "hi": "तानाह लोट"}, {"key": "B", "en": "Uluwatu Temple", "hi": "उलुवातु मंदिर"}, {"key": "C", "en": "Pura Besakih", "hi": "पुरा बेसकिह"}, {"key": "D", "en": "Tirta Empul", "hi": "तिर्ता एम्पुल"}]','C');
INSERT INTO knowledge_quiz VALUES(13,'Who is the monkey devotee of Lord Rama?','भगवान राम के वानर भक्त कौन हैं?','[{"key": "A", "en": "Sugriva", "hi": "सुग्रीव"}, {"key": "B", "en": "Vali", "hi": "वालि"}, {"key": "C", "en": "Hanuman", "hi": "हनुमान"}, {"key": "D", "en": "Angada", "hi": "अंगद"}]','C');
INSERT INTO knowledge_quiz VALUES(14,'Which goddess is worshipped as the goddess of knowledge?','ज्ञान की देवी कौन मानी जाती हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','C');
INSERT INTO knowledge_quiz VALUES(15,'The temple of Lord Jyotiba near Kolhapur is believed to be an incarnation of which three deities combined?','कोल्हापुर के पास भगवान जोतिबा के मंदिर को किन तीन देवताओं का संयुक्त अवतार माना जाता है?','[{"key": "A", "en": "Brahma, Vishnu, Mahesh", "hi": "ब्रह्मा, विष्णु, महेश"}, {"key": "B", "en": "Shiva, Surya, Kaal", "hi": "शिव, सूर्य, काल"}, {"key": "C", "en": "Ram, Krishna, Hari", "hi": "राम, कृष्ण, हरि"}, {"key": "D", "en": "Ganesha, Kartikeya, Shiva", "hi": "गणेश, कार्तिकेय, शिव"}]','A');
INSERT INTO knowledge_quiz VALUES(16,'What is the ultimate goal of life according to Hindu philosophy?','हिंदू दर्शन के अनुसार जीवन का परम लक्ष्य क्या है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Artha", "hi": "अर्थ"}, {"key": "C", "en": "Kama", "hi": "काम"}, {"key": "D", "en": "Moksha", "hi": "मोक्ष"}]','D');
INSERT INTO knowledge_quiz VALUES(17,'Which avatar of Vishnu is half-man and half-lion?','विष्णु का कौन सा अवतार आधा मनुष्य और आधा सिंह है?','[{"key": "A", "en": "Varaha", "hi": "वराह"}, {"key": "B", "en": "Narasimha", "hi": "नरसिंह"}, {"key": "C", "en": "Vamana", "hi": "वामन"}, {"key": "D", "en": "Rama", "hi": "राम"}]','B');
INSERT INTO knowledge_quiz VALUES(18,'Which epic narrates the story of Lord Rama?','कौन सा महाकाव्य भगवान राम की कथा बताता है?','[{"key": "A", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "B", "en": "Ramayana", "hi": "रामायण"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Shiva Purana", "hi": "शिव पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(19,'Which temple is one of the twelve Jyotirlingas?','बारह ज्योतिर्लिंगों में से एक कौन सा है?','[{"key": "A", "en": "Somnath", "hi": "सोमनाथ"}, {"key": "B", "en": "Puri", "hi": "पुरी"}, {"key": "C", "en": "Tirupati", "hi": "तिरुपति"}, {"key": "D", "en": "Dwarka", "hi": "द्वारका"}]','A');
INSERT INTO knowledge_quiz VALUES(20,'The Mannarasala Sree Nagaraja Temple is unique because its rituals are traditionally headed by whom?','मन्नारसाला श्री नागराज मंदिर अद्वितीय है क्योंकि इसके अनुष्ठानों का नेतृत्व पारंपरिक रूप से किसके द्वारा किया जाता है?','[{"key": "A", "en": "A child priest", "hi": "एक बाल पुजारी"}, {"key": "B", "en": "A female priestess (Amma)", "hi": "एक महिला पुजारिन (अम्मा)"}, {"key": "C", "en": "The oldest male member", "hi": "सबसे बड़ा पुरुष सदस्य"}, {"key": "D", "en": "The King of Travancore", "hi": "त्रावणकोर के राजा"}]','B');
INSERT INTO knowledge_quiz VALUES(21,'Which mountain is considered the abode of Lord Shiva?','कौन सा पर्वत भगवान शिव का निवास माना जाता है?','[{"key": "A", "en": "Mount Kailash", "hi": "माउंट कैलाश"}, {"key": "B", "en": "Mount Meru", "hi": "माउंट मेरु"}, {"key": "C", "en": "Himalaya", "hi": "हिमालय"}, {"key": "D", "en": "Vindhya", "hi": "विंध्य"}]','A');
INSERT INTO knowledge_quiz VALUES(22,'Which sacred syllable represents ultimate reality?','कौन सा पवित्र अक्षर परम सत्य का प्रतीक है?','[{"key": "A", "en": "Om", "hi": "ॐ"}, {"key": "B", "en": "Hum", "hi": "हुम"}, {"key": "C", "en": "Ram", "hi": "राम"}, {"key": "D", "en": "Namah", "hi": "नमः"}]','A');
INSERT INTO knowledge_quiz VALUES(23,'Who is the consort of Lord Vishnu?','भगवान विष्णु की पत्नी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Radha", "hi": "राधा"}]','C');
INSERT INTO knowledge_quiz VALUES(24,'Which yuga are we currently in according to Hindu belief?','हिंदू मान्यता के अनुसार वर्तमान में कौन सा युग चल रहा है?','[{"key": "A", "en": "Satya Yuga", "hi": "सत्य युग"}, {"key": "B", "en": "Treta Yuga", "hi": "त्रेता युग"}, {"key": "C", "en": "Dvapara Yuga", "hi": "द्वापर युग"}, {"key": "D", "en": "Kali Yuga", "hi": "कलियुग"}]','D');
INSERT INTO knowledge_quiz VALUES(25,'Which temple is dedicated to Lord Venkateswara?','भगवान वेंकटेश्वर को समर्पित मंदिर कौन सा है?','[{"key": "A", "en": "Tirupati", "hi": "तिरुपति"}, {"key": "B", "en": "Kedarnath", "hi": "केदारनाथ"}, {"key": "C", "en": "Badrinath", "hi": "बद्रीनाथ"}, {"key": "D", "en": "Rameswaram", "hi": "रामेश्वरम"}]','A');
INSERT INTO knowledge_quiz VALUES(26,'Who is the son of Lord Shiva and Goddess Parvati?','भगवान शिव और माता पार्वती के पुत्र कौन हैं?','[{"key": "A", "en": "Ganesha", "hi": "गणेश"}, {"key": "B", "en": "Kartikey", "hi": "कार्तिकेय"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "None", "hi": "कोई नहीं"}]','C');
INSERT INTO knowledge_quiz VALUES(27,'Which text focuses mainly on devotion (Bhakti)?','कौन सा ग्रंथ भक्ति पर मुख्य रूप से केंद्रित है?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "C", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "D", "en": "Yoga Sutra", "hi": "योग सूत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(28,'Which goddess is worshipped during Navratri?','नवरात्रि में किस देवी की पूजा की जाती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','C');
INSERT INTO knowledge_quiz VALUES(29,'Which place is known as the city of temples?','कौन सा नगर मंदिरों का शहर कहलाता है?','[{"key": "A", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "B", "en": "Madurai", "hi": "मदुरै"}, {"key": "C", "en": "Kanchipuram", "hi": "कांचीपुरम"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(30,'Which sage compiled the Vedas?','वेदों का संकलन किस ऋषि ने किया?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Bharadwaj", "hi": "भारद्वाज"}]','B');
INSERT INTO knowledge_quiz VALUES(31,'Which god holds the Sudarshan Chakra?','सुदर्शन चक्र किस देवता के पास है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Rama", "hi": "राम"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(32,'Which temple is part of the Char Dham in Uttarakhand?','उत्तराखंड के चार धामों में से कौन सा है?','[{"key": "A", "en": "Badrinath", "hi": "बद्रीनाथ"}, {"key": "B", "en": "Dwarka", "hi": "द्वारका"}, {"key": "C", "en": "Puri", "hi": "पुरी"}, {"key": "D", "en": "Rameswaram", "hi": "रामेश्वरम"}]','A');
INSERT INTO knowledge_quiz VALUES(33,'What is Karma?','कर्म का अर्थ क्या है?','[{"key": "A", "en": "Fate", "hi": "भाग्य"}, {"key": "B", "en": "Action", "hi": "कर्म"}, {"key": "C", "en": "Prayer", "hi": "प्रार्थना"}, {"key": "D", "en": "Meditation", "hi": "ध्यान"}]','B');
INSERT INTO knowledge_quiz VALUES(34,'Which goddess emerged during the churning of the ocean?','समुद्र मंथन के दौरान कौन सी देवी प्रकट हुईं?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(35,'Which festival marks the birth of Lord Krishna?','भगवान कृष्ण का जन्म किस पर्व पर मनाया जाता है?','[{"key": "A", "en": "Holi", "hi": "होली"}, {"key": "B", "en": "Janmashtami", "hi": "जन्माष्टमी"}, {"key": "C", "en": "Diwali", "hi": "दीवाली"}, {"key": "D", "en": "Navratri", "hi": "नवरात्रि"}]','B');
INSERT INTO knowledge_quiz VALUES(36,'Which demon king was defeated by Lord Rama?','भगवान राम ने किस राक्षस राजा का वध किया?','[{"key": "A", "en": "Kumbhakarna", "hi": "कुंभकर्ण"}, {"key": "B", "en": "Ravana", "hi": "रावण"}, {"key": "C", "en": "Bali", "hi": "बलि"}, {"key": "D", "en": "Hiranyakashipu", "hi": "हिरण्यकशिपु"}]','B');
INSERT INTO knowledge_quiz VALUES(37,'Which weapon is associated with Lord Shiva?','भगवान शिव का प्रमुख अस्त्र कौन सा है?','[{"key": "A", "en": "Bow", "hi": "धनुष"}, {"key": "B", "en": "Trident", "hi": "त्रिशूल"}, {"key": "C", "en": "Chakra", "hi": "चक्र"}, {"key": "D", "en": "Mace", "hi": "गदा"}]','B');
INSERT INTO knowledge_quiz VALUES(38,'Which sage is associated with the Gayatri Mantra?','गायत्री मंत्र किस ऋषि से संबंधित है?','[{"key": "A", "en": "Vishwamitra", "hi": "विश्वामित्र"}, {"key": "B", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "C", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "D", "en": "Narada", "hi": "नारद"}]','A');
INSERT INTO knowledge_quiz VALUES(39,'Which temple is dedicated to Lord Shiva in Tamil Nadu?','तमिलनाडु में भगवान शिव का प्रसिद्ध मंदिर कौन सा है?','[{"key": "A", "en": "Meenakshi Temple", "hi": "मीनाक्षी मंदिर"}, {"key": "B", "en": "Brihadeeswarar Temple", "hi": "बृहदेश्वर मंदिर"}, {"key": "C", "en": "Tirupati", "hi": "तिरुपति"}, {"key": "D", "en": "Ranganathaswamy Temple", "hi": "रंगनाथस्वामी मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(40,'What is the sacred thread ceremony called?','यज्ञोपवीत संस्कार को क्या कहा जाता है?','[{"key": "A", "en": "Vivaha", "hi": "विवाह"}, {"key": "B", "en": "Upanayana", "hi": "उपनयन"}, {"key": "C", "en": "Antyeshti", "hi": "अंत्येष्टि"}, {"key": "D", "en": "Namkaran", "hi": "नामकरण"}]','B');
INSERT INTO knowledge_quiz VALUES(41,'Which god is known as the king of gods?','देवताओं के राजा कौन कहलाते हैं?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Yama", "hi": "यम"}]','B');
INSERT INTO knowledge_quiz VALUES(42,'Which text explains Yoga philosophy?','योग दर्शन किस ग्रंथ में वर्णित है?','[{"key": "A", "en": "Yoga Sutra", "hi": "योग सूत्र"}, {"key": "B", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "C", "en": "Ramayana", "hi": "रामायण"}, {"key": "D", "en": "Vedas", "hi": "वेद"}]','A');
INSERT INTO knowledge_quiz VALUES(43,'Who is the wife of Lord Shiva?','भगवान शिव की पत्नी कौन हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','B');
INSERT INTO knowledge_quiz VALUES(44,'Which ashram stage comes after Grihastha?','गृहस्थ आश्रम के बाद कौन सा आश्रम आता है?','[{"key": "A", "en": "Brahmacharya", "hi": "ब्रह्मचर्य"}, {"key": "B", "en": "Vanaprastha", "hi": "वानप्रस्थ"}, {"key": "C", "en": "Sannyasa", "hi": "संन्यास"}, {"key": "D", "en": "Tapasya", "hi": "तपस्या"}]','B');
INSERT INTO knowledge_quiz VALUES(45,'Which god rides Garuda?','गरुड़ किस देवता का वाहन है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','A');
INSERT INTO knowledge_quiz VALUES(46,'Which scripture deals with law and social duties?','कौन सा ग्रंथ कानून और सामाजिक कर्तव्यों से संबंधित है?','[{"key": "A", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Vedas", "hi": "वेद"}]','A');
