INSERT INTO knowledge_quiz VALUES(51,'Who is known as the author of the Yoga Sutras?','योग सूत्रों के रचयिता कौन हैं?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Patanjali", "hi": "पतंजलि"}, {"key": "C", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "D", "en": "Kapila", "hi": "कपिल"}]','B');
