INSERT INTO knowledge_quiz VALUES(53,'Which festival is known as the festival of colors?','रंगों का त्योहार कौन सा है?','[{"key": "A", "en": "Diwali", "hi": "दीवाली"}, {"key": "B", "en": "Holi", "hi": "होली"}, {"key": "C", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "D", "en": "Dussehra", "hi": "दशहरा"}]','B');
INSERT INTO knowledge_quiz VALUES(54,'Who was the guru of Lord Krishna?','भगवान कृष्ण के गुरु कौन थे?','[{"key": "A", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "B", "en": "Sandipani", "hi": "संदीपनि"}, {"key": "C", "en": "Dronacharya", "hi": "द्रोणाचार्य"}, {"key": "D", "en": "Parashurama", "hi": "परशुराम"}]','B');
INSERT INTO knowledge_quiz VALUES(55,'Which river is associated with Lord Krishna’s childhood?','भगवान कृष्ण के बाल्यकाल से कौन सी नदी जुड़ी है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','B');
INSERT INTO knowledge_quiz VALUES(56,'Which demon was slain by Goddess Durga?','माँ दुर्गा ने किस असुर का वध किया?','[{"key": "A", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "B", "en": "Ravana", "hi": "रावण"}, {"key": "C", "en": "Bhasmasura", "hi": "भस्मासुर"}, {"key": "D", "en": "Hiranyaksha", "hi": "हिरण्याक्ष"}]','A');
INSERT INTO knowledge_quiz VALUES(57,'Which sacred city is also called Kashi?','कौन सा पवित्र नगर काशी कहलाता है?','[{"key": "A", "en": "Prayagraj", "hi": "प्रयागराज"}, {"key": "B", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "C", "en": "Haridwar", "hi": "हरिद्वार"}, {"key": "D", "en": "Ujjain", "hi": "उज्जैन"}]','B');
INSERT INTO knowledge_quiz VALUES(58,'Which god is known as Gopala?','गोपाल किस देवता का नाम है?','[{"key": "A", "en": "Rama", "hi": "राम"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','B');
INSERT INTO knowledge_quiz VALUES(59,'Which asana is commonly used for meditation?','ध्यान के लिए सामान्यतः कौन सा आसन उपयोग होता है?','[{"key": "A", "en": "Padmasana", "hi": "पद्मासन"}, {"key": "B", "en": "Shirshasana", "hi": "शीर्षासन"}, {"key": "C", "en": "Halasana", "hi": "हलासन"}, {"key": "D", "en": "Dhanurasana", "hi": "धनुरासन"}]','A');
INSERT INTO knowledge_quiz VALUES(60,'Which scripture begins with the Gayatri Mantra?','गायत्री मंत्र किस ग्रंथ में मिलता है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Samaveda", "hi": "सामवेद"}, {"key": "C", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','A');
INSERT INTO knowledge_quiz VALUES(61,'Which god is worshipped at Kedarnath?','केदारनाथ में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(62,'Which river originates from Gangotri?','गंगोत्री से कौन सी नदी निकलती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Alaknanda", "hi": "अलकनंदा"}, {"key": "D", "en": "Mandakini", "hi": "मंदाकिनी"}]','B');
INSERT INTO knowledge_quiz VALUES(63,'What was the name of the place where Lord Krishna left his mortal body?','उस स्थान का नाम क्या था जहाँ भगवान कृष्ण ने अपना नश्वर शरीर त्यागा था?','[{"key": "A", "en": "Dwaraka", "hi": "द्वारका"}, {"key": "B", "en": "Bhalka Tirtha (Prabhas Patan)", "hi": "भालका तीर्थ (प्रभास पाटन)"}, {"key": "C", "en": "Mathura", "hi": "मथुरा"}, {"key": "D", "en": "Vrindavan", "hi": "वृंदावन"}]','B');
