INSERT INTO knowledge_quiz VALUES(65,'Which holy book is a dialogue between Krishna and Arjuna?','कौन सा ग्रंथ कृष्ण और अर्जुन के संवाद पर आधारित है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Purana", "hi": "पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(66,'Which of these characters in the Mahabharata have seen the Krishna''s Vishwaroop?','महाभारत का वह पात्र कौन है जिसने कृष्ण का विश्वरूप देखा था?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Uttanka Rishi", "hi": "उत्तंक ऋषि"}, {"key": "C", "en": "Sanjaya", "hi": "संजय"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(67,'Which temple is famous for the Rath Yatra?','रथ यात्रा के लिए कौन सा मंदिर प्रसिद्ध है?','[{"key": "A", "en": "Dwarka", "hi": "द्वारका"}, {"key": "B", "en": "Puri", "hi": "पुरी"}, {"key": "C", "en": "Mathura", "hi": "मथुरा"}, {"key": "D", "en": "Ayodhya", "hi": "अयोध्या"}]','B');
