INSERT INTO knowledge_quiz VALUES(69,'Which scripture explains duties of kings and rulers?','राजाओं के कर्तव्यों का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Vedas", "hi": "वेद"}]','A');
INSERT INTO knowledge_quiz VALUES(70,'Which goddess is associated with wealth?','धन की देवी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(71,'Which god is worshipped as Vithoba?','विठोबा के रूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Rama", "hi": "राम"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','A');
INSERT INTO knowledge_quiz VALUES(72,'Which pilgrimage includes Prayagraj, Haridwar, Ujjain, and Nashik?','प्रयागराज, हरिद्वार, उज्जैन और नासिक किस तीर्थ से जुड़े हैं?','[{"key": "A", "en": "Char Dham", "hi": "चार धाम"}, {"key": "B", "en": "Kumbh Mela", "hi": "कुंभ मेला"}, {"key": "C", "en": "Jyotirlinga Yatra", "hi": "ज्योतिर्लिंग यात्रा"}, {"key": "D", "en": "Shakti Peeth", "hi": "शक्ति पीठ"}]','B');
INSERT INTO knowledge_quiz VALUES(73,'Which god is known as the lord of fire?','अग्नि के देवता कौन हैं?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Surya", "hi": "सूर्य"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','A');
INSERT INTO knowledge_quiz VALUES(74,'Which text describes the story of King Harishchandra?','राजा हरिश्चंद्र की कथा किस ग्रंथ में मिलती है?','[{"key": "A", "en": "Markandeya Purana", "hi": "मार्कण्डेय पुराण"}, {"key": "B", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "C", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "D", "en": "Ramayana", "hi": "रामायण"}]','A');
INSERT INTO knowledge_quiz VALUES(75,'What does the word ''Kedarnath'' literally mean in Sanskrit?','संस्कृत में ''केदारनाथ'' शब्द का शाब्दिक अर्थ क्या है?','[{"key": "A", "en": "Lord of the Mountains", "hi": "पर्वतों का स्वामी"}, {"key": "B", "en": "Lord of the Field", "hi": "क्षेत्र (खेत) का स्वामी"}, {"key": "C", "en": "Lord of the Snow", "hi": "बर्फ का स्वामी"}, {"key": "D", "en": "Lord of Liberation", "hi": "मुक्ति का स्वामी"}]','B');
INSERT INTO knowledge_quiz VALUES(76,'In the Hanuman Chalisa, ''Kandan'' in the line ''Sankat Se Hanuman Chudavai, Man Kram Bachan Dhyan Jo Lavai'' refers to which three ways of devotion?','हनुमान चालीसा में, ''संकट तें हनुमान छुड़ावै, मन क्रम बचन ध्यान जो लावै'' में भक्ति के किन तीन तरीकों का उल्लेख है?','[{"key": "A", "en": "Mind, Action, Speech", "hi": "मन, कर्म, वचन"}, {"key": "B", "en": "Yoga, Dhyana, Bhakti", "hi": "योग, ध्यान, भक्ति"}, {"key": "C", "en": "Fast, Prayer, Charity", "hi": "व्रत, प्रार्थना, दान"}, {"key": "D", "en": "Sleep, Eat, Work", "hi": "निद्रा, आहार, कर्म"}]','A');
INSERT INTO knowledge_quiz VALUES(77,'Which sage is considered the father of Ayurveda?','आयुर्वेद के जनक कौन माने जाते हैं?','[{"key": "A", "en": "Charaka", "hi": "चरक"}, {"key": "B", "en": "Sushruta", "hi": "सुश्रुत"}, {"key": "C", "en": "Dhanvantari", "hi": "धन्वंतरि"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','C');
INSERT INTO knowledge_quiz VALUES(78,'Which goddess rides a lion?','कौन सी देवी सिंह पर सवार होती हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','C');
INSERT INTO knowledge_quiz VALUES(79,'Which sacred text is also called Vedanta?','किस ग्रंथ को वेदांत कहा जाता है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Puranas", "hi": "पुराण"}, {"key": "C", "en": "Smritis", "hi": "स्मृतियाँ"}, {"key": "D", "en": "Brahmanas", "hi": "ब्राह्मण"}]','A');
INSERT INTO knowledge_quiz VALUES(80,'Which god is known as the lord of water?','जल के देवता कौन हैं?','[{"key": "A", "en": "Varuna", "hi": "वरुण"}, {"key": "B", "en": "Agni", "hi": "अग्नि"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','A');
INSERT INTO knowledge_quiz VALUES(81,'Which place is considered the birthplace of Lord Rama?','भगवान राम का जन्मस्थान कौन सा है?','[{"key": "A", "en": "Mathura", "hi": "मथुरा"}, {"key": "B", "en": "Ayodhya", "hi": "अयोध्या"}, {"key": "C", "en": "Dwarka", "hi": "द्वारका"}, {"key": "D", "en": "Chitrakoot", "hi": "चित्रकूट"}]','B');
INSERT INTO knowledge_quiz VALUES(82,'Which god is worshipped as the destroyer of ego?','अहंकार के नाशक के रूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','A');
INSERT INTO knowledge_quiz VALUES(83,'Which temple is also known as the Golden Temple of South India?','दक्षिण भारत का स्वर्ण मंदिर किसे कहा जाता है?','[{"key": "A", "en": "Tirupati", "hi": "तिरुपति"}, {"key": "B", "en": "Rameswaram", "hi": "रामेश्वरम"}, {"key": "C", "en": "Chidambaram", "hi": "चिदंबरम"}, {"key": "D", "en": "Srirangam", "hi": "श्रीरंगम"}]','A');
