INSERT INTO knowledge_quiz VALUES(85,'Which god is worshipped as the lord of wisdom?','बुद्धि के देवता कौन माने जाते हैं?','[{"key": "A", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','B');
INSERT INTO knowledge_quiz VALUES(86,'Which scripture narrates stories of Lord Krishna’s childhood?','भगवान कृष्ण के बाल्यकाल की कथाएँ किस ग्रंथ में हैं?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "D", "en": "Ramayana", "hi": "रामायण"}]','A');
