INSERT INTO knowledge_quiz VALUES(221,'Which goddess is worshipped as the consort of Lord Shiva?','भगवान शिव की पत्नी कौन हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','B');
INSERT INTO knowledge_quiz VALUES(222,'Which sacred sound is chanted at the beginning of rituals?','किस पवित्र ध्वनि का उच्चारण यज्ञ के आरंभ में होता है?','[{"key": "A", "en": "Om", "hi": "ॐ"}, {"key": "B", "en": "Hum", "hi": "हुम्"}, {"key": "C", "en": "Ram", "hi": "राम"}, {"key": "D", "en": "Namah", "hi": "नमः"}]','A');
INSERT INTO knowledge_quiz VALUES(223,'Which demon disguised himself as a sage to deceive Hanuman?','कौन सा राक्षस हनुमान को धोखा देने के लिए ऋषि का वेश धारण करके आया था?','[{"key": "A", "en": "Ravana", "hi": "रावण"}, {"key": "B", "en": "Kalanemi", "hi": "कालनेमि"}, {"key": "C", "en": "Meghnad", "hi": "मेघनाद"}, {"key": "D", "en": "Atikaya", "hi": "अतिकाय"}]','B');
INSERT INTO knowledge_quiz VALUES(224,'Which goddess is worshipped as the protector of women?','स्त्रियों की रक्षक देवी कौन हैं?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Kali", "hi": "काली"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(225,'Where was Hanuman going when Kalanemi tried to stop him?','जब कालनेमि ने हनुमान को रोकने की कोशिश की, तब हनुमान कहाँ जा रहे थे?','[{"key": "A", "en": "To Lanka", "hi": "लंका"}, {"key": "B", "en": "To bring Sanjeevani herb", "hi": "संजीवनी बूटी लाने"}, {"key": "C", "en": "To Ayodhya", "hi": "अयोध्या"}, {"key": "D", "en": "To Kishkindha", "hi": "किष्किंधा"}]','B');
INSERT INTO knowledge_quiz VALUES(226,'Which goddess is worshipped as the presiding deity of learning?','विद्या की अधिष्ठात्री देवी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(227,'Who sent the demon Kalanemi to stop Hanuman in the Ramayana?','रामायण में हनुमान को रोकने के लिए राक्षस कालनेमि को किसने भेजा था?','[{"key": "A", "en": "Ravana", "hi": "रावण"}, {"key": "B", "en": "Meghnad", "hi": "मेघनाद"}, {"key": "C", "en": "Kumbhakarna", "hi": "कुंभकर्ण"}, {"key": "D", "en": "Vibhishana", "hi": "विभीषण"}]','A');
INSERT INTO knowledge_quiz VALUES(228,'Which sacred river is worshipped as a mother?','माता के रूप में किस पवित्र नदी की पूजा होती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(229,'In Ramayana, Who was the father of Bali(Vali)?','रामायण में, बाली के पिता कौन थे?','[{"key": "A", "en": "Surya", "hi": "सूर्य"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Vayu", "hi": "वायु"}, {"key": "D", "en": "Kubera", "hi": "कुबेर"}]','B');
INSERT INTO knowledge_quiz VALUES(230,'Which ancient temple in Meerut is associated with the ''Mahabharata'' and is said to have been visited by the Pandavas?','मेरठ का कौन सा प्राचीन मंदिर ''महाभारत'' से जुड़ा है और कहा जाता है कि पांडवों ने यहाँ दर्शन किए थे?','[{"key": "A", "en": "Augharnath Temple", "hi": "औघड़नाथ मंदिर"}, {"key": "B", "en": "Bale-Miyan Dargah", "hi": "बाले-मियाँ दरगाह"}, {"key": "C", "en": "Shahpir Mausoleum", "hi": "शाहपीर मकबरा"}, {"key": "D", "en": "Chandi Devi", "hi": "चंडी देवी"}]','A');
