INSERT INTO knowledge_quiz VALUES(238,'Where did Rama, Lakshmana, and Sita spend their first night after leaving Ayodhya?','अयोध्या छोड़ने के बाद राम, लक्ष्मण और सीता ने अपनी पहली रात कहाँ बिताई?','[{"key": "A", "en": "Chitrakoot", "hi": "चित्रकूट"}, {"key": "B", "en": "Banks of the Tamasa River", "hi": "तमसा नदी के तट पर"}, {"key": "C", "en": "Panchavati", "hi": "पंचवटी"}, {"key": "D", "en": "Dandakaranya", "hi": "दंडकारण्य"}]','B');
INSERT INTO knowledge_quiz VALUES(239,'Which sacred city is associated with liberation?','मोक्ष से जुड़ा पवित्र नगर कौन सा है?','[{"key": "A", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "B", "en": "Haridwar", "hi": "हरिद्वार"}, {"key": "C", "en": "Prayagraj", "hi": "प्रयागराज"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
