INSERT INTO knowledge_quiz VALUES(245,'Which sage cursed the monkey-king Vali that he would die if he entered the Rishyamukha mountain?','किस ऋषि ने बाली को श्राप दिया था कि यदि वह ऋष्यमूक पर्वत पर गया तो उसकी मृत्यु हो जाएगी?','[{"key": "A", "en": "Sage Matanga", "hi": "ऋषि मतंग"}, {"key": "B", "en": "Sage Agastya", "hi": "ऋषि अगस्त्य"}, {"key": "C", "en": "Sage Gautama", "hi": "ऋषि गौतम"}, {"key": "D", "en": "Sage Durvasa", "hi": "ऋषि दुर्वासा"}]','A');
INSERT INTO knowledge_quiz VALUES(246,'Which sacred day is considered auspicious for Goddess Lakshmi?','देवी लक्ष्मी के लिए कौन सा दिन शुभ माना जाता है?','[{"key": "A", "en": "Friday", "hi": "शुक्रवार"}, {"key": "B", "en": "Monday", "hi": "सोमवार"}, {"key": "C", "en": "Tuesday", "hi": "मंगलवार"}, {"key": "D", "en": "Thursday", "hi": "गुरुवार"}]','A');
