INSERT INTO knowledge_quiz VALUES(248,'How many ''Kandas'' (books) are there in the original Valmiki Ramayana?','मूल वाल्मीकि रामायण में कितने ''कांड'' हैं?','[{"key": "A", "en": "Five", "hi": "पाँच"}, {"key": "B", "en": "Nine", "hi": "नौ"}, {"key": "C", "en": "Seven", "hi": "सात"}, {"key": "D", "en": "Eight", "hi": "आठ"}]','C');
INSERT INTO knowledge_quiz VALUES(249,'Which goddess is worshipped as the symbol of peace?','शांति की प्रतीक देवी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','D');
INSERT INTO knowledge_quiz VALUES(250,'Which sacred goal represents liberation in Hinduism?','हिंदू धर्म में मोक्ष किस लक्ष्य का प्रतीक है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Artha", "hi": "अर्थ"}, {"key": "C", "en": "Kama", "hi": "काम"}, {"key": "D", "en": "Moksha", "hi": "मोक्ष"}]','D');
INSERT INTO knowledge_quiz VALUES(251,'Which goddess is worshipped as the presiding deity of fortune?','सौभाग्य की अधिष्ठात्री देवी कौन हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(252,'Which sacred text contains teachings of devotion and philosophy of Krishna?','भगवान कृष्ण की भक्ति और दर्शन की शिक्षाएँ किस ग्रंथ में हैं?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "C", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "D", "en": "Skanda Purana", "hi": "स्कंद पुराण"}]','A');
