INSERT INTO knowledge_quiz VALUES(255,'Which god is worshipped as the embodiment of righteousness?','धर्म के साक्षात स्वरूप कौन माने जाते हैं?','[{"key": "A", "en": "Rama", "hi": "राम"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(256,'Which goddess is worshipped as the presiding deity of learning and arts?','विद्या और कला की अधिष्ठात्री देवी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(257,'Which god is worshipped as the lord of ascetics?','संन्यासियों के स्वामी कौन माने जाते हैं?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','A');
