INSERT INTO knowledge_quiz VALUES(261,'Who was the son of Laxmana and Urmila?','लक्ष्मण और ऊर्मिला के पुत्र कौन थे?','[{"key": "A", "en": "Angad and Dharmaketu", "hi": "अंगद और धर्मकेतु"}, {"key": "B", "en": "Subahu and Shatrughati", "hi": "सुबाहु और शत्रुघाती"}, {"key": "C", "en": "Angad and Chandraketu", "hi": "अंगद और चंद्रकेतु"}, {"key": "D", "en": "Taksha and Pushkala", "hi": "तक्ष और पुष्कल"}]','C');
