INSERT INTO knowledge_quiz VALUES(357,'Which goddess is worshipped as the embodiment of chastity?','पातिव्रत्य की प्रतीक देवी कौन हैं?','[{"key": "A", "en": "Sita", "hi": "सीता"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Anasuya", "hi": "अनसूया"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
