INSERT INTO knowledge_quiz VALUES(399,'Which goddess is worshipped as the embodiment of devotion and faith?','भक्ति और श्रद्धा की प्रतीक देवी कौन हैं?','[{"key": "A", "en": "Radha", "hi": "राधा"}, {"key": "B", "en": "Sita", "hi": "सीता"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(400,'Which ultimate goal represents freedom from samsara?','संसार चक्र से मुक्ति का अंतिम लक्ष्य कौन सा है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Artha", "hi": "अर्थ"}, {"key": "C", "en": "Kama", "hi": "काम"}, {"key": "D", "en": "Moksha", "hi": "मोक्ष"}]','D');
