INSERT INTO knowledge_quiz VALUES(402,'Which god requested Krishna and Arjuna to help burn the Khandava forest?','किस देव ने कृष्ण और अर्जुन से खांडव वन जलाने में सहायता मांगी थी?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Vayu", "hi": "वायु"}, {"key": "C", "en": "Indra", "hi": "इन्द्र"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','A');
INSERT INTO knowledge_quiz VALUES(403,'Which sacred text narrates the story of Lord Rama?','भगवान राम की कथा किस ग्रंथ में वर्णित है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Vedas", "hi": "वेद"}]','A');
INSERT INTO knowledge_quiz VALUES(404,'Which goddess is worshipped as the presiding deity of learning and arts?','विद्या और कला की अधिष्ठात्री देवी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','A');
INSERT INTO knowledge_quiz VALUES(405,'What was the name of the demon who was killed by Lord Shiva and later worshipped as a Jyotirlinga?','उस राक्षस का क्या नाम था जिसे भगवान शिव ने मारा और बाद में उसी स्थान पर ज्योतिर्लिंग की स्थापना हुई?','[{"key": "A", "en": "Dakaru", "hi": "डाकारु"}, {"key": "B", "en": "Bhasmasura", "hi": "भस्मासुर"}, {"key": "C", "en": "Tripurasura", "hi": "त्रिपुरासुर"}, {"key": "D", "en": "Jalandhara", "hi": "जलंधर"}]','A');
