INSERT INTO knowledge_quiz VALUES(409,'Which divine bow was specially crafted by Vishwakarma for Karna, ensuring his victory as long as he held it?','विश्वकर्मा ने कर्ण के लिए कौन सा दिव्य धनुष विशेष रूप से बनाया था, जो उसके हाथ में रहने तक उसकी जीत सुनिश्चित करता था?','[{"key": "A", "en": "Gandiva", "hi": "गांडीव"}, {"key": "B", "en": "Vijaya", "hi": "विजय"}, {"key": "C", "en": "Sharanga", "hi": "शारंग"}, {"key": "D", "en": "Pinaka", "hi": "पिनाक"}]','B');
