INSERT INTO knowledge_quiz VALUES(426,'Which goddess is worshipped as the presiding deity of devotion?','भक्ति की अधिष्ठात्री देवी कौन हैं?','[{"key": "A", "en": "Radha", "hi": "राधा"}, {"key": "B", "en": "Sita", "hi": "सीता"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(427,'Which emblem was present on Arjuna’s chariot during the Kurukshetra war?','कुरुक्षेत्र युद्ध में अर्जुन के रथ पर किसका ध्वज चिन्ह था?','[{"key": "A", "en": "Garuda", "hi": "गरुड़"}, {"key": "B", "en": "Hanuman", "hi": "हनुमान"}, {"key": "C", "en": "Nandi", "hi": "नंदी"}, {"key": "D", "en": "Lion", "hi": "सिंह"}]','B');
