INSERT INTO knowledge_quiz VALUES(429,'Which goddess is worshipped as the embodiment of sacrifice?','त्याग की प्रतीक देवी कौन हैं?','[{"key": "A", "en": "Sita", "hi": "सीता"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','A');
