INSERT INTO knowledge_quiz VALUES(431,'Which goddess is worshipped as the presiding deity of auspiciousness?','मंगल की अधिष्ठात्री देवी कौन हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','A');
