INSERT INTO knowledge_quiz VALUES(435,'Which forest was burned by Arjuna and Krishna to build the city of Indraprastha?','इंद्रप्रस्थ नगर बसाने के लिए अर्जुन और कृष्ण ने किस वन का दहन किया था?','[{"key": "A", "en": "Dandakaranya", "hi": "दंडकारण्य"}, {"key": "B", "en": "Khandava Vana", "hi": "खांडव वन"}, {"key": "C", "en": "Naimisharanya", "hi": "नैमिषारण्य"}, {"key": "D", "en": "Madhuvana", "hi": "मधुवन"}]','B');
INSERT INTO knowledge_quiz VALUES(436,'Which goddess is worshipped as the presiding deity of knowledge?','ज्ञान की अधिष्ठात्री देवी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','A');
