INSERT INTO knowledge_quiz VALUES(447,'Which river emerged when Lord Shiva released the Ganga from his locks?','भगवान शिव की जटाओं से मुक्त होने पर गंगा किस रूप में पृथ्वी पर प्रवाहित हुई?','[{"key": "A", "en": "Bhagirathi", "hi": "भागीरथी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Narmada", "hi": "नर्मदा"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','A');
