INSERT INTO knowledge_quiz VALUES(469,'Which goddess is worshipped as the embodiment of compassion?','करुणा की प्रतीक देवी कौन हैं?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
