INSERT INTO knowledge_quiz VALUES(471,'Which goddess is worshipped as the presiding deity of speech?','वाणी की अधिष्ठात्री देवी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
