INSERT INTO knowledge_quiz VALUES(474,'Which goddess is worshipped as the embodiment of patience?','धैर्य की प्रतीक देवी कौन हैं?','[{"key": "A", "en": "Sita", "hi": "सीता"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(475,'What was the name of the island where Ved Vyasa was born?','उस द्वीप का नाम क्या था जहाँ वेद व्यास का जन्म हुआ था?','[{"key": "A", "en": "Lanka", "hi": "लंका"}, {"key": "B", "en": "Jambudvipa", "hi": "जम्बूद्वीप"}, {"key": "C", "en": "Kalpi", "hi": "कालपी"}, {"key": "D", "en": "Rameshwaram", "hi": "रामेश्वरम"}]','C');
INSERT INTO knowledge_quiz VALUES(476,'Which goddess is worshipped as the presiding deity of devotion and love?','भक्ति और प्रेम की अधिष्ठात्री देवी कौन हैं?','[{"key": "A", "en": "Radha", "hi": "राधा"}, {"key": "B", "en": "Sita", "hi": "सीता"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(477,'Who was the father of King Bharat, after whom India is named ''Bharatvarsha''?','राजा भरत, जिनके नाम पर भारत का नाम ''भारतवर्ष'' पड़ा, उनके पिता कौन थे?','[{"key": "A", "en": "Dasharatha", "hi": "दशरथ"}, {"key": "B", "en": "Dushyanta", "hi": "दुष्यंत"}, {"key": "C", "en": "Shantanu", "hi": "शांतनु"}, {"key": "D", "en": "Pandu", "hi": "पांडु"}]','B');
