INSERT INTO knowledge_quiz VALUES(525,'Who was the elder sister of Goddess Lakshmi who emerged during the churning and is associated with misfortune?','देवी लक्ष्मी की वह बड़ी बहन कौन थी जो मंथन से निकली और जिन्हें अलक्ष्मी या दुर्भाग्य की देवी माना जाता है?','[{"key": "A", "en": "Jyestha", "hi": "ज्येष्ठा"}, {"key": "B", "en": "Diti", "hi": "दिति"}, {"key": "C", "en": "Surasa", "hi": "सुरसा"}, {"key": "D", "en": "Danu", "hi": "दनु"}]','A');
INSERT INTO knowledge_quiz VALUES(526,'Which goddess is worshipped as the presiding deity of speech?','वाणी की अधिष्ठात्री देवी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(527,'Which god is worshipped as the lord of wind?','वायु के देवता कौन हैं?','[{"key": "A", "en": "Vayu", "hi": "वायु"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','A');
INSERT INTO knowledge_quiz VALUES(528,'Which temple town in Karnataka is known as the ''Dakshina Kashi'' and is dedicated to Lord Shiva (Manjunatha)?','कर्नाटक के किस मंदिर शहर को ''दक्षिण काशी'' के रूप में जाना जाता है और यह भगवान शिव (मंजुनाथ) को समर्पित है?','[{"key": "A", "en": "Dharmasthala", "hi": "धर्मस्थल"}, {"key": "B", "en": "Murudeshwar", "hi": "मुरुदेश्वर"}, {"key": "C", "en": "Kadur", "hi": "कादुर"}, {"key": "D", "en": "Nanjangud", "hi": "नंजनगुड"}]','A');
INSERT INTO knowledge_quiz VALUES(529,'Which goddess is worshipped as the embodiment of patience?','धैर्य की प्रतीक देवी कौन हैं?','[{"key": "A", "en": "Sita", "hi": "सीता"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(530,'Which ultimate goal represents liberation?','मोक्ष का प्रतिनिधित्व कौन सा लक्ष्य करता है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Artha", "hi": "अर्थ"}, {"key": "C", "en": "Kama", "hi": "काम"}, {"key": "D", "en": "Moksha", "hi": "मोक्ष"}]','D');
INSERT INTO knowledge_quiz VALUES(531,'Which goddess is worshipped as the presiding deity of devotion and love?','भक्ति और प्रेम की अधिष्ठात्री देवी कौन हैं?','[{"key": "A", "en": "Radha", "hi": "राधा"}, {"key": "B", "en": "Sita", "hi": "सीता"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(532,'What did the Asuras take from the churning process that the Devas did not want?','मंथन प्रक्रिया के दौरान असुरों ने क्या लिया जिसे देवताओं ने स्वीकार नहीं किया था?','[{"key": "A", "en": "Parijat Tree", "hi": "पारिजात वृक्ष"}, {"key": "B", "en": "Varuni", "hi": "वारुणी"}, {"key": "C", "en": "Airavata Elephant", "hi": "ऐरावत हाथी"}, {"key": "D", "en": "Kaustubha Mani", "hi": "कौस्तुभ मणि"}]','B');
INSERT INTO knowledge_quiz VALUES(533,'Thirunelli Temple, often called ''Kashi of the South'', is located in the Brahmagiri hills of which district?','तिरुनेल्ली मंदिर, जिसे अक्सर ''दक्षिण की काशी'' कहा जाता है, किस जिले की ब्रह्मगिरी पहाड़ियों में स्थित है?','[{"key": "A", "en": "Idukki", "hi": "इडुक्की"}, {"key": "B", "en": "Wayanad", "hi": "वायनाड"}, {"key": "C", "en": "Palakkad", "hi": "पलक्कड़"}, {"key": "D", "en": "Pathanamthitta", "hi": "पतनमतिट्टा"}]','B');
INSERT INTO knowledge_quiz VALUES(534,'Which goddess is worshipped as the embodiment of sacrifice?','त्याग की प्रतीक देवी कौन हैं?','[{"key": "A", "en": "Sita", "hi": "सीता"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','A');
INSERT INTO knowledge_quiz VALUES(535,'Which god is worshipped as the supreme protector?','परम रक्षक कौन माने जाते हैं?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Rama", "hi": "राम"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(536,'Which goddess is worshipped as the presiding deity of auspiciousness?','मंगल की अधिष्ठात्री देवी कौन हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(537,'Which god is worshipped as the lord of medicine?','औषधि के देवता कौन हैं?','[{"key": "A", "en": "Dhanvantari", "hi": "धन्वंतरि"}, {"key": "B", "en": "Agni", "hi": "अग्नि"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Vayu", "hi": "वायु"}]','A');
INSERT INTO knowledge_quiz VALUES(538,'Which sacred place is associated with Goddess Vaishno Devi?','देवी वैष्णो देवी से कौन सा स्थान जुड़ा है?','[{"key": "A", "en": "Katra", "hi": "कटरा"}, {"key": "B", "en": "Amritsar", "hi": "अमृतसर"}, {"key": "C", "en": "Haridwar", "hi": "हरिद्वार"}, {"key": "D", "en": "Shimla", "hi": "शिमला"}]','A');
INSERT INTO knowledge_quiz VALUES(539,'Which goddess is worshipped as the embodiment of faith?','श्रद्धा की प्रतीक देवी कौन हैं?','[{"key": "A", "en": "Radha", "hi": "राधा"}, {"key": "B", "en": "Sita", "hi": "सीता"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(540,'Which ultimate aim is freedom from samsara?','संसार चक्र से मुक्ति का लक्ष्य कौन सा है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Artha", "hi": "अर्थ"}, {"key": "C", "en": "Kama", "hi": "काम"}, {"key": "D", "en": "Moksha", "hi": "मोक्ष"}]','D');
INSERT INTO knowledge_quiz VALUES(541,'Which goddess is worshipped as the presiding deity of sacred rivers?','पवित्र नदियों की अधिष्ठात्री देवी कौन हैं?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(542,'Which of these temples is built on an artificial hillock called ''Kattu Malai''?','इनमें से कौन सा मंदिर ''कट्टू मलै'' नामक एक कृत्रिम पहाड़ी पर बना है?','[{"key": "A", "en": "Swamimalai", "hi": "स्वामीमलै"}, {"key": "B", "en": "Palani", "hi": "पलानी"}, {"key": "C", "en": "Thiruchendur", "hi": "तिरुचेंदूर"}, {"key": "D", "en": "Thiruttani", "hi": "तिरुत्तणी"}]','A');
INSERT INTO knowledge_quiz VALUES(543,'Which sacred lake is associated with Lord Brahma?','भगवान ब्रह्मा से कौन सा सरोवर जुड़ा है?','[{"key": "A", "en": "Pushkar", "hi": "पुष्कर"}, {"key": "B", "en": "Manasarovar", "hi": "मानसरोवर"}, {"key": "C", "en": "Bindu Sarovar", "hi": "बिंदु सरोवर"}, {"key": "D", "en": "Amrit Sarovar", "hi": "अमृत सरोवर"}]','A');
INSERT INTO knowledge_quiz VALUES(544,'Which goddess is worshipped as the embodiment of divine energy?','दिव्य ऊर्जा की प्रतीक देवी कौन हैं?','[{"key": "A", "en": "Shakti", "hi": "शक्ति"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Kali", "hi": "काली"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(545,'Which celestial bird helped transport Mount Mandara to the ocean?','मंदराचल पर्वत को समुद्र तक ले जाने में किस दिव्य पक्षी ने सहायता की थी?','[{"key": "A", "en": "Jatayu", "hi": "जटायु"}, {"key": "B", "en": "Sampati", "hi": "सम्पाती"}, {"key": "C", "en": "Garuda", "hi": "गरुड़"}, {"key": "D", "en": "Hamsa", "hi": "हंस"}]','C');
INSERT INTO knowledge_quiz VALUES(546,'Which goddess is worshipped as the presiding deity of the night?','रात्रि की अधिष्ठात्री देवी कौन हैं?','[{"key": "A", "en": "Ratri", "hi": "रात्रि"}, {"key": "B", "en": "Kali", "hi": "काली"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(547,'Which god is worshipped as the giver of health?','स्वास्थ्य प्रदान करने वाले देवता कौन हैं?','[{"key": "A", "en": "Dhanvantari", "hi": "धन्वंतरि"}, {"key": "B", "en": "Ashwini Kumaras", "hi": "अश्विनी कुमार"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "All of these", "hi": "ये सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(548,'Which temple in Hampi is famous for its ''Stone Chariot'' and musical pillars that emit different notes when tapped?','हम्पी का कौन सा मंदिर अपने ''पत्थर के रथ'' और संगीतमय स्तंभों के लिए प्रसिद्ध है जो थपथपाने पर अलग-अलग स्वर निकालते हैं?','[{"key": "A", "en": "Virupaksha Temple", "hi": "विरुपाक्ष मंदिर"}, {"key": "B", "en": "Vittala Temple", "hi": "विट्ठल मंदिर"}, {"key": "C", "en": "Hazara Rama Temple", "hi": "हजारा राम मंदिर"}, {"key": "D", "en": "Achyutaraya Temple", "hi": "अच्युतराय मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(549,'Which goddess is worshipped as the embodiment of truthfulness?','सत्य की प्रतीक देवी कौन हैं?','[{"key": "A", "en": "Sita", "hi": "सीता"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(550,'Which ultimate goal is union with the Absolute?','परम सत्य से एकत्व कौन सा लक्ष्य है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Artha", "hi": "अर्थ"}, {"key": "C", "en": "Kama", "hi": "काम"}, {"key": "D", "en": "Moksha", "hi": "मोक्ष"}]','D');
INSERT INTO knowledge_quiz VALUES(551,'Who composed the Ramcharitmanas?','रामचरितमानस की रचना किसने की?','[{"key": "A", "en": "Tulsidas", "hi": "तुलसीदास"}, {"key": "B", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "C", "en": "Ved Vyasa", "hi": "वेदव्यास"}, {"key": "D", "en": "Kalidasa", "hi": "कालिदास"}]','A');
INSERT INTO knowledge_quiz VALUES(552,'Which yuga is currently believed to be ongoing?','वर्तमान में कौन सा युग चल रहा है?','[{"key": "A", "en": "Satya Yuga", "hi": "सत्य युग"}, {"key": "B", "en": "Treta Yuga", "hi": "त्रेता युग"}, {"key": "C", "en": "Dvapara Yuga", "hi": "द्वापर युग"}, {"key": "D", "en": "Kali Yuga", "hi": "कलियुग"}]','D');
INSERT INTO knowledge_quiz VALUES(553,'Which river is considered the most sacred in Hinduism?','हिंदू धर्म में सबसे पवित्र नदी कौन सी मानी जाती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','C');
INSERT INTO knowledge_quiz VALUES(554,'Who was the mother of Lord Rama?','भगवान राम की माता कौन थीं?','[{"key": "A", "en": "Kaikeyi", "hi": "कैकेयी"}, {"key": "B", "en": "Sumitra", "hi": "सुमित्रा"}, {"key": "C", "en": "Kausalya", "hi": "कौशल्या"}, {"key": "D", "en": "Mandodari", "hi": "मंदोदरी"}]','C');
INSERT INTO knowledge_quiz VALUES(555,'Which Purana is primarily dedicated to Lord Vishnu?','कौन सा पुराण मुख्य रूप से भगवान विष्णु को समर्पित है?','[{"key": "A", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Markandeya Purana", "hi": "मार्कण्डेय पुराण"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(556,'What is the vehicle of Goddess Saraswati?','देवी सरस्वती का वाहन क्या है?','[{"key": "A", "en": "Lion", "hi": "सिंह"}, {"key": "B", "en": "Peacock", "hi": "मोर"}, {"key": "C", "en": "Swan", "hi": "हंस"}, {"key": "D", "en": "Owl", "hi": "उल्लू"}]','C');
INSERT INTO knowledge_quiz VALUES(557,'Which festival celebrates the victory of Lord Rama over Ravana?','कौन सा पर्व भगवान राम की रावण पर विजय का उत्सव है?','[{"key": "A", "en": "Diwali", "hi": "दीपावली"}, {"key": "B", "en": "Dussehra", "hi": "दशहरा"}, {"key": "C", "en": "Holi", "hi": "होली"}, {"key": "D", "en": "Navratri", "hi": "नवरात्रि"}]','B');
INSERT INTO knowledge_quiz VALUES(558,'Which mantra is known as the Gayatri Mantra?','कौन सा मंत्र गायत्री मंत्र कहलाता है?','[{"key": "A", "en": "Om Namah Shivaya", "hi": "ॐ नमः शिवाय"}, {"key": "B", "en": "Om Namo Narayanaya", "hi": "ॐ नमो नारायणाय"}, {"key": "C", "en": "Om Bhur Bhuvaḥ Swaḥ", "hi": "ॐ भूर्भुवः स्वः"}, {"key": "D", "en": "Om Shanti Shanti Shantiḥ", "hi": "ॐ शान्तिः शान्तिः शान्तिः"}]','C');
INSERT INTO knowledge_quiz VALUES(559,'What was the name of the island where the bird-king Sampati lived?','उस द्वीप का नाम क्या था जहाँ पक्षी-राज सम्पाती रहते थे?','[{"key": "A", "en": "Lanka", "hi": "लंका"}, {"key": "B", "en": "Mahendra Hill", "hi": "महेंद्र पर्वत"}, {"key": "C", "en": "Jambudvipa", "hi": "जम्बूद्वीप"}, {"key": "D", "en": "Bali", "hi": "बाली"}]','B');
INSERT INTO knowledge_quiz VALUES(560,'Which temple in Thanjavur, is famous for its massive interlocking stones and is a UNESCO World Heritage site?','तंजावुर का कौन सा मंदिर अपने विशाल इंटरलॉकिंग पत्थरों के लिए प्रसिद्ध है और यूनेस्को की विश्व धरोहर स्थल है?','[{"key": "A", "en": "Airavatesvara Temple", "hi": "ऐरावतेश्वर मंदिर"}, {"key": "B", "en": "Brihadisvara Temple", "hi": "बृहदेश्वर मंदिर"}, {"key": "C", "en": "Gangaikonda Cholapuram", "hi": "गंगैकोंडा चोलपुरम"}, {"key": "D", "en": "Shore Temple", "hi": "शोर मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(561,'Which weapon is associated with Lord Vishnu?','भगवान विष्णु का प्रमुख अस्त्र कौन सा है?','[{"key": "A", "en": "Trishul", "hi": "त्रिशूल"}, {"key": "B", "en": "Sudarshana Chakra", "hi": "सुदर्शन चक्र"}, {"key": "C", "en": "Vajra", "hi": "वज्र"}, {"key": "D", "en": "Pashupatastra", "hi": "पाशुपतास्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(562,'Who is the goddess of wealth in Hinduism?','हिंदू धर्म में धन की देवी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Kali", "hi": "काली"}]','C');
INSERT INTO knowledge_quiz VALUES(563,'Which day is considered auspicious for Lord Shiva?','भगवान शिव के लिए कौन सा दिन शुभ माना जाता है?','[{"key": "A", "en": "Monday", "hi": "सोमवार"}, {"key": "B", "en": "Tuesday", "hi": "मंगलवार"}, {"key": "C", "en": "Thursday", "hi": "गुरुवार"}, {"key": "D", "en": "Sunday", "hi": "रविवार"}]','A');
INSERT INTO knowledge_quiz VALUES(564,'Who was the father of Bhishma?','भीष्म के पिता कौन थे?','[{"key": "A", "en": "Vichitravirya", "hi": "विचित्रवीर्य"}, {"key": "B", "en": "Shantanu", "hi": "शांतनु"}, {"key": "C", "en": "Parashara", "hi": "पराशर"}, {"key": "D", "en": "Pandu", "hi": "पांडु"}]','B');
INSERT INTO knowledge_quiz VALUES(565,'Which fast is observed for marital happiness?','वैवाहिक सुख के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "B", "en": "Karva Chauth", "hi": "करवा चौथ"}, {"key": "C", "en": "Maha Shivratri", "hi": "महाशिवरात्रि"}, {"key": "D", "en": "Navratri", "hi": "नवरात्रि"}]','B');
INSERT INTO knowledge_quiz VALUES(566,'Which scripture contains the teachings of Krishna to Arjuna?','कृष्ण द्वारा अर्जुन को दिए गए उपदेश किस ग्रंथ में हैं?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Ramayana", "hi": "रामायण"}, {"key": "D", "en": "Vedas", "hi": "वेद"}]','B');
INSERT INTO knowledge_quiz VALUES(567,'How many ''Ratnas'' precious things in total are said to have emerged from Samudra Manthan?','समुद्र मंथन से कुल कितने ''रत्न'' निकलने की बात कही गई है?','[{"key": "A", "en": "9", "hi": "9"}, {"key": "B", "en": "11", "hi": "11"}, {"key": "C", "en": "14", "hi": "14"}, {"key": "D", "en": "21", "hi": "21"}]','C');
INSERT INTO knowledge_quiz VALUES(568,'Which lake was created by the falling of the lotus from Lord Brahma''s hand?','भगवान ब्रह्मा के हाथ से कमल गिरने से किस झील का निर्माण हुआ था?','[{"key": "A", "en": "Manasarovar", "hi": "मानसरोवर"}, {"key": "B", "en": "Pushkar Lake", "hi": "पुष्कर झील"}, {"key": "C", "en": "Bindu Sarovar", "hi": "बिंदु सरोवर"}, {"key": "D", "en": "Pampa Sarovar", "hi": "पंपा सरोवर"}]','B');
INSERT INTO knowledge_quiz VALUES(569,'Which ashram stage comes after Grihastha?','गृहस्थ आश्रम के बाद कौन सा आश्रम आता है?','[{"key": "A", "en": "Brahmacharya", "hi": "ब्रह्मचर्य"}, {"key": "B", "en": "Vanaprastha", "hi": "वानप्रस्थ"}, {"key": "C", "en": "Sannyasa", "hi": "संन्यास"}, {"key": "D", "en": "Tapasya", "hi": "तपस्या"}]','B');
INSERT INTO knowledge_quiz VALUES(570,'Which flower is most commonly offered to Lord Shiva?','भगवान शिव को कौन सा फूल सबसे अधिक अर्पित किया जाता है?','[{"key": "A", "en": "Lotus", "hi": "कमल"}, {"key": "B", "en": "Rose", "hi": "गुलाब"}, {"key": "C", "en": "Bilva", "hi": "बेलपत्र"}, {"key": "D", "en": "Jasmine", "hi": "चमेली"}]','C');
INSERT INTO knowledge_quiz VALUES(571,'Which river flows through Varanasi?','वाराणसी से कौन सी नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','B');
INSERT INTO knowledge_quiz VALUES(572,'Who wrote the Yoga Sutras?','योगसूत्र की रचना किसने की?','[{"key": "A", "en": "Patanjali", "hi": "पतंजलि"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Kapila", "hi": "कपिल"}, {"key": "D", "en": "Yajnavalkya", "hi": "याज्ञवल्क्य"}]','A');
INSERT INTO knowledge_quiz VALUES(573,'The ''Magh Mela'', held annually in Prayagraj, transforms into which massive festival every 12 years?','प्रयागराज में प्रतिवर्ष आयोजित होने वाला ''माघ मेला'' प्रत्येक 12 वर्ष में किस विशाल उत्सव में बदल जाता है?','[{"key": "A", "en": "Ardh Kumbh", "hi": "अर्ध कुंभ"}, {"key": "B", "en": "Maha Kumbh", "hi": "महा कुंभ"}, {"key": "C", "en": "Dev Deepawali", "hi": "देव दीपावली"}, {"key": "D", "en": "Kartik Poornima", "hi": "कार्तिक पूर्णिमा"}]','B');
INSERT INTO knowledge_quiz VALUES(574,'Which temple in Sikar district is dedicated to ''Barbareek'' from the Mahabharata and is visited by millions of devotees?','सीकर जिले का कौन सा मंदिर महाभारत के ''बर्बरीक'' को समर्पित है और यहाँ लाखों भक्त आते हैं?','[{"key": "A", "en": "Salasar Balaji", "hi": "सालासर बालाजी"}, {"key": "B", "en": "Khatu Shyam Ji", "hi": "खाटू श्याम जी"}, {"key": "C", "en": "Jeen Mata", "hi": "जीण माता"}, {"key": "D", "en": "Harshnath Temple", "hi": "हर्षनाथ मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(575,'Which demon king was the father of Prahlada?','प्रह्लाद का पिता कौन सा असुर राजा था?','[{"key": "A", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "B", "en": "Hiranyakashipu", "hi": "हिरण्यकश्यप"}, {"key": "C", "en": "Ravana", "hi": "रावण"}, {"key": "D", "en": "Bali", "hi": "बलि"}]','B');
INSERT INTO knowledge_quiz VALUES(576,'Which temple is one of the twelve Jyotirlingas?','बारह ज्योतिर्लिंगों में से कौन सा मंदिर है?','[{"key": "A", "en": "Somnath", "hi": "सोमनाथ"}, {"key": "B", "en": "Tirupati", "hi": "तिरुपति"}, {"key": "C", "en": "Kamakhya", "hi": "कामाख्या"}, {"key": "D", "en": "Vaishno Devi", "hi": "वैष्णो देवी"}]','A');
INSERT INTO knowledge_quiz VALUES(577,'Which concept means liberation from rebirth?','पुनर्जन्म से मुक्ति को क्या कहते हैं?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Karma", "hi": "कर्म"}, {"key": "C", "en": "Moksha", "hi": "मोक्ष"}, {"key": "D", "en": "Bhakti", "hi": "भक्ति"}]','C');
INSERT INTO knowledge_quiz VALUES(578,'Who was the wife of King Dasharatha?','राजा दशरथ की पत्नी कौन थीं?','[{"key": "A", "en": "Kausalya", "hi": "कौशल्या"}, {"key": "B", "en": "Kaikeyi", "hi": "कैकेयी"}, {"key": "C", "en": "Sumitra", "hi": "सुमित्रा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(579,'The Kavala Caves, located in the Dandeli forest, contain a naturally formed Shiva Linga. In which district are they?','दांदेली के जंगलों में स्थित कवाला गुफाओं में प्राकृतिक रूप से निर्मित शिव लिंग है। ये किस जिले में हैं?','[{"key": "A", "en": "Uttara Kannada", "hi": "उत्तर कन्नड़"}, {"key": "B", "en": "Dakshina Kannada", "hi": "दक्षिण कन्नड़"}, {"key": "C", "en": "Shivamogga", "hi": "शिवामोग्गा"}, {"key": "D", "en": "Udupi", "hi": "उडुपी"}]','A');
