INSERT INTO knowledge_quiz VALUES(581,'Which vrata is observed on Ekadashi?','एकादशी के दिन कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Vishnu Vrat", "hi": "विष्णु व्रत"}, {"key": "B", "en": "Shiva Vrat", "hi": "शिव व्रत"}, {"key": "C", "en": "Surya Vrat", "hi": "सूर्य व्रत"}, {"key": "D", "en": "Chandra Vrat", "hi": "चंद्र व्रत"}]','A');
INSERT INTO knowledge_quiz VALUES(582,'Which epic narrates the life of Lord Rama?','भगवान राम के जीवन का वर्णन किस महाकाव्य में है?','[{"key": "A", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "B", "en": "Ramayana", "hi": "रामायण"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Skanda Purana", "hi": "स्कंद पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(583,'Which God is worshipped in the form of a Lingam?','लिंग रूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','C');
INSERT INTO knowledge_quiz VALUES(584,'Who was the only Kaurava brother to protest against the disrobing of Draupadi in the assembly?','सभा में द्रौपदी के चीरहरण का विरोध करने वाले एकमात्र कौरव भाई कौन थे?','[{"key": "A", "en": "Dushasana", "hi": "दुशासन"}, {"key": "B", "en": "Vikarna", "hi": "विकर्ण"}, {"key": "C", "en": "Chitrasena", "hi": "चित्रसेन"}, {"key": "D", "en": "Sala", "hi": "शल"}]','B');
INSERT INTO knowledge_quiz VALUES(585,'Which sage is associated with Advaita Vedanta?','अद्वैत वेदांत किस आचार्य से संबंधित है?','[{"key": "A", "en": "Ramanuja", "hi": "रामानुज"}, {"key": "B", "en": "Madhva", "hi": "माध्व"}, {"key": "C", "en": "Adi Shankaracharya", "hi": "आदि शंकराचार्य"}, {"key": "D", "en": "Chaitanya", "hi": "चैतन्य"}]','C');
INSERT INTO knowledge_quiz VALUES(586,'Which ritual involves offering food to fire?','अग्नि में आहुति देने की क्रिया को क्या कहते हैं?','[{"key": "A", "en": "Puja", "hi": "पूजा"}, {"key": "B", "en": "Homa", "hi": "होम"}, {"key": "C", "en": "Abhisheka", "hi": "अभिषेक"}, {"key": "D", "en": "Japa", "hi": "जप"}]','B');
