INSERT INTO knowledge_quiz VALUES(589,'Which scripture focuses on devotion to Lord Krishna?','कौन सा ग्रंथ भगवान कृष्ण की भक्ति पर केंद्रित है?','[{"key": "A", "en": "Narada Bhakti Sutra", "hi": "नारद भक्ति सूत्र"}, {"key": "B", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "C", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "D", "en": "Arthashastra", "hi": "अर्थशास्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(590,'Which river is associated with Lord Krishna’s childhood?','भगवान कृष्ण के बाल्यकाल से कौन सी नदी जुड़ी है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','B');
INSERT INTO knowledge_quiz VALUES(591,'Which demon was slain by Lord Rama?','भगवान राम ने किस राक्षस का वध किया?','[{"key": "A", "en": "Kumbhakarna", "hi": "कुंभकर्ण"}, {"key": "B", "en": "Ravana", "hi": "रावण"}, {"key": "C", "en": "Bali", "hi": "बालि"}, {"key": "D", "en": "Meghnad", "hi": "मेघनाद"}]','B');
INSERT INTO knowledge_quiz VALUES(592,'Which concept refers to righteous duty?','धार्मिक कर्तव्य को क्या कहते हैं?','[{"key": "A", "en": "Karma", "hi": "कर्म"}, {"key": "B", "en": "Dharma", "hi": "धर्म"}, {"key": "C", "en": "Maya", "hi": "माया"}, {"key": "D", "en": "Moksha", "hi": "मोक्ष"}]','B');
INSERT INTO knowledge_quiz VALUES(593,'Who was the mother of Lord Krishna?','भगवान कृष्ण की माता कौन थीं?','[{"key": "A", "en": "Yashoda", "hi": "यशोदा"}, {"key": "B", "en": "Devaki", "hi": "देवकी"}, {"key": "C", "en": "Rohini", "hi": "रोहिणी"}, {"key": "D", "en": "Kunti", "hi": "कुंती"}]','B');
