INSERT INTO knowledge_quiz VALUES(597,'Which festival celebrates the worship of Goddess Durga?','देवी दुर्गा की पूजा किस पर्व में होती है?','[{"key": "A", "en": "Diwali", "hi": "दीपावली"}, {"key": "B", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "C", "en": "Holi", "hi": "होली"}, {"key": "D", "en": "Raksha Bandhan", "hi": "रक्षा बंधन"}]','B');
INSERT INTO knowledge_quiz VALUES(598,'Which avatar of Vishnu appeared as a dwarf?','भगवान विष्णु का कौन सा अवतार बौना था?','[{"key": "A", "en": "Vamana", "hi": "वामन"}, {"key": "B", "en": "Kurma", "hi": "कूर्म"}, {"key": "C", "en": "Matsya", "hi": "मत्स्य"}, {"key": "D", "en": "Varaha", "hi": "वराह"}]','A');
INSERT INTO knowledge_quiz VALUES(599,'Which sacred text is also called Vedanta?','वेदांत किस ग्रंथ को कहा जाता है?','[{"key": "A", "en": "Brahmanas", "hi": "ब्राह्मण"}, {"key": "B", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "C", "en": "Aranyakas", "hi": "आरण्यक"}, {"key": "D", "en": "Samhitas", "hi": "संहिता"}]','B');
INSERT INTO knowledge_quiz VALUES(600,'Which deity is worshipped as the Sun God?','सूर्य देव के रूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Surya", "hi": "सूर्य"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','B');
INSERT INTO knowledge_quiz VALUES(601,'Who was the foster mother of Lord Krishna?','भगवान कृष्ण की पालक माता कौन थीं?','[{"key": "A", "en": "Devaki", "hi": "देवकी"}, {"key": "B", "en": "Rohini", "hi": "रोहिणी"}, {"key": "C", "en": "Yashoda", "hi": "यशोदा"}, {"key": "D", "en": "Kunti", "hi": "कुंती"}]','C');
INSERT INTO knowledge_quiz VALUES(602,'Which king performed the Ashwamedha Yajna?','अश्वमेध यज्ञ किस राजा ने किया था?','[{"key": "A", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "B", "en": "Dasharatha", "hi": "दशरथ"}, {"key": "C", "en": "Harishchandra", "hi": "हरिश्चंद्र"}, {"key": "D", "en": "Janamejaya", "hi": "जनमेजय"}]','A');
INSERT INTO knowledge_quiz VALUES(603,'Which demon was killed by Lord Vishnu in Matsya avatar?','मत्स्य अवतार में भगवान विष्णु ने किस असुर का वध किया?','[{"key": "A", "en": "Hayagriva", "hi": "हयग्रीव"}, {"key": "B", "en": "Hiranyaksha", "hi": "हिरण्याक्ष"}, {"key": "C", "en": "Shumbha", "hi": "शुंभ"}, {"key": "D", "en": "Kalanemi", "hi": "कालनेमि"}]','A');
INSERT INTO knowledge_quiz VALUES(604,'Which river is also called the daughter of the Sun?','कौन सी नदी सूर्य की पुत्री कहलाती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','B');
INSERT INTO knowledge_quiz VALUES(605,'Who was the teacher of Karna?','कर्ण के गुरु कौन थे?','[{"key": "A", "en": "Dronacharya", "hi": "द्रोणाचार्य"}, {"key": "B", "en": "Kripacharya", "hi": "कृपाचार्य"}, {"key": "C", "en": "Parashurama", "hi": "परशुराम"}, {"key": "D", "en": "Vyasa", "hi": "व्यास"}]','C');
INSERT INTO knowledge_quiz VALUES(606,'Which temple in Kerala is famous for the ''Parumala Perunnal'' and also has a unique ''Mirrored Idol''?','केरल का कौन सा मंदिर ''परुमाला पेरुन्नल'' के लिए प्रसिद्ध है और इसमें एक अनूठी ''दर्पण वाली मूर्ति'' भी है?','[{"key": "A", "en": "Aranmula Parthasarathy", "hi": "अरनमुला पार्थसारथी"}, {"key": "B", "en": "Ambalappuzha Krishna", "hi": "अम्बलप्पुझा कृष्ण"}, {"key": "C", "en": "Ettumanoor Mahadeva", "hi": "एट्टुमानूर महादेव"}, {"key": "D", "en": "Vaikom Mahadeva", "hi": "वैकोम महादेव"}]','A');
INSERT INTO knowledge_quiz VALUES(607,'Which fast is dedicated to Lord Hanuman?','कौन सा व्रत भगवान हनुमान को समर्पित है?','[{"key": "A", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "B", "en": "Mangalvar Vrat", "hi": "मंगलवार व्रत"}, {"key": "C", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "D", "en": "Shani Vrat", "hi": "शनि व्रत"}]','B');
INSERT INTO knowledge_quiz VALUES(608,'Who narrated the Ramayana?','रामायण की रचना किसने की?','[{"key": "A", "en": "Ved Vyasa", "hi": "वेदव्यास"}, {"key": "B", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "C", "en": "Tulsidas", "hi": "तुलसीदास"}, {"key": "D", "en": "Kalidasa", "hi": "कालिदास"}]','B');
INSERT INTO knowledge_quiz VALUES(609,'Which temple in Gurugram is dedicated to the wife of Guru Dronacharya and is a major pilgrimage site?','गुरुग्राम का कौन सा मंदिर गुरु द्रोणाचार्य की पत्नी को समर्पित है और एक प्रमुख तीर्थ स्थल है?','[{"key": "A", "en": "Sheetla Mata Temple", "hi": "शीतला माता मंदिर"}, {"key": "B", "en": "Eklavya Temple", "hi": "एकलव्य मंदिर"}, {"key": "C", "en": "Bhuteshwar Temple", "hi": "भूतेश्वर मंदिर"}, {"key": "D", "en": "Sthaneshwar Mahadev", "hi": "स्थानेश्वर महादेव"}]','A');
