INSERT INTO knowledge_quiz VALUES(611,'Which scripture is a dialogue between Nachiketa and Yama?','नचिकेता और यम के संवाद वाला उपनिषद कौन सा है?','[{"key": "A", "en": "Isha Upanishad", "hi": "ईश उपनिषद"}, {"key": "B", "en": "Katha Upanishad", "hi": "कठोपनिषद"}, {"key": "C", "en": "Mundaka Upanishad", "hi": "मुंडक उपनिषद"}, {"key": "D", "en": "Aitareya Upanishad", "hi": "ऐतरेय उपनिषद"}]','B');
INSERT INTO knowledge_quiz VALUES(612,'Which part of Lord Sati''s body fell at the Kamakhya temple in Assam?','असम के कामाख्या मंदिर में माता सती के शरीर का कौन सा भाग गिरा था?','[{"key": "A", "en": "Eyes", "hi": "आंखें"}, {"key": "B", "en": "Yoni (Womb)", "hi": "योनि"}, {"key": "C", "en": "Heart", "hi": "हृदय"}, {"key": "D", "en": "Hair", "hi": "बाल"}]','B');
