INSERT INTO knowledge_quiz VALUES(630,'What was the original name of the Mahabharata when it consisted of only 8,800 verses?','महाभारत का मूल नाम क्या था जब इसमें केवल 8,800 श्लोक थे?','[{"key": "A", "en": "Bharata", "hi": "भारत"}, {"key": "B", "en": "Jaya Samhita", "hi": "जय संहिता"}, {"key": "C", "en": "Kurukshetra Gatha", "hi": "कुरुक्षेत्र गाथा"}, {"key": "D", "en": "Itihasa", "hi": "इतिहास"}]','B');
