INSERT INTO knowledge_quiz VALUES(641,'Which demon was killed by Goddess Durga during Navratri?','नवरात्रि में देवी दुर्गा ने किस असुर का वध किया?','[{"key": "A", "en": "Shumbha", "hi": "शुंभ"}, {"key": "B", "en": "Nishumbha", "hi": "निशुंभ"}, {"key": "C", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "D", "en": "Raktabija", "hi": "रक्तबीज"}]','C');
