INSERT INTO knowledge_quiz VALUES(645,'Who was the guru of Lord Rama?','भगवान राम के गुरु कौन थे?','[{"key": "A", "en": "Vashishta", "hi": "वशिष्ठ"}, {"key": "B", "en": "Vishwamitra", "hi": "विश्वामित्र"}, {"key": "C", "en": "Bharadwaja", "hi": "भरद्वाज"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','B');
