INSERT INTO knowledge_quiz VALUES(647,'To whom did Lord Krishna impart the knowledge of the Bhagavad Gita?','भगवान कृष्ण ने भगवद गीता का ज्ञान किसे दिया था?','[{"key": "A", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Bhishma", "hi": "भीष्म"}, {"key": "D", "en": "Karna", "hi": "कर्ण"}]','B');
INSERT INTO knowledge_quiz VALUES(648,'Which goddess is worshipped on Fridays?','शुक्रवार को किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Kali", "hi": "काली"}]','B');
INSERT INTO knowledge_quiz VALUES(649,'Which Pandava had knowledge of astronomy?','पांडवों में ज्योतिष का ज्ञान किसे था?','[{"key": "A", "en": "Nakula", "hi": "नकुल"}, {"key": "B", "en": "Sahadeva", "hi": "सहदेव"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Bhima", "hi": "भीम"}]','B');
INSERT INTO knowledge_quiz VALUES(650,'In which temple is the idol of Lord Krishna said to have been brought from Dwarka by a devotee named Bodana?','किस मंदिर में भगवान कृष्ण की मूर्ति के बारे में कहा जाता है कि उसे बोदाणा नामक भक्त द्वारका से लाए थे?','[{"key": "A", "en": "Shamlaji", "hi": "शामलाजी"}, {"key": "B", "en": "Dakor (Ranchhodraiji)", "hi": "डाकोर (रणछोड़रायजी)"}, {"key": "C", "en": "Bet Dwarka", "hi": "बेट द्वारका"}, {"key": "D", "en": "Bhalka Tirth", "hi": "भालका तीर्थ"}]','B');
INSERT INTO knowledge_quiz VALUES(651,'Which river is known as the king of rivers in Hindu texts?','हिंदू ग्रंथों में किस नदी को नदियों का राजा कहा गया है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','C');
INSERT INTO knowledge_quiz VALUES(652,'Who was the mother of the Pandavas?','पांडवों की माता कौन थीं?','[{"key": "A", "en": "Gandhari", "hi": "गांधारी"}, {"key": "B", "en": "Kunti", "hi": "कुंती"}, {"key": "C", "en": "Madri", "hi": "माद्री"}, {"key": "D", "en": "Both B and C", "hi": "B और C दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(653,'Who is the consort (husband) of Goddess Meenakshi in the Madurai temple?','मदुरै मंदिर में देवी मीनाक्षी के पति कौन हैं?','[{"key": "A", "en": "Lord Ranganatha", "hi": "भगवान रंगनाथ"}, {"key": "B", "en": "Lord Sundareshwar", "hi": "भगवान सुंदरेश्वर"}, {"key": "C", "en": "Lord Venkateswara", "hi": "भगवान वेंकटेश्वर"}, {"key": "D", "en": "Lord Murugan", "hi": "भगवान मुरुगन"}]','B');
INSERT INTO knowledge_quiz VALUES(654,'Which demon was killed by Lord Krishna using Sudarshana Chakra?','भगवान कृष्ण ने सुदर्शन चक्र से किस असुर का वध किया?','[{"key": "A", "en": "Kamsa", "hi": "कंस"}, {"key": "B", "en": "Shishupala", "hi": "शिशुपाल"}, {"key": "C", "en": "Putana", "hi": "पूतना"}, {"key": "D", "en": "Bakasura", "hi": "बकासुर"}]','B');
INSERT INTO knowledge_quiz VALUES(655,'Which scripture explains duties according to varna and ashrama?','वर्ण और आश्रम के अनुसार कर्तव्यों का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "B", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "C", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "D", "en": "Narada Smriti", "hi": "नारद स्मृति"}]','A');
INSERT INTO knowledge_quiz VALUES(656,'Which wife of Arjuna belonged to the Naga kingdom?','अर्जुन की कौन सी पत्नी नागलोक से थीं?','[{"key": "A", "en": "Subhadra", "hi": "सुभद्रा"}, {"key": "B", "en": "Ulupi", "hi": "उलूपी"}, {"key": "C", "en": "Chitrangada", "hi": "चित्रांगदा"}, {"key": "D", "en": "Draupadi", "hi": "द्रौपदी"}]','B');
INSERT INTO knowledge_quiz VALUES(657,'Which vrata is observed for the well-being of brothers?','भाइयों की मंगलकामना के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Raksha Bandhan", "hi": "रक्षा बंधन"}, {"key": "B", "en": "Bhai Dooj", "hi": "भैया दूज"}, {"key": "C", "en": "Karva Chauth", "hi": "करवा चौथ"}, {"key": "D", "en": "Ahoi Ashtami", "hi": "अहोई अष्टमी"}]','B');
INSERT INTO knowledge_quiz VALUES(658,'Which demon was killed by Bhima during exile?','वनवास के समय भीम ने किस असुर का वध किया?','[{"key": "A", "en": "Bakasura", "hi": "बकासुर"}, {"key": "B", "en": "Kichaka", "hi": "कीचक"}, {"key": "C", "en": "Hidimba", "hi": "हिडिंब"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(659,'Which Upanishad declares ''Tat Tvam Asi''?','''तत् त्वम् असि'' महावाक्य किस उपनिषद में है?','[{"key": "A", "en": "Chandogya Upanishad", "hi": "छांदोग्य उपनिषद"}, {"key": "B", "en": "Brihadaranyaka Upanishad", "hi": "बृहदारण्यक उपनिषद"}, {"key": "C", "en": "Kena Upanishad", "hi": "केन उपनिषद"}, {"key": "D", "en": "Isha Upanishad", "hi": "ईश उपनिषद"}]','A');
INSERT INTO knowledge_quiz VALUES(660,'Which mountain is associated with the Samudra Manthan?','समुद्र मंथन में कौन सा पर्वत प्रयुक्त हुआ?','[{"key": "A", "en": "Govardhan", "hi": "गोवर्धन"}, {"key": "B", "en": "Mandara", "hi": "मंदराचल"}, {"key": "C", "en": "Meru", "hi": "मेरु"}, {"key": "D", "en": "Kailash", "hi": "कैलाश"}]','B');
INSERT INTO knowledge_quiz VALUES(661,'Which deity is worshipped as the family deity (Kuladevata)?','कुलदेवता किसे कहा जाता है?','[{"key": "A", "en": "Village deity", "hi": "ग्राम देवता"}, {"key": "B", "en": "Clan deity", "hi": "वंश देवता"}, {"key": "C", "en": "Temple deity", "hi": "मंदिर देवता"}, {"key": "D", "en": "Universal deity", "hi": "सार्वभौमिक देवता"}]','B');
INSERT INTO knowledge_quiz VALUES(662,'Which Pandava ruled the kingdom of Indraprastha?','इंद्रप्रस्थ के राजा कौन थे?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "D", "en": "Nakula", "hi": "नकुल"}]','C');
INSERT INTO knowledge_quiz VALUES(663,'Which goddess is associated with learning and arts?','विद्या और कला की देवी कौन हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','C');
INSERT INTO knowledge_quiz VALUES(664,'Which ritual is performed after birth naming?','जन्म के बाद नामकरण के पश्चात कौन सा संस्कार होता है?','[{"key": "A", "en": "Annaprashana", "hi": "अन्नप्राशन"}, {"key": "B", "en": "Chudakarana", "hi": "चूड़ाकरण"}, {"key": "C", "en": "Upanayana", "hi": "उपनयन"}, {"key": "D", "en": "Jatakarma", "hi": "जातकर्म"}]','A');
INSERT INTO knowledge_quiz VALUES(665,'Which sage cursed King Yayati?','राजा ययाति को किस ऋषि ने श्राप दिया?','[{"key": "A", "en": "Shukracharya", "hi": "शुक्राचार्य"}, {"key": "B", "en": "Brihaspati", "hi": "बृहस्पति"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Durvasa", "hi": "दुर्वासा"}]','A');
INSERT INTO knowledge_quiz VALUES(666,'Which vow is observed for Lord Shiva during Shravan?','श्रावण मास में भगवान शिव के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "B", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "C", "en": "Pradosh Vrat", "hi": "प्रदोष व्रत"}, {"key": "D", "en": "Shani Vrat", "hi": "शनि व्रत"}]','A');
INSERT INTO knowledge_quiz VALUES(667,'At the Kalighat Temple in Kolkata, which part of Sati''s body is believed to have fallen?','कोलकाता के कालीघाट मंदिर में सती के शरीर का कौन सा भाग गिरा माना जाता है?','[{"key": "A", "en": "Right Foot Toes", "hi": "दाएं पैर की उंगलियां"}, {"key": "B", "en": "Left Shoulder", "hi": "बायां कंधा"}, {"key": "C", "en": "Skull", "hi": "कपाल"}, {"key": "D", "en": "Ankle", "hi": "टखना"}]','A');
INSERT INTO knowledge_quiz VALUES(668,'Which scripture is a conversation between Rama and Hanuman?','राम और हनुमान के संवाद वाला ग्रंथ कौन सा है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Adhyatma Ramayana", "hi": "अध्यात्म रामायण"}, {"key": "C", "en": "Hanuman Chalisa", "hi": "हनुमान चालीसा"}, {"key": "D", "en": "Rama Gita", "hi": "राम गीता"}]','D');
INSERT INTO knowledge_quiz VALUES(669,'Which deity is worshipped during Ganesh Chaturthi?','गणेश चतुर्थी पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Kartikey", "hi": "कार्तिकेय"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','B');
INSERT INTO knowledge_quiz VALUES(670,'Which Pandava had expertise in cattle management?','पांडवों में पशुपालन का विशेषज्ञ कौन था?','[{"key": "A", "en": "Nakula", "hi": "नकुल"}, {"key": "B", "en": "Sahadeva", "hi": "सहदेव"}, {"key": "C", "en": "Bhima", "hi": "भीम"}, {"key": "D", "en": "Arjuna", "hi": "अर्जुन"}]','A');
INSERT INTO knowledge_quiz VALUES(671,'Which mantra is chanted for universal peace?','विश्व शांति के लिए कौन सा मंत्र जपा जाता है?','[{"key": "A", "en": "Gayatri Mantra", "hi": "गायत्री मंत्र"}, {"key": "B", "en": "Shanti Mantra", "hi": "शांति मंत्र"}, {"key": "C", "en": "Mahamrityunjaya Mantra", "hi": "महामृत्युंजय मंत्र"}, {"key": "D", "en": "Narayan Mantra", "hi": "नारायण मंत्र"}]','B');
INSERT INTO knowledge_quiz VALUES(672,'The Chennakesava Temple, a masterpiece of Hoysala architecture, is located in which town?','होयसल वास्तुकला की उत्कृष्ट कृति, चेनकेशव मंदिर किस शहर में स्थित है?','[{"key": "A", "en": "Halebidu", "hi": "हलेबिडु"}, {"key": "B", "en": "Belur", "hi": "बेलूर"}, {"key": "C", "en": "Sringeri", "hi": "शृंगेरी"}, {"key": "D", "en": "Mysuru", "hi": "मैसूरु"}]','B');
INSERT INTO knowledge_quiz VALUES(673,'Which Saptarishi is credited with being the chief author of the Rigveda''s seventh Mandala?','किस सप्तर्षि को ऋग्वेद के सातवें मंडल का मुख्य रचयिता माना जाता है?','[{"key": "A", "en": "Sage Vishwamitra", "hi": "ऋषि विश्वामित्र"}, {"key": "B", "en": "Sage Vashistha", "hi": "ऋषि वशिष्ठ"}, {"key": "C", "en": "Sage Bharadwaja", "hi": "ऋषि भरद्वाज"}, {"key": "D", "en": "Sage Kashyapa", "hi": "ऋषि कश्यप"}]','B');
INSERT INTO knowledge_quiz VALUES(674,'Which demon was killed by Lord Rama in Kishkindha?','किष्किंधा में भगवान राम ने किसका वध किया?','[{"key": "A", "en": "Vali", "hi": "बालि"}, {"key": "B", "en": "Sugriva", "hi": "सुग्रीव"}, {"key": "C", "en": "Kabandha", "hi": "कबंध"}, {"key": "D", "en": "Maricha", "hi": "मारीच"}]','A');
INSERT INTO knowledge_quiz VALUES(675,'Which goddess is worshipped as Shakti?','शक्ति रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','A');
INSERT INTO knowledge_quiz VALUES(676,'Who cursed Arjuna to become a eunuch for one year?','किसने अर्जुन को एक वर्ष के लिए नपुंसक बनने का श्राप दिया था?','[{"key": "A", "en": "Urvashi", "hi": "उर्वशी"}, {"key": "B", "en": "Durvasa", "hi": "दुर्वासा"}, {"key": "C", "en": "Menaka", "hi": "मेनका"}, {"key": "D", "en": "Rambha", "hi": "रंभा"}]','A');
INSERT INTO knowledge_quiz VALUES(677,'Which river is associated with Prayagraj?','प्रयागराज से कौन सी नदी जुड़ी है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(678,'Which vow is observed for Goddess Santoshi?','संतोषी माता के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Friday Vrat", "hi": "शुक्रवार व्रत"}, {"key": "B", "en": "Tuesday Vrat", "hi": "मंगलवार व्रत"}, {"key": "C", "en": "Thursday Vrat", "hi": "गुरुवार व्रत"}, {"key": "D", "en": "Ekadashi", "hi": "एकादशी"}]','A');
INSERT INTO knowledge_quiz VALUES(679,'Which Pandava was skilled in swordsmanship?','तलवार विद्या में कौन सा पांडव निपुण था?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Nakula", "hi": "नकुल"}, {"key": "D", "en": "Sahadeva", "hi": "सहदेव"}]','C');
INSERT INTO knowledge_quiz VALUES(680,'Which sacred text emphasizes devotion (Bhakti)?','भक्ति पर विशेष बल देने वाला ग्रंथ कौन सा है?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "C", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "D", "en": "Nyaya Sutra", "hi": "न्याय सूत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(681,'Which sage is known for extreme anger?','अत्यधिक क्रोध के लिए कौन से ऋषि प्रसिद्ध हैं?','[{"key": "A", "en": "Vashishta", "hi": "वशिष्ठ"}, {"key": "B", "en": "Narada", "hi": "नारद"}, {"key": "C", "en": "Durvasa", "hi": "दुर्वासा"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','C');
INSERT INTO knowledge_quiz VALUES(682,'Which festival marks the birth of Lord Rama?','भगवान राम का जन्मोत्सव कौन सा है?','[{"key": "A", "en": "Janmashtami", "hi": "जन्माष्टमी"}, {"key": "B", "en": "Ram Navami", "hi": "राम नवमी"}, {"key": "C", "en": "Dussehra", "hi": "दशहरा"}, {"key": "D", "en": "Diwali", "hi": "दीपावली"}]','B');
INSERT INTO knowledge_quiz VALUES(683,'Which deity holds the mace (Gada)?','गदा किस देवता का अस्त्र है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Hanuman", "hi": "हनुमान"}, {"key": "C", "en": "Balarama", "hi": "बलराम"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(684,'Which river is known as Dakshin Ganga?','दक्षिण गंगा किस नदी को कहा जाता है?','[{"key": "A", "en": "Krishna", "hi": "कृष्णा"}, {"key": "B", "en": "Kaveri", "hi": "कावेरी"}, {"key": "C", "en": "Godavari", "hi": "गोदावरी"}, {"key": "D", "en": "Tungabhadra", "hi": "तुंगभद्रा"}]','C');
INSERT INTO knowledge_quiz VALUES(685,'Which avatar of Vishnu taught the demons?','किस अवतार ने असुरों को उपदेश दिया?','[{"key": "A", "en": "Buddha", "hi": "बुद्ध"}, {"key": "B", "en": "Vamana", "hi": "वामन"}, {"key": "C", "en": "Kurma", "hi": "कूर्म"}, {"key": "D", "en": "Matsya", "hi": "मत्स्य"}]','A');
INSERT INTO knowledge_quiz VALUES(686,'Which vow is observed on Amavasya?','अमावस्या के दिन कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "B", "en": "Pitru Tarpan", "hi": "पितृ तर्पण"}, {"key": "C", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "D", "en": "Navratri", "hi": "नवरात्रि"}]','B');
INSERT INTO knowledge_quiz VALUES(687,'Which deity is worshipped in Dwarka?','द्वारका में किस देवता की पूजा होती है?','[{"key": "A", "en": "Rama", "hi": "राम"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','B');
INSERT INTO knowledge_quiz VALUES(688,'Which Pandava was youngest?','पांडवों में सबसे छोटा कौन था?','[{"key": "A", "en": "Nakula", "hi": "नकुल"}, {"key": "B", "en": "Sahadeva", "hi": "सहदेव"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Bhima", "hi": "भीम"}]','B');
