INSERT INTO knowledge_quiz VALUES(730,'Which vow is observed on Thursdays?','गुरुवार को कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Guru Vrat", "hi": "गुरु व्रत"}, {"key": "B", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "C", "en": "Shani Vrat", "hi": "शनि व्रत"}, {"key": "D", "en": "Mangal Vrat", "hi": "मंगल व्रत"}]','A');
