INSERT INTO knowledge_quiz VALUES(732,'Which Pandava was associated with horse management?','घोड़ा पालन में कौन सा पांडव निपुण था?','[{"key": "A", "en": "Nakula", "hi": "नकुल"}, {"key": "B", "en": "Sahadeva", "hi": "सहदेव"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Bhima", "hi": "भीम"}]','A');
INSERT INTO knowledge_quiz VALUES(733,'Which deity is worshipped in Tirupati?','तिरुपति में किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Venkateswara", "hi": "वेंकटेश्वर"}, {"key": "C", "en": "Rama", "hi": "राम"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','B');
INSERT INTO knowledge_quiz VALUES(734,'Which scripture contains the Vishnu Sahasranama?','विष्णु सहस्रनाम किस ग्रंथ में है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(735,'Which river is known as the daughter of Brahma?','ब्रह्मा की पुत्री किस नदी को कहा जाता है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Yamuna", "hi": "यमुना"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','B');
INSERT INTO knowledge_quiz VALUES(736,'Which demon was killed by Goddess Durga as Mahishasuramardini?','महिषासुरमर्दिनी रूप में देवी दुर्गा ने किसका वध किया?','[{"key": "A", "en": "Shumbha", "hi": "शुंभ"}, {"key": "B", "en": "Nishumbha", "hi": "निशुंभ"}, {"key": "C", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "D", "en": "Raktabija", "hi": "रक्तबीज"}]','C');
INSERT INTO knowledge_quiz VALUES(737,'The Alagar Koyil temple is situated at the foot of which hills near Madurai?','अझगर कोविल मंदिर मदुरै के पास किन पहाड़ियों की तलहटी में स्थित है?','[{"key": "A", "en": "Nilgiri Hills", "hi": "नीलगिरी पहाड़ियाँ"}, {"key": "B", "en": "Alagar Hills (Solaimalai)", "hi": "अझगर पहाड़ियाँ (सोलाईमलाई)"}, {"key": "C", "en": "Palani Hills", "hi": "पलानी पहाड़ियाँ"}, {"key": "D", "en": "Cardamom Hills", "hi": "इलायची पहाड़ियाँ"}]','B');
INSERT INTO knowledge_quiz VALUES(738,'Which character is considered an ''Amsha'' (partial incarnation) of Lord Dharma?','किस पात्र को भगवान धर्म का ''अंश'' (आंशिक अवतार) माना जाता है?','[{"key": "A", "en": "Yudhisthira", "hi": "युधिष्ठिर"}, {"key": "B", "en": "Vidura", "hi": "विदुर"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Bhishma", "hi": "भीष्म"}]','C');
INSERT INTO knowledge_quiz VALUES(739,'Which festival celebrates the victory of good over evil?','अच्छाई की बुराई पर विजय का प्रतीक कौन सा पर्व है?','[{"key": "A", "en": "Dussehra", "hi": "दशहरा"}, {"key": "B", "en": "Diwali", "hi": "दीपावली"}, {"key": "C", "en": "Holi", "hi": "होली"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(740,'Which sacred sound is used at the end of prayers?','प्रार्थना के अंत में कौन सा पवित्र शब्द बोला जाता है?','[{"key": "A", "en": "Om", "hi": "ॐ"}, {"key": "B", "en": "Shanti", "hi": "शांति"}, {"key": "C", "en": "Swaha", "hi": "स्वाहा"}, {"key": "D", "en": "Namah", "hi": "नमः"}]','B');
INSERT INTO knowledge_quiz VALUES(741,'Which deity is worshipped as the giver of knowledge?','ज्ञान प्रदान करने वाले देवता कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','A');
INSERT INTO knowledge_quiz VALUES(742,'Which ritual object used during Aarti represents the ''Vayu'' element?','आरती के दौरान उपयोग की जाने वाली कौन सी वस्तु ''वायु'' तत्व का प्रतिनिधित्व करती है?','[{"key": "A", "en": "Incense sticks (Agarbatti)", "hi": "अगरबत्ती"}, {"key": "B", "en": "Chamar (Whisk) or Fan", "hi": "चँवर या पंखा"}, {"key": "C", "en": "Flowers", "hi": "फूल"}, {"key": "D", "en": "Oil Lamp", "hi": "दीपक"}]','B');
INSERT INTO knowledge_quiz VALUES(743,'Which scripture focuses on yoga philosophy?','योग दर्शन पर केंद्रित ग्रंथ कौन सा है?','[{"key": "A", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "B", "en": "Nyaya Sutra", "hi": "न्याय सूत्र"}, {"key": "C", "en": "Brahma Sutra", "hi": "ब्रह्मसूत्र"}, {"key": "D", "en": "Mimamsa Sutra", "hi": "मीमांसा सूत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(744,'Which vow is observed for Lord Vishnu?','भगवान विष्णु के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "B", "en": "Pradosh", "hi": "प्रदोष"}, {"key": "C", "en": "Somvar", "hi": "सोमवार"}, {"key": "D", "en": "Shani", "hi": "शनि"}]','A');
INSERT INTO knowledge_quiz VALUES(745,'Which demon was killed by Lord Krishna at Vrindavan?','वृंदावन में भगवान कृष्ण ने किसका वध किया?','[{"key": "A", "en": "Kaliya", "hi": "कालिया"}, {"key": "B", "en": "Aghasura", "hi": "अघासुर"}, {"key": "C", "en": "Bakāsura", "hi": "बकासुर"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(746,'The Shore Temple, one of the oldest structural stone temples in South India, is located in which UNESCO site?','दक्षिण भारत के सबसे पुराने संरचनात्मक पत्थर के मंदिरों में से एक, शोर मंदिर किस यूनेस्को स्थल में स्थित है?','[{"key": "A", "en": "Mamallapuram (Mahabalipuram)", "hi": "ममल्लापुरम (महाबलीपुरम)"}, {"key": "B", "en": "Poompuhar", "hi": "पुम्पूहार"}, {"key": "C", "en": "Dhanushkodi", "hi": "धनुषकोडी"}, {"key": "D", "en": "Vedaranyam", "hi": "वेदारण्यम"}]','A');
INSERT INTO knowledge_quiz VALUES(747,'Which goddess is worshipped as Annapurna?','अन्नपूर्णा रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(748,'Which river is called the lifeline of Bihar?','बिहार की जीवनरेखा किस नदी को कहा जाता है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Kosi", "hi": "कोसी"}, {"key": "C", "en": "Son", "hi": "सोन"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','A');
INSERT INTO knowledge_quiz VALUES(749,'According to the Mahabharata, what is the exact ratio of Chariots, Elephants, Cavalry, and Infantry in one Akshauhini?','महाभारत के अनुसार, एक अक्षौहिणी सेना में रथ, हाथी, घुड़सवार और पैदल सैनिकों का सटीक अनुपात क्या है?','[{"key": "A", "en": "1:1:3:5", "hi": "1:1:3:5"}, {"key": "B", "en": "1:2:3:4", "hi": "1:2:3:4"}, {"key": "C", "en": "1:3:5:7", "hi": "1:3:5:7"}, {"key": "D", "en": "1:5:10:20", "hi": "1:5:10:20"}]','A');
INSERT INTO knowledge_quiz VALUES(750,'Which sacred text emphasizes devotion and surrender?','भक्ति और शरणागति पर बल देने वाला ग्रंथ कौन सा है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "C", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "D", "en": "Nyaya Sutra", "hi": "न्याय सूत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(751,'Which deity is known as the lord of justice?','न्याय के देवता कौन माने जाते हैं?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Yama", "hi": "यम"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(752,'Which river is also called Bhagirathi?','कौन सी नदी को भागीरथी भी कहा जाता है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Alaknanda", "hi": "अलकनंदा"}]','B');
INSERT INTO knowledge_quiz VALUES(753,'Which vow is observed on full moon day?','पूर्णिमा के दिन कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "B", "en": "Purnima Vrat", "hi": "पूर्णिमा व्रत"}, {"key": "C", "en": "Amavasya Vrat", "hi": "अमावस्या व्रत"}, {"key": "D", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}]','B');
