INSERT INTO knowledge_quiz VALUES(755,'Which scripture contains stories of Lord Vishnu’s avatars?','भगवान विष्णु के अवतारों की कथाएँ किस ग्रंथ में हैं?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "C", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "D", "en": "Nyaya Sutra", "hi": "न्याय सूत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(756,'Which festival is dedicated to Goddess Lakshmi?','कौन सा पर्व देवी लक्ष्मी को समर्पित है?','[{"key": "A", "en": "Diwali", "hi": "दीपावली"}, {"key": "B", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "C", "en": "Holi", "hi": "होली"}, {"key": "D", "en": "Janmashtami", "hi": "जन्माष्टमी"}]','A');
