INSERT INTO knowledge_quiz VALUES(761,'Which sacred text explains duties of a king?','राजा के कर्तव्यों का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Brahma Sutra", "hi": "ब्रह्मसूत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(762,'Which goddess is worshipped as the power of speech?','वाणी की शक्ति के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Kali", "hi": "काली"}]','B');
INSERT INTO knowledge_quiz VALUES(763,'The ''Patalpuri Temple'' is an underground temple located inside which historical structure in Prayagraj?','''पातालपुरी मंदिर'' प्रयागराज की किस ऐतिहासिक संरचना के अंदर स्थित एक भूमिगत मंदिर है?','[{"key": "A", "en": "Anand Bhavan", "hi": "आनंद भवन"}, {"key": "B", "en": "Prayagraj Fort", "hi": "प्रयागराज का किला"}, {"key": "C", "en": "Khusro Bagh", "hi": "खुसरो बाग"}, {"key": "D", "en": "Swaraj Bhavan", "hi": "स्वराज भवन"}]','B');
INSERT INTO knowledge_quiz VALUES(764,'Which demon was killed by Goddess Kali?','देवी काली ने किस असुर का वध किया?','[{"key": "A", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "B", "en": "Raktabija", "hi": "रक्तबीज"}, {"key": "C", "en": "Shumbha", "hi": "शुंभ"}, {"key": "D", "en": "Nishumbha", "hi": "निशुंभ"}]','B');
INSERT INTO knowledge_quiz VALUES(765,'Which sacred lake is associated with Brahma?','ब्रह्मा से जुड़ा पवित्र सरोवर कौन सा है?','[{"key": "A", "en": "Pushkar Lake", "hi": "पुष्कर सरोवर"}, {"key": "B", "en": "Manasarovar", "hi": "मानसरोवर"}, {"key": "C", "en": "Bindu Sarovar", "hi": "बिंदु सरोवर"}, {"key": "D", "en": "Amrit Sarovar", "hi": "अमृत सरोवर"}]','A');
INSERT INTO knowledge_quiz VALUES(766,'Which deity is worshipped during Skanda Shashti?','स्कंद षष्ठी में किस देवता की पूजा होती है?','[{"key": "A", "en": "Ganesha", "hi": "गणेश"}, {"key": "B", "en": "Kartikey", "hi": "कार्तिकेय"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','B');
