INSERT INTO knowledge_quiz VALUES(768,'Which river flows near Chitrakoot?','चित्रकूट के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Mandakini", "hi": "मंदाकिनी"}, {"key": "B", "en": "Sarayu", "hi": "सरयू"}, {"key": "C", "en": "Yamuna", "hi": "यमुना"}, {"key": "D", "en": "Betwa", "hi": "बेतवा"}]','A');
INSERT INTO knowledge_quiz VALUES(769,'Which goddess is worshipped for fertility?','उर्वरता के लिए किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Shashthi Devi", "hi": "षष्ठी देवी"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','C');
INSERT INTO knowledge_quiz VALUES(770,'Which Pandava was skilled in medicine?','चिकित्सा विद्या में कौन सा पांडव निपुण था?','[{"key": "A", "en": "Nakula", "hi": "नकुल"}, {"key": "B", "en": "Sahadeva", "hi": "सहदेव"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Bhima", "hi": "भीम"}]','A');
INSERT INTO knowledge_quiz VALUES(771,'Which mantra is chanted before meals?','भोजन से पहले कौन सा मंत्र बोला जाता है?','[{"key": "A", "en": "Brahmarpanam Mantra", "hi": "ब्रह्मार्पणं मंत्र"}, {"key": "B", "en": "Gayatri Mantra", "hi": "गायत्री मंत्र"}, {"key": "C", "en": "Shanti Mantra", "hi": "शांति मंत्र"}, {"key": "D", "en": "Mahamrityunjaya Mantra", "hi": "महामृत्युंजय मंत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(772,'Which deity is worshipped in Amarnath?','अमरनाथ में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','B');
INSERT INTO knowledge_quiz VALUES(773,'Which river is associated with Haridwar Kumbh?','हरिद्वार कुंभ किस नदी से जुड़ा है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','B');
INSERT INTO knowledge_quiz VALUES(774,'Which scripture deals with logic and reasoning?','तर्क और न्याय से संबंधित ग्रंथ कौन सा है?','[{"key": "A", "en": "Nyaya Sutra", "hi": "न्याय सूत्र"}, {"key": "B", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "C", "en": "Brahma Sutra", "hi": "ब्रह्मसूत्र"}, {"key": "D", "en": "Mimamsa Sutra", "hi": "मीमांसा सूत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(775,'Which goddess is worshipped as the remover of poverty?','दरिद्रता नाश के लिए किस देवी की पूजा होती है?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Kali", "hi": "काली"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(776,'Which festival is associated with Lord Jagannath’s chariot?','भगवान जगन्नाथ की रथ यात्रा किस पर्व से जुड़ी है?','[{"key": "A", "en": "Ratha Yatra", "hi": "रथ यात्रा"}, {"key": "B", "en": "Snana Yatra", "hi": "स्नान यात्रा"}, {"key": "C", "en": "Dol Yatra", "hi": "डोल यात्रा"}, {"key": "D", "en": "Chandan Yatra", "hi": "चंदन यात्रा"}]','A');
INSERT INTO knowledge_quiz VALUES(777,'Which sacred mountain is associated with Lord Murugan?','भगवान मुरुगन से कौन सा पर्वत जुड़ा है?','[{"key": "A", "en": "Palani", "hi": "पलनी"}, {"key": "B", "en": "Arunachala", "hi": "अरुणाचल"}, {"key": "C", "en": "Kailash", "hi": "कैलाश"}, {"key": "D", "en": "Govardhan", "hi": "गोवर्धन"}]','A');
INSERT INTO knowledge_quiz VALUES(778,'Which vow is observed for ancestors during Pitru Paksha?','पितृ पक्ष में पूर्वजों के लिए कौन सा कर्म किया जाता है?','[{"key": "A", "en": "Shraddha", "hi": "श्राद्ध"}, {"key": "B", "en": "Homa", "hi": "होम"}, {"key": "C", "en": "Japa", "hi": "जप"}, {"key": "D", "en": "Abhisheka", "hi": "अभिषेक"}]','A');
INSERT INTO knowledge_quiz VALUES(779,'Which goddess''s Chalisa is often recited to gain eloquence, wisdom, and success in creative fields?','वाक्पटुता, बुद्धिमत्ता और रचनात्मक क्षेत्रों में सफलता पाने के लिए किस देवी की चालीसा का पाठ किया जाता है?','[{"key": "A", "en": "Durga Chalisa", "hi": "दुर्गा चालीसा"}, {"key": "B", "en": "Saraswati Chalisa", "hi": "सरस्वती चालीसा"}, {"key": "C", "en": "Laxmi Chalisa", "hi": "लक्ष्मी चालीसा"}, {"key": "D", "en": "Gayatri Chalisa", "hi": "गायत्री चालीसा"}]','B');
INSERT INTO knowledge_quiz VALUES(780,'Which deity is worshipped as the god of fire?','अग्नि देव के रूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Surya", "hi": "सूर्य"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','A');
INSERT INTO knowledge_quiz VALUES(781,'Which river is associated with Pandharpur?','पंढरपुर किस नदी से जुड़ा है?','[{"key": "A", "en": "Krishna", "hi": "कृष्णा"}, {"key": "B", "en": "Bhima", "hi": "भीमा"}, {"key": "C", "en": "Godavari", "hi": "गोदावरी"}, {"key": "D", "en": "Tungabhadra", "hi": "तुंगभद्रा"}]','B');
INSERT INTO knowledge_quiz VALUES(782,'Which sacred text is attributed to Sage Patanjali?','किस ग्रंथ की रचना पतंजलि ने की?','[{"key": "A", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "B", "en": "Nyaya Sutra", "hi": "न्याय सूत्र"}, {"key": "C", "en": "Brahma Sutra", "hi": "ब्रह्मसूत्र"}, {"key": "D", "en": "Mimamsa Sutra", "hi": "मीमांसा सूत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(783,'Which goddess is worshipped for marital harmony?','वैवाहिक सुख के लिए किस देवी की पूजा होती है?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Kali", "hi": "काली"}]','A');
INSERT INTO knowledge_quiz VALUES(784,'Which deity is worshipped during Ganga Dussehra?','गंगा दशहरा में किसकी पूजा होती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','A');
INSERT INTO knowledge_quiz VALUES(785,'Which river flows near Kurukshetra?','कुरुक्षेत्र के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Ghaggar", "hi": "घग्गर"}, {"key": "D", "en": "Markanda", "hi": "मारकंडा"}]','A');
INSERT INTO knowledge_quiz VALUES(786,'Which vow is observed for Lord Shani?','भगवान शनि के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Shani Vrat", "hi": "शनि व्रत"}, {"key": "B", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "C", "en": "Guru Vrat", "hi": "गुरु व्रत"}, {"key": "D", "en": "Mangal Vrat", "hi": "मंगल व्रत"}]','A');
INSERT INTO knowledge_quiz VALUES(787,'Which demon was killed by Lord Indra?','इंद्र देव ने किस असुर का वध किया?','[{"key": "A", "en": "Vritra", "hi": "वृत्र"}, {"key": "B", "en": "Ravana", "hi": "रावण"}, {"key": "C", "en": "Bali", "hi": "बलि"}, {"key": "D", "en": "Shumbha", "hi": "शुंभ"}]','A');
INSERT INTO knowledge_quiz VALUES(788,'Who is the brother of Goddess Yamuna, who is also known as the God of Death?','देवी यमुना के भाई कौन हैं, जिन्हें मृत्यु का देवता भी कहा जाता है?','[{"key": "A", "en": "Lord Shani", "hi": "भगवान शनि"}, {"key": "B", "en": "Lord Yama", "hi": "भगवान यम"}, {"key": "C", "en": "Lord Varuna", "hi": "भगवान वरुण"}, {"key": "D", "en": "Both A and B", "hi": "A और B दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(789,'The Birla Mandir in Hyderabad is unique as it was constructed entirely out of which material without any traditional bells?','हैदराबाद का बिड़ला मंदिर अद्वितीय है क्योंकि इसे बिना किसी पारंपरिक घंटी के पूरी तरह से किस सामग्री से बनाया गया था?','[{"key": "A", "en": "Sandstone", "hi": "बलुआ पत्थर"}, {"key": "B", "en": "White Marble", "hi": "सफेद संगमरमर"}, {"key": "C", "en": "Red Granite", "hi": "लाल ग्रेनाइट"}, {"key": "D", "en": "Soapstone", "hi": "सोपस्टोन"}]','B');
INSERT INTO knowledge_quiz VALUES(790,'Which sacred text teaches non-attachment?','अनासक्ति का उपदेश किस ग्रंथ में मिलता है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "C", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "D", "en": "Puranas", "hi": "पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(791,'Which deity is worshipped in Ujjain Mahakaleshwar?','उज्जैन महाकालेश्वर में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','B');
INSERT INTO knowledge_quiz VALUES(792,'Which river is associated with Nasik Kumbh?','नासिक कुंभ किस नदी से जुड़ा है?','[{"key": "A", "en": "Godavari", "hi": "गोदावरी"}, {"key": "B", "en": "Krishna", "hi": "कृष्णा"}, {"key": "C", "en": "Bhima", "hi": "भीमा"}, {"key": "D", "en": "Tapi", "hi": "तापी"}]','A');
INSERT INTO knowledge_quiz VALUES(793,'Which goddess is worshipped as the mother of the universe?','जगत जननी के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','A');
INSERT INTO knowledge_quiz VALUES(794,'Which vow is observed during Navratri fasting?','नवरात्रि उपवास में क्या किया जाता है?','[{"key": "A", "en": "Grain fasting", "hi": "अन्न त्याग"}, {"key": "B", "en": "Fruit fasting", "hi": "फलाहार"}, {"key": "C", "en": "Water fasting", "hi": "निर्जल"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(795,'Which demon was killed by Goddess Parvati as Kaushiki?','कौशिकी रूप में देवी पार्वती ने किसका वध किया?','[{"key": "A", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "B", "en": "Shumbha", "hi": "शुंभ"}, {"key": "C", "en": "Nishumbha", "hi": "निशुंभ"}, {"key": "D", "en": "Chanda and Munda", "hi": "चंड और मुंड"}]','D');
INSERT INTO knowledge_quiz VALUES(796,'Which sacred place is associated with Sage Kapila?','ऋषि कपिल से कौन सा तीर्थ जुड़ा है?','[{"key": "A", "en": "Kapilavastu", "hi": "कपिलवस्तु"}, {"key": "B", "en": "Kapilashram", "hi": "कपिलाश्रम"}, {"key": "C", "en": "Sarnath", "hi": "सारनाथ"}, {"key": "D", "en": "Bodh Gaya", "hi": "बोधगया"}]','B');
INSERT INTO knowledge_quiz VALUES(797,'Which deity is worshipped as the lord of wealth?','धन के देवता कौन माने जाते हैं?','[{"key": "A", "en": "Kubera", "hi": "कुबेर"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','A');
INSERT INTO knowledge_quiz VALUES(798,'The Amruteshwar Temple in Ratanwadi, near Bhandardara, was built in the 9th century in which architectural style?','भंडारदरा के पास रतनवाड़ी में स्थित मृतेश्वर मंदिर 9वीं शताब्दी में किस वास्तुकला शैली में बनाया गया था?','[{"key": "A", "en": "Dravidian", "hi": "द्रविड़"}, {"key": "B", "en": "Hemadpanti", "hi": "हेमाडपंती"}, {"key": "C", "en": "Nagara", "hi": "नागर"}, {"key": "D", "en": "Vesara", "hi": "वेसर"}]','B');
INSERT INTO knowledge_quiz VALUES(799,'Which goddess is worshipped during Varalakshmi Vratam?','वरलक्ष्मी व्रतम में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(800,'In the Kurukshetra war, how many Akshauhinis did the Kauravas and Pandavas have respectively?','कुरुक्षेत्र युद्ध में कौरवों और पांडवों के पास क्रमशः कितनी अक्षौहिणी सेना थी?','[{"key": "A", "en": "7 and 11", "hi": "7 और 11"}, {"key": "B", "en": "11 and 7", "hi": "11 और 7"}, {"key": "C", "en": "9 and 9", "hi": "9 और 9"}, {"key": "D", "en": "10 and 8", "hi": "10 और 8"}]','B');
INSERT INTO knowledge_quiz VALUES(801,'Which deity is known as the god of water?','जल के देवता कौन माने जाते हैं?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Varuna", "hi": "वरुण"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Vayu", "hi": "वायु"}]','B');
INSERT INTO knowledge_quiz VALUES(802,'In a traditional Aarti, the plate is moved in which direction as per the scriptures?','शास्त्रों के अनुसार, पारंपरिक आरती में थाली को किस दिशा में घुमाया जाता है?','[{"key": "A", "en": "Anti-clockwise", "hi": "वामावर्त (उल्टा)"}, {"key": "B", "en": "Clockwise", "hi": "दक्षिणावर्त (सीधा)"}, {"key": "C", "en": "Up and Down", "hi": "ऊपर और नीचे"}, {"key": "D", "en": "Only horizontal", "hi": "केवल क्षैतिज"}]','B');
INSERT INTO knowledge_quiz VALUES(803,'Which puja material is used to draw sacred symbols like the Swastika or Om on the puja thali?','पूजा की थाली पर स्वास्तिक या ओम जैसे पवित्र प्रतीक बनाने के लिए किस सामग्री का उपयोग किया जाता है?','[{"key": "A", "en": "Saffron", "hi": "केसर"}, {"key": "B", "en": "Turmeric/Kumkum", "hi": "हल्दी/कुमकुम"}, {"key": "C", "en": "Black ink", "hi": "काली स्याही"}, {"key": "D", "en": "Sugar", "hi": "चीनी"}]','B');
INSERT INTO knowledge_quiz VALUES(804,'By what other name is the River Godavari known, especially in the context of it being brought by Sage Gautama?','गोदावरी नदी को और किस नाम से जाना जाता है, विशेष रूप से ऋषि गौतम द्वारा लाए जाने के संदर्भ में?','[{"key": "A", "en": "Reva", "hi": "रेवा"}, {"key": "B", "en": "Kalindi", "hi": "कालिंदी"}, {"key": "C", "en": "Gautami", "hi": "गौतमी"}, {"key": "D", "en": "Mandakini", "hi": "मंदाकिनी"}]','C');
INSERT INTO knowledge_quiz VALUES(805,'Which scripture describes the duties of householders?','गृहस्थ के कर्तव्यों का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "B", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "C", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "D", "en": "Nyaya Sutra", "hi": "न्याय सूत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(806,'Which festival is celebrated to welcome spring?','वसंत के स्वागत में कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Vasant Panchami", "hi": "वसंत पंचमी"}, {"key": "B", "en": "Diwali", "hi": "दीपावली"}, {"key": "C", "en": "Dussehra", "hi": "दशहरा"}, {"key": "D", "en": "Janmashtami", "hi": "जन्माष्टमी"}]','A');
INSERT INTO knowledge_quiz VALUES(807,'Which Pandava was expert in astrology?','ज्योतिष विद्या में कौन सा पांडव निपुण था?','[{"key": "A", "en": "Nakula", "hi": "नकुल"}, {"key": "B", "en": "Sahadeva", "hi": "सहदेव"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Bhima", "hi": "भीम"}]','B');
INSERT INTO knowledge_quiz VALUES(808,'Which sacred hymn is chanted for prosperity?','समृद्धि के लिए कौन सा स्तोत्र जपा जाता है?','[{"key": "A", "en": "Kanakadhara Stotram", "hi": "कनकधारा स्तोत्र"}, {"key": "B", "en": "Shiva Tandava Stotram", "hi": "शिव तांडव स्तोत्र"}, {"key": "C", "en": "Vishnu Sahasranama", "hi": "विष्णु सहस्रनाम"}, {"key": "D", "en": "Hanuman Chalisa", "hi": "हनुमान चालीसा"}]','A');
INSERT INTO knowledge_quiz VALUES(809,'Which river is associated with Sage Agastya?','ऋषि अगस्त्य से कौन सी नदी जुड़ी है?','[{"key": "A", "en": "Kaveri", "hi": "कावेरी"}, {"key": "B", "en": "Godavari", "hi": "गोदावरी"}, {"key": "C", "en": "Narmada", "hi": "नर्मदा"}, {"key": "D", "en": "Krishna", "hi": "कृष्णा"}]','A');
INSERT INTO knowledge_quiz VALUES(810,'Which hill among the seven hills of Tirumala is the Venkateswara Temple located on?','तिरुपति के सात पर्वतों में से किस पर्वत पर भगवान वेंकटेश्वर का मंदिर स्थित है?','[{"key": "A", "en": "Garudadri", "hi": "गरुदाद्रि"}, {"key": "B", "en": "Vrishabhadri", "hi": "वृषभाद्रि"}, {"key": "C", "en": "Venkatadri", "hi": "वेंकटाद्रि"}, {"key": "D", "en": "Anjanadri", "hi": "अंजनाद्रि"}]','C');
INSERT INTO knowledge_quiz VALUES(811,'Which Purana describes the genealogy of kings?','राजाओं की वंशावली का वर्णन किस पुराण में है?','[{"key": "A", "en": "Vayu Purana", "hi": "वायु पुराण"}, {"key": "B", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "C", "en": "Agni Purana", "hi": "अग्नि पुराण"}, {"key": "D", "en": "Narada Purana", "hi": "नारद पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(812,'Which goddess is worshipped as the consort of Vishnu?','भगवान विष्णु की सहचरी देवी कौन हैं?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','B');
INSERT INTO knowledge_quiz VALUES(813,'Which scripture explains the eightfold path of yoga?','अष्टांग योग की व्याख्या किस ग्रंथ में है?','[{"key": "A", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Nyaya Sutra", "hi": "न्याय सूत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(814,'Which temple marks the spot where Sati''s ''Eyes'' (Nayan) fell?','कौन सा मंदिर उस स्थान को चिह्नित करता है जहाँ सती के ''नयन'' (आंखें) गिरे थे?','[{"key": "A", "en": "Naina Devi, Himachal Pradesh", "hi": "नैना देवी, हिमाचल प्रदेश"}, {"key": "B", "en": "Chamunda Devi", "hi": "चामुंडा देवी"}, {"key": "C", "en": "Vindhyavasini", "hi": "विंध्यवासिनी"}, {"key": "D", "en": "Jwala Ji", "hi": "ज्वाला जी"}]','A');
INSERT INTO knowledge_quiz VALUES(815,'Which sacred city is associated with Goddess Meenakshi?','देवी मीनाक्षी से कौन सा नगर जुड़ा है?','[{"key": "A", "en": "Madurai", "hi": "मदुरै"}, {"key": "B", "en": "Kanchipuram", "hi": "कांचीपुरम"}, {"key": "C", "en": "Rameswaram", "hi": "रामेश्वरम"}, {"key": "D", "en": "Chidambaram", "hi": "चिदंबरम"}]','A');
