INSERT INTO knowledge_quiz VALUES(851,'Which deity is worshipped as the god of oceans?','समुद्र के देवता कौन माने जाते हैं?','[{"key": "A", "en": "Varuna", "hi": "वरुण"}, {"key": "B", "en": "Agni", "hi": "अग्नि"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Vayu", "hi": "वायु"}]','A');
INSERT INTO knowledge_quiz VALUES(852,'Which river is associated with Prayagraj Sangam?','प्रयागराज संगम किन नदियों से जुड़ा है?','[{"key": "A", "en": "Ganga and Yamuna", "hi": "गंगा और यमुना"}, {"key": "B", "en": "Ganga and Saraswati", "hi": "गंगा और सरस्वती"}, {"key": "C", "en": "Yamuna and Saraswati", "hi": "यमुना और सरस्वती"}, {"key": "D", "en": "All three", "hi": "तीनों"}]','D');
INSERT INTO knowledge_quiz VALUES(853,'What is the name of the ritual where devotees carry decorated structures on their shoulders for Murugan?','उस अनुष्ठान का नाम क्या है जिसमें भक्त मुरुगन के लिए अपने कंधों पर सजी हुई संरचनाएं ले जाते हैं?','[{"key": "A", "en": "Abhishekam", "hi": "अभिषेकम"}, {"key": "B", "en": "Kavadi Attam", "hi": "कावड़ी अट्टम"}, {"key": "C", "en": "Theyyam", "hi": "तेय्यम"}, {"key": "D", "en": "Kummi", "hi": "कुम्मी"}]','B');
INSERT INTO knowledge_quiz VALUES(854,'Who is the father of Surya Dev and one of the Prajapatis?','सूर्य देव के पिता और प्रजापतियों में से एक कौन हैं?','[{"key": "A", "en": "Sage Vashistha", "hi": "ऋषि वशिष्ठ"}, {"key": "B", "en": "Sage Kashyapa", "hi": "ऋषि कश्यप"}, {"key": "C", "en": "Sage Atri", "hi": "ऋषि अत्रि"}, {"key": "D", "en": "Sage Vishwamitra", "hi": "ऋषि विश्वामित्र"}]','B');
INSERT INTO knowledge_quiz VALUES(855,'Which scripture explains Dharma, Artha, Kama, and Moksha?','धर्म, अर्थ, काम और मोक्ष की व्याख्या किस ग्रंथ में मिलती है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Vedas", "hi": "वेद"}, {"key": "C", "en": "Smriti texts", "hi": "स्मृति ग्रंथ"}, {"key": "D", "en": "Puranas", "hi": "पुराण"}]','C');
INSERT INTO knowledge_quiz VALUES(856,'Which festival celebrates the return of Lord Rama to Ayodhya?','भगवान राम के अयोध्या लौटने की खुशी में कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Diwali", "hi": "दीपावली"}, {"key": "B", "en": "Dussehra", "hi": "दशहरा"}, {"key": "C", "en": "Ram Navami", "hi": "राम नवमी"}, {"key": "D", "en": "Holi", "hi": "होली"}]','A');
INSERT INTO knowledge_quiz VALUES(857,'Which Pandava was known for wisdom?','बुद्धिमत्ता के लिए कौन सा पांडव प्रसिद्ध था?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Sahadeva", "hi": "सहदेव"}, {"key": "D", "en": "Yudhishthira", "hi": "युधिष्ठिर"}]','C');
INSERT INTO knowledge_quiz VALUES(858,'Which sacred hymn praises Lord Shiva?','भगवान शिव की स्तुति करने वाला स्तोत्र कौन सा है?','[{"key": "A", "en": "Shiva Tandava Stotram", "hi": "शिव तांडव स्तोत्र"}, {"key": "B", "en": "Kanakadhara Stotram", "hi": "कनकधारा स्तोत्र"}, {"key": "C", "en": "Durga Saptashati", "hi": "दुर्गा सप्तशती"}, {"key": "D", "en": "Vishnu Sahasranama", "hi": "विष्णु सहस्रनाम"}]','A');
INSERT INTO knowledge_quiz VALUES(859,'Which river is associated with Naimisharanya?','नैमिषारण्य किस नदी से जुड़ा है?','[{"key": "A", "en": "Gomti", "hi": "गोमती"}, {"key": "B", "en": "Sarayu", "hi": "सरयू"}, {"key": "C", "en": "Ghaghara", "hi": "घाघरा"}, {"key": "D", "en": "Yamuna", "hi": "यमुना"}]','A');
INSERT INTO knowledge_quiz VALUES(860,'Which deity is worshipped during Kartik Purnima?','कार्तिक पूर्णिमा पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Kartikeya", "hi": "कार्तिकेय"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(861,'Which Purana describes the story of Samudra Manthan in detail?','समुद्र मंथन की विस्तृत कथा किस पुराण में है?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "C", "en": "Vayu Purana", "hi": "वायु पुराण"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(862,'By which other popular name is the River Narmada known in Hindu scriptures?','हिंदू शास्त्रों में नर्मदा नदी को और किस लोकप्रिय नाम से जाना जाता है?','[{"key": "A", "en": "Kshipra", "hi": "क्षिप्रा"}, {"key": "B", "en": "Reva", "hi": "रेवा"}, {"key": "C", "en": "Kalindi", "hi": "कालिंदी"}, {"key": "D", "en": "Mandakini", "hi": "मंदाकिनी"}]','B');
INSERT INTO knowledge_quiz VALUES(863,'Which scripture teaches the concept of Bhakti Yoga?','भक्ति योग की शिक्षा किस ग्रंथ में मिलती है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "C", "en": "Nyaya Sutra", "hi": "न्याय सूत्र"}, {"key": "D", "en": "Arthashastra", "hi": "अर्थशास्त्र"}]','A');
INSERT INTO knowledge_quiz VALUES(864,'At the Jwala Ji Temple in Himachal Pradesh, which part of Sati fell?','हिमाचल प्रदेश के ज्वाला जी मंदिर में सती का कौन सा भाग गिरा था?','[{"key": "A", "en": "Lower Lip", "hi": "निचला होंठ"}, {"key": "B", "en": "Tongue", "hi": "जीभ"}, {"key": "C", "en": "Chin", "hi": "ठोड़ी"}, {"key": "D", "en": "Neck", "hi": "गर्दन"}]','B');
INSERT INTO knowledge_quiz VALUES(865,'Which sacred city is associated with Lord Shiva as Vishwanath?','विश्वनाथ रूप में भगवान शिव से कौन सा नगर जुड़ा है?','[{"key": "A", "en": "Ujjain", "hi": "उज्जैन"}, {"key": "B", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "C", "en": "Kedarnath", "hi": "केदारनाथ"}, {"key": "D", "en": "Somnath", "hi": "सोमनाथ"}]','B');
INSERT INTO knowledge_quiz VALUES(866,'Which vow is observed for Goddess Lakshmi on Fridays?','शुक्रवार को देवी लक्ष्मी के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Friday Vrat", "hi": "शुक्रवार व्रत"}, {"key": "B", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "C", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "D", "en": "Shani Vrat", "hi": "शनि व्रत"}]','A');
INSERT INTO knowledge_quiz VALUES(867,'Which direction is guarded by Lord Yama as the Dikpala?','दिक्पाल के रूप में भगवान यम किस दिशा की रक्षा करते हैं?','[{"key": "A", "en": "North", "hi": "उत्तर"}, {"key": "B", "en": "South", "hi": "दक्षिण"}, {"key": "C", "en": "East", "hi": "पूर्व"}, {"key": "D", "en": "West", "hi": "पश्चिम"}]','B');
INSERT INTO knowledge_quiz VALUES(868,'Which river is known as the lifeline of Madhya Pradesh?','मध्य प्रदेश की जीवनरेखा किस नदी को कहा जाता है?','[{"key": "A", "en": "Narmada", "hi": "नर्मदा"}, {"key": "B", "en": "Tapi", "hi": "तापी"}, {"key": "C", "en": "Chambal", "hi": "चंबल"}, {"key": "D", "en": "Betwa", "hi": "बेतवा"}]','A');
INSERT INTO knowledge_quiz VALUES(869,'In the Aarti ''Jai Ganesh Deva'', the line ''Andhan ko aankh det'' refers to Ganesha''s power to grant sight. What does ''Kodian ko kaya'' refer to?','आरती ''जय गणेश देवा'' में पंक्ति ''अँधन को आँख देत'' गणेश जी की दृष्टि देने की शक्ति को दर्शाती है। ''कोढ़िन को काया'' का क्या अर्थ है?','[{"key": "A", "en": "Granting wealth to the poor", "hi": "गरीबों को धन देना"}, {"key": "B", "en": "Healing the diseased body", "hi": "रोगी शरीर को स्वस्थ करना"}, {"key": "C", "en": "Giving clothes to the naked", "hi": "निर्धन को वस्त्र देना"}, {"key": "D", "en": "Giving children to the childless", "hi": "संतानहीनों को संतान देना"}]','B');
INSERT INTO knowledge_quiz VALUES(870,'Which scripture is known as the fifth Veda?','पंचम वेद किसे कहा जाता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Puranas", "hi": "पुराण"}, {"key": "D", "en": "Arthashastra", "hi": "अर्थशास्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(871,'Which deity is worshipped in Kedarnath?','केदारनाथ में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','B');
INSERT INTO knowledge_quiz VALUES(872,'Which river flows near Mathura?','मथुरा के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Ghaghara", "hi": "घाघरा"}, {"key": "D", "en": "Betwa", "hi": "बेतवा"}]','B');
INSERT INTO knowledge_quiz VALUES(873,'Which sacred forest in Braj is associated with Shani Dev?','ब्रज में स्थित कौन सा पवित्र वन शनि देव से संबंधित है?','[{"key": "A", "en": "Nidhivan", "hi": "निधिवन"}, {"key": "B", "en": "Seva Kunj", "hi": "सेवा कुंज"}, {"key": "C", "en": "Kokilavan", "hi": "कोकिलावन"}, {"key": "D", "en": "Bhandirvan", "hi": "भांडीरवन"}]','C');
INSERT INTO knowledge_quiz VALUES(874,'Which vow is observed during Pitru Paksha?','पितृ पक्ष में कौन सा कर्म किया जाता है?','[{"key": "A", "en": "Shraddha", "hi": "श्राद्ध"}, {"key": "B", "en": "Homa", "hi": "होम"}, {"key": "C", "en": "Japa", "hi": "जप"}, {"key": "D", "en": "Abhisheka", "hi": "अभिषेक"}]','A');
INSERT INTO knowledge_quiz VALUES(875,'What is the name of the divine bell of Goddess Durga, whose sound is said to terrify demons?','देवी दुर्गा की उस दिव्य घंटी का क्या नाम है, जिसकी ध्वनि के बारे में कहा जाता है कि वह असुरों को भयभीत कर देती है?','[{"key": "A", "en": "Ghanta", "hi": "घंटा"}, {"key": "B", "en": "Maharava", "hi": "महारव"}, {"key": "C", "en": "Sughosha", "hi": "सुघोष"}, {"key": "D", "en": "Dhvani", "hi": "ध्वनि"}]','B');
INSERT INTO knowledge_quiz VALUES(876,'Which sacred place is associated with Sage Valmiki?','ऋषि वाल्मीकि से कौन सा स्थल जुड़ा है?','[{"key": "A", "en": "Valmiki Ashram", "hi": "वाल्मीकि आश्रम"}, {"key": "B", "en": "Naimisharanya", "hi": "नैमिषारण्य"}, {"key": "C", "en": "Chitrakoot", "hi": "चित्रकूट"}, {"key": "D", "en": "Prayagraj", "hi": "प्रयागराज"}]','A');
INSERT INTO knowledge_quiz VALUES(877,'Which two brothers of Ravana ruled the Janasthana and were defeated by Rama after Surpanakha''s humiliation?','रावण के किन दो भाइयों ने जनस्थान पर शासन किया और शूर्पणखा के अपमान के बाद राम द्वारा पराजित हुए थे?','[{"key": "A", "en": "Khara and Dushana", "hi": "खर और दूषण"}, {"key": "B", "en": "Ahiravan and Mahiravan", "hi": "अहिरावण और महिरावण"}, {"key": "C", "en": "Prahasta and Akampana", "hi": "प्रहस्त और अकंपन"}, {"key": "D", "en": "Malyavan and Sumali", "hi": "माल्यवान और सुमाली"}]','A');
INSERT INTO knowledge_quiz VALUES(878,'How many spokes (Aaras) are there in the single wheel of Surya''s chariot, representing the seasons or months?','ऋतुओं या महीनों का प्रतिनिधित्व करने वाले सूर्य के रथ के एकमात्र पहिये में कितनी तीलियाँ (आर) होती हैं?','[{"key": "A", "en": "Six", "hi": "छह"}, {"key": "B", "en": "Twelve", "hi": "बारह"}, {"key": "C", "en": "Twenty-four", "hi": "चौबीस"}, {"key": "D", "en": "Eight", "hi": "आठ"}]','B');
INSERT INTO knowledge_quiz VALUES(879,'Which goddess is worshipped as the protector of children?','बच्चों की रक्षक देवी कौन मानी जाती हैं?','[{"key": "A", "en": "Shashthi Devi", "hi": "षष्ठी देवी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Kali", "hi": "काली"}]','A');
INSERT INTO knowledge_quiz VALUES(880,'Which scripture emphasizes Karma Yoga?','कर्म योग पर विशेष बल देने वाला ग्रंथ कौन सा है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Nyaya Sutra", "hi": "न्याय सूत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(881,'Which deity is worshipped in Badrinath?','बद्रीनाथ में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','A');
INSERT INTO knowledge_quiz VALUES(882,'Which river flows near Haridwar?','हरिद्वार के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','B');
INSERT INTO knowledge_quiz VALUES(883,'Which goddess is worshipped during Navratri as Mahagauri?','नवरात्रि में महागौरी रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Kali", "hi": "काली"}]','B');
INSERT INTO knowledge_quiz VALUES(884,'Which demon was killed by Lord Krishna at Mathura?','मथुरा में भगवान कृष्ण ने किसका वध किया?','[{"key": "A", "en": "Kamsa", "hi": "कंस"}, {"key": "B", "en": "Chanura", "hi": "चानूर"}, {"key": "C", "en": "Mushtika", "hi": "मुश्टिक"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(885,'Which sacred place is associated with Goddess Kamakhya?','देवी कामाख्या से कौन सा तीर्थ जुड़ा है?','[{"key": "A", "en": "Guwahati", "hi": "गुवाहाटी"}, {"key": "B", "en": "Kolkata", "hi": "कोलकाता"}, {"key": "C", "en": "Puri", "hi": "पुरी"}, {"key": "D", "en": "Madurai", "hi": "मदुरै"}]','A');
INSERT INTO knowledge_quiz VALUES(886,'Which vow is observed for Lord Surya?','भगवान सूर्य के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Chhath Vrat", "hi": "छठ व्रत"}, {"key": "B", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "C", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "D", "en": "Shani Vrat", "hi": "शनि व्रत"}]','A');
INSERT INTO knowledge_quiz VALUES(887,'Which deity is worshipped as the remover of sins?','पाप नाशक देवता किसे माना जाता है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(888,'Which river is known as the lifeline of Uttar Pradesh?','उत्तर प्रदेश की जीवनरेखा किस नदी को कहा जाता है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Ghaghara", "hi": "घाघरा"}, {"key": "D", "en": "Gomti", "hi": "गोमती"}]','B');
INSERT INTO knowledge_quiz VALUES(889,'Which goddess is worshipped as the divine mother?','दिव्य माता के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Adi Shakti", "hi": "आदि शक्ति"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','A');
INSERT INTO knowledge_quiz VALUES(890,'Which scripture narrates the story of King Bali?','राजा बलि की कथा किस ग्रंथ में मिलती है?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "C", "en": "Agni Purana", "hi": "अग्नि पुराण"}, {"key": "D", "en": "Narada Purana", "hi": "नारद पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(891,'Which deity is worshipped in Rameswaram?','रामेश्वरम में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','B');
INSERT INTO knowledge_quiz VALUES(892,'Which river flows near Chidambaram?','चिदंबरम के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Kaveri", "hi": "कावेरी"}, {"key": "B", "en": "Coleroon", "hi": "कोल्लेरून"}, {"key": "C", "en": "Vaigai", "hi": "वैगई"}, {"key": "D", "en": "Tamiraparani", "hi": "ताम्रपर्णी"}]','B');
INSERT INTO knowledge_quiz VALUES(893,'Which goddess is worshipped during Durga Puja?','दुर्गा पूजा में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Kali", "hi": "काली"}]','B');
INSERT INTO knowledge_quiz VALUES(894,'Which demon was killed by Lord Rama?','भगवान राम ने किस राक्षस का वध किया?','[{"key": "A", "en": "Ravana", "hi": "रावण"}, {"key": "B", "en": "Maricha", "hi": "मारीच"}, {"key": "C", "en": "Khara", "hi": "खर"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(895,'Which coastal temple in Karnataka is home to the world''s second-tallest statue of Lord Shiva?','कर्नाटक के किस तटीय मंदिर में भगवान शिव की दुनिया की दूसरी सबसे ऊंची मूर्ति स्थित है?','[{"key": "A", "en": "Gokarna Mahabaleshwar", "hi": "गोकर्ण महाबलेश्वर"}, {"key": "B", "en": "Murudeshwar Temple", "hi": "मुरुदेश्वर मंदिर"}, {"key": "C", "en": "Idagunji Ganpati", "hi": "इडागुंजी गणपति"}, {"key": "D", "en": "Kollur Mookambika", "hi": "कोल्लूर मूकांबिका"}]','B');
INSERT INTO knowledge_quiz VALUES(896,'Which temple complex in Bishnupur is famous for its pyramid-shaped structure and was used to house the idols of Krishna during festivals?','बिष्णुपुर का कौन सा मंदिर परिसर अपनी पिरामिड जैसी संरचना के लिए प्रसिद्ध है और त्योहारों के दौरान कृष्ण की मूर्तियों को रखने के लिए इस्तेमाल किया जाता था?','[{"key": "A", "en": "Madan Mohan Temple", "hi": "मदन मोहन मंदिर"}, {"key": "B", "en": "Rasmancha", "hi": "रासमंच"}, {"key": "C", "en": "Jor Bangla", "hi": "जोर बांग्ला"}, {"key": "D", "en": "Shyamrai Temple", "hi": "श्यामराय मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(897,'Which deity is worshipped as the god of knowledge?','ज्ञान के देवता किसे माना जाता है?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "C", "en": "Ganesha", "hi": "गणेश"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(898,'In which famous temple are the 12 wheels of Surya''s chariot carved on the sides of the structure?','किस प्रसिद्ध मंदिर में सूर्य के रथ के 12 पहिये संरचना के किनारों पर उकेरे गए हैं?','[{"key": "A", "en": "Modhera Sun Temple", "hi": "मोढेरा सूर्य मंदिर"}, {"key": "B", "en": "Konark Sun Temple", "hi": "कोणार्क सूर्य मंदिर"}, {"key": "C", "en": "Martand Sun Temple", "hi": "मार्तंड सूर्य मंदिर"}, {"key": "D", "en": "Arasavalli Temple", "hi": "अरसावल्ली मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(899,'Which goddess is worshipped as the giver of boons?','वरदान देने वाली देवी कौन मानी जाती हैं?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Santoshi Mata", "hi": "संतोषी माता"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','C');
INSERT INTO knowledge_quiz VALUES(900,'Which scripture summarizes the essence of the Vedas?','वेदों का सार किस ग्रंथ में निहित है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Brahmanas", "hi": "ब्राह्मण"}, {"key": "C", "en": "Aranyakas", "hi": "आरण्यक"}, {"key": "D", "en": "Smritis", "hi": "स्मृति"}]','A');
INSERT INTO knowledge_quiz VALUES(901,'Which animal is the ''Vahana'' (mount) of the goddess of misfortune, Alakshmi?','दुर्भाग्य की देवी, अलक्ष्मी का ''वाहन'' कौन सा जानवर है?','[{"key": "A", "en": "Donkey", "hi": "गधा"}, {"key": "B", "en": "Crow", "hi": "कौआ"}, {"key": "C", "en": "Owl", "hi": "उल्लू"}, {"key": "D", "en": "Cat", "hi": "बिल्ली"}]','A');
INSERT INTO knowledge_quiz VALUES(902,'Which river is associated with Kedarnath?','केदारनाथ किस नदी से जुड़ा है?','[{"key": "A", "en": "Mandakini", "hi": "मंदाकिनी"}, {"key": "B", "en": "Alaknanda", "hi": "अलकनंदा"}, {"key": "C", "en": "Bhagirathi", "hi": "भागीरथी"}, {"key": "D", "en": "Yamuna", "hi": "यमुना"}]','A');
INSERT INTO knowledge_quiz VALUES(903,'Which vow is observed on Thursdays?','गुरुवार को कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Guru Vrat", "hi": "गुरु व्रत"}, {"key": "B", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "C", "en": "Shani Vrat", "hi": "शनि व्रत"}, {"key": "D", "en": "Mangal Vrat", "hi": "मंगल व्रत"}]','A');
INSERT INTO knowledge_quiz VALUES(904,'Which of the following sages is traditionally included in the list of Saptarishis of the current Manvantara?','निम्नलिखित में से कौन से ऋषि वर्तमान मन्वंतर के सप्तर्षियों की सूची में शामिल हैं?','[{"key": "A", "en": "Sage Valmiki", "hi": "ऋषि वाल्मीकि"}, {"key": "B", "en": "Sage Vashistha", "hi": "ऋषि वशिष्ठ"}, {"key": "C", "en": "Sage Vyasa", "hi": "ऋषि व्यास"}, {"key": "D", "en": "Sage Parashurama", "hi": "ऋषि परशुराम"}]','B');
INSERT INTO knowledge_quiz VALUES(905,'Which scripture explains duties according to varna and ashrama?','वर्ण और आश्रम के अनुसार कर्तव्यों का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Yoga Sutra", "hi": "योगसूत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(906,'The Vishnupad Temple in Gaya features a 40-cm-long footprint of Lord Vishnu. Which Maratha queen reconstructed this temple in 1787?','गया के विष्णुपद मंदिर में भगवान विष्णु का 40 सेमी लंबा पदचिह्न है। 1787 में किस मराठा रानी ने इस मंदिर का पुनर्निर्माण कराया था?','[{"key": "A", "en": "Rani Laxmibai", "hi": "रानी लक्ष्मीबाई"}, {"key": "B", "en": "Ahilyabai Holkar", "hi": "अहिल्याबाई होलकर"}, {"key": "C", "en": "Jijabai", "hi": "जीजाबाई"}, {"key": "D", "en": "Tarabai", "hi": "ताराबाई"}]','B');
INSERT INTO knowledge_quiz VALUES(907,'Near which Dham is the ''Mana'' village located, known as the last Indian village?','किस धाम के पास ''माणा'' गाँव स्थित है, जिसे भारत का अंतिम गाँव कहा जाता है?','[{"key": "A", "en": "Yamunotri", "hi": "यमुनोत्री"}, {"key": "B", "en": "Gangotri", "hi": "गंगोत्री"}, {"key": "C", "en": "Badrinath", "hi": "बद्रीनाथ"}, {"key": "D", "en": "Kedarnath", "hi": "केदारनाथ"}]','C');
INSERT INTO knowledge_quiz VALUES(908,'Which sacred hymn is chanted for peace?','शांति के लिए कौन सा मंत्र बोला जाता है?','[{"key": "A", "en": "Shanti Mantra", "hi": "शांति मंत्र"}, {"key": "B", "en": "Gayatri Mantra", "hi": "गायत्री मंत्र"}, {"key": "C", "en": "Mahamrityunjaya Mantra", "hi": "महामृत्युंजय मंत्र"}, {"key": "D", "en": "Beej Mantra", "hi": "बीज मंत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(909,'Which river is associated with Chitrakoot?','चित्रकूट किस नदी से जुड़ा है?','[{"key": "A", "en": "Mandakini", "hi": "मंदाकिनी"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Sarayu", "hi": "सरयू"}]','A');
INSERT INTO knowledge_quiz VALUES(910,'According to the Puranas, how many times did Lord Vishnu take the Mohini avatar?','पुराणों के अनुसार, भगवान विष्णु ने कितनी बार मोहिनी अवतार लिया था?','[{"key": "A", "en": "Once ", "hi": "एक बार"}, {"key": "B", "en": "Twice", "hi": "दो बार"}, {"key": "C", "en": "Three times", "hi": "तीन बार"}, {"key": "D", "en": "Multiple times in different Kalpas", "hi": "विभिन्न कल्पों में कई बार"}]','B');
INSERT INTO knowledge_quiz VALUES(911,'Which Purana describes the glory of Lord Vishnu?','भगवान विष्णु की महिमा का वर्णन किस पुराण में है?','[{"key": "A", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "B", "en": "Agni Purana", "hi": "अग्नि पुराण"}, {"key": "C", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "D", "en": "Narada Purana", "hi": "नारद पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(912,'Who was the maidservant who convinced Queen Kaikeyi to ask King Dasharatha for Lord Rama''s exile?','वह दासी कौन थी जिसने रानी कैकेयी को राजा दशरथ से भगवान राम के वनवास की मांग करने के लिए उकसाया था?','[{"key": "A", "en": "Trijata", "hi": "त्रिजटा"}, {"key": "B", "en": "Manthara", "hi": "मंथरा"}, {"key": "C", "en": "Surpanakha", "hi": "शूर्पणखा"}, {"key": "D", "en": "Mandodari", "hi": "मंदोदरी"}]','B');
INSERT INTO knowledge_quiz VALUES(913,'Which scripture teaches renunciation?','वैराग्य की शिक्षा किस ग्रंथ में मिलती है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "C", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "D", "en": "Brahmanas", "hi": "ब्राह्मण"}]','A');
INSERT INTO knowledge_quiz VALUES(914,'Which demon was killed by Lord Parashurama?','भगवान परशुराम ने किसका वध किया?','[{"key": "A", "en": "Kartavirya Arjuna", "hi": "कर्तवीर्य अर्जुन"}, {"key": "B", "en": "Hiranyakashipu", "hi": "हिरण्यकश्यप"}, {"key": "C", "en": "Bali", "hi": "बलि"}, {"key": "D", "en": "Ravana", "hi": "रावण"}]','A');
INSERT INTO knowledge_quiz VALUES(915,'Which sacred city is associated with Lord Krishna’s childhood?','भगवान कृष्ण के बाल्यकाल से कौन सा नगर जुड़ा है?','[{"key": "A", "en": "Mathura", "hi": "मथुरा"}, {"key": "B", "en": "Dwarka", "hi": "द्वारका"}, {"key": "C", "en": "Vrindavan", "hi": "वृंदावन"}, {"key": "D", "en": "Kurukshetra", "hi": "कुरुक्षेत्र"}]','C');
INSERT INTO knowledge_quiz VALUES(916,'Which vow is observed during Karva Chauth?','करवा चौथ में कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Husband’s long life", "hi": "पति की दीर्घायु"}, {"key": "B", "en": "Wealth", "hi": "धन"}, {"key": "C", "en": "Children", "hi": "संतान"}, {"key": "D", "en": "Health", "hi": "स्वास्थ्य"}]','A');
INSERT INTO knowledge_quiz VALUES(917,'Which deity is worshipped as the remover of ignorance?','अज्ञान नाशक देवता किसे माना जाता है?','[{"key": "A", "en": "Ganesha", "hi": "गणेश"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(918,'Which river is known as the lifeline of Rajasthan?','राजस्थान की जीवनरेखा किस नदी को कहा जाता है?','[{"key": "A", "en": "Luni", "hi": "लूणी"}, {"key": "B", "en": "Chambal", "hi": "चंबल"}, {"key": "C", "en": "Banas", "hi": "बाणास"}, {"key": "D", "en": "Mahi", "hi": "माही"}]','A');
INSERT INTO knowledge_quiz VALUES(919,'Which goddess is worshipped as Annapurna?','अन्नपूर्णा रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(920,'Which scripture explains the concept of Maya?','माया की अवधारणा किस ग्रंथ में समझाई गई है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "C", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "D", "en": "Smritis", "hi": "स्मृति"}]','A');
INSERT INTO knowledge_quiz VALUES(921,'Which bright red flower is the most favorite offering for Goddess Kali?','देवी काली को अर्पित किया जाने वाला सबसे प्रिय लाल रंग का फूल कौन सा है?','[{"key": "A", "en": "Hibiscus", "hi": "गुड़हल"}, {"key": "B", "en": "Rose", "hi": "गुलाब"}, {"key": "C", "en": "Marigold", "hi": "गेंदा"}, {"key": "D", "en": "Tulip", "hi": "ट्यूलिप"}]','A');
INSERT INTO knowledge_quiz VALUES(922,'Which river flows near Dwarka?','द्वारका के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Gomti", "hi": "गोमती"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Yamuna", "hi": "यमुना"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','A');
INSERT INTO knowledge_quiz VALUES(923,'In the Hanuman Chalisa, ''Sadhu Santa ke tuma rakhaware''. Who are the ''Sadhu'' and ''Santa''?','हनुमान चालीसा में, ''साधु संत के तुम रखवारे''। यहाँ ''साधु'' और ''संत'' कौन हैं?','[{"key": "A", "en": "Warriors", "hi": "योद्धा"}, {"key": "B", "en": "Sages and Holy People", "hi": "ऋषि और सज्जन लोग"}, {"key": "C", "en": "Kings", "hi": "राजा"}, {"key": "D", "en": "Commoners", "hi": "आम आदमी"}]','B');
INSERT INTO knowledge_quiz VALUES(924,'Which demon was killed by Lord Indra?','इंद्र देव ने किस असुर का वध किया?','[{"key": "A", "en": "Vritra", "hi": "वृत्र"}, {"key": "B", "en": "Bali", "hi": "बलि"}, {"key": "C", "en": "Ravana", "hi": "रावण"}, {"key": "D", "en": "Hiranyakashipu", "hi": "हिरण्यकश्यप"}]','A');
INSERT INTO knowledge_quiz VALUES(925,'The Annamalaiyar Temple is situated at the foot of the Annamalai hill. For which festival is it world-famous?','अन्नामलाईयार मंदिर अन्नामलाई पहाड़ी की तलहटी में स्थित है। यह किस त्योहार के लिए विश्व प्रसिद्ध है?','[{"key": "A", "en": "Pongal", "hi": "पोंगल"}, {"key": "B", "en": "Karthigai Deepam", "hi": "कार्तिकेय दीपम"}, {"key": "C", "en": "Thaipusam", "hi": "थाईपुसम"}, {"key": "D", "en": "Chithirai Thiruvizha", "hi": "चित्तिराई तिरुविझा"}]','B');
INSERT INTO knowledge_quiz VALUES(926,'Which vow is observed during Teej?','तीज में कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "For marital bliss", "hi": "वैवाहिक सुख हेतु"}, {"key": "B", "en": "For wealth", "hi": "धन हेतु"}, {"key": "C", "en": "For children", "hi": "संतान हेतु"}, {"key": "D", "en": "For health", "hi": "स्वास्थ्य हेतु"}]','A');
INSERT INTO knowledge_quiz VALUES(927,'Which deity is worshipped as the lord of yoga?','योग के अधिपति देवता कौन हैं?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','A');
INSERT INTO knowledge_quiz VALUES(928,'Which river is associated with Ujjain?','उज्जैन किस नदी से जुड़ा है?','[{"key": "A", "en": "Shipra", "hi": "शिप्रा"}, {"key": "B", "en": "Narmada", "hi": "नर्मदा"}, {"key": "C", "en": "Betwa", "hi": "बेतवा"}, {"key": "D", "en": "Tapi", "hi": "तापी"}]','A');
INSERT INTO knowledge_quiz VALUES(929,'Which goddess is worshipped as Kali?','काली रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Adi Shakti", "hi": "आदि शक्ति"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
