INSERT INTO knowledge_quiz VALUES(954,'Who was the wife of Lord Rama?','भगवान राम की पत्नी कौन थीं?','[{"key": "A", "en": "Sita", "hi": "सीता"}, {"key": "B", "en": "Urmila", "hi": "उर्मिला"}, {"key": "C", "en": "Mandavi", "hi": "मांडवी"}, {"key": "D", "en": "Shrutakirti", "hi": "श्रुतकीर्ति"}]','A');
