INSERT INTO knowledge_quiz VALUES(959,'Which river flows near Haridwar?','हरिद्वार के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Alaknanda", "hi": "अलकनंदा"}, {"key": "D", "en": "Sarayu", "hi": "सरयू"}]','A');
