INSERT INTO knowledge_quiz VALUES(961,'Which Purana narrates the story of Lord Rama?','भगवान राम की कथा किस पुराण में मिलती है?','[{"key": "A", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "B", "en": "Padma Purana", "hi": "पद्म पुराण"}, {"key": "C", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "D", "en": "Narada Purana", "hi": "नारद पुराण"}]','C');
INSERT INTO knowledge_quiz VALUES(962,'Which goddess is worshipped as the river Yamuna?','यमुना नदी को किस देवी के रूप में पूजा जाता है?','[{"key": "A", "en": "Kalindi", "hi": "कालिंदी"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','A');
