INSERT INTO knowledge_quiz VALUES(1047,'Which deity is worshipped as the god of wealth?','धन के देवता कौन माने जाते हैं?','[{"key": "A", "en": "Kubera", "hi": "कुबेर"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','A');
INSERT INTO knowledge_quiz VALUES(1048,'Which river is associated with Gangotri?','गंगोत्री किस नदी से जुड़ा है?','[{"key": "A", "en": "Bhagirathi", "hi": "भागीरथी"}, {"key": "B", "en": "Alaknanda", "hi": "अलकनंदा"}, {"key": "C", "en": "Mandakini", "hi": "मंदाकिनी"}, {"key": "D", "en": "Yamuna", "hi": "यमुना"}]','A');
INSERT INTO knowledge_quiz VALUES(1049,'Tungnath is known as the highest Shiva temple in the world. At what approximate altitude is it located?','तुंगनाथ को दुनिया के सबसे ऊंचे शिव मंदिर के रूप में जाना जाता है। यह लगभग कितनी ऊंचाई पर स्थित है?','[{"key": "A", "en": "3,450 meters", "hi": "3,450 मीटर"}, {"key": "B", "en": "3,680 meters", "hi": "3,680 मीटर"}, {"key": "C", "en": "4,100 meters", "hi": "4,100 मीटर"}, {"key": "D", "en": "3,200 meters", "hi": "3,200 मीटर"}]','B');
INSERT INTO knowledge_quiz VALUES(1050,'Which scripture is known as the song of the Lord?','भगवान का गीत किस ग्रंथ को कहा जाता है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "C", "en": "Vedas", "hi": "वेद"}, {"key": "D", "en": "Puranas", "hi": "पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(1051,'Which deity is worshipped as the god of justice?','न्याय के देवता किसे माना जाता है?','[{"key": "A", "en": "Yama", "hi": "यम"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','A');
INSERT INTO knowledge_quiz VALUES(1052,'Which spiritual practice involves singing the glories of God through repetitive verses like a Chalisa?','चालीसा जैसे दोहराव वाले छंदों के माध्यम से ईश्वर की महिमा गाने वाली आध्यात्मिक साधना को क्या कहा जाता है?','[{"key": "A", "en": "Yoga", "hi": "योग"}, {"key": "B", "en": "Kirtan/Path", "hi": "कीर्तन/पाठ"}, {"key": "C", "en": "Dhyana", "hi": "ध्यान"}, {"key": "D", "en": "Pranayama", "hi": "प्राणायाम"}]','B');
INSERT INTO knowledge_quiz VALUES(1053,'Which vow is observed on Fridays?','शुक्रवार को कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Lakshmi Vrat", "hi": "लक्ष्मी व्रत"}, {"key": "B", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "C", "en": "Shani Vrat", "hi": "शनि व्रत"}, {"key": "D", "en": "Mangal Vrat", "hi": "मंगल व्रत"}]','A');
INSERT INTO knowledge_quiz VALUES(1054,'Which Saptarishi is known for his intense rivalry with Sage Vishwamitra?','कौन से सप्तर्षि ऋषि विश्वामित्र के साथ अपनी घोर प्रतिद्वंद्विता के लिए जाने जाते हैं?','[{"key": "A", "en": "Sage Gautama", "hi": "ऋषि गौतम"}, {"key": "B", "en": "Sage Atri", "hi": "ऋषि अत्रि"}, {"key": "C", "en": "Sage Vashistha", "hi": "ऋषि वशिष्ठ"}, {"key": "D", "en": "Sage Jamadagni", "hi": "ऋषि जमदग्नि"}]','C');
INSERT INTO knowledge_quiz VALUES(1055,'Which scripture is attributed to Sage Patanjali?','ऋषि पतंजलि से संबंधित ग्रंथ कौन सा है?','[{"key": "A", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "B", "en": "Nyaya Sutra", "hi": "न्याय सूत्र"}, {"key": "C", "en": "Brahma Sutra", "hi": "ब्रह्मसूत्र"}, {"key": "D", "en": "Narada Bhakti Sutra", "hi": "नारद भक्ति सूत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1056,'Which festival celebrates the worship of Goddess Lakshmi?','देवी लक्ष्मी की पूजा किस पर्व में होती है?','[{"key": "A", "en": "Diwali", "hi": "दीपावली"}, {"key": "B", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "C", "en": "Holi", "hi": "होली"}, {"key": "D", "en": "Maha Shivaratri", "hi": "महाशिवरात्रि"}]','A');
INSERT INTO knowledge_quiz VALUES(1057,'Which Pandava was known for archery?','धनुर्विद्या के लिए कौन सा पांडव प्रसिद्ध था?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Nakula", "hi": "नकुल"}, {"key": "D", "en": "Sahadeva", "hi": "सहदेव"}]','A');
INSERT INTO knowledge_quiz VALUES(1058,'Which mantra is known as the universal prayer?','सार्वभौमिक प्रार्थना के रूप में कौन सा मंत्र जाना जाता है?','[{"key": "A", "en": "Gayatri Mantra", "hi": "गायत्री मंत्र"}, {"key": "B", "en": "Shanti Mantra", "hi": "शांति मंत्र"}, {"key": "C", "en": "Mahamrityunjaya Mantra", "hi": "महामृत्युंजय मंत्र"}, {"key": "D", "en": "Beej Mantra", "hi": "बीज मंत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1059,'Which river flows near Vrindavan?','वृंदावन के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','A');
INSERT INTO knowledge_quiz VALUES(1060,'What is the name of Shani Dev''s weapon?','शनि देव के अस्त्र का नाम क्या है?','[{"key": "A", "en": "Danda (Staff)", "hi": "दण्ड"}, {"key": "B", "en": "Pasha (Noose)", "hi": "पाश"}, {"key": "C", "en": "Trishul", "hi": "त्रिशूल"}, {"key": "D", "en": "Sudarshana", "hi": "सुदर्शन"}]','A');
INSERT INTO knowledge_quiz VALUES(1061,'Which Purana narrates the childhood of Lord Krishna in detail?','भगवान कृष्ण के बाल्यकाल का विस्तृत वर्णन किस पुराण में है?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(1062,'Which goddess is worshipped as the river Narmada?','नर्मदा नदी को किस देवी के रूप में पूजा जाता है?','[{"key": "A", "en": "Reva", "hi": "रेवा"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Yamuna", "hi": "यमुना"}]','A');
INSERT INTO knowledge_quiz VALUES(1063,'Which scripture discusses Raja Yoga?','राजयोग की चर्चा किस ग्रंथ में है?','[{"key": "A", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Arthashastra", "hi": "अर्थशास्त्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1064,'At the Mansa Devi Temple in Haridwar, which part of Sati is said to have fallen?','हरिद्वार के मनसा देवी मंदिर में सती का कौन सा भाग गिरा बताया जाता है?','[{"key": "A", "en": "Head/Forehead", "hi": "सिर/माथा"}, {"key": "B", "en": "Hands", "hi": "हाथ"}, {"key": "C", "en": "Stomach", "hi": "पेट"}, {"key": "D", "en": "Heart", "hi": "हृदय"}]','A');
INSERT INTO knowledge_quiz VALUES(1065,'Which sacred city is associated with Lord Shiva as Vishwanath?','विश्वनाथ रूप में भगवान शिव से कौन सा नगर जुड़ा है?','[{"key": "A", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "B", "en": "Ujjain", "hi": "उज्जैन"}, {"key": "C", "en": "Kedarnath", "hi": "केदारनाथ"}, {"key": "D", "en": "Somnath", "hi": "सोमनाथ"}]','A');
INSERT INTO knowledge_quiz VALUES(1066,'Which vow is observed during Hartalika Teej?','हरतालिका तीज में कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "For marital bliss", "hi": "वैवाहिक सुख हेतु"}, {"key": "B", "en": "For wealth", "hi": "धन हेतु"}, {"key": "C", "en": "For children", "hi": "संतान हेतु"}, {"key": "D", "en": "For health", "hi": "स्वास्थ्य हेतु"}]','A');
INSERT INTO knowledge_quiz VALUES(1067,'Which deity is worshipped as the god of water?','जल के देवता कौन माने जाते हैं?','[{"key": "A", "en": "Varuna", "hi": "वरुण"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Vayu", "hi": "वायु"}]','A');
INSERT INTO knowledge_quiz VALUES(1068,'Which river is associated with Chitrakoot?','चित्रकूट किस नदी से जुड़ा है?','[{"key": "A", "en": "Mandakini", "hi": "मंदाकिनी"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Sarayu", "hi": "सरयू"}]','A');
INSERT INTO knowledge_quiz VALUES(1069,'Which goddess is worshipped as Mahalakshmi?','महालक्ष्मी के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(1070,'Which scripture explains Jnana Yoga?','ज्ञान योग की व्याख्या किस ग्रंथ में है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "C", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "D", "en": "Manusmriti", "hi": "मनुस्मृति"}]','A');
INSERT INTO knowledge_quiz VALUES(1071,'Which deity is worshipped in Kedarnath Temple?','केदारनाथ मंदिर में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','A');
INSERT INTO knowledge_quiz VALUES(1072,'The ''Ganesh Chalisa'' states that Lord Ganesha was born from the dirt of whose body?','गणेश चालीसा के अनुसार, भगवान गणेश का जन्म किसके शरीर के उबटन (मैल) से हुआ था?','[{"key": "A", "en": "Lord Shiva", "hi": "भगवान शिव"}, {"key": "B", "en": "Goddess Parvati", "hi": "देवी पार्वती"}, {"key": "C", "en": "Lord Vishnu", "hi": "भगवान विष्णु"}, {"key": "D", "en": "Lord Brahma", "hi": "भगवान ब्रह्मा"}]','B');
INSERT INTO knowledge_quiz VALUES(1073,'Which goddess is worshipped during Varalakshmi Vratam?','वरलक्ष्मी व्रतम में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(1074,'Which divine boat was used by Satyavrata (Manu) to survive the great flood, guided by Lord Vishnu in Matsya avatar?','सत्यव्रत (मनु) ने महाप्रलय से बचने के लिए किस दिव्य नाव का उपयोग किया था, जिसका मार्गदर्शन मत्स्य अवतार में भगवान विष्णु ने किया था?','[{"key": "A", "en": "Nau", "hi": "नौ"}, {"key": "B", "en": "Naubandhana", "hi": "नौबन्धन"}, {"key": "C", "en": "Vaitarani", "hi": "वैतरणी"}, {"key": "D", "en": "Tarani", "hi": "तरणि"}]','B');
INSERT INTO knowledge_quiz VALUES(1075,'In which temple of Karnataka is Lord Krishna worshipped through a silver-plated window with nine holes (Navagruha Kindi)?','कर्नाटक के किस मंदिर में नौ छिद्रों वाली चांदी की खिड़की (नवग्रह किंडी) के माध्यम से भगवान कृष्ण की पूजा की जाती है?','[{"key": "A", "en": "Udupi Sri Krishna Matha", "hi": "उडुपी श्री कृष्ण मठ"}, {"key": "B", "en": "ISKCON Bangalore", "hi": "इस्कॉन बैंगलोर"}, {"key": "C", "en": "Venugopala Swamy", "hi": "वेणुगोपाल स्वामी"}, {"key": "D", "en": "Ambalapuzha", "hi": "अम्बलपुझा"}]','A');
INSERT INTO knowledge_quiz VALUES(1076,'The ''Jor-Bangla'' style of architecture, seen in many Bengal temples, is characterized by its roofs resembling what?','बंगाल के कई मंदिरों में देखी जाने वाली वास्तुकला की ''जोर-बांग्ला'' शैली की विशेषता इसकी छतें हैं, जो किसके समान दिखती हैं?','[{"key": "A", "en": "Pyramids", "hi": "पिरामिड"}, {"key": "B", "en": "Two joined thatched huts", "hi": "दो जुड़ी हुई फूस की झोपड़ियां"}, {"key": "C", "en": "Domes", "hi": "गुंबद"}, {"key": "D", "en": "Lotus flowers", "hi": "कमल के फूल"}]','B');
INSERT INTO knowledge_quiz VALUES(1077,'Which deity is worshipped as the god of wealth?','धन के देवता कौन माने जाते हैं?','[{"key": "A", "en": "Kubera", "hi": "कुबेर"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','A');
INSERT INTO knowledge_quiz VALUES(1078,'Which color is traditionally associated with the horses of the Sun God in most iconography?','अधिकांश प्रतिमा विज्ञान में सूर्य देव के घोड़ों के साथ पारंपरिक रूप से कौन सा रंग जुड़ा हुआ है?','[{"key": "A", "en": "Black", "hi": "काला"}, {"key": "B", "en": "White", "hi": "सफेद"}, {"key": "C", "en": "Red", "hi": "लाल"}, {"key": "D", "en": "Green", "hi": "हरा"}]','B');
INSERT INTO knowledge_quiz VALUES(1079,'Which goddess is worshipped as the remover of ignorance?','अज्ञान नाशिनी देवी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(1080,'Which scripture summarizes the essence of Vedantic philosophy?','वेदांत दर्शन का सार किस ग्रंथ में निहित है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Brahmanas", "hi": "ब्राह्मण"}, {"key": "C", "en": "Aranyakas", "hi": "आरण्यक"}, {"key": "D", "en": "Smritis", "hi": "स्मृति"}]','A');
INSERT INTO knowledge_quiz VALUES(1081,'In which direction does Shani Dev''s idol or temple traditionally face?','शनि देव की मूर्ति या मंदिर का मुख पारंपरिक रूप से किस दिशा की ओर होता है?','[{"key": "A", "en": "East", "hi": "पूर्व"}, {"key": "B", "en": "North", "hi": "उत्तर"}, {"key": "C", "en": "West", "hi": "पश्चिम"}, {"key": "D", "en": "South", "hi": "दक्षिण"}]','C');
INSERT INTO knowledge_quiz VALUES(1082,'Which river flows near Prayagraj?','प्रयागराज के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1083,'Which goddess is worshipped as the giver of knowledge?','ज्ञान प्रदान करने वाली देवी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','A');
INSERT INTO knowledge_quiz VALUES(1084,'Which demon was killed by Goddess Kali?','देवी काली ने किस असुर का वध किया?','[{"key": "A", "en": "Raktabija", "hi": "रक्तबीज"}, {"key": "B", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "C", "en": "Shumbha", "hi": "शुंभ"}, {"key": "D", "en": "Nishumbha", "hi": "निशुंभ"}]','A');
INSERT INTO knowledge_quiz VALUES(1085,'Which sacred city is associated with Lord Rama?','भगवान राम से कौन सा नगर जुड़ा है?','[{"key": "A", "en": "Ayodhya", "hi": "अयोध्या"}, {"key": "B", "en": "Mathura", "hi": "मथुरा"}, {"key": "C", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "D", "en": "Prayagraj", "hi": "प्रयागराज"}]','A');
INSERT INTO knowledge_quiz VALUES(1086,'What was the name of the pot containing the nectar of immortality (Amrita) during Samudra Manthan?','समुद्र मंथन के दौरान अमरता के अमृत (अमृत) वाले कलश का नाम क्या था?','[{"key": "A", "en": "Kamandalu", "hi": "कमंडलु"}, {"key": "B", "en": "Amrita Kalasha", "hi": "अमृत कलश"}, {"key": "C", "en": "Akshaya Patra", "hi": "अक्षय पात्र"}, {"key": "D", "en": "Soma", "hi": "सोम"}]','B');
INSERT INTO knowledge_quiz VALUES(1087,'Which deity is worshipped as the lord of knowledge?','ज्ञान के अधिपति देवता कौन माने जाते हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "C", "en": "Ganesha", "hi": "गणेश"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1088,'Which river is known as the lifeline of Madhya Pradesh?','मध्य प्रदेश की जीवनरेखा किस नदी को कहा जाता है?','[{"key": "A", "en": "Narmada", "hi": "नर्मदा"}, {"key": "B", "en": "Betwa", "hi": "बेतवा"}, {"key": "C", "en": "Chambal", "hi": "चंबल"}, {"key": "D", "en": "Tapi", "hi": "तापी"}]','A');
INSERT INTO knowledge_quiz VALUES(1089,'Which goddess is worshipped as the divine mother?','दिव्य माता के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Adi Shakti", "hi": "आदि शक्ति"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(1090,'Which scripture teaches the concept of Dharma?','धर्म की अवधारणा किस ग्रंथ में समझाई गई है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "C", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "D", "en": "Charaka Samhita", "hi": "चरक संहिता"}]','A');
INSERT INTO knowledge_quiz VALUES(1091,'Which deity is worshipped in Amarnath Cave?','अमरनाथ गुफा में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','A');
INSERT INTO knowledge_quiz VALUES(1092,'Which river flows near Ayodhya?','अयोध्या के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Sarayu", "hi": "सरयू"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Yamuna", "hi": "यमुना"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','A');
INSERT INTO knowledge_quiz VALUES(1093,'Which goddess is worshipped during Durga Puja?','दुर्गा पूजा में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Kali", "hi": "काली"}]','A');
INSERT INTO knowledge_quiz VALUES(1094,'Which demon was killed by Lord Rama?','भगवान राम ने किस राक्षस का वध किया?','[{"key": "A", "en": "Ravana", "hi": "रावण"}, {"key": "B", "en": "Maricha", "hi": "मारीच"}, {"key": "C", "en": "Khara", "hi": "खर"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1095,'The Kapaleeshwarar Temple in Chennai is dedicated to Lord Shiva and is built in which architectural style?','चेन्नई का कपालेश्वर मंदिर भगवान शिव को समर्पित है और यह किस वास्तुकला शैली में बना है?','[{"key": "A", "en": "Nagara", "hi": "नागर"}, {"key": "B", "en": "Dravidian", "hi": "द्रविड़"}, {"key": "C", "en": "Vesara", "hi": "वेसर"}, {"key": "D", "en": "Kalinga", "hi": "कलिंग"}]','B');
INSERT INTO knowledge_quiz VALUES(1096,'Which vow is observed during Teej?','तीज में कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "For marital bliss", "hi": "वैवाहिक सुख हेतु"}, {"key": "B", "en": "For wealth", "hi": "धन हेतु"}, {"key": "C", "en": "For health", "hi": "स्वास्थ्य हेतु"}, {"key": "D", "en": "For children", "hi": "संतान हेतु"}]','A');
INSERT INTO knowledge_quiz VALUES(1097,'What was the name of the only female philosopher who challenged Sage Yajnavalkya in King Janaka''s court?','राजा जनक की सभा में ऋषि याज्ञवल्क्य को चुनौती देने वाली एकमात्र महिला दार्शनिक का नाम क्या था?','[{"key": "A", "en": "Maitreyi", "hi": "मैत्रेयी"}, {"key": "B", "en": "Gargi", "hi": "गार्गी"}, {"key": "C", "en": "Lopamudra", "hi": "लोपामुद्रा"}, {"key": "D", "en": "Anusuya", "hi": "अनुसूया"}]','B');
INSERT INTO knowledge_quiz VALUES(1098,'Which famous bridge connects the mainland of India to the Pamban Island where Rameshwaram is located?','कौन सा प्रसिद्ध पुल भारत की मुख्य भूमि को पंबन द्वीप से जोड़ता है जहाँ रामेश्वरम स्थित है?','[{"key": "A", "en": "Howrah Bridge", "hi": "हावड़ा ब्रिज"}, {"key": "B", "en": "Pamban Bridge", "hi": "पंबन ब्रिज"}, {"key": "C", "en": "Bandra-Worli Sea Link", "hi": "बांद्रा-वर्ली सी लिंक"}, {"key": "D", "en": "Adam''s Bridge", "hi": "एडम ब्रिज"}]','B');
INSERT INTO knowledge_quiz VALUES(1099,'Which goddess is worshipped as the embodiment of power?','शक्ति के स्वरूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Shakti", "hi": "शक्ति"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(1100,'Which scripture is regarded as the philosophical conclusion of the Vedas?','वेदों का दार्शनिक निष्कर्ष किसे माना जाता है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Brahmanas", "hi": "ब्राह्मण"}, {"key": "C", "en": "Aranyakas", "hi": "आरण्यक"}, {"key": "D", "en": "Smritis", "hi": "स्मृति"}]','A');
INSERT INTO knowledge_quiz VALUES(1101,'Which king of the Ikshvaku dynasty was cursed to remain suspended between heaven and earth, creating ''Trishanku Swarga''?','इक्ष्वाकु वंश के किस राजा को स्वर्ग और पृथ्वी के बीच अधर में लटके रहने का श्राप मिला था, जिससे ''त्रिशंकु स्वर्ग'' की उत्पत्ति हुई?','[{"key": "A", "en": "Sagara", "hi": "सगर"}, {"key": "B", "en": "Satyavrata", "hi": "सत्यव्रत"}, {"key": "C", "en": "Harishchandra", "hi": "हरिश्चंद्र"}, {"key": "D", "en": "Dilipa", "hi": "दिलीप"}]','B');
INSERT INTO knowledge_quiz VALUES(1102,'Which river is associated with Kedarnath?','केदारनाथ किस नदी से जुड़ा है?','[{"key": "A", "en": "Mandakini", "hi": "मंदाकिनी"}, {"key": "B", "en": "Alaknanda", "hi": "अलकनंदा"}, {"key": "C", "en": "Bhagirathi", "hi": "भागीरथी"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','A');
INSERT INTO knowledge_quiz VALUES(1103,'Which vow is observed on Thursdays?','गुरुवार को कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Guru Vrat", "hi": "गुरु व्रत"}, {"key": "B", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "C", "en": "Shani Vrat", "hi": "शनि व्रत"}, {"key": "D", "en": "Mangal Vrat", "hi": "मंगल व्रत"}]','A');
INSERT INTO knowledge_quiz VALUES(1104,'Who was the wife of Lord Krishna?','भगवान कृष्ण की प्रमुख पत्नी कौन थीं?','[{"key": "A", "en": "Rukmini", "hi": "रुक्मिणी"}, {"key": "B", "en": "Radha", "hi": "राधा"}, {"key": "C", "en": "Satyabhama", "hi": "सत्यभामा"}, {"key": "D", "en": "Jambavati", "hi": "जाम्बवती"}]','A');
INSERT INTO knowledge_quiz VALUES(1105,'Which scripture explains Bhakti Sutras?','भक्ति सूत्र किस ऋषि से संबंधित हैं?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Patanjali", "hi": "पतंजलि"}, {"key": "D", "en": "Valmiki", "hi": "वाल्मीकि"}]','A');
INSERT INTO knowledge_quiz VALUES(1106,'Which temple in Patna is one of the oldest and most famous dedicated to Lord Hanuman, known for its ''Naivedyam'' laddoos?','पटना का कौन सा मंदिर भगवान हनुमान को समर्पित सबसे पुराने और प्रसिद्ध मंदिरों में से एक है, जो अपने ''नैवेद्यम'' लड्डू के लिए जाना जाता है?','[{"key": "A", "en": "Patan Devi", "hi": "पाटन देवी"}, {"key": "B", "en": "Mahavir Mandir", "hi": "महावीर मंदिर"}, {"key": "C", "en": "Sheetla Mata", "hi": "शीतला माता"}, {"key": "D", "en": "Badi Patan Devi", "hi": "बड़ी पाटन देवी"}]','B');
INSERT INTO knowledge_quiz VALUES(1107,'Where are the historic swords, believed to belong to the Pandavas, worshipped at a nearby pond?','कहाँ में पांडवों की ऐतिहासिक तलवारों की पूजा की जाती है?','[{"key": "A", "en": "Nandi Kund", "hi": "नंदी कुंड"}, {"key": "B", "en": "Gauri Kund", "hi": "गौरी कुंड"}, {"key": "C", "en": "Kalpeshwar", "hi": "कल्पेश्वर"}, {"key": "D", "en": "Kedarnath", "hi": "केदारनाथ"}]','A');
INSERT INTO knowledge_quiz VALUES(1108,'Which mantra is chanted for peace?','शांति के लिए कौन सा मंत्र जपा जाता है?','[{"key": "A", "en": "Shanti Mantra", "hi": "शांति मंत्र"}, {"key": "B", "en": "Gayatri Mantra", "hi": "गायत्री मंत्र"}, {"key": "C", "en": "Beej Mantra", "hi": "बीज मंत्र"}, {"key": "D", "en": "Agni Mantra", "hi": "अग्नि मंत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1109,'Which river flows near Naimisharanya?','नैमिषारण्य के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Gomti", "hi": "गोमती"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','A');
INSERT INTO knowledge_quiz VALUES(1110,'Which deity is worshipped during Vishnu Sahasranama recitation?','विष्णु सहस्रनाम में किस देवता की उपासना होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','A');
INSERT INTO knowledge_quiz VALUES(1111,'Which Purana describes cosmic creation?','सृष्टि की उत्पत्ति का वर्णन किस पुराण में है?','[{"key": "A", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "B", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "C", "en": "Agni Purana", "hi": "अग्नि पुराण"}, {"key": "D", "en": "Narada Purana", "hi": "नारद पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(1112,'Which goddess is worshipped as the river Ganga?','गंगा नदी को किस देवी के रूप में पूजा जाता है?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Jahnavi", "hi": "जाह्नवी"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(1113,'Which scripture deals with Ayurveda?','आयुर्वेद से संबंधित ग्रंथ कौन सा है?','[{"key": "A", "en": "Charaka Samhita", "hi": "चरक संहिता"}, {"key": "B", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "C", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "D", "en": "Manusmriti", "hi": "मनुस्मृति"}]','A');
INSERT INTO knowledge_quiz VALUES(1114,'The ''Akashiganga'' pilgrimage site is associated with the legend of Goddess Sati. It is believed that which part of her body fell here?','''आकाशगंगा'' तीर्थ स्थल देवी सती की कथा से जुड़ा है। माना जाता है कि यहाँ उनके शरीर का कौन सा भाग गिरा था?','[{"key": "A", "en": "Eyes", "hi": "आंखें"}, {"key": "B", "en": "Head", "hi": "सिर"}, {"key": "C", "en": "Hand", "hi": "हाथ"}, {"key": "D", "en": "Heart", "hi": "हृदय"}]','B');
INSERT INTO knowledge_quiz VALUES(1115,'Which sacred city is associated with Sage Vashishta?','ऋषि वशिष्ठ से कौन सा नगर जुड़ा है?','[{"key": "A", "en": "Ayodhya", "hi": "अयोध्या"}, {"key": "B", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "C", "en": "Ujjain", "hi": "उज्जैन"}, {"key": "D", "en": "Prayagraj", "hi": "प्रयागराज"}]','A');
INSERT INTO knowledge_quiz VALUES(1116,'In the Hanuman Chalisa, the line ''Prabhu pratap maha jagat ujiyara'' implies that Hanuman''s glory enlightens the entire world. What does ''Pratap'' mean here?','हनुमान चालीसा की पंक्ति ''प्रभु प्रताप महा जगत उजियारा'' का अर्थ है कि हनुमान का यश पूरे संसार को आलोकित करता है। यहाँ ''प्रताप'' का क्या अर्थ है?','[{"key": "A", "en": "Wealth", "hi": "धन"}, {"key": "B", "en": "Divine Glory/Majesty", "hi": "दिव्य तेज/महिमा"}, {"key": "C", "en": "Anger", "hi": "क्रोध"}, {"key": "D", "en": "Form", "hi": "रूप"}]','B');
INSERT INTO knowledge_quiz VALUES(1117,'Which deity is worshipped as the god of speech?','वाणी के देवता किसे माना जाता है?','[{"key": "A", "en": "Brihaspati", "hi": "बृहस्पति"}, {"key": "B", "en": "Agni", "hi": "अग्नि"}, {"key": "C", "en": "Vayu", "hi": "वायु"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','A');
INSERT INTO knowledge_quiz VALUES(1118,'Which river is associated with Srirangam?','श्रीरंगम किस नदी से जुड़ा है?','[{"key": "A", "en": "Kaveri", "hi": "कावेरी"}, {"key": "B", "en": "Godavari", "hi": "गोदावरी"}, {"key": "C", "en": "Krishna", "hi": "कृष्णा"}, {"key": "D", "en": "Tungabhadra", "hi": "तुंगभद्रा"}]','A');
INSERT INTO knowledge_quiz VALUES(1119,'Which goddess is worshipped as Lalita Tripurasundari?','ललिता त्रिपुरसुंदरी किस देवी का रूप हैं?','[{"key": "A", "en": "Adi Shakti", "hi": "आदि शक्ति"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','A');
INSERT INTO knowledge_quiz VALUES(1120,'Which scripture explains Karma Yoga?','कर्म योग की व्याख्या किस ग्रंथ में है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Manusmriti", "hi": "मनुस्मृति"}]','A');
INSERT INTO knowledge_quiz VALUES(1121,'Which deity is worshipped in Udupi Temple?','उडुपी मंदिर में किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Rama", "hi": "राम"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','A');
INSERT INTO knowledge_quiz VALUES(1122,'Which river flows near Puri?','पुरी के पास कौन सी नदी बहती है?','[{"key": "A", "en": "No major river", "hi": "कोई प्रमुख नदी नहीं"}, {"key": "B", "en": "Mahanadi", "hi": "महानदी"}, {"key": "C", "en": "Brahmani", "hi": "ब्राह्मणी"}, {"key": "D", "en": "Subarnarekha", "hi": "सुवर्णरेखा"}]','A');
INSERT INTO knowledge_quiz VALUES(1123,'The Mansa Devi Temple, a prominent Shakti Peetha, is located in which district of Haryana?','मनसा देवी मंदिर, जो एक प्रमुख शक्तिपीठ है, हरियाणा के किस जिले में स्थित है?','[{"key": "A", "en": "Gurugram", "hi": "गुरुग्राम"}, {"key": "B", "en": "Panchkula", "hi": "पंचकूला"}, {"key": "C", "en": "Ambala", "hi": "अंबाला"}, {"key": "D", "en": "Karnal", "hi": "करनाल"}]','B');
INSERT INTO knowledge_quiz VALUES(1124,'Which demon was killed by Lord Rama at Dandakaranya?','दंडकारण्य में भगवान राम ने किसका वध किया?','[{"key": "A", "en": "Khara", "hi": "खर"}, {"key": "B", "en": "Ravana", "hi": "रावण"}, {"key": "C", "en": "Bali", "hi": "बलि"}, {"key": "D", "en": "Vritra", "hi": "वृत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1125,'Which sacred place is associated with Sage Kapila?','ऋषि कपिल से कौन सा स्थल जुड़ा है?','[{"key": "A", "en": "Kapilavastu", "hi": "कपिलवस्तु"}, {"key": "B", "en": "Bodh Gaya", "hi": "बोधगया"}, {"key": "C", "en": "Nalanda", "hi": "नालंदा"}, {"key": "D", "en": "Sarnath", "hi": "सारनाथ"}]','A');
INSERT INTO knowledge_quiz VALUES(1126,'Which vow is observed during Vat Savitri?','वट सावित्री में कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "For husband’s long life", "hi": "पति की दीर्घायु हेतु"}, {"key": "B", "en": "For children", "hi": "संतान हेतु"}, {"key": "C", "en": "For wealth", "hi": "धन हेतु"}, {"key": "D", "en": "For health", "hi": "स्वास्थ्य हेतु"}]','A');
