INSERT INTO knowledge_quiz VALUES(1130,'Which scripture describes the four Ashramas?','चार आश्रमों का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Yoga Sutra", "hi": "योगसूत्र"}]','A');
