INSERT INTO knowledge_quiz VALUES(1136,'Which of these temples is world-famous for its ''Hall of Thousand Pillars''?','इनमें से कौन सा मंदिर अपने ''हजार स्तंभों वाले हॉल'' के लिए विश्व प्रसिद्ध है?','[{"key": "A", "en": "Sabarimala", "hi": "सबरीमाला"}, {"key": "B", "en": "Meenakshi Amman Temple", "hi": "मीनाक्षी अम्मन मंदिर"}, {"key": "C", "en": "Padmanabhaswamy Temple", "hi": "पद्मनाभस्वामी मंदिर"}, {"key": "D", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(1137,'Which deity is worshipped as the sun god?','सूर्य देव किसे माना जाता है?','[{"key": "A", "en": "Surya", "hi": "सूर्य"}, {"key": "B", "en": "Agni", "hi": "अग्नि"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','A');
