INSERT INTO knowledge_quiz VALUES(1139,'Which goddess is worshipped as the consort of Vishnu?','विष्णु की पत्नी के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','A');
INSERT INTO knowledge_quiz VALUES(1140,'Which scripture is known as the fifth Veda?','पंचम वेद किसे कहा जाता है?','[{"key": "A", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "B", "en": "Ramayana", "hi": "रामायण"}, {"key": "C", "en": "Puranas", "hi": "पुराण"}, {"key": "D", "en": "Upanishads", "hi": "उपनिषद"}]','A');
INSERT INTO knowledge_quiz VALUES(1141,'Which deity is worshipped in Tiruvannamalai?','तिरुवन्नामलाई में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Murugan", "hi": "मुरुगन"}, {"key": "D", "en": "Ganesha", "hi": "गणेश"}]','A');
INSERT INTO knowledge_quiz VALUES(1142,'Which river flows near Nashik?','नासिक के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Godavari", "hi": "गोदावरी"}, {"key": "B", "en": "Krishna", "hi": "कृष्णा"}, {"key": "C", "en": "Bhima", "hi": "भीमा"}, {"key": "D", "en": "Tapi", "hi": "तापी"}]','A');
INSERT INTO knowledge_quiz VALUES(1143,'Which goddess is worshipped during Navaratri as Mahagauri?','नवरात्रि में महागौरी के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','A');
INSERT INTO knowledge_quiz VALUES(1144,'Which demon was killed by Goddess Durga during Navratri?','नवरात्रि में देवी दुर्गा ने किस असुर का वध किया?','[{"key": "A", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "B", "en": "Raktabija", "hi": "रक्तबीज"}, {"key": "C", "en": "Shumbha", "hi": "शुंभ"}, {"key": "D", "en": "Nishumbha", "hi": "निशुंभ"}]','A');
INSERT INTO knowledge_quiz VALUES(1145,'Which sacred place is associated with Sage Vyasa?','ऋषि व्यास से कौन सा स्थल जुड़ा है?','[{"key": "A", "en": "Badari (Badrinath)", "hi": "बदरी (बद्रीनाथ)"}, {"key": "B", "en": "Ayodhya", "hi": "अयोध्या"}, {"key": "C", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "D", "en": "Prayagraj", "hi": "प्रयागराज"}]','A');
INSERT INTO knowledge_quiz VALUES(1146,'Which poisonous flower is considered very dear to Lord Shiva and is offered to his Lingam?','कौन सा विषैला फूल भगवान शिव को बहुत प्रिय माना जाता है और उनके शिवलिंग पर चढ़ाया जाता है?','[{"key": "A", "en": "Datura", "hi": "धतूरा"}, {"key": "B", "en": "Oleander", "hi": "कनेर"}, {"key": "C", "en": "Calotropis (Akanda)", "hi": "आक (मदार)"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1147,'Which deity is worshipped as the lord of time?','काल के देवता किसे माना जाता है?','[{"key": "A", "en": "Mahakal", "hi": "महाकाल"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Yama", "hi": "यम"}]','A');
INSERT INTO knowledge_quiz VALUES(1148,'Which temple was the family deity (Kuldevi) of Chhatrapati Shivaji Maharaj?','छत्रपति शिवाजी महाराज की कुलदेवी कौन सा मंदिर था?','[{"key": "A", "en": "Mumbadevi", "hi": "मुंबादेवी"}, {"key": "B", "en": "Tulja Bhavani", "hi": "तुलजा भवानी"}, {"key": "C", "en": "Mahalakshmi", "hi": "महालक्ष्मी"}, {"key": "D", "en": "Saptashrungi", "hi": "सप्तशृंगी"}]','B');
INSERT INTO knowledge_quiz VALUES(1149,'Which goddess is worshipped as the embodiment of compassion?','करुणा की मूर्ति के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','A');
INSERT INTO knowledge_quiz VALUES(1150,'Which scripture systematizes Yoga philosophy?','योग दर्शन को व्यवस्थित करने वाला ग्रंथ कौन सा है?','[{"key": "A", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Manusmriti", "hi": "मनुस्मृति"}]','A');
INSERT INTO knowledge_quiz VALUES(1151,'Who is considered to be the ''Guru'' (teacher) of Shani Dev?','शनि देव के गुरु कौन माने जाते हैं?','[{"key": "A", "en": "Lord Shiva", "hi": "भगवान शिव"}, {"key": "B", "en": "Lord Vishnu", "hi": "भगवान विष्णु"}, {"key": "C", "en": "Sage Brihaspati", "hi": "ऋषि बृहस्पति"}, {"key": "D", "en": "Sage Shukracharya", "hi": "ऋषि शुक्राचार्य"}]','A');
INSERT INTO knowledge_quiz VALUES(1152,'Which river is associated with Badrinath?','बद्रीनाथ किस नदी से जुड़ा है?','[{"key": "A", "en": "Alaknanda", "hi": "अलकनंदा"}, {"key": "B", "en": "Mandakini", "hi": "मंदाकिनी"}, {"key": "C", "en": "Bhagirathi", "hi": "भागीरथी"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','A');
INSERT INTO knowledge_quiz VALUES(1153,'Which object was gifted to Yudhishthira by Lord Surya to provide an inexhaustible supply of food?','भगवान सूर्य द्वारा युधिष्ठिर को भोजन की अटूट आपूर्ति प्रदान करने के लिए कौन सी वस्तु उपहार में दी गई थी?','[{"key": "A", "en": "Kamadhenu", "hi": "कामधेनु"}, {"key": "B", "en": "Akshaya Patra", "hi": "अक्षय पात्र"}, {"key": "C", "en": "Chintamani", "hi": "चिंतामणि"}, {"key": "D", "en": "Kalpavriksha", "hi": "कल्पवृक्ष"}]','B');
INSERT INTO knowledge_quiz VALUES(1154,'Aruna, the charioteer of the Sun, is the brother of which mythical bird?','सूर्य के सारथी अरुण, किस पौराणिक पक्षी के भाई हैं?','[{"key": "A", "en": "Jatayu", "hi": "जटायु"}, {"key": "B", "en": "Garuda", "hi": "गरुड़"}, {"key": "C", "en": "Sampati", "hi": "सम्पाती"}, {"key": "D", "en": "Hamsa", "hi": "हंस"}]','B');
INSERT INTO knowledge_quiz VALUES(1155,'Which scripture is composed by Sage Valmiki?','ऋषि वाल्मीकि द्वारा रचित ग्रंथ कौन सा है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Upanishads", "hi": "उपनिषद"}]','A');
INSERT INTO knowledge_quiz VALUES(1156,'Which festival celebrates the return of Lord Rama to Ayodhya?','भगवान राम के अयोध्या लौटने का पर्व कौन सा है?','[{"key": "A", "en": "Diwali", "hi": "दीपावली"}, {"key": "B", "en": "Dussehra", "hi": "दशहरा"}, {"key": "C", "en": "Rama Navami", "hi": "राम नवमी"}, {"key": "D", "en": "Holi", "hi": "होली"}]','A');
INSERT INTO knowledge_quiz VALUES(1157,'Which of these is the correct sequence of the Chota Char Dham yatra (traditionally)?','छोटा चार धाम यात्रा का सही क्रम (पारंपरिक रूप से) इनमें से कौन सा है?','[{"key": "A", "en": "Yamunotri - Gangotri - Kedarnath - Badrinath", "hi": "यमुनोत्री - गंगोत्री - केदारनाथ - बद्रीनाथ"}, {"key": "B", "en": "Badrinath - Kedarnath - Gangotri - Yamunotri", "hi": "बद्रीनाथ - केदारनाथ - गंगोत्री - यमुनोत्री"}, {"key": "C", "en": "Gangotri - Yamunotri - Badrinath - Kedarnath", "hi": "गंगोत्री - यमुनोत्री - बद्रीनाथ - केदारनाथ"}, {"key": "D", "en": "Kedarnath - Badrinath - Yamunotri - Gangotri", "hi": "केदारनाथ - बद्रीनाथ - यमुनोत्री - गंगोत्री"}]','A');
INSERT INTO knowledge_quiz VALUES(1158,'Which mantra is dedicated to the Sun God?','सूर्य देव को समर्पित मंत्र कौन सा है?','[{"key": "A", "en": "Gayatri Mantra", "hi": "गायत्री मंत्र"}, {"key": "B", "en": "Mahamrityunjaya Mantra", "hi": "महामृत्युंजय मंत्र"}, {"key": "C", "en": "Shanti Mantra", "hi": "शांति मंत्र"}, {"key": "D", "en": "Beej Mantra", "hi": "बीज मंत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1159,'Which river flows near Haridwar?','हरिद्वार के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Alaknanda", "hi": "अलकनंदा"}, {"key": "D", "en": "Sarayu", "hi": "सरयू"}]','A');
INSERT INTO knowledge_quiz VALUES(1160,'Which deity in Hindu mythology is believed to have a limp?','हिंदू पौराणिक कथाओं में किस देवता की चाल में लंगड़ाहट है?','[{"key": "A", "en": "Surya", "hi": "सूर्य"}, {"key": "B", "en": "Shani", "hi": "शनि"}, {"key": "C", "en": "Yama", "hi": "यम"}, {"key": "D", "en": "Kubera", "hi": "कुबेर"}]','B');
