INSERT INTO knowledge_quiz VALUES(1163,'Which scripture explains the concept of Atman?','आत्मा की अवधारणा किस ग्रंथ में समझाई गई है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "C", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "D", "en": "Brahmanas", "hi": "ब्राह्मण"}]','A');
INSERT INTO knowledge_quiz VALUES(1164,'Which demon was killed by Lord Krishna in Vrindavan?','वृंदावन में भगवान कृष्ण ने किस असुर का वध किया?','[{"key": "A", "en": "Putana", "hi": "पूतना"}, {"key": "B", "en": "Kamsa", "hi": "कंस"}, {"key": "C", "en": "Chanura", "hi": "चानूर"}, {"key": "D", "en": "Mushtika", "hi": "मुश्टिक"}]','A');
INSERT INTO knowledge_quiz VALUES(1165,'Which sacred city is known as the city of liberation?','मोक्ष की नगरी किसे कहा जाता है?','[{"key": "A", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "B", "en": "Haridwar", "hi": "हरिद्वार"}, {"key": "C", "en": "Prayagraj", "hi": "प्रयागराज"}, {"key": "D", "en": "Ujjain", "hi": "उज्जैन"}]','A');
INSERT INTO knowledge_quiz VALUES(1166,'Which vow is observed during Karva Chauth?','करवा चौथ में कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "For husband''s long life", "hi": "पति की दीर्घायु हेतु"}, {"key": "B", "en": "For wealth", "hi": "धन हेतु"}, {"key": "C", "en": "For children", "hi": "संतान हेतु"}, {"key": "D", "en": "For health", "hi": "स्वास्थ्य हेतु"}]','A');
INSERT INTO knowledge_quiz VALUES(1167,'Which deity is worshipped as the god of rain?','वर्षा के देवता कौन माने जाते हैं?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Varuna", "hi": "वरुण"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Vayu", "hi": "वायु"}]','A');
INSERT INTO knowledge_quiz VALUES(1168,'Which Chalisa is recited to seek the protection of the ''Commander of the Devas'' and the son of Shiva and Parvati?','''देवताओं के सेनापति'' और शिव-पार्वती के पुत्र की सुरक्षा पाने के लिए किस चालीसा का पाठ किया जाता है?','[{"key": "A", "en": "Ganesh Chalisa", "hi": "गणेश चालीसा"}, {"key": "B", "en": "Kartikeya Chalisa", "hi": "कार्तिकेय चालीसा"}, {"key": "C", "en": "Bhairav Chalisa", "hi": "भैरव चालीसा"}, {"key": "D", "en": "Hanuman Chalisa", "hi": "हनुमान चालीसा"}]','B');
INSERT INTO knowledge_quiz VALUES(1169,'Which goddess is worshipped during Chaitra Navratri?','चैत्र नवरात्रि में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Kali", "hi": "काली"}]','A');
INSERT INTO knowledge_quiz VALUES(1170,'Which scripture is known as Vedanta?','वेदांत किसे कहा जाता है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Brahmanas", "hi": "ब्राह्मण"}, {"key": "C", "en": "Aranyakas", "hi": "आरण्यक"}, {"key": "D", "en": "Smritis", "hi": "स्मृति"}]','A');
INSERT INTO knowledge_quiz VALUES(1171,'Which famous deity rescued Shani Dev from the prison of Ravana in Lanka?','किस प्रसिद्ध देवता ने लंका में रावण के कारागार से शनि देव को मुक्त कराया था?','[{"key": "A", "en": "Lord Rama", "hi": "भगवान राम"}, {"key": "B", "en": "Lord Hanuman", "hi": "भगवान हनुमान"}, {"key": "C", "en": "Vibhishana", "hi": "विभीषण"}, {"key": "D", "en": "Angad", "hi": "अंगद"}]','B');
INSERT INTO knowledge_quiz VALUES(1172,'Which river flows near Varanasi?','वाराणसी के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Ghaghara", "hi": "घाघरा"}, {"key": "D", "en": "Son", "hi": "सोन"}]','A');
INSERT INTO knowledge_quiz VALUES(1173,'Which goddess is worshipped as the embodiment of power?','शक्ति के स्वरूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Shakti", "hi": "शक्ति"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(1174,'Which demon was killed by Lord Rama at Lanka?','लंका में भगवान राम ने किसका वध किया?','[{"key": "A", "en": "Ravana", "hi": "रावण"}, {"key": "B", "en": "Kumbhakarna", "hi": "कुंभकर्ण"}, {"key": "C", "en": "Indrajit", "hi": "इंद्रजीत"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1175,'Which sacred place is associated with Lord Krishna’s kingdom?','भगवान कृष्ण के राज्य से कौन सा नगर जुड़ा है?','[{"key": "A", "en": "Dwarka", "hi": "द्वारका"}, {"key": "B", "en": "Mathura", "hi": "मथुरा"}, {"key": "C", "en": "Vrindavan", "hi": "वृंदावन"}, {"key": "D", "en": "Kurukshetra", "hi": "कुरुक्षेत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1176,'Which sacred thread is offered to male deities or worn by devotees during puja?','पूजा के दौरान पुरुष देवताओं को कौन सा पवित्र धागा अर्पित किया जाता है या भक्तों द्वारा धारण किया जाता है?','[{"key": "A", "en": "Kalava", "hi": "कलावा"}, {"key": "B", "en": "Janeu (Yagnopavit)", "hi": "जनेऊ (यज्ञोपवीत)"}, {"key": "C", "en": "Rakhi", "hi": "राखी"}, {"key": "D", "en": "Mangalsutra", "hi": "मंगलसूत्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1177,'Which deity is worshipped as the god of water?','जल के देवता कौन माने जाते हैं?','[{"key": "A", "en": "Varuna", "hi": "वरुण"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Vayu", "hi": "वायु"}]','A');
INSERT INTO knowledge_quiz VALUES(1178,'Which temple in Maharashtra is considered one of the ''Shakti Peethas'' and is situated on a cliff with 510 steps?','महाराष्ट्र का कौन सा मंदिर ''शक्तिपीठों'' में से एक माना जाता है और 510 सीढ़ियों वाली एक चट्टान पर स्थित है?','[{"key": "A", "en": "Saptashrungi Devi", "hi": "सप्तशृंगी देवी"}, {"key": "B", "en": "Ekvira Devi", "hi": "एकवीरा देवी"}, {"key": "C", "en": "Renuka Devi", "hi": "रेणुका देवी"}, {"key": "D", "en": "Yogeshwari Devi", "hi": "योगेश्वरी देवी"}]','A');
INSERT INTO knowledge_quiz VALUES(1179,'Which goddess is worshipped during Sharad Navratri?','शारद नवरात्रि में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Kali", "hi": "काली"}]','A');
INSERT INTO knowledge_quiz VALUES(1180,'Which scripture explains the law of Karma?','कर्म सिद्धांत की व्याख्या किस ग्रंथ में है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "C", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "D", "en": "Brahmanas", "hi": "ब्राह्मण"}]','A');
INSERT INTO knowledge_quiz VALUES(1181,'Goddess Meenakshi is considered an avatar of which Hindu deity?','देवी मीनाक्षी को किस हिंदू देवी का अवतार माना जाता है?','[{"key": "A", "en": "Goddess Lakshmi", "hi": "देवी लक्ष्मी"}, {"key": "B", "en": "Goddess Saraswati", "hi": "देवी सरस्वती"}, {"key": "C", "en": "Goddess Parvati", "hi": "देवी पार्वती"}, {"key": "D", "en": "Goddess Kali", "hi": "देवी काली"}]','C');
INSERT INTO knowledge_quiz VALUES(1182,'Which river flows near Prayagraj?','प्रयागराज के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1183,'Which goddess is worshipped as the giver of knowledge?','ज्ञान प्रदान करने वाली देवी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','A');
INSERT INTO knowledge_quiz VALUES(1184,'Which demon was killed by Goddess Kali?','देवी काली ने किस असुर का वध किया?','[{"key": "A", "en": "Raktabija", "hi": "रक्तबीज"}, {"key": "B", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "C", "en": "Shumbha", "hi": "शुंभ"}, {"key": "D", "en": "Nishumbha", "hi": "निशुंभ"}]','A');
INSERT INTO knowledge_quiz VALUES(1185,'Which sacred city is associated with Lord Shiva as Mahakal?','महाकाल रूप में भगवान शिव से कौन सा नगर जुड़ा है?','[{"key": "A", "en": "Ujjain", "hi": "उज्जैन"}, {"key": "B", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "C", "en": "Somnath", "hi": "सोमनाथ"}, {"key": "D", "en": "Kedarnath", "hi": "केदारनाथ"}]','A');
INSERT INTO knowledge_quiz VALUES(1186,'The ''Malinithan'' temple ruins, dedicated to Goddess Durga, feature classical Odisha style architecture. In which district is it located?','देवी दुर्गा को समर्पित ''मालिनीथान'' मंदिर के अवशेषों में शास्त्रीय ओडिशा शैली की वास्तुकला है। यह किस जिले में स्थित है?','[{"key": "A", "en": "Tawang", "hi": "तवांग"}, {"key": "B", "en": "Lower Siang", "hi": "लोअर सियांग"}, {"key": "C", "en": "Lohit", "hi": "लोहित"}, {"key": "D", "en": "Papum Pare", "hi": "पापुम पारे"}]','B');
INSERT INTO knowledge_quiz VALUES(1187,'Which deity is worshipped as the god of death?','मृत्यु के देवता कौन हैं?','[{"key": "A", "en": "Yama", "hi": "यम"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','A');
INSERT INTO knowledge_quiz VALUES(1188,'Which river is known as the lifeline of Bihar?','बिहार की जीवनरेखा किस नदी को कहा जाता है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Kosi", "hi": "कोसी"}, {"key": "C", "en": "Son", "hi": "सोन"}, {"key": "D", "en": "Gandak", "hi": "गंडक"}]','A');
INSERT INTO knowledge_quiz VALUES(1189,'Which goddess is worshipped as the universal mother?','विश्व माता के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Adi Shakti", "hi": "आदि शक्ति"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(1190,'Which scripture summarizes the teachings of Krishna to Arjuna?','कृष्ण द्वारा अर्जुन को दी गई शिक्षाओं का सार किस ग्रंथ में है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "C", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "D", "en": "Harivamsa", "hi": "हरिवंश"}]','A');
INSERT INTO knowledge_quiz VALUES(1191,'Which temple is famous for its ''Palpayasam'' (sweet milk porridge) offered as a main Prasadam?','कौन सा मंदिर मुख्य प्रसाद के रूप में दिए जाने वाले ''पालपायसम'' (मीठी दूध की खीर) के लिए प्रसिद्ध है?','[{"key": "A", "en": "Ambalappuzha Sri Krishna Temple", "hi": "अम्बलप्पुझा श्री कृष्ण मंदिर"}, {"key": "B", "en": "Mannarasala Sree Nagaraja", "hi": "मन्नारसाला श्री नागराज"}, {"key": "C", "en": "Thirunelli Temple", "hi": "तिरुनेल्ली मंदिर"}, {"key": "D", "en": "Kadampuzha Devi", "hi": "कदम्पुझा देवी"}]','A');
INSERT INTO knowledge_quiz VALUES(1192,'Which river flows near Rameswaram?','रामेश्वरम के पास कौन सी नदी बहती है?','[{"key": "A", "en": "No major river", "hi": "कोई प्रमुख नदी नहीं"}, {"key": "B", "en": "Kaveri", "hi": "कावेरी"}, {"key": "C", "en": "Vaigai", "hi": "वैगई"}, {"key": "D", "en": "Tamiraparani", "hi": "ताम्रपर्णी"}]','A');
INSERT INTO knowledge_quiz VALUES(1193,'Which goddess is worshipped during Kali Puja?','काली पूजा में किस देवी की पूजा होती है?','[{"key": "A", "en": "Kali", "hi": "काली"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(1194,'Which body part fell at the Chinnamasta Temple in Rajrappa?','रजरप्पा के छिन्नमस्तिका मंदिर में शरीर का कौन सा भाग गिरा था?','[{"key": "A", "en": "Neck", "hi": "गर्दन"}, {"key": "B", "en": "Right Shoulder", "hi": "दाहिना कंधा"}, {"key": "C", "en": "Spine", "hi": "रीढ़ की हड्डी"}, {"key": "D", "en": "None", "hi": "कोई नहीं"}]','B');
INSERT INTO knowledge_quiz VALUES(1195,'The Gommateshwara statue, the largest free-standing monolithic statue in the world, is located at which pilgrimage site?','गोमतेश्वर की मूर्ति, जो दुनिया की सबसे बड़ी मुक्त खड़ी अखंड मूर्ति है, किस तीर्थ स्थल पर स्थित है?','[{"key": "A", "en": "Badami", "hi": "बादामी"}, {"key": "B", "en": "Shravanabelagola", "hi": "श्रवणबेलगोला"}, {"key": "C", "en": "Pattadakal", "hi": "पट्टदकल"}, {"key": "D", "en": "Aihole", "hi": "ऐहोल"}]','B');
INSERT INTO knowledge_quiz VALUES(1196,'Which ritual is performed during Pitru Paksha?','पितृ पक्ष में कौन सा कर्म किया जाता है?','[{"key": "A", "en": "Shraddha", "hi": "श्राद्ध"}, {"key": "B", "en": "Japa", "hi": "जप"}, {"key": "C", "en": "Homa", "hi": "होम"}, {"key": "D", "en": "Abhisheka", "hi": "अभिषेक"}]','A');
INSERT INTO knowledge_quiz VALUES(1197,'Which deity is worshipped as the lord of wealth?','धन के देवता कौन माने जाते हैं?','[{"key": "A", "en": "Kubera", "hi": "कुबेर"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','A');
INSERT INTO knowledge_quiz VALUES(1198,'Who are the 60,000 tiny sages who travel in front of Surya''s horses to protect the world from excessive heat?','वे 60,000 नन्हे ऋषि कौन हैं जो दुनिया को अत्यधिक गर्मी से बचाने के लिए सूर्य के घोड़ों के आगे चलते हैं?','[{"key": "A", "en": "Saptarishis", "hi": "सप्तऋषि"}, {"key": "B", "en": "Valakhilyas", "hi": "बालखिल्य"}, {"key": "C", "en": "Gandharvas", "hi": "गंधर्व"}, {"key": "D", "en": "Maruts", "hi": "मरुत"}]','B');
INSERT INTO knowledge_quiz VALUES(1199,'According to legend, who laid the foundation of the Kedarnath temple?','किंवदंती के अनुसार, किसने केदारनाथ मंदिर की नींव रखी थी?','[{"key": "A", "en": "Kauravas", "hi": "कौरव"}, {"key": "B", "en": "Rama", "hi": "राम"}, {"key": "C", "en": "Hanuman", "hi": "हनुमान"}, {"key": "D", "en": "Pandavas", "hi": "पांडव"}]','D');
INSERT INTO knowledge_quiz VALUES(1200,'Which scripture is considered the essence of all scriptures?','सभी शास्त्रों का सार किसे माना जाता है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "C", "en": "Vedas", "hi": "वेद"}, {"key": "D", "en": "Puranas", "hi": "पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(1201,'Where is the winter seat (Utsav Murti) of Lord Kedarnath kept when the main temple closes?','जब मुख्य मंदिर बंद हो जाता है, तो भगवान केदारनाथ की शीतकालीन गद्दी (उत्सव मूर्ति) कहाँ रखी जाती है?','[{"key": "A", "en": "Joshimath", "hi": "जोशीमठ"}, {"key": "B", "en": "Ukhimath", "hi": "ऊखीमठ"}, {"key": "C", "en": "Mukhba", "hi": "मुखबा"}, {"key": "D", "en": "Kharsali", "hi": "खरसाली"}]','B');
INSERT INTO knowledge_quiz VALUES(1202,'Surya''s chariot is said to move along which mountain range encircling the earth?','कहा जाता है कि सूर्य का रथ पृथ्वी को घेरे हुए किस पर्वत श्रृंखला के साथ चलता है?','[{"key": "A", "en": "Himalayas", "hi": "हिमालय"}, {"key": "B", "en": "Lokaloka Mountain", "hi": "लोकालोक पर्वत"}, {"key": "C", "en": "Vindhyas", "hi": "विंध्य"}, {"key": "D", "en": "Mount Meru", "hi": "मेरु पर्वत"}]','B');
INSERT INTO knowledge_quiz VALUES(1203,'The Koodal Azhagar Temple in Madurai is unique because it depicts Lord Vishnu in which three postures?','मदुरै का कूडल अझगर मंदिर अद्वितीय है क्योंकि यह भगवान विष्णु को किन तीन मुद्राओं में दर्शाता है?','[{"key": "A", "en": "Sitting, Standing, Reclining", "hi": "बैठे हुए, खड़े हुए, शयन मुद्रा"}, {"key": "B", "en": "Dancing, Sleeping, Walking", "hi": "नृत्य, निद्रा, चलते हुए"}, {"key": "C", "en": "Child, Youth, Old age", "hi": "बाल, युवा, वृद्धावस्था"}, {"key": "D", "en": "Warrior, Priest, King", "hi": "योद्धा, पुजारी, राजा"}]','A');
INSERT INTO knowledge_quiz VALUES(1204,'Who was the only sister of the Kauravas in the Mahabharata?','महाभारत में कौरवों की इकलौती बहन कौन थी?','[{"key": "A", "en": "Duhsala", "hi": "दुश्शला"}, {"key": "B", "en": "Madhavi", "hi": "माधवी"}, {"key": "C", "en": "Subhadra", "hi": "सुभद्रा"}, {"key": "D", "en": "Ulupi", "hi": "उलूपी"}]','A');
INSERT INTO knowledge_quiz VALUES(1205,'Which scripture is attributed to Sage Vyasa?','ऋषि व्यास से संबंधित ग्रंथ कौन सा है?','[{"key": "A", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "B", "en": "Ramayana", "hi": "रामायण"}, {"key": "C", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "D", "en": "Arthashastra", "hi": "अर्थशास्त्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1206,'Which ancient temple in Sri Lanka is believed to house the sacred tooth relic of Gautama Buddha?','श्रीलंका के किस प्राचीन मंदिर में गौतम बुद्ध का पवित्र दंत अवशेष रखा माना जाता है?','[{"key": "A", "en": "Temple of the Sacred Tooth Relic", "hi": "पवित्र दंत अवशेष मंदिर"}, {"key": "B", "en": "Gangaramaya Temple", "hi": "गंगारामय मंदिर"}, {"key": "C", "en": "Dambulla Cave Temple", "hi": "दाम्बुला गुफा मंदिर"}, {"key": "D", "en": "Koneswaram Temple", "hi": "कोणेश्वरम मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(1207,'Which temple is believed to have remained submerged under snow for nearly 400 years during a ''mini ice age''?','माना जाता है कि कौन सा मंदिर ''लघु हिमयुग'' के दौरान लगभग 400 वर्षों तक बर्फ के नीचे दबा रहा?','[{"key": "A", "en": "Tungnath", "hi": "तुंगनाथ"}, {"key": "B", "en": "Kedarnath", "hi": "केदारनाथ"}, {"key": "C", "en": "Madmaheshwar", "hi": "मदमहेश्वर"}, {"key": "D", "en": "Kalpeshwar", "hi": "कल्पेश्वर"}]','B');
INSERT INTO knowledge_quiz VALUES(1208,'Which mantra is known as the great death-conquering mantra?','महामृत्युंजय मंत्र किसे कहा जाता है?','[{"key": "A", "en": "Mahamrityunjaya Mantra", "hi": "महामृत्युंजय मंत्र"}, {"key": "B", "en": "Gayatri Mantra", "hi": "गायत्री मंत्र"}, {"key": "C", "en": "Shanti Mantra", "hi": "शांति मंत्र"}, {"key": "D", "en": "Beej Mantra", "hi": "बीज मंत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1209,'Which river flows near Mathura?','मथुरा के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','A');
INSERT INTO knowledge_quiz VALUES(1210,'Which deity is worshipped during Ganesh Chaturthi?','गणेश चतुर्थी में किस देवता की पूजा होती है?','[{"key": "A", "en": "Ganesha", "hi": "गणेश"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','A');
INSERT INTO knowledge_quiz VALUES(1211,'Which Purana narrates the story of Prahlada?','प्रह्लाद की कथा किस पुराण में है?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Agni Purana", "hi": "अग्नि पुराण"}, {"key": "C", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "D", "en": "Vayu Purana", "hi": "वायु पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(1212,'Which goddess is worshipped as the river Ganga?','गंगा नदी को किस देवी के रूप में पूजा जाता है?','[{"key": "A", "en": "Bhagirathi", "hi": "भागीरथी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(1213,'Which scripture explains Bhakti Yoga?','भक्ति योग की व्याख्या किस ग्रंथ में है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "C", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "D", "en": "Manusmriti", "hi": "मनुस्मृति"}]','A');
INSERT INTO knowledge_quiz VALUES(1214,'Which demon was killed by Lord Vishnu as Narasimha?','नरसिंह अवतार में भगवान विष्णु ने किसका वध किया?','[{"key": "A", "en": "Hiranyakashipu", "hi": "हिरण्यकश्यप"}, {"key": "B", "en": "Hiranyaksha", "hi": "हिरण्याक्ष"}, {"key": "C", "en": "Bali", "hi": "बलि"}, {"key": "D", "en": "Ravana", "hi": "रावण"}]','A');
INSERT INTO knowledge_quiz VALUES(1215,'The ''Bateshwar Temples'' near Agra are a complex of 101 temples dedicated to which deity?','आगरा के पास ''बटेश्वर मंदिर'' 101 मंदिरों का एक समूह है जो किस देवता को समर्पित है?','[{"key": "A", "en": "Lord Vishnu", "hi": "भगवान विष्णु"}, {"key": "B", "en": "Lord Shiva", "hi": "भगवान शिव"}, {"key": "C", "en": "Lord Surya", "hi": "भगवान सूर्य"}, {"key": "D", "en": "Lord Brahma", "hi": "भगवान ब्रह्मा"}]','B');
INSERT INTO knowledge_quiz VALUES(1216,'Which vow is observed during Navratri?','नवरात्रि में कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Devi worship", "hi": "देवी उपासना"}, {"key": "B", "en": "Vishnu worship", "hi": "विष्णु उपासना"}, {"key": "C", "en": "Surya worship", "hi": "सूर्य उपासना"}, {"key": "D", "en": "Ganesha worship", "hi": "गणेश उपासना"}]','A');
INSERT INTO knowledge_quiz VALUES(1217,'Which deity is worshipped as the god of fire?','अग्नि के देवता कौन माने जाते हैं?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Vayu", "hi": "वायु"}]','A');
INSERT INTO knowledge_quiz VALUES(1218,'Which river is associated with Rameswaram?','रामेश्वरम किस नदी से जुड़ा है?','[{"key": "A", "en": "No major river", "hi": "कोई प्रमुख नदी नहीं"}, {"key": "B", "en": "Kaveri", "hi": "कावेरी"}, {"key": "C", "en": "Vaigai", "hi": "वैगई"}, {"key": "D", "en": "Tamiraparani", "hi": "ताम्रपर्णी"}]','A');
INSERT INTO knowledge_quiz VALUES(1219,'Which goddess is worshipped as the consort of Shiva?','शिव की पत्नी के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','A');
INSERT INTO knowledge_quiz VALUES(1220,'Which scripture discusses the four Purusharthas?','चार पुरुषार्थों की चर्चा किस ग्रंथ में है?','[{"key": "A", "en": "Dharma Shastras", "hi": "धर्मशास्त्र"}, {"key": "B", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "C", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "D", "en": "Charaka Samhita", "hi": "चरक संहिता"}]','A');
INSERT INTO knowledge_quiz VALUES(1221,'White flowers are primarily offered to which goddess of wisdom?','सफेद फूल, मुख्य रूप से ज्ञान की किस देवी को अर्पित किए जाते हैं?','[{"key": "A", "en": "Goddess Lakshmi", "hi": "देवी लक्ष्मी"}, {"key": "B", "en": "Goddess Saraswati", "hi": "देवी सरस्वती"}, {"key": "C", "en": "Goddess Parvati", "hi": "देवी पार्वती"}, {"key": "D", "en": "Goddess Kali", "hi": "देवी काली"}]','B');
INSERT INTO knowledge_quiz VALUES(1222,'Which river flows near Kurukshetra?','कुरुक्षेत्र के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','A');
INSERT INTO knowledge_quiz VALUES(1223,'Which goddess is worshipped during Lakshmi Puja?','लक्ष्मी पूजा में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Kali", "hi": "काली"}]','A');
INSERT INTO knowledge_quiz VALUES(1224,'Which demon was killed by Goddess Durga?','देवी दुर्गा ने किस असुर का वध किया?','[{"key": "A", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "B", "en": "Raktabija", "hi": "रक्तबीज"}, {"key": "C", "en": "Shumbha", "hi": "शुंभ"}, {"key": "D", "en": "Nishumbha", "hi": "निशुंभ"}]','A');
INSERT INTO knowledge_quiz VALUES(1225,'Which sacred place is associated with Lord Rama’s exile?','भगवान राम के वनवास से कौन सा स्थल जुड़ा है?','[{"key": "A", "en": "Chitrakoot", "hi": "चित्रकूट"}, {"key": "B", "en": "Ayodhya", "hi": "अयोध्या"}, {"key": "C", "en": "Mathura", "hi": "मथुरा"}, {"key": "D", "en": "Dwarka", "hi": "द्वारका"}]','A');
INSERT INTO knowledge_quiz VALUES(1226,'According to tradition, which of these flowers should not be offered to Lord Ganesha?','परंपरा के अनुसार, इनमें से कौन सा फूल भगवान गणेश को अर्पित नहीं करना चाहिए?','[{"key": "A", "en": "Red Rose", "hi": "लाल गुलाब"}, {"key": "B", "en": "Hibiscus", "hi": "गुड़हल"}, {"key": "C", "en": "Tulsi (Basil) flowers/leaves", "hi": "तुलसी के फूल/पत्ते"}, {"key": "D", "en": "Marigold", "hi": "गेंदा"}]','C');
INSERT INTO knowledge_quiz VALUES(1227,'Which deity is worshipped as the god of wind?','वायु के देवता कौन माने जाते हैं?','[{"key": "A", "en": "Vayu", "hi": "वायु"}, {"key": "B", "en": "Agni", "hi": "अग्नि"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','A');
INSERT INTO knowledge_quiz VALUES(1228,'Which river is associated with Amarkantak?','अमरकंटक किस नदी से जुड़ा है?','[{"key": "A", "en": "Narmada", "hi": "नर्मदा"}, {"key": "B", "en": "Tapi", "hi": "तापी"}, {"key": "C", "en": "Godavari", "hi": "गोदावरी"}, {"key": "D", "en": "Mahanadi", "hi": "महानदी"}]','A');
INSERT INTO knowledge_quiz VALUES(1229,'Which goddess is worshipped as the embodiment of knowledge?','ज्ञान के स्वरूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(1230,'Which scripture lays down rules of conduct and law?','आचार और कानून के नियम किस ग्रंथ में हैं?','[{"key": "A", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Yoga Sutra", "hi": "योगसूत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1231,'Which deity is worshipped in Badrinath Temple?','बद्रीनाथ मंदिर में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','A');
INSERT INTO knowledge_quiz VALUES(1232,'In the context of Aarti, what is ''Niranjan''?','आरती के संदर्भ में, ''निरंजन'' क्या है?','[{"key": "A", "en": "A type of sweet", "hi": "एक प्रकार की मिठाई"}, {"key": "B", "en": "The first lamp lit without a wick", "hi": "बिना बत्ती के जलाया गया पहला दीप (शुद्ध ज्योति)"}, {"key": "C", "en": "A musical instrument", "hi": "एक वाद्य यंत्र"}, {"key": "D", "en": "A sacred thread", "hi": "एक पवित्र धागा"}]','B');
INSERT INTO knowledge_quiz VALUES(1233,'The ''Shri Suktam'', often recited as an Aarti or hymn for Lakshmi, is found in which Veda?','देवी लक्ष्मी के लिए आरती या स्तोत्र के रूप में गाया जाने वाला ''श्री सूक्त'' किस वेद में मिलता है?','[{"key": "A", "en": "Samaveda", "hi": "सामवेद"}, {"key": "B", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "C", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','B');
INSERT INTO knowledge_quiz VALUES(1234,'At the Sugandha Shakti Peetha in Bangladesh, which part of Sati fell?','बांग्लादेश के सुगंधा शक्तिपीठ में सती का कौन सा अंग गिरा था?','[{"key": "A", "en": "Nose", "hi": "नासिका (नाक)"}, {"key": "B", "en": "Ears", "hi": "कान"}, {"key": "C", "en": "Chin", "hi": "ठोड़ी"}, {"key": "D", "en": "Teeth", "hi": "दांत"}]','A');
INSERT INTO knowledge_quiz VALUES(1235,'Which sacred place is associated with the Kumbh Mela at the confluence?','संगम पर लगने वाला कुंभ मेला किस स्थान से जुड़ा है?','[{"key": "A", "en": "Prayagraj", "hi": "प्रयागराज"}, {"key": "B", "en": "Haridwar", "hi": "हरिद्वार"}, {"key": "C", "en": "Ujjain", "hi": "उज्जैन"}, {"key": "D", "en": "Nashik", "hi": "नासिक"}]','A');
INSERT INTO knowledge_quiz VALUES(1236,'The ritual of ''Prana Pratishtha'' is performed to accomplish what?','''प्राण प्रतिष्ठा'' की रस्म क्या संपन्न करने के लिए की जाती है?','[{"key": "A", "en": "Concluding the puja", "hi": "पूजा का समापन"}, {"key": "B", "en": "Infusing life force into the idol", "hi": "मूर्ति में प्राण शक्ति का संचार करना"}, {"key": "C", "en": "Cleaning the temple", "hi": "मंदिर की सफाई"}, {"key": "D", "en": "Preparing the prasad", "hi": "प्रसाद तैयार करना"}]','B');
INSERT INTO knowledge_quiz VALUES(1237,'Which deity is worshipped as the god of justice?','न्याय के देवता कौन माने जाते हैं?','[{"key": "A", "en": "Yama", "hi": "यम"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','A');
INSERT INTO knowledge_quiz VALUES(1238,'Which river is associated with Kedarnath?','केदारनाथ किस नदी से जुड़ा है?','[{"key": "A", "en": "Mandakini", "hi": "मंदाकिनी"}, {"key": "B", "en": "Alaknanda", "hi": "अलकनंदा"}, {"key": "C", "en": "Bhagirathi", "hi": "भागीरथी"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','A');
INSERT INTO knowledge_quiz VALUES(1239,'Which goddess is worshipped as the divine mother?','दिव्य माता के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Adi Shakti", "hi": "आदि शक्ति"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(1240,'Which scripture is regarded as the fifth Veda?','पंचम वेद किसे माना जाता है?','[{"key": "A", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "B", "en": "Ramayana", "hi": "रामायण"}, {"key": "C", "en": "Puranas", "hi": "पुराण"}, {"key": "D", "en": "Upanishads", "hi": "उपनिषद"}]','A');
INSERT INTO knowledge_quiz VALUES(1241,'Which deity is worshipped in Rameswaram Temple?','रामेश्वरम मंदिर में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','A');
INSERT INTO knowledge_quiz VALUES(1242,'What is the name of the first and most important Theertham where pilgrims take a holy dip in Rameswaram?','उस पहले और सबसे महत्वपूर्ण तीर्थम का नाम क्या है जहाँ तीर्थयात्री रामेश्वरम में पवित्र डुबकी लगाते हैं?','[{"key": "A", "en": "Agni Theertham", "hi": "अग्नि तीर्थम"}, {"key": "B", "en": "Lakshmana Theertham", "hi": "लक्ष्मण तीर्थम"}, {"key": "C", "en": "Rama Theertham", "hi": "राम तीर्थम"}, {"key": "D", "en": "Jata Theertham", "hi": "जटा तीर्थम"}]','A');
INSERT INTO knowledge_quiz VALUES(1243,'Which goddess is worshipped during Durga Puja?','दुर्गा पूजा में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Kali", "hi": "काली"}]','A');
INSERT INTO knowledge_quiz VALUES(1244,'Which demon was killed by Lord Rama?','भगवान राम ने किस राक्षस का वध किया?','[{"key": "A", "en": "Ravana", "hi": "रावण"}, {"key": "B", "en": "Maricha", "hi": "मारीच"}, {"key": "C", "en": "Khara", "hi": "खर"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1245,'The Karni Mata Temple in Deshnoke is world-famous for being the home of thousands of which sacred animals?','देशनोक का करणी माता मंदिर हजारों किन पवित्र जानवरों का घर होने के लिए विश्व प्रसिद्ध है?','[{"key": "A", "en": "Monkeys", "hi": "बंदर"}, {"key": "B", "en": "Rats (Kabas)", "hi": "चूहे (काबा)"}, {"key": "C", "en": "Cows", "hi": "गाएं"}, {"key": "D", "en": "Peacocks", "hi": "मोर"}]','B');
INSERT INTO knowledge_quiz VALUES(1246,'Which ritual is performed during Pitru Paksha?','पितृ पक्ष में कौन सा कर्म किया जाता है?','[{"key": "A", "en": "Shraddha", "hi": "श्राद्ध"}, {"key": "B", "en": "Japa", "hi": "जप"}, {"key": "C", "en": "Homa", "hi": "होम"}, {"key": "D", "en": "Abhisheka", "hi": "अभिषेक"}]','A');
INSERT INTO knowledge_quiz VALUES(1247,'Which deity is worshipped as the god of wealth?','धन के देवता कौन माने जाते हैं?','[{"key": "A", "en": "Kubera", "hi": "कुबेर"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','A');
INSERT INTO knowledge_quiz VALUES(1248,'The seven horses of Surya are said to be yoked to the chariot using what as reins?','सूर्य के सात घोड़ों को रथ से लगाम के रूप में किसका उपयोग करके जोता गया है?','[{"key": "A", "en": "Leather straps", "hi": "चमड़े की पट्टियाँ"}, {"key": "B", "en": "Snakes", "hi": "सांप"}, {"key": "C", "en": "Golden chains", "hi": "सोने की जंजीरें"}, {"key": "D", "en": "Rays of light", "hi": "प्रकाश की किरणें"}]','B');
INSERT INTO knowledge_quiz VALUES(1249,'Which goddess is worshipped as the remover of ignorance?','अज्ञान नाशिनी देवी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(1250,'Which scripture is considered the essence of Vedantic philosophy?','वेदांत दर्शन का सार किस ग्रंथ में निहित है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Brahmanas", "hi": "ब्राह्मण"}, {"key": "C", "en": "Aranyakas", "hi": "आरण्यक"}, {"key": "D", "en": "Smritis", "hi": "स्मृति"}]','A');
INSERT INTO knowledge_quiz VALUES(1251,'Which son of Lord Krishna is considered an incarnation of the God of Love?','भगवान कृष्ण के किस पुत्र को प्रेम के देवता का अवतार माना जाता है?','[{"key": "A", "en": "Samba", "hi": "साम्ब"}, {"key": "B", "en": "Pradyumna", "hi": "प्रद्युम्न"}, {"key": "C", "en": "Aniruddha", "hi": "अनिरुद्ध"}, {"key": "D", "en": "Bhanu", "hi": "भानु"}]','B');
INSERT INTO knowledge_quiz VALUES(1252,'Which Veda is primarily concerned with melodies and chants?','कौन सा वेद मुख्य रूप से संगीत और गायन से संबंधित है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "C", "en": "Samaveda", "hi": "सामवेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','C');
INSERT INTO knowledge_quiz VALUES(1253,'The idol of Lord Badrinath is made of which stone?','भगवान बद्रीनाथ की मूर्ति किस पत्थर से बनी है?','[{"key": "A", "en": "Marble", "hi": "संगमरमर"}, {"key": "B", "en": "Shaligram (Black Stone)", "hi": "शालिग्राम (काला पत्थर)"}, {"key": "C", "en": "Granite", "hi": "ग्रेनाइट"}, {"key": "D", "en": "Sandstone", "hi": "बलुआ पत्थर"}]','B');
INSERT INTO knowledge_quiz VALUES(1254,'Which sacred text is a dialogue between Krishna and Arjuna?','कौन सा पवित्र ग्रंथ श्रीकृष्ण और अर्जुन के संवाद के रूप में है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "D", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}]','C');
INSERT INTO knowledge_quiz VALUES(1255,'Who was the wife of King Janaka?','राजा जनक की पत्नी कौन थीं?','[{"key": "A", "en": "Sunaina", "hi": "सुनैना"}, {"key": "B", "en": "Kaushalya", "hi": "कौशल्या"}, {"key": "C", "en": "Mandavi", "hi": "मांडवी"}, {"key": "D", "en": "Urmila", "hi": "उर्मिला"}]','A');
INSERT INTO knowledge_quiz VALUES(1256,'Which festival celebrates the victory of Lord Rama over Ravana?','भगवान राम की रावण पर विजय का उत्सव कौन सा है?','[{"key": "A", "en": "Diwali", "hi": "दीपावली"}, {"key": "B", "en": "Holi", "hi": "होली"}, {"key": "C", "en": "Dussehra", "hi": "दशहरा"}, {"key": "D", "en": "Navratri", "hi": "नवरात्रि"}]','C');
INSERT INTO knowledge_quiz VALUES(1257,'Which river flows near the city of Ayodhya?','अयोध्या नगर के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','C');
INSERT INTO knowledge_quiz VALUES(1258,'Which world-famous unique ritual is performed every morning at the Mahakaleshwar temple?','महाकालेश्वर मंदिर में प्रतिदिन सुबह कौन सा विश्व प्रसिद्ध अनूठा अनुष्ठान किया जाता है?','[{"key": "A", "en": "Panchamrut Snan", "hi": "पंचामृत स्नान"}, {"key": "B", "en": "Bhasma Aarti", "hi": "भस्म आरती"}, {"key": "C", "en": "Shringar Aarti", "hi": "शृंगार आरती"}, {"key": "D", "en": "Deep Daan", "hi": "दीप दान"}]','B');
INSERT INTO knowledge_quiz VALUES(1259,'Which Purana is primarily devoted to Lord Vishnu?','कौन सा पुराण मुख्य रूप से भगवान विष्णु को समर्पित है?','[{"key": "A", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Markandeya Purana", "hi": "मार्कण्डेय पुराण"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1260,'Which weapon is associated with Lord Vishnu?','भगवान विष्णु से कौन सा आयुध जुड़ा है?','[{"key": "A", "en": "Trishula", "hi": "त्रिशूल"}, {"key": "B", "en": "Sudarshana Chakra", "hi": "सुदर्शन चक्र"}, {"key": "C", "en": "Vajra", "hi": "वज्र"}, {"key": "D", "en": "Pashupatastra", "hi": "पाशुपतास्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1261,'Who is the wife of Sage Atri, one of the Saptarishis, known for her great devotion and penance?','सप्तर्षियों में से एक, ऋषि अत्रि की पत्नी कौन हैं, जो अपनी महान भक्ति और तपस्या के लिए जानी जाती हैं?','[{"key": "A", "en": "Arundhati", "hi": "अरुंधति"}, {"key": "B", "en": "Anasuya", "hi": "अनसूया"}, {"key": "C", "en": "Ahilya", "hi": "अहिल्या"}, {"key": "D", "en": "Lopamudra", "hi": "लोपामुद्रा"}]','B');
INSERT INTO knowledge_quiz VALUES(1262,'Who was the brother of Lord Rama?','भगवान राम के भाई कौन थे?','[{"key": "A", "en": "Bharata", "hi": "भरत"}, {"key": "B", "en": "Lakshmana", "hi": "लक्ष्मण"}, {"key": "C", "en": "Shatrughna", "hi": "शत्रुघ्न"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1263,'Who was the wife of Lord Rama?','भगवान राम की पत्नी कौन थीं?','[{"key": "A", "en": "Urmila", "hi": "उर्मिला"}, {"key": "B", "en": "Mandavi", "hi": "मांडवी"}, {"key": "C", "en": "Sita", "hi": "सीता"}, {"key": "D", "en": "Sunaina", "hi": "सुनैना"}]','C');
