INSERT INTO knowledge_quiz VALUES(1270,'Who was the teacher of the Pandavas?','पांडवों के गुरु कौन थे?','[{"key": "A", "en": "Kripacharya", "hi": "कृपाचार्य"}, {"key": "B", "en": "Dronacharya", "hi": "द्रोणाचार्य"}, {"key": "C", "en": "Parashurama", "hi": "परशुराम"}, {"key": "D", "en": "Vashistha", "hi": "वशिष्ठ"}]','B');
