INSERT INTO knowledge_quiz VALUES(1273,'Who was the wife of Arjuna?','अर्जुन की पत्नी कौन थीं?','[{"key": "A", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "B", "en": "Subhadra", "hi": "सुभद्रा"}, {"key": "C", "en": "Chitrangada", "hi": "चित्रांगदा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
