INSERT INTO knowledge_quiz VALUES(1275,'Who was the son of Arjuna and Subhadra?','अर्जुन और सुभद्रा के पुत्र कौन थे?','[{"key": "A", "en": "Parikshit", "hi": "परीक्षित"}, {"key": "B", "en": "Abhimanyu", "hi": "अभिमन्यु"}, {"key": "C", "en": "Ghatotkacha", "hi": "घटोत्कच"}, {"key": "D", "en": "Iravan", "hi": "इरावन"}]','B');
INSERT INTO knowledge_quiz VALUES(1276,'Who was the wife of Bhima?','भीम की पत्नी कौन थीं?','[{"key": "A", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "B", "en": "Hidimba", "hi": "हिडिम्बा"}, {"key": "C", "en": "Uttara", "hi": "उत्तर"}, {"key": "D", "en": "Chitrangada", "hi": "चित्रांगदा"}]','B');
INSERT INTO knowledge_quiz VALUES(1277,'Who was the biological mother of the demon King Ravana?','राक्षस राज रावण की जैविक माता कौन थीं?','[{"key": "A", "en": "Tadaka", "hi": "ताड़का"}, {"key": "B", "en": "Kaikesi", "hi": "कैकसी"}, {"key": "C", "en": "Surasa", "hi": "सुरसा"}, {"key": "D", "en": "Mandodari", "hi": "मंदोदरी"}]','B');
INSERT INTO knowledge_quiz VALUES(1278,'Who was the wife of Nakula?','नकुल की पत्नी कौन थीं?','[{"key": "A", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "B", "en": "Karenumati", "hi": "कारेणुमती"}, {"key": "C", "en": "Devika", "hi": "देविका"}, {"key": "D", "en": "Subhadra", "hi": "सुभद्रा"}]','B');
INSERT INTO knowledge_quiz VALUES(1279,'Who was the wife of Sahadeva?','सहदेव की पत्नी कौन थीं?','[{"key": "A", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "B", "en": "Vijaya", "hi": "विजया"}, {"key": "C", "en": "Devika", "hi": "देविका"}, {"key": "D", "en": "Uttara", "hi": "उत्तर"}]','B');
