INSERT INTO knowledge_quiz VALUES(1281,'Who is the mother of Surya Dev?','सूर्य देव की माता कौन हैं?','[{"key": "A", "en": "Diti", "hi": "दिति"}, {"key": "B", "en": "Aditi", "hi": "अदिति"}, {"key": "C", "en": "Danu", "hi": "दनु"}, {"key": "D", "en": "Vinata", "hi": "विनता"}]','B');
INSERT INTO knowledge_quiz VALUES(1282,'Who was the wife of Pandu?','पांडु की पत्नी कौन थीं?','[{"key": "A", "en": "Kunti", "hi": "कुंती"}, {"key": "B", "en": "Madri", "hi": "माद्री"}, {"key": "C", "en": "Gandhari", "hi": "गांधारी"}, {"key": "D", "en": "Both A and B", "hi": "A और B दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(1283,'Who was the blind king of Hastinapura?','हस्तिनापुर का अंधा राजा कौन था?','[{"key": "A", "en": "Pandu", "hi": "पांडु"}, {"key": "B", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}, {"key": "C", "en": "Shantanu", "hi": "शंतनु"}, {"key": "D", "en": "Yudhishthira", "hi": "युधिष्ठिर"}]','B');
INSERT INTO knowledge_quiz VALUES(1284,'Who was the wife of Dhritarashtra?','धृतराष्ट्र की पत्नी कौन थीं?','[{"key": "A", "en": "Kunti", "hi": "कुंती"}, {"key": "B", "en": "Gandhari", "hi": "गांधारी"}, {"key": "C", "en": "Madri", "hi": "माद्री"}, {"key": "D", "en": "Satyavati", "hi": "सत्यवती"}]','B');
INSERT INTO knowledge_quiz VALUES(1285,'How many Kauravas were there?','कौरवों की संख्या कितनी थी?','[{"key": "A", "en": "99", "hi": "99"}, {"key": "B", "en": "100", "hi": "100"}, {"key": "C", "en": "101", "hi": "101"}, {"key": "D", "en": "102", "hi": "102"}]','C');
INSERT INTO knowledge_quiz VALUES(1286,'Who was the eldest Kaurava?','कौरवों में सबसे बड़ा कौन था?','[{"key": "A", "en": "Dushasana", "hi": "दुःशासन"}, {"key": "B", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "C", "en": "Vikarna", "hi": "विकर्ण"}, {"key": "D", "en": "Chitrasena", "hi": "चित्रसेन"}]','B');
INSERT INTO knowledge_quiz VALUES(1287,'Who was the wife of Duryodhana?','दुर्योधन की पत्नी कौन थीं?','[{"key": "A", "en": "Bhanumati", "hi": "भानुमती"}, {"key": "B", "en": "Gandhari", "hi": "गांधारी"}, {"key": "C", "en": "Devika", "hi": "देविका"}, {"key": "D", "en": "Subhadra", "hi": "सुभद्रा"}]','A');
INSERT INTO knowledge_quiz VALUES(1288,'Who disrobed Draupadi in the Kaurava court?','कौरव सभा में द्रौपदी का चीरहरण किसने किया?','[{"key": "A", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "B", "en": "Shakuni", "hi": "शकुनि"}, {"key": "C", "en": "Dushasana", "hi": "दुःशासन"}, {"key": "D", "en": "Karna", "hi": "कर्ण"}]','C');
INSERT INTO knowledge_quiz VALUES(1289,'Who was the maternal uncle of the Kauravas?','कौरवों का मामा कौन था?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Shakuni", "hi": "शकुनि"}, {"key": "C", "en": "Vidura", "hi": "विदुर"}, {"key": "D", "en": "Karna", "hi": "कर्ण"}]','B');
INSERT INTO knowledge_quiz VALUES(1290,'Who was the son of Karna?','कर्ण का पुत्र कौन था?','[{"key": "A", "en": "Lakshmana", "hi": "लक्ष्मण"}, {"key": "B", "en": "Vrishasena", "hi": "वृषसेन"}, {"key": "C", "en": "Satyasena", "hi": "सत्यसेन"}, {"key": "D", "en": "Sudakshina", "hi": "सुदक्षिण"}]','B');
INSERT INTO knowledge_quiz VALUES(1291,'Who was the wife of Karna?','कर्ण की पत्नी कौन थीं?','[{"key": "A", "en": "Uruvi", "hi": "उरुवी"}, {"key": "B", "en": "Bhanumati", "hi": "भानुमती"}, {"key": "C", "en": "Devika", "hi": "देविका"}, {"key": "D", "en": "Subhadra", "hi": "सुभद्रा"}]','A');
INSERT INTO knowledge_quiz VALUES(1292,'Who cursed Karna that he would forget his knowledge?','कर्ण को विद्या भूलने का श्राप किसने दिया था?','[{"key": "A", "en": "Parashurama", "hi": "परशुराम"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1293,'Who was the minister of Hastinapura known for wisdom?','हस्तिनापुर का बुद्धिमान मंत्री कौन था?','[{"key": "A", "en": "Bhishma", "hi": "भीष्म"}, {"key": "B", "en": "Vidura", "hi": "विदुर"}, {"key": "C", "en": "Drona", "hi": "द्रोण"}, {"key": "D", "en": "Kripa", "hi": "कृप"}]','B');
INSERT INTO knowledge_quiz VALUES(1294,'Mahakaleshwar is the only one among the 12 Jyotirlingas to face which direction?','12 ज्योतिर्लिंगों में महाकालेश्वर एकमात्र ज्योतिर्लिंग है जिसका मुख किस दिशा की ओर है?','[{"key": "A", "en": "East", "hi": "पूर्व"}, {"key": "B", "en": "North", "hi": "उत्तर"}, {"key": "C", "en": "South (Dakshinamurti)", "hi": "दक्षिण (दक्षिणामूर्ति)"}, {"key": "D", "en": "West", "hi": "पश्चिम"}]','C');
INSERT INTO knowledge_quiz VALUES(1295,'Who was the king of Indraprastha?','इंद्रप्रस्थ का राजा कौन था?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "D", "en": "Nakula", "hi": "नकुल"}]','C');
INSERT INTO knowledge_quiz VALUES(1296,'Who built the Maya Sabha?','मय सभा का निर्माण किसने किया था?','[{"key": "A", "en": "Vishwakarma", "hi": "विश्वकर्मा"}, {"key": "B", "en": "Maya Danava", "hi": "मय दानव"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','B');
INSERT INTO knowledge_quiz VALUES(1297,'Who lost everything in the game of dice?','जुए के खेल में सब कुछ किसने हार दिया?','[{"key": "A", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "B", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "C", "en": "Bhima", "hi": "भीम"}, {"key": "D", "en": "Arjuna", "hi": "अर्जुन"}]','B');
INSERT INTO knowledge_quiz VALUES(1298,'How many years did the Pandavas spend in exile?','पांडवों ने कितने वर्षों का वनवास भोगा?','[{"key": "A", "en": "12 years", "hi": "12 वर्ष"}, {"key": "B", "en": "13 years", "hi": "13 वर्ष"}, {"key": "C", "en": "14 years", "hi": "14 वर्ष"}, {"key": "D", "en": "15 years", "hi": "15 वर्ष"}]','B');
INSERT INTO knowledge_quiz VALUES(1299,'Which was the final year of the Pandavas'' exile called?','पांडवों के वनवास का अंतिम वर्ष क्या कहलाता है?','[{"key": "A", "en": "Agnyatavasa", "hi": "अज्ञातवास"}, {"key": "B", "en": "Tapovana", "hi": "तपोवन"}, {"key": "C", "en": "Aranyavasa", "hi": "आरण्यवास"}, {"key": "D", "en": "Vanavasa", "hi": "वनवास"}]','A');
INSERT INTO knowledge_quiz VALUES(1300,'Which yuga is the present age according to Hindu belief?','हिंदू मान्यता के अनुसार वर्तमान युग कौन सा है?','[{"key": "A", "en": "Satya Yuga", "hi": "सत्य युग"}, {"key": "B", "en": "Treta Yuga", "hi": "त्रेता युग"}, {"key": "C", "en": "Dvapara Yuga", "hi": "द्वापर युग"}, {"key": "D", "en": "Kali Yuga", "hi": "कलियुग"}]','D');
INSERT INTO knowledge_quiz VALUES(1301,'Who was the author of the original Sanskrit Ramayana?','संस्कृत रामायण के मूल रचयिता कौन थे?','[{"key": "A", "en": "Ved Vyasa", "hi": "वेदव्यास"}, {"key": "B", "en": "Tulsidas", "hi": "तुलसीदास"}, {"key": "C", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "D", "en": "Kalidasa", "hi": "कालिदास"}]','C');
INSERT INTO knowledge_quiz VALUES(1302,'Which demon king was defeated by Goddess Durga?','देवी दुर्गा ने किस असुर राजा का वध किया था?','[{"key": "A", "en": "Shumbha", "hi": "शुम्भ"}, {"key": "B", "en": "Nishumbha", "hi": "निशुम्भ"}, {"key": "C", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "D", "en": "Bhasmasura", "hi": "भस्मासुर"}]','C');
INSERT INTO knowledge_quiz VALUES(1303,'The Attukal Pongala festival, which holds a Guinness World Record for the largest gathering of women, is celebrated in which city?','अट्टुकल पोंगाला उत्सव, जिसने महिलाओं के सबसे बड़े जमावड़े के लिए गिनीज वर्ल्ड रिकॉर्ड बनाया है, किस शहर में मनाया जाता है?','[{"key": "A", "en": "Kochi", "hi": "कोच्चि"}, {"key": "B", "en": "Thiruvananthapuram", "hi": "तिरुवनंतपुरम"}, {"key": "C", "en": "Thrissur", "hi": "त्रिशूर"}, {"key": "D", "en": "Kozhikode", "hi": "कोझिकोड"}]','B');
INSERT INTO knowledge_quiz VALUES(1304,'Which avatar of Vishnu appeared as a man-lion?','भगवान विष्णु का कौन सा अवतार नरसिंह रूप में प्रकट हुआ?','[{"key": "A", "en": "Varaha", "hi": "वराह"}, {"key": "B", "en": "Vamana", "hi": "वामन"}, {"key": "C", "en": "Narasimha", "hi": "नरसिंह"}, {"key": "D", "en": "Parashurama", "hi": "परशुराम"}]','C');
INSERT INTO knowledge_quiz VALUES(1305,'Which scripture is known as the fifth Veda?','किस ग्रंथ को पंचम वेद कहा जाता है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Ramayana", "hi": "रामायण"}, {"key": "D", "en": "Natya Shastra", "hi": "नाट्यशास्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1306,'At Mahakaleshwar, the ''Bhasma Aarti'' is a symbolic representation of what?','महाकालेश्वर में ''भस्म आरती'' अस्तित्व के किसका प्रतीकात्मक चित्रण है?','[{"key": "A", "en": "Birth and Creation", "hi": "जन्म और सृजन"}, {"key": "B", "en": "Life and Prosperity", "hi": "जीवन और समृद्धि"}, {"key": "C", "en": "Death and Regeneration", "hi": "मृत्यु और पुनर्जन्म"}, {"key": "D", "en": "Wealth and Power", "hi": "धन और शक्ति"}]','C');
INSERT INTO knowledge_quiz VALUES(1307,'Which river is associated with Lord Krishna’s childhood?','भगवान कृष्ण के बाल्यकाल से कौन सी नदी जुड़ी है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','B');
INSERT INTO knowledge_quiz VALUES(1308,'Which temple in Deoghar is one of the 12 Jyotirlingas and is famous for the Shravani Mela?','देवघर का कौन सा मंदिर 12 ज्योतिर्लिंगों में से एक है और श्रावणी मेले के लिए प्रसिद्ध है?','[{"key": "A", "en": "Baidyanath Dham", "hi": "बैद्यनाथ धाम"}, {"key": "B", "en": "Ajgaibinath", "hi": "अजगैबीनाथ"}, {"key": "C", "en": "Basukinath", "hi": "बासुकीनाथ"}, {"key": "D", "en": "Hariharnath", "hi": "हरिहरनाथ"}]','A');
INSERT INTO knowledge_quiz VALUES(1309,'Which weapon is carried by Goddess Durga?','देवी दुर्गा के हाथ में कौन सा शस्त्र होता है?','[{"key": "A", "en": "Bow", "hi": "धनुष"}, {"key": "B", "en": "Trishula", "hi": "त्रिशूल"}, {"key": "C", "en": "Chakra", "hi": "चक्र"}, {"key": "D", "en": "Vajra", "hi": "वज्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1310,'Who was the wife of Lord Shiva?','भगवान शिव की पत्नी कौन हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','C');
INSERT INTO knowledge_quiz VALUES(1311,'Which epic narrates the story of the Kurukshetra war?','कुरुक्षेत्र युद्ध की कथा किस महाकाव्य में वर्णित है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Harivamsa", "hi": "हरिवंश"}, {"key": "D", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1312,'Who is known as the god of wisdom?','ज्ञान के देवता किसे कहा जाता है?','[{"key": "A", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','B');
INSERT INTO knowledge_quiz VALUES(1313,'Which Purana narrates the stories of Lord Krishna in detail?','भगवान कृष्ण की कथाओं का विस्तृत वर्णन किस पुराण में है?','[{"key": "A", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "B", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "C", "en": "Brahma Purana", "hi": "ब्रह्म पुराण"}, {"key": "D", "en": "Skanda Purana", "hi": "स्कंद पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1314,'Which yajna did King Janamejaya perform?','राजा जनमेजय ने कौन सा यज्ञ किया था?','[{"key": "A", "en": "Ashwamedha Yajna", "hi": "अश्वमेध यज्ञ"}, {"key": "B", "en": "Rajasuya Yajna", "hi": "राजसूय यज्ञ"}, {"key": "C", "en": "Sarpa Satra", "hi": "सर्पसत्र"}, {"key": "D", "en": "Vajapeya Yajna", "hi": "वाजपेय यज्ञ"}]','C');
INSERT INTO knowledge_quiz VALUES(1315,'Which sage cursed King Yayati?','राजा ययाति को किस ऋषि ने श्राप दिया था?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Shukracharya", "hi": "शुक्राचार्य"}, {"key": "C", "en": "Angiras", "hi": "अंगिरस"}, {"key": "D", "en": "Bhrigu", "hi": "भृगु"}]','B');
INSERT INTO knowledge_quiz VALUES(1316,'What was the name of the powerful bow used by Lord Vishnu, similar to Shiva''s Pinaka?','भगवान विष्णु द्वारा उपयोग किए जाने वाले शक्तिशाली धनुष का नाम क्या था, जो शिव के पिनाक के समान था?','[{"key": "A", "en": "Gandiva", "hi": "गांडीव"}, {"key": "B", "en": "Sharanga", "hi": "शारंग"}, {"key": "C", "en": "Vijaya", "hi": "विजय"}, {"key": "D", "en": "Ajagava", "hi": "अजगावा"}]','B');
INSERT INTO knowledge_quiz VALUES(1317,'What vow is Bhishma famous for?','भीष्म किस प्रतिज्ञा के लिए प्रसिद्ध हैं?','[{"key": "A", "en": "Truthfulness", "hi": "सत्यनिष्ठा"}, {"key": "B", "en": "Celibacy", "hi": "ब्रह्मचर्य"}, {"key": "C", "en": "Non-violence", "hi": "अहिंसा"}, {"key": "D", "en": "Silence", "hi": "मौन"}]','B');
INSERT INTO knowledge_quiz VALUES(1318,'Who granted Bhishma the boon of choosing the time of his death?','भीष्म को इच्छामृत्यु का वरदान किसने दिया?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Shantanu", "hi": "शंतनु"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Parashurama", "hi": "परशुराम"}]','B');
INSERT INTO knowledge_quiz VALUES(1319,'Who was the mother of Bhishma?','भीष्म की माता कौन थीं?','[{"key": "A", "en": "Satyavati", "hi": "सत्यवती"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Amba", "hi": "अंबा"}, {"key": "D", "en": "Ambika", "hi": "अंबिका"}]','B');
INSERT INTO knowledge_quiz VALUES(1320,'Who was the teacher of Bhishma?','भीष्म के गुरु कौन थे?','[{"key": "A", "en": "Dronacharya", "hi": "द्रोणाचार्य"}, {"key": "B", "en": "Parashurama", "hi": "परशुराम"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Kripacharya", "hi": "कृपाचार्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1321,'Who was the father of Dronacharya?','द्रोणाचार्य के पिता कौन थे?','[{"key": "A", "en": "Bharadwaja", "hi": "भरद्वाज"}, {"key": "B", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "C", "en": "Gautama", "hi": "गौतम"}, {"key": "D", "en": "Parashara", "hi": "पराशर"}]','A');
INSERT INTO knowledge_quiz VALUES(1322,'Who was the son of Dronacharya?','द्रोणाचार्य के पुत्र कौन थे?','[{"key": "A", "en": "Kripa", "hi": "कृप"}, {"key": "B", "en": "Ashwatthama", "hi": "अश्वत्थामा"}, {"key": "C", "en": "Ekalavya", "hi": "एकलव्य"}, {"key": "D", "en": "Parikshit", "hi": "परीक्षित"}]','B');
INSERT INTO knowledge_quiz VALUES(1323,'Who was the wife of Dronacharya?','द्रोणाचार्य की पत्नी कौन थीं?','[{"key": "A", "en": "Kripi", "hi": "कृपी"}, {"key": "B", "en": "Gandhari", "hi": "गांधारी"}, {"key": "C", "en": "Madri", "hi": "माद्री"}, {"key": "D", "en": "Devika", "hi": "देविका"}]','A');
INSERT INTO knowledge_quiz VALUES(1324,'Who killed Dronacharya in the Kurukshetra war?','कुरुक्षेत्र युद्ध में द्रोणाचार्य का वध किसने किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Dhrishtadyumna", "hi": "धृष्टद्युम्न"}, {"key": "C", "en": "Bhima", "hi": "भीम"}, {"key": "D", "en": "Krishna", "hi": "कृष्ण"}]','B');
INSERT INTO knowledge_quiz VALUES(1325,'Who was Ekalavya?','एकलव्य कौन था?','[{"key": "A", "en": "Prince of Hastinapura", "hi": "हस्तिनापुर का राजकुमार"}, {"key": "B", "en": "Disciple of Drona", "hi": "द्रोण का शिष्य"}, {"key": "C", "en": "King of Magadha", "hi": "मगध का राजा"}, {"key": "D", "en": "Son of Shantanu", "hi": "शंतनु का पुत्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1326,'Which finger did Ekalavya offer as guru dakshina?','एकलव्य ने गुरु दक्षिणा में कौन सी उंगली अर्पित की?','[{"key": "A", "en": "Index finger", "hi": "तर्जनी"}, {"key": "B", "en": "Middle finger", "hi": "मध्यमा"}, {"key": "C", "en": "Thumb", "hi": "अंगूठा"}, {"key": "D", "en": "Little finger", "hi": "कनिष्ठा"}]','C');
INSERT INTO knowledge_quiz VALUES(1327,'Who was the commander of the Pandava army on the first day?','पहले दिन पांडव सेना का सेनापति कौन था?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Dhrishtadyumna", "hi": "धृष्टद्युम्न"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','B');
INSERT INTO knowledge_quiz VALUES(1328,'Who was the commander of the Kaurava army on the first day?','पहले दिन कौरव सेना का सेनापति कौन था?','[{"key": "A", "en": "Drona", "hi": "द्रोण"}, {"key": "B", "en": "Bhishma", "hi": "भीष्म"}, {"key": "C", "en": "Karna", "hi": "कर्ण"}, {"key": "D", "en": "Shalya", "hi": "शल्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1329,'How many days did the Kurukshetra war last?','कुरुक्षेत्र युद्ध कितने दिनों तक चला?','[{"key": "A", "en": "16 days", "hi": "16 दिन"}, {"key": "B", "en": "17 days", "hi": "17 दिन"}, {"key": "C", "en": "18 days", "hi": "18 दिन"}, {"key": "D", "en": "19 days", "hi": "19 दिन"}]','C');
INSERT INTO knowledge_quiz VALUES(1330,'Who killed Bhishma?','भीष्म को किसने पराजित किया?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Shikhandi", "hi": "शिखंडी"}, {"key": "D", "en": "Dhrishtadyumna", "hi": "धृष्टद्युम्न"}]','C');
INSERT INTO knowledge_quiz VALUES(1331,'Who was Shikhandi in his previous birth?','पूर्व जन्म में शिखंडी कौन था?','[{"key": "A", "en": "Amba", "hi": "अंबा"}, {"key": "B", "en": "Ambika", "hi": "अंबिका"}, {"key": "C", "en": "Ambalika", "hi": "अंबालिका"}, {"key": "D", "en": "Satyavati", "hi": "सत्यवती"}]','A');
INSERT INTO knowledge_quiz VALUES(1332,'Who was the commander of the Kaurava army after Bhishma?','भीष्म के बाद कौरव सेना का सेनापति कौन बना?','[{"key": "A", "en": "Karna", "hi": "कर्ण"}, {"key": "B", "en": "Drona", "hi": "द्रोण"}, {"key": "C", "en": "Shalya", "hi": "शल्य"}, {"key": "D", "en": "Ashwatthama", "hi": "अश्वत्थामा"}]','B');
INSERT INTO knowledge_quiz VALUES(1333,'Who became the commander after Dronacharya?','द्रोणाचार्य के बाद सेनापति कौन बना?','[{"key": "A", "en": "Karna", "hi": "कर्ण"}, {"key": "B", "en": "Ashwatthama", "hi": "अश्वत्थामा"}, {"key": "C", "en": "Shalya", "hi": "शल्य"}, {"key": "D", "en": "Kripa", "hi": "कृप"}]','A');
INSERT INTO knowledge_quiz VALUES(1334,'Who killed Karna?','कर्ण का वध किसने किया?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','C');
INSERT INTO knowledge_quiz VALUES(1335,'Who was the final commander of the Kaurava army?','कौरव सेना का अंतिम सेनापति कौन था?','[{"key": "A", "en": "Karna", "hi": "कर्ण"}, {"key": "B", "en": "Ashwatthama", "hi": "अश्वत्थामा"}, {"key": "C", "en": "Shalya", "hi": "शल्य"}, {"key": "D", "en": "Kripa", "hi": "कृप"}]','C');
INSERT INTO knowledge_quiz VALUES(1336,'Who killed Shalya?','शल्य का वध किसने किया?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Nakula", "hi": "नकुल"}, {"key": "C", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "D", "en": "Arjuna", "hi": "अर्जुन"}]','C');
INSERT INTO knowledge_quiz VALUES(1337,'Who killed Duryodhana?','दुर्योधन का वध किसने किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Nakula", "hi": "नकुल"}, {"key": "D", "en": "Sahadeva", "hi": "सहदेव"}]','B');
INSERT INTO knowledge_quiz VALUES(1338,'Which fruit did Lord Ganesha win in the contest with Kartikeya?','कार्तिकेय के साथ प्रतियोगिता में भगवान गणेश ने कौन सा फल जीता?','[{"key": "A", "en": "Gnanapazham/Jnana Palam", "hi": "ज्ञानपलम"}, {"key": "B", "en": "Amrita Fruit", "hi": "अमृत फल"}, {"key": "C", "en": "Kalpavriksha Fruit", "hi": "कल्पवृक्ष फल"}, {"key": "D", "en": "Divya Pomegranate", "hi": "दिव्य अनार"}]','A');
INSERT INTO knowledge_quiz VALUES(1339,'Who survived from the Kaurava side after the war?','युद्ध के बाद कौरव पक्ष से कौन जीवित बचे?','[{"key": "A", "en": "Karna", "hi": "कर्ण"}, {"key": "B", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "C", "en": "Ashwatthama", "hi": "अश्वत्थामा"}, {"key": "D", "en": "Shakuni", "hi": "शकुनि"}]','C');
INSERT INTO knowledge_quiz VALUES(1340,'Who crowned Yudhishthira as king after the war?','युद्ध के बाद युधिष्ठिर का राज्याभिषेक किसने किया?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Bhishma", "hi": "भीष्म"}, {"key": "D", "en": "Narada", "hi": "नारद"}]','C');
INSERT INTO knowledge_quiz VALUES(1341,'Which sacrifice did Yudhishthira perform after becoming king?','राजा बनने के बाद युधिष्ठिर ने कौन सा यज्ञ किया?','[{"key": "A", "en": "Rajasuya", "hi": "राजसूय"}, {"key": "B", "en": "Ashwamedha", "hi": "अश्वमेध"}, {"key": "C", "en": "Somayajna", "hi": "सोमयज्ञ"}, {"key": "D", "en": "Vajapeya", "hi": "वाजपेय"}]','B');
INSERT INTO knowledge_quiz VALUES(1342,'Who was the grandson of Arjuna?','अर्जुन के पौत्र कौन थे?','[{"key": "A", "en": "Abhimanyu", "hi": "अभिमन्यु"}, {"key": "B", "en": "Parikshit", "hi": "परीक्षित"}, {"key": "C", "en": "Janamejaya", "hi": "जनमेजय"}, {"key": "D", "en": "Uttara", "hi": "उत्तर"}]','B');
INSERT INTO knowledge_quiz VALUES(1343,'Who was the son of Parikshit?','परीक्षित के पुत्र कौन थे?','[{"key": "A", "en": "Janamejaya", "hi": "जनमेजय"}, {"key": "B", "en": "Abhimanyu", "hi": "अभिमन्यु"}, {"key": "C", "en": "Uttara", "hi": "उत्तर"}, {"key": "D", "en": "Takshaka", "hi": "तक्षक"}]','A');
INSERT INTO knowledge_quiz VALUES(1344,'Who narrated the Mahabharata to King Janamejaya?','राजा जनमेजय को महाभारत किसने सुनाई?','[{"key": "A", "en": "Ved Vyasa", "hi": "वेदव्यास"}, {"key": "B", "en": "Vaishampayana", "hi": "वैशंपायन"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Lomasha", "hi": "लोमश"}]','B');
INSERT INTO knowledge_quiz VALUES(1345,'Which serpent king killed Parikshit?','किस नागराज ने परीक्षित की मृत्यु की?','[{"key": "A", "en": "Vasuki", "hi": "वासुकी"}, {"key": "B", "en": "Takshaka", "hi": "तक्षक"}, {"key": "C", "en": "Ananta", "hi": "अनंत"}, {"key": "D", "en": "Kaliya", "hi": "कालिया"}]','B');
INSERT INTO knowledge_quiz VALUES(1346,'Which yajna did Janamejaya perform to destroy snakes?','सर्पों के विनाश के लिए जनमेजय ने कौन सा यज्ञ किया?','[{"key": "A", "en": "Ashwamedha Yajna", "hi": "अश्वमेध यज्ञ"}, {"key": "B", "en": "Sarpa Satra", "hi": "सर्प सत्र"}, {"key": "C", "en": "Rajasuya Yajna", "hi": "राजसूय यज्ञ"}, {"key": "D", "en": "Somayajna", "hi": "सोमयज्ञ"}]','B');
INSERT INTO knowledge_quiz VALUES(1347,'Who stopped Janamejaya’s Sarpa Satra?','जनमेजय के सर्प सत्र को किसने रोका?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Astika", "hi": "आस्तिक"}, {"key": "C", "en": "Vyasa", "hi": "व्यास"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1348,'Who was Astika?','आस्तिक कौन थे?','[{"key": "A", "en": "Son of Jaratkaru and Manasa", "hi": "जरत्कारु और मनसा के पुत्र"}, {"key": "B", "en": "Son of Parikshit", "hi": "परीक्षित के पुत्र"}, {"key": "C", "en": "Son of Janamejaya", "hi": "जनमेजय के पुत्र"}, {"key": "D", "en": "Disciple of Vyasa", "hi": "व्यास के शिष्य"}]','A');
INSERT INTO knowledge_quiz VALUES(1349,'Which sage cursed King Parikshit?','किस ऋषि ने राजा परीक्षित को श्राप दिया?','[{"key": "A", "en": "Durvasa", "hi": "दुर्वासा"}, {"key": "B", "en": "Shringi", "hi": "श्रृंगी"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Narada", "hi": "नारद"}]','B');
INSERT INTO knowledge_quiz VALUES(1350,'Which epic contains the story of Janamejaya?','जनमेजय की कथा किस महाकाव्य में है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Harivamsa", "hi": "हरिवंश"}, {"key": "D", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1351,'Who is called the mother of the Adityas?','आदित्यों की माता किसे कहा जाता है?','[{"key": "A", "en": "Diti", "hi": "दिति"}, {"key": "B", "en": "Aditi", "hi": "अदिति"}, {"key": "C", "en": "Danu", "hi": "दनु"}, {"key": "D", "en": "Vinata", "hi": "विनता"}]','B');
INSERT INTO knowledge_quiz VALUES(1352,'Which demon was killed by Lord Krishna during his childhood?','भगवान कृष्ण ने अपने बाल्यकाल में किस असुर का वध किया था?','[{"key": "A", "en": "Hiranyakashipu", "hi": "हिरण्यकशिपु"}, {"key": "B", "en": "Putana", "hi": "पूतना"}, {"key": "C", "en": "Ravana", "hi": "रावण"}, {"key": "D", "en": "Bhasmasura", "hi": "भस्मासुर"}]','B');
INSERT INTO knowledge_quiz VALUES(1353,'Which serpent does Lord Vishnu rest upon?','भगवान विष्णु किस नाग पर शयन करते हैं?','[{"key": "A", "en": "Vasuki", "hi": "वासुकी"}, {"key": "B", "en": "Takshaka", "hi": "तक्षक"}, {"key": "C", "en": "Ananta Shesha", "hi": "अनंत शेष"}, {"key": "D", "en": "Kaliya", "hi": "कालिया"}]','C');
INSERT INTO knowledge_quiz VALUES(1354,'Which river is considered the daughter of the Himalayas?','किस नदी को हिमालय की पुत्री माना जाता है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','A');
INSERT INTO knowledge_quiz VALUES(1355,'Which goddess is worshipped during Navratri?','नवरात्रि में किस देवी की पूजा की जाती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','C');
INSERT INTO knowledge_quiz VALUES(1356,'Which sage is known as the father of Ayurveda?','आयुर्वेद के जनक के रूप में किस ऋषि को जाना जाता है?','[{"key": "A", "en": "Charaka", "hi": "चरक"}, {"key": "B", "en": "Sushruta", "hi": "सुश्रुत"}, {"key": "C", "en": "Dhanvantari", "hi": "धन्वंतरि"}, {"key": "D", "en": "Kapila", "hi": "कपिल"}]','C');
INSERT INTO knowledge_quiz VALUES(1357,'Which avatar of Vishnu rescued the Earth from the ocean?','भगवान विष्णु के किस अवतार ने पृथ्वी को समुद्र से बाहर निकाला?','[{"key": "A", "en": "Matsya", "hi": "मत्स्य"}, {"key": "B", "en": "Kurma", "hi": "कूर्म"}, {"key": "C", "en": "Varaha", "hi": "वराह"}, {"key": "D", "en": "Vamana", "hi": "वामन"}]','C');
INSERT INTO knowledge_quiz VALUES(1358,'Which temple is known for the black idol of Lord Vishnu, often called ''Gadadhar''?','भगवान विष्णु की काली मूर्ति के लिए कौन सा मंदिर प्रसिद्ध है, जिसे अक्सर ''गदाधर'' कहा जाता है?','[{"key": "A", "en": "Shamlaji Temple", "hi": "शामलाजी मंदिर"}, {"key": "B", "en": "Sun Temple", "hi": "सूर्य मंदिर"}, {"key": "C", "en": "Sudama Temple", "hi": "सुदामा मंदिर"}, {"key": "D", "en": "Koteshwar Mahadev", "hi": "कोटेश्वर महादेव"}]','A');
INSERT INTO knowledge_quiz VALUES(1359,'Which scripture contains the Vishnu Sahasranama?','विष्णु सहस्रनाम किस ग्रंथ में है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "D", "en": "Ramayana", "hi": "रामायण"}]','B');
INSERT INTO knowledge_quiz VALUES(1360,'Which god is known as the lord of destruction?','संहार के देवता किसे कहा जाता है?','[{"key": "A", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','C');
INSERT INTO knowledge_quiz VALUES(1361,'Which ashrama is associated with Sage Valmiki?','महर्षि वाल्मीकि का आश्रम किससे संबंधित है?','[{"key": "A", "en": "Naimisharanya", "hi": "नैमिषारण्य"}, {"key": "B", "en": "Chitrakuta", "hi": "चित्रकूट"}, {"key": "C", "en": "Panchavati", "hi": "पंचवटी"}, {"key": "D", "en": "Valmiki Ashram", "hi": "वाल्मीकि आश्रम"}]','D');
INSERT INTO knowledge_quiz VALUES(1362,'Which vrata is observed for marital happiness?','वैवाहिक सुख के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "B", "en": "Karva Chauth", "hi": "करवा चौथ"}, {"key": "C", "en": "Maha Shivaratri", "hi": "महाशिवरात्रि"}, {"key": "D", "en": "Nag Panchami", "hi": "नाग पंचमी"}]','B');
INSERT INTO knowledge_quiz VALUES(1363,'Which Purana is the largest among the eighteen Mahapuranas?','अठारह महापुराणों में सबसे बड़ा पुराण कौन सा है?','[{"key": "A", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "B", "en": "Padma Purana", "hi": "पद्म पुराण"}, {"key": "C", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "D", "en": "Brahmanda Purana", "hi": "ब्रह्माण्ड पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(1364,'Which mantra is dedicated to Lord Shiva?','कौन सा मंत्र भगवान शिव को समर्पित है?','[{"key": "A", "en": "Gayatri Mantra", "hi": "गायत्री मंत्र"}, {"key": "B", "en": "Om Namah Shivaya", "hi": "ॐ नमः शिवाय"}, {"key": "C", "en": "Hare Krishna", "hi": "हरे कृष्ण"}, {"key": "D", "en": "Vishnu Sahasranama", "hi": "विष्णु सहस्रनाम"}]','B');
INSERT INTO knowledge_quiz VALUES(1365,'Which god emerged from the churning of the ocean with nectar?','समुद्र मंथन से अमृत के साथ कौन से देवता प्रकट हुए?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Dhanvantari", "hi": "धन्वंतरि"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','C');
INSERT INTO knowledge_quiz VALUES(1366,'According to the Ramayana, who was the wife of Kumbhakarna?','रामायण के अनुसार, कुंभकर्ण की पत्नी कौन थी?','[{"key": "A", "en": "Mandodari", "hi": "मंदोदरी"}, {"key": "B", "en": "Vajramala", "hi": "वज्रमाला"}, {"key": "C", "en": "Sulochana", "hi": "सुलोचना"}, {"key": "D", "en": "Trijata", "hi": "त्रिजटा"}]','B');
INSERT INTO knowledge_quiz VALUES(1367,'The river goddess Tapti is the sister of which planet?','नदी देवी ताप्ती किस ग्रह की बहन हैं?','[{"key": "A", "en": "Mangal (Mars)", "hi": "मंगल"}, {"key": "B", "en": "Shani (Saturn)", "hi": "शनि"}, {"key": "C", "en": "Budh (Mercury)", "hi": "बुध"}, {"key": "D", "en": "Brihaspati (Jupiter)", "hi": "बृहस्पति"}]','B');
INSERT INTO knowledge_quiz VALUES(1368,'Who raised Lord Krishna in Gokul?','गोकुल में भगवान कृष्ण का पालन-पोषण किसने किया?','[{"key": "A", "en": "Devaki", "hi": "देवकी"}, {"key": "B", "en": "Rohini", "hi": "रोहिणी"}, {"key": "C", "en": "Yashoda", "hi": "यशोदा"}, {"key": "D", "en": "Kunti", "hi": "कुंती"}]','C');
INSERT INTO knowledge_quiz VALUES(1369,'Who was the foster father of Lord Krishna?','भगवान कृष्ण के पालक पिता कौन थे?','[{"key": "A", "en": "Vasudeva", "hi": "वसुदेव"}, {"key": "B", "en": "Nanda", "hi": "नंद"}, {"key": "C", "en": "Ugrasena", "hi": "उग्रसेन"}, {"key": "D", "en": "Akrura", "hi": "अक्रूर"}]','B');
INSERT INTO knowledge_quiz VALUES(1370,'Which demoness tried to poison infant Krishna?','किस राक्षसी ने बालक कृष्ण को विष पिलाने का प्रयास किया?','[{"key": "A", "en": "Putana", "hi": "पूतना"}, {"key": "B", "en": "Trijata", "hi": "त्रिजटा"}, {"key": "C", "en": "Surpanakha", "hi": "शूर्पणखा"}, {"key": "D", "en": "Holika", "hi": "होलिका"}]','A');
INSERT INTO knowledge_quiz VALUES(1371,'Which serpent did Krishna subdue in the Yamuna river?','यमुना नदी में कृष्ण ने किस नाग को वश में किया?','[{"key": "A", "en": "Takshaka", "hi": "तक्षक"}, {"key": "B", "en": "Vasuki", "hi": "वासुकी"}, {"key": "C", "en": "Kaliya", "hi": "कालिया"}, {"key": "D", "en": "Ananta", "hi": "अनंत"}]','C');
INSERT INTO knowledge_quiz VALUES(1372,'Which mountain did Krishna lift to protect villagers?','गोकुलवासियों की रक्षा के लिए कृष्ण ने कौन सा पर्वत उठाया?','[{"key": "A", "en": "Mount Kailasa", "hi": "कैलास पर्वत"}, {"key": "B", "en": "Mount Mandara", "hi": "मंदराचल"}, {"key": "C", "en": "Govardhan Hill", "hi": "गोवर्धन पर्वत"}, {"key": "D", "en": "Mount Meru", "hi": "मेरु पर्वत"}]','C');
INSERT INTO knowledge_quiz VALUES(1373,'Who was Krishna''s childhood friend known for loyalty?','कृष्ण के बाल्यकाल के कौन से मित्र अपनी निष्ठा के लिए प्रसिद्ध थे?','[{"key": "A", "en": "Sudama", "hi": "सुदामा"}, {"key": "B", "en": "Akrura", "hi": "अक्रूर"}, {"key": "C", "en": "Uddhava", "hi": "उद्धव"}, {"key": "D", "en": "Balarama", "hi": "बलराम"}]','A');
INSERT INTO knowledge_quiz VALUES(1374,'Who was the elder brother of Lord Krishna?','भगवान कृष्ण के बड़े भाई कौन थे?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Balarama", "hi": "बलराम"}, {"key": "C", "en": "Shatrughna", "hi": "शत्रुघ्न"}, {"key": "D", "en": "Sahadeva", "hi": "सहदेव"}]','B');
INSERT INTO knowledge_quiz VALUES(1375,'Which weapon is associated with Balarama?','बलराम से कौन सा आयुध जुड़ा है?','[{"key": "A", "en": "Bow", "hi": "धनुष"}, {"key": "B", "en": "Mace", "hi": "गदा"}, {"key": "C", "en": "Plough", "hi": "हल"}, {"key": "D", "en": "Sword", "hi": "तलवार"}]','C');
INSERT INTO knowledge_quiz VALUES(1376,'Who sent Krishna to Mathura to confront Kamsa?','कृष्ण को कंस से सामना करने के लिए मथुरा किसने भेजा?','[{"key": "A", "en": "Nanda", "hi": "नंद"}, {"key": "B", "en": "Akrura", "hi": "अक्रूर"}, {"key": "C", "en": "Vasudeva", "hi": "वसुदेव"}, {"key": "D", "en": "Ugrasena", "hi": "उग्रसेन"}]','B');
INSERT INTO knowledge_quiz VALUES(1377,'Who was the maternal uncle of Krishna?','कृष्ण के मामा कौन थे?','[{"key": "A", "en": "Shishupala", "hi": "शिशुपाल"}, {"key": "B", "en": "Ugrasena", "hi": "उग्रसेन"}, {"key": "C", "en": "Kamsa", "hi": "कंस"}, {"key": "D", "en": "Jarandha", "hi": "जरासंध"}]','C');
INSERT INTO knowledge_quiz VALUES(1378,'After killing Kamsa, who was made king of Mathura?','कंस वध के बाद मथुरा का राजा किसे बनाया गया?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Balarama", "hi": "बलराम"}, {"key": "C", "en": "Ugrasena", "hi": "उग्रसेन"}, {"key": "D", "en": "Akrura", "hi": "अक्रूर"}]','C');
INSERT INTO knowledge_quiz VALUES(1379,'Which city did Krishna establish as his capital?','कृष्ण ने किस नगर को अपनी राजधानी बनाया?','[{"key": "A", "en": "Mathura", "hi": "मथुरा"}, {"key": "B", "en": "Indraprastha", "hi": "इंद्रप्रस्थ"}, {"key": "C", "en": "Dwarka", "hi": "द्वारका"}, {"key": "D", "en": "Hastinapura", "hi": "हस्तिनापुर"}]','C');
INSERT INTO knowledge_quiz VALUES(1380,'Who was Krishna’s principal queen?','कृष्ण की प्रमुख रानी कौन थीं?','[{"key": "A", "en": "Radha", "hi": "राधा"}, {"key": "B", "en": "Rukmini", "hi": "रुक्मिणी"}, {"key": "C", "en": "Satyabhama", "hi": "सत्यभामा"}, {"key": "D", "en": "Jambavati", "hi": "जाम्बवती"}]','B');
INSERT INTO knowledge_quiz VALUES(1381,'Who abducted Rukmini before her marriage?','रुक्मिणी का हरण किसने किया था?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Shishupala", "hi": "शिशुपाल"}, {"key": "D", "en": "Balarama", "hi": "बलराम"}]','B');
INSERT INTO knowledge_quiz VALUES(1382,'Who was the father of Rukmini?','रुक्मिणी के पिता कौन थे?','[{"key": "A", "en": "Bhishmaka", "hi": "भीष्मक"}, {"key": "B", "en": "Ugrasena", "hi": "उग्रसेन"}, {"key": "C", "en": "Jarandha", "hi": "जरासंध"}, {"key": "D", "en": "Drupada", "hi": "द्रुपद"}]','A');
INSERT INTO knowledge_quiz VALUES(1383,'Which demon king was defeated by Krishna many times?','कृष्ण ने किस असुर राजा को कई बार पराजित किया?','[{"key": "A", "en": "Banasura", "hi": "बाणासुर"}, {"key": "B", "en": "Narakasura", "hi": "नरकासुर"}, {"key": "C", "en": "Jarandha", "hi": "जरासंध"}, {"key": "D", "en": "Kalayavana", "hi": "कालयवन"}]','C');
INSERT INTO knowledge_quiz VALUES(1384,'Who ultimately killed Jarasandha?','अंततः जरासंध का वध किसने किया?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Bhima", "hi": "भीम"}, {"key": "D", "en": "Balarama", "hi": "बलराम"}]','C');
INSERT INTO knowledge_quiz VALUES(1385,'Which festival is associated with Krishna’s victory over Narakasura?','नरकासुर पर कृष्ण की विजय किस पर्व से जुड़ी है?','[{"key": "A", "en": "Holi", "hi": "होली"}, {"key": "B", "en": "Diwali", "hi": "दीपावली"}, {"key": "C", "en": "Janmashtami", "hi": "जन्माष्टमी"}, {"key": "D", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}]','B');
INSERT INTO knowledge_quiz VALUES(1386,'Who was Krishna’s close companion and messenger?','कृष्ण के निकट सहयोगी और दूत कौन थे?','[{"key": "A", "en": "Akrura", "hi": "अक्रूर"}, {"key": "B", "en": "Uddhava", "hi": "उद्धव"}, {"key": "C", "en": "Sudama", "hi": "सुदामा"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','B');
INSERT INTO knowledge_quiz VALUES(1387,'Which form did Krishna reveal in the Bhagavad Gita?','भगवद्गीता में कृष्ण ने कौन सा रूप दिखाया?','[{"key": "A", "en": "Narasimha", "hi": "नरसिंह"}, {"key": "B", "en": "Vishvarupa", "hi": "विश्व रूप"}, {"key": "C", "en": "Vamana", "hi": "वामन"}, {"key": "D", "en": "Rama", "hi": "राम"}]','B');
INSERT INTO knowledge_quiz VALUES(1388,'To whom did Krishna deliver the Bhagavad Gita?','कृष्ण ने भगवद्गीता किसे उपदेश दी?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Nakula", "hi": "नकुल"}]','C');
INSERT INTO knowledge_quiz VALUES(1389,'In which battlefield was the Bhagavad Gita spoken?','भगवद्गीता का उपदेश किस युद्धभूमि में दिया गया?','[{"key": "A", "en": "Lanka", "hi": "लंका"}, {"key": "B", "en": "Kurukshetra", "hi": "कुरुक्षेत्र"}, {"key": "C", "en": "Mathura", "hi": "मथुरा"}, {"key": "D", "en": "Dwarka", "hi": "द्वारका"}]','B');
INSERT INTO knowledge_quiz VALUES(1390,'Which path does Krishna emphasize in the Bhagavad Gita?','भगवद्गीता में कृष्ण किस मार्ग पर विशेष बल देते हैं?','[{"key": "A", "en": "Bhakti Yoga", "hi": "भक्ति योग"}, {"key": "B", "en": "Karma Yoga", "hi": "कर्म योग"}, {"key": "C", "en": "Jnana Yoga", "hi": "ज्ञान योग"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1391,'Which clan did Krishna belong to?','कृष्ण किस वंश से संबंधित थे?','[{"key": "A", "en": "Ikshvaku", "hi": "इक्ष्वाकु"}, {"key": "B", "en": "Yadu", "hi": "यदु"}, {"key": "C", "en": "Puru", "hi": "पुरु"}, {"key": "D", "en": "Bharata", "hi": "भरत"}]','B');
INSERT INTO knowledge_quiz VALUES(1392,'Who was the sage that cursed the Yadava clan?','यादव वंश को किस ऋषि ने श्राप दिया?','[{"key": "A", "en": "Durvasa", "hi": "दुर्वासा"}, {"key": "B", "en": "Narada", "hi": "नारद"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Lomasha", "hi": "लोमश"}]','A');
INSERT INTO knowledge_quiz VALUES(1393,'Where did the Yadava clan perish?','यादव वंश का विनाश कहाँ हुआ?','[{"key": "A", "en": "Dwarka", "hi": "द्वारका"}, {"key": "B", "en": "Prabhasa", "hi": "प्रभास"}, {"key": "C", "en": "Mathura", "hi": "मथुरा"}, {"key": "D", "en": "Kurukshetra", "hi": "कुरुक्षेत्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1394,'How did Lord Krishna leave his mortal body?','भगवान कृष्ण ने देह त्याग कैसे किया?','[{"key": "A", "en": "Battle wound", "hi": "युद्ध घाव"}, {"key": "B", "en": "Arrow by a hunter", "hi": "शिकारी के बाण से"}, {"key": "C", "en": "Poison", "hi": "विष से"}, {"key": "D", "en": "Fire", "hi": "अग्नि से"}]','B');
INSERT INTO knowledge_quiz VALUES(1395,'What was the name of the hunter who shot Krishna?','जिस शिकारी ने कृष्ण को बाण मारा उसका नाम क्या था?','[{"key": "A", "en": "Lubdhaka", "hi": "लुब्धक"}, {"key": "B", "en": "Jara", "hi": "जरा"}, {"key": "C", "en": "Vyadha", "hi": "व्याध"}, {"key": "D", "en": "Nishada", "hi": "निषाद"}]','B');
INSERT INTO knowledge_quiz VALUES(1396,'After Krishna’s departure, which age began?','कृष्ण के देह त्याग के बाद कौन सा युग प्रारंभ हुआ?','[{"key": "A", "en": "Dvapara Yuga", "hi": "द्वापर युग"}, {"key": "B", "en": "Treta Yuga", "hi": "त्रेता युग"}, {"key": "C", "en": "Kali Yuga", "hi": "कलियुग"}, {"key": "D", "en": "Satya Yuga", "hi": "सत्य युग"}]','C');
INSERT INTO knowledge_quiz VALUES(1397,'Which Purana primarily narrates Krishna’s life?','कृष्ण की लीलाओं का प्रमुख वर्णन किस पुराण में है?','[{"key": "A", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "B", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "C", "en": "Agni Purana", "hi": "अग्नि पुराण"}, {"key": "D", "en": "Markandeya Purana", "hi": "मार्कण्डेय पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1398,'Which devotional path is Krishna most associated with?','कृष्ण किस भक्ति मार्ग से सर्वाधिक जुड़े माने जाते हैं?','[{"key": "A", "en": "Jnana Yoga", "hi": "ज्ञान योग"}, {"key": "B", "en": "Karma Yoga", "hi": "कर्म योग"}, {"key": "C", "en": "Bhakti Yoga", "hi": "भक्ति योग"}, {"key": "D", "en": "Hatha Yoga", "hi": "हठ योग"}]','C');
INSERT INTO knowledge_quiz VALUES(1399,'Which title best describes Krishna’s role in the Mahabharata?','महाभारत में कृष्ण की भूमिका किस रूप में वर्णित है?','[{"key": "A", "en": "Warrior", "hi": "योद्धा"}, {"key": "B", "en": "King", "hi": "राजा"}, {"key": "C", "en": "Charioteer and guide", "hi": "सारथी और मार्गदर्शक"}, {"key": "D", "en": "Ascetic", "hi": "सन्यासी"}]','C');
INSERT INTO knowledge_quiz VALUES(1400,'Which divine quality is Krishna most revered for?','कृष्ण किस दिव्य गुण के लिए विशेष रूप से पूजे जाते हैं?','[{"key": "A", "en": "Power", "hi": "शक्ति"}, {"key": "B", "en": "Justice", "hi": "न्याय"}, {"key": "C", "en": "Compassion and love", "hi": "करुणा और प्रेम"}, {"key": "D", "en": "Asceticism", "hi": "तपस्या"}]','C');
INSERT INTO knowledge_quiz VALUES(1401,'Who was the foster mother of Lord Krishna?','भगवान कृष्ण की पालक माता कौन थीं?','[{"key": "A", "en": "Devaki", "hi": "देवकी"}, {"key": "B", "en": "Rohini", "hi": "रोहिणी"}, {"key": "C", "en": "Yashoda", "hi": "यशोदा"}, {"key": "D", "en": "Gandhari", "hi": "गांधारी"}]','C');
INSERT INTO knowledge_quiz VALUES(1402,'Which avatar of Vishnu appeared as a dwarf?','भगवान विष्णु का कौन सा अवतार बौने रूप में प्रकट हुआ?','[{"key": "A", "en": "Vamana", "hi": "वामन"}, {"key": "B", "en": "Parashurama", "hi": "परशुराम"}, {"key": "C", "en": "Kurma", "hi": "कूर्म"}, {"key": "D", "en": "Matsya", "hi": "मत्स्य"}]','A');
INSERT INTO knowledge_quiz VALUES(1403,'Which sage authored the Brahma Sutras?','ब्रह्म सूत्रों के रचयिता कौन हैं?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Badrayana", "hi": "बादरायण"}, {"key": "C", "en": "Shankara", "hi": "शंकराचार्य"}, {"key": "D", "en": "Kapila", "hi": "कपिल"}]','B');
INSERT INTO knowledge_quiz VALUES(1404,'Which river flows at the site of the Kumbh Mela in Prayagraj?','प्रयागराज में कुंभ मेले के स्थल पर कौन सी नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "All three", "hi": "तीनों"}]','D');
INSERT INTO knowledge_quiz VALUES(1405,'Which king performed the Rajasuya Yajna in the Mahabharata?','महाभारत में राजसूय यज्ञ किस राजा ने किया था?','[{"key": "A", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "B", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "C", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}, {"key": "D", "en": "Shantanu", "hi": "शंतनु"}]','A');
INSERT INTO knowledge_quiz VALUES(1406,'Which goddess is considered the deity of knowledge?','ज्ञान की देवी किसे माना जाता है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','C');
INSERT INTO knowledge_quiz VALUES(1407,'Which weapon did Arjuna receive from Lord Shiva?','अर्जुन को भगवान शिव से कौन सा अस्त्र प्राप्त हुआ?','[{"key": "A", "en": "Brahmastra", "hi": "ब्रह्मास्त्र"}, {"key": "B", "en": "Pashupatastra", "hi": "पाशुपतास्त्र"}, {"key": "C", "en": "Narayanastra", "hi": "नारायणास्त्र"}, {"key": "D", "en": "Agneyastra", "hi": "आग्नेयास्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1408,'Which natural substance is used to create ''Bhasma'' (sacred ash) offered to Lord Shiva?','भगवान शिव को अर्पित की जाने वाली ''भस्म'' (पवित्र राख) बनाने के लिए किस प्राकृतिक पदार्थ का उपयोग किया जाता है?','[{"key": "A", "en": "Wood Ash", "hi": "लकड़ी की राख"}, {"key": "B", "en": "Cow Dung (Dried)", "hi": "गाय का गोबर (सूखा)"}, {"key": "C", "en": "Coal", "hi": "कोयला"}, {"key": "D", "en": "Paper", "hi": "कागज"}]','B');
INSERT INTO knowledge_quiz VALUES(1409,'Which forest did the Pandavas stay in during exile?','वनवास के दौरान पांडव किस वन में रहे?','[{"key": "A", "en": "Dandakaranya", "hi": "दंडकारण्य"}, {"key": "B", "en": "Kamyaka Forest", "hi": "काम्यक वन"}, {"key": "C", "en": "Naimisharanya", "hi": "नैमिषारण्य"}, {"key": "D", "en": "Chitrakuta", "hi": "चित्रकूट"}]','B');
INSERT INTO knowledge_quiz VALUES(1410,'Which Purana describes the churning of the ocean in detail?','समुद्र मंथन का विस्तृत वर्णन किस पुराण में है?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Kurma Purana", "hi": "कूर्म पुराण"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1411,'Which chakra is associated with the heart?','हृदय से कौन सा चक्र संबंधित है?','[{"key": "A", "en": "Muladhara", "hi": "मूलाधार"}, {"key": "B", "en": "Manipura", "hi": "मणिपूर"}, {"key": "C", "en": "Anahata", "hi": "अनाहत"}, {"key": "D", "en": "Ajna", "hi": "आज्ञा"}]','C');
INSERT INTO knowledge_quiz VALUES(1412,'Which rishi is associated with the Gayatri Mantra?','गायत्री मंत्र किस ऋषि से संबंधित है?','[{"key": "A", "en": "Vishwamitra", "hi": "विश्वामित्र"}, {"key": "B", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "C", "en": "Bharadwaja", "hi": "भरद्वाज"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','A');
INSERT INTO knowledge_quiz VALUES(1413,'Which demon was slain by Lord Rama?','भगवान राम ने किस राक्षस का वध किया?','[{"key": "A", "en": "Kumbhakarna", "hi": "कुंभकर्ण"}, {"key": "B", "en": "Ravana", "hi": "रावण"}, {"key": "C", "en": "Maricha", "hi": "मारीच"}, {"key": "D", "en": "Subahu", "hi": "सुबाहु"}]','B');
INSERT INTO knowledge_quiz VALUES(1414,'Which asura was devoted to Lord Vishnu?','कौन सा असुर भगवान विष्णु का भक्त था?','[{"key": "A", "en": "Bali", "hi": "बलि"}, {"key": "B", "en": "Hiranyaksha", "hi": "हिरण्याक्ष"}, {"key": "C", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "D", "en": "Bhasmasura", "hi": "भस्मासुर"}]','A');
INSERT INTO knowledge_quiz VALUES(1415,'Which group of temples in Karnataka is known as the ''Cradle of Indian Temple Architecture''?','कर्नाटक के किस मंदिर समूह को ''भारतीय मंदिर वास्तुकला का पालना'' कहा जाता है?','[{"key": "A", "en": "Hampi", "hi": "हम्पी"}, {"key": "B", "en": "Aihole", "hi": "ऐहोल"}, {"key": "C", "en": "Banavasi", "hi": "बणवासी"}, {"key": "D", "en": "Talakadu", "hi": "तलकाडू"}]','B');
INSERT INTO knowledge_quiz VALUES(1416,'Which scripture is recited during Satyanarayana Puja?','सत्यनारायण पूजा में कौन सा ग्रंथ पढ़ा जाता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "D", "en": "Satyanarayana Katha", "hi": "सत्यनारायण कथा"}]','D');
INSERT INTO knowledge_quiz VALUES(1417,'Which Yuga follows Treta Yuga?','त्रेता युग के बाद कौन सा युग आता है?','[{"key": "A", "en": "Satya Yuga", "hi": "सत्य युग"}, {"key": "B", "en": "Dvapara Yuga", "hi": "द्वापर युग"}, {"key": "C", "en": "Kali Yuga", "hi": "कलि युग"}, {"key": "D", "en": "None", "hi": "कोई नहीं"}]','B');
INSERT INTO knowledge_quiz VALUES(1418,'The Shrinathji Temple in Nathdwara follows which Hindu sect (Sampradaya)?','नाथद्वारा का श्रीनाथजी मंदिर किस हिंदू संप्रदाय का अनुसरण करता है?','[{"key": "A", "en": "Shaivism", "hi": "शैव धर्म"}, {"key": "B", "en": "Pushtimarg", "hi": "पुष्टिमार्ग"}, {"key": "C", "en": "Smartism", "hi": "स्मार्त धर्म"}, {"key": "D", "en": "Shaktism", "hi": "शाक्त धर्म"}]','B');
INSERT INTO knowledge_quiz VALUES(1419,'Which Veda contains hymns to various deities?','किस वेद में विभिन्न देवताओं की स्तुतियाँ हैं?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Samaveda", "hi": "सामवेद"}, {"key": "C", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','A');
INSERT INTO knowledge_quiz VALUES(1420,'Which deity is worshipped in the form of a linga?','किस देवता की पूजा लिंग रूप में होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1421,'Which festival celebrates the return of Lord Rama to Ayodhya?','भगवान राम के अयोध्या लौटने का उत्सव कौन सा है?','[{"key": "A", "en": "Holi", "hi": "होली"}, {"key": "B", "en": "Diwali", "hi": "दीपावली"}, {"key": "C", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "D", "en": "Dussehra", "hi": "दशहरा"}]','B');
INSERT INTO knowledge_quiz VALUES(1422,'Which rishi is associated with the Atharvaveda?','अथर्ववेद किस ऋषि से संबंधित है?','[{"key": "A", "en": "Angiras", "hi": "अंगिरस"}, {"key": "B", "en": "Vishwamitra", "hi": "विश्वामित्र"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Bhrigu", "hi": "भृगु"}]','A');
INSERT INTO knowledge_quiz VALUES(1423,'Which god is worshipped during Surya Namaskar?','सूर्य नमस्कार में किस देवता की पूजा होती है?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','C');
INSERT INTO knowledge_quiz VALUES(1424,'Which scripture contains the story of Prahlada?','प्रह्लाद की कथा किस ग्रंथ में मिलती है?','[{"key": "A", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "B", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "C", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "D", "en": "Ramayana", "hi": "रामायण"}]','B');
INSERT INTO knowledge_quiz VALUES(1425,'Which ashrama stage follows Grihastha?','गृहस्थ आश्रम के बाद कौन सा आश्रम आता है?','[{"key": "A", "en": "Brahmacharya", "hi": "ब्रह्मचर्य"}, {"key": "B", "en": "Vanaprastha", "hi": "वानप्रस्थ"}, {"key": "C", "en": "Sannyasa", "hi": "संन्यास"}, {"key": "D", "en": "None", "hi": "कोई नहीं"}]','B');
INSERT INTO knowledge_quiz VALUES(1426,'Which temple is one of the Char Dham?','चार धाम में से कौन सा मंदिर है?','[{"key": "A", "en": "Puri", "hi": "पुरी"}, {"key": "B", "en": "Somnath", "hi": "सोमनाथ"}, {"key": "C", "en": "Kashi Vishwanath", "hi": "काशी विश्वनाथ"}, {"key": "D", "en": "Vaishno Devi", "hi": "वैष्णो देवी"}]','A');
INSERT INTO knowledge_quiz VALUES(1427,'Which deity is worshipped on Ganesh Chaturthi?','गणेश चतुर्थी पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Karttikeya", "hi": "कार्तिकेय"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','B');
INSERT INTO knowledge_quiz VALUES(1428,'Which holy site in Chitrakoot is believed to be the place where Lord Rama stayed during his 14-year exile?','चित्रकूट का कौन सा पवित्र स्थल माना जाता है कि यहाँ भगवान राम ने अपने 14 वर्ष के वनवास के दौरान निवास किया था?','[{"key": "A", "en": "Kamadgiri", "hi": "कामदगिरि"}, {"key": "B", "en": "Ram Ghat", "hi": "राम घाट"}, {"key": "C", "en": "Gupt Godavari", "hi": "गुप्त गोदावरी"}, {"key": "D", "en": "Sati Anusuya Ashram", "hi": "सती अनुसूया आश्रम"}]','A');
INSERT INTO knowledge_quiz VALUES(1429,'Which scripture is also called the Vedanta?','किस ग्रंथ को वेदांत भी कहा जाता है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Aranyakas", "hi": "आरण्यक"}, {"key": "C", "en": "Brahmanas", "hi": "ब्राह्मण"}, {"key": "D", "en": "Samhitas", "hi": "संहिता"}]','A');
INSERT INTO knowledge_quiz VALUES(1430,'Which king was the father of Bhishma?','भीष्म के पिता कौन थे?','[{"key": "A", "en": "Vichitravirya", "hi": "विचित्रवीर्य"}, {"key": "B", "en": "Shantanu", "hi": "शंतनु"}, {"key": "C", "en": "Pandu", "hi": "पांडु"}, {"key": "D", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1431,'Which goddess is associated with wealth?','धन की देवी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(1432,'Which epic contains the Bhagavad Gita?','भगवद्गीता किस महाकाव्य का भाग है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Harivamsa", "hi": "हरिवंश"}, {"key": "D", "en": "Vedas", "hi": "वेद"}]','B');
INSERT INTO knowledge_quiz VALUES(1433,'Which Saptarishi''s hermitage did Lord Rama visit in the Dandakaranya forest?','दंडकारण्य वन में भगवान राम किस सप्तर्षि के आश्रम में गए थे?','[{"key": "A", "en": "Sage Kashyapa", "hi": "ऋषि कश्यप"}, {"key": "B", "en": "Sage Atri", "hi": "ऋषि अत्रि"}, {"key": "C", "en": "Sage Bharadwaja", "hi": "ऋषि भरद्वाज"}, {"key": "D", "en": "Sage Vashistha", "hi": "ऋषि वशिष्ठ"}]','B');
INSERT INTO knowledge_quiz VALUES(1434,'The ''Panchalingas'' of Talakadu are located on the banks of which river and are often buried under sand?','तलकाडू के ''पंचलिंग'' किस नदी के तट पर स्थित हैं और अक्सर रेत के नीचे दबे रहते हैं?','[{"key": "A", "en": "Krishna", "hi": "कृष्णा"}, {"key": "B", "en": "Kaveri", "hi": "कावेरी"}, {"key": "C", "en": "Tungabhadra", "hi": "तुंगभद्रा"}, {"key": "D", "en": "Sharavati", "hi": "शरावती"}]','B');
INSERT INTO knowledge_quiz VALUES(1435,'Which mantra is known as the Mahamantra?','महामंत्र किसे कहा जाता है?','[{"key": "A", "en": "Gayatri Mantra", "hi": "गायत्री मंत्र"}, {"key": "B", "en": "Om Namah Shivaya", "hi": "ॐ नमः शिवाय"}, {"key": "C", "en": "Hare Krishna Mantra", "hi": "हरे कृष्ण मंत्र"}, {"key": "D", "en": "Mahamrityunjaya Mantra", "hi": "महामृत्युंजय मंत्र"}]','C');
INSERT INTO knowledge_quiz VALUES(1436,'Which avatar of Vishnu is yet to appear?','भगवान विष्णु का कौन सा अवतार अभी प्रकट होना है?','[{"key": "A", "en": "Kalki", "hi": "कल्कि"}, {"key": "B", "en": "Rama", "hi": "राम"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Buddha", "hi": "बुद्ध"}]','A');
INSERT INTO knowledge_quiz VALUES(1437,'At the Sabarimala temple, what is the ''Makara Jyothi'' which devotees believe to be a celestial light?','सबरीमाला मंदिर में ''मकर ज्योति'' क्या है जिसे भक्त दिव्य प्रकाश मानते हैं?','[{"key": "A", "en": "A star", "hi": "एक तारा"}, {"key": "B", "en": "A flame lit on Ponnambalamedu hill", "hi": "पोन्नम्बलमेडु पहाड़ी पर जलाई गई लौ"}, {"key": "C", "en": "A reflection of the sun", "hi": "सूर्य का प्रतिबिंब"}, {"key": "D", "en": "A lightning strike", "hi": "आकाशीय बिजली"}]','B');
INSERT INTO knowledge_quiz VALUES(1438,'The ''Vaikom Ashtami'' festival is dedicated to which form of Lord Shiva?','''वैकोम अष्टमी'' उत्सव भगवान शिव के किस रूप को समर्पित है?','[{"key": "A", "en": "Nataraja", "hi": "नटराज"}, {"key": "B", "en": "Dakshinamurthy", "hi": "दक्षिणामूर्ति"}, {"key": "C", "en": "Vaikkathappan (Annadana Prabhu)", "hi": "वैकोमथप्पन (अन्नदान प्रभु)"}, {"key": "D", "en": "Ardhanarishvara", "hi": "अर्धनारीश्वर"}]','C');
INSERT INTO knowledge_quiz VALUES(1439,'Which rishi is associated with the Ramayana?','रामायण किस ऋषि से संबंधित है?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "C", "en": "Vishwamitra", "hi": "विश्वामित्र"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1440,'Which festival marks the worship of Goddess Lakshmi?','कौन सा त्योहार देवी लक्ष्मी की पूजा से जुड़ा है?','[{"key": "A", "en": "Diwali", "hi": "दीपावली"}, {"key": "B", "en": "Holi", "hi": "होली"}, {"key": "C", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "D", "en": "Raksha Bandhan", "hi": "रक्षा बंधन"}]','A');
INSERT INTO knowledge_quiz VALUES(1441,'Which deity rides a peacock?','कौन सा देवता मोर पर सवार है?','[{"key": "A", "en": "Ganesha", "hi": "गणेश"}, {"key": "B", "en": "Karttikeya", "hi": "कार्तिकेय"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','B');
INSERT INTO knowledge_quiz VALUES(1442,'The Kanaka Durga Temple in Vijayawada is situated on which hill overlooking the Krishna River?','विजयवाड़ा में कनक दुर्गा मंदिर कृष्णा नदी के किनारे किस पहाड़ी पर स्थित है?','[{"key": "A", "en": "Indrakeeladri", "hi": "इंद्रकीलाद्री"}, {"key": "B", "en": "Ratnagiri", "hi": "रत्नागिरी"}, {"key": "C", "en": "Mangalagiri", "hi": "मंगलगीरी"}, {"key": "D", "en": "Srisailam", "hi": "श्रीशैलम"}]','A');
INSERT INTO knowledge_quiz VALUES(1443,'Which god is known as the preserver in the Trinity?','त्रिदेवों में पालनकर्ता कौन है?','[{"key": "A", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1444,'Which festival is associated with colors?','रंगों से जुड़ा त्योहार कौन सा है?','[{"key": "A", "en": "Diwali", "hi": "दीपावली"}, {"key": "B", "en": "Holi", "hi": "होली"}, {"key": "C", "en": "Dussehra", "hi": "दशहरा"}, {"key": "D", "en": "Baisakhi", "hi": "बैसाखी"}]','B');
INSERT INTO knowledge_quiz VALUES(1445,'Which river is associated with Lord Rama’s ancestry?','भगवान राम के वंश से कौन सी नदी जुड़ी है?','[{"key": "A", "en": "Sarayu", "hi": "सरयू"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','A');
INSERT INTO knowledge_quiz VALUES(1446,'Which day is considered auspicious for Lord Shiva?','भगवान शिव के लिए कौन सा दिन शुभ माना जाता है?','[{"key": "A", "en": "Monday", "hi": "सोमवार"}, {"key": "B", "en": "Tuesday", "hi": "मंगलवार"}, {"key": "C", "en": "Thursday", "hi": "गुरुवार"}, {"key": "D", "en": "Sunday", "hi": "रविवार"}]','A');
INSERT INTO knowledge_quiz VALUES(1447,'Which deity is worshipped in the form of Shaligram?','शालिग्राम रूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1448,'Which rishi is associated with the Mandukya Upanishad?','माण्डूक्य उपनिषद किस ऋषि से संबंधित है?','[{"key": "A", "en": "Gaudapada", "hi": "गौड़पाद"}, {"key": "B", "en": "Shankara", "hi": "शंकराचार्य"}, {"key": "C", "en": "Badrayana", "hi": "बादरायण"}, {"key": "D", "en": "Vyasa", "hi": "व्यास"}]','A');
INSERT INTO knowledge_quiz VALUES(1449,'Which city is known as the gateway to Badrinath?','बद्रीनाथ का प्रवेश द्वार कौन सा नगर है?','[{"key": "A", "en": "Joshimath", "hi": "जोशीमठ"}, {"key": "B", "en": "Rishikesh", "hi": "ऋषिकेश"}, {"key": "C", "en": "Haridwar", "hi": "हरिद्वार"}, {"key": "D", "en": "Uttarkashi", "hi": "उत्तरकाशी"}]','A');
INSERT INTO knowledge_quiz VALUES(1450,'Who is traditionally credited with consolidating the Panch Kedar pilgrimage circuit?','पारंपरिक रूप से पंच केदार तीर्थयात्रा सर्किट को व्यवस्थित करने का श्रेय किसे दिया जाता है?','[{"key": "A", "en": "Ramanujacharya", "hi": "रामानुजाचार्य"}, {"key": "B", "en": "Adi Shankaracharya", "hi": "आदि शंकराचार्य"}, {"key": "C", "en": "Madhvacharya", "hi": "माध्वाचार्य"}, {"key": "D", "en": "Swami Vivekananda", "hi": "स्वामी विवेकानंद"}]','B');
INSERT INTO knowledge_quiz VALUES(1451,'Who was the teacher of the Pandavas and Kauravas?','पांडवों और कौरवों के गुरु कौन थे?','[{"key": "A", "en": "Kripacharya", "hi": "कृपाचार्य"}, {"key": "B", "en": "Parashurama", "hi": "परशुराम"}, {"key": "C", "en": "Dronacharya", "hi": "द्रोणाचार्य"}, {"key": "D", "en": "Vashistha", "hi": "वशिष्ठ"}]','C');
INSERT INTO knowledge_quiz VALUES(1452,'Which river flows near the city of Mathura?','मथुरा नगर के पास कौन सी नदी बहती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','B');
INSERT INTO knowledge_quiz VALUES(1453,'Which Vedic deity is associated with fire?','कौन सा वैदिक देवता अग्नि से संबंधित है?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Varuna", "hi": "वरुण"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Vayu", "hi": "वायु"}]','C');
INSERT INTO knowledge_quiz VALUES(1454,'Which festival marks the worship of Goddess Saraswati?','देवी सरस्वती की पूजा किस पर्व पर की जाती है?','[{"key": "A", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "B", "en": "Vasant Panchami", "hi": "वसंत पंचमी"}, {"key": "C", "en": "Diwali", "hi": "दीपावली"}, {"key": "D", "en": "Holi", "hi": "होली"}]','B');
INSERT INTO knowledge_quiz VALUES(1455,'Which Purana narrates the legends of Lord Shiva?','भगवान शिव की कथाएँ किस पुराण में वर्णित हैं?','[{"key": "A", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "B", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "C", "en": "Padma Purana", "hi": "पद्म पुराण"}, {"key": "D", "en": "Brahma Purana", "hi": "ब्रह्म पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1456,'At the Chamundeshwari Temple in Mysore, which part of Sati fell?','मैसूर के चामुंडेश्वरी मंदिर में सती का कौन सा अंग गिरा था?','[{"key": "A", "en": "Hair", "hi": "बाल"}, {"key": "B", "en": "Ears", "hi": "कान"}, {"key": "C", "en": "Right Hand", "hi": "दायां हाथ"}, {"key": "D", "en": "Chest", "hi": "छाती"}]','A');
INSERT INTO knowledge_quiz VALUES(1457,'Which 11th-century temple in Bhubaneswar is dedicated to Lord Shiva as ''Harihara'' (half Shiva, half Vishnu)?','भुवनेश्वर में 11वीं शताब्दी का कौन सा मंदिर भगवान शिव को ''हरिहर'' (आधे शिव, आधे विष्णु) के रूप में समर्पित है?','[{"key": "A", "en": "Rajarani Temple", "hi": "राजाराणी मंदिर"}, {"key": "B", "en": "Lingaraj Temple", "hi": "लिंगराज मंदिर"}, {"key": "C", "en": "Brahmeswara Temple", "hi": "ब्रह्मेश्वर मंदिर"}, {"key": "D", "en": "Vaital Deula", "hi": "वैताल देउला"}]','B');
INSERT INTO knowledge_quiz VALUES(1458,'Which Upanishad begins with the mantra ''Om Purnamadah Purnamidam''?','‘ॐ पूर्णमदः पूर्णमिदम्’ मंत्र किस उपनिषद से संबंधित है?','[{"key": "A", "en": "Kena Upanishad", "hi": "केन उपनिषद"}, {"key": "B", "en": "Isha Upanishad", "hi": "ईश उपनिषद"}, {"key": "C", "en": "Katha Upanishad", "hi": "कठ उपनिषद"}, {"key": "D", "en": "Mundaka Upanishad", "hi": "मुण्डक उपनिषद"}]','B');
INSERT INTO knowledge_quiz VALUES(1459,'Which vrata is observed for the long life of husband?','पति की दीर्घायु के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Karva Chauth", "hi": "करवा चौथ"}, {"key": "B", "en": "Vat Savitri", "hi": "वट सावित्री"}, {"key": "C", "en": "Teej", "hi": "तीज"}, {"key": "D", "en": "Ekadashi", "hi": "एकादशी"}]','A');
INSERT INTO knowledge_quiz VALUES(1460,'Which god is known as the king of gods in the Vedas?','वेदों में देवताओं का राजा किसे कहा गया है?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1461,'Which mountain did Lord Krishna lift to protect villagers?','भगवान कृष्ण ने ग्रामीणों की रक्षा के लिए कौन सा पर्वत उठाया था?','[{"key": "A", "en": "Mount Meru", "hi": "मेरु पर्वत"}, {"key": "B", "en": "Govardhan", "hi": "गोवर्धन"}, {"key": "C", "en": "Mandara", "hi": "मंदराचल"}, {"key": "D", "en": "Kailash", "hi": "कैलाश"}]','B');
INSERT INTO knowledge_quiz VALUES(1462,'Who took the form of Mohini?','मोहिनी रूप किसने धारण किया था?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','D');
INSERT INTO knowledge_quiz VALUES(1463,'Which scripture is attributed to Sage Manu?','कौन सा ग्रंथ ऋषि मनु से संबंधित है?','[{"key": "A", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "B", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "C", "en": "Yogasutra", "hi": "योगसूत्र"}, {"key": "D", "en": "Brahma Sutra", "hi": "ब्रह्म सूत्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1464,'Which rishi is associated with the Rigveda?','ऋग्वेद किस ऋषि से संबंधित है?','[{"key": "A", "en": "Angiras", "hi": "अंगिरस"}, {"key": "B", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "C", "en": "Vishwamitra", "hi": "विश्वामित्र"}, {"key": "D", "en": "Many rishis", "hi": "अनेक ऋषि"}]','D');
INSERT INTO knowledge_quiz VALUES(1465,'What is the specific offering associated with the worship of Lord Shani to mitigate his effects?','भगवान शनि के प्रभाव को कम करने के लिए उनकी पूजा में किस विशिष्ट वस्तु का दान या अर्पण किया जाता है?','[{"key": "A", "en": "Milk", "hi": "दूध"}, {"key": "B", "en": "Mustard Oil", "hi": "सरसों का तेल"}, {"key": "C", "en": "Honey", "hi": "शहद"}, {"key": "D", "en": "Curd", "hi": "दही"}]','B');
INSERT INTO knowledge_quiz VALUES(1466,'Which holy text is known as the Song of God?','‘भगवान का गीत’ किस ग्रंथ को कहा जाता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Vedas", "hi": "वेद"}, {"key": "D", "en": "Upanishads", "hi": "उपनिषद"}]','B');
INSERT INTO knowledge_quiz VALUES(1467,'Vindhyachal Temple in Mirzapur district is dedicated to which form of the Goddess?','मिर्जापुर जिले का विंध्याचल मंदिर देवी के किस रूप को समर्पित है?','[{"key": "A", "en": "Vindhyavasini", "hi": "विंध्यवासिनी"}, {"key": "B", "en": "Shakumbhari Devi", "hi": "शाकम्भरी देवी"}, {"key": "C", "en": "Lalita Devi", "hi": "ललिता देवी"}, {"key": "D", "en": "Katyayani", "hi": "कात्यायनी"}]','A');
INSERT INTO knowledge_quiz VALUES(1468,'Which rishi is associated with the Mahabharata?','महाभारत किस ऋषि से संबंधित है?','[{"key": "A", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1469,'Which yuga is the longest?','सबसे लंबा युग कौन सा है?','[{"key": "A", "en": "Satya Yuga", "hi": "सत्य युग"}, {"key": "B", "en": "Treta Yuga", "hi": "त्रेता युग"}, {"key": "C", "en": "Dvapara Yuga", "hi": "द्वापर युग"}, {"key": "D", "en": "Kali Yuga", "hi": "कलि युग"}]','A');
INSERT INTO knowledge_quiz VALUES(1470,'Which place is known as the birthplace of Lord Krishna?','भगवान कृष्ण का जन्मस्थान कौन सा है?','[{"key": "A", "en": "Dwarka", "hi": "द्वारका"}, {"key": "B", "en": "Vrindavan", "hi": "वृंदावन"}, {"key": "C", "en": "Mathura", "hi": "मथुरा"}, {"key": "D", "en": "Gokul", "hi": "गोकुल"}]','C');
INSERT INTO knowledge_quiz VALUES(1471,'Which goddess is also known as Shakti?','शक्ति के रूप में किस देवी को जाना जाता है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','A');
INSERT INTO knowledge_quiz VALUES(1472,'Which weapon of Lord Brahma is capable of destroying the entire universe and cannot be countered once released?','भगवान ब्रह्मा का वह कौन सा अस्त्र है जो पूरे ब्रह्मांड को नष्ट करने में सक्षम है और एक बार छोड़े जाने के बाद इसे रोका नहीं जा सकता?','[{"key": "A", "en": "Brahmashira Astra", "hi": "ब्रह्मशिरा अस्त्र"}, {"key": "B", "en": "Brahmastra", "hi": "ब्रह्मास्त्र"}, {"key": "C", "en": "Brahmadanda", "hi": "ब्रह्मदण्ड"}, {"key": "D", "en": "Pashupatastra", "hi": "पाशुपतास्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1473,'Which deity is worshipped at Kedarnath?','केदारनाथ में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1474,'Which ashrama is the first stage of life?','जीवन का पहला आश्रम कौन सा है?','[{"key": "A", "en": "Grihastha", "hi": "गृहस्थ"}, {"key": "B", "en": "Brahmacharya", "hi": "ब्रह्मचर्य"}, {"key": "C", "en": "Vanaprastha", "hi": "वानप्रस्थ"}, {"key": "D", "en": "Sannyasa", "hi": "संन्यास"}]','B');
INSERT INTO knowledge_quiz VALUES(1475,'Which Purana is associated with Lord Skanda?','भगवान स्कंद से संबंधित पुराण कौन सा है?','[{"key": "A", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "B", "en": "Agni Purana", "hi": "अग्नि पुराण"}, {"key": "C", "en": "Linga Purana", "hi": "लिंग पुराण"}, {"key": "D", "en": "Vayu Purana", "hi": "वायु पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(1476,'Which deity is associated with the planet Jupiter?','कौन सा देवता ग्रह बृहस्पति से संबंधित है?','[{"key": "A", "en": "Shukra", "hi": "शुक्र"}, {"key": "B", "en": "Brihaspati", "hi": "बृहस्पति"}, {"key": "C", "en": "Chandra", "hi": "चंद्र"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1477,'Which temple is famous for the Rath Yatra?','रथ यात्रा के लिए कौन सा मंदिर प्रसिद्ध है?','[{"key": "A", "en": "Dwarkadhish Temple", "hi": "द्वारकाधीश मंदिर"}, {"key": "B", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}, {"key": "C", "en": "Somnath Temple", "hi": "सोमनाथ मंदिर"}, {"key": "D", "en": "Kedarnath Temple", "hi": "केदारनाथ मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(1478,'Which historic temple near Sangli is famous for its Hemadpanti style architecture and 108 stone pillars?','सांगली के पास कौन सा ऐतिहासिक मंदिर अपनी हेमाडपंती शैली की वास्तुकला और 108 पत्थर के खंभों के लिए प्रसिद्ध है?','[{"key": "A", "en": "Kopeshwar Temple", "hi": "कोपेश्वर मंदिर"}, {"key": "B", "en": "Khidrapur Temple", "hi": "खिद्रापुर मंदिर"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Gondeshwar Temple", "hi": "गोंदेश्वर मंदिर"}]','C');
INSERT INTO knowledge_quiz VALUES(1479,'Which text contains the laws of Dharma?','धर्म के नियम किस ग्रंथ में वर्णित हैं?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Dharmashastras", "hi": "धर्मशास्त्र"}, {"key": "C", "en": "Vedas", "hi": "वेद"}, {"key": "D", "en": "Puranas", "hi": "पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1480,'Which goddess is worshipped during Sharad Navratri?','शारदीय नवरात्रि में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','C');
INSERT INTO knowledge_quiz VALUES(1481,'Which epic describes the childhood of Lord Krishna?','भगवान कृष्ण के बाल्यकाल का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "B", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "C", "en": "Harivamsa", "hi": "हरिवंश"}, {"key": "D", "en": "Both B and C", "hi": "B और C दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(1482,'Which rishi is associated with Ayurveda?','आयुर्वेद किस ऋषि से संबंधित है?','[{"key": "A", "en": "Charaka", "hi": "चरक"}, {"key": "B", "en": "Sushruta", "hi": "सुश्रुत"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Kapila", "hi": "कपिल"}]','C');
INSERT INTO knowledge_quiz VALUES(1483,'Which sacred lake is near Mount Kailash?','कैलाश पर्वत के पास कौन सा पवित्र सरोवर है?','[{"key": "A", "en": "Pushkar Lake", "hi": "पुष्कर सरोवर"}, {"key": "B", "en": "Manasarovar", "hi": "मानसरोवर"}, {"key": "C", "en": "Dal Lake", "hi": "डल झील"}, {"key": "D", "en": "Nainital Lake", "hi": "नैनीताल झील"}]','B');
INSERT INTO knowledge_quiz VALUES(1484,'Which flower is unique because it is offered to deities even after it has fallen to the ground (unlike others)?','कौन सा फूल अद्वितीय है क्योंकि जमीन पर गिरने के बाद भी उसे देवताओं को अर्पित किया जाता है (दूसरों के विपरीत)?','[{"key": "A", "en": "Parijat", "hi": "पारिजात"}, {"key": "B", "en": "Mogra", "hi": "मोगरा"}, {"key": "C", "en": "Champa", "hi": "चम्पा"}, {"key": "D", "en": "Lotus", "hi": "कमल"}]','A');
INSERT INTO knowledge_quiz VALUES(1485,'Which yuga did Lord Rama belong to?','भगवान राम किस युग से संबंधित हैं?','[{"key": "A", "en": "Satya Yuga", "hi": "सत्य युग"}, {"key": "B", "en": "Treta Yuga", "hi": "त्रेता युग"}, {"key": "C", "en": "Dvapara Yuga", "hi": "द्वापर युग"}, {"key": "D", "en": "Kali Yuga", "hi": "कलि युग"}]','B');
INSERT INTO knowledge_quiz VALUES(1486,'Which god is worshipped as the Sun God?','सूर्य देव के रूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Surya", "hi": "सूर्य"}, {"key": "B", "en": "Agni", "hi": "अग्नि"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','A');
INSERT INTO knowledge_quiz VALUES(1487,'Which scripture is recited during Griha Pravesh?','गृह प्रवेश के समय कौन सा ग्रंथ पढ़ा जाता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Vedas", "hi": "वेद"}, {"key": "C", "en": "Satyanarayana Katha", "hi": "सत्यनारायण कथा"}, {"key": "D", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}]','C');
INSERT INTO knowledge_quiz VALUES(1488,'Which rishi is associated with the Yajurveda?','यजुर्वेद किस ऋषि से संबंधित है?','[{"key": "A", "en": "Vaishampayana", "hi": "वैशंपायन"}, {"key": "B", "en": "Vishwamitra", "hi": "विश्वामित्र"}, {"key": "C", "en": "Angiras", "hi": "अंगिरस"}, {"key": "D", "en": "Bharadwaja", "hi": "भरद्वाज"}]','A');
INSERT INTO knowledge_quiz VALUES(1489,'Which metal is traditionally offered to Shani Dev to pacify his influence?','शनि देव के प्रभाव को शांत करने के लिए पारंपरिक रूप से कौन सी धातु अर्पित की जाती है?','[{"key": "A", "en": "Gold", "hi": "सोना"}, {"key": "B", "en": "Silver", "hi": "चांदी"}, {"key": "C", "en": "Iron", "hi": "लोहा"}, {"key": "D", "en": "Copper", "hi": "तांबा"}]','C');
INSERT INTO knowledge_quiz VALUES(1490,'Which goddess is known as Annapurna?','अन्नपूर्णा किस देवी का नाम है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(1491,'Which city is known as the city of learning?','किस नगर को विद्या की नगरी कहा जाता है?','[{"key": "A", "en": "Kashi", "hi": "काशी"}, {"key": "B", "en": "Takshashila", "hi": "तक्षशिला"}, {"key": "C", "en": "Nalanda", "hi": "नालंदा"}, {"key": "D", "en": "Both B and C", "hi": "B और C दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(1492,'Which Purana contains the Devi Mahatmya?','देवी महात्म्य किस पुराण में है?','[{"key": "A", "en": "Markandeya Purana", "hi": "मार्कण्डेय पुराण"}, {"key": "B", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "C", "en": "Brahma Purana", "hi": "ब्रह्म पुराण"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(1493,'Which fast is observed on full moon day?','पूर्णिमा के दिन कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Amavasya Vrat", "hi": "अमावस्या व्रत"}, {"key": "B", "en": "Purnima Vrat", "hi": "पूर्णिमा व्रत"}, {"key": "C", "en": "Ekadashi Vrat", "hi": "एकादशी व्रत"}, {"key": "D", "en": "Pradosh Vrat", "hi": "प्रदोष व्रत"}]','B');
INSERT INTO knowledge_quiz VALUES(1494,'Which god is worshipped during Vishnu Sahasranama recitation?','विष्णु सहस्रनाम के पाठ में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1495,'Which famous Aarti is sung in praise of the holy river Ganga, especially at Haridwar and Varanasi?','पवित्र नदी गंगा की स्तुति में कौन सी प्रसिद्ध आरती गाई जाती है, विशेष रूप से हरिद्वार और वाराणसी में?','[{"key": "A", "en": "Om Jai Gange Mata", "hi": "ओम जय गंगे माता"}, {"key": "B", "en": "Jai Ambe Gauri", "hi": "जय अम्बे गौरी"}, {"key": "C", "en": "Sukhakarta Dukhaharta", "hi": "सुखकर्ता दुखहर्ता"}, {"key": "D", "en": "Ganga Chalisa", "hi": "गंगा चालीसा"}]','A');
INSERT INTO knowledge_quiz VALUES(1496,'The ''Bhitargaon Temple'', located in Kanpur district, is one of the oldest surviving examples of which construction material?','कानपुर जिले में स्थित ''भीतरगाँव मंदिर'' किस निर्माण सामग्री का सबसे पुराना जीवित उदाहरण है?','[{"key": "A", "en": "Marble", "hi": "संगमरमर"}, {"key": "B", "en": "Terracotta Bricks", "hi": "पकी हुई ईंटें (टेराकोटा)"}, {"key": "C", "en": "Sandstone", "hi": "बलुआ पत्थर"}, {"key": "D", "en": "Granite", "hi": "ग्रेनाइट"}]','B');
INSERT INTO knowledge_quiz VALUES(1497,'Which scripture focuses on devotion to Vishnu?','विष्णु भक्ति पर केंद्रित ग्रंथ कौन सा है?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "C", "en": "Linga Purana", "hi": "लिंग पुराण"}, {"key": "D", "en": "Skanda Purana", "hi": "स्कंद पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(1498,'Which god is known as the lord of yoga?','योग के अधिपति किस देवता को कहा जाता है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','A');
INSERT INTO knowledge_quiz VALUES(1499,'Which festival celebrates brother-sister bond?','भाई-बहन के संबंध को कौन सा त्योहार मनाता है?','[{"key": "A", "en": "Raksha Bandhan", "hi": "रक्षा बंधन"}, {"key": "B", "en": "Bhai Dooj", "hi": "भाई दूज"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Teej", "hi": "तीज"}]','C');
INSERT INTO knowledge_quiz VALUES(1500,'Which sacred tree is worshipped in Hinduism?','हिंदू धर्म में किस पवित्र वृक्ष की पूजा होती है?','[{"key": "A", "en": "Banyan (Vat)", "hi": "वट वृक्ष"}, {"key": "B", "en": "Peepal", "hi": "पीपल"}, {"key": "C", "en": "Neem", "hi": "नीम"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1501,'Which sage is known as the ''Grandfather'' of both the Kauravas and the Pandavas?','किस ऋषि को कौरवों और पांडवों दोनों का ''दादा'' (पितामह) माना जाता है?','[{"key": "A", "en": "Sage Vashistha", "hi": "ऋषि वशिष्ठ"}, {"key": "B", "en": "Sage Vyasa", "hi": "ऋषि व्यास"}, {"key": "C", "en": "Sage Narada", "hi": "ऋषि नारद"}, {"key": "D", "en": "Sage Parashar", "hi": "ऋषि पराशर"}]','B');
INSERT INTO knowledge_quiz VALUES(1502,'In the Hanuman Chalisa, ''Prabhu mudrika meli mukha mahi'' refers to Hanuman carrying what in his mouth while crossing the ocean?','हनुमान चालीसा में ''प्रभु मुद्रिका मेलि मुख माहीं'' का अर्थ है कि हनुमान ने समुद्र पार करते समय अपने मुख में क्या रखा था?','[{"key": "A", "en": "A pearl", "hi": "एक मोती"}, {"key": "B", "en": "Lord Rama''s ring", "hi": "भगवान राम की अंगूठी (मुद्रिका)"}, {"key": "C", "en": "A sacred leaf", "hi": "एक पवित्र पत्ता"}, {"key": "D", "en": "Sanjivani herb", "hi": "संजीवनी बूटी"}]','B');
INSERT INTO knowledge_quiz VALUES(1503,'Which sage is considered the compiler of the Vedas?','वेदों के संकलनकर्ता के रूप में किस ऋषि को माना जाता है?','[{"key": "A", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1504,'Dhakeshwari Temple, the national temple of Bangladesh, is dedicated to which goddess?','बांग्लादेश का राष्ट्रीय मंदिर, ढाकेश्वरी मंदिर, किस देवी को समर्पित है?','[{"key": "A", "en": "Goddess Sheetala", "hi": "देवी शीतला"}, {"key": "B", "en": "Goddess Durga", "hi": "देवी दुर्गा"}, {"key": "C", "en": "Goddess Lakshmi", "hi": "देवी लक्ष्मी"}, {"key": "D", "en": "Goddess Saraswati", "hi": "देवी सरस्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(1505,'Which goddess is known as the consort of Lord Shiva?','भगवान शिव की पत्नी के रूप में किस देवी को जाना जाता है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','C');
INSERT INTO knowledge_quiz VALUES(1506,'Which Purana describes the genealogy of kings?','राजाओं की वंशावली का वर्णन किस पुराण में मिलता है?','[{"key": "A", "en": "Vayu Purana", "hi": "वायु पुराण"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1507,'Which temple is dedicated to Lord Shiva at Ujjain?','उज्जैन में भगवान शिव को समर्पित कौन सा मंदिर है?','[{"key": "A", "en": "Somnath", "hi": "सोमनाथ"}, {"key": "B", "en": "Mahakaleshwar", "hi": "महाकालेश्वर"}, {"key": "C", "en": "Badrinath", "hi": "बद्रीनाथ"}, {"key": "D", "en": "Kedarnath", "hi": "केदारनाथ"}]','B');
INSERT INTO knowledge_quiz VALUES(1508,'Which yuga is associated with Lord Krishna?','भगवान कृष्ण किस युग से संबंधित हैं?','[{"key": "A", "en": "Satya Yuga", "hi": "सत्य युग"}, {"key": "B", "en": "Treta Yuga", "hi": "त्रेता युग"}, {"key": "C", "en": "Dvapara Yuga", "hi": "द्वापर युग"}, {"key": "D", "en": "Kali Yuga", "hi": "कलि युग"}]','C');
INSERT INTO knowledge_quiz VALUES(1509,'Which rishi is associated with the Shiva Tandava Stotra?','शिव तांडव स्तोत्र किस ऋषि से जुड़ा है?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Ravana", "hi": "रावण"}, {"key": "C", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "D", "en": "Vashistha", "hi": "वशिष्ठ"}]','B');
INSERT INTO knowledge_quiz VALUES(1510,'Which goddess is worshipped as the river Yamuna?','यमुना नदी के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yami", "hi": "यामी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Lakshmi", "hi": "लक्ष्मी"}]','B');
INSERT INTO knowledge_quiz VALUES(1511,'Which scripture explains the philosophy of Advaita Vedanta?','अद्वैत वेदांत के दर्शन को कौन सा ग्रंथ समझाता है?','[{"key": "A", "en": "Brahma Sutra Bhashya", "hi": "ब्रह्मसूत्र भाष्य"}, {"key": "B", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "C", "en": "Nyaya Sutra", "hi": "न्याय सूत्र"}, {"key": "D", "en": "Purva Mimamsa", "hi": "पूर्व मीमांसा"}]','A');
INSERT INTO knowledge_quiz VALUES(1512,'Which god is known as the lord of wealth?','धन के देवता किसे कहा जाता है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Kubera", "hi": "कुबेर"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1513,'In Shodashopachara puja, what does ''Arghya'' signify?','षोडशोपचार पूजा में ''अर्घ्य'' का क्या अर्थ है?','[{"key": "A", "en": "Offering flowers", "hi": "पुष्प अर्पित करना"}, {"key": "B", "en": "Offering water to wash hands", "hi": "हाथ धोने के लिए जल अर्पित करना"}, {"key": "C", "en": "Offering a seat", "hi": "आसन अर्पित करना"}, {"key": "D", "en": "Offering clothes", "hi": "वस्त्र अर्पित करना"}]','B');
INSERT INTO knowledge_quiz VALUES(1514,'Which epic contains the story of Nala and Damayanti?','नल और दमयंती की कथा किस महाकाव्य में है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Harivamsa", "hi": "हरिवंश"}, {"key": "D", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1515,'Which deity is worshipped on Akshaya Tritiya?','अक्षय तृतीया पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','C');
INSERT INTO knowledge_quiz VALUES(1516,'Which sage is associated with the Ram Raksha Stotra?','राम रक्षा स्तोत्र किस ऋषि से संबंधित है?','[{"key": "A", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "B", "en": "Budha Kaushika", "hi": "बुध कौशिक"}, {"key": "C", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "D", "en": "Vishwamitra", "hi": "विश्वामित्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1517,'Which city is known as the city of Shiva?','किस नगर को शिव की नगरी कहा जाता है?','[{"key": "A", "en": "Ujjain", "hi": "उज्जैन"}, {"key": "B", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "C", "en": "Haridwar", "hi": "हरिद्वार"}, {"key": "D", "en": "Rishikesh", "hi": "ऋषिकेश"}]','B');
INSERT INTO knowledge_quiz VALUES(1518,'Which goddess is worshipped during Gauri Puja?','गौरी पूजा में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(1519,'Which asura was slain by Goddess Durga during Navratri?','नवरात्रि में देवी दुर्गा ने किस असुर का वध किया?','[{"key": "A", "en": "Shumbha", "hi": "शुम्भ"}, {"key": "B", "en": "Nishumbha", "hi": "निशुम्भ"}, {"key": "C", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "D", "en": "Bali", "hi": "बलि"}]','C');
INSERT INTO knowledge_quiz VALUES(1520,'Which scripture describes the duties of kings?','राजाओं के कर्तव्यों का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "B", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Upanishads", "hi": "उपनिषद"}]','C');
INSERT INTO knowledge_quiz VALUES(1521,'Which god is worshipped as Nataraja?','नटराज के रूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1522,'Which Jyotirlinga temple is located at the base of the Brahmagiri Mountain?','ब्रह्मगिरी पर्वत की तलहटी में कौन सा ज्योतिर्लिंग मंदिर स्थित है?','[{"key": "A", "en": "Bhimashankar", "hi": "भीमाशंकर"}, {"key": "B", "en": "Trimbakeshwar", "hi": "त्रयंबकेश्वर"}, {"key": "C", "en": "Grishneshwar", "hi": "घृष्णेश्वर"}, {"key": "D", "en": "Aundha Nagnath", "hi": "औंढा नागनाथ"}]','B');
INSERT INTO knowledge_quiz VALUES(1523,'Which festival is dedicated to the worship of snakes?','सर्पों की पूजा के लिए कौन सा पर्व समर्पित है?','[{"key": "A", "en": "Nag Panchami", "hi": "नाग पंचमी"}, {"key": "B", "en": "Vat Savitri", "hi": "वट सावित्री"}, {"key": "C", "en": "Teej", "hi": "तीज"}, {"key": "D", "en": "Pradosh", "hi": "प्रदोष"}]','A');
INSERT INTO knowledge_quiz VALUES(1524,'In the Hanuman Chalisa, Hanuman is called ''Anjani Putra'' and ''Pavan Suta''. What does ''Suta'' mean?','हनुमान चालीसा में, हनुमान को ''अंजनी पुत्र'' और ''पवन सुत'' कहा गया है। ''सुत'' का क्या अर्थ है?','[{"key": "A", "en": "Friend", "hi": "मित्र"}, {"key": "B", "en": "Son", "hi": "पुत्र"}, {"key": "C", "en": "Brother", "hi": "भाई"}, {"key": "D", "en": "Servant", "hi": "सेवक"}]','B');
INSERT INTO knowledge_quiz VALUES(1525,'Which deity is worshipped during Varalakshmi Vratam?','वरलक्ष्मी व्रतम में किस देवी की पूजा होती है?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(1526,'Which scripture is considered the essence of the Upanishads?','उपनिषदों का सार किस ग्रंथ को माना जाता है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Brahma Sutra", "hi": "ब्रह्म सूत्र"}, {"key": "C", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "D", "en": "Aranyakas", "hi": "आरण्यक"}]','A');
INSERT INTO knowledge_quiz VALUES(1527,'Which rishi is associated with the Atharvaveda?','अथर्ववेद किस ऋषि से संबंधित है?','[{"key": "A", "en": "Angiras", "hi": "अंगिरस"}, {"key": "B", "en": "Vishwamitra", "hi": "विश्वामित्र"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','A');
INSERT INTO knowledge_quiz VALUES(1528,'Which temple is one of the twelve Jyotirlingas?','बारह ज्योतिर्लिंगों में से कौन सा मंदिर है?','[{"key": "A", "en": "Kashi Vishwanath", "hi": "काशी विश्वनाथ"}, {"key": "B", "en": "Vaishno Devi", "hi": "वैष्णो देवी"}, {"key": "C", "en": "Tirupati", "hi": "तिरुपति"}, {"key": "D", "en": "Jagannath", "hi": "जगन्नाथ"}]','A');
INSERT INTO knowledge_quiz VALUES(1529,'Which deity is worshipped in the form of Shivalinga?','शिवलिंग के रूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1530,'Which temple in Jajpur is one of the 18 Maha Shakti Peethas and is dedicated to Goddess Varahi?','जाजपुर में कौन सा मंदिर 18 महाशक्तिपीठों में से एक है और देवी वराही को समर्पित है?','[{"key": "A", "en": "Biraja Temple", "hi": "बिरजा मंदिर"}, {"key": "B", "en": "Taratarini", "hi": "तारातारिणी"}, {"key": "C", "en": "Maa Mangala", "hi": "माँ मंगला"}, {"key": "D", "en": "Kichakeswari", "hi": "किचकेश्वरी"}]','A');
INSERT INTO knowledge_quiz VALUES(1531,'The Leaning Temple of Huma, the only leaning temple in the world, is dedicated to which deity?','हुमा का झुका हुआ मंदिर, दुनिया का एकमात्र झुका हुआ मंदिर, किस देवता को समर्पित है?','[{"key": "A", "en": "Lord Vishnu", "hi": "भगवान विष्णु"}, {"key": "B", "en": "Lord Shiva (Bimaleshwar)", "hi": "भगवान शिव (बिमलेश्वर)"}, {"key": "C", "en": "Lord Ganesha", "hi": "भगवान गणेश"}, {"key": "D", "en": "Lord Surya", "hi": "भगवान सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1532,'In the Jagannath Temple, the idols are made of which material, unlike traditional stone or metal?','जगन्नाथ मंदिर में मूर्तियाँ पारंपरिक पत्थर या धातु के बजाय किस सामग्री से बनी होती हैं?','[{"key": "A", "en": "Marble", "hi": "संगमरमर"}, {"key": "B", "en": "Neem Wood (Daru)", "hi": "नीम की लकड़ी (दारु)"}, {"key": "C", "en": "Terracotta", "hi": "टेराकोटा"}, {"key": "D", "en": "Silver", "hi": "चांदी"}]','B');
INSERT INTO knowledge_quiz VALUES(1533,'Which scripture narrates the exploits of Lord Vishnu?','भगवान विष्णु की लीलाओं का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "B", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "C", "en": "Markandeya Purana", "hi": "मार्कण्डेय पुराण"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(1534,'What is the literal meaning of the name ''Meenakshi''?','''मीनाक्षी'' नाम का शाब्दिक अर्थ क्या है?','[{"key": "A", "en": "One with lotus-like eyes", "hi": "कमल जैसे नेत्रों वाली"}, {"key": "B", "en": "One with fish-shaped eyes", "hi": "मछली के आकार की आँखों वाली"}, {"key": "C", "en": "One who is beautiful", "hi": "अत्यंत सुंदर स्त्री"}, {"key": "D", "en": "Queen of the seas", "hi": "समुद्रों की रानी"}]','B');
INSERT INTO knowledge_quiz VALUES(1535,'Which ashrama is associated with household life?','गृहस्थ जीवन से कौन सा आश्रम संबंधित है?','[{"key": "A", "en": "Brahmacharya", "hi": "ब्रह्मचर्य"}, {"key": "B", "en": "Grihastha", "hi": "गृहस्थ"}, {"key": "C", "en": "Vanaprastha", "hi": "वानप्रस्थ"}, {"key": "D", "en": "Sannyasa", "hi": "संन्यास"}]','B');
INSERT INTO knowledge_quiz VALUES(1536,'Which sacred river flows through Rameswaram?','रामेश्वरम से होकर कौन सी पवित्र नदी बहती है?','[{"key": "A", "en": "Kaveri", "hi": "कावेरी"}, {"key": "B", "en": "Vaigai", "hi": "वैगई"}, {"key": "C", "en": "None (sea location)", "hi": "कोई नहीं (समुद्र तट)"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','C');
INSERT INTO knowledge_quiz VALUES(1537,'Which deity is worshipped during Ganesha Chaturthi?','गणेश चतुर्थी पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Karttikeya", "hi": "कार्तिकेय"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','B');
INSERT INTO knowledge_quiz VALUES(1538,'Which mantra is known as the universal mantra?','सार्वभौमिक मंत्र किसे कहा जाता है?','[{"key": "A", "en": "Gayatri Mantra", "hi": "गायत्री मंत्र"}, {"key": "B", "en": "Om", "hi": "ॐ"}, {"key": "C", "en": "Mahamrityunjaya", "hi": "महामृत्युंजय"}, {"key": "D", "en": "Hare Krishna", "hi": "हरे कृष्ण"}]','B');
INSERT INTO knowledge_quiz VALUES(1539,'Which river is considered the lifeline of Gujarat?','गुजरात की जीवनरेखा किस नदी को माना जाता है?','[{"key": "A", "en": "Narmada", "hi": "नर्मदा"}, {"key": "B", "en": "Sabarmati", "hi": "साबरमती"}, {"key": "C", "en": "Tapi", "hi": "ताप्ती"}, {"key": "D", "en": "Mahi", "hi": "माही"}]','A');
INSERT INTO knowledge_quiz VALUES(1540,'Which scripture contains the story of Gajendra Moksha?','गजेंद्र मोक्ष की कथा किस ग्रंथ में है?','[{"key": "A", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "B", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "C", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "D", "en": "Padma Purana", "hi": "पद्म पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1541,'Which deity is worshipped during Ayyappa Mandala Puja?','अयप्पा मंडल पूजा में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Ayyappa", "hi": "अयप्पा"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Murugan", "hi": "मुरुगन"}]','B');
INSERT INTO knowledge_quiz VALUES(1542,'Which festival marks the worship of tools and machines?','औजारों और मशीनों की पूजा किस पर्व पर होती है?','[{"key": "A", "en": "Ayudha Puja", "hi": "आयुध पूजा"}, {"key": "B", "en": "Onam", "hi": "ओणम"}, {"key": "C", "en": "Pongal", "hi": "पोंगल"}, {"key": "D", "en": "Baisakhi", "hi": "बैसाखी"}]','A');
INSERT INTO knowledge_quiz VALUES(1543,'Which deity is worshipped during Pongal?','पोंगल पर्व पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Surya", "hi": "सूर्य"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','B');
INSERT INTO knowledge_quiz VALUES(1544,'Which goddess is worshipped as the Earth?','पृथ्वी के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Bhumi", "hi": "भूमि"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Lakshmi", "hi": "लक्ष्मी"}]','A');
INSERT INTO knowledge_quiz VALUES(1545,'Which deity is worshipped in the form of Shaligram?','शालिग्राम के रूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1546,'Which epic narrates the story of Lord Rama?','भगवान राम की कथा किस महाकाव्य में वर्णित है?','[{"key": "A", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "B", "en": "Ramayana", "hi": "रामायण"}, {"key": "C", "en": "Harivamsa", "hi": "हरिवंश"}, {"key": "D", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1547,'Which rishi is associated with the Gayatri Mantra?','गायत्री मंत्र किस ऋषि से संबंधित है?','[{"key": "A", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "B", "en": "Vishwamitra", "hi": "विश्वामित्र"}, {"key": "C", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "D", "en": "Bharadwaja", "hi": "भरद्वाज"}]','B');
INSERT INTO knowledge_quiz VALUES(1548,'Which deity is worshipped during Mahashivaratri?','महाशिवरात्रि पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Ganesha", "hi": "गणेश"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1549,'Which river is associated with the city of Prayagraj?','प्रयागराज नगर किस नदी से जुड़ा है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','C');
INSERT INTO knowledge_quiz VALUES(1550,'The term ''Chalisa'' is derived from which Hindi word, indicating the number of verses it contains?','''चालीसा'' शब्द किस हिंदी शब्द से निकला है, जो इसमें छंदों की संख्या को दर्शाता है?','[{"key": "A", "en": "Forty", "hi": "चालीस"}, {"key": "B", "en": "Char (Four)", "hi": "चार"}, {"key": "C", "en": "Chausath (Sixty-four)", "hi": "चौंसठ"}, {"key": "D", "en": "Chandra (Moon)", "hi": "चंद्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1551,'Which river goddess is known as the daughter of Surya Dev?','कौन सी नदी देवी सूर्य देव की पुत्री जानी जाती हैं?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Tapti", "hi": "ताप्ती"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','C');
INSERT INTO knowledge_quiz VALUES(1552,'Which river is known as the lifeline of Tamil Nadu?','तमिलनाडु की जीवनरेखा किस नदी को कहा जाता है?','[{"key": "A", "en": "Krishna", "hi": "कृष्णा"}, {"key": "B", "en": "Godavari", "hi": "गोदावरी"}, {"key": "C", "en": "Kaveri", "hi": "कावेरी"}, {"key": "D", "en": "Vaigai", "hi": "वैगई"}]','C');
INSERT INTO knowledge_quiz VALUES(1553,'Which rishi is considered the father of the Indian nation in ancient lore?','प्राचीन परंपरा में भारतीय राष्ट्र का पिता किस ऋषि को माना जाता है?','[{"key": "A", "en": "Bharata", "hi": "भरत"}, {"key": "B", "en": "Bharadwaja", "hi": "भरद्वाज"}, {"key": "C", "en": "Vishwamitra", "hi": "विश्वामित्र"}, {"key": "D", "en": "Manu", "hi": "मनु"}]','D');
INSERT INTO knowledge_quiz VALUES(1554,'Which Purana is dedicated primarily to Lord Vishnu?','मुख्य रूप से भगवान विष्णु को समर्पित कौन सा पुराण है?','[{"key": "A", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1555,'Which festival is associated with the worship of cows?','गौ पूजा से संबंधित पर्व कौन सा है?','[{"key": "A", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "B", "en": "Gopashtami", "hi": "गोपाष्टमी"}, {"key": "C", "en": "Nag Panchami", "hi": "नाग पंचमी"}, {"key": "D", "en": "Pongal", "hi": "पोंगल"}]','B');
INSERT INTO knowledge_quiz VALUES(1556,'Which mountain is associated with the churning of the ocean?','समुद्र मंथन से कौन सा पर्वत जुड़ा है?','[{"key": "A", "en": "Mount Meru", "hi": "मेरु पर्वत"}, {"key": "B", "en": "Mount Kailash", "hi": "कैलाश पर्वत"}, {"key": "C", "en": "Mount Mandara", "hi": "मंदराचल पर्वत"}, {"key": "D", "en": "Mount Govardhan", "hi": "गोवर्धन पर्वत"}]','C');
INSERT INTO knowledge_quiz VALUES(1557,'The ''Bhairav Chalisa'' is often recited to overcome fear. Lord Bhairav is considered a fierce manifestation of which God?','''भैरव चालीसा'' का पाठ अक्सर डर पर विजय पाने के लिए किया जाता है। भगवान भैरव को किस भगवान का उग्र रूप माना जाता है?','[{"key": "A", "en": "Lord Vishnu", "hi": "भगवान विष्णु"}, {"key": "B", "en": "Lord Shiva", "hi": "भगवान शिव"}, {"key": "C", "en": "Lord Brahma", "hi": "भगवान ब्रह्मा"}, {"key": "D", "en": "Lord Indra", "hi": "भगवान इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1558,'Which sacred text is known as the storehouse of stories?','किस ग्रंथ को कथाओं का भंडार कहा जाता है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Puranas", "hi": "पुराण"}, {"key": "C", "en": "Vedas", "hi": "वेद"}, {"key": "D", "en": "Aranyakas", "hi": "आरण्यक"}]','B');
INSERT INTO knowledge_quiz VALUES(1559,'Which deity is worshipped during Navratri in Gujarat?','गुजरात में नवरात्रि के दौरान किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Amba (Durga)", "hi": "अम्बा (दुर्गा)"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','C');
INSERT INTO knowledge_quiz VALUES(1560,'Which rishi is associated with the Brihadaranyaka Upanishad?','बृहदारण्यक उपनिषद किस ऋषि से संबंधित है?','[{"key": "A", "en": "Yajnavalkya", "hi": "याज्ञवल्क्य"}, {"key": "B", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "C", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "D", "en": "Bharadwaja", "hi": "भरद्वाज"}]','A');
INSERT INTO knowledge_quiz VALUES(1561,'Which god is worshipped during Guru Purnima?','गुरु पूर्णिमा पर किसकी पूजा की जाती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','B');
INSERT INTO knowledge_quiz VALUES(1562,'Which sacred place is known as the confluence of three rivers?','तीन नदियों के संगम के रूप में कौन सा स्थान प्रसिद्ध है?','[{"key": "A", "en": "Haridwar", "hi": "हरिद्वार"}, {"key": "B", "en": "Prayagraj", "hi": "प्रयागराज"}, {"key": "C", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "D", "en": "Ujjain", "hi": "उज्जैन"}]','B');
INSERT INTO knowledge_quiz VALUES(1563,'Which scripture is known as the law book of ancient India?','प्राचीन भारत की विधि पुस्तिका किस ग्रंथ को कहा जाता है?','[{"key": "A", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "B", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "C", "en": "Vedas", "hi": "वेद"}, {"key": "D", "en": "Upanishads", "hi": "उपनिषद"}]','B');
INSERT INTO knowledge_quiz VALUES(1564,'Which deity is worshipped in the form of Tulsi plant?','तुलसी पौधे के रूप में किस देवी/देवता की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Vrinda", "hi": "वृंदा"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','B');
INSERT INTO knowledge_quiz VALUES(1565,'Which avatar of Vishnu protected Prahlada?','प्रह्लाद की रक्षा किस विष्णु अवतार ने की?','[{"key": "A", "en": "Vamana", "hi": "वामन"}, {"key": "B", "en": "Narasimha", "hi": "नरसिंह"}, {"key": "C", "en": "Kurma", "hi": "कूर्म"}, {"key": "D", "en": "Varaha", "hi": "वराह"}]','B');
INSERT INTO knowledge_quiz VALUES(1566,'Which festival is celebrated as the harvest festival in North India?','उत्तर भारत में फसल पर्व के रूप में कौन सा त्योहार मनाया जाता है?','[{"key": "A", "en": "Pongal", "hi": "पोंगल"}, {"key": "B", "en": "Baisakhi", "hi": "बैसाखी"}, {"key": "C", "en": "Onam", "hi": "ओणम"}, {"key": "D", "en": "Lohri", "hi": "लोहड़ी"}]','B');
INSERT INTO knowledge_quiz VALUES(1567,'Which goddess is worshipped during Bonalu festival?','बोनालु पर्व में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Mahakali", "hi": "महाकाली"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Lakshmi", "hi": "लक्ष्मी"}]','B');
INSERT INTO knowledge_quiz VALUES(1568,'Which scripture contains the story of Savitri and Satyavan?','सावित्री और सत्यवान की कथा किस ग्रंथ में मिलती है?','[{"key": "A", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "B", "en": "Ramayana", "hi": "रामायण"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Padma Purana", "hi": "पद्म पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(1569,'Which god is known as the lord of beginnings?','आरंभ के देवता किसे कहा जाता है?','[{"key": "A", "en": "Ganesha", "hi": "गणेश"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','A');
INSERT INTO knowledge_quiz VALUES(1570,'Which temple is associated with Lord Ayyappa?','भगवान अयप्पा से कौन सा मंदिर जुड़ा है?','[{"key": "A", "en": "Guruvayur", "hi": "गुरुवायूर"}, {"key": "B", "en": "Sabarimala", "hi": "सबरीमला"}, {"key": "C", "en": "Rameswaram", "hi": "रामेश्वरम"}, {"key": "D", "en": "Chidambaram", "hi": "चिदंबरम"}]','B');
