INSERT INTO knowledge_quiz VALUES(1610,'Which god is known as the preserver in the Trimurti?','त्रिमूर्ति में पालनकर्ता देवता कौन हैं?','[{"key": "A", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1611,'Which rishi is associated with the Rigveda?','ऋग्वेद किन ऋषियों से संबंधित है?','[{"key": "A", "en": "Only Vishwamitra", "hi": "केवल विश्वामित्र"}, {"key": "B", "en": "Only Vashistha", "hi": "केवल वशिष्ठ"}, {"key": "C", "en": "Many rishis", "hi": "अनेक ऋषि"}, {"key": "D", "en": "Only Agastya", "hi": "केवल अगस्त्य"}]','C');
INSERT INTO knowledge_quiz VALUES(1612,'What is the name of the sacred waterfall located near the Tirumala temple, believed to wash away sins?','तिरुपति मंदिर के पास स्थित उस पवित्र जलप्रपात का नाम क्या है, जिसके बारे में मान्यता है कि वह पापों को धो देता है?','[{"key": "A", "en": "Akasa Ganga", "hi": "आकाश गंगा"}, {"key": "B", "en": "Papanasanam", "hi": "पापनाशनम"}, {"key": "C", "en": "Kapila Theertham", "hi": "कपिला तीर्थम"}, {"key": "D", "en": "Chakra Theertham", "hi": "चक्र तीर्थम"}]','B');
INSERT INTO knowledge_quiz VALUES(1613,'Which scripture contains the dialogue of Nachiketa and Yama?','नचिकेता और यम का संवाद किस ग्रंथ में है?','[{"key": "A", "en": "Kena Upanishad", "hi": "केन उपनिषद"}, {"key": "B", "en": "Katha Upanishad", "hi": "कठ उपनिषद"}, {"key": "C", "en": "Isha Upanishad", "hi": "ईश उपनिषद"}, {"key": "D", "en": "Mundaka Upanishad", "hi": "मुण्डक उपनिषद"}]','B');
INSERT INTO knowledge_quiz VALUES(1614,'Which of the following is not one of the ''Panchamrit'' ingredients used for Abhishekam?','अभिषेक के लिए उपयोग की जाने वाली ''पंचामृत'' सामग्रियों में इनमें से कौन सी शामिल नहीं है?','[{"key": "A", "en": "Milk", "hi": "दूध"}, {"key": "B", "en": "Honey", "hi": "शहद"}, {"key": "C", "en": "Ghee", "hi": "घी"}, {"key": "D", "en": "Coconut Water", "hi": "नारियल पानी"}]','D');
INSERT INTO knowledge_quiz VALUES(1615,'In the Hanuman Chalisa, the line ''Sahasa badana tumharo yasha gaavai'' refers to a ''thousand-mouthed'' being singing Hanuman''s glory. Who is this being?','हनुमान चालीसा की पंक्ति ''सहस बदन तुम्हरो यस गावै'' में हनुमान का यश गाने वाले ''हज़ार मुख'' वाले जीव का उल्लेख है। यह जीव कौन है?','[{"key": "A", "en": "Lord Brahma", "hi": "भगवान ब्रह्मा"}, {"key": "B", "en": "Sheshnag", "hi": "शेषनाग"}, {"key": "C", "en": "Ravana", "hi": "रावण"}, {"key": "D", "en": "Airavata", "hi": "ऐरावत"}]','B');
INSERT INTO knowledge_quiz VALUES(1616,'Which sacred text explains the concept of Karma in detail?','कर्म के सिद्धांत को विस्तार से कौन सा ग्रंथ समझाता है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "C", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "D", "en": "Natya Shastra", "hi": "नाट्यशास्त्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1617,'Which temple is dedicated to Lord Krishna in Vrindavan?','वृंदावन में भगवान कृष्ण को समर्पित प्रमुख मंदिर कौन सा है?','[{"key": "A", "en": "Banke Bihari Temple", "hi": "बांके बिहारी मंदिर"}, {"key": "B", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}, {"key": "C", "en": "Dwarkadhish Temple", "hi": "द्वारकाधीश मंदिर"}, {"key": "D", "en": "Somnath Temple", "hi": "सोमनाथ मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(1618,'Which deity is worshipped during Sharad Purnima?','शरद पूर्णिमा पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Chandra", "hi": "चंद्र"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1619,'In which pond (Kund) in Nashik do pilgrims take a holy dip during the Kumbh Mela?','कुंभ मेले के दौरान तीर्थयात्री नासिक के किस कुंड में पवित्र डुबकी लगाते हैं?','[{"key": "A", "en": "Ram Kund", "hi": "राम कुंड"}, {"key": "B", "en": "Surya Kund", "hi": "सूर्य कुंड"}, {"key": "C", "en": "Kushavarta Kund", "hi": "कुशावर्त कुंड"}, {"key": "D", "en": "Tapt Kund", "hi": "तप्त कुंड"}]','A');
INSERT INTO knowledge_quiz VALUES(1620,'Which goddess is worshipped as Shakti?','शक्ति के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','B');
INSERT INTO knowledge_quiz VALUES(1621,'Which scripture describes the four Ashramas?','चार आश्रमों का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Dharmashastras", "hi": "धर्मशास्त्र"}, {"key": "C", "en": "Vedas", "hi": "वेद"}, {"key": "D", "en": "Aranyakas", "hi": "आरण्यक"}]','B');
INSERT INTO knowledge_quiz VALUES(1622,'Which deity is worshipped during Kartik Maas?','कार्तिक मास में किस देवता की पूजा की जाती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1623,'Which river is considered sacred in Odisha?','ओडिशा में कौन सी नदी पवित्र मानी जाती है?','[{"key": "A", "en": "Mahanadi", "hi": "महानदी"}, {"key": "B", "en": "Brahmani", "hi": "ब्रह्मणी"}, {"key": "C", "en": "Baitarani", "hi": "बैतरिणी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1624,'Which deity is worshipped during Tulsi Vivah?','तुलसी विवाह में किस देवता की पूजा होती है?','[{"key": "A", "en": "Rama", "hi": "राम"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','B');
INSERT INTO knowledge_quiz VALUES(1625,'Which epic describes the life of Lord Rama?','भगवान राम के जीवन का वर्णन किस महाकाव्य में है?','[{"key": "A", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "B", "en": "Ramayana", "hi": "रामायण"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Harivamsa", "hi": "हरिवंश"}]','B');
INSERT INTO knowledge_quiz VALUES(1626,'Which goddess is worshipped during Kojagiri Purnima?','कोजागरी पूर्णिमा पर किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(1627,'Which rishi is associated with the Aitareya Upanishad?','ऐतरेय उपनिषद किस ऋषि से संबंधित है?','[{"key": "A", "en": "Aitareya", "hi": "ऐतरेय"}, {"key": "B", "en": "Yajnavalkya", "hi": "याज्ञवल्क्य"}, {"key": "C", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "D", "en": "Vashistha", "hi": "वशिष्ठ"}]','A');
INSERT INTO knowledge_quiz VALUES(1628,'Which deity is worshipped during Bhai Dooj?','भाई दूज पर किस देवता/देवी की पूजा होती है?','[{"key": "A", "en": "Yama", "hi": "यम"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','A');
INSERT INTO knowledge_quiz VALUES(1629,'Which sacred plant is worshipped daily in Hindu homes?','हिंदू घरों में प्रतिदिन किस पवित्र पौधे की पूजा होती है?','[{"key": "A", "en": "Peepal", "hi": "पीपल"}, {"key": "B", "en": "Banyan", "hi": "वट"}, {"key": "C", "en": "Tulsi", "hi": "तुलसी"}, {"key": "D", "en": "Neem", "hi": "नीम"}]','C');
INSERT INTO knowledge_quiz VALUES(1630,'Which of the Panch Kedar temples is accessible throughout the year?','पंच केदार मंदिरों में से कौन सा मंदिर पूरे वर्ष सुलभ रहता है?','[{"key": "A", "en": "Tungnath", "hi": "तुंगनाथ"}, {"key": "B", "en": "Madmaheshwar", "hi": "मदमहेश्वर"}, {"key": "C", "en": "Kalpeshwar", "hi": "कल्पेश्वर"}, {"key": "D", "en": "Rudranath", "hi": "रुद्रनाथ"}]','C');
INSERT INTO knowledge_quiz VALUES(1631,'Which scripture contains the Vishnu Sahasranama?','विष्णु सहस्रनाम किस ग्रंथ में है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "D", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1632,'Which festival marks the worship of tools and machines?','औजारों और मशीनों की पूजा किस पर्व पर होती है?','[{"key": "A", "en": "Ayudha Puja", "hi": "आयुध पूजा"}, {"key": "B", "en": "Onam", "hi": "ओणम"}, {"key": "C", "en": "Pongal", "hi": "पोंगल"}, {"key": "D", "en": "Baisakhi", "hi": "बैसाखी"}]','A');
INSERT INTO knowledge_quiz VALUES(1633,'Which deity is worshipped during Margashirsha month?','मार्गशीर्ष मास में किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1634,'Which temple is located at the highest point of Gujarat on the Girnar hills?','गिरनार पहाड़ियों पर गुजरात के सबसे ऊंचे बिंदु पर कौन सा मंदिर स्थित है?','[{"key": "A", "en": "Ambaji Temple", "hi": "अम्बाजी मंदिर"}, {"key": "B", "en": "Gorakhnath Temple", "hi": "गोरखनाथ मंदिर"}, {"key": "C", "en": "Dattatreya Temple", "hi": "दत्तात्रेय मंदिर"}, {"key": "D", "en": "Neminath Temple", "hi": "नेमिनाथ मंदिर"}]','C');
INSERT INTO knowledge_quiz VALUES(1635,'Which goddess is worshipped during Sharad Navratri?','शारदीय नवरात्रि में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','C');
INSERT INTO knowledge_quiz VALUES(1636,'The Sthaneshwar Mahadev Temple, where the Pandavas prayed to Lord Shiva, is located in which town?','स्थानेश्वर महादेव मंदिर, जहाँ पांडवों ने भगवान शिव की प्रार्थना की थी, किस शहर में स्थित है?','[{"key": "A", "en": "Thanesar", "hi": "थानेसर"}, {"key": "B", "en": "Pehowa", "hi": "पेहोवा"}, {"key": "C", "en": "Panipat", "hi": "पानीपत"}, {"key": "D", "en": "Rohtak", "hi": "रोहतक"}]','A');
INSERT INTO knowledge_quiz VALUES(1637,'Which scripture is known as the fifth Veda?','किस ग्रंथ को पंचम वेद कहा जाता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Natya Shastra", "hi": "नाट्यशास्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1638,'Which goddess is worshipped during Gauri Puja?','गौरी पूजा में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(1639,'Which temple in Prayagraj is famous for its unique ''reclining'' or ''lying'' posture of Hanuman Ji?','प्रयागराज का कौन सा मंदिर हनुमान जी की अनूठी ''लेटी हुई'' मुद्रा के लिए प्रसिद्ध है?','[{"key": "A", "en": "Alopi Devi Temple", "hi": "अलोपी देवी मंदिर"}, {"key": "B", "en": "Bade Hanuman Temple", "hi": "बड़े हनुमान मंदिर"}, {"key": "C", "en": "Patalpuri Temple", "hi": "पातालपुरी मंदिर"}, {"key": "D", "en": "Shankar Viman Mandapam", "hi": "शंकर विमान मंडपम"}]','B');
INSERT INTO knowledge_quiz VALUES(1640,'The concluding lines of most Aartiyan ask for ''Kshama'' from the deity. What does ''Kshama'' mean?','अधिकांश आरतियों की अंतिम पंक्तियों में देवता से ''क्षमा'' मांगी जाती है। ''क्षमा'' का क्या अर्थ है?','[{"key": "A", "en": "Wealth", "hi": "धन"}, {"key": "B", "en": "Forgiveness", "hi": "माफी/क्षमा"}, {"key": "C", "en": "Power", "hi": "शक्ति"}, {"key": "D", "en": "Victory", "hi": "विजय"}]','B');
