INSERT INTO knowledge_quiz VALUES(1642,'Which sacred river flows through Haridwar?','हरिद्वार से होकर कौन सी पवित्र नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Alaknanda", "hi": "अलकनंदा"}]','B');
INSERT INTO knowledge_quiz VALUES(1643,'Which scripture is attributed to Sage Vyasa?','ऋषि व्यास से संबंधित कौन सा ग्रंथ है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "D", "en": "Nyaya Sutra", "hi": "न्याय सूत्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1644,'Which holy tank in Kurukshetra is believed to be the spot where Lord Brahma created the universe?','कुरुक्षेत्र का कौन सा पवित्र सरोवर माना जाता है कि यहाँ भगवान ब्रह्मा ने ब्रह्मांड की रचना की थी?','[{"key": "A", "en": "Sannihit Sarovar", "hi": "सन्निहित सरोवर"}, {"key": "B", "en": "Brahma Sarovar", "hi": "ब्रह्म सरोवर"}, {"key": "C", "en": "Jyotisar", "hi": "ज्योतिसर"}, {"key": "D", "en": "Ban Ganga", "hi": "बाण गंगा"}]','B');
INSERT INTO knowledge_quiz VALUES(1645,'Which festival celebrates the bond between brothers and sisters?','भाई-बहन के बंधन का उत्सव कौन सा है?','[{"key": "A", "en": "Raksha Bandhan", "hi": "रक्षा बंधन"}, {"key": "B", "en": "Bhai Dooj", "hi": "भाई दूज"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Teej", "hi": "तीज"}]','C');
INSERT INTO knowledge_quiz VALUES(1646,'Which deity is worshipped in the form of Shaligram?','शालिग्राम के रूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1647,'Which river is associated with Lord Rama’s exile period?','भगवान राम के वनवास काल से कौन सी नदी जुड़ी है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Godavari", "hi": "गोदावरी"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','C');
INSERT INTO knowledge_quiz VALUES(1648,'Which rishi is associated with the Yoga philosophy?','योग दर्शन किस ऋषि से संबंधित है?','[{"key": "A", "en": "Kapila", "hi": "कपिल"}, {"key": "B", "en": "Patanjali", "hi": "पतंजलि"}, {"key": "C", "en": "Jaimini", "hi": "जैमिनि"}, {"key": "D", "en": "Vyasa", "hi": "व्यास"}]','B');
INSERT INTO knowledge_quiz VALUES(1649,'Which sacred animal is the vehicle of Goddess Durga?','देवी दुर्गा का वाहन कौन सा पवित्र पशु है?','[{"key": "A", "en": "Lion", "hi": "सिंह"}, {"key": "B", "en": "Tiger", "hi": "बाघ"}, {"key": "C", "en": "Bull", "hi": "वृषभ"}, {"key": "D", "en": "Elephant", "hi": "हाथी"}]','B');
INSERT INTO knowledge_quiz VALUES(1650,'Which deity is worshipped during Ram Navami?','राम नवमी पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Rama", "hi": "राम"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','B');
INSERT INTO knowledge_quiz VALUES(1651,'Who was the eldest among the Pandavas?','पांडवों में सबसे बड़े कौन थे?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "D", "en": "Nakula", "hi": "नकुल"}]','C');
INSERT INTO knowledge_quiz VALUES(1652,'Which river is called the ''Ganga of the South''?','किस नदी को दक्षिण की गंगा कहा जाता है?','[{"key": "A", "en": "Krishna", "hi": "कृष्णा"}, {"key": "B", "en": "Godavari", "hi": "गोदावरी"}, {"key": "C", "en": "Kaveri", "hi": "कावेरी"}, {"key": "D", "en": "Periyar", "hi": "पेरियार"}]','B');
INSERT INTO knowledge_quiz VALUES(1653,'Which rishi composed the Ramayana?','रामायण की रचना किस ऋषि ने की?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "C", "en": "Tulsidas", "hi": "तुलसीदास"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1654,'The ''Viraat Ramayan Mandir'', currently under construction in East Champaran, aims to be larger than which world-famous temple?','पूर्वी चंपारण में निर्माणाधीन ''विराट रामायण मंदिर'' का लक्ष्य किस विश्व प्रसिद्ध मंदिर से बड़ा होना है?','[{"key": "A", "en": "Prambanan", "hi": "प्रम्बानन"}, {"key": "B", "en": "Angkor Wat", "hi": "अंगकोर वाट"}, {"key": "C", "en": "Akshardham", "hi": "अक्षरधाम"}, {"key": "D", "en": "Kashi Vishwanath", "hi": "काशी विश्वनाथ"}]','B');
INSERT INTO knowledge_quiz VALUES(1655,'Which goddess is worshipped as the consort of Vishnu?','भगवान विष्णु की पत्नी के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','C');
INSERT INTO knowledge_quiz VALUES(1656,'Which Purana primarily focuses on Lord Shiva?','कौन सा पुराण मुख्य रूप से भगवान शिव पर केंद्रित है?','[{"key": "A", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "B", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Markandeya Purana", "hi": "मार्कण्डेय पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1657,'Which deity is worshipped during Dhanteras?','धनतेरस पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Kubera", "hi": "कुबेर"}, {"key": "B", "en": "Yama", "hi": "यम"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1658,'Which sacred city is known as the birthplace of Lord Krishna?','भगवान कृष्ण की जन्मभूमि के रूप में कौन सा नगर प्रसिद्ध है?','[{"key": "A", "en": "Vrindavan", "hi": "वृंदावन"}, {"key": "B", "en": "Mathura", "hi": "मथुरा"}, {"key": "C", "en": "Dwarka", "hi": "द्वारका"}, {"key": "D", "en": "Gokul", "hi": "गोकुल"}]','B');
INSERT INTO knowledge_quiz VALUES(1659,'Which river is associated with Lord Rama’s birthplace Ayodhya?','भगवान राम की जन्मभूमि अयोध्या किस नदी से जुड़ी है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','C');
INSERT INTO knowledge_quiz VALUES(1660,'The Parli Vaijnath temple is associated with which legendary figure who performed penance there?','परली वैजनाथ मंदिर किस पौराणिक पात्र से जुड़ा है जिन्होंने वहां तपस्या की थी?','[{"key": "A", "en": "Ravana", "hi": "रावण"}, {"key": "B", "en": "Markandeya", "hi": "मार्कंडेय"}, {"key": "C", "en": "Satyavan-Savitri", "hi": "सत्यवान-सावित्री"}, {"key": "D", "en": "Both A and C", "hi": "A और C दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(1661,'Which Veda deals mainly with rituals and sacrifices?','कौन सा वेद मुख्य रूप से यज्ञ और कर्मकांड से संबंधित है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Samaveda", "hi": "सामवेद"}, {"key": "C", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','C');
INSERT INTO knowledge_quiz VALUES(1662,'Which festival marks the victory of Lord Rama over Ravana?','भगवान राम की रावण पर विजय का पर्व कौन सा है?','[{"key": "A", "en": "Diwali", "hi": "दीपावली"}, {"key": "B", "en": "Dussehra", "hi": "दशहरा"}, {"key": "C", "en": "Ram Navami", "hi": "राम नवमी"}, {"key": "D", "en": "Hanuman Jayanti", "hi": "हनुमान जयंती"}]','B');
INSERT INTO knowledge_quiz VALUES(1663,'Which Upanishad begins with the phrase ''Isha vasyam idam sarvam''?','''ईशावास्यमिदं सर्वम्'' किस उपनिषद से लिया गया है?','[{"key": "A", "en": "Kena Upanishad", "hi": "केन उपनिषद"}, {"key": "B", "en": "Isha Upanishad", "hi": "ईश उपनिषद"}, {"key": "C", "en": "Mundaka Upanishad", "hi": "मुण्डक उपनिषद"}, {"key": "D", "en": "Prashna Upanishad", "hi": "प्रश्न उपनिषद"}]','B');
INSERT INTO knowledge_quiz VALUES(1664,'Which deity is worshipped during Hanuman Jayanti?','हनुमान जयंती पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Rama", "hi": "राम"}, {"key": "B", "en": "Bajrangbali", "hi": "बजरंगबली"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Vayu", "hi": "वायु"}]','B');
INSERT INTO knowledge_quiz VALUES(1665,'Which goddess is worshipped during Navratri as Mahalakshmi?','नवरात्रि में महालक्ष्मी रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(1666,'Which sacred text is also known as Vedanta?','किस ग्रंथ को वेदांत भी कहा जाता है?','[{"key": "A", "en": "Brahmanas", "hi": "ब्राह्मण"}, {"key": "B", "en": "Aranyakas", "hi": "आरण्यक"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Samhitas", "hi": "संहिता"}]','C');
INSERT INTO knowledge_quiz VALUES(1667,'The Madhukeshwara Temple, one of the oldest in Karnataka, is the primary attraction of which ancient capital?','मधुकेश्वर मंदिर, जो कर्नाटक के सबसे पुराने मंदिरों में से एक है, किस प्राचीन राजधानी का मुख्य आकर्षण है?','[{"key": "A", "en": "Hampi", "hi": "हम्पी"}, {"key": "B", "en": "Banavasi", "hi": "बणवासी"}, {"key": "C", "en": "Badami", "hi": "बादामी"}, {"key": "D", "en": "Bidar", "hi": "बीदर"}]','B');
INSERT INTO knowledge_quiz VALUES(1668,'Which instrument''s sound during Aarti is believed to dispel negative thoughts and sync the left and right hemispheres of the brain?','आरती के दौरान किस वाद्य यंत्र की ध्वनि के बारे में माना जाता है कि वह नकारात्मक विचारों को दूर करती है और मस्तिष्क के बाएं और दाएं गोलार्ध को संतुलित करती है?','[{"key": "A", "en": "Flute", "hi": "बांसुरी"}, {"key": "B", "en": "Temple Bell", "hi": "मंदिर की घंटी"}, {"key": "C", "en": "Harmonium", "hi": "हारमोनियम"}, {"key": "D", "en": "Tabla", "hi": "तबला"}]','B');
INSERT INTO knowledge_quiz VALUES(1669,'Which deity is worshipped during Chaitra Navratri?','चैत्र नवरात्रि में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','A');
INSERT INTO knowledge_quiz VALUES(1670,'Which god is worshipped as the teacher of the gods?','देवताओं के गुरु के रूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Brihaspati", "hi": "बृहस्पति"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','A');
INSERT INTO knowledge_quiz VALUES(1671,'Which temple in Ayodhya is said to have been gifted to Mata Sita by Kaikeyi as a ''Munhdikhayi'' (wedding gift)?','अयोध्या के किस मंदिर के बारे में कहा जाता है कि उसे कैकेयी ने माता सीता को ''मुंहदिखाई'' के उपहार के रूप में दिया था?','[{"key": "A", "en": "Dashrath Mahal", "hi": "दशरथ महल"}, {"key": "B", "en": "Kanak Bhawan", "hi": "कनक भवन"}, {"key": "C", "en": "Mani Parvat", "hi": "मणि पर्वत"}, {"key": "D", "en": "Sita Ki Rasoi", "hi": "सीता की रसोई"}]','B');
INSERT INTO knowledge_quiz VALUES(1672,'Which goddess is worshipped during Varaha Jayanti?','वराह जयंती पर किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Earth (Bhudevi)", "hi": "भूमि (भूदेवी)"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(1673,'Which deity is worshipped during Pitru Paksha?','पितृ पक्ष में किसकी पूजा की जाती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Ancestors", "hi": "पितर"}, {"key": "C", "en": "Yama", "hi": "यम"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1674,'How many ''Chaupais'' (verses) are there in the main body of the Hanuman Chalisa?','हनुमान चालीसा के मुख्य भाग में कितनी ''चौपाइयाँ'' (छंद) हैं?','[{"key": "A", "en": "10", "hi": "10"}, {"key": "B", "en": "40", "hi": "40"}, {"key": "C", "en": "108", "hi": "108"}, {"key": "D", "en": "100", "hi": "100"}]','B');
INSERT INTO knowledge_quiz VALUES(1675,'Which god is worshipped as the lord of death?','मृत्यु के देवता किसे कहा जाता है?','[{"key": "A", "en": "Varuna", "hi": "वरुण"}, {"key": "B", "en": "Yama", "hi": "यम"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1676,'Which scripture contains the story of Savitri and Satyavan?','सावित्री और सत्यवान की कथा किस ग्रंथ में मिलती है?','[{"key": "A", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "B", "en": "Ramayana", "hi": "रामायण"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(1677,'The ''Panchopachara'' puja involves offering how many types of services or items to the deity?','''पंचोपचार'' पूजा में देवता को कितने प्रकार की सेवाएँ या वस्तुएँ अर्पित की जाती हैं?','[{"key": "A", "en": "3", "hi": "3"}, {"key": "B", "en": "5", "hi": "5"}, {"key": "C", "en": "16", "hi": "16"}, {"key": "D", "en": "108", "hi": "108"}]','B');
INSERT INTO knowledge_quiz VALUES(1678,'Which sacred text is known as the ''Song of the Lord''?','''भगवान का गीत'' किस ग्रंथ को कहा जाता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Vedas", "hi": "वेद"}]','B');
INSERT INTO knowledge_quiz VALUES(1679,'Which river is associated with Kedarnath?','केदारनाथ किस नदी से जुड़ा है?','[{"key": "A", "en": "Alaknanda", "hi": "अलकनंदा"}, {"key": "B", "en": "Mandakini", "hi": "मंदाकिनी"}, {"key": "C", "en": "Bhagirathi", "hi": "भागीरथी"}, {"key": "D", "en": "Yamuna", "hi": "यमुना"}]','B');
INSERT INTO knowledge_quiz VALUES(1680,'Which temple in Telangana is the only UNESCO World Heritage site in the state, known for its ''floating bricks''?','तेलंगाना का कौन सा मंदिर राज्य का एकमात्र यूनेस्को विश्व धरोहर स्थल है, जो अपनी ''तैरने वाली ईंटों'' के लिए जाना जाता है?','[{"key": "A", "en": "Thousand Pillar Temple", "hi": "हजार स्तंभ मंदिर"}, {"key": "B", "en": "Ramappa Temple", "hi": "रामप्पा मंदिर"}, {"key": "C", "en": "Bhadrachalam Temple", "hi": "भद्राचलम मंदिर"}, {"key": "D", "en": "Yadadri Temple", "hi": "यादाद्री मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(1681,'Which specific Aarti is performed to put the deity to rest at night in major temples like ISKCON or Kashi Vishwanath?','इस्कॉन या काशी विश्वनाथ जैसे प्रमुख मंदिरों में रात को देवता को सुलाने के लिए कौन सी विशिष्ट आरती की जाती है?','[{"key": "A", "en": "Sandhya Aarti", "hi": "संध्या आरती"}, {"key": "B", "en": "Shayan Aarti", "hi": "शयन आरती"}, {"key": "C", "en": "Rajbhog Aarti", "hi": "राजभोग आरती"}, {"key": "D", "en": "Dhoop Aarti", "hi": "धूप आरती"}]','B');
INSERT INTO knowledge_quiz VALUES(1682,'Which place near Rameshwaram is known as the ghost town?','रामेश्वरम के पास किस स्थान को ''भूतिया शहर जाना जाता है?','[{"key": "A", "en": "Dhanushkodi", "hi": "धनुषकोडी"}, {"key": "B", "en": "Mandapam", "hi": "मंडपम"}, {"key": "C", "en": "Rameswaram City", "hi": "रामेश्वरम शहर"}, {"key": "D", "en": "Tuticorin", "hi": "तूतीकोरिन"}]','A');
INSERT INTO knowledge_quiz VALUES(1683,'Which scripture describes the duties of kings?','राजाओं के कर्तव्यों का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "B", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Upanishads", "hi": "उपनिषद"}]','C');
INSERT INTO knowledge_quiz VALUES(1684,'According to Puranas, whose sight caused Shani Dev''s gaze to become destructive?','पुराण के अनुसार, किसकी दृष्टि के कारण शनि देव की दृष्टि विनाशकारी हो गई थी?','[{"key": "A", "en": "Dhamini", "hi": "धामिनी"}, {"key": "B", "en": "Lord Shiva", "hi": "भगवान शिव"}, {"key": "C", "en": "Sage Durvasa", "hi": "ऋषि दुर्वासा"}, {"key": "D", "en": "Goddess Parvati", "hi": "देवी पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(1685,'The famous Aarti ''Om Jai Jagdish Hare'' was composed by which 19th-century social reformer?','प्रसिद्ध आरती ''ओम जय जगदीश हरे'' की रचना 19वीं सदी के किस समाज सुधारक ने की थी?','[{"key": "A", "en": "Ramakrishna Paramahansa", "hi": "रामकृष्ण परमहंस"}, {"key": "B", "en": "Shraddha Ram Phillauri", "hi": "श्रद्धा राम फिल्लौरी"}, {"key": "C", "en": "Dayanand Saraswati", "hi": "दयानंद सरस्वती"}, {"key": "D", "en": "Vivekananda", "hi": "विवेकानंद"}]','B');
INSERT INTO knowledge_quiz VALUES(1686,'Which deity is worshipped during Ayyappa Mandala Puja?','अयप्पा मंडल पूजा में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Ayyappa", "hi": "अयप्पा"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Murugan", "hi": "मुरुगन"}]','B');
INSERT INTO knowledge_quiz VALUES(1687,'Which sacred river flows through Varanasi?','वाराणसी से होकर कौन सी पवित्र नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','B');
INSERT INTO knowledge_quiz VALUES(1688,'Which scripture is known as the fifth Veda?','किस ग्रंथ को पंचम वेद कहा जाता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Natya Shastra", "hi": "नाट्यशास्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1689,'Which goddess is worshipped during Gauri Puja?','गौरी पूजा में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(1690,'Which temple in Haryana is dedicated to the 11th incarnation of Lord Rudra and features a massive statue of Hanuman?','हरियाणा का कौन सा मंदिर भगवान रुद्र के 11वें अवतार को समर्पित है और इसमें हनुमान जी की विशाल मूर्ति है?','[{"key": "A", "en": "Gyarah Rudri Siva Temple", "hi": "ग्यारह रुद्री शिव मंदिर"}, {"key": "B", "en": "Birla Mandir", "hi": "बिड़ला मंदिर"}, {"key": "C", "en": "Agroha Dham", "hi": "अग्रोहा धाम"}, {"key": "D", "en": "Kartikeya Temple", "hi": "कार्तिकेय मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(1691,'Which deity is worshipped during Ram Navami?','राम नवमी पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Rama", "hi": "राम"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','B');
INSERT INTO knowledge_quiz VALUES(1692,'In the Hanuman Chalisa, the phrase ''Kanchana barana biraja subesa'' describes Hanuman''s complexion as being like what?','हनुमान चालीसा में ''कंचन बरन बिराज सुबेसा'' में हनुमान के रंग की तुलना किससे की गई है?','[{"key": "A", "en": "Silver", "hi": "चांदी"}, {"key": "B", "en": "Gold", "hi": "सोना"}, {"key": "C", "en": "Copper", "hi": "तांबा"}, {"key": "D", "en": "Cloud", "hi": "बादल"}]','B');
INSERT INTO knowledge_quiz VALUES(1693,'Which scripture narrates the life of Lord Krishna?','भगवान कृष्ण के जीवन का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Harivamsa", "hi": "हरिवंश"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1694,'Who is the mother of the 11 Rudras?','11 रुद्रों की माता कौन हैं?','[{"key": "A", "en": "Aditi", "hi": "अदिति"}, {"key": "B", "en": "Surabhi", "hi": "सुरभि"}, {"key": "C", "en": "Diti", "hi": "दिति"}, {"key": "D", "en": "Danu", "hi": "दनु"}]','B');
INSERT INTO knowledge_quiz VALUES(1695,'Which sacred plant is worshipped daily in Hindu homes?','हिंदू घरों में प्रतिदिन किस पवित्र पौधे की पूजा होती है?','[{"key": "A", "en": "Peepal", "hi": "पीपल"}, {"key": "B", "en": "Tulsi", "hi": "तुलसी"}, {"key": "C", "en": "Neem", "hi": "नीम"}, {"key": "D", "en": "Banyan", "hi": "वट"}]','B');
INSERT INTO knowledge_quiz VALUES(1696,'In Gangotri, the submerged Shivling is visible only during which time?','गंगोत्री में, जलमग्न शिवलिंग केवल किस समय दिखाई देता है?','[{"key": "A", "en": "During Monsoons", "hi": "मानसून के दौरान"}, {"key": "B", "en": "Peak Summer", "hi": "कड़कड़ाती गर्मियों में"}, {"key": "C", "en": "Winter", "hi": "सर्दियों में"}, {"key": "D", "en": "On every Purnima", "hi": "प्रत्येक पूर्णिमा को"}]','C');
INSERT INTO knowledge_quiz VALUES(1697,'The ''Khatu Shyam Chalisa'' is dedicated to Barbareek. Who gave him the name ''Shyam''?','''खाटू श्याम चालीसा'' बर्बरीक को समर्पित है। उन्हें ''श्याम'' नाम किसने दिया था?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Lord Krishna", "hi": "भगवान कृष्ण"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Pandu", "hi": "पांडु"}]','B');
INSERT INTO knowledge_quiz VALUES(1698,'Which scripture contains the Vishnu Sahasranama?','विष्णु सहस्रनाम किस ग्रंथ में मिलता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "D", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1699,'Which famous Aarti mentions ''Shankh Chakra Gada Padma'' as the four symbols held by Lord Vishnu?','किस प्रसिद्ध आरती में ''शंख चक्र गदा पद्म'' का उल्लेख भगवान विष्णु द्वारा धारण किए गए चार प्रतीकों के रूप में किया गया है?','[{"key": "A", "en": "Om Jai Jagdish Hare", "hi": "ओम जय जगदीश हरे"}, {"key": "B", "en": "Jai Laxmi Ramana", "hi": "जय लक्ष्मी रमणा"}, {"key": "C", "en": "Vishnu Chalisa", "hi": "विष्णु चालीसा"}, {"key": "D", "en": "Both A and B", "hi": "A और B दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(1700,'Which deity is worshipped during Govardhan Puja?','गोवर्धन पूजा में किस देवता की पूजा होती है?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(1701,'Who was the wife of King Pandu?','राजा पांडु की पत्नी कौन थीं?','[{"key": "A", "en": "Gandhari", "hi": "गांधारी"}, {"key": "B", "en": "Kunti", "hi": "कुंती"}, {"key": "C", "en": "Madri", "hi": "माद्री"}, {"key": "D", "en": "Both B and C", "hi": "B और C दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(1702,'The ''Mukti Gupteshwar'' temple, which houses a man-made cave for 12 Jyotirlingas, is located in which country?','''मुक्ति गुप्तेश्वर'' मंदिर, जिसमें 12 ज्योतिर्लिंगों के लिए एक मानव निर्मित गुफा है, किस देश में स्थित है?','[{"key": "A", "en": "United Kingdom", "hi": "यूनाइटेड किंगडम"}, {"key": "B", "en": "Australia", "hi": "ऑस्ट्रेलिया"}, {"key": "C", "en": "Canada", "hi": "कनाडा"}, {"key": "D", "en": "South Africa", "hi": "दक्षिण अफ्रीका"}]','B');
INSERT INTO knowledge_quiz VALUES(1703,'Which rishi is associated with the Gayatri Mantra?','गायत्री मंत्र किस ऋषि से संबंधित है?','[{"key": "A", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "B", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "C", "en": "Vishwamitra", "hi": "विश्वामित्र"}, {"key": "D", "en": "Bharadwaja", "hi": "भरद्वाज"}]','C');
INSERT INTO knowledge_quiz VALUES(1704,'Which festival marks the return of Lord Rama to Ayodhya?','भगवान राम के अयोध्या लौटने का पर्व कौन सा है?','[{"key": "A", "en": "Dussehra", "hi": "दशहरा"}, {"key": "B", "en": "Diwali", "hi": "दीपावली"}, {"key": "C", "en": "Ram Navami", "hi": "राम नवमी"}, {"key": "D", "en": "Holi", "hi": "होली"}]','B');
INSERT INTO knowledge_quiz VALUES(1705,'Which goddess is worshipped as the goddess of wealth?','धन की देवी के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(1706,'Which Purana describes the cosmic dance of Lord Shiva?','भगवान शिव के तांडव नृत्य का वर्णन किस पुराण में है?','[{"key": "A", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(1707,'Which deity is worshipped during Naraka Chaturdashi?','नरक चतुर्दशी पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Yama", "hi": "यम"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','A');
INSERT INTO knowledge_quiz VALUES(1708,'The 64 Yogini Temple, one of the few surviving circular temples in India, is located in which place near Bhubaneswar?','64 योगिनी मंदिर, भारत में जीवित बचे कुछ गोलाकार मंदिरों में से एक, भुवनेश्वर के पास किस स्थान पर स्थित है?','[{"key": "A", "en": "Hirapur", "hi": "हीरापुर"}, {"key": "B", "en": "Cuttack", "hi": "कटक"}, {"key": "C", "en": "Puri", "hi": "पुरी"}, {"key": "D", "en": "Sambalpur", "hi": "संभलपुर"}]','A');
INSERT INTO knowledge_quiz VALUES(1709,'Which river flows through Haridwar?','हरिद्वार से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Alaknanda", "hi": "अलकनंदा"}]','B');
INSERT INTO knowledge_quiz VALUES(1710,'Which god is known as the creator in the Trimurti?','त्रिमूर्ति में सृष्टिकर्ता देवता कौन हैं?','[{"key": "A", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1711,'Which Veda is the oldest among the four Vedas?','चारों वेदों में सबसे प्राचीन वेद कौन सा है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Samaveda", "hi": "सामवेद"}, {"key": "C", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','A');
INSERT INTO knowledge_quiz VALUES(1712,'The famous Tirupati Laddu, given as prasadam, has been granted which status to protect its authenticity?','प्रसाद के रूप में दिए जाने वाले प्रसिद्ध ''तिरुपति लड्डू'' की प्रामाणिकता की रक्षा के लिए इसे कौन सा दर्जा दिया गया है?','[{"key": "A", "en": "UNESCO Heritage", "hi": "यूनेस्को विरासत"}, {"key": "B", "en": "ISO Certification", "hi": "आईएसओ प्रमाणन"}, {"key": "C", "en": "Geographical Indication (GI Tag)", "hi": "भौगोलिक संकेत (GI टैग)"}, {"key": "D", "en": "National Treasure", "hi": "राष्ट्रीय धरोहर"}]','C');
INSERT INTO knowledge_quiz VALUES(1713,'Which Upanishad contains the teaching ''Tat Tvam Asi''?','''तत् त्वम् असि'' का उपदेश किस उपनिषद में है?','[{"key": "A", "en": "Katha Upanishad", "hi": "कठ उपनिषद"}, {"key": "B", "en": "Chandogya Upanishad", "hi": "छांदोग्य उपनिषद"}, {"key": "C", "en": "Isha Upanishad", "hi": "ईश उपनिषद"}, {"key": "D", "en": "Mundaka Upanishad", "hi": "मुण्डक उपनिषद"}]','B');
INSERT INTO knowledge_quiz VALUES(1714,'Which tree is considered sacred to Shani Dev?','कौन सा वृक्ष शनि देव के लिए पवित्र माना जाता है?','[{"key": "A", "en": "Banyan (Bargad)", "hi": "बरगद"}, {"key": "B", "en": "Peepal", "hi": "पीपल"}, {"key": "C", "en": "Neem", "hi": "नीम"}, {"key": "D", "en": "Tulsi", "hi": "तुलसी"}]','B');
INSERT INTO knowledge_quiz VALUES(1715,'Which goddess is worshipped during Teej festival?','तीज पर्व पर किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(1716,'Which sacred text explains the philosophy of Bhakti Yoga?','भक्ति योग के दर्शन को कौन सा ग्रंथ समझाता है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "C", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "D", "en": "Natya Shastra", "hi": "नाट्यशास्त्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1717,'The Ranakpur Jain Temple is famous for having how many intricately carved pillars, no two of which are alike?','रणकपुर जैन मंदिर कितने जटिल नक्काशीदार खंभों के लिए प्रसिद्ध है, जिनमें से कोई भी दो एक जैसे नहीं हैं?','[{"key": "A", "en": "1008", "hi": "1008"}, {"key": "B", "en": "1444", "hi": "1444"}, {"key": "C", "en": "560", "hi": "560"}, {"key": "D", "en": "720", "hi": "720"}]','B');
INSERT INTO knowledge_quiz VALUES(1718,'Which deity is worshipped during Sharad Purnima?','शरद पूर्णिमा पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Chandra", "hi": "चंद्र"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1719,'The ''Aarti Kunj Bihari Ki'' is a famous hymn dedicated to Lord Krishna. In which state''s temples is it most predominantly sung?','''आरती कुंज बिहारी की'' भगवान कृष्ण को समर्पित एक प्रसिद्ध आरती है। यह मुख्य रूप से किस राज्य के मंदिरों में गाई जाती है?','[{"key": "A", "en": "Gujarat", "hi": "गुजरात"}, {"key": "B", "en": "Uttar Pradesh", "hi": "उत्तर प्रदेश"}, {"key": "C", "en": "Maharashtra", "hi": "महाराष्ट्र"}, {"key": "D", "en": "Odisha", "hi": "ओडिशा"}]','B');
INSERT INTO knowledge_quiz VALUES(1720,'Which goddess is worshipped as Shakti?','शक्ति के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','B');
INSERT INTO knowledge_quiz VALUES(1721,'Which scripture describes the four Purusharthas?','चार पुरुषार्थों का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Dharmashastras", "hi": "धर्मशास्त्र"}, {"key": "C", "en": "Vedas", "hi": "वेद"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
