INSERT INTO knowledge_quiz VALUES(1723,'Which river is considered sacred in Odisha?','ओडिशा में कौन सी नदी पवित्र मानी जाती है?','[{"key": "A", "en": "Mahanadi", "hi": "महानदी"}, {"key": "B", "en": "Baitarani", "hi": "बैतरिणी"}, {"key": "C", "en": "Brahmani", "hi": "ब्रह्मणी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1724,'Which deity is worshipped during Tulsi Vivah?','तुलसी विवाह में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Rama", "hi": "राम"}]','B');
INSERT INTO knowledge_quiz VALUES(1725,'Which epic describes the Kurukshetra war?','कुरुक्षेत्र युद्ध का वर्णन किस महाकाव्य में है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Harivamsa", "hi": "हरिवंश"}, {"key": "D", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1726,'Which goddess is worshipped during Kojagiri Purnima?','कोजागरी पूर्णिमा पर किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(1727,'Which rishi is associated with the Aitareya Upanishad?','ऐतरेय उपनिषद किस ऋषि से संबंधित है?','[{"key": "A", "en": "Aitareya", "hi": "ऐतरेय"}, {"key": "B", "en": "Yajnavalkya", "hi": "याज्ञवल्क्य"}, {"key": "C", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "D", "en": "Vashistha", "hi": "वशिष्ठ"}]','A');
INSERT INTO knowledge_quiz VALUES(1728,'Which deity is worshipped during Bhai Dooj?','भाई दूज पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Yama", "hi": "यम"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','A');
INSERT INTO knowledge_quiz VALUES(1729,'Which sacred plant is worshipped daily in Hindu households?','हिंदू घरों में प्रतिदिन किस पवित्र पौधे की पूजा होती है?','[{"key": "A", "en": "Neem", "hi": "नीम"}, {"key": "B", "en": "Tulsi", "hi": "तुलसी"}, {"key": "C", "en": "Peepal", "hi": "पीपल"}, {"key": "D", "en": "Banyan", "hi": "वट"}]','B');
