INSERT INTO knowledge_quiz VALUES(1731,'Which scripture contains the Vishnu Sahasranama?','विष्णु सहस्रनाम किस ग्रंथ में मिलता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "D", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1732,'Which festival marks the worship of tools and machines?','औजारों और मशीनों की पूजा किस पर्व पर होती है?','[{"key": "A", "en": "Ayudha Puja", "hi": "आयुध पूजा"}, {"key": "B", "en": "Onam", "hi": "ओणम"}, {"key": "C", "en": "Pongal", "hi": "पोंगल"}, {"key": "D", "en": "Baisakhi", "hi": "बैसाखी"}]','A');
INSERT INTO knowledge_quiz VALUES(1733,'Which deity is worshipped during Margashirsha month?','मार्गशीर्ष मास में किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
