INSERT INTO knowledge_quiz VALUES(1735,'Which goddess is worshipped during Sharad Navratri?','शारदीय नवरात्रि में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','C');
INSERT INTO knowledge_quiz VALUES(1736,'The Bhuteshwar Temple, located in Jind, is dedicated to which deity?','जींद में स्थित भूतेश्वर मंदिर किस देवता को समर्पित है?','[{"key": "A", "en": "Lord Vishnu", "hi": "भगवान विष्णु"}, {"key": "B", "en": "Lord Shiva", "hi": "भगवान शिव"}, {"key": "C", "en": "Lord Ganesha", "hi": "भगवान गणेश"}, {"key": "D", "en": "Lord Rama", "hi": "भगवान राम"}]','B');
INSERT INTO knowledge_quiz VALUES(1737,'Which text is known as the fifth Veda?','किस ग्रंथ को पंचम वेद कहा जाता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Natya Shastra", "hi": "नाट्यशास्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1738,'Which goddess is worshipped during Gauri Puja?','गौरी पूजा में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(1739,'In Hindu Panchang, ''Bhadra'' is considered a part of which of these elements?','हिंदू पंचांग में ''भद्रा'' को इनमें से किस अंग का हिस्सा माना जाता है?','[{"key": "A", "en": "Tithi", "hi": "तिथि"}, {"key": "B", "en": "Nakshatra", "hi": "नक्षत्र"}, {"key": "C", "en": "Karana (Vishti)", "hi": "करण (विष्टि)"}, {"key": "D", "en": "Yoga", "hi": "योग"}]','C');
INSERT INTO knowledge_quiz VALUES(1740,'Which saint''s name is mentioned in the last line of the Hanuman Chalisa as a devotee seeking residency in the heart of God?','हनुमान चालीसा की अंतिम पंक्ति में किस संत का नाम एक भक्त के रूप में आता है जो ईश्वर के हृदय में निवास की प्रार्थना करता है?','[{"key": "A", "en": "Kabir", "hi": "कबीर"}, {"key": "B", "en": "Tulsidas", "hi": "तुलसीदास"}, {"key": "C", "en": "Ravidas", "hi": "रविदास"}, {"key": "D", "en": "Namdev", "hi": "नामदेव"}]','B');
INSERT INTO knowledge_quiz VALUES(1741,'What was the name of the sword of Lord Shiva, which he gave to Ravana?','भगवान शिव की तलवार का क्या नाम था, जिसे उन्होंने रावण को दिया था?','[{"key": "A", "en": "Nandaka", "hi": "नंदक"}, {"key": "B", "en": "Chandrahas", "hi": "चंद्रहास"}, {"key": "C", "en": "Asi", "hi": "असि"}, {"key": "D", "en": "Khadga", "hi": "खड्ग"}]','B');
INSERT INTO knowledge_quiz VALUES(1742,'In the Hanuman Chalisa, the line ''Yug Sahasra Yojana Par Bhanu'' describes Hanuman leaping towards the Sun. What does ''Bhanu'' mean?','हनुमान चालीसा की पंक्ति ''जुग सहस्र जोजन पर भानु'' में हनुमान के सूर्य की ओर उछलने का वर्णन है। यहाँ ''भानु'' का क्या अर्थ है?','[{"key": "A", "en": "Moon", "hi": "चंद्रमा"}, {"key": "B", "en": "Sun", "hi": "सूर्य"}, {"key": "C", "en": "Star", "hi": "तारा"}, {"key": "D", "en": "Sky", "hi": "आकाश"}]','B');
INSERT INTO knowledge_quiz VALUES(1743,'Which scripture is attributed to Sage Vyasa?','ऋषि व्यास से संबंधित कौन सा ग्रंथ है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "D", "en": "Nyaya Sutra", "hi": "न्याय सूत्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1744,'Which temple in Jharkhand is known as ''Chhinnamasta Temple'' and is situated at the confluence of Damodar and Bhairavi rivers?','झारखंड के किस मंदिर को ''छिन्नमस्तिका मंदिर'' के नाम से जाना जाता है और यह दामोदर और भैरवी नदियों के संगम पर स्थित है?','[{"key": "A", "en": "Rajrappa Temple", "hi": "रजरप्पा मंदिर"}, {"key": "B", "en": "Angrabari", "hi": "आम्रेश्वर धाम"}, {"key": "C", "en": "Pahari Mandir", "hi": "पहाड़ी मंदिर"}, {"key": "D", "en": "Jagannathpur Mandir", "hi": "जगन्नाथपुर मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(1745,'Which festival celebrates the bond between brothers and sisters?','भाई-बहन के बंधन का पर्व कौन सा है?','[{"key": "A", "en": "Raksha Bandhan", "hi": "रक्षा बंधन"}, {"key": "B", "en": "Bhai Dooj", "hi": "भाई दूज"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Teej", "hi": "तीज"}]','C');
INSERT INTO knowledge_quiz VALUES(1746,'Which deity is worshipped in the form of Shaligram?','शालिग्राम के रूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1747,'Which river is associated with Lord Rama’s exile period?','भगवान राम के वनवास काल से कौन सी नदी जुड़ी है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Godavari", "hi": "गोदावरी"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','C');
INSERT INTO knowledge_quiz VALUES(1748,'Which rishi is associated with Yoga philosophy?','योग दर्शन किस ऋषि से संबंधित है?','[{"key": "A", "en": "Kapila", "hi": "कपिल"}, {"key": "B", "en": "Patanjali", "hi": "पतंजलि"}, {"key": "C", "en": "Jaimini", "hi": "जैमिनि"}, {"key": "D", "en": "Vyasa", "hi": "व्यास"}]','B');
