INSERT INTO knowledge_quiz VALUES(1750,'Which deity is worshipped during Ram Navami?','राम नवमी पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Rama", "hi": "राम"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','B');
INSERT INTO knowledge_quiz VALUES(1751,'Which sage is known as the ''Lopamudra''s husband''?','किस ऋषि को ''लोपामुद्रा के पति'' के रूप में जाना जाता है?','[{"key": "A", "en": "Sage Agastya", "hi": "ऋषि अगस्त्य"}, {"key": "B", "en": "Sage Markandeya", "hi": "ऋषि मार्कंडेय"}, {"key": "C", "en": "Sage Durvasa", "hi": "ऋषि दुर्वासा"}, {"key": "D", "en": "Sage Bhrigu", "hi": "ऋषि भृगु"}]','A');
INSERT INTO knowledge_quiz VALUES(1752,'Which river is known as the daughter of the Sun?','किस नदी को सूर्य की पुत्री कहा जाता है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','B');
INSERT INTO knowledge_quiz VALUES(1753,'Which sage is considered the compiler of the Vedas?','वेदों के संकलनकर्ता किस ऋषि को माना जाता है?','[{"key": "A", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1754,'Which festival marks the beginning of the Hindu New Year in many regions?','कई क्षेत्रों में हिंदू नववर्ष की शुरुआत कौन सा पर्व दर्शाता है?','[{"key": "A", "en": "Diwali", "hi": "दीपावली"}, {"key": "B", "en": "Ugadi", "hi": "उगादी"}, {"key": "C", "en": "Holi", "hi": "होली"}, {"key": "D", "en": "Navratri", "hi": "नवरात्रि"}]','B');
INSERT INTO knowledge_quiz VALUES(1755,'In a traditional Aarti, which element is symbolized by the burning of camphor (Kapoor)?','पारंपरिक आरती में कपूर जलाने से किस तत्व का प्रतीक माना जाता है?','[{"key": "A", "en": "Earth", "hi": "पृथ्वी"}, {"key": "B", "en": "Ether/Space", "hi": "आकाश"}, {"key": "C", "en": "Fire", "hi": "अग्नि"}, {"key": "D", "en": "Water", "hi": "जल"}]','B');
INSERT INTO knowledge_quiz VALUES(1756,'Which Purana is devoted mainly to Lord Vishnu?','कौन सा पुराण मुख्य रूप से भगवान विष्णु को समर्पित है?','[{"key": "A", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Markandeya Purana", "hi": "मार्कण्डेय पुराण"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1757,'Which deity is worshipped during Magha Purnima?','माघ पूर्णिमा पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1758,'Which sacred city is one of the Sapta Puri?','सप्तपुरी में से एक पवित्र नगर कौन सा है?','[{"key": "A", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "B", "en": "Mathura", "hi": "मथुरा"}, {"key": "C", "en": "Ayodhya", "hi": "अयोध्या"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1759,'Which river is associated with the city of Ayodhya?','अयोध्या नगर किस नदी से जुड़ा है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Sarayu", "hi": "सरयू"}, {"key": "C", "en": "Yamuna", "hi": "यमुना"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','B');
INSERT INTO knowledge_quiz VALUES(1760,'Which god is known as the lord of medicine?','औषधि के देवता किसे कहा जाता है?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Dhanvantari", "hi": "धन्वंतरि"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1761,'Which Veda is associated with melodies and chants?','कौन सा वेद संगीत और मंत्रोच्चार से संबंधित है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Samaveda", "hi": "सामवेद"}, {"key": "C", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','B');
INSERT INTO knowledge_quiz VALUES(1762,'The ''Erawan Shrine'' in Bangkok is dedicated to which Hindu deity?','बैंकॉक में ''इरावन श्राइन'' किस हिंदू देवता को समर्पित है?','[{"key": "A", "en": "Lord Vishnu", "hi": "भगवान विष्णु"}, {"key": "B", "en": "Lord Brahma", "hi": "भगवान ब्रह्मा"}, {"key": "C", "en": "Lord Ganesha", "hi": "भगवान गणेश"}, {"key": "D", "en": "Lord Shiva", "hi": "भगवान शिव"}]','B');
INSERT INTO knowledge_quiz VALUES(1763,'Which Upanishad teaches the concept of ''Neti Neti''?','''नेति नेति'' की अवधारणा किस उपनिषद में मिलती है?','[{"key": "A", "en": "Isha Upanishad", "hi": "ईश उपनिषद"}, {"key": "B", "en": "Kena Upanishad", "hi": "केन उपनिषद"}, {"key": "C", "en": "Brihadaranyaka Upanishad", "hi": "बृहदारण्यक उपनिषद"}, {"key": "D", "en": "Prashna Upanishad", "hi": "प्रश्न उपनिषद"}]','C');
INSERT INTO knowledge_quiz VALUES(1764,'Which deity is worshipped during Ganga Dussehra?','गंगा दशहरा पर किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(1765,'Which goddess is worshipped during Varalakshmi Vratam?','वरलक्ष्मी व्रतम में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(1766,'Which sacred text outlines Raja Yoga?','राजयोग का विवरण किस ग्रंथ में मिलता है?','[{"key": "A", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Arthashastra", "hi": "अर्थशास्त्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1767,'Which temple is dedicated to Lord Shiva at Jyotirlinga in Gujarat?','गुजरात में ज्योतिर्लिंग के रूप में भगवान शिव को समर्पित कौन सा मंदिर है?','[{"key": "A", "en": "Somnath", "hi": "सोमनाथ"}, {"key": "B", "en": "Trimbakeshwar", "hi": "त्र्यंबकेश्वर"}, {"key": "C", "en": "Baidyanath", "hi": "बैद्यनाथ"}, {"key": "D", "en": "Kedarnath", "hi": "केदारनाथ"}]','A');
INSERT INTO knowledge_quiz VALUES(1768,'Which deity is worshipped during Vat Savitri Vrat?','वट सावित्री व्रत में किस देवी की पूजा होती है?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Savitri", "hi": "सावित्री"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(1769,'Which river is associated with the city of Nashik?','नासिक नगर किस नदी से जुड़ा है?','[{"key": "A", "en": "Godavari", "hi": "गोदावरी"}, {"key": "B", "en": "Krishna", "hi": "कृष्णा"}, {"key": "C", "en": "Tapi", "hi": "ताप्ती"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','A');
INSERT INTO knowledge_quiz VALUES(1770,'Which god is known as the lord of fire?','अग्नि के देवता कौन हैं?','[{"key": "A", "en": "Surya", "hi": "सूर्य"}, {"key": "B", "en": "Agni", "hi": "अग्नि"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1771,'Which scripture narrates the story of Prahlada?','प्रह्लाद की कथा किस ग्रंथ में मिलती है?','[{"key": "A", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "B", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "C", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','B');
INSERT INTO knowledge_quiz VALUES(1772,'In the Hanuman Chalisa, ''Sadhu Santa ke tuma rakhaware''. Who is specifically called ''Asura Nikandana'' in the next part of the line?','हनुमान चालीसा में, ''साधु संत के तुम रखवारे''। पंक्ति के अगले भाग में विशेष रूप से किसे ''असुर निकंदन'' कहा गया है?','[{"key": "A", "en": "Lord Rama", "hi": "भगवान राम"}, {"key": "B", "en": "Lord Hanuman", "hi": "भगवान हनुमान"}, {"key": "C", "en": "Lord Krishna", "hi": "भगवान कृष्ण"}, {"key": "D", "en": "Lakshmana", "hi": "लक्ष्मण"}]','B');
INSERT INTO knowledge_quiz VALUES(1773,'Which deity is traditionally offered ''Chhappan Bhog'' (56 varieties of food)?','पारंपरिक रूप से किस देवता को ''छप्पन भोग'' (56 प्रकार के व्यंजन) अर्पित किया जाता है?','[{"key": "A", "en": "Lord Shiva", "hi": "भगवान शिव"}, {"key": "B", "en": "Lord Krishna", "hi": "भगवान कृष्ण"}, {"key": "C", "en": "Lord Rama", "hi": "भगवान राम"}, {"key": "D", "en": "Lord Indra", "hi": "भगवान इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1774,'Which river flows through the city of Prayagraj?','प्रयागराज नगर से होकर कौन सी नदियाँ बहती हैं?','[{"key": "A", "en": "Ganga and Yamuna", "hi": "गंगा और यमुना"}, {"key": "B", "en": "Ganga and Saraswati", "hi": "गंगा और सरस्वती"}, {"key": "C", "en": "Yamuna and Saraswati", "hi": "यमुना और सरस्वती"}, {"key": "D", "en": "All three", "hi": "तीनों"}]','D');
INSERT INTO knowledge_quiz VALUES(1775,'Which god is known as the king of gods?','देवताओं के राजा किसे कहा जाता है?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1776,'Which scripture contains the Devi Mahatmya?','देवी माहात्म्य किस ग्रंथ में मिलता है?','[{"key": "A", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "B", "en": "Markandeya Purana", "hi": "मार्कण्डेय पुराण"}, {"key": "C", "en": "Brahmanda Purana", "hi": "ब्रह्माण्ड पुराण"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1777,'Which goddess is worshipped during Hartalika Teej?','हरतालिका तीज पर किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(1778,'The horse ''Ushnik'' represents which color in the rainbow spectrum associated with Surya?','घोड़ा ''उष्णिह'' सूर्य से जुड़े इंद्रधनुष स्पेक्ट्रम में किस रंग का प्रतिनिधित्व करता है?','[{"key": "A", "en": "Indigo", "hi": "इंडिगो"}, {"key": "B", "en": "Yellow", "hi": "पीला"}, {"key": "C", "en": "Orange", "hi": "नारंगी"}, {"key": "D", "en": "Violet", "hi": "बैंगनी"}]','C');
INSERT INTO knowledge_quiz VALUES(1779,'In a traditional puja, which element does ''Dhup'' (incense) represent among the five elements of nature?','एक पारंपरिक पूजा में, ''धूप'' प्रकृति के पांच तत्वों में से किस तत्व का प्रतिनिधित्व करती है?','[{"key": "A", "en": "Fire (Agni)", "hi": "अग्नि"}, {"key": "B", "en": "Air (Vayu)", "hi": "वायु"}, {"key": "C", "en": "Earth (Prithvi)", "hi": "पृथ्वी"}, {"key": "D", "en": "Space (Akash)", "hi": "आकाश"}]','B');
INSERT INTO knowledge_quiz VALUES(1780,'Which river is associated with Kedarnath?','केदारनाथ किस नदी से जुड़ा है?','[{"key": "A", "en": "Alaknanda", "hi": "अलकनंदा"}, {"key": "B", "en": "Mandakini", "hi": "मंदाकिनी"}, {"key": "C", "en": "Bhagirathi", "hi": "भागीरथी"}, {"key": "D", "en": "Yamuna", "hi": "यमुना"}]','B');
INSERT INTO knowledge_quiz VALUES(1781,'The Hanuman Chalisa mentions ''Lanka jari''. Who actually set Lanka on fire according to the text?','हनुमान चालीसा में ''लंका जारि'' (लंका जलाई) का उल्लेख है। पाठ के अनुसार वास्तव में लंका किसने जलाई थी?','[{"key": "A", "en": "Angad", "hi": "अंगद"}, {"key": "B", "en": "Hanuman", "hi": "हनुमान"}, {"key": "C", "en": "Lakshmana", "hi": "लक्ष्मण"}, {"key": "D", "en": "Ravana himself", "hi": "स्वयं रावण"}]','B');
INSERT INTO knowledge_quiz VALUES(1782,'In which temple in Nashik did Lord Rama, Sita, and Laxmana stay during their exile?','नासिक के किस मंदिर के क्षेत्र में भगवान राम, सीता और लक्ष्मण ने अपने वनवास के दौरान निवास किया था?','[{"key": "A", "en": "Kalaram Temple", "hi": "कलाराम मंदिर"}, {"key": "B", "en": "Kapaleshwar Temple", "hi": "कपालेश्वर मंदिर"}, {"key": "C", "en": "Muktidham", "hi": "मुक्तिधाम"}, {"key": "D", "en": "Someshwar", "hi": "सोमेश्वर"}]','A');
INSERT INTO knowledge_quiz VALUES(1783,'Which scripture describes the duties of kings?','राजाओं के कर्तव्यों का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "B", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Upanishads", "hi": "उपनिषद"}]','C');
INSERT INTO knowledge_quiz VALUES(1784,'Who became Dosha after disrupting sacred prayers?','पवित्र प्रार्थना भंग करने के बाद कौन दोष बनी?','[{"key": "A", "en": "Bhadra", "hi": "भद्रा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Neelima", "hi": "नीलिमा"}, {"key": "D", "en": "Chhaya", "hi": "छाया"}]','A');
INSERT INTO knowledge_quiz VALUES(1785,'Which goddess is worshipped during Navratri?','नवरात्रि में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(1786,'Which deity is worshipped during Ayyappa Mandala Puja?','अयप्पा मंडल पूजा में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Ayyappa", "hi": "अयप्पा"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Murugan", "hi": "मुरुगन"}]','B');
INSERT INTO knowledge_quiz VALUES(1787,'Which sacred river flows through Varanasi?','वाराणसी से होकर कौन सी पवित्र नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','B');
INSERT INTO knowledge_quiz VALUES(1788,'Which scripture is known as the fifth Veda?','किस ग्रंथ को पंचम वेद कहा जाता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Natya Shastra", "hi": "नाट्यशास्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1789,'Which goddess is worshipped during Gauri Puja?','गौरी पूजा में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(1790,'In which temple of Kurukshetra is it believed that the 51st Shakti Peetha exists?','कुरुक्षेत्र के किस मंदिर में माना जाता है कि 51वां शक्तिपीठ स्थित है?','[{"key": "A", "en": "Bhadrakali Temple", "hi": "भद्रकाली मंदिर"}, {"key": "B", "en": "Katyayani Temple", "hi": "कात्यायनी मंदिर"}, {"key": "C", "en": "Ambika Devi", "hi": "अंबिका देवी"}, {"key": "D", "en": "Kali Mata Temple, Kalka", "hi": "काली माता मंदिर, कालका"}]','A');
INSERT INTO knowledge_quiz VALUES(1791,'Which deity is worshipped during Ram Navami?','राम नवमी पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Rama", "hi": "राम"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','B');
INSERT INTO knowledge_quiz VALUES(1792,'Which item used in a traditional Aarti plate is considered a symbol of ''Naga'' (Serpent) energy and is also a natural disinfectant?','पारंपरिक आरती की थाली में उपयोग की जाने वाली कौन सी वस्तु ''नाग'' ऊर्जा का प्रतीक मानी जाती है और एक प्राकृतिक कीटाणुनाशक भी है?','[{"key": "A", "en": "Betel Leaf (Paan)", "hi": "पान का पत्ता"}, {"key": "B", "en": "Camphor (Kapoor)", "hi": "कपूर"}, {"key": "C", "en": "Incense (Dhoop)", "hi": "धूप"}, {"key": "D", "en": "Cloves (Laung)", "hi": "लौंग"}]','A');
INSERT INTO knowledge_quiz VALUES(1793,'Which scripture narrates the life of Lord Krishna?','भगवान कृष्ण के जीवन का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Harivamsa", "hi": "हरिवंश"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1794,'Which star is associated with the sage Agastya in Indian astronomy?','भारतीय खगोल विज्ञान में कौन सा तारा ऋषि अगस्त्य से जुड़ा है?','[{"key": "A", "en": "Sirius", "hi": "सीरियस (लुब्धक)"}, {"key": "B", "en": "Canopus", "hi": "कैनोपस"}, {"key": "C", "en": "Pole Star", "hi": "ध्रुव तारा"}, {"key": "D", "en": "Vega", "hi": "वेगा (अभिजीत)"}]','B');
INSERT INTO knowledge_quiz VALUES(1795,'Which sacred plant is worshipped daily in Hindu homes?','हिंदू घरों में प्रतिदिन किस पवित्र पौधे की पूजा होती है?','[{"key": "A", "en": "Peepal", "hi": "पीपल"}, {"key": "B", "en": "Tulsi", "hi": "तुलसी"}, {"key": "C", "en": "Neem", "hi": "नीम"}, {"key": "D", "en": "Banyan", "hi": "वट"}]','B');
INSERT INTO knowledge_quiz VALUES(1796,'Which hot water spring is located near the Yamunotri temple where pilgrims cook rice?','यमुनोत्री मंदिर के पास कौन सा गर्म पानी का कुंड स्थित है जहाँ तीर्थयात्री चावल पकाते हैं?','[{"key": "A", "en": "Tapt Kund", "hi": "तप्त कुंड"}, {"key": "B", "en": "Surya Kund", "hi": "सूर्य कुंड"}, {"key": "C", "en": "Gauri Kund", "hi": "गौरी कुंड"}, {"key": "D", "en": "Narad Kund", "hi": "नारद कुंड"}]','B');
INSERT INTO knowledge_quiz VALUES(1797,'The famous line ''Sab sukh lahai tumhari sarana'' in Hanuman Chalisa implies that all of what is found in your protection.','हनुमान चालीसा की प्रसिद्ध पंक्ति ''सब सुख लहै तुम्हारी सरना'' का अर्थ है कि आपकी शरण में सभी क्या प्राप्त होते हैं।','[{"key": "A", "en": "Wealth", "hi": "धन"}, {"key": "B", "en": "Happiness/Joys", "hi": "सुख/खुशियाँ"}, {"key": "C", "en": "Knowledge", "hi": "ज्ञान"}, {"key": "D", "en": "Strength", "hi": "बल"}]','B');
INSERT INTO knowledge_quiz VALUES(1798,'Which scripture contains the Vishnu Sahasranama?','विष्णु सहस्रनाम किस ग्रंथ में मिलता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "D", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1799,'Which color of cloth is traditionally offered to Goddess Kali during her Aarti and Chalisa path to represent her fierce energy?','देवी काली की आरती और चालीसा पाठ के दौरान उनकी उग्र ऊर्जा का प्रतिनिधित्व करने के लिए पारंपरिक रूप से किस रंग का वस्त्र अर्पित किया जाता है?','[{"key": "A", "en": "White", "hi": "सफेद"}, {"key": "B", "en": "Red or Black", "hi": "लाल या काला"}, {"key": "C", "en": "Yellow", "hi": "पीला"}, {"key": "D", "en": "Green", "hi": "हरा"}]','B');
INSERT INTO knowledge_quiz VALUES(1800,'Which deity is worshipped during Govardhan Puja?','गोवर्धन पूजा में किस देवता की पूजा होती है?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(1801,'Who is the primary wife of Surya Dev?','सूर्य देव की मुख्य पत्नी कौन हैं?','[{"key": "A", "en": "Chhaya", "hi": "छाया"}, {"key": "B", "en": "Saranyu", "hi": "सरन्यू"}, {"key": "C", "en": "Aditi", "hi": "अदिति"}, {"key": "D", "en": "Swaha", "hi": "स्वाहा"}]','B');
INSERT INTO knowledge_quiz VALUES(1802,'Which river is known as the daughter of the Himalayas?','किस नदी को हिमालय की पुत्री कहा जाता है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Alaknanda", "hi": "अलकनंदा"}]','A');
INSERT INTO knowledge_quiz VALUES(1803,'Which sage composed the Yoga Sutra?','योगसूत्र की रचना किस ऋषि ने की?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Kapila", "hi": "कपिल"}, {"key": "C", "en": "Patanjali", "hi": "पतंजलि"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','C');
INSERT INTO knowledge_quiz VALUES(1804,'Which festival celebrates the birth of Goddess Lakshmi?','देवी लक्ष्मी के प्रकट होने का उत्सव कौन सा है?','[{"key": "A", "en": "Diwali", "hi": "दीपावली"}, {"key": "B", "en": "Sharad Purnima", "hi": "शरद पूर्णिमा"}, {"key": "C", "en": "Kojagiri Purnima", "hi": "कोजागरी पूर्णिमा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1805,'Which deity is known as the preserver in the Trimurti?','त्रिमूर्ति में पालनकर्ता देवता कौन हैं?','[{"key": "A", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1806,'Which scripture explains the concept of Dharma in detail?','धर्म की अवधारणा का विस्तृत वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Dharmashastras", "hi": "धर्मशास्त्र"}, {"key": "C", "en": "Vedas", "hi": "वेद"}, {"key": "D", "en": "Puranas", "hi": "पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1807,'Which goddess is worshipped during Chaitra Navratri?','चैत्र नवरात्रि में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','C');
INSERT INTO knowledge_quiz VALUES(1808,'Which sacred city is associated with Lord Krishna’s birth?','भगवान कृष्ण के जन्म से कौन सा पवित्र नगर जुड़ा है?','[{"key": "A", "en": "Mathura", "hi": "मथुरा"}, {"key": "B", "en": "Vrindavan", "hi": "वृंदावन"}, {"key": "C", "en": "Dwarka", "hi": "द्वारका"}, {"key": "D", "en": "Gokul", "hi": "गोकुल"}]','A');
INSERT INTO knowledge_quiz VALUES(1809,'Which river is associated with the city of Mathura?','मथुरा नगर किस नदी से जुड़ा है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','B');
INSERT INTO knowledge_quiz VALUES(1810,'Which ''Mudra'' is formed by joining both palms in a prayer gesture?','प्रार्थना की मुद्रा में दोनों हथेलियों को जोड़कर कौन सी ''मुद्रा'' बनाई जाती है?','[{"key": "A", "en": "Chin Mudra", "hi": "चिन्मय मुद्रा"}, {"key": "B", "en": "Anjali Mudra", "hi": "अंजलि मुद्रा"}, {"key": "C", "en": "Dhyana Mudra", "hi": "ध्यान मुद्रा"}, {"key": "D", "en": "Vayu Mudra", "hi": "वायु मुद्रा"}]','B');
INSERT INTO knowledge_quiz VALUES(1811,'Which scripture contains the teachings of Adi Shankaracharya?','आदि शंकराचार्य की शिक्षाएँ किन ग्रंथों में मिलती हैं?','[{"key": "A", "en": "Bhashyas", "hi": "भाष्य"}, {"key": "B", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "C", "en": "Puranas", "hi": "पुराण"}, {"key": "D", "en": "Vedas", "hi": "वेद"}]','A');
INSERT INTO knowledge_quiz VALUES(1812,'Which goddess is worshipped during Navratri in nine forms?','नवरात्रि में नौ रूपों में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(1813,'Which sacred river is known as the lifeline of South India?','दक्षिण भारत की जीवनरेखा किस नदी को कहा जाता है?','[{"key": "A", "en": "Godavari", "hi": "गोदावरी"}, {"key": "B", "en": "Krishna", "hi": "कृष्णा"}, {"key": "C", "en": "Kaveri", "hi": "कावेरी"}, {"key": "D", "en": "Tungabhadra", "hi": "तुंगभद्रा"}]','C');
INSERT INTO knowledge_quiz VALUES(1814,'Which temple near Madurai is one of the ''Arupadaiveedu'' (six abodes) of Lord Murugan and is carved out of a hill?','मदुरै के पास कौन सा मंदिर भगवान मुरुगन के ''आरुपदैवेदु'' (छह निवासों) में से एक है और इसे पहाड़ी को काटकर बनाया गया है?','[{"key": "A", "en": "Palani", "hi": "पलानी"}, {"key": "B", "en": "Thirupparankundram", "hi": "तिरुप्परनकुंद्रम"}, {"key": "C", "en": "Pazhamudircholai", "hi": "पझमुदिरचोलै"}, {"key": "D", "en": "Tiruchendur", "hi": "तिरुचेंदुर"}]','B');
INSERT INTO knowledge_quiz VALUES(1815,'Which Purana narrates the stories of Goddess Durga?','देवी दुर्गा की कथाओं का वर्णन किस पुराण में है?','[{"key": "A", "en": "Markandeya Purana", "hi": "मार्कण्डेय पुराण"}, {"key": "B", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "C", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(1816,'In which country is the ''Prambanan'' temple compound, a 9th-century Hindu temple site, located?','''प्रमबनन'' मंदिर परिसर, जो 9वीं शताब्दी का हिंदू मंदिर स्थल है, किस देश में स्थित है?','[{"key": "A", "en": "Thailand", "hi": "थाईलैंड"}, {"key": "B", "en": "Vietnam", "hi": "वियतनाम"}, {"key": "C", "en": "Indonesia", "hi": "इंडोनेशिया"}, {"key": "D", "en": "Malaysia", "hi": "मलेशिया"}]','C');
INSERT INTO knowledge_quiz VALUES(1817,'Which sacred city is one of the Char Dham?','चार धामों में से एक पवित्र नगर कौन सा है?','[{"key": "A", "en": "Dwarka", "hi": "द्वारका"}, {"key": "B", "en": "Ayodhya", "hi": "अयोध्या"}, {"key": "C", "en": "Mathura", "hi": "मथुरा"}, {"key": "D", "en": "Vrindavan", "hi": "वृंदावन"}]','A');
INSERT INTO knowledge_quiz VALUES(1818,'What is the spiritual significance of waving a piece of cloth (Vastra) during an elaborate Aarti?','एक विस्तृत आरती के दौरान कपड़े का टुकड़ा (वस्त्र) लहराने का आध्यात्मिक महत्व क्या है?','[{"key": "A", "en": "To clean the air", "hi": "हवा साफ करने के लिए"}, {"key": "B", "en": "Surrendering one''s privacy and ego to God", "hi": "अपनी गोपनीयता और अहंकार को ईश्वर को समर्पित करना"}, {"key": "C", "en": "To show wealth", "hi": "धन प्रदर्शन के लिए"}, {"key": "D", "en": "To provide shade", "hi": "छाया प्रदान करने के लिए"}]','B');
INSERT INTO knowledge_quiz VALUES(1819,'Which god is worshipped during Thursday fasts?','गुरुवार व्रत में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Brihaspati", "hi": "बृहस्पति"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1820,'The 18 sacred steps leading to the Sabarimala sanctum sanctorum are known as what?','सबरीमाला गर्भगृह तक जाने वाली 18 पवित्र सीढ़ियों को क्या कहा जाता है?','[{"key": "A", "en": "Pathinettam Padi", "hi": "पधिनट्टम पडी"}, {"key": "B", "en": "Ashtadasa Sopanam", "hi": "अष्टादश सोपानम"}, {"key": "C", "en": "Dharma Padi", "hi": "धर्म पडी"}, {"key": "D", "en": "Moksha Sopanam", "hi": "मोक्ष सोपानम"}]','A');
INSERT INTO knowledge_quiz VALUES(1821,'Which scripture explains Bhakti Yoga in detail?','भक्ति योग का विस्तृत वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "C", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "D", "en": "Nyaya Sutra", "hi": "न्याय सूत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1822,'The Bhoramdeo Temple, often called the ''Khajuraho of Chhattisgarh'', is dedicated to which deity?','भोरमदेव मंदिर, जिसे अक्सर ''छत्तीसगढ़ का खजुराहो'' कहा जाता है, किस देवता को समर्पित है?','[{"key": "A", "en": "Lord Vishnu", "hi": "भगवान विष्णु"}, {"key": "B", "en": "Lord Shiva", "hi": "भगवान शिव"}, {"key": "C", "en": "Lord Surya", "hi": "भगवान सूर्य"}, {"key": "D", "en": "Lord Brahma", "hi": "भगवान ब्रह्मा"}]','B');
INSERT INTO knowledge_quiz VALUES(1823,'Which river is known as the lifeline of Gujarat?','गुजरात की जीवनरेखा किस नदी को कहा जाता है?','[{"key": "A", "en": "Sabarmati", "hi": "साबरमती"}, {"key": "B", "en": "Narmada", "hi": "नर्मदा"}, {"key": "C", "en": "Tapi", "hi": "ताप्ती"}, {"key": "D", "en": "Mahi", "hi": "माही"}]','B');
INSERT INTO knowledge_quiz VALUES(1824,'Which deity is worshipped during Masik Shivaratri?','मासिक शिवरात्रि में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Ganesha", "hi": "गणेश"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','A');
INSERT INTO knowledge_quiz VALUES(1825,'The Yadadri (Yadagirigutta) Temple, recently reconstructed with black stone (Krushna Shila), is dedicated to which deity?','यादाद्री (यादगिरिगुट्टा) मंदिर, जिसे हाल ही में काले पत्थर (कृष्ण शिला) से पुनर्निर्मित किया गया है, किस देवता को समर्पित है?','[{"key": "A", "en": "Lord Shiva", "hi": "भगवान शिव"}, {"key": "B", "en": "Lord Lakshmi Narasimha", "hi": "भगवान लक्ष्मी नरसिंह"}, {"key": "C", "en": "Lord Venkateswara", "hi": "भगवान वेंकटेश्वर"}, {"key": "D", "en": "Lord Rama", "hi": "भगवान राम"}]','B');
INSERT INTO knowledge_quiz VALUES(1826,'Which temple is known as the ''Dakshina Kashi'' of Telangana and is situated on the banks of the Godavari river?','किस मंदिर को तेलंगाना की ''दक्षिण काशी'' कहा जाता है और यह गोदावरी नदी के तट पर स्थित है?','[{"key": "A", "en": "Gnana Saraswati, Basar", "hi": "ज्ञान सरस्वती, बासर"}, {"key": "B", "en": "Vemulawada Rajarajeshwara", "hi": "वेमुलवाड़ा राजराजेश्वर"}, {"key": "C", "en": "Kaleshwaram Temple", "hi": "कालेश्वरम मंदिर"}, {"key": "D", "en": "Kondagattu Temple", "hi": "कोंडागट्टू मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(1827,'Which temple in Telangana features two Shiva Lingas on a single pedestal, representing Lord Shiva and Lord Yama?','तेलंगाना के किस मंदिर में एक ही वेदी पर दो शिव लिंग हैं, जो भगवान शिव और भगवान यम का प्रतिनिधित्व करते हैं?','[{"key": "A", "en": "Kaleshwaram Mukteswara Swamy", "hi": "कालेश्वरम मुक्तेश्वर स्वामी"}, {"key": "B", "en": "Ramappa Temple", "hi": "रामप्पा मंदिर"}, {"key": "C", "en": "Jogulamba Temple", "hi": "जोगुलम्बा मंदिर"}, {"key": "D", "en": "Sangameshwara Temple", "hi": "संगमेश्वर मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(1828,'Which god is known as the lord of wealth?','धन के देवता किसे कहा जाता है?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Kubera", "hi": "कुबेर"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(1829,'Which festival celebrates the lifting of Govardhan Hill?','गोवर्धन पर्वत उठाने की घटना किस पर्व से जुड़ी है?','[{"key": "A", "en": "Janmashtami", "hi": "जन्माष्टमी"}, {"key": "B", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "C", "en": "Holi", "hi": "होली"}, {"key": "D", "en": "Diwali", "hi": "दीपावली"}]','B');
INSERT INTO knowledge_quiz VALUES(1830,'Which deity is worshipped during Sankashti Chaturthi?','संकष्टी चतुर्थी पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1831,'Which sacred text is a dialogue between Arjuna and Krishna?','अर्जुन और कृष्ण के संवाद वाला पवित्र ग्रंथ कौन सा है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Yoga Sutra", "hi": "योगसूत्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1832,'Which river is associated with the city of Haridwar?','हरिद्वार नगर किस नदी से जुड़ा है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Alaknanda", "hi": "अलकनंदा"}, {"key": "D", "en": "Mandakini", "hi": "मंदाकिनी"}]','B');
INSERT INTO knowledge_quiz VALUES(1833,'In the Hanuman Chalisa, the line ''Jaya jaya jaya Hanumana Gosai''. What does ''Gosai'' (Goswami) mean in this context?','हनुमान चालीसा की पंक्ति ''जय जय जय हनुमान गोसाईं''। इस संदर्भ में ''गोसाईं'' (गोस्वामी) का क्या अर्थ है?','[{"key": "A", "en": "A poet", "hi": "एक कवि"}, {"key": "B", "en": "Master of the Senses", "hi": "इंद्रियों का स्वामी"}, {"key": "C", "en": "A cowherd", "hi": "एक ग्वाला"}, {"key": "D", "en": "A king", "hi": "एक राजा"}]','B');
INSERT INTO knowledge_quiz VALUES(1834,'The Danteshwari Temple, one of the 52 Shakti Peethas, is located at the confluence of which two rivers in Bastar?','52 शक्तिपीठों में से एक, दंतेश्वरी मंदिर बस्तर में किन दो नदियों के संगम पर स्थित है?','[{"key": "A", "en": "Indravati and Mahanadi", "hi": "इंद्रावती और महानदी"}, {"key": "B", "en": "Dankini and Shankini", "hi": "डंकिनी और शंखिनी"}, {"key": "C", "en": "Shivnath and Arpa", "hi": "शिवनाथ और अरपा"}, {"key": "D", "en": "Sabari and Kanger", "hi": "शबरी और कांगेर"}]','B');
INSERT INTO knowledge_quiz VALUES(1835,'Which river is known as the sorrow of Bengal?','बंगाल का शोक किस नदी को कहा जाता है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Damodar", "hi": "दामोदर"}, {"key": "C", "en": "Hooghly", "hi": "हुगली"}, {"key": "D", "en": "Teesta", "hi": "तीस्ता"}]','B');
INSERT INTO knowledge_quiz VALUES(1836,'Bhadra is considered beneficial only when she resides in which Loka?','भद्रा को केवल तभी लाभकारी माना जाता है जब वह किस लोक में निवास करती है?','[{"key": "A", "en": "Prithvi Loka", "hi": "पृथ्वी लोक"}, {"key": "B", "en": "Swarga and Patal Loka", "hi": "स्वर्ग और पाताल लोक"}, {"key": "C", "en": "None, she is always harmful", "hi": "कोई नहीं, वह हमेशा हानिकारक होती है"}, {"key": "D", "en": "Only Swarga Loka", "hi": "केवल स्वर्ग लोक"}]','B');
INSERT INTO knowledge_quiz VALUES(1837,'Which goddess is worshipped during Katyayani Puja?','कात्यायनी पूजा में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Katyayani", "hi": "कात्यायनी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Lakshmi", "hi": "लक्ष्मी"}]','B');
INSERT INTO knowledge_quiz VALUES(1838,'The ''Eklavya Temple'', said to be the only temple in the world dedicated to Eklavya, is located in which village of Gurugram?','''एकलव्य मंदिर'', जिसे दुनिया में एकलव्य को समर्पित एकमात्र मंदिर कहा जाता है, गुरुग्राम के किस गाँव में स्थित है?','[{"key": "A", "en": "Sohna", "hi": "सोहना"}, {"key": "B", "en": "Khandsa", "hi": "खांडसा"}, {"key": "C", "en": "Manesar", "hi": "मानेसर"}, {"key": "D", "en": "Pataudi", "hi": "पटौदी"}]','B');
INSERT INTO knowledge_quiz VALUES(1839,'Which scripture deals with ancient Indian medicine?','प्राचीन भारतीय चिकित्सा से संबंधित ग्रंथ कौन सा है?','[{"key": "A", "en": "Charaka Samhita", "hi": "चरक संहिता"}, {"key": "B", "en": "Sushruta Samhita", "hi": "सुश्रुत संहिता"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','C');
INSERT INTO knowledge_quiz VALUES(1840,'Which deity is worshipped during Rohini Vrat?','रोहिणी व्रत में किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','A');
INSERT INTO knowledge_quiz VALUES(1841,'Which river flows through the city of Patna?','पटना नगर से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Gandak", "hi": "गंडक"}, {"key": "B", "en": "Son", "hi": "सोन"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Kosi", "hi": "कोसी"}]','C');
INSERT INTO knowledge_quiz VALUES(1842,'In the ritual of ''Sandhya Aarti'', what does the lighting of five wicks (Panch-Aarti) represent?','''संध्या आरती'' के अनुष्ठान में, पांच बत्तियों (पंच-आरती) को जलाना किसका प्रतिनिधित्व करता है?','[{"key": "A", "en": "Five Rivers", "hi": "पाँच नदियाँ"}, {"key": "B", "en": "Five Elements (Pancha Tattva)", "hi": "पाँच तत्व (पंच तत्व)"}, {"key": "C", "en": "Five Senses", "hi": "पाँच इंद्रियाँ"}, {"key": "D", "en": "Five Pandavas", "hi": "पाँच पांडव"}]','B');
INSERT INTO knowledge_quiz VALUES(1843,'What is the name of the vessel used to pour water during Havan or Sandhyavandanam?','हवन या संध्यावंदनम के दौरान जल छोड़ने के लिए उपयोग किए जाने वाले पात्र का क्या नाम है?','[{"key": "A", "en": "Thali", "hi": "थाली"}, {"key": "B", "en": "Panchapatra & Achmani", "hi": "पंचपात्र और आचमनी"}, {"key": "C", "en": "Lota", "hi": "लोटा"}, {"key": "D", "en": "Katori", "hi": "कटोरी"}]','B');
INSERT INTO knowledge_quiz VALUES(1844,'Which goddess is worshipped during Ambubachi Mela?','अंबुबाची मेले में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Kamakhya", "hi": "कामाख्या"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Lakshmi", "hi": "लक्ष्मी"}]','B');
INSERT INTO knowledge_quiz VALUES(1845,'Which deity is worshipped during Ganga Saptami?','गंगा सप्तमी पर किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Lakshmi", "hi": "लक्ष्मी"}]','B');
INSERT INTO knowledge_quiz VALUES(1846,'Which river is known as the lifeline of Assam?','असम की जीवनरेखा किस नदी को कहा जाता है?','[{"key": "A", "en": "Barak", "hi": "बराक"}, {"key": "B", "en": "Brahmaputra", "hi": "ब्रह्मपुत्र"}, {"key": "C", "en": "Teesta", "hi": "तीस्ता"}, {"key": "D", "en": "Subansiri", "hi": "सुबनसिरी"}]','B');
INSERT INTO knowledge_quiz VALUES(1847,'Which deity is worshipped during Shukla Paksha?','शुक्ल पक्ष में सामान्यतः किस देवता की पूजा की जाती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Chandra", "hi": "चंद्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1848,'Which goddess is worshipped during Mahalakshmi Vrat?','महालक्ष्मी व्रत में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(1849,'Which deity is worshipped during Amavasya?','अमावस्या पर सामान्यतः किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Pitrs", "hi": "पितृ"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','C');
INSERT INTO knowledge_quiz VALUES(1850,'Which festival is dedicated to the worship of cows?','गायों की पूजा को समर्पित पर्व कौन सा है?','[{"key": "A", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "B", "en": "Gopashtami", "hi": "गोपाष्टमी"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}]','C');
INSERT INTO knowledge_quiz VALUES(1851,'Who was the wife of Lord Rama?','भगवान राम की पत्नी कौन थीं?','[{"key": "A", "en": "Urmila", "hi": "उर्मिला"}, {"key": "B", "en": "Mandodari", "hi": "मंदोदरी"}, {"key": "C", "en": "Sita", "hi": "सीता"}, {"key": "D", "en": "Mandavi", "hi": "मांडवी"}]','C');
INSERT INTO knowledge_quiz VALUES(1852,'Which river is associated with Lord Rama’s kingdom Ayodhya?','भगवान राम की अयोध्या नगरी किस नदी से जुड़ी है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','C');
INSERT INTO knowledge_quiz VALUES(1853,'Which sage authored the Ramayana?','रामायण के रचयिता कौन ऋषि थे?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Narada", "hi": "नारद"}]','B');
INSERT INTO knowledge_quiz VALUES(1854,'The Hariharnath Temple in Sonepur is situated at the confluence of which two rivers?','सोनपुर का हरिहरनाथ मंदिर किन दो नदियों के संगम पर स्थित है?','[{"key": "A", "en": "Ganga and Gandak", "hi": "गंगा और गंडक"}, {"key": "B", "en": "Ganga and Sone", "hi": "गंगा और सोन"}, {"key": "C", "en": "Gandak and Kosi", "hi": "गंडक और कोसी"}, {"key": "D", "en": "Sone and Punpun", "hi": "सोन और पुनपुन"}]','A');
INSERT INTO knowledge_quiz VALUES(1855,'Which deity is known as the king of serpents?','नागों के राजा किसे कहा जाता है?','[{"key": "A", "en": "Vasuki", "hi": "वासुकी"}, {"key": "B", "en": "Shesha", "hi": "शेष"}, {"key": "C", "en": "Takshaka", "hi": "तक्षक"}, {"key": "D", "en": "Kaliya", "hi": "कालिया"}]','B');
INSERT INTO knowledge_quiz VALUES(1856,'Which goddess is worshipped during Varalakshmi Vratam?','वरलक्ष्मी व्रतम में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(1857,'In the Hanuman Chalisa, what does the word ''Bajrang'' (from Vajrang) signify about Hanuman''s body?','हनुमान चालीसा में, ''बजरंग'' (वज्रांग से) शब्द हनुमान के शरीर के बारे में क्या दर्शाता है?','[{"key": "A", "en": "Fast as wind", "hi": "हवा जैसा तेज"}, {"key": "B", "en": "Hard as a diamond/thunderbolt", "hi": "वज्र के समान कठोर"}, {"key": "C", "en": "Light as a feather", "hi": "पंख जैसा हल्का"}, {"key": "D", "en": "Ocean-like vastness", "hi": "सागर जैसी विशालता"}]','B');
INSERT INTO knowledge_quiz VALUES(1858,'What is the ritual of waving a lighted lamp (diya) before the deity called?','देवता के सामने जलता हुआ दीपक घुमाने की विधि को क्या कहा जाता है?','[{"key": "A", "en": "Arghya", "hi": "अर्घ्य"}, {"key": "B", "en": "Aarti", "hi": "आरती"}, {"key": "C", "en": "Naivedya", "hi": "नैवेद्य"}, {"key": "D", "en": "Visarjan", "hi": "विसर्जन"}]','B');
INSERT INTO knowledge_quiz VALUES(1859,'Which day of the week is considered most auspicious for visiting the Siddhivinayak temple?','सिद्धिविनायक मंदिर के दर्शन के लिए सप्ताह का कौन सा दिन सबसे शुभ माना जाता है?','[{"key": "A", "en": "Monday", "hi": "सोमवार"}, {"key": "B", "en": "Tuesday", "hi": "मंगलवार"}, {"key": "C", "en": "Friday", "hi": "शुक्रवार"}, {"key": "D", "en": "Sunday", "hi": "रविवार"}]','B');
INSERT INTO knowledge_quiz VALUES(1860,'Which scripture contains the dialogue between Yama and Nachiketa?','यम और नचिकेता के संवाद वाला ग्रंथ कौन सा है?','[{"key": "A", "en": "Isha Upanishad", "hi": "ईश उपनिषद"}, {"key": "B", "en": "Katha Upanishad", "hi": "कठ उपनिषद"}, {"key": "C", "en": "Mundaka Upanishad", "hi": "मुण्डक उपनिषद"}, {"key": "D", "en": "Kena Upanishad", "hi": "केन उपनिषद"}]','B');
INSERT INTO knowledge_quiz VALUES(1861,'Which Aarti concludes with the prayer for ''Loka Samasta Sukhino Bhavantu''?','कौन सी आरती ''लोकाः समस्ताः सुखिनो भवन्तु'' की प्रार्थना के साथ समाप्त होती है?','[{"key": "A", "en": "Shanti Path", "hi": "शांति पाठ"}, {"key": "B", "en": "Ganesh Aarti", "hi": "गणेश आरती"}, {"key": "C", "en": "Durga Aarti", "hi": "दुर्गा आरती"}, {"key": "D", "en": "Hanuman Aarti", "hi": "हनुमान आरती"}]','A');
INSERT INTO knowledge_quiz VALUES(1862,'In the Aarti ''Om Jai Jagdish Hare'', the line ''Vishay vikar mitao pap haro deva'' is a prayer to remove what?','आरती ''ओम जय जगदीश हरे'' में पंक्ति ''विषय विकार मिटाओ पाप हरो देवा'' में क्या दूर करने की प्रार्थना की गई है?','[{"key": "A", "en": "Wealth", "hi": "धन"}, {"key": "B", "en": "Worldly attachments", "hi": "सांसारिक मोह-माया"}, {"key": "C", "en": "Friends", "hi": "मित्र"}, {"key": "D", "en": "Knowledge", "hi": "ज्ञान"}]','B');
INSERT INTO knowledge_quiz VALUES(1863,'Which river flows through the city of Varanasi?','वाराणसी नगर से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','B');
INSERT INTO knowledge_quiz VALUES(1864,'The Gnana Saraswati Temple in Basar is unique because it is one of the very few temples in India dedicated to Goddess Saraswati. What ritual for children is famous here?','बासर का ज्ञान सरस्वती मंदिर अद्वितीय है क्योंकि यह भारत में देवी सरस्वती को समर्पित बहुत कम मंदिरों में से एक है। यहाँ बच्चों के लिए कौन सा अनुष्ठान प्रसिद्ध है?','[{"key": "A", "en": "Akshara Abhyasam", "hi": "अक्षर अभ्यासम"}, {"key": "B", "en": "Annaprasana", "hi": "अन्नप्राशन"}, {"key": "C", "en": "Upanayanam", "hi": "उपनयन"}, {"key": "D", "en": "Namakaran", "hi": "नामकरण"}]','A');
INSERT INTO knowledge_quiz VALUES(1865,'The ''Shani Aarti'' often mentions ''Tel'' (Oil). Why is mustard oil offered to Lord Shani?','''शनि आरती'' में अक्सर ''तेल'' का उल्लेख होता है। भगवान शनि को सरसों का तेल क्यों चढ़ाया जाता है?','[{"key": "A", "en": "To cool his anger", "hi": "उनके क्रोध को शांत करने के लिए"}, {"key": "B", "en": "To heal his wounds", "hi": "उनके घावों को भरने के लिए"}, {"key": "C", "en": "As a symbol of wealth", "hi": "धन के प्रतीक के रूप में"}, {"key": "D", "en": "For good luck", "hi": "सौभाग्य के लिए"}]','B');
INSERT INTO knowledge_quiz VALUES(1866,'Which deity is worshipped during Sankashti Chaturthi?','संकष्टी चतुर्थी पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1867,'Which scripture explains Advaita Vedanta?','अद्वैत वेदांत की व्याख्या किस परंपरा में मिलती है?','[{"key": "A", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "B", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "C", "en": "Puranas", "hi": "पुराण"}, {"key": "D", "en": "Arthashastra", "hi": "अर्थशास्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1868,'Which mythical bird or creature is seen on the pillars of the Meenakshi temple, representing strength?','मीनाक्षी मंदिर के स्तंभों पर कौन सा पौराणिक जीव देखा जाता है, जो शक्ति का प्रतीक है?','[{"key": "A", "en": "Garuda", "hi": "गरुड़"}, {"key": "B", "en": "Yali", "hi": "याली"}, {"key": "C", "en": "Nandi", "hi": "नंदी"}, {"key": "D", "en": "Airavata", "hi": "ऐरावत"}]','B');
INSERT INTO knowledge_quiz VALUES(1869,'In the Hanuman Chalisa, the line ''Ram Rasayan tumhare pasa'' refers to ''Rasayan''. What does it symbolize in a spiritual context?','हनुमान चालीसा की पंक्ति ''राम रसायन तुम्हारे पासा'' में ''रसायन'' का उल्लेख है। आध्यात्मिक संदर्भ में यह किसका प्रतीक है?','[{"key": "A", "en": "Physical medicine", "hi": "शारीरिक औषधि"}, {"key": "B", "en": "The essence/elixir of Ram''s devotion", "hi": "राम भक्ति का सार/अमृत"}, {"key": "C", "en": "Alchemical gold", "hi": "कीमियाई सोना"}, {"key": "D", "en": "Poison", "hi": "विष"}]','B');
INSERT INTO knowledge_quiz VALUES(1870,'Which god is known as the lord of wealth?','धन के देवता किसे कहा जाता है?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Kubera", "hi": "कुबेर"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(1871,'Which sacred text is a conversation between Krishna and Arjuna?','कृष्ण और अर्जुन के संवाद वाला ग्रंथ कौन सा है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Yoga Sutra", "hi": "योगसूत्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1872,'Which river is known as the lifeline of Assam?','असम की जीवनरेखा किस नदी को कहा जाता है?','[{"key": "A", "en": "Barak", "hi": "बराक"}, {"key": "B", "en": "Brahmaputra", "hi": "ब्रह्मपुत्र"}, {"key": "C", "en": "Teesta", "hi": "तीस्ता"}, {"key": "D", "en": "Subansiri", "hi": "सुबनसिरी"}]','B');
INSERT INTO knowledge_quiz VALUES(1873,'Which deity is worshipped during Masik Shivaratri?','मासिक शिवरात्रि में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Ganesha", "hi": "गणेश"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1874,'In the Hanuman Chalisa, the line ''Laya Sanjivana Lakhana jiyaye'' credits Hanuman with bringing the Sanjivani herb. Where did he find this herb?','हनुमान चालीसा की पंक्ति ''लाय सजीवन लखन जियाये'' में हनुमान को संजीवनी बूटी लाने का श्रेय दिया गया है। उन्हें यह बूटी कहाँ मिली थी?','[{"key": "A", "en": "Mount Kailash", "hi": "कैलाश पर्वत"}, {"key": "B", "en": "Dronagiri Mountain", "hi": "द्रोणागिरी पर्वत"}, {"key": "C", "en": "Vindhya Range", "hi": "विंध्य पर्वतमाला"}, {"key": "D", "en": "Gandhamardan Mountain", "hi": "गंधमादन पर्वत"}]','B');
INSERT INTO knowledge_quiz VALUES(1875,'Which river flows through the city of Patna?','पटना नगर से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Son", "hi": "सोन"}, {"key": "B", "en": "Gandak", "hi": "गंडक"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Kosi", "hi": "कोसी"}]','C');
INSERT INTO knowledge_quiz VALUES(1876,'Which temple in Hyderabad is popularly known as ''Visa Balaji'' because devotees believe the deity helps with US visa approvals?','हैदराबाद के किस मंदिर को लोकप्रिय रूप से ''वीजा बालाजी'' कहा जाता है क्योंकि भक्तों का मानना है कि देवता अमेरिकी वीजा अनुमोदन में मदद करते हैं?','[{"key": "A", "en": "Birla Mandir", "hi": "बिड़ला मंदिर"}, {"key": "B", "en": "Chilkur Balaji Temple", "hi": "चिलकुर बालाजी मंदिर"}, {"key": "C", "en": "Sanghi Temple", "hi": "संघी मंदिर"}, {"key": "D", "en": "Karmanghat Hanuman", "hi": "कर्मनघाट हनुमान"}]','B');
INSERT INTO knowledge_quiz VALUES(1877,'Which festival marks the lifting of Govardhan Hill?','गोवर्धन पर्वत उठाने की घटना किस पर्व से जुड़ी है?','[{"key": "A", "en": "Janmashtami", "hi": "जन्माष्टमी"}, {"key": "B", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "C", "en": "Diwali", "hi": "दीपावली"}, {"key": "D", "en": "Holi", "hi": "होली"}]','B');
INSERT INTO knowledge_quiz VALUES(1878,'The ancient Harishchandreshwar Temple, carved out of a single rock, is located at the top of which fort?','एक ही चट्टान से तराशा गया प्राचीन हरिश्चंद्रेश्वर मंदिर किस किले की चोटी पर स्थित है?','[{"key": "A", "en": "Ratangad", "hi": "रतनगढ़"}, {"key": "B", "en": "Harishchandragad", "hi": "हरिश्चंद्रगढ़"}, {"key": "C", "en": "Alang Fort", "hi": "अलंग किला"}, {"key": "D", "en": "Kalsubai", "hi": "कलसूबाई"}]','B');
INSERT INTO knowledge_quiz VALUES(1879,'Which scripture deals with ancient Indian medicine?','प्राचीन भारतीय चिकित्सा से संबंधित ग्रंथ कौन से हैं?','[{"key": "A", "en": "Charaka Samhita", "hi": "चरक संहिता"}, {"key": "B", "en": "Sushruta Samhita", "hi": "सुश्रुत संहिता"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','C');
INSERT INTO knowledge_quiz VALUES(1880,'Which goddess is worshipped during Gauri Puja?','गौरी पूजा में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(1881,'Which deity is worshipped during Amavasya?','अमावस्या पर सामान्यतः किसकी पूजा की जाती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Pitrs", "hi": "पितृ"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','C');
INSERT INTO knowledge_quiz VALUES(1882,'Which sacred plant is worshipped daily in Hindu homes?','हिंदू घरों में प्रतिदिन किस पवित्र पौधे की पूजा होती है?','[{"key": "A", "en": "Neem", "hi": "नीम"}, {"key": "B", "en": "Tulsi", "hi": "तुलसी"}, {"key": "C", "en": "Peepal", "hi": "पीपल"}, {"key": "D", "en": "Banyan", "hi": "वट"}]','B');
INSERT INTO knowledge_quiz VALUES(1883,'Which river is associated with the Kumbh Mela at Nashik?','नासिक के कुंभ मेले में कौन सी नदी जुड़ी है?','[{"key": "A", "en": "Godavari", "hi": "गोदावरी"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Shipra", "hi": "शिप्रा"}, {"key": "D", "en": "Yamuna", "hi": "यमुना"}]','A');
INSERT INTO knowledge_quiz VALUES(1884,'Which deity is worshipped during Rohini Vrat?','रोहिणी व्रत में किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','A');
INSERT INTO knowledge_quiz VALUES(1885,'Which goddess is worshipped during Katyayani Puja?','कात्यायनी पूजा में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Katyayani", "hi": "कात्यायनी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Lakshmi", "hi": "लक्ष्मी"}]','B');
INSERT INTO knowledge_quiz VALUES(1886,'Which rhythmic instrument is most commonly used during a high-energy Aarti in North Indian temples?','उत्तर भारतीय मंदिरों में उच्च ऊर्जा वाली आरती के दौरान आमतौर पर किस वाद्य यंत्र का उपयोग किया जाता है?','[{"key": "A", "en": "Veena", "hi": "वीणा"}, {"key": "B", "en": "Manjira/Jhanjh", "hi": "मंजीरा/झांझ"}, {"key": "C", "en": "Flute", "hi": "बांसुरी"}, {"key": "D", "en": "Sitar", "hi": "सितार"}]','B');
INSERT INTO knowledge_quiz VALUES(1887,'Which flower is traditionally forbidden to be offered to Lord Shiva?','भगवान शिव को पारंपरिक रूप से कौन सा फूल अर्पित करना वर्जित है?','[{"key": "A", "en": "Datura", "hi": "धतूरा"}, {"key": "B", "en": "Ketaki", "hi": "केतकी"}, {"key": "C", "en": "Kaner", "hi": "कनेर"}, {"key": "D", "en": "Aprajita", "hi": "अपराजिता"}]','B');
INSERT INTO knowledge_quiz VALUES(1888,'Which puja step involves inviting the deity to reside in the idol or image?','पूजा के किस चरण में देवता को मूर्ति या चित्र में निवास करने के लिए आमंत्रित किया जाता है?','[{"key": "A", "en": "Avahana", "hi": "आह्वान"}, {"key": "B", "en": "Asana", "hi": "आसन"}, {"key": "C", "en": "Snana", "hi": "स्नान"}, {"key": "D", "en": "Pushpam", "hi": "पुष्पम"}]','A');
INSERT INTO knowledge_quiz VALUES(1889,'Which goddess is worshipped during Mangal Gauri Vrat?','मंगल गौरी व्रत में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(1890,'The Kapaleshwar Temple in Nashik is unique because it is a Shiva temple without which common feature?','नासिक का कपालेश्वर मंदिर अद्वितीय है क्योंकि यह एक शिव मंदिर है जिसमें कौन सी सामान्य विशेषता नहीं है?','[{"key": "A", "en": "Shivalinga", "hi": "शिवलिंग"}, {"key": "B", "en": "Nandi (the Bull)", "hi": "नंदी (बैल)"}, {"key": "C", "en": "Pujari", "hi": "पुजारी"}, {"key": "D", "en": "Bell", "hi": "घंटी"}]','B');
INSERT INTO knowledge_quiz VALUES(1891,'Which deity is worshipped during Dhanteras?','धनतेरस पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Kubera", "hi": "कुबेर"}, {"key": "B", "en": "Dhanvantari", "hi": "धन्वंतरि"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1892,'Which scripture is considered the essence of the Vedas?','वेदों का सार किस ग्रंथ को माना जाता है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Brahmanas", "hi": "ब्राह्मण"}, {"key": "D", "en": "Aranyakas", "hi": "आरण्यक"}]','A');
INSERT INTO knowledge_quiz VALUES(1893,'Which goddess is worshipped during Sharad Navratri?','शारदीय नवरात्रि में किस देवी की पूजा होती है?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','C');
INSERT INTO knowledge_quiz VALUES(1894,'Which river is associated with Lord Krishna’s childhood?','भगवान कृष्ण के बाल्यकाल से कौन सी नदी जुड़ी है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','B');
INSERT INTO knowledge_quiz VALUES(1895,'Which deity is worshipped during Guru Purnima?','गुरु पूर्णिमा पर किसकी पूजा होती है?','[{"key": "A", "en": "Brihaspati", "hi": "बृहस्पति"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "All gurus", "hi": "सभी गुरु"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','C');
INSERT INTO knowledge_quiz VALUES(1896,'Who is the composer of the powerful ''Durga Chalisa'' used to invoke the Goddess''s protection?','देवी की सुरक्षा का आह्वान करने के लिए उपयोग की जाने वाली शक्तिशाली ''दुर्गा चालीसा'' के रचयिता कौन माने जाते हैं?','[{"key": "A", "en": "Tulsidas", "hi": "तुलसीदास"}, {"key": "B", "en": "Ayodhya Prasad", "hi": "अयोध्या प्रसाद"}, {"key": "C", "en": "Surdas", "hi": "सूरदास"}, {"key": "D", "en": "Lallu Lal", "hi": "लल्लू लाल"}]','B');
INSERT INTO knowledge_quiz VALUES(1897,'The sound of which instrument is said to produce the ''Om'' vibration and is essential in temples?','किस वाद्ययंत्र की ध्वनि के बारे में कहा जाता है कि वह ''ओम'' की कंपन पैदा करती है और मंदिरों में अनिवार्य है?','[{"key": "A", "en": "Flute", "hi": "बांसुरी"}, {"key": "B", "en": "Shankh (Conch)", "hi": "शंख"}, {"key": "C", "en": "Veena", "hi": "वीणा"}, {"key": "D", "en": "Tabla", "hi": "तबला"}]','B');
INSERT INTO knowledge_quiz VALUES(1898,'Which goddess is worshipped during Ganga Dussehra?','गंगा दशहरा पर किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(1899,'What is the favorite offering (Bhog) of Lord Ganesha, often prepared during Ganesh Chaturthi?','भगवान गणेश का प्रिय भोग क्या है, जो अक्सर गणेश चतुर्थी के दौरान बनाया जाता है?','[{"key": "A", "en": "Peda", "hi": "पेड़ा"}, {"key": "B", "en": "Modak", "hi": "मोदक"}, {"key": "C", "en": "Halwa", "hi": "हलवा"}, {"key": "D", "en": "Kheer", "hi": "खीर"}]','B');
INSERT INTO knowledge_quiz VALUES(1900,'Which festival marks the return of Lord Rama to Ayodhya?','भगवान राम के अयोध्या लौटने का पर्व कौन सा है?','[{"key": "A", "en": "Ram Navami", "hi": "राम नवमी"}, {"key": "B", "en": "Dussehra", "hi": "दशहरा"}, {"key": "C", "en": "Diwali", "hi": "दीपावली"}, {"key": "D", "en": "Holi", "hi": "होली"}]','C');
INSERT INTO knowledge_quiz VALUES(1901,'Which sage is credited with creating the Tamil language?','किस ऋषि को तमिल भाषा बनाने का श्रेय दिया जाता है?','[{"key": "A", "en": "Sage Agastya", "hi": "ऋषि अगस्त्य"}, {"key": "B", "en": "Sage Markandeya", "hi": "ऋषि मार्कंडेय"}, {"key": "C", "en": "Sage Durvasa", "hi": "ऋषि दुर्वासा"}, {"key": "D", "en": "Sage Bhrigu", "hi": "ऋषि भृगु"}]','A');
INSERT INTO knowledge_quiz VALUES(1902,'Which son of King Dasharatha was born to Queen Sumitra along with Lakshmana?','राजा दशरथ के कौन से पुत्र रानी सुमित्रा से लक्ष्मण के साथ जन्मे थे?','[{"key": "A", "en": "Bharat", "hi": "भरत"}, {"key": "B", "en": "Shatrughna", "hi": "शत्रुघ्न"}, {"key": "C", "en": "Rama", "hi": "राम"}, {"key": "D", "en": "None of these", "hi": "इनमें से कोई नहीं"}]','B');
INSERT INTO knowledge_quiz VALUES(1903,'Which part of Sati fell at the Godavari River banks (Sarvashail Peetha)?','गोदावरी नदी के तट (सर्वशैल पीठ) पर सती का कौन सा अंग गिरा था?','[{"key": "A", "en": "Cheeks", "hi": "गाल"}, {"key": "B", "en": "Hips", "hi": "कूल्हे"}, {"key": "C", "en": "Feet", "hi": "पैर"}, {"key": "D", "en": "Wrists", "hi": "कलाई"}]','A');
INSERT INTO knowledge_quiz VALUES(1904,'Which weapon did Lord Rama use to defeat Ravana?','भगवान राम ने रावण का वध किस अस्त्र से किया?','[{"key": "A", "en": "Brahmastra", "hi": "ब्रह्मास्त्र"}, {"key": "B", "en": "Agneyastra", "hi": "आग्नेयास्त्र"}, {"key": "C", "en": "Pashupatastra", "hi": "पाशुपतास्त्र"}, {"key": "D", "en": "Narayanastra", "hi": "नारायणास्त्र"}]','A');
INSERT INTO knowledge_quiz VALUES(1905,'Which goddess is considered the consort of Lord Vishnu?','भगवान विष्णु की पत्नी कौन मानी जाती हैं?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','C');
INSERT INTO knowledge_quiz VALUES(1906,'Which river is believed to wash away sins according to Hindu belief?','हिंदू मान्यता के अनुसार कौन सी नदी पापों का नाश करती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','C');
INSERT INTO knowledge_quiz VALUES(1907,'Which festival marks the worship of tools and weapons?','औजारों और अस्त्र-शस्त्रों की पूजा किस पर्व में होती है?','[{"key": "A", "en": "Ayudha Puja", "hi": "आयुध पूजा"}, {"key": "B", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}, {"key": "C", "en": "Onam", "hi": "ओणम"}, {"key": "D", "en": "Vasant Panchami", "hi": "वसंत पंचमी"}]','A');
INSERT INTO knowledge_quiz VALUES(1908,'The Ekvira Devi Temple, a major site for the Koli community, is located right next to which famous Buddhist caves?','कोली समुदाय का प्रमुख स्थल एकवीरा देवी मंदिर किस प्रसिद्ध बौद्ध गुफाओं के ठीक बगल में स्थित है?','[{"key": "A", "en": "Kanheri Caves", "hi": "कान्हेरी गुफाएं"}, {"key": "B", "en": "Karla Caves", "hi": "कार्ला गुफाएं"}, {"key": "C", "en": "Bhaja Caves", "hi": "भाजा गुफाएं"}, {"key": "D", "en": "Bedse Caves", "hi": "बेडसे गुफाएं"}]','B');
INSERT INTO knowledge_quiz VALUES(1909,'Which sage is known as the author of the Mahabharata?','महाभारत के रचयिता के रूप में किस ऋषि को जाना जाता है?','[{"key": "A", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "B", "en": "Ved Vyasa", "hi": "वेदव्यास"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Narada", "hi": "नारद"}]','B');
INSERT INTO knowledge_quiz VALUES(1910,'Which Veda deals mainly with rituals and sacrifices?','कौन सा वेद मुख्य रूप से यज्ञ और कर्मकांड से संबंधित है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Samaveda", "hi": "सामवेद"}, {"key": "C", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','C');
INSERT INTO knowledge_quiz VALUES(1911,'Which Chalisa mentions the astronomical distance between the Sun and Earth long before modern science?','किस चालीसा में आधुनिक विज्ञान से बहुत पहले सूर्य और पृथ्वी के बीच की खगोलीय दूरी का उल्लेख मिलता है?','[{"key": "A", "en": "Shiva Chalisa", "hi": "शिव चालीसा"}, {"key": "B", "en": "Hanuman Chalisa", "hi": "हनुमान चालीसा"}, {"key": "C", "en": "Durga Chalisa", "hi": "दुर्गा चालीसा"}, {"key": "D", "en": "Ganesh Chalisa", "hi": "गणेश चालीसा"}]','B');
INSERT INTO knowledge_quiz VALUES(1912,'Which river flows through Prayagraj?','प्रयागराज नगर से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','C');
INSERT INTO knowledge_quiz VALUES(1913,'Which avatar of Vishnu appeared as a dwarf?','भगवान विष्णु का कौन सा अवतार बौने रूप में था?','[{"key": "A", "en": "Parashurama", "hi": "परशुराम"}, {"key": "B", "en": "Vamana", "hi": "वामन"}, {"key": "C", "en": "Varaha", "hi": "वराह"}, {"key": "D", "en": "Matsya", "hi": "मत्स्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1914,'Which festival is associated with the worship of Goddess Durga?','देवी दुर्गा की पूजा से कौन सा पर्व जुड़ा है?','[{"key": "A", "en": "Holi", "hi": "होली"}, {"key": "B", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "C", "en": "Diwali", "hi": "दीपावली"}, {"key": "D", "en": "Raksha Bandhan", "hi": "रक्षा बंधन"}]','B');
INSERT INTO knowledge_quiz VALUES(1915,'In which temple is the famous ''Aranmula Valla Sadhya'' (ritual feast) and Boat Race held?','किस मंदिर में प्रसिद्ध ''अरनमुला वल्ल सद्य'' (अनुष्ठान भोज) और नौका दौड़ आयोजित की जाती है?','[{"key": "A", "en": "Parthasarathy Temple", "hi": "पार्थसारथी मंदिर"}, {"key": "B", "en": "Siva Temple, Ernakulam", "hi": "शिव मंदिर, एर्नाकुलम"}, {"key": "C", "en": "Mannarasala Temple", "hi": "मन्नारसाला मंदिर"}, {"key": "D", "en": "Thiruvalla Temple", "hi": "तिरुवल्ला मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(1916,'Which Kerala temple is famous for its architecture and the massive mural painting of ''Gajendra Moksha''?','केरल का कौन सा मंदिर अपनी वास्तुकला और ''गजेंद्र मोक्ष'' के विशाल भित्ति चित्र (Mural) के लिए प्रसिद्ध है?','[{"key": "A", "en": "Krishnapuram Palace Temple", "hi": "कृष्णपुरम पैलेस मंदिर"}, {"key": "B", "en": "Padmanabhapuram Palace", "hi": "पद्मनाभपुरम पैलेस"}, {"key": "C", "en": "Ettumanoor Mahadeva", "hi": "एट्टुमानूर महादेव"}, {"key": "D", "en": "Vaikom Mahadeva", "hi": "वैकोम महादेव"}]','A');
INSERT INTO knowledge_quiz VALUES(1917,'Which Purana is dedicated mainly to Lord Shiva?','कौन सा पुराण मुख्य रूप से भगवान शिव को समर्पित है?','[{"key": "A", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "B", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Markandeya Purana", "hi": "मार्कण्डेय पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1918,'Which temple in Vietnam was a major center for Hindu worship by the Champa civilization?','वियतनाम का कौन सा मंदिर चंपा सभ्यता द्वारा हिंदू पूजा का एक प्रमुख केंद्र था?','[{"key": "A", "en": "My Son Sanctuary", "hi": "माई सन सैंक्चुअरी"}, {"key": "B", "en": "Po Nagar", "hi": "पो नगर"}, {"key": "C", "en": "Mariamman Temple", "hi": "मरियम्मन मंदिर"}, {"key": "D", "en": "Jade Emperor Pagoda", "hi": "जेड एम्परर पैगोडा"}]','A');
INSERT INTO knowledge_quiz VALUES(1919,'Which river is associated with Lord Krishna’s childhood?','भगवान कृष्ण के बाल्यकाल से कौन सी नदी जुड़ी है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Godavari", "hi": "गोदावरी"}, {"key": "D", "en": "Sarayu", "hi": "सरयू"}]','B');
INSERT INTO knowledge_quiz VALUES(1920,'Which ingredient is essential for the ''Tilak'' of Lord Vishnu, symbolizing purity?','शुद्धता का प्रतीक, भगवान विष्णु के ''तिलक'' के लिए कौन सी सामग्री अनिवार्य है?','[{"key": "A", "en": "Ash", "hi": "राख"}, {"key": "B", "en": "Sandalwood (Chandan)", "hi": "चंदन"}, {"key": "C", "en": "Kumkum", "hi": "कुमकुम"}, {"key": "D", "en": "Turmeric", "hi": "हल्दी"}]','B');
INSERT INTO knowledge_quiz VALUES(1921,'Which goddess is worshipped during Sharad Navratri?','शारदीय नवरात्रि में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(1922,'Which sacred city is known as the City of Light?','प्रकाश की नगरी के रूप में कौन सा पवित्र नगर प्रसिद्ध है?','[{"key": "A", "en": "Haridwar", "hi": "हरिद्वार"}, {"key": "B", "en": "Ujjain", "hi": "उज्जैन"}, {"key": "C", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "D", "en": "Dwarka", "hi": "द्वारका"}]','C');
INSERT INTO knowledge_quiz VALUES(1923,'Which river flows through Dwarka?','द्वारका नगर किस नदी से जुड़ा है?','[{"key": "A", "en": "Gomti", "hi": "गोमती"}, {"key": "B", "en": "Narmada", "hi": "नर्मदा"}, {"key": "C", "en": "Yamuna", "hi": "यमुना"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','A');
INSERT INTO knowledge_quiz VALUES(1924,'Which temple in Cambodia is known as the largest religious monument in the world?','कंबोडिया का कौन सा मंदिर दुनिया के सबसे बड़े धार्मिक स्मारक के रूप में जाना जाता है?','[{"key": "A", "en": "Bayon Temple", "hi": "बायोन मंदिर"}, {"key": "B", "en": "Angkor Wat", "hi": "अंगकोर वाट"}, {"key": "C", "en": "Preah Vihear", "hi": "प्रिया विहियर"}, {"key": "D", "en": "Banteay Srei", "hi": "बंतेय श्री"}]','B');
INSERT INTO knowledge_quiz VALUES(1925,'Which festival marks the worship of cows?','गायों की पूजा से संबंधित पर्व कौन सा है?','[{"key": "A", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "B", "en": "Gopashtami", "hi": "गोपाष्टमी"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}]','C');
INSERT INTO knowledge_quiz VALUES(1926,'Who was the sage who composed the Rigveda?','ऋग्वेद की रचना किस ऋषि ने की?','[{"key": "A", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "B", "en": "Ved Vyasa", "hi": "वेदव्यास"}, {"key": "C", "en": "Various sages", "hi": "विभिन्न ऋषियों ने"}, {"key": "D", "en": "Vashistha", "hi": "वशिष्ठ"}]','C');
INSERT INTO knowledge_quiz VALUES(1927,'How many mandalas are there in the Rigveda?','ऋग्वेद में कितने मंडल हैं?','[{"key": "A", "en": "8", "hi": "8"}, {"key": "B", "en": "9", "hi": "9"}, {"key": "C", "en": "10", "hi": "10"}, {"key": "D", "en": "12", "hi": "12"}]','C');
INSERT INTO knowledge_quiz VALUES(1928,'Which Veda deals mainly with rituals and sacrifices?','कौन सा वेद मुख्य रूप से यज्ञ और कर्मकांड से संबंधित है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Samaveda", "hi": "सामवेद"}, {"key": "C", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','C');
INSERT INTO knowledge_quiz VALUES(1929,'Which Veda is associated with music and chants?','कौन सा वेद संगीत और गायन से संबंधित है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Samaveda", "hi": "सामवेद"}, {"key": "C", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','B');
INSERT INTO knowledge_quiz VALUES(1930,'Which Veda contains hymns related to daily life and healing?','दैनिक जीवन और उपचार से संबंधित मंत्र किस वेद में हैं?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Samaveda", "hi": "सामवेद"}, {"key": "C", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','D');
INSERT INTO knowledge_quiz VALUES(1931,'Which Upanishad contains the Mahavakya ''Tat Tvam Asi''?','''तत्त्वमसि'' महावाक्य किस उपनिषद में है?','[{"key": "A", "en": "Kena Upanishad", "hi": "केन उपनिषद"}, {"key": "B", "en": "Chandogya Upanishad", "hi": "छांदोग्य उपनिषद"}, {"key": "C", "en": "Isha Upanishad", "hi": "ईश उपनिषद"}, {"key": "D", "en": "Aitareya Upanishad", "hi": "ऐतरेय उपनिषद"}]','B');
INSERT INTO knowledge_quiz VALUES(1932,'What does the word ''Upanishad'' primarily mean?','''उपनिषद'' शब्द का मुख्य अर्थ क्या है?','[{"key": "A", "en": "Prayer", "hi": "प्रार्थना"}, {"key": "B", "en": "Secret teaching", "hi": "गूढ़ शिक्षा"}, {"key": "C", "en": "Ritual", "hi": "कर्मकांड"}, {"key": "D", "en": "Song", "hi": "गीत"}]','B');
INSERT INTO knowledge_quiz VALUES(1933,'Which scripture is known as the ''essence of the Upanishads''?','कौन सा ग्रंथ ''उपनिषदों का सार'' कहलाता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "D", "en": "Brahma Sutra", "hi": "ब्रह्मसूत्र"}]','C');
INSERT INTO knowledge_quiz VALUES(1934,'Who authored the Brahma Sutra?','ब्रह्मसूत्र के रचयिता कौन हैं?','[{"key": "A", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "B", "en": "Badarayana", "hi": "बादरायण"}, {"key": "C", "en": "Ved Vyasa", "hi": "वेदव्यास"}, {"key": "D", "en": "Shankaracharya", "hi": "शंकराचार्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1935,'Which philosophy is associated with Shankaracharya?','शंकराचार्य किस दर्शन से जुड़े हैं?','[{"key": "A", "en": "Dvaita", "hi": "द्वैत"}, {"key": "B", "en": "Vishishtadvaita", "hi": "विशिष्टाद्वैत"}, {"key": "C", "en": "Advaita", "hi": "अद्वैत"}, {"key": "D", "en": "Samkhya", "hi": "सांख्य"}]','C');
INSERT INTO knowledge_quiz VALUES(1936,'Which philosopher propounded Vishishtadvaita philosophy?','विशिष्टाद्वैत दर्शन के प्रवर्तक कौन थे?','[{"key": "A", "en": "Shankaracharya", "hi": "शंकराचार्य"}, {"key": "B", "en": "Ramanujacharya", "hi": "रामानुजाचार्य"}, {"key": "C", "en": "Madhvacharya", "hi": "माध्वाचार्य"}, {"key": "D", "en": "Kapila", "hi": "कपिल"}]','B');
INSERT INTO knowledge_quiz VALUES(1937,'Which philosophy was taught by Madhvacharya?','माध्वाचार्य ने कौन सा दर्शन प्रतिपादित किया?','[{"key": "A", "en": "Advaita", "hi": "अद्वैत"}, {"key": "B", "en": "Dvaita", "hi": "द्वैत"}, {"key": "C", "en": "Vishishtadvaita", "hi": "विशिष्टाद्वैत"}, {"key": "D", "en": "Yoga", "hi": "योग"}]','B');
INSERT INTO knowledge_quiz VALUES(1938,'Who is regarded as the founder of Samkhya philosophy?','सांख्य दर्शन के प्रवर्तक कौन माने जाते हैं?','[{"key": "A", "en": "Patanjali", "hi": "पतंजलि"}, {"key": "B", "en": "Kapila", "hi": "कपिल"}, {"key": "C", "en": "Vyasa", "hi": "व्यास"}, {"key": "D", "en": "Gautama", "hi": "गौतम"}]','B');
INSERT INTO knowledge_quiz VALUES(1939,'Which sage compiled the Yoga Sutras?','योगसूत्र की रचना किस ऋषि ने की?','[{"key": "A", "en": "Kapila", "hi": "कपिल"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Patanjali", "hi": "पतंजलि"}, {"key": "D", "en": "Gautama", "hi": "गौतम"}]','C');
INSERT INTO knowledge_quiz VALUES(1940,'How many limbs are described in Ashtanga Yoga?','अष्टांग योग में कितने अंग बताए गए हैं?','[{"key": "A", "en": "6", "hi": "6"}, {"key": "B", "en": "7", "hi": "7"}, {"key": "C", "en": "8", "hi": "8"}, {"key": "D", "en": "9", "hi": "9"}]','C');
INSERT INTO knowledge_quiz VALUES(1941,'Which is the first limb of Ashtanga Yoga?','अष्टांग योग का पहला अंग कौन सा है?','[{"key": "A", "en": "Niyama", "hi": "नियम"}, {"key": "B", "en": "Asana", "hi": "आसन"}, {"key": "C", "en": "Yama", "hi": "यम"}, {"key": "D", "en": "Pranayama", "hi": "प्राणायाम"}]','C');
INSERT INTO knowledge_quiz VALUES(1942,'Which concept refers to the law of cause and effect?','कर्म और फल के नियम को क्या कहा जाता है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Karma", "hi": "कर्म"}, {"key": "C", "en": "Moksha", "hi": "मोक्ष"}, {"key": "D", "en": "Bhakti", "hi": "भक्ति"}]','B');
INSERT INTO knowledge_quiz VALUES(1943,'What is the ultimate goal of human life according to Hindu philosophy?','हिंदू दर्शन के अनुसार मानव जीवन का अंतिम लक्ष्य क्या है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Artha", "hi": "अर्थ"}, {"key": "C", "en": "Kama", "hi": "काम"}, {"key": "D", "en": "Moksha", "hi": "मोक्ष"}]','D');
INSERT INTO knowledge_quiz VALUES(1944,'How many Purusharthas are described in Hinduism?','हिंदू धर्म में पुरुषार्थ कितने बताए गए हैं?','[{"key": "A", "en": "3", "hi": "3"}, {"key": "B", "en": "4", "hi": "4"}, {"key": "C", "en": "5", "hi": "5"}, {"key": "D", "en": "6", "hi": "6"}]','B');
INSERT INTO knowledge_quiz VALUES(1945,'Which Purushartha relates to material prosperity?','कौन सा पुरुषार्थ भौतिक समृद्धि से संबंधित है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Artha", "hi": "अर्थ"}, {"key": "C", "en": "Kama", "hi": "काम"}, {"key": "D", "en": "Moksha", "hi": "मोक्ष"}]','B');
INSERT INTO knowledge_quiz VALUES(1946,'Which Purushartha represents desire and pleasure?','इच्छा और आनंद को कौन सा पुरुषार्थ दर्शाता है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Artha", "hi": "अर्थ"}, {"key": "C", "en": "Kama", "hi": "काम"}, {"key": "D", "en": "Moksha", "hi": "मोक्ष"}]','C');
INSERT INTO knowledge_quiz VALUES(1947,'Which Purushartha guides righteous living?','धार्मिक जीवन का मार्गदर्शन कौन सा पुरुषार्थ करता है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Artha", "hi": "अर्थ"}, {"key": "C", "en": "Kama", "hi": "काम"}, {"key": "D", "en": "Moksha", "hi": "मोक्ष"}]','A');
INSERT INTO knowledge_quiz VALUES(1948,'What is the cycle of birth and death called?','जन्म और मृत्यु के चक्र को क्या कहा जाता है?','[{"key": "A", "en": "Karma", "hi": "कर्म"}, {"key": "B", "en": "Samsara", "hi": "संसार"}, {"key": "C", "en": "Maya", "hi": "माया"}, {"key": "D", "en": "Yoga", "hi": "योग"}]','B');
INSERT INTO knowledge_quiz VALUES(1949,'What liberates the soul from Samsara?','संसार से आत्मा को क्या मुक्त करता है?','[{"key": "A", "en": "Karma", "hi": "कर्म"}, {"key": "B", "en": "Dharma", "hi": "धर्म"}, {"key": "C", "en": "Moksha", "hi": "मोक्ष"}, {"key": "D", "en": "Bhakti", "hi": "भक्ति"}]','C');
INSERT INTO knowledge_quiz VALUES(1950,'Which path emphasizes devotion to God?','ईश्वर भक्ति पर कौन सा मार्ग विशेष बल देता है?','[{"key": "A", "en": "Jnana Yoga", "hi": "ज्ञान योग"}, {"key": "B", "en": "Karma Yoga", "hi": "कर्म योग"}, {"key": "C", "en": "Bhakti Yoga", "hi": "भक्ति योग"}, {"key": "D", "en": "Raja Yoga", "hi": "राज योग"}]','C');
INSERT INTO knowledge_quiz VALUES(1951,'Who was the teacher of Lord Rama?','भगवान राम के गुरु कौन थे?','[{"key": "A", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "B", "en": "Vishwamitra", "hi": "विश्वामित्र"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1952,'Which ashram did Lord Rama visit during his exile?','वनवास के दौरान भगवान राम किस आश्रम में गए?','[{"key": "A", "en": "Naimisharanya", "hi": "नैमिषारण्य"}, {"key": "B", "en": "Agastya Ashram", "hi": "अगस्त्य आश्रम"}, {"key": "C", "en": "Dandakaranya", "hi": "दण्डकारण्य"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(1953,'Who was the sister of Ravana whose nose was cut ?','रावण की वह बहन कौन थी जिसकी नाक कटी थी?','[{"key": "A", "en": "Trijata", "hi": "त्रिजटा"}, {"key": "B", "en": "Surpanakha", "hi": "शूर्पणखा"}, {"key": "C", "en": "Mandodari", "hi": "मंदोदरी"}, {"key": "D", "en": "Simhika", "hi": "सिंहिका"}]','B');
INSERT INTO knowledge_quiz VALUES(1954,'Which serpent did Lord Krishna subdue in the Yamuna river?','भगवान कृष्ण ने यमुना नदी में किस नाग का दमन किया?','[{"key": "A", "en": "Takshaka", "hi": "तक्षक"}, {"key": "B", "en": "Vasuki", "hi": "वासुकी"}, {"key": "C", "en": "Kaliya", "hi": "कालिया"}, {"key": "D", "en": "Shesha", "hi": "शेष"}]','C');
INSERT INTO knowledge_quiz VALUES(1955,'Which avatar of Vishnu appeared as a fish?','भगवान विष्णु का कौन सा अवतार मछली रूप में प्रकट हुआ?','[{"key": "A", "en": "Kurma", "hi": "कूर्म"}, {"key": "B", "en": "Matsya", "hi": "मत्स्य"}, {"key": "C", "en": "Varaha", "hi": "वराह"}, {"key": "D", "en": "Vamana", "hi": "वामन"}]','B');
INSERT INTO knowledge_quiz VALUES(1956,'The ''Bharat Milap'' festival, which commemorates the reunion of Rama and Bharata, is most famously celebrated in which city?','राम और भरत के पुनर्मिलन की स्मृति में मनाया जाने वाला ''भरत मिलाप'' उत्सव सबसे प्रसिद्ध रूप से किस शहर में मनाया जाता है?','[{"key": "A", "en": "Lucknow", "hi": "लखनऊ"}, {"key": "B", "en": "Varanasi (Nati Imli)", "hi": "वाराणसी (नाटी इमली)"}, {"key": "C", "en": "Chitrakoot", "hi": "चित्रकूट"}, {"key": "D", "en": "Prayagraj", "hi": "प्रयागराज"}]','B');
INSERT INTO knowledge_quiz VALUES(1957,'Who emerged with the nectar during Samudra Manthan?','समुद्र मंथन में अमृत लेकर कौन प्रकट हुए?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Dhanvantari", "hi": "धन्वंतरि"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','C');
INSERT INTO knowledge_quiz VALUES(1958,'Which goddess emerged during Samudra Manthan?','समुद्र मंथन से कौन सी देवी प्रकट हुईं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','C');
INSERT INTO knowledge_quiz VALUES(1959,'Which god consumed poison during the churning of the ocean?','समुद्र मंथन के दौरान विष किस देवता ने पिया?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','C');
INSERT INTO knowledge_quiz VALUES(1960,'Which name of Shiva refers to his blue throat?','शिव के नीले कंठ को दर्शाने वाला नाम कौन सा है?','[{"key": "A", "en": "Mahadeva", "hi": "महादेव"}, {"key": "B", "en": "Neelkanth", "hi": "नीलकंठ"}, {"key": "C", "en": "Trilochana", "hi": "त्रिलोचन"}, {"key": "D", "en": "Shankara", "hi": "शंकर"}]','B');
INSERT INTO knowledge_quiz VALUES(1961,'Which goddess is worshipped as the consort of Lord Shiva?','भगवान शिव की पत्नी के रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','B');
INSERT INTO knowledge_quiz VALUES(1962,'Which festival celebrates the victory of Goddess Durga over Mahishasura?','महिषासुर पर देवी दुर्गा की विजय किस पर्व से जुड़ी है?','[{"key": "A", "en": "Diwali", "hi": "दीपावली"}, {"key": "B", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "C", "en": "Dussehra", "hi": "दशहरा"}, {"key": "D", "en": "Holi", "hi": "होली"}]','C');
INSERT INTO knowledge_quiz VALUES(1963,'Which sacred text contains the Vishnu Sahasranama?','विष्णु सहस्रनाम किस ग्रंथ में मिलता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "D", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(1964,'The Nishkalank Mahadev Temple is situated inside the sea. In which district is it located?','निष्कलंक महादेव मंदिर समुद्र के अंदर स्थित है। यह किस जिले में है?','[{"key": "A", "en": "Jamnagar", "hi": "जामनगर"}, {"key": "B", "en": "Bhavnagar", "hi": "भावनगर"}, {"key": "C", "en": "Valsad", "hi": "वलसाड"}, {"key": "D", "en": "Devbhumi Dwarka", "hi": "देवभूमि द्वारका"}]','B');
INSERT INTO knowledge_quiz VALUES(1965,'Who was the only gopi who is said to have known Krishna''s divinity from birth?','कौन सी एकमात्र गोपी थी जिसके बारे में कहा जाता है कि वह जन्म से ही कृष्ण की दिव्यता जानती थी?','[{"key": "A", "en": "Radha", "hi": "राधा"}, {"key": "B", "en": "Lalita", "hi": "ललिता"}, {"key": "C", "en": "Vishakha", "hi": "विशाखा"}, {"key": "D", "en": "Chandravali", "hi": "चंद्रावली"}]','B');
INSERT INTO knowledge_quiz VALUES(1966,'The ''Aditya Temple'' (Sun Temple) of Multan, once a famous pilgrimage site, was located in which modern-day country?','मुलतान का ''आदित्य मंदिर'' (सूर्य मंदिर), जो कभी एक प्रसिद्ध तीर्थ स्थल था, वर्तमान में किस देश में स्थित था?','[{"key": "A", "en": "India", "hi": "भारत"}, {"key": "B", "en": "Afghanistan", "hi": "अफगानिस्तान"}, {"key": "C", "en": "Pakistan", "hi": "पाकिस्तान"}, {"key": "D", "en": "Iran", "hi": "ईरान"}]','C');
INSERT INTO knowledge_quiz VALUES(1967,'Which part of Lord Shiva''s body is worshipped at Madmaheshwar?','मदमहेश्वर में भगवान शिव के शरीर के किस भाग की पूजा की जाती है?','[{"key": "A", "en": "Arms", "hi": "भुजाएं"}, {"key": "B", "en": "Navel (Nabhi)", "hi": "नाभि"}, {"key": "C", "en": "Hump", "hi": "कूबड़"}, {"key": "D", "en": "Face", "hi": "मुख"}]','B');
INSERT INTO knowledge_quiz VALUES(1968,'Which Sun Temple in Bihar is unique because its entrance faces West instead of the traditional East?','बिहार का कौन सा सूर्य मंदिर अद्वितीय है क्योंकि इसका प्रवेश द्वार पारंपरिक पूर्व के बजाय पश्चिम की ओर है?','[{"key": "A", "en": "Deo Sun Temple", "hi": "देव सूर्य मंदिर"}, {"key": "B", "en": "Surajpur Sun Temple", "hi": "सूरजपुर सूर्य मंदिर"}, {"key": "C", "en": "Ular Sun Temple", "hi": "उलार सूर्य मंदिर"}, {"key": "D", "en": "Bargao Sun Temple", "hi": "बड़गाँव सूर्य मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(1969,'Which scripture is a dialogue between Krishna and Arjuna?','कृष्ण और अर्जुन के संवाद वाला ग्रंथ कौन सा है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Yoga Sutra", "hi": "योगसूत्र"}]','B');
INSERT INTO knowledge_quiz VALUES(1970,'Which deity is worshipped during Navratri?','नवरात्रि में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','C');
INSERT INTO knowledge_quiz VALUES(1971,'Which river flows through Mathura?','मथुरा नगर से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','B');
INSERT INTO knowledge_quiz VALUES(1972,'Which word is said during a Havan offering?','हवन में आहुति देते समय कौन सा शब्द बोला जाता है?','[{"key": "A", "en": "Namaste", "hi": "नमस्ते"}, {"key": "B", "en": "Svaha", "hi": "स्वाहा"}, {"key": "C", "en": "Shanti", "hi": "शांति"}, {"key": "D", "en": "Pranam", "hi": "प्रणाम"}]','B');
INSERT INTO knowledge_quiz VALUES(1973,'Which sacred plant is worshipped daily in Hindu households?','हिंदू घरों में प्रतिदिन किस पवित्र पौधे की पूजा होती है?','[{"key": "A", "en": "Neem", "hi": "नीम"}, {"key": "B", "en": "Tulsi", "hi": "तुलसी"}, {"key": "C", "en": "Peepal", "hi": "पीपल"}, {"key": "D", "en": "Banyan", "hi": "वट"}]','B');
INSERT INTO knowledge_quiz VALUES(1974,'The famous Pashupatinath Temple, dedicated to Lord Shiva, is located in which city?','भगवान शिव को समर्पित प्रसिद्ध पशुपतिनाथ मंदिर किस शहर में स्थित है?','[{"key": "A", "en": "Kathmandu, Nepal", "hi": "काठमांडू, नेपाल"}, {"key": "B", "en": "Thimphu, Bhutan", "hi": "थिम्पू, भूटान"}, {"key": "C", "en": "Colombo, Sri Lanka", "hi": "कोलंबो, श्रीलंका"}, {"key": "D", "en": "Dhaka, Bangladesh", "hi": "ढाका, बांग्लादेश"}]','A');
INSERT INTO knowledge_quiz VALUES(1975,'Which festival celebrates the return of Lord Rama to Ayodhya?','भगवान राम के अयोध्या लौटने का उत्सव कौन सा है?','[{"key": "A", "en": "Ram Navami", "hi": "राम नवमी"}, {"key": "B", "en": "Dussehra", "hi": "दशहरा"}, {"key": "C", "en": "Diwali", "hi": "दीपावली"}, {"key": "D", "en": "Holi", "hi": "होली"}]','C');
INSERT INTO knowledge_quiz VALUES(1976,'Which ashrama represents the student stage of life?','जीवन के विद्यार्थी चरण को कौन सा आश्रम दर्शाता है?','[{"key": "A", "en": "Brahmacharya", "hi": "ब्रह्मचर्य"}, {"key": "B", "en": "Grihastha", "hi": "गृहस्थ"}, {"key": "C", "en": "Vanaprastha", "hi": "वानप्रस्थ"}, {"key": "D", "en": "Sannyasa", "hi": "सन्यास"}]','A');
INSERT INTO knowledge_quiz VALUES(1977,'Which ashrama is focused on household duties?','कौन सा आश्रम गृहस्थ जीवन से संबंधित है?','[{"key": "A", "en": "Brahmacharya", "hi": "ब्रह्मचर्य"}, {"key": "B", "en": "Grihastha", "hi": "गृहस्थ"}, {"key": "C", "en": "Vanaprastha", "hi": "वानप्रस्थ"}, {"key": "D", "en": "Sannyasa", "hi": "सन्यास"}]','B');
INSERT INTO knowledge_quiz VALUES(1978,'Which ashrama involves withdrawal from worldly life?','सांसारिक जीवन से धीरे-धीरे विरक्ति किस आश्रम में होती है?','[{"key": "A", "en": "Brahmacharya", "hi": "ब्रह्मचर्य"}, {"key": "B", "en": "Grihastha", "hi": "गृहस्थ"}, {"key": "C", "en": "Vanaprastha", "hi": "वानप्रस्थ"}, {"key": "D", "en": "Sannyasa", "hi": "सन्यास"}]','C');
INSERT INTO knowledge_quiz VALUES(1979,'Which ashrama signifies complete renunciation?','पूर्ण त्याग किस आश्रम में किया जाता है?','[{"key": "A", "en": "Brahmacharya", "hi": "ब्रह्मचर्य"}, {"key": "B", "en": "Grihastha", "hi": "गृहस्थ"}, {"key": "C", "en": "Vanaprastha", "hi": "वानप्रस्थ"}, {"key": "D", "en": "Sannyasa", "hi": "सन्यास"}]','D');
INSERT INTO knowledge_quiz VALUES(1980,'How many ashramas are described in Hinduism?','हिंदू धर्म में कुल कितने आश्रम बताए गए हैं?','[{"key": "A", "en": "3", "hi": "3"}, {"key": "B", "en": "4", "hi": "4"}, {"key": "C", "en": "5", "hi": "5"}, {"key": "D", "en": "6", "hi": "6"}]','B');
INSERT INTO knowledge_quiz VALUES(1981,'Which concept refers to righteous duty?','धार्मिक कर्तव्य को किस शब्द से जाना जाता है?','[{"key": "A", "en": "Karma", "hi": "कर्म"}, {"key": "B", "en": "Dharma", "hi": "धर्म"}, {"key": "C", "en": "Moksha", "hi": "मोक्ष"}, {"key": "D", "en": "Maya", "hi": "माया"}]','B');
INSERT INTO knowledge_quiz VALUES(1982,'Which term denotes illusion or worldly attachment?','माया या सांसारिक आसक्ति को कौन सा शब्द दर्शाता है?','[{"key": "A", "en": "Maya", "hi": "माया"}, {"key": "B", "en": "Karma", "hi": "कर्म"}, {"key": "C", "en": "Bhakti", "hi": "भक्ति"}, {"key": "D", "en": "Yoga", "hi": "योग"}]','A');
INSERT INTO knowledge_quiz VALUES(1983,'Which concept refers to devotion toward God?','ईश्वर के प्रति भक्ति को किस शब्द से व्यक्त किया जाता है?','[{"key": "A", "en": "Karma", "hi": "कर्म"}, {"key": "B", "en": "Jnana", "hi": "ज्ञान"}, {"key": "C", "en": "Bhakti", "hi": "भक्ति"}, {"key": "D", "en": "Tapas", "hi": "तप"}]','C');
INSERT INTO knowledge_quiz VALUES(1984,'Which yoga emphasizes selfless action?','निष्काम कर्म पर कौन सा योग बल देता है?','[{"key": "A", "en": "Bhakti Yoga", "hi": "भक्ति योग"}, {"key": "B", "en": "Jnana Yoga", "hi": "ज्ञान योग"}, {"key": "C", "en": "Karma Yoga", "hi": "कर्म योग"}, {"key": "D", "en": "Raja Yoga", "hi": "राज योग"}]','C');
INSERT INTO knowledge_quiz VALUES(1985,'Which yoga focuses on knowledge and wisdom?','ज्ञान और विवेक पर कौन सा योग केंद्रित है?','[{"key": "A", "en": "Bhakti Yoga", "hi": "भक्ति योग"}, {"key": "B", "en": "Jnana Yoga", "hi": "ज्ञान योग"}, {"key": "C", "en": "Karma Yoga", "hi": "कर्म योग"}, {"key": "D", "en": "Hatha Yoga", "hi": "हठ योग"}]','B');
INSERT INTO knowledge_quiz VALUES(1986,'Which yoga focuses on meditation and mind control?','ध्यान और मन नियंत्रण पर कौन सा योग केंद्रित है?','[{"key": "A", "en": "Bhakti Yoga", "hi": "भक्ति योग"}, {"key": "B", "en": "Karma Yoga", "hi": "कर्म योग"}, {"key": "C", "en": "Raja Yoga", "hi": "राज योग"}, {"key": "D", "en": "Jnana Yoga", "hi": "ज्ञान योग"}]','C');
INSERT INTO knowledge_quiz VALUES(1987,'Which scripture explains Raja Yoga in detail?','राज योग का विस्तार से वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Vedas", "hi": "वेद"}]','A');
INSERT INTO knowledge_quiz VALUES(1988,'Which quality means non-violence?','अहिंसा किस गुण को दर्शाती है?','[{"key": "A", "en": "Satya", "hi": "सत्य"}, {"key": "B", "en": "Ahimsa", "hi": "अहिंसा"}, {"key": "C", "en": "Asteya", "hi": "अस्तेय"}, {"key": "D", "en": "Aparigraha", "hi": "अपरिग्रह"}]','B');
INSERT INTO knowledge_quiz VALUES(1989,'Which yama emphasizes truthfulness?','सत्य पर बल देने वाला यम कौन सा है?','[{"key": "A", "en": "Ahimsa", "hi": "अहिंसा"}, {"key": "B", "en": "Satya", "hi": "सत्य"}, {"key": "C", "en": "Asteya", "hi": "अस्तेय"}, {"key": "D", "en": "Brahmacharya", "hi": "ब्रह्मचर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(1990,'Which niyama refers to cleanliness?','शुद्धता से संबंधित नियम कौन सा है?','[{"key": "A", "en": "Saucha", "hi": "शौच"}, {"key": "B", "en": "Santosha", "hi": "संतोष"}, {"key": "C", "en": "Tapas", "hi": "तप"}, {"key": "D", "en": "Ishvara Pranidhana", "hi": "ईश्वर प्रणिधान"}]','A');
INSERT INTO knowledge_quiz VALUES(1991,'Which niyama emphasizes contentment?','संतोष पर बल देने वाला नियम कौन सा है?','[{"key": "A", "en": "Saucha", "hi": "शौच"}, {"key": "B", "en": "Santosha", "hi": "संतोष"}, {"key": "C", "en": "Tapas", "hi": "तप"}, {"key": "D", "en": "Svadhyaya", "hi": "स्वाध्याय"}]','B');
INSERT INTO knowledge_quiz VALUES(1992,'Which practice involves self-study?','स्वाध्याय किस अभ्यास से संबंधित है?','[{"key": "A", "en": "Tapas", "hi": "तप"}, {"key": "B", "en": "Svadhyaya", "hi": "स्वाध्याय"}, {"key": "C", "en": "Asana", "hi": "आसन"}, {"key": "D", "en": "Pranayama", "hi": "प्राणायाम"}]','B');
INSERT INTO knowledge_quiz VALUES(1993,'Which limb of yoga deals with posture?','योग का कौन सा अंग आसन से संबंधित है?','[{"key": "A", "en": "Asana", "hi": "आसन"}, {"key": "B", "en": "Pranayama", "hi": "प्राणायाम"}, {"key": "C", "en": "Pratyahara", "hi": "प्रत्याहार"}, {"key": "D", "en": "Dharana", "hi": "धारणा"}]','A');
INSERT INTO knowledge_quiz VALUES(1994,'Which limb of yoga controls the breath?','योग का कौन सा अंग श्वास नियंत्रण से संबंधित है?','[{"key": "A", "en": "Asana", "hi": "आसन"}, {"key": "B", "en": "Pranayama", "hi": "प्राणायाम"}, {"key": "C", "en": "Dhyana", "hi": "ध्यान"}, {"key": "D", "en": "Samadhi", "hi": "समाधि"}]','B');
INSERT INTO knowledge_quiz VALUES(1995,'Which limb involves withdrawal of senses?','इंद्रियों की वापसी से संबंधित योग अंग कौन सा है?','[{"key": "A", "en": "Dharana", "hi": "धारणा"}, {"key": "B", "en": "Pratyahara", "hi": "प्रत्याहार"}, {"key": "C", "en": "Dhyana", "hi": "ध्यान"}, {"key": "D", "en": "Samadhi", "hi": "समाधि"}]','B');
INSERT INTO knowledge_quiz VALUES(1996,'Which limb of yoga represents concentration?','एकाग्रता को कौन सा योग अंग दर्शाता है?','[{"key": "A", "en": "Pratyahara", "hi": "प्रत्याहार"}, {"key": "B", "en": "Dharana", "hi": "धारणा"}, {"key": "C", "en": "Dhyana", "hi": "ध्यान"}, {"key": "D", "en": "Samadhi", "hi": "समाधि"}]','B');
INSERT INTO knowledge_quiz VALUES(1997,'Which limb of yoga signifies meditation?','ध्यान को कौन सा योग अंग दर्शाता है?','[{"key": "A", "en": "Dharana", "hi": "धारणा"}, {"key": "B", "en": "Dhyana", "hi": "ध्यान"}, {"key": "C", "en": "Samadhi", "hi": "समाधि"}, {"key": "D", "en": "Pranayama", "hi": "प्राणायाम"}]','B');
