INSERT INTO knowledge_quiz VALUES(1999,'Which practice leads to liberation according to Yoga philosophy?','योग दर्शन के अनुसार मोक्ष की ओर कौन सा अभ्यास ले जाता है?','[{"key": "A", "en": "Only rituals", "hi": "केवल कर्मकांड"}, {"key": "B", "en": "Ashtanga Yoga", "hi": "अष्टांग योग"}, {"key": "C", "en": "Worldly enjoyment", "hi": "सांसारिक भोग"}, {"key": "D", "en": "Material wealth", "hi": "भौतिक संपत्ति"}]','B');
