INSERT INTO knowledge_quiz VALUES(2004,'Which river did Lord Krishna play near during his childhood?','भगवान कृष्ण ने बाल्यकाल में किस नदी के तट पर लीला की?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Godavari", "hi": "गोदावरी"}, {"key": "D", "en": "Sarayu", "hi": "सरयू"}]','B');
INSERT INTO knowledge_quiz VALUES(2005,'Who was the brother of Bali (Vali)?','बालि (वालि) के भाई कौन थे?','[{"key": "A", "en": "Hanuman", "hi": "हनुमान"}, {"key": "B", "en": "Sugriva", "hi": "सुग्रीव"}, {"key": "C", "en": "Angada", "hi": "अंगद"}, {"key": "D", "en": "Nal", "hi": "नल"}]','B');
INSERT INTO knowledge_quiz VALUES(2006,'The ''Navagraha Temple'' in Guwahati, dedicated to the nine celestial bodies, is located on which hill?','नौ खगोलीय पिंडों को समर्पित गुवाहाटी का ''नवग्रह मंदिर'' किस पहाड़ी पर स्थित है?','[{"key": "A", "en": "Nilachal Hill", "hi": "नीलाचल पहाड़ी"}, {"key": "B", "en": "Chitrachal Hill", "hi": "चित्राचल पहाड़ी"}, {"key": "C", "en": "Sandhyachal Hill", "hi": "संध्याचल पहाड़ी"}, {"key": "D", "en": "Kalapahar", "hi": "कालापहाड़"}]','B');
INSERT INTO knowledge_quiz VALUES(2007,'The ''Shitala Mata Chalisa'' is recited to seek protection from which type of diseases?','शीतला माता चालीसा का पाठ किस प्रकार की बीमारियों से सुरक्षा पाने के लिए किया जाता है?','[{"key": "A", "en": "Heart diseases", "hi": "हृदय रोग"}, {"key": "B", "en": "Skin diseases/Pox", "hi": "त्वचा रोग/चेचक"}, {"key": "C", "en": "Bone injuries", "hi": "हड्डियों की चोट"}, {"key": "D", "en": "Mental stress", "hi": "मानसिक तनाव"}]','B');
INSERT INTO knowledge_quiz VALUES(2008,'Which sacred text explains the duties of kings?','राजाओं के कर्तव्यों का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "B", "en": "Yoga Sutra", "hi": "योगसूत्र"}, {"key": "C", "en": "Brahma Sutra", "hi": "ब्रह्मसूत्र"}, {"key": "D", "en": "Upanishads", "hi": "उपनिषद"}]','A');
INSERT INTO knowledge_quiz VALUES(2009,'Which sage is considered the father of Sankhya philosophy?','सांख्य दर्शन के प्रवर्तक किस ऋषि को माना जाता है?','[{"key": "A", "en": "Patanjali", "hi": "पतंजलि"}, {"key": "B", "en": "Kapila", "hi": "कपिल"}, {"key": "C", "en": "Vyasa", "hi": "व्यास"}, {"key": "D", "en": "Gautama", "hi": "गौतम"}]','B');
INSERT INTO knowledge_quiz VALUES(2010,'Which specific leaf is considered essential to be placed on any food offered to Lord Vishnu?','भगवान विष्णु को अर्पित किए जाने वाले किसी भी भोजन पर किस विशिष्ट पत्ते को रखना अनिवार्य माना जाता है?','[{"key": "A", "en": "Betel Leaf", "hi": "पान का पत्ता"}, {"key": "B", "en": "Neem Leaf", "hi": "नीम का पत्ता"}, {"key": "C", "en": "Tulsi Leaf", "hi": "तुलसी का पत्ता"}, {"key": "D", "en": "Banana Leaf", "hi": "केले का पत्ता"}]','C');
