INSERT INTO knowledge_quiz VALUES(2013,'Which mudra (hand gesture) is commonly used to offer water to the ancestors?','पूर्वजों को जल अर्पित करने के लिए आमतौर पर किस मुद्रा का उपयोग किया जाता है?','[{"key": "A", "en": "Anjali Mudra", "hi": "अंजलि मुद्रा"}, {"key": "B", "en": "Pitru Tirtha (through the thumb)", "hi": "पितृ तीर्थ (अंगूठे के माध्यम से)"}, {"key": "C", "en": "Dhyana Mudra", "hi": "ध्यान मुद्रा"}, {"key": "D", "en": "Abhaya Mudra", "hi": "अभय मुद्रा"}]','B');
INSERT INTO knowledge_quiz VALUES(2014,'Which sacred river flows through Rameswaram?','रामेश्वरम से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Kaveri", "hi": "कावेरी"}, {"key": "B", "en": "Vaigai", "hi": "वैगई"}, {"key": "C", "en": "No major river", "hi": "कोई प्रमुख नदी नहीं"}, {"key": "D", "en": "Tamiraparani", "hi": "ताम्रपर्णी"}]','C');
