INSERT INTO knowledge_quiz VALUES(2018,'Which deity is known as the lord of obstacles?','विघ्नों के स्वामी के रूप में किस देवता को जाना जाता है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Hanuman", "hi": "हनुमान"}]','B');
INSERT INTO knowledge_quiz VALUES(2019,'Which Aarti is traditionally performed to ward off ''Evil Eye'' or negative energies in many Indian households?','कई भारतीय घरों में ''नजर'' उतारने या नकारात्मक ऊर्जा को दूर करने के लिए पारंपरिक रूप से कौन सी आरती/प्रक्रिया की जाती है?','[{"key": "A", "en": "Niranjan/Drishti Aarti", "hi": "निरंजन/दृष्टि आरती"}, {"key": "B", "en": "Sandhya Aarti", "hi": "संध्या आरती"}, {"key": "C", "en": "Mangal Aarti", "hi": "मंगल आरती"}, {"key": "D", "en": "Shayan Aarti", "hi": "शयन आरती"}]','A');
INSERT INTO knowledge_quiz VALUES(2020,'Which deity is worshipped during Rohini Vrat?','रोहिणी व्रत में किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','A');
INSERT INTO knowledge_quiz VALUES(2021,'Which sacred river flows through Haridwar?','हरिद्वार से होकर कौन सी पवित्र नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Alaknanda", "hi": "अलकनंदा"}, {"key": "D", "en": "Mandakini", "hi": "मंदाकिनी"}]','B');
INSERT INTO knowledge_quiz VALUES(2022,'Which goddess is worshipped during Varalakshmi Vratam?','वरलक्ष्मी व्रतम में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(2023,'Which scripture is known as the fifth Veda?','किस ग्रंथ को पंचम वेद कहा जाता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Natya Shastra", "hi": "नाट्यशास्त्र"}, {"key": "D", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(2024,'Which deity is worshipped during Sankashti Chaturthi?','संकष्टी चतुर्थी पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2025,'Which river flows through Ayodhya?','अयोध्या नगर से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','C');
INSERT INTO knowledge_quiz VALUES(2026,'The ritual offering of food to the deity is known as:','देवता को भोजन अर्पित करने की विधि को किस नाम से जाना जाता है?','[{"key": "A", "en": "Akshata", "hi": "अक्षत"}, {"key": "B", "en": "Gandha", "hi": "गंध"}, {"key": "C", "en": "Naivedya", "hi": "नैवेद्य"}, {"key": "D", "en": "Deepa", "hi": "दीप"}]','C');
INSERT INTO knowledge_quiz VALUES(2027,'Most Chalisas begin and end with which specific poetic form?','अधिकांश चालीसाएँ किस विशिष्ट काव्य रूप (छंद) से शुरू और समाप्त होती हैं?','[{"key": "A", "en": "Chaupai", "hi": "चौपाई"}, {"key": "B", "en": "Doha (Couplet)", "hi": "दोहा"}, {"key": "C", "en": "Shloka", "hi": "श्लोक"}, {"key": "D", "en": "Bhajan", "hi": "भजन"}]','B');
INSERT INTO knowledge_quiz VALUES(2028,'The Kedarheshwar Cave near Harishchandreshwar temple features a Shiva Linga surrounded by water and supported by how many original pillars?','हरिश्चंद्रेश्वर मंदिर के पास केदारेश्वर गुफा में पानी से घिरा एक शिव लिंग है, जो मूल रूप से कितने स्तंभों पर टिका था?','[{"key": "A", "en": "2", "hi": "2"}, {"key": "B", "en": "4", "hi": "4"}, {"key": "C", "en": "8", "hi": "8"}, {"key": "D", "en": "12", "hi": "12"}]','B');
INSERT INTO knowledge_quiz VALUES(2029,'The ''Deori Temple'' near Ranchi is famous because cricketer frequently visits it. Which deity is worshipped here?','राँची के पास स्थित ''देउड़ी मंदिर'' इसलिए प्रसिद्ध है क्योंकि क्रिकेटर यहाँ अक्सर आते हैं। यहाँ किस देवी की पूजा की जाती है?','[{"key": "A", "en": "Durga (16-armed)", "hi": "दुर्गा (16-भुजा वाली)"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Kali", "hi": "काली"}, {"key": "D", "en": "Lakshmi", "hi": "लक्ष्मी"}]','A');
INSERT INTO knowledge_quiz VALUES(2030,'In the Hanuman Chalisa, Hanuman is described as ''Vidyavan Guni Ati Chatur''. What does ''Vidyavan'' mean?','हनुमान चालीसा में, हनुमान को ''विद्यावान गुणी अति चातुर'' बताया गया है। ''विद्यावान'' का क्या अर्थ है?','[{"key": "A", "en": "Wealthy", "hi": "धनवान"}, {"key": "B", "en": "Full of Knowledge/Learned", "hi": "ज्ञान से पूर्ण/विद्वान"}, {"key": "C", "en": "Strong", "hi": "शक्तिशाली"}, {"key": "D", "en": "Fast", "hi": "तेज"}]','B');
INSERT INTO knowledge_quiz VALUES(2031,'Which deity is worshipped during Amavasya?','अमावस्या पर सामान्यतः किसकी पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Pitrs", "hi": "पितृ"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','C');
INSERT INTO knowledge_quiz VALUES(2032,'Which festival is dedicated to the worship of cows?','गायों की पूजा को समर्पित पर्व कौन सा है?','[{"key": "A", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "B", "en": "Gopashtami", "hi": "गोपाष्टमी"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}]','C');
INSERT INTO knowledge_quiz VALUES(2033,'In which direction do the horses of Surya ideally start their journey every morning?','सूर्य के घोड़े आदर्श रूप से हर सुबह अपनी यात्रा किस दिशा में शुरू करते हैं?','[{"key": "A", "en": "West", "hi": "पश्चिम"}, {"key": "B", "en": "East", "hi": "पूर्व"}, {"key": "C", "en": "North", "hi": "उत्तर"}, {"key": "D", "en": "South", "hi": "दक्षिण"}]','B');
INSERT INTO knowledge_quiz VALUES(2034,'Which deity is worshipped during Guru Purnima?','गुरु पूर्णिमा पर किसकी पूजा होती है?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Brihaspati", "hi": "बृहस्पति"}, {"key": "C", "en": "All gurus", "hi": "सभी गुरु"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','C');
INSERT INTO knowledge_quiz VALUES(2035,'Which deity is known as the lord of wealth?','धन के देवता किसे कहा जाता है?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Kubera", "hi": "कुबेर"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(2036,'Which river flows through Varanasi?','वाराणसी नगर से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','B');
INSERT INTO knowledge_quiz VALUES(2037,'Which of the six main abodes (Arupadaiveedu) of Lord Murugan is located on the seashore?','भगवान मुरुगन के छह मुख्य निवासों (आरुपदैवीडु) में से कौन सा समुद्र तट पर स्थित है?','[{"key": "A", "en": "Palani", "hi": "पलानी"}, {"key": "B", "en": "Thiruchendur", "hi": "तिरुचेंदूर"}, {"key": "C", "en": "Swamimalai", "hi": "स्वामीमलै"}, {"key": "D", "en": "Pazhamudircholai", "hi": "पलामुदिरचोलै"}]','B');
INSERT INTO knowledge_quiz VALUES(2038,'To which deity is ''Lapsi'' commonly offered as Bhog?','किस देवी को ''लापसी'' आमतौर पर भोग के रूप में अर्पित किया जाता है?','[{"key": "A", "en": "Goddess Vaishno", "hi": "देवी वैष्णो"}, {"key": "B", "en": "Goddess Saraswati", "hi": "देवी सरस्वती"}, {"key": "C", "en": "Goddess Santoshi Maa", "hi": "देवी संतोषी माँ"}, {"key": "D", "en": "Goddess Tulsi", "hi": "देवी तुलसी"}]','C');
INSERT INTO knowledge_quiz VALUES(2039,'Which goddess is worshipped during Mangal Gauri Vrat?','मंगल गौरी व्रत में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(2040,'The Saptashrungi Devi temple is situated on a hill with how many peaks, giving it its name?','सप्तश्रृंगी देवी का मंदिर कितनी चोटियों वाली पहाड़ी पर स्थित है, जिससे इसे यह नाम मिला है?','[{"key": "A", "en": "Five", "hi": "पाँच"}, {"key": "B", "en": "Seven", "hi": "सात"}, {"key": "C", "en": "Nine", "hi": "नौ"}, {"key": "D", "en": "Three", "hi": "तीन"}]','B');
INSERT INTO knowledge_quiz VALUES(2041,'Which deity is worshipped during Dhanteras?','धनतेरस पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Kubera", "hi": "कुबेर"}, {"key": "B", "en": "Dhanvantari", "hi": "धन्वंतरि"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2042,'Which scripture is considered the essence of the Vedas?','वेदों का सार किस ग्रंथ को माना जाता है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Brahmanas", "hi": "ब्राह्मण"}, {"key": "D", "en": "Aranyakas", "hi": "आरण्यक"}]','A');
INSERT INTO knowledge_quiz VALUES(2043,'Which goddess is worshipped during Sharad Navratri?','शारदीय नवरात्रि में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(2044,'The ''Navagraha Aarti'' is sung to appease the nine planets. Which planet is described as ''Chhaya Martanda Sambhutam''?','नौ ग्रहों को शांत करने के लिए ''नवग्रह आरती'' गाई जाती है। किस ग्रह को ''छाया मार्तंड संभूतं'' कहा गया है?','[{"key": "A", "en": "Mars (Mangal)", "hi": "मंगल"}, {"key": "B", "en": "Saturn (Shani)", "hi": "शनि"}, {"key": "C", "en": "Jupiter (Guru)", "hi": "गुरु"}, {"key": "D", "en": "Venus (Shukra)", "hi": "शुक्र"}]','B');
INSERT INTO knowledge_quiz VALUES(2045,'What is the significance of ''Pradakshina'' (circumambulation) in a temple?','मंदिर में ''प्रदक्षिणा'' (परिक्रमा) करने का क्या महत्व है?','[{"key": "A", "en": "Exercise", "hi": "व्यायाम"}, {"key": "B", "en": "Keeping God as the center of one''s life", "hi": "ईश्वर को अपने जीवन का केंद्र मानना"}, {"key": "C", "en": "Counting the number of pillars", "hi": "खंभों की गिनती करना"}, {"key": "D", "en": "Meeting other devotees", "hi": "अन्य भक्तों से मिलना"}]','B');
INSERT INTO knowledge_quiz VALUES(2046,'Which goddess is worshipped during Shitala Ashtami?','शीतला अष्टमी पर किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Shitala Mata", "hi": "शीतला माता"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Lakshmi", "hi": "लक्ष्मी"}]','B');
INSERT INTO knowledge_quiz VALUES(2047,'Which deity is worshipped during Masik Shivaratri?','मासिक शिवरात्रि में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Ganesha", "hi": "गणेश"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2048,'In the Hanuman Chalisa, the word ''Sankat'' refers to which obstacle that Hanuman helps to remove?','हनुमान चालीसा में, ''संकट'' शब्द का तात्पर्य किस बाधा से है जिसे हनुमान दूर करने में मदद करते हैं?','[{"key": "A", "en": "Physical illness", "hi": "शारीरिक बीमारी"}, {"key": "B", "en": "Suffering and Difficulties", "hi": "कष्ट और कठिनाइयाँ"}, {"key": "C", "en": "Financial loss", "hi": "आर्थिक हानि"}, {"key": "D", "en": "Ignorance", "hi": "अज्ञानता"}]','B');
INSERT INTO knowledge_quiz VALUES(2049,'Which deity is worshipped during Sankranti?','संक्रांति पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Surya", "hi": "सूर्य"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(2050,'Which festival celebrates the return of Lord Rama to Ayodhya?','भगवान राम के अयोध्या लौटने का उत्सव कौन सा है?','[{"key": "A", "en": "Ram Navami", "hi": "राम नवमी"}, {"key": "B", "en": "Dussehra", "hi": "दशहरा"}, {"key": "C", "en": "Diwali", "hi": "दीपावली"}, {"key": "D", "en": "Holi", "hi": "होली"}]','C');
INSERT INTO knowledge_quiz VALUES(2051,'Who is the daughter of Vishwakarma?','विश्वकर्मा की पुत्री कौन हैं?','[{"key": "A", "en": "Yami", "hi": "यामी"}, {"key": "B", "en": "Sandhya", "hi": "संध्या"}, {"key": "C", "en": "Aditi", "hi": "अदिति"}, {"key": "D", "en": "Swaha", "hi": "स्वाहा"}]','B');
INSERT INTO knowledge_quiz VALUES(2052,'Which brother accompanied Lord Rama during his exile?','वनवास के दौरान भगवान राम के साथ कौन सा भाई गया था?','[{"key": "A", "en": "Bharata", "hi": "भरत"}, {"key": "B", "en": "Shatrughna", "hi": "शत्रुघ्न"}, {"key": "C", "en": "Lakshmana", "hi": "लक्ष्मण"}, {"key": "D", "en": "None", "hi": "कोई नहीं"}]','C');
INSERT INTO knowledge_quiz VALUES(2053,'Which demon abducted Sita?','सीता का हरण किस राक्षस ने किया था?','[{"key": "A", "en": "Kumbhakarna", "hi": "कुंभकर्ण"}, {"key": "B", "en": "Ravana", "hi": "रावण"}, {"key": "C", "en": "Maricha", "hi": "मारीच"}, {"key": "D", "en": "Subahu", "hi": "सुभाहु"}]','B');
INSERT INTO knowledge_quiz VALUES(2054,'Who helped Lord Rama find Sita in Lanka?','लंका में सीता की खोज में भगवान राम की सहायता किसने की?','[{"key": "A", "en": "Sugriva", "hi": "सुग्रीव"}, {"key": "B", "en": "Hanuman", "hi": "हनुमान"}, {"key": "C", "en": "Vibhishana", "hi": "विभीषण"}, {"key": "D", "en": "Angada", "hi": "अंगद"}]','B');
INSERT INTO knowledge_quiz VALUES(2055,'Which mountain did Hanuman lift to save Lakshmana?','लक्ष्मण को बचाने के लिए हनुमान कौन सा पर्वत उठा लाए?','[{"key": "A", "en": "Mount Meru", "hi": "मेरु पर्वत"}, {"key": "B", "en": "Mount Kailash", "hi": "कैलाश पर्वत"}, {"key": "C", "en": "Mount Dronagiri", "hi": "द्रोणगिरि पर्वत"}, {"key": "D", "en": "Mount Mandara", "hi": "मंदराचल पर्वत"}]','C');
INSERT INTO knowledge_quiz VALUES(2056,'Which avatar of Vishnu appeared as a boar?','भगवान विष्णु का कौन सा अवतार वराह रूप में था?','[{"key": "A", "en": "Kurma", "hi": "कूर्म"}, {"key": "B", "en": "Varaha", "hi": "वराह"}, {"key": "C", "en": "Matsya", "hi": "मत्स्य"}, {"key": "D", "en": "Narasimha", "hi": "नरसिंह"}]','B');
INSERT INTO knowledge_quiz VALUES(2057,'Which avatar of Vishnu appeared as a tortoise?','भगवान विष्णु का कौन सा अवतार कच्छप रूप में था?','[{"key": "A", "en": "Matsya", "hi": "मत्स्य"}, {"key": "B", "en": "Kurma", "hi": "कूर्म"}, {"key": "C", "en": "Varaha", "hi": "वराह"}, {"key": "D", "en": "Vamana", "hi": "वामन"}]','B');
INSERT INTO knowledge_quiz VALUES(2058,'Which festival in Varanasi is known as the ''Diwali of the Gods'' and is celebrated 15 days after Diwali?','वाराणसी के किस उत्सव को ''देवताओं की दिवाली'' कहा जाता है और यह दिवाली के 15 दिन बाद मनाया जाता है?','[{"key": "A", "en": "Ganga Mahotsav", "hi": "गंगा महोत्सव"}, {"key": "B", "en": "Dev Deepawali", "hi": "देव दीपावली"}, {"key": "C", "en": "Sheetala Ashtami", "hi": "शीतला अष्टमी"}, {"key": "D", "en": "Bharat Milap", "hi": "भरत मिलाप"}]','B');
INSERT INTO knowledge_quiz VALUES(2059,'Which avatar of Vishnu is known as the warrior with an axe?','कुल्हाड़ी धारण करने वाले विष्णु के अवतार कौन हैं?','[{"key": "A", "en": "Rama", "hi": "राम"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Parashurama", "hi": "परशुराम"}, {"key": "D", "en": "Balarama", "hi": "बलराम"}]','C');
INSERT INTO knowledge_quiz VALUES(2060,'Which avatar of Vishnu is known as the future avatar?','भगवान विष्णु का भविष्य का अवतार कौन माना जाता है?','[{"key": "A", "en": "Buddha", "hi": "बुद्ध"}, {"key": "B", "en": "Kalki", "hi": "कल्कि"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Rama", "hi": "राम"}]','B');
INSERT INTO knowledge_quiz VALUES(2061,'Which goddess is worshipped during Navratri?','नवरात्रि में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(2062,'Which festival celebrates the worship of Goddess Lakshmi?','किस पर्व में देवी लक्ष्मी की पूजा की जाती है?','[{"key": "A", "en": "Holi", "hi": "होली"}, {"key": "B", "en": "Diwali", "hi": "दीपावली"}, {"key": "C", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "D", "en": "Raksha Bandhan", "hi": "रक्षा बंधन"}]','B');
INSERT INTO knowledge_quiz VALUES(2063,'The idol of Lord Murugan in Palani is uniquely made of a combination of nine poisonous substances known as what?','पलानी में भगवान मुरुगन की मूर्ति नौ जहरीले पदार्थों के अनूठे मिश्रण से बनी है, जिसे क्या कहा जाता है?','[{"key": "A", "en": "Navaratna", "hi": "नवरत्न"}, {"key": "B", "en": "Navapashanam", "hi": "नवपाषाणम"}, {"key": "C", "en": "Panchaloha", "hi": "पंचलौह"}, {"key": "D", "en": "Ashtadhatu", "hi": "अष्टधातु"}]','B');
INSERT INTO knowledge_quiz VALUES(2064,'Which deity is worshipped during Karva Chauth?','करवा चौथ पर किसकी पूजा की जाती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Moon", "hi": "चंद्रमा"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','C');
INSERT INTO knowledge_quiz VALUES(2065,'Which deity is worshipped during Sankashti Chaturthi?','संकष्टी चतुर्थी पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2066,'Which sacred river flows through Haridwar?','हरिद्वार से होकर कौन सी पवित्र नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Alaknanda", "hi": "अलकनंदा"}, {"key": "D", "en": "Mandakini", "hi": "मंदाकिनी"}]','B');
INSERT INTO knowledge_quiz VALUES(2067,'Which city is known as the abode of Lord Krishna?','भगवान कृष्ण की नगरी किसे कहा जाता है?','[{"key": "A", "en": "Mathura", "hi": "मथुरा"}, {"key": "B", "en": "Ayodhya", "hi": "अयोध्या"}, {"key": "C", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "D", "en": "Ujjain", "hi": "उज्जैन"}]','A');
INSERT INTO knowledge_quiz VALUES(2068,'Which sacred text is known as the fifth Veda?','किस ग्रंथ को पंचम वेद कहा जाता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(2069,'Which item used in aarti represents the ''Akash'' (Space/Ether) element?','आरती में उपयोग की जाने वाली कौन सी वस्तु ''आकाश'' तत्व का प्रतिनिधित्व करती है?','[{"key": "A", "en": "Flowers (Pushpa)", "hi": "पुष्प"}, {"key": "B", "en": "Incense (Dhup)", "hi": "धूप"}, {"key": "C", "en": "Chauri (Fan or Whisk)", "hi": "चौर (चँवर)"}, {"key": "D", "en": "Lamp (Deepa)", "hi": "दीप"}]','C');
INSERT INTO knowledge_quiz VALUES(2070,'The word ''Aarti'' is derived from the Sanskrit word ''Aratrika'', which means what?','''आरती'' शब्द संस्कृत के ''आरार्त्रिक'' शब्द से बना है, जिसका अर्थ क्या है?','[{"key": "A", "en": "Divine Sound", "hi": "दिव्य ध्वनि"}, {"key": "B", "en": "Removing Darkness", "hi": "अंधकार को दूर करना"}, {"key": "C", "en": "Singing Praise", "hi": "प्रशंसा गायन"}, {"key": "D", "en": "Offering Food", "hi": "भोजन अर्पण"}]','B');
INSERT INTO knowledge_quiz VALUES(2071,'Which river flows through Mathura?','मथुरा नगर से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','B');
INSERT INTO knowledge_quiz VALUES(2072,'Which deity is known as Vighnaharta?','विघ्नहर्ता के रूप में किस देवता को जाना जाता है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Ganesha", "hi": "गणेश"}, {"key": "D", "en": "Hanuman", "hi": "हनुमान"}]','C');
INSERT INTO knowledge_quiz VALUES(2073,'What is the name of the forest where the Pandavas spent a large part of their exile?','उस वन का नाम क्या था जहाँ पांडवों ने अपने वनवास का एक बड़ा हिस्सा बिताया था?','[{"key": "A", "en": "Naimisharanya", "hi": "नैमिषारण्य"}, {"key": "B", "en": "Kamyaka Vana", "hi": "काम्यक वन"}, {"key": "C", "en": "Dandakaranya", "hi": "दंडकारण्य"}, {"key": "D", "en": "Madhuvana", "hi": "मधुवन"}]','B');
INSERT INTO knowledge_quiz VALUES(2074,'In the Hanuman Chalisa, the word ''Lari'' in ''Bikat Roop Dhari Siyahi Dikhawa'' refers to what?','हनुमान चालीसा में, ''बिकट रूप धरि सियहिं दिखावा'' में ''बिकट'' (विकट) शब्द का क्या अर्थ है?','[{"key": "A", "en": "Beautiful", "hi": "सुंदर"}, {"key": "B", "en": "Fearsome/Huge", "hi": "भयानक/विशाल"}, {"key": "C", "en": "Tiny", "hi": "सूक्ष्म"}, {"key": "D", "en": "Invisible", "hi": "अदृश्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2075,'What do the unbroken rice grains (Akshata) used in puja symbolize?','पूजा में उपयोग किए जाने वाले अखंड चावल (अक्षत) किसका प्रतीक हैं?','[{"key": "A", "en": "End of life", "hi": "जीवन का अंत"}, {"key": "B", "en": "Wealth only", "hi": "केवल धन"}, {"key": "C", "en": "Purity and Prosperity (Abundance)", "hi": "शुद्धता और समृद्धि"}, {"key": "D", "en": "Surrender", "hi": "समर्पण"}]','C');
INSERT INTO knowledge_quiz VALUES(2076,'In the Hanuman Chalisa, the phrase ''Kupanta nivara sumati ke sangi'' means Hanuman removes bad thoughts and is a companion to what?','हनुमान चालीसा में ''कुमति निवार सुमति के संगी'' का अर्थ है कि हनुमान बुरी बुद्धि को दूर करते हैं और किसके साथी हैं?','[{"key": "A", "en": "Wealth (Dhan)", "hi": "धन"}, {"key": "B", "en": "Good Wisdom/Intellect", "hi": "अच्छी बुद्धि/सुमति"}, {"key": "C", "en": "Anger (Krodha)", "hi": "क्रोध"}, {"key": "D", "en": "Ego (Ahankar)", "hi": "अहंकार"}]','B');
INSERT INTO knowledge_quiz VALUES(2077,'Which temple is located at the highest peak of Maharashtra and is dedicated to a local deity believed to be an incarnation of Devi?','महाराष्ट्र की सबसे ऊँची चोटी पर कौन सा मंदिर स्थित है, जो देवी का अवतार मानी जाने वाली एक स्थानीय देवी को समर्पित है?','[{"key": "A", "en": "Saptashrungi", "hi": "सप्तशृंगी"}, {"key": "B", "en": "Kalsubai Devi Temple", "hi": "कलसूबाई देवी मंदिर"}, {"key": "C", "en": "Renuka Mata", "hi": "रेणुका माता"}, {"key": "D", "en": "Ekvira Devi", "hi": "एकवीरा देवी"}]','B');
INSERT INTO knowledge_quiz VALUES(2078,'Which famous temple in Chhattisgarh is located on a hilltop in Dongargarh and requires climbing over 1000 steps?','छत्तीसगढ़ का कौन सा प्रसिद्ध मंदिर डोंगरगढ़ में एक पहाड़ी की चोटी पर स्थित है और यहाँ पहुँचने के लिए 1000 से अधिक सीढ़ियाँ चढ़नी पड़ती हैं?','[{"key": "A", "en": "Bambleshwari Devi", "hi": "बम्लेश्वरी देवी"}, {"key": "B", "en": "Danteshwari Devi", "hi": "दंतेश्वरी देवी"}, {"key": "C", "en": "Chandrahasini Devi", "hi": "चंद्रहासिनी देवी"}, {"key": "D", "en": "Mahamaya Devi", "hi": "महामाया देवी"}]','A');
INSERT INTO knowledge_quiz VALUES(2079,'In the Hanuman Chalisa, the line ''Prabhu Charitra Sunibe Ko Rasiya'' means Hanuman takes great delight in listening to whose story?','हनुमान चालीसा की पंक्ति ''प्रभु चरित्र सुनिबे को रसिया'' का अर्थ है कि हनुमान को किसका चरित्र सुनने में बहुत आनंद आता है?','[{"key": "A", "en": "Lord Shiva", "hi": "भगवान शिव"}, {"key": "B", "en": "Lord Rama", "hi": "भगवान राम"}, {"key": "C", "en": "Lord Krishna", "hi": "भगवान कृष्ण"}, {"key": "D", "en": "Lord Ganesha", "hi": "भगवान गणेश"}]','B');
INSERT INTO knowledge_quiz VALUES(2080,'Which deity is worshipped during Amavasya?','अमावस्या पर सामान्यतः किसकी पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Pitrs", "hi": "पितृ"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','C');
INSERT INTO knowledge_quiz VALUES(2081,'Which festival is dedicated to the worship of cows?','गायों की पूजा को समर्पित पर्व कौन सा है?','[{"key": "A", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "B", "en": "Gopashtami", "hi": "गोपाष्टमी"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}]','C');
INSERT INTO knowledge_quiz VALUES(2082,'What is the name of the goddess who is sometimes seen accompanying Surya on his chariot along with his horses?','उस देवी का नाम क्या है जो कभी-कभी सूर्य के साथ उनके रथ पर उनके घोड़ों के साथ दिखाई देती हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Usha", "hi": "उषा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(2083,'Which deity is worshipped during Guru Purnima?','गुरु पूर्णिमा पर किसकी पूजा होती है?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Brihaspati", "hi": "बृहस्पति"}, {"key": "C", "en": "All gurus", "hi": "सभी गुरु"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','C');
INSERT INTO knowledge_quiz VALUES(2084,'Which deity is known as the lord of wealth?','धन के देवता किसे कहा जाता है?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Kubera", "hi": "कुबेर"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(2085,'Which river flows through Varanasi?','वाराणसी नगर से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','B');
INSERT INTO knowledge_quiz VALUES(2086,'In which Murugan temple did the Lord explain the meaning of the ''Pranava Mantra'' (Om)?','मुरुगन के किस मंदिर में उन्होंने ''प्रणव मंत्र'' (ओम) का अर्थ समझाया था?','[{"key": "A", "en": "Thiruttani", "hi": "तिरुत्तणी"}, {"key": "B", "en": "Swamimalai", "hi": "स्वामीमलै"}, {"key": "C", "en": "Thirupparamkunram", "hi": "तिरुप्परनकुंरम"}, {"key": "D", "en": "Palani", "hi": "पलानी"}]','B');
INSERT INTO knowledge_quiz VALUES(2087,'Which sweet is traditionally offered to Hanuman Ji as prasad?','हनुमान जी को प्रसाद में कौन सी मिठाई चढ़ाई जाती है?','[{"key": "A", "en": "Guldana", "hi": "गुलदाना"}, {"key": "B", "en": "Peda", "hi": "पेड़ा"}, {"key": "C", "en": "Barfi", "hi": "बर्फी"}, {"key": "D", "en": "Jalebi", "hi": "जलेबी"}]','A');
INSERT INTO knowledge_quiz VALUES(2088,'Which goddess is worshipped during Mangal Gauri Vrat?','मंगल गौरी व्रत में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(2089,'Which temple in Nashik is entirely made of white marble and features replicas of all 12 Jyotirlingas?','नासिक का कौन सा मंदिर पूरी तरह से सफेद संगमरमर से बना है और इसमें सभी 12 ज्योतिर्लिंगों की प्रतिकृतियां हैं?','[{"key": "A", "en": "Someshwar", "hi": "सोमेश्वर"}, {"key": "B", "en": "Muktidham", "hi": "मुक्तिधाम"}, {"key": "C", "en": "Sundarnarayan", "hi": "सुंदरनारायण"}, {"key": "D", "en": "Ganga Godavari", "hi": "गंगा गोदावरी"}]','B');
INSERT INTO knowledge_quiz VALUES(2090,'Which deity is worshipped during Dhanteras?','धनतेरस पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Kubera", "hi": "कुबेर"}, {"key": "B", "en": "Dhanvantari", "hi": "धन्वंतरि"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2091,'Which scripture is considered the essence of the Vedas?','वेदों का सार किस ग्रंथ को माना जाता है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Brahmanas", "hi": "ब्राह्मण"}, {"key": "D", "en": "Aranyakas", "hi": "आरण्यक"}]','A');
INSERT INTO knowledge_quiz VALUES(2092,'Which goddess is worshipped during Sharad Navratri?','शारदीय नवरात्रि में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(2093,'Which river is associated with the Kumbh Mela at Prayagraj?','प्रयागराज के कुंभ मेले में कौन सी नदी जुड़ी है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2094,'In which direction should a person ideally face while performing puja?','पूजा करते समय व्यक्ति का मुख आदर्श रूप से किस दिशा में होना चाहिए?','[{"key": "A", "en": "South", "hi": "दक्षिण"}, {"key": "B", "en": "East or North", "hi": "पूर्व या उत्तर"}, {"key": "C", "en": "West", "hi": "पश्चिम"}, {"key": "D", "en": "Any direction is fine", "hi": "किसी भी दिशा में"}]','B');
INSERT INTO knowledge_quiz VALUES(2095,'Which goddess is worshipped during Shitala Ashtami?','शीतला अष्टमी पर किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Shitala Mata", "hi": "शीतला माता"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Lakshmi", "hi": "लक्ष्मी"}]','B');
INSERT INTO knowledge_quiz VALUES(2096,'Which deity is worshipped during Masik Shivaratri?','मासिक शिवरात्रि में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Ganesha", "hi": "गणेश"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2097,'The ''Laxmi Chalisa'' is traditionally recited during which major Hindu festival to seek prosperity?','समृद्धि की कामना के लिए ''लक्ष्मी चालीसा'' का पाठ पारंपरिक रूप से किस प्रमुख हिंदू त्योहार के दौरान किया जाता है?','[{"key": "A", "en": "Holi", "hi": "होली"}, {"key": "B", "en": "Diwali", "hi": "दीपावली"}, {"key": "C", "en": "Raksha Bandhan", "hi": "रक्षाबंधन"}, {"key": "D", "en": "Dussehra", "hi": "दशहरा"}]','B');
INSERT INTO knowledge_quiz VALUES(2098,'Which Chalisa is often recited to alleviate the malefic effects of planet Saturn?','शनि ग्रह के प्रतिकूल प्रभावों को कम करने के लिए अक्सर किस चालीसा का पाठ किया जाता है?','[{"key": "A", "en": "Surya Chalisa", "hi": "सूर्य चालीसा"}, {"key": "B", "en": "Shani Chalisa", "hi": "शनि चालीसा"}, {"key": "C", "en": "Hanuman Chalisa", "hi": "हनुमान चालीसा"}, {"key": "D", "en": "Both B and C", "hi": "B और C दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(2099,'Which deity is worshipped during Rohini Vrat?','रोहिणी व्रत में किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','A');
INSERT INTO knowledge_quiz VALUES(2100,'Which festival marks the return of Lord Rama to Ayodhya?','भगवान राम के अयोध्या लौटने का उत्सव कौन सा है?','[{"key": "A", "en": "Ram Navami", "hi": "राम नवमी"}, {"key": "B", "en": "Dussehra", "hi": "दशहरा"}, {"key": "C", "en": "Diwali", "hi": "दीपावली"}, {"key": "D", "en": "Holi", "hi": "होली"}]','C');
INSERT INTO knowledge_quiz VALUES(2101,'Who was the only human ever allowed to enter Indraloka with his physical body?','अपने भौतिक शरीर के साथ इंद्रलोक में प्रवेश करने की अनुमति पाने वाले एकमात्र मानव कौन थे?','[{"key": "A", "en": "King Harishchandra", "hi": "राजा हरिश्चंद्र"}, {"key": "B", "en": "King Yudhishthira", "hi": "राजा युधिष्ठिर"}, {"key": "C", "en": "King Nahusha", "hi": "राजा नहुष"}, {"key": "D", "en": "King Bhagiratha", "hi": "राजा भगीरथ"}]','B');
INSERT INTO knowledge_quiz VALUES(2102,'Who was the wife of Lord Rama?','भगवान राम की पत्नी कौन थीं?','[{"key": "A", "en": "Sita", "hi": "सीता"}, {"key": "B", "en": "Urmila", "hi": "उर्मिला"}, {"key": "C", "en": "Mandavi", "hi": "मांडवी"}, {"key": "D", "en": "Shrutakirti", "hi": "श्रुतकीर्ति"}]','A');
INSERT INTO knowledge_quiz VALUES(2103,'The Kaal Bhairav temple in Ujjain is famous for offering which of these to the deity?','उज्जैन का काल भैरव मंदिर देवता को इनमें से क्या अर्पित करने के लिए प्रसिद्ध है?','[{"key": "A", "en": "Milk", "hi": "दूध"}, {"key": "B", "en": "Liquor (Madira)", "hi": "मदिरा"}, {"key": "C", "en": "Honey", "hi": "शहद"}, {"key": "D", "en": "Ghee", "hi": "घी"}]','B');
INSERT INTO knowledge_quiz VALUES(2104,'Which weapon is associated with Lord Vishnu?','भगवान विष्णु से कौन सा अस्त्र जुड़ा है?','[{"key": "A", "en": "Trishul", "hi": "त्रिशूल"}, {"key": "B", "en": "Sudarshan Chakra", "hi": "सुदर्शन चक्र"}, {"key": "C", "en": "Pashupatastra", "hi": "पाशुपतास्त्र"}, {"key": "D", "en": "Vajra", "hi": "वज्र"}]','B');
INSERT INTO knowledge_quiz VALUES(2105,'Who is the consort of Lord Vishnu?','भगवान विष्णु की पत्नी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','C');
INSERT INTO knowledge_quiz VALUES(2106,'The Kalaram Temple in Nashik, where the idols of Rama, Laxman, and Sita are made of black stone, was the site of a famous satyagraha led by whom?','नासिक का कलाराम मंदिर, जहाँ राम, लक्ष्मण और सीता की मूर्तियाँ काले पत्थर से बनी हैं, किसके नेतृत्व में हुए प्रसिद्ध सत्याग्रह का स्थल था?','[{"key": "A", "en": "Mahatma Gandhi", "hi": "महात्मा गांधी"}, {"key": "B", "en": "Dr. B.R. Ambedkar", "hi": "डॉ. बी.आर. अंबेडकर"}, {"key": "C", "en": "Vinoba Bhave", "hi": "विनोबा भावे"}, {"key": "D", "en": "Jyotirao Phule", "hi": "ज्योतिराव फुले"}]','B');
INSERT INTO knowledge_quiz VALUES(2107,'Which Veda is the oldest?','सबसे प्राचीन वेद कौन सा है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "C", "en": "Samaveda", "hi": "सामवेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','A');
INSERT INTO knowledge_quiz VALUES(2108,'Which god is known as the king of gods?','देवताओं के राजा किसे कहा जाता है?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Varuna", "hi": "वरुण"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','C');
INSERT INTO knowledge_quiz VALUES(2109,'Which planet is associated with Shani?','शनि किस ग्रह से संबंधित हैं?','[{"key": "A", "en": "Mars", "hi": "मंगल"}, {"key": "B", "en": "Saturn", "hi": "शनि"}, {"key": "C", "en": "Jupiter", "hi": "बृहस्पति"}, {"key": "D", "en": "Venus", "hi": "शुक्र"}]','B');
INSERT INTO knowledge_quiz VALUES(2110,'Who was the Gorkha commander that built the current structure of the Gangotri temple in the 18th century?','18वीं शताब्दी में गंगोत्री मंदिर की वर्तमान संरचना का निर्माण करने वाले गोरखा कमांडर कौन थे?','[{"key": "A", "en": "Amar Singh Thapa", "hi": "अमर सिंह थापा"}, {"key": "B", "en": "Bhakti Thapa", "hi": "भक्ति थापा"}, {"key": "C", "en": "Jang Bahadur Rana", "hi": "जंग बहादुर राणा"}, {"key": "D", "en": "Balbhadra Kunwar", "hi": "बलभद्र कुंवर"}]','A');
INSERT INTO knowledge_quiz VALUES(2111,'Who is the author of the Mahabharata?','महाभारत के रचयिता कौन हैं?','[{"key": "A", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Tulsidas", "hi": "तुलसीदास"}, {"key": "D", "en": "Kalidasa", "hi": "कालिदास"}]','B');
INSERT INTO knowledge_quiz VALUES(2112,'Which god is associated with the trident?','त्रिशूल किस देवता से जुड़ा है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(2113,'Which goddess is the consort of Lord Shiva?','भगवान शिव की पत्नी कौन हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','C');
INSERT INTO knowledge_quiz VALUES(2114,'Which temple in Ahmedabad was built by Seth Hutheesing in 1848 and is dedicated to Dharmanath?','अहमदाबाद का कौन सा मंदिर 1848 में सेठ हठीसिंह द्वारा बनवाया गया था और धर्मनाथ को समर्पित है?','[{"key": "A", "en": "Swaminarayan Mandir", "hi": "स्वामीनारायण मंदिर"}, {"key": "B", "en": "Hutheesing Jain Temple", "hi": "हठीसिंह जैन मंदिर"}, {"key": "C", "en": "Bhadra Kali", "hi": "भद्रा काली"}, {"key": "D", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2115,'Which deity is known as the god of fire?','अग्नि के देवता कौन हैं?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','A');
INSERT INTO knowledge_quiz VALUES(2116,'Which god is associated with the Sun?','सूर्य से संबंधित देवता कौन हैं?','[{"key": "A", "en": "Surya", "hi": "सूर्य"}, {"key": "B", "en": "Agni", "hi": "अग्नि"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Vayu", "hi": "वायु"}]','A');
INSERT INTO knowledge_quiz VALUES(2117,'Which goddess is associated with learning?','विद्या की देवी कौन हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','C');
INSERT INTO knowledge_quiz VALUES(2118,'Which part of Sati fell at the Amarnath (Mahamaya Peetha)?','अमरनाथ (महामाया पीठ) में सती का कौन सा अंग गिरा था?','[{"key": "A", "en": "Throat", "hi": "गला"}, {"key": "B", "en": "Spine", "hi": "रीढ़ की हड्डी"}, {"key": "C", "en": "Fingers", "hi": "उंगलियां"}, {"key": "D", "en": "Left Arm", "hi": "बाईं भुजा"}]','A');
INSERT INTO knowledge_quiz VALUES(2119,'The world-famous ''Lathmar Holi'' is traditionally celebrated in which two towns of Uttar Pradesh?','विश्व प्रसिद्ध ''लठमार होली'' पारंपरिक रूप से उत्तर प्रदेश के किन दो शहरों में मनाई जाती है?','[{"key": "A", "en": "Mathura and Vrindavan", "hi": "मथुरा और वृंदावन"}, {"key": "B", "en": "Barsana and Nandgaon", "hi": "बरसाना और नंदगाँव"}, {"key": "C", "en": "Gokul and Mahavan", "hi": "गोकुल और महावन"}, {"key": "D", "en": "Ayodhya and Lucknow", "hi": "अयोध्या और लखनऊ"}]','B');
INSERT INTO knowledge_quiz VALUES(2120,'Which Hindu deity is the primary focus of the ''Koneswaram Temple'' in Trincomalee, Sri Lanka?','श्रीलंका के त्रिंकोमाली में ''कोणेश्वरम मंदिर'' का प्राथमिक केंद्र कौन से हिंदू देवता हैं?','[{"key": "A", "en": "Lord Vishnu", "hi": "भगवान विष्णु"}, {"key": "B", "en": "Lord Shiva", "hi": "भगवान शिव"}, {"key": "C", "en": "Lord Murugan", "hi": "भगवान मुरुगन"}, {"key": "D", "en": "Lord Ganesha", "hi": "भगवान गणेश"}]','B');
INSERT INTO knowledge_quiz VALUES(2121,'Which temple in Karnataka is famous for its architecture where the sun''s rays fall directly on the deity''s feet twice a year (Surya Majjana)?','कर्नाटक का कौन सा मंदिर अपनी वास्तुकला के लिए प्रसिद्ध है जहाँ साल में दो बार सूर्य की किरणें सीधे देवता के चरणों पर गिरती हैं?','[{"key": "A", "en": "Gavi Gangadhareshwara", "hi": "गवि गंगाधरेश्वर"}, {"key": "B", "en": "Vidyashankara", "hi": "विद्याशंकर"}, {"key": "C", "en": "Bhoga Nandeeshwara", "hi": "भोग नंदीश्वर"}, {"key": "D", "en": "Chennakesava", "hi": "चेनकेशव"}]','A');
INSERT INTO knowledge_quiz VALUES(2122,'Which avatar of Vishnu appeared as a dwarf?','भगवान विष्णु का कौन सा अवतार वामन रूप में था?','[{"key": "A", "en": "Vamana", "hi": "वामन"}, {"key": "B", "en": "Parashurama", "hi": "परशुराम"}, {"key": "C", "en": "Rama", "hi": "राम"}, {"key": "D", "en": "Krishna", "hi": "कृष्ण"}]','A');
