INSERT INTO knowledge_quiz VALUES(2124,'Which god is worshipped as the god of wind?','वायु के देवता कौन हैं?','[{"key": "A", "en": "Vayu", "hi": "वायु"}, {"key": "B", "en": "Agni", "hi": "अग्नि"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','A');
INSERT INTO knowledge_quiz VALUES(2125,'Which deity is associated with the bull Nandi?','नंदी बैल किस देवता से जुड़ा है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(2126,'Where did Lord Rama pray to Shiva after defeating Ravana?','रावण को पराजित करने के बाद भगवान राम ने शिव की पूजा कहाँ की?','[{"key": "A", "en": "Munneswaram", "hi": "मुन्नेश्वरम"}, {"key": "B", "en": "Rameshwaram", "hi": "रामेश्वरम"}, {"key": "C", "en": "Kedarnath", "hi": "केदारनाथ"}, {"key": "D", "en": "Kashi", "hi": "काशी"}]','A');
INSERT INTO knowledge_quiz VALUES(2127,'Which deity holds a flute?','बांसुरी धारण करने वाले देवता कौन हैं?','[{"key": "A", "en": "Rama", "hi": "राम"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','B');
INSERT INTO knowledge_quiz VALUES(2128,'Which god is worshipped for wisdom?','बुद्धि के लिए किस देवता की पूजा होती है?','[{"key": "A", "en": "Ganesha", "hi": "गणेश"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','A');
INSERT INTO knowledge_quiz VALUES(2129,'Which goddess is worshipped for prosperity?','समृद्धि के लिए किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(2130,'Which god is known as the preserver?','पालनकर्ता के रूप में किस देवता को जाना जाता है?','[{"key": "A", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
