INSERT INTO knowledge_quiz VALUES(2134,'Which god is worshipped as the god of water?','जल के देवता कौन हैं?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Varuna", "hi": "वरुण"}, {"key": "C", "en": "Vayu", "hi": "वायु"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2135,'Which goddess is known as Jagat Janani?','जगत जननी किस देवी को कहा जाता है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','A');
INSERT INTO knowledge_quiz VALUES(2136,'Which god is worshipped during Mondays?','सोमवार को किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Ganesha", "hi": "गणेश"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2137,'Which deity is worshipped during Thursdays?','गुरुवार को किस देवता की पूजा होती है?','[{"key": "A", "en": "Brihaspati", "hi": "बृहस्पति"}, {"key": "B", "en": "Shani", "hi": "शनि"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','A');
INSERT INTO knowledge_quiz VALUES(2138,'Which deity is associated with the planet Mars?','मंगल ग्रह से संबंधित देवता कौन हैं?','[{"key": "A", "en": "Shani", "hi": "शनि"}, {"key": "B", "en": "Budha", "hi": "बुध"}, {"key": "C", "en": "Mangala", "hi": "मंगल"}, {"key": "D", "en": "Guru", "hi": "गुरु"}]','C');
INSERT INTO knowledge_quiz VALUES(2139,'Which festival celebrates colors?','रंगों का पर्व कौन सा है?','[{"key": "A", "en": "Diwali", "hi": "दीपावली"}, {"key": "B", "en": "Holi", "hi": "होली"}, {"key": "C", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "D", "en": "Dussehra", "hi": "दशहरा"}]','B');
INSERT INTO knowledge_quiz VALUES(2140,'What is unique about the eye of Lord Ganesha at Siddhi Vinayaka temple?','सिद्धि विनायक मंदिर में भगवान गणेश की आंख की क्या विशेषता है?','[{"key": "A", "en": "It is made of Diamond", "hi": "यह हीरे से बनी है"}, {"key": "B", "en": "It is the Third Eye on the forehead", "hi": "यह माथे पर तीसरी आंख है"}, {"key": "C", "en": "It is always closed", "hi": "यह हमेशा बंद रहती है"}, {"key": "D", "en": "It changes color", "hi": "यह रंग बदलती है"}]','B');
INSERT INTO knowledge_quiz VALUES(2141,'Which deity is worshipped during Fridays?','शुक्रवार को किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(2142,'The Chennakesava Temple at Somanathapura, near Mysore, is a prime example of which architectural style?','मैसूर के पास सोमनाथपुरा में चेनकेशव मंदिर किस वास्तुकला शैली का प्रमुख उदाहरण है?','[{"key": "A", "en": "Chola", "hi": "चोल"}, {"key": "B", "en": "Hoysala", "hi": "होयसल"}, {"key": "C", "en": "Pallava", "hi": "पल्लव"}, {"key": "D", "en": "Vijayanagara", "hi": "विजयनगर"}]','B');
INSERT INTO knowledge_quiz VALUES(2143,'Which goddess is worshipped during Tuesdays by married women?','विवाहित स्त्रियाँ मंगलवार को किस देवी की पूजा करती हैं?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(2144,'Which god is worshipped during Sundays?','रविवार को किस देवता की पूजा होती है?','[{"key": "A", "en": "Surya", "hi": "सूर्य"}, {"key": "B", "en": "Agni", "hi": "अग्नि"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','A');
INSERT INTO knowledge_quiz VALUES(2145,'Which deity is worshipped during Chaturthi?','चतुर्थी पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2146,'Which goddess is associated with the river Ganga?','गंगा नदी किस देवी से संबंधित है?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Durga", "hi": "दुर्गा"}, {"key": "D", "en": "Lakshmi", "hi": "लक्ष्मी"}]','B');
INSERT INTO knowledge_quiz VALUES(2147,'Which god is known as the teacher of the gods?','देवताओं के गुरु कौन हैं?','[{"key": "A", "en": "Shukracharya", "hi": "शुक्राचार्य"}, {"key": "B", "en": "Brihaspati", "hi": "बृहस्पति"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(2148,'Which deity is known as the messenger of gods?','देवताओं का दूत किसे कहा जाता है?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Vayu", "hi": "वायु"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','C');
INSERT INTO knowledge_quiz VALUES(2149,'Which goddess is worshipped during Kojagiri Purnima?','कोजागरी पूर्णिमा पर किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','A');
INSERT INTO knowledge_quiz VALUES(2150,'Which deity is worshipped during Naraka Chaturdashi?','नरक चतुर्दशी पर किस देवता की पूजा होती है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Yama", "hi": "यम"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','C');
INSERT INTO knowledge_quiz VALUES(2151,'What is the name of the island on which the Omkareshwar temple is located?','उस द्वीप का नाम क्या है जिस पर ओंकारेश्वर मंदिर स्थित है?','[{"key": "A", "en": "Mandhata", "hi": "मान्धाता"}, {"key": "B", "en": "Majuli", "hi": "माजुली"}, {"key": "C", "en": "Rameswaram", "hi": "रामेश्वरम"}, {"key": "D", "en": "Elephanta", "hi": "एलिफेंटा"}]','A');
INSERT INTO knowledge_quiz VALUES(2152,'Which weapon did Arjuna receive from Lord Shiva?','अर्जुन को भगवान शिव से कौन सा अस्त्र प्राप्त हुआ था?','[{"key": "A", "en": "Brahmastra", "hi": "ब्रह्मास्त्र"}, {"key": "B", "en": "Pashupatastra", "hi": "पाशुपतास्त्र"}, {"key": "C", "en": "Narayanastra", "hi": "नारायणास्त्र"}, {"key": "D", "en": "Agneyastra", "hi": "आग्नेयास्त्र"}]','B');
