INSERT INTO knowledge_quiz VALUES(2154,'Which mythical tree, believed to grant wishes, is located near the Kalpeshwar temple?','कल्पेश्वर मंदिर के पास कौन सा पौराणिक वृक्ष स्थित है, जिसे मनोकामना पूर्ण करने वाला माना जाता है?','[{"key": "A", "en": "Banyan Tree", "hi": "बरगद का वृक्ष"}, {"key": "B", "en": "Parijat Tree", "hi": "पारिजात वृक्ष"}, {"key": "C", "en": "Kalpavriksha", "hi": "कल्पवृक्ष"}, {"key": "D", "en": "Peepal Tree", "hi": "पीपल का वृक्ष"}]','C');
