INSERT INTO knowledge_quiz VALUES(2195,'Which king was known as the father of Shishupala?','शिशुपाल के पिता कौन थे?','[{"key": "A", "en": "Damaghosa", "hi": "दमघोष"}, {"key": "B", "en": "Jarāsandha", "hi": "जरासंध"}, {"key": "C", "en": "Kamsa", "hi": "कंस"}, {"key": "D", "en": "Salya", "hi": "शल्य"}]','A');
INSERT INTO knowledge_quiz VALUES(2196,'Who was the king of Magadha?','मगध का राजा कौन था?','[{"key": "A", "en": "Kamsa", "hi": "कंस"}, {"key": "B", "en": "Jarāsandha", "hi": "जरासंध"}, {"key": "C", "en": "Shishupala", "hi": "शिशुपाल"}, {"key": "D", "en": "Salya", "hi": "शल्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2197,'Who killed Jarasandha?','जरासंध का वध किसने किया?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Bhima", "hi": "भीम"}, {"key": "D", "en": "Yudhishthira", "hi": "युधिष्ठिर"}]','C');
INSERT INTO knowledge_quiz VALUES(2198,'Who was the maternal uncle of the Pandavas?','पांडवों के मामा कौन थे?','[{"key": "A", "en": "Shakuni", "hi": "शकुनि"}, {"key": "B", "en": "Kamsa", "hi": "कंस"}, {"key": "C", "en": "Vasudeva", "hi": "वसुदेव"}, {"key": "D", "en": "Vidura", "hi": "विदुर"}]','D');
INSERT INTO knowledge_quiz VALUES(2199,'Who was the prime minister of Hastinapura?','हस्तिनापुर के महामंत्री कौन थे?','[{"key": "A", "en": "Bheeshma", "hi": "भीष्म"}, {"key": "B", "en": "Drona", "hi": "द्रोण"}, {"key": "C", "en": "Vidura", "hi": "विदुर"}, {"key": "D", "en": "Kripa", "hi": "कृप"}]','C');
INSERT INTO knowledge_quiz VALUES(2200,'Which character is considered the embodiment of righteousness in Mahabharata?','महाभारत में धर्म का प्रतीक किसे माना जाता है?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "D", "en": "Bheeshma", "hi": "भीष्म"}]','C');
INSERT INTO knowledge_quiz VALUES(2201,'Who was the foster father of Lord Krishna?','भगवान कृष्ण के पालक पिता कौन थे?','[{"key": "A", "en": "Vasudeva", "hi": "वसुदेव"}, {"key": "B", "en": "Nanda", "hi": "नंद"}, {"key": "C", "en": "Ugrasena", "hi": "उग्रसेन"}, {"key": "D", "en": "Akrura", "hi": "अक्रूर"}]','B');
INSERT INTO knowledge_quiz VALUES(2202,'Who was the foster mother of Lord Krishna?','भगवान कृष्ण की पालक माता कौन थीं?','[{"key": "A", "en": "Devaki", "hi": "देवकी"}, {"key": "B", "en": "Rohini", "hi": "रोहिणी"}, {"key": "C", "en": "Yashoda", "hi": "यशोदा"}, {"key": "D", "en": "Radha", "hi": "राधा"}]','C');
INSERT INTO knowledge_quiz VALUES(2203,'Who was the biological mother of Lord Krishna?','भगवान कृष्ण की जन्मदात्री माता कौन थीं?','[{"key": "A", "en": "Yashoda", "hi": "यशोदा"}, {"key": "B", "en": "Devaki", "hi": "देवकी"}, {"key": "C", "en": "Rohini", "hi": "रोहिणी"}, {"key": "D", "en": "Subhadra", "hi": "सुभद्रा"}]','B');
INSERT INTO knowledge_quiz VALUES(2204,'Who was the son of Sahadeva and Draupadi, and one of the five Upapandavas?','सहदेव और द्रौपदी के पुत्र कौन थे, जो पांच उपपांडवों में से एक थे?','[{"key": "A", "en": "Srutakarma", "hi": "श्रुतकर्म"}, {"key": "B", "en": "Srutasena", "hi": "श्रुतसेन"}, {"key": "C", "en": "Srutasoma", "hi": "श्रुतसोम"}, {"key": "D", "en": "Satanika", "hi": "शतानीक"}]','B');
INSERT INTO knowledge_quiz VALUES(2205,'Who was the brother of Lord Krishna?','भगवान कृष्ण के भाई कौन थे?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Balarama", "hi": "बलराम"}, {"key": "C", "en": "Shatrughna", "hi": "शत्रुघ्न"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','B');
INSERT INTO knowledge_quiz VALUES(2206,'Which demon did Krishna kill in his childhood?','बाल्यकाल में कृष्ण ने किस राक्षस का वध किया?','[{"key": "A", "en": "Putana", "hi": "पूतना"}, {"key": "B", "en": "Bakasura", "hi": "बकासुर"}, {"key": "C", "en": "Aghasura", "hi": "अघासुर"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2207,'Which serpent did Krishna subdue in the Yamuna?','यमुना नदी में कृष्ण ने किस नाग को वश में किया?','[{"key": "A", "en": "Takshaka", "hi": "तक्षक"}, {"key": "B", "en": "Vasuki", "hi": "वासुकी"}, {"key": "C", "en": "Kaliya", "hi": "कालिया"}, {"key": "D", "en": "Ananta", "hi": "अनंत"}]','C');
INSERT INTO knowledge_quiz VALUES(2208,'Which hill did Krishna lift to protect the villagers?','ग्रामीणों की रक्षा के लिए कृष्ण ने कौन सा पर्वत उठाया?','[{"key": "A", "en": "Mount Meru", "hi": "मेरु पर्वत"}, {"key": "B", "en": "Govardhan", "hi": "गोवर्धन"}, {"key": "C", "en": "Mandara", "hi": "मंदराचल"}, {"key": "D", "en": "Dronagiri", "hi": "द्रोणगिरि"}]','B');
INSERT INTO knowledge_quiz VALUES(2209,'Who was Krishna’s closest friend among the Pandavas?','पांडवों में कृष्ण के सबसे निकट मित्र कौन थे?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Nakula", "hi": "नकुल"}]','C');
INSERT INTO knowledge_quiz VALUES(2210,'Who was the biological father of the bird-king Garuda?','पक्षी-राज गरुड़ के जैविक पिता कौन थे?','[{"key": "A", "en": "Aruna", "hi": "अरुण"}, {"key": "B", "en": "Kashyapa", "hi": "कश्यप"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Daksh", "hi": "दक्ष"}]','B');
INSERT INTO knowledge_quiz VALUES(2211,'To whom did Krishna deliver the Bhagavad Gita?','कृष्ण ने भगवद्गीता का उपदेश किसे दिया?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Karna", "hi": "कर्ण"}]','C');
INSERT INTO knowledge_quiz VALUES(2212,'How many chapters are there in the Bhagavad Gita?','भगवद्गीता में कितने अध्याय हैं?','[{"key": "A", "en": "12", "hi": "12"}, {"key": "B", "en": "15", "hi": "15"}, {"key": "C", "en": "18", "hi": "18"}, {"key": "D", "en": "24", "hi": "24"}]','C');
INSERT INTO knowledge_quiz VALUES(2213,'How many days did the Kurukshetra war last?','कुरुक्षेत्र युद्ध कितने दिनों तक चला?','[{"key": "A", "en": "7 days", "hi": "7 दिन"}, {"key": "B", "en": "10 days", "hi": "10 दिन"}, {"key": "C", "en": "18 days", "hi": "18 दिन"}, {"key": "D", "en": "21 days", "hi": "21 दिन"}]','C');
INSERT INTO knowledge_quiz VALUES(2214,'Who was the commander of the Kaurava army on the first day?','पहले दिन कौरव सेना के सेनापति कौन थे?','[{"key": "A", "en": "Drona", "hi": "द्रोण"}, {"key": "B", "en": "Karna", "hi": "कर्ण"}, {"key": "C", "en": "Bhishma", "hi": "भीष्म"}, {"key": "D", "en": "Shalya", "hi": "शल्य"}]','C');
INSERT INTO knowledge_quiz VALUES(2215,'Who became the commander of the Kaurava army after Bhishma?','भीष्म के बाद कौरव सेना का सेनापति कौन बना?','[{"key": "A", "en": "Karna", "hi": "कर्ण"}, {"key": "B", "en": "Drona", "hi": "द्रोण"}, {"key": "C", "en": "Ashwatthama", "hi": "अश्वत्थामा"}, {"key": "D", "en": "Shalya", "hi": "शल्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2216,'Who killed Bhishma in the Kurukshetra war?','कुरुक्षेत्र युद्ध में भीष्म को किसने पराजित किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Shikhandi", "hi": "शिखंडी"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Bhima", "hi": "भीम"}]','B');
INSERT INTO knowledge_quiz VALUES(2217,'Who was the commander of the Pandava army?','पांडव सेना के सेनापति कौन थे?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Dhrishtadyumna", "hi": "धृष्टद्युम्न"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','C');
INSERT INTO knowledge_quiz VALUES(2218,'Which temple in Vrindavan is world-famous for its ''Jhulan Yatra'' and is dedicated to the ''Banke'' (bent in three places) form of Krishna?','वृंदावन का कौन सा मंदिर अपनी ''झूलन यात्रा'' के लिए विश्व प्रसिद्ध है और कृष्ण के ''बांके'' (तीन स्थानों से मुड़े हुए) रूप को समर्पित है?','[{"key": "A", "en": "Radha Raman", "hi": "राधा रमण"}, {"key": "B", "en": "Banke Bihari Temple", "hi": "बांके बिहारी मंदिर"}, {"key": "C", "en": "Radha Vallabh", "hi": "राधा वल्लभ"}, {"key": "D", "en": "Shahji Temple", "hi": "शाहजी मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2219,'Who killed Karna?','कर्ण का वध किसने किया?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Yudhishthira", "hi": "युधिष्ठिर"}]','C');
INSERT INTO knowledge_quiz VALUES(2220,'Who killed Duryodhana?','दुर्योधन का वध किसने किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Sahadeva", "hi": "सहदेव"}]','B');
INSERT INTO knowledge_quiz VALUES(2221,'Who killed Shakuni?','शकुनि का वध किसने किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Sahadeva", "hi": "सहदेव"}, {"key": "D", "en": "Nakula", "hi": "नकुल"}]','C');
INSERT INTO knowledge_quiz VALUES(2222,'Who was the only Dhritrashtra''s son to survive the war?','युद्ध में जीवित रहने वाला एकमात्र धृतराष्ट्र का पुत्र कौन था?','[{"key": "A", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "B", "en": "Dushasana", "hi": "दुःशासन"}, {"key": "C", "en": "Yuyutsu", "hi": "युयुत्सु"}, {"key": "D", "en": "Vikarna", "hi": "विकर्ण"}]','C');
INSERT INTO knowledge_quiz VALUES(2223,'Which deity is known as ''Mukhya Prana'' in the Dvaita philosophy of Madhvacharya?','मध्वाचार्य के द्वैत दर्शन में किस देवता को ''मुख्य प्राण'' के रूप में जाना जाता है?','[{"key": "A", "en": "Ganesha", "hi": "गणेश"}, {"key": "B", "en": "Vayu / Hanuman", "hi": "वायु / हनुमान"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Kartikeya", "hi": "कार्तिकेय"}]','B');
INSERT INTO knowledge_quiz VALUES(2224,'Which mountain is associated with Lord Shiva as his abode?','भगवान शिव का निवास किस पर्वत को माना जाता है?','[{"key": "A", "en": "Mount Meru", "hi": "मेरु पर्वत"}, {"key": "B", "en": "Mount Kailash", "hi": "कैलाश पर्वत"}, {"key": "C", "en": "Mount Mandara", "hi": "मंदराचल"}, {"key": "D", "en": "Mount Govardhan", "hi": "गोवर्धन पर्वत"}]','B');
INSERT INTO knowledge_quiz VALUES(2225,'Which river is considered the daughter of the Himalayas?','किस नदी को हिमालय की पुत्री कहा जाता है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Alaknanda", "hi": "अलकनंदा"}]','B');
INSERT INTO knowledge_quiz VALUES(2226,'Which Jyotirlinga is located in Ujjain?','उज्जैन में कौन सा ज्योतिर्लिंग स्थित है?','[{"key": "A", "en": "Somnath", "hi": "सोमनाथ"}, {"key": "B", "en": "Mahakaleshwar", "hi": "महाकालेश्वर"}, {"key": "C", "en": "Omkareshwar", "hi": "ओंकारेश्वर"}, {"key": "D", "en": "Kedarnath", "hi": "केदारनाथ"}]','B');
INSERT INTO knowledge_quiz VALUES(2227,'The ''Ashtavinayak'' pilgrimage consists of how many temples dedicated to Lord Ganesha in Maharashtra?','''अष्टविनायक'' तीर्थयात्रा में महाराष्ट्र में भगवान गणेश को समर्पित कितने मंदिर शामिल हैं?','[{"key": "A", "en": "5", "hi": "5"}, {"key": "B", "en": "8", "hi": "8"}, {"key": "C", "en": "10", "hi": "10"}, {"key": "D", "en": "12", "hi": "12"}]','B');
INSERT INTO knowledge_quiz VALUES(2228,'Which temple is located at the confluence of Ganga and Yamuna?','गंगा और यमुना के संगम पर कौन सा तीर्थ स्थित है?','[{"key": "A", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "B", "en": "Prayagraj", "hi": "प्रयागराज"}, {"key": "C", "en": "Haridwar", "hi": "हरिद्वार"}, {"key": "D", "en": "Rishikesh", "hi": "ऋषिकेश"}]','B');
INSERT INTO knowledge_quiz VALUES(2229,'Bishnupur in Bankura district is world-famous for its temples built with which unique material?','बांकुरा जिले का बिष्णुपुर किन अनूठी सामग्रियों से बने अपने मंदिरों के लिए विश्व प्रसिद्ध है?','[{"key": "A", "en": "Marble", "hi": "संगमरमर"}, {"key": "B", "en": "Terracotta Bricks", "hi": "टेराकोटा (पकी मिट्टी की ईंटें)"}, {"key": "C", "en": "Sandstone", "hi": "बलुआ पत्थर"}, {"key": "D", "en": "White Granite", "hi": "सफेद ग्रेनाइट"}]','B');
INSERT INTO knowledge_quiz VALUES(2230,'At Palani temple, what is the main prasadam offered to Lord Murugan and given to devotees?','पलानी मंदिर में भगवान मुरुगन को अर्पित किया जाने वाला और भक्तों को दिया जाने वाला मुख्य प्रसाद क्या है?','[{"key": "A", "en": "Laddu", "hi": "लड्डू"}, {"key": "B", "en": "Panchamirtham", "hi": "पंचामृतम"}, {"key": "C", "en": "Payasam", "hi": "पायसम"}, {"key": "D", "en": "Vada", "hi": "वड़ा"}]','B');
INSERT INTO knowledge_quiz VALUES(2231,'Which festival marks the victory of Rama over Ravana?','राम की रावण पर विजय का प्रतीक पर्व कौन सा है?','[{"key": "A", "en": "Diwali", "hi": "दीपावली"}, {"key": "B", "en": "Dussehra", "hi": "दशहरा"}, {"key": "C", "en": "Rama Navami", "hi": "राम नवमी"}, {"key": "D", "en": "Holi", "hi": "होली"}]','B');
INSERT INTO knowledge_quiz VALUES(2232,'Which festival marks the return of Rama to Ayodhya?','राम के अयोध्या लौटने का उत्सव कौन सा है?','[{"key": "A", "en": "Dussehra", "hi": "दशहरा"}, {"key": "B", "en": "Diwali", "hi": "दीपावली"}, {"key": "C", "en": "Rama Navami", "hi": "राम नवमी"}, {"key": "D", "en": "Holi", "hi": "होली"}]','B');
INSERT INTO knowledge_quiz VALUES(2233,'Which goddess is worshipped during Navratri?','नवरात्रि में किस देवी की पूजा होती है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(2234,'Which festival is dedicated to Lord Ganesha?','कौन सा पर्व भगवान गणेश को समर्पित है?','[{"key": "A", "en": "Ganesh Chaturthi", "hi": "गणेश चतुर्थी"}, {"key": "B", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "C", "en": "Diwali", "hi": "दीपावली"}, {"key": "D", "en": "Holi", "hi": "होली"}]','A');
