INSERT INTO knowledge_quiz VALUES(2236,'Which festival is known as the festival of colors?','रंगों का पर्व किसे कहा जाता है?','[{"key": "A", "en": "Holi", "hi": "होली"}, {"key": "B", "en": "Diwali", "hi": "दीपावली"}, {"key": "C", "en": "Dussehra", "hi": "दशहरा"}, {"key": "D", "en": "Navratri", "hi": "नवरात्रि"}]','A');
