INSERT INTO knowledge_quiz VALUES(2277,'Which temple is built at the site where Lord Krishna is believed to have left his mortal body?','वह कौन सा मंदिर है जो उस स्थान पर बना है जहाँ माना जाता है कि भगवान कृष्ण ने अपना देह त्याग किया था?','[{"key": "A", "en": "Gita Mandir", "hi": "गीता मंदिर"}, {"key": "B", "en": "Triveni Sangam", "hi": "त्रिवेणी संगम"}, {"key": "C", "en": "Bhalka Tirth", "hi": "भालका तीर्थ"}, {"key": "D", "en": "Somnath", "hi": "सोमनाथ"}]','C');
