INSERT INTO knowledge_quiz VALUES(2279,'Which city is known as the birthplace of Lord Krishna?','भगवान कृष्ण की जन्मभूमि कौन सी नगरी है?','[{"key": "A", "en": "Ayodhya", "hi": "अयोध्या"}, {"key": "B", "en": "Mathura", "hi": "मथुरा"}, {"key": "C", "en": "Dwarka", "hi": "द्वारका"}, {"key": "D", "en": "Vrindavan", "hi": "वृंदावन"}]','B');
INSERT INTO knowledge_quiz VALUES(2280,'Which city is known as the kingdom of Lord Krishna?','भगवान कृष्ण की नगरी किसे कहा जाता है?','[{"key": "A", "en": "Mathura", "hi": "मथुरा"}, {"key": "B", "en": "Vrindavan", "hi": "वृंदावन"}, {"key": "C", "en": "Dwarka", "hi": "द्वारका"}, {"key": "D", "en": "Ayodhya", "hi": "अयोध्या"}]','C');
INSERT INTO knowledge_quiz VALUES(2281,'Which city is associated with Lord Shiva?','भगवान शिव से संबंधित नगरी कौन सी है?','[{"key": "A", "en": "Ayodhya", "hi": "अयोध्या"}, {"key": "B", "en": "Mathura", "hi": "मथुरा"}, {"key": "C", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "D", "en": "Dwarka", "hi": "द्वारका"}]','C');
INSERT INTO knowledge_quiz VALUES(2282,'Which river flows through Varanasi?','वाराणसी नगर से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Godavari", "hi": "गोदावरी"}, {"key": "D", "en": "Sarayu", "hi": "सरयू"}]','B');
INSERT INTO knowledge_quiz VALUES(2283,'Which river flows through Mathura?','मथुरा से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Sarayu", "hi": "सरयू"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','B');
INSERT INTO knowledge_quiz VALUES(2284,'Which river flows through Ayodhya?','अयोध्या से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Sarayu", "hi": "सरयू"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Yamuna", "hi": "यमुना"}, {"key": "D", "en": "Ghaghara", "hi": "घाघरा"}]','A');
INSERT INTO knowledge_quiz VALUES(2285,'Which river flows through Haridwar?','हरिद्वार से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Alaknanda", "hi": "अलकनंदा"}, {"key": "D", "en": "Mandakini", "hi": "मंदाकिनी"}]','B');
INSERT INTO knowledge_quiz VALUES(2286,'In the Hanuman Chalisa, the phrase ''Ashta Siddhi Nav Nidhi Ke Daata'' means Hanuman can grant 8 supernatural powers and 9 types of what?','हनुमान चालीसा में, ''अष्ट सिद्धि नव निधि के दाता'' का अर्थ है कि हनुमान 8 अलौकिक शक्तियाँ और 9 प्रकार की क्या प्रदान कर सकते हैं?','[{"key": "A", "en": "Wealth/Treasures", "hi": "धन/निधियाँ"}, {"key": "B", "en": "Weapons", "hi": "अस्त्र"}, {"key": "C", "en": "Planets", "hi": "ग्रह"}, {"key": "D", "en": "Directions", "hi": "दिशाएँ"}]','A');
INSERT INTO knowledge_quiz VALUES(2287,'Which Aarti is traditionally performed early in the morning to wake up the deity in a temple?','मंदिर में देवता को जगाने के लिए पारंपरिक रूप से सुबह-सवेरे कौन सी आरती की जाती है?','[{"key": "A", "en": "Sandhya Aarti", "hi": "संध्या आरती"}, {"key": "B", "en": "Mangal Aarti", "hi": "मंगल आरती"}, {"key": "C", "en": "Shayan Aarti", "hi": "शयन आरती"}, {"key": "D", "en": "Bhog Aarti", "hi": "भोग आरती"}]','B');
INSERT INTO knowledge_quiz VALUES(2288,'Which Aarti is sung to conclude the ''Jagrata'' or ''Chowki'' dedicated to Goddess Durga?','देवी दुर्गा को समर्पित ''जागरण'' या ''चौकी'' के समापन पर कौन सी आरती गाई जाती है?','[{"key": "A", "en": "Jai Ambe Gauri", "hi": "जय अम्बे गौरी"}, {"key": "B", "en": "Bhor Bhai Din Chadh Gaya", "hi": "भोर भई दिन चढ़ गया"}, {"key": "C", "en": "Durga Chalisa", "hi": "दुर्गा चालीसा"}, {"key": "D", "en": "Mangal Aarti", "hi": "मंगल आरती"}]','B');
INSERT INTO knowledge_quiz VALUES(2289,'Which temple in Gujarat is known as the ''Sun Temple of the East'' and was built by the Solanki dynasty?','गुजरात के किस मंदिर को ''पूर्व का सूर्य मंदिर'' कहा जाता है और इसका निर्माण सोलंकी राजवंश द्वारा किया गया था?','[{"key": "A", "en": "Somnath", "hi": "सोमनाथ"}, {"key": "B", "en": "Modhera", "hi": "मोढेरा"}, {"key": "C", "en": "Dwarkadhish", "hi": "द्वारकाधीश"}, {"key": "D", "en": "Akshardham", "hi": "अक्षरधाम"}]','B');
INSERT INTO knowledge_quiz VALUES(2290,'Which river flows through Dwarka?','द्वारका से होकर कौन सी नदी बहती है?','[{"key": "A", "en": "Gomti", "hi": "गोमती"}, {"key": "B", "en": "Sarayu", "hi": "सरयू"}, {"key": "C", "en": "Yamuna", "hi": "यमुना"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','A');
INSERT INTO knowledge_quiz VALUES(2291,'Which scripture is known as the fifth Veda?','किस ग्रंथ को पंचम वेद कहा जाता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(2292,'Which scripture is considered the essence of the Vedas?','वेदों का सार किस ग्रंथ को माना जाता है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "C", "en": "Brahmanas", "hi": "ब्राह्मण"}, {"key": "D", "en": "Aranyakas", "hi": "आरण्यक"}]','A');
INSERT INTO knowledge_quiz VALUES(2293,'Which temple in Gujarat is famous for its ''Akhand Jyot'' (eternal flame) which has been burning for over 600 years?','गुजरात का कौन सा मंदिर अपनी ''अखंड ज्योत'' के लिए प्रसिद्ध है जो 600 से अधिक वर्षों से जल रही है?','[{"key": "A", "en": "Ambaji", "hi": "अम्बाजी"}, {"key": "B", "en": "Harsiddhi Mata", "hi": "हर्षसिद्धि माता"}, {"key": "C", "en": "Navlakha", "hi": "नवलखा"}, {"key": "D", "en": "Ashapura Mata", "hi": "आशापुरा माता"}]','B');
INSERT INTO knowledge_quiz VALUES(2294,'How many Vedas are there?','कुल कितने वेद हैं?','[{"key": "A", "en": "3", "hi": "3"}, {"key": "B", "en": "4", "hi": "4"}, {"key": "C", "en": "5", "hi": "5"}, {"key": "D", "en": "6", "hi": "6"}]','B');
INSERT INTO knowledge_quiz VALUES(2295,'Which is the oldest Veda?','सबसे प्राचीन वेद कौन सा है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Samaveda", "hi": "सामवेद"}, {"key": "C", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','A');
INSERT INTO knowledge_quiz VALUES(2296,'Which Veda is associated with music and chants?','संगीत और मंत्रोच्चार से संबंधित वेद कौन सा है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Samaveda", "hi": "सामवेद"}, {"key": "C", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','B');
INSERT INTO knowledge_quiz VALUES(2297,'Which Veda deals mainly with rituals?','कर्मकांड से संबंधित वेद कौन सा है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Samaveda", "hi": "सामवेद"}, {"key": "C", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','C');
INSERT INTO knowledge_quiz VALUES(2298,'Which Veda contains hymns related to daily life?','दैनिक जीवन से जुड़े मंत्र किस वेद में मिलते हैं?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Samaveda", "hi": "सामवेद"}, {"key": "C", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','D');
INSERT INTO knowledge_quiz VALUES(2299,'Which temple in Gorakhpur is the main seat of the ''Nath Sampradaya'' and is named after a famous medieval saint?','गोरखपुर का कौन सा मंदिर ''नाथ संप्रदाय'' का मुख्य स्थान है और इसका नाम एक प्रसिद्ध मध्यकालीन संत के नाम पर रखा गया है?','[{"key": "A", "en": "Gorakhnath Temple", "hi": "गोरखनाथ मंदिर"}, {"key": "B", "en": "Mahadev Temple", "hi": "महादेव मंदिर"}, {"key": "C", "en": "Hanuman Garhi", "hi": "हनुमान गढ़ी"}, {"key": "D", "en": "Patalpuri Temple", "hi": "पातालपुरी मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2300,'Which mantra is considered the Gayatri Mantra?','गायत्री मंत्र किस देवता को समर्पित है?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','C');
INSERT INTO knowledge_quiz VALUES(2301,'Which temple in Ujjain is dedicated to the goddess of power and is one of the 51 Shakti Peethas?','उज्जैन का कौन सा मंदिर शक्ति की देवी को समर्पित है और 51 शक्तिपीठों में से एक है?','[{"key": "A", "en": "Harsiddhi Temple", "hi": "हरसिद्धि मंदिर"}, {"key": "B", "en": "Mangalnath Temple", "hi": "मंगलनाथ मंदिर"}, {"key": "C", "en": "Chintaman Ganesh", "hi": "चिंतामन गणेश"}, {"key": "D", "en": "Gadkalika Temple", "hi": "गढ़कालिका मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2302,'The Sandipani Ashram in Ujjain is famous as the place where which two deities received their education?','उज्जैन का सांदीपनि आश्रम उस स्थान के रूप में प्रसिद्ध है जहाँ किन दो देवताओं ने शिक्षा प्राप्त की थी?','[{"key": "A", "en": "Rama and Laxmana", "hi": "राम और लक्ष्मण"}, {"key": "B", "en": "Krishna and Balarama", "hi": "कृष्ण और बलराम"}, {"key": "C", "en": "Ganesha and Kartikeya", "hi": "गणेश और कार्तिकेय"}, {"key": "D", "en": "Luv and Kush", "hi": "लव और कुश"}]','B');
INSERT INTO knowledge_quiz VALUES(2303,'Which of these temples opens its doors for devotees only once a year on Nag Panchami?','इनमें से कौन सा मंदिर साल में केवल एक बार नागपंचमी पर भक्तों के लिए अपने द्वार खोलता है?','[{"key": "A", "en": "Nagchandreshwar Temple", "hi": "नागचंद्रेश्वर मंदिर"}, {"key": "B", "en": "Bada Ganesh", "hi": "बड़ा गणेश"}, {"key": "C", "en": "Gopal Mandir", "hi": "गोपाल मंदिर"}, {"key": "D", "en": "Navgraha Mandir", "hi": "नवग्रह मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2304,'Which language was the Ramcharitmanas written in?','रामचरितमानस किस भाषा में लिखी गई?','[{"key": "A", "en": "Sanskrit", "hi": "संस्कृत"}, {"key": "B", "en": "Awadhi", "hi": "अवधी"}, {"key": "C", "en": "Braj", "hi": "ब्रज"}, {"key": "D", "en": "Hindi", "hi": "हिंदी"}]','B');
INSERT INTO knowledge_quiz VALUES(2305,'Which language was the original Ramayana written in?','मूल रामायण किस भाषा में लिखी गई?','[{"key": "A", "en": "Prakrit", "hi": "प्राकृत"}, {"key": "B", "en": "Sanskrit", "hi": "संस्कृत"}, {"key": "C", "en": "Pali", "hi": "पाली"}, {"key": "D", "en": "Tamil", "hi": "तमिल"}]','B');
INSERT INTO knowledge_quiz VALUES(2306,'Who was the son of Sahadeva and his second wife, Princess Vijaya of Madra?','सहदेव और उनकी दूसरी पत्नी, मद्र की राजकुमारी विजया के पुत्र कौन थे?','[{"key": "A", "en": "Suhotra", "hi": "सुहोत्र"}, {"key": "B", "en": "Nirmitra", "hi": "निर् मित्र"}, {"key": "C", "en": "Abhimanyu", "hi": "अभिमन्यु"}, {"key": "D", "en": "Iravan", "hi": "इरावन"}]','A');
INSERT INTO knowledge_quiz VALUES(2307,'Who was the wife of Lord Rama?','भगवान राम की पत्नी कौन थीं?','[{"key": "A", "en": "Mandodari", "hi": "मंदोदरी"}, {"key": "B", "en": "Sita", "hi": "सीता"}, {"key": "C", "en": "Urmila", "hi": "उर्मिला"}, {"key": "D", "en": "Tara", "hi": "तारा"}]','B');
INSERT INTO knowledge_quiz VALUES(2308,'Who was the father of Sita?','सीता के पिता कौन थे?','[{"key": "A", "en": "Dasharatha", "hi": "दशरथ"}, {"key": "B", "en": "Janaka", "hi": "जनक"}, {"key": "C", "en": "Vibhishana", "hi": "विभीषण"}, {"key": "D", "en": "Vali", "hi": "वालि"}]','B');
INSERT INTO knowledge_quiz VALUES(2309,'Which brother ruled Ayodhya during Rama’s exile?','राम के वनवास के समय अयोध्या पर किस भाई ने शासन किया?','[{"key": "A", "en": "Lakshmana", "hi": "लक्ष्मण"}, {"key": "B", "en": "Shatrughna", "hi": "शत्रुघ्न"}, {"key": "C", "en": "Bharata", "hi": "भरत"}, {"key": "D", "en": "None", "hi": "कोई नहीं"}]','C');
INSERT INTO knowledge_quiz VALUES(2310,'How many years did Lord Rama spend in exile?','भगवान राम ने कितने वर्षों का वनवास किया?','[{"key": "A", "en": "10 years", "hi": "10 वर्ष"}, {"key": "B", "en": "12 years", "hi": "12 वर्ष"}, {"key": "C", "en": "14 years", "hi": "14 वर्ष"}, {"key": "D", "en": "16 years", "hi": "16 वर्ष"}]','C');
INSERT INTO knowledge_quiz VALUES(2311,'Who was the king of Lanka?','लंका का राजा कौन था?','[{"key": "A", "en": "Kumbhakarna", "hi": "कुंभकर्ण"}, {"key": "B", "en": "Vibhishana", "hi": "विभीषण"}, {"key": "C", "en": "Ravana", "hi": "रावण"}, {"key": "D", "en": "Indrajit", "hi": "इंद्रजीत"}]','C');
INSERT INTO knowledge_quiz VALUES(2312,'Who was Ravana’s brother who supported Rama?','रावण का कौन सा भाई राम के पक्ष में था?','[{"key": "A", "en": "Kumbhakarna", "hi": "कुंभकर्ण"}, {"key": "B", "en": "Vibhishana", "hi": "विभीषण"}, {"key": "C", "en": "Indrajit", "hi": "इंद्रजीत"}, {"key": "D", "en": "Atikaya", "hi": "अतिकाय"}]','B');
INSERT INTO knowledge_quiz VALUES(2313,'How many silver-plated wooden doors lead to the main sanctum of the Siddhi Vinayaka temple?',' सिद्धि विनायक मंदिर के मुख्य गर्भगृह तक चांदी की परत वाले कितने लकड़ी के दरवाजे जाते हैं?','[{"key": "A", "en": "Two", "hi": "दो"}, {"key": "B", "en": "Three", "hi": "तीन"}, {"key": "C", "en": "Four", "hi": "चार"}, {"key": "D", "en": "Five", "hi": "पाँच"}]','B');
INSERT INTO knowledge_quiz VALUES(2314,'Who was the chief architect responsible for building the Ram Setu?','राम सेतु के निर्माण के लिए जिम्मेदार मुख्य वास्तुकार कौन थे?','[{"key": "A", "en": "Hanuman and Angad", "hi": "हनुमान और अंगद"}, {"key": "B", "en": "Nala and Nila", "hi": "नल और नील"}, {"key": "C", "en": "Sugriva and Jambavan", "hi": "सुग्रीव और जाम्बवंत"}, {"key": "D", "en": "Vishwakarma", "hi": "विश्वकर्मा"}]','B');
INSERT INTO knowledge_quiz VALUES(2315,'Who was the king of Kishkindha?','किष्किंधा का राजा कौन था?','[{"key": "A", "en": "Vali", "hi": "वालि"}, {"key": "B", "en": "Sugriva", "hi": "सुग्रीव"}, {"key": "C", "en": "Angada", "hi": "अंगद"}, {"key": "D", "en": "Hanuman", "hi": "हनुमान"}]','B');
INSERT INTO knowledge_quiz VALUES(2316,'Who was the son of Vali?','वालि का पुत्र कौन था?','[{"key": "A", "en": "Hanuman", "hi": "हनुमान"}, {"key": "B", "en": "Angada", "hi": "अंगद"}, {"key": "C", "en": "Sugriva", "hi": "सुग्रीव"}, {"key": "D", "en": "Nala", "hi": "नल"}]','B');
INSERT INTO knowledge_quiz VALUES(2317,'Who burnt Lanka with his tail?','पूंछ से लंका को किसने जलाया?','[{"key": "A", "en": "Sugriva", "hi": "सुग्रीव"}, {"key": "B", "en": "Angada", "hi": "अंगद"}, {"key": "C", "en": "Hanuman", "hi": "हनुमान"}, {"key": "D", "en": "Jambavan", "hi": "जाम्बवान"}]','C');
INSERT INTO knowledge_quiz VALUES(2318,'Who reminded Hanuman of his powers?','हनुमान को उनकी शक्तियों का स्मरण किसने कराया?','[{"key": "A", "en": "Sugriva", "hi": "सुग्रीव"}, {"key": "B", "en": "Angada", "hi": "अंगद"}, {"key": "C", "en": "Jambavan", "hi": "जाम्बवान"}, {"key": "D", "en": "Rama", "hi": "राम"}]','C');
INSERT INTO knowledge_quiz VALUES(2319,'Who was Hanuman’s father?','हनुमान के पिता कौन थे?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Vayu", "hi": "वायु"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','B');
INSERT INTO knowledge_quiz VALUES(2320,'Who was Hanuman’s mother?','हनुमान की माता कौन थीं?','[{"key": "A", "en": "Anjana", "hi": "अंजना"}, {"key": "B", "en": "Kausalya", "hi": "कौशल्या"}, {"key": "C", "en": "Sumitra", "hi": "सुमित्रा"}, {"key": "D", "en": "Tara", "hi": "तारा"}]','A');
INSERT INTO knowledge_quiz VALUES(2321,'Which weapon did Rama use to kill Ravana?','राम ने रावण का वध किस अस्त्र से किया?','[{"key": "A", "en": "Brahmastra", "hi": "ब्रह्मास्त्र"}, {"key": "B", "en": "Pashupatastra", "hi": "पाशुपतास्त्र"}, {"key": "C", "en": "Narayanastra", "hi": "नारायणास्त्र"}, {"key": "D", "en": "Agneyastra", "hi": "आग्नेयास्त्र"}]','A');
INSERT INTO knowledge_quiz VALUES(2322,'Who was Ravana’s son?','रावण का पुत्र कौन था?','[{"key": "A", "en": "Atikaya", "hi": "अतिकाय"}, {"key": "B", "en": "Indrajit", "hi": "इंद्रजीत"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "None", "hi": "कोई नहीं"}]','C');
