INSERT INTO knowledge_quiz VALUES(2325,'Which famous temple in Bali is built on a large offshore rock and is known for its sunset views?','बाली का कौन सा प्रसिद्ध मंदिर एक बड़ी समुद्री चट्टान पर बना है और अपने सूर्यास्त के दृश्यों के लिए जाना जाता है?','[{"key": "A", "en": "Tanah Lot", "hi": "तानाह लोट"}, {"key": "B", "en": "Uluwatu", "hi": "उलुवातु"}, {"key": "C", "en": "Pura Lempuyang", "hi": "पुरा लेम्पूयांग"}, {"key": "D", "en": "Tirta Gangga", "hi": "तिर्ता गंगा"}]','A');
INSERT INTO knowledge_quiz VALUES(2326,'Which avatar of Vishnu is Lord Rama?','भगवान राम विष्णु के कौन से अवतार हैं?','[{"key": "A", "en": "Seventh", "hi": "सातवें"}, {"key": "B", "en": "Eighth", "hi": "आठवें"}, {"key": "C", "en": "Ninth", "hi": "नौवें"}, {"key": "D", "en": "Tenth", "hi": "दसवें"}]','A');
INSERT INTO knowledge_quiz VALUES(2327,'Which avatar of Vishnu is Lord Krishna?','भगवान कृष्ण विष्णु के कौन से अवतार हैं?','[{"key": "A", "en": "Seventh", "hi": "सातवें"}, {"key": "B", "en": "Eighth", "hi": "आठवें"}, {"key": "C", "en": "Ninth", "hi": "नौवें"}, {"key": "D", "en": "Tenth", "hi": "दसवें"}]','B');
INSERT INTO knowledge_quiz VALUES(2328,'Which avatar of Vishnu is Kalki?','कल्कि विष्णु के कौन से अवतार हैं?','[{"key": "A", "en": "Eighth", "hi": "आठवें"}, {"key": "B", "en": "Ninth", "hi": "नौवें"}, {"key": "C", "en": "Tenth", "hi": "दसवें"}, {"key": "D", "en": "Eleventh", "hi": "ग्यारहवें"}]','C');
INSERT INTO knowledge_quiz VALUES(2329,'Which avatar of Vishnu appeared as a fish?','मछली रूप में विष्णु का कौन सा अवतार था?','[{"key": "A", "en": "Kurma", "hi": "कूर्म"}, {"key": "B", "en": "Matsya", "hi": "मत्स्य"}, {"key": "C", "en": "Varaha", "hi": "वराह"}, {"key": "D", "en": "Vamana", "hi": "वामन"}]','B');
INSERT INTO knowledge_quiz VALUES(2330,'Which avatar of Vishnu appeared as a dwarf?','बौने रूप में विष्णु का कौन सा अवतार था?','[{"key": "A", "en": "Vamana", "hi": "वामन"}, {"key": "B", "en": "Narasimha", "hi": "नरसिंह"}, {"key": "C", "en": "Parashurama", "hi": "परशुराम"}, {"key": "D", "en": "Rama", "hi": "राम"}]','A');
INSERT INTO knowledge_quiz VALUES(2331,'Which avatar of Vishnu killed Hiranyakashipu?','हिरण्यकशिपु का वध विष्णु के किस अवतार ने किया?','[{"key": "A", "en": "Varaha", "hi": "वराह"}, {"key": "B", "en": "Narasimha", "hi": "नरसिंह"}, {"key": "C", "en": "Vamana", "hi": "वामन"}, {"key": "D", "en": "Kurma", "hi": "कूर्म"}]','B');
INSERT INTO knowledge_quiz VALUES(2332,'Who was Hiranyakashipu’s son?','हिरण्यकशिपु का पुत्र कौन था?','[{"key": "A", "en": "Bali", "hi": "बलि"}, {"key": "B", "en": "Prahlada", "hi": "प्रह्लाद"}, {"key": "C", "en": "Virochana", "hi": "विरोचन"}, {"key": "D", "en": "Namuchi", "hi": "नमुचि"}]','B');
INSERT INTO knowledge_quiz VALUES(2333,'Who was the devotee saved by Narasimha?','नरसिंह द्वारा किस भक्त की रक्षा की गई?','[{"key": "A", "en": "Dhruva", "hi": "ध्रुव"}, {"key": "B", "en": "Prahlada", "hi": "प्रह्लाद"}, {"key": "C", "en": "Markandeya", "hi": "मार्कण्डेय"}, {"key": "D", "en": "Bali", "hi": "बलि"}]','B');
INSERT INTO knowledge_quiz VALUES(2334,'Who was King Bali’s guru?','राजा बलि के गुरु कौन थे?','[{"key": "A", "en": "Brihaspati", "hi": "बृहस्पति"}, {"key": "B", "en": "Shukracharya", "hi": "शुक्राचार्य"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Vasistha", "hi": "वशिष्ठ"}]','B');
INSERT INTO knowledge_quiz VALUES(2335,'Who pushed King Bali to the netherworld?','राजा बलि को पाताल लोक किसने भेजा?','[{"key": "A", "en": "Narasimha", "hi": "नरसिंह"}, {"key": "B", "en": "Vamana", "hi": "वामन"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','B');
INSERT INTO knowledge_quiz VALUES(2336,'Which festival is associated with King Bali?','राजा बलि से संबंधित पर्व कौन सा है?','[{"key": "A", "en": "Onam", "hi": "ओणम"}, {"key": "B", "en": "Diwali", "hi": "दीपावली"}, {"key": "C", "en": "Holi", "hi": "होली"}, {"key": "D", "en": "Navratri", "hi": "नवरात्रि"}]','A');
INSERT INTO knowledge_quiz VALUES(2337,'Who was the teacher of the Pandavas and Kauravas?','पांडवों और कौरवों के गुरु कौन थे?','[{"key": "A", "en": "Kripacharya", "hi": "कृपाचार्य"}, {"key": "B", "en": "Dronacharya", "hi": "द्रोणाचार्य"}, {"key": "C", "en": "Vyasa", "hi": "व्यास"}, {"key": "D", "en": "Vasistha", "hi": "वशिष्ठ"}]','B');
INSERT INTO knowledge_quiz VALUES(2338,'In Govardhan, which sacred lake is believed to have been created by Lord Krishna for his gopis to bathe in?','गोवर्धन में किस पवित्र कुंड के बारे में माना जाता है कि इसे भगवान कृष्ण ने अपनी गोपियों के स्नान के लिए बनाया था?','[{"key": "A", "en": "Radha Kund", "hi": "राधा कुंड"}, {"key": "B", "en": "Kusum Sarovar", "hi": "कुसुम सरोवर"}, {"key": "C", "en": "Manasi Ganga", "hi": "मानसी गंगा"}, {"key": "D", "en": "Govinda Kund", "hi": "गोविंद कुंड"}]','C');
INSERT INTO knowledge_quiz VALUES(2339,'Who was the best archer among the Pandavas?','पांडवों में सर्वश्रेष्ठ धनुर्धर कौन था?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Nakula", "hi": "नकुल"}, {"key": "D", "en": "Sahadeva", "hi": "सहदेव"}]','B');
INSERT INTO knowledge_quiz VALUES(2340,'Who was the eldest Pandava?','पांडवों में सबसे बड़े कौन थे?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "D", "en": "Nakula", "hi": "नकुल"}]','C');
INSERT INTO knowledge_quiz VALUES(2341,'Who was the strongest Pandava?','पांडवों में सबसे बलवान कौन था?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Nakula", "hi": "नकुल"}, {"key": "D", "en": "Sahadeva", "hi": "सहदेव"}]','B');
INSERT INTO knowledge_quiz VALUES(2342,'In the Sunderbans, which goddess is worshipped as the protector of the forest and its inhabitants from tigers?','सुंदरवन में, जंगल और वहां के निवासियों को बाघों से बचाने वाली रक्षक के रूप में किस देवी की पूजा की जाती है?','[{"key": "A", "en": "Manasa Devi", "hi": "मनसा देवी"}, {"key": "B", "en": "Bon Bibi", "hi": "बन बीबी"}, {"key": "C", "en": "Shitala Mata", "hi": "शीतला माता"}, {"key": "D", "en": "Kamakhya Devi", "hi": "कामाख्या देवी"}]','B');
INSERT INTO knowledge_quiz VALUES(2343,'Who was the wife of the Pandavas?','पांडवों की पत्नी कौन थीं?','[{"key": "A", "en": "Subhadra", "hi": "सुभद्रा"}, {"key": "B", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "C", "en": "Urmila", "hi": "उर्मिला"}, {"key": "D", "en": "Gandhari", "hi": "गांधारी"}]','B');
INSERT INTO knowledge_quiz VALUES(2344,'Who was the wife of Duryodhana?','दुर्योधन की पत्नी कौन थीं?','[{"key": "A", "en": "Gandhari", "hi": "गांधारी"}, {"key": "B", "en": "Bhanumati", "hi": "भानुमती"}, {"key": "C", "en": "Kunti", "hi": "कुंती"}, {"key": "D", "en": "Madri", "hi": "माद्री"}]','B');
INSERT INTO knowledge_quiz VALUES(2345,'Who was the mother of the Kauravas?','कौरवों की माता कौन थीं?','[{"key": "A", "en": "Kunti", "hi": "कुंती"}, {"key": "B", "en": "Madri", "hi": "माद्री"}, {"key": "C", "en": "Gandhari", "hi": "गांधारी"}, {"key": "D", "en": "Subhadra", "hi": "सुभद्रा"}]','C');
INSERT INTO knowledge_quiz VALUES(2346,'In the Ramayana, which character cut off the nose and ears of Ravana''s sister, Surpanakha, after she attacked Sita?','रामायण में, सीता पर हमला करने के बाद रावण की बहन शूर्पणखा की नाक और कान किस पात्र ने काटे थे?','[{"key": "A", "en": "Lord Rama", "hi": "भगवान राम"}, {"key": "B", "en": "Lakshmana", "hi": "लक्ष्मण"}, {"key": "C", "en": "Hanuman", "hi": "हनुमान"}, {"key": "D", "en": "Bharata", "hi": "भरत"}]','B');
INSERT INTO knowledge_quiz VALUES(2347,'Who was the maternal uncle of the Kauravas?','कौरवों का मामा कौन था?','[{"key": "A", "en": "Kripa", "hi": "कृप"}, {"key": "B", "en": "Shakuni", "hi": "शकुनि"}, {"key": "C", "en": "Vidura", "hi": "विदुर"}, {"key": "D", "en": "Karna", "hi": "कर्ण"}]','B');
INSERT INTO knowledge_quiz VALUES(2348,'Who advised Dhritarashtra wisely?','धृतराष्ट्र को बुद्धिमानी से सलाह कौन देता था?','[{"key": "A", "en": "Shakuni", "hi": "शकुनि"}, {"key": "B", "en": "Drona", "hi": "द्रोण"}, {"key": "C", "en": "Vidura", "hi": "विदुर"}, {"key": "D", "en": "Bhishma", "hi": "भीष्म"}]','C');
INSERT INTO knowledge_quiz VALUES(2349,'Who was the grandsire of both Pandavas and Kauravas?','पांडवों और कौरवों के पितामह कौन थे?','[{"key": "A", "en": "Shantanu", "hi": "शंतनु"}, {"key": "B", "en": "Bhishma", "hi": "भीष्म"}, {"key": "C", "en": "Vyasa", "hi": "व्यास"}, {"key": "D", "en": "Vichitravirya", "hi": "विचित्रवीर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2350,'What is the name of the celestial flower tree that remains in Indra''s garden and never fades?','इंद्र के बगीचे में रहने वाले उस दिव्य फूलों के पेड़ का नाम क्या है जो कभी नहीं मुरझाता?','[{"key": "A", "en": "Tulsi", "hi": "तुलसी"}, {"key": "B", "en": "Parijat", "hi": "पारिजात"}, {"key": "C", "en": "Santalum", "hi": "चंदन"}, {"key": "D", "en": "Ashoka", "hi": "अशोक"}]','B');
INSERT INTO knowledge_quiz VALUES(2351,'Who delivered the Bhagavad Gita to Arjuna?','अर्जुन को भगवद्गीता का उपदेश किसने दिया?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Bhishma", "hi": "भीष्म"}, {"key": "D", "en": "Drona", "hi": "द्रोण"}]','B');
INSERT INTO knowledge_quiz VALUES(2352,'On which battlefield was the Mahabharata war fought?','महाभारत का युद्ध किस युद्धभूमि में लड़ा गया?','[{"key": "A", "en": "Panipat", "hi": "पानीपत"}, {"key": "B", "en": "Kurukshetra", "hi": "कुरुक्षेत्र"}, {"key": "C", "en": "Hastinapur", "hi": "हस्तिनापुर"}, {"key": "D", "en": "Indraprastha", "hi": "इंद्रप्रस्थ"}]','B');
INSERT INTO knowledge_quiz VALUES(2353,'How many days did the Mahabharata war last?','महाभारत का युद्ध कितने दिनों तक चला?','[{"key": "A", "en": "10 days", "hi": "10 दिन"}, {"key": "B", "en": "14 days", "hi": "14 दिन"}, {"key": "C", "en": "18 days", "hi": "18 दिन"}, {"key": "D", "en": "21 days", "hi": "21 दिन"}]','C');
INSERT INTO knowledge_quiz VALUES(2354,'Who was the commander-in-chief of the Kaurava army on the first day?','पहले दिन कौरव सेना के सेनापति कौन थे?','[{"key": "A", "en": "Drona", "hi": "द्रोण"}, {"key": "B", "en": "Bhishma", "hi": "भीष्म"}, {"key": "C", "en": "Karna", "hi": "कर्ण"}, {"key": "D", "en": "Shalya", "hi": "शल्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2355,'Who was the commander-in-chief of the Pandava army?','पांडव सेना के सेनापति कौन थे?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Dhrishtadyumna", "hi": "धृष्टद्युम्न"}, {"key": "D", "en": "Yudhishthira", "hi": "युधिष्ठिर"}]','C');
INSERT INTO knowledge_quiz VALUES(2356,'Who killed Bhishma?','भीष्म को किसने पराजित किया?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Shikhandi", "hi": "शिखंडी"}, {"key": "D", "en": "Dhrishtadyumna", "hi": "धृष्टद्युम्न"}]','C');
INSERT INTO knowledge_quiz VALUES(2357,'Which temple near Bhandardara is famous for its intricate stone carvings and is accessible via a boat ride across the Arthur Lake?','भंडारदरा के पास कौन सा मंदिर अपनी जटिल पत्थर की नक्काशी के लिए प्रसिद्ध है और आर्थर झील के पार नाव से पहुँचा जा सकता है?','[{"key": "A", "en": "Amruteshwar", "hi": "अमृतेश्वर"}, {"key": "B", "en": "Ghatghar Temple", "hi": "घाटघर मंदिर"}, {"key": "C", "en": "Randha Fall Temple", "hi": "रंधा फॉल मंदिर"}, {"key": "D", "en": "Agasti Rishi Ashram", "hi": "अगस्ति ऋषि आश्रम"}]','A');
INSERT INTO knowledge_quiz VALUES(2358,'Who killed Karna?','कर्ण का वध किसने किया?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Nakula", "hi": "नकुल"}]','C');
INSERT INTO knowledge_quiz VALUES(2359,'Who killed Duryodhana?','दुर्योधन का वध किसने किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Sahadeva", "hi": "सहदेव"}]','B');
INSERT INTO knowledge_quiz VALUES(2360,'Who was Karna’s real mother?','कर्ण की वास्तविक माता कौन थीं?','[{"key": "A", "en": "Madri", "hi": "माद्री"}, {"key": "B", "en": "Gandhari", "hi": "गांधारी"}, {"key": "C", "en": "Kunti", "hi": "कुंती"}, {"key": "D", "en": "Radha", "hi": "राधा"}]','C');
INSERT INTO knowledge_quiz VALUES(2361,'Who was Karna’s divine father?','कर्ण के दिव्य पिता कौन थे?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Surya", "hi": "सूर्य"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','B');
INSERT INTO knowledge_quiz VALUES(2362,'Who was the foster father of Karna?','कर्ण के पालक पिता कौन थे?','[{"key": "A", "en": "Adhiratha", "hi": "अधिरथ"}, {"key": "B", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}, {"key": "C", "en": "Pandu", "hi": "पांडु"}, {"key": "D", "en": "Shantanu", "hi": "शंतनु"}]','A');
INSERT INTO knowledge_quiz VALUES(2363,'Who cursed Karna that his chariot wheel would get stuck?','कर्ण को यह श्राप किसने दिया कि उसका रथ फंस जाएगा?','[{"key": "A", "en": "Parashurama", "hi": "परशुराम"}, {"key": "B", "en": "Brahmin", "hi": "ब्राह्मण"}, {"key": "C", "en": "Bhishma", "hi": "भीष्म"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
