INSERT INTO knowledge_quiz VALUES(2409,'Which forest is associated with Krishna’s childhood?','कृष्ण के बाल्यकाल से कौन सा वन जुड़ा है?','[{"key": "A", "en": "Dandakaranya", "hi": "दंडकारण्य"}, {"key": "B", "en": "Naimisharanya", "hi": "नैमिषारण्य"}, {"key": "C", "en": "Vrindavan", "hi": "वृंदावन"}, {"key": "D", "en": "Chitrakoot", "hi": "चित्रकूट"}]','C');
INSERT INTO knowledge_quiz VALUES(2410,'Which festival celebrates Krishna’s birth?','कृष्ण जन्म का उत्सव कौन सा है?','[{"key": "A", "en": "Ram Navami", "hi": "राम नवमी"}, {"key": "B", "en": "Janmashtami", "hi": "जन्माष्टमी"}, {"key": "C", "en": "Holi", "hi": "होली"}, {"key": "D", "en": "Diwali", "hi": "दीपावली"}]','B');
INSERT INTO knowledge_quiz VALUES(2411,'Which form of Krishna is worshipped in Nathdwara?','नाथद्वारा में कृष्ण के किस रूप की पूजा होती है?','[{"key": "A", "en": "Gopala", "hi": "गोपाल"}, {"key": "B", "en": "Shrinathji", "hi": "श्रीनाथजी"}, {"key": "C", "en": "Dwarkadhish", "hi": "द्वारकाधीश"}, {"key": "D", "en": "Makhan Chor", "hi": "माखन चोर"}]','B');
INSERT INTO knowledge_quiz VALUES(2412,'Which devotee offered Krishna a handful of beaten rice?','कृष्ण को चिउड़ा किस भक्त ने अर्पित किया था?','[{"key": "A", "en": "Sudama", "hi": "सुदामा"}, {"key": "B", "en": "Uddhava", "hi": "उद्धव"}, {"key": "C", "en": "Akrura", "hi": "अक्रूर"}, {"key": "D", "en": "Nanda", "hi": "नंद"}]','A');
INSERT INTO knowledge_quiz VALUES(2413,'Which gopi is considered the supreme devotee of Krishna?','कृष्ण की परम भक्त गोपी कौन मानी जाती हैं?','[{"key": "A", "en": "Radha", "hi": "राधा"}, {"key": "B", "en": "Rukmini", "hi": "रुक्मिणी"}, {"key": "C", "en": "Yashoda", "hi": "यशोदा"}, {"key": "D", "en": "Lalita", "hi": "ललिता"}]','A');
INSERT INTO knowledge_quiz VALUES(2414,'Which dance is associated with Krishna and the gopis?','कृष्ण और गोपियों से कौन सा नृत्य जुड़ा है?','[{"key": "A", "en": "Tandava", "hi": "तांडव"}, {"key": "B", "en": "Lasya", "hi": "लास्य"}, {"key": "C", "en": "Rasa Lila", "hi": "रास लीला"}, {"key": "D", "en": "Kathakali", "hi": "कथकली"}]','C');
INSERT INTO knowledge_quiz VALUES(2415,'Who was Krishna’s messenger to the Kauravas?','कौरवों के पास कृष्ण का दूत कौन था?','[{"key": "A", "en": "Akrura", "hi": "अक्रूर"}, {"key": "B", "en": "Uddhava", "hi": "उद्धव"}, {"key": "C", "en": "Krishna himself", "hi": "स्वयं कृष्ण"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','C');
INSERT INTO knowledge_quiz VALUES(2416,'Which king was a staunch enemy of Krishna and attacked Mathura many times?','कौन सा राजा कृष्ण का कट्टर शत्रु था और उसने मथुरा पर कई बार आक्रमण किया?','[{"key": "A", "en": "Kansa", "hi": "कंस"}, {"key": "B", "en": "Jarandha", "hi": "जरासंध"}, {"key": "C", "en": "Shishupala", "hi": "शिशुपाल"}, {"key": "D", "en": "Duryodhana", "hi": "दुर्योधन"}]','B');
INSERT INTO knowledge_quiz VALUES(2417,'Who killed Shishupala?','शिशुपाल का वध किसने किया?','[{"key": "A", "en": "Balarama", "hi": "बलराम"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Bhima", "hi": "भीम"}, {"key": "D", "en": "Arjuna", "hi": "अर्जुन"}]','B');
INSERT INTO knowledge_quiz VALUES(2418,'At which sacrifice did Krishna kill Shishupala?','किस यज्ञ में कृष्ण ने शिशुपाल का वध किया?','[{"key": "A", "en": "Ashvamedha", "hi": "अश्वमेध"}, {"key": "B", "en": "Rajasuya", "hi": "राजसूय"}, {"key": "C", "en": "Sarpa Satra", "hi": "सर्पसत्र"}, {"key": "D", "en": "Somayajna", "hi": "सोमयज्ञ"}]','B');
INSERT INTO knowledge_quiz VALUES(2419,'Who performed the Rajasuya Yajna?','राजसूय यज्ञ किसने किया था?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "D", "en": "Bhishma", "hi": "भीष्म"}]','C');
INSERT INTO knowledge_quiz VALUES(2420,'Which warrior beheaded Jayadratha?','जयद्रथ का वध किस योद्धा ने किया?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','B');
INSERT INTO knowledge_quiz VALUES(2421,'Who was Jayadratha’s wife?','जयद्रथ की पत्नी कौन थीं?','[{"key": "A", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "B", "en": "Dussala", "hi": "दुश्शला"}, {"key": "C", "en": "Gandhari", "hi": "गांधारी"}, {"key": "D", "en": "Subhadra", "hi": "सुभद्रा"}]','B');
INSERT INTO knowledge_quiz VALUES(2422,'Who was the only sister of the Kauravas?','कौरवों की एकमात्र बहन कौन थीं?','[{"key": "A", "en": "Subhadra", "hi": "सुभद्रा"}, {"key": "B", "en": "Uttara", "hi": "उत्तरा"}, {"key": "C", "en": "Dussala", "hi": "दुश्शला"}, {"key": "D", "en": "Chitrangada", "hi": "चित्रांगदा"}]','C');
INSERT INTO knowledge_quiz VALUES(2423,'In Tirupati, which goddess has a dedicated temple in Tiruchanur?','तिरुपति में, तिरुचानूर में किस देवी का समर्पित मंदिर है?','[{"key": "A", "en": "Goddess Meenakshi", "hi": "देवी मीनाक्षी"}, {"key": "B", "en": "Goddess Padmavathi", "hi": "देवी पद्मावती"}, {"key": "C", "en": "Goddess Kamakshi", "hi": "देवी कामाक्षी"}, {"key": "D", "en": "Goddess Andal", "hi": "देवी अंडाल"}]','B');
INSERT INTO knowledge_quiz VALUES(2424,'Who was the son of Bhima and Hidimba?','भीम और हिडिंबा का पुत्र कौन था?','[{"key": "A", "en": "Abhimanyu", "hi": "अभिमन्यु"}, {"key": "B", "en": "Ghatotkacha", "hi": "घटोत्कच"}, {"key": "C", "en": "Iravan", "hi": "इरावान"}, {"key": "D", "en": "Prativindhya", "hi": "प्रतिविंध्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2425,'Who killed Ghatotkacha?','घटोत्कच का वध किसने किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhishma", "hi": "भीष्म"}, {"key": "C", "en": "Karna", "hi": "कर्ण"}, {"key": "D", "en": "Drona", "hi": "द्रोण"}]','C');
INSERT INTO knowledge_quiz VALUES(2426,'Which divine weapon did Karna use to kill Ghatotkacha?','घटोत्कच को मारने के लिए कर्ण ने कौन सा दिव्य अस्त्र प्रयोग किया?','[{"key": "A", "en": "Brahmastra", "hi": "ब्रह्मास्त्र"}, {"key": "B", "en": "Vasavi Shakti", "hi": "वासवी शक्ति"}, {"key": "C", "en": "Agneyastra", "hi": "आग्नेयास्त्र"}, {"key": "D", "en": "Narayanastra", "hi": "नारायणास्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(2427,'Who was the wife of Bhima?','भीम की पत्नी कौन थीं?','[{"key": "A", "en": "Hidimba", "hi": "हिडिंबा"}, {"key": "B", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Subhadra", "hi": "सुभद्रा"}]','C');
INSERT INTO knowledge_quiz VALUES(2428,'Which river flows near the Rudranath temple and is used for performing rituals for ancestors?','रुद्रनाथ मंदिर के पास कौन सी नदी बहती है जिसका उपयोग पितरों के तर्पण के लिए किया जाता है?','[{"key": "A", "en": "Mandakini", "hi": "मंदाकिनी"}, {"key": "B", "en": "Alaknanda", "hi": "अलकनंदा"}, {"key": "C", "en": "Vaitarani", "hi": "वैतरणी"}, {"key": "D", "en": "Pindar", "hi": "पिंडर"}]','C');
INSERT INTO knowledge_quiz VALUES(2429,'Which Pandava was known for beauty and horse knowledge?','सुंदरता और अश्व-ज्ञान के लिए कौन सा पांडव प्रसिद्ध था?','[{"key": "A", "en": "Nakula", "hi": "नकुल"}, {"key": "B", "en": "Sahadeva", "hi": "सहदेव"}, {"key": "C", "en": "Bhima", "hi": "भीम"}, {"key": "D", "en": "Arjuna", "hi": "अर्जुन"}]','A');
INSERT INTO knowledge_quiz VALUES(2430,'Who was the son of Yudhishthira?','युधिष्ठिर के पुत्र कौन थे?','[{"key": "A", "en": "Prativindhya", "hi": "प्रतिविंध्य"}, {"key": "B", "en": "Sutasoma", "hi": "सुतसोम"}, {"key": "C", "en": "Shrutakarma", "hi": "श्रुतकर्मा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','A');
INSERT INTO knowledge_quiz VALUES(2431,'The winter idol of Madmaheshwar is shifted to which location for worship?','मदमहेश्वर की शीतकालीन मूर्ति को पूजा के लिए किस स्थान पर ले जाया जाता है?','[{"key": "A", "en": "Joshimath", "hi": "जोशीमठ"}, {"key": "B", "en": "Ukhimath", "hi": "ऊखीमठ"}, {"key": "C", "en": "Gopeshwar", "hi": "गोपेश्वर"}, {"key": "D", "en": "Guptkashi", "hi": "गुप्तकाशी"}]','B');
INSERT INTO knowledge_quiz VALUES(2432,'Who cursed Ashwatthama?','अश्वत्थामा को किसने श्राप दिया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Vyasa", "hi": "व्यास"}]','C');
INSERT INTO knowledge_quiz VALUES(2433,'Which gem was embedded in Ashwatthama’s forehead?','अश्वत्थामा के मस्तक में कौन सा मणि जड़ा था?','[{"key": "A", "en": "Kaustubha", "hi": "कौस्तुभ"}, {"key": "B", "en": "Syamantaka", "hi": "स्यमंतक"}, {"key": "C", "en": "Mani", "hi": "मणि"}, {"key": "D", "en": "Chintamani", "hi": "चिंतामणि"}]','C');
INSERT INTO knowledge_quiz VALUES(2434,'Who protected Uttara’s womb from Ashwatthama’s weapon?','अश्वत्थामा के अस्त्र से उत्तरा के गर्भ की रक्षा किसने की?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Bhishma", "hi": "भीष्म"}]','B');
INSERT INTO knowledge_quiz VALUES(2435,'Which king was resurrected multiple times by Jarasandha?','जरासंध किस राजा को बार-बार पुनर्जीवित करता था?','[{"key": "A", "en": "Shishupala", "hi": "शिशुपाल"}, {"key": "B", "en": "Jarasandha himself", "hi": "स्वयं जरासंध"}, {"key": "C", "en": "Kansa", "hi": "कंस"}, {"key": "D", "en": "Bali", "hi": "बलि"}]','B');
INSERT INTO knowledge_quiz VALUES(2436,'Who killed Jarasandha?','जरासंध का वध किसने किया?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Bhima", "hi": "भीम"}, {"key": "D", "en": "Balarama", "hi": "बलराम"}]','C');
INSERT INTO knowledge_quiz VALUES(2437,'Which technique was used to kill Jarasandha?','जरासंध को मारने के लिए कौन सी विधि अपनाई गई?','[{"key": "A", "en": "Beheading", "hi": "शीर्षच्छेदन"}, {"key": "B", "en": "Splitting the body", "hi": "शरीर को चीरना"}, {"key": "C", "en": "Poison", "hi": "विष"}, {"key": "D", "en": "Arrow", "hi": "बाण"}]','B');
INSERT INTO knowledge_quiz VALUES(2438,'Which Yadava was a great devotee and advisor of Krishna?','कृष्ण के महान भक्त और सलाहकार कौन से यादव थे?','[{"key": "A", "en": "Akrura", "hi": "अक्रूर"}, {"key": "B", "en": "Uddhava", "hi": "उद्धव"}, {"key": "C", "en": "Satyaki", "hi": "सात्यकि"}, {"key": "D", "en": "Nanda", "hi": "नंद"}]','B');
INSERT INTO knowledge_quiz VALUES(2439,'Which sacred conch belonged to Krishna?','कृष्ण की शंख का नाम क्या था?','[{"key": "A", "en": "Devadatta", "hi": "देवदत्त"}, {"key": "B", "en": "Panchajanya", "hi": "पाञ्चजन्य"}, {"key": "C", "en": "Anantavijaya", "hi": "अनंतविजय"}, {"key": "D", "en": "Sughosha", "hi": "सुघोष"}]','B');
INSERT INTO knowledge_quiz VALUES(2440,'Which conch belonged to Arjuna?','अर्जुन की शंख का नाम क्या था?','[{"key": "A", "en": "Devadatta", "hi": "देवदत्त"}, {"key": "B", "en": "Panchajanya", "hi": "पाञ्चजन्य"}, {"key": "C", "en": "Anantavijaya", "hi": "अनंतविजय"}, {"key": "D", "en": "Sughosha", "hi": "सुघोष"}]','A');
INSERT INTO knowledge_quiz VALUES(2441,'Which conch belonged to Bhima?','भीम की शंख का नाम क्या था?','[{"key": "A", "en": "Devadatta", "hi": "देवदत्त"}, {"key": "B", "en": "Paundra", "hi": "पौण्ड्र"}, {"key": "C", "en": "Anantavijaya", "hi": "अनंतविजय"}, {"key": "D", "en": "Sughosha", "hi": "सुघोष"}]','B');
INSERT INTO knowledge_quiz VALUES(2442,'Which Pandava’s conch was named Anantavijaya?','अनंतविजय नामक शंख किस पांडव की थी?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "D", "en": "Nakula", "hi": "नकुल"}]','C');
INSERT INTO knowledge_quiz VALUES(2443,'Who blew the conch Sughosha?','सुघोष नामक शंख किसने फूंकी?','[{"key": "A", "en": "Nakula", "hi": "नकुल"}, {"key": "B", "en": "Sahadeva", "hi": "सहदेव"}, {"key": "C", "en": "Bhima", "hi": "भीम"}, {"key": "D", "en": "Arjuna", "hi": "अर्जुन"}]','B');
INSERT INTO knowledge_quiz VALUES(2444,'The Rudra Mahalaya temple ruins are found in which historic town of Gujarat?','रुद्र महालय मंदिर के अवशेष गुजरात के किस ऐतिहासिक शहर में पाए जाते हैं?','[{"key": "A", "en": "Modhera", "hi": "मोढेरा"}, {"key": "B", "en": "Sidhpur", "hi": "सिद्धपुर"}, {"key": "C", "en": "Patan", "hi": "पाटन"}, {"key": "D", "en": "Champaner", "hi": "चांपानेर"}]','B');
INSERT INTO knowledge_quiz VALUES(2445,'How many chapters are there in the Bhagavad Gita?','भगवद्गीता में कितने अध्याय हैं?','[{"key": "A", "en": "16", "hi": "16"}, {"key": "B", "en": "18", "hi": "18"}, {"key": "C", "en": "20", "hi": "20"}, {"key": "D", "en": "24", "hi": "24"}]','B');
INSERT INTO knowledge_quiz VALUES(2446,'How many verses are there in the Bhagavad Gita (approx)?','भगवद्गीता में लगभग कितने श्लोक हैं?','[{"key": "A", "en": "500", "hi": "500"}, {"key": "B", "en": "600", "hi": "600"}, {"key": "C", "en": "700", "hi": "700"}, {"key": "D", "en": "800", "hi": "800"}]','C');
INSERT INTO knowledge_quiz VALUES(2447,'Who was the narrator of the Bhagavad Gita?','भगवद्गीता के उपदेशक कौन थे?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Sanjaya", "hi": "संजय"}, {"key": "D", "en": "Arjuna", "hi": "अर्जुन"}]','B');
INSERT INTO knowledge_quiz VALUES(2448,'Who heard the Bhagavad Gita directly besides Arjuna?','अर्जुन के अलावा भगवद्गीता किसने प्रत्यक्ष सुनी?','[{"key": "A", "en": "Sanjaya", "hi": "संजय"}, {"key": "B", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}, {"key": "C", "en": "Bhishma", "hi": "भीष्म"}, {"key": "D", "en": "Kripa", "hi": "कृप"}]','A');
INSERT INTO knowledge_quiz VALUES(2449,'Which path is emphasized most in the Bhagavad Gita?','भगवद्गीता में किस मार्ग पर सबसे अधिक बल दिया गया है?','[{"key": "A", "en": "Karma Yoga", "hi": "कर्म योग"}, {"key": "B", "en": "Bhakti Yoga", "hi": "भक्ति योग"}, {"key": "C", "en": "Jnana Yoga", "hi": "ज्ञान योग"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2450,'Which concept means performing duty without attachment to results?','फल की आसक्ति छोड़े बिना कर्तव्य करने की शिक्षा किस अवधारणा में है?','[{"key": "A", "en": "Bhakti", "hi": "भक्ति"}, {"key": "B", "en": "Sannyasa", "hi": "संन्यास"}, {"key": "C", "en": "Nishkama Karma", "hi": "निष्काम कर्म"}, {"key": "D", "en": "Moksha", "hi": "मोक्ष"}]','C');
INSERT INTO knowledge_quiz VALUES(2451,'Which chapter of the Bhagavad Gita is called Sankhya Yoga?','भगवद्गीता का कौन सा अध्याय सांख्य योग कहलाता है?','[{"key": "A", "en": "Chapter 1", "hi": "अध्याय 1"}, {"key": "B", "en": "Chapter 2", "hi": "अध्याय 2"}, {"key": "C", "en": "Chapter 3", "hi": "अध्याय 3"}, {"key": "D", "en": "Chapter 4", "hi": "अध्याय 4"}]','B');
INSERT INTO knowledge_quiz VALUES(2452,'Which chapter of the Bhagavad Gita explains Karma Yoga?','भगवद्गीता का कौन सा अध्याय कर्म योग का वर्णन करता है?','[{"key": "A", "en": "Chapter 2", "hi": "अध्याय 2"}, {"key": "B", "en": "Chapter 3", "hi": "अध्याय 3"}, {"key": "C", "en": "Chapter 6", "hi": "अध्याय 6"}, {"key": "D", "en": "Chapter 12", "hi": "अध्याय 12"}]','B');
INSERT INTO knowledge_quiz VALUES(2453,'Which chapter of the Bhagavad Gita is devoted to Bhakti Yoga?','भगवद्गीता का कौन सा अध्याय भक्ति योग को समर्पित है?','[{"key": "A", "en": "Chapter 6", "hi": "अध्याय 6"}, {"key": "B", "en": "Chapter 9", "hi": "अध्याय 9"}, {"key": "C", "en": "Chapter 12", "hi": "अध्याय 12"}, {"key": "D", "en": "Chapter 15", "hi": "अध्याय 15"}]','C');
INSERT INTO knowledge_quiz VALUES(2454,'Which chapter of the Bhagavad Gita describes the Vishvarupa?','भगवद्गीता के किस अध्याय में विराट रूप का वर्णन है?','[{"key": "A", "en": "Chapter 9", "hi": "अध्याय 9"}, {"key": "B", "en": "Chapter 10", "hi": "अध्याय 10"}, {"key": "C", "en": "Chapter 11", "hi": "अध्याय 11"}, {"key": "D", "en": "Chapter 15", "hi": "अध्याय 15"}]','C');
INSERT INTO knowledge_quiz VALUES(2455,'Who granted Sanjaya divine vision?','संजय को दिव्य दृष्टि किसने प्रदान की?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','B');
INSERT INTO knowledge_quiz VALUES(2456,'Which deity is the guardian of the North-West direction?','उत्तर-पश्चिम दिशा के संरक्षक कौन से देवता हैं?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Vayu", "hi": "वायु"}, {"key": "C", "en": "Nirriti", "hi": "निरृति"}, {"key": "D", "en": "Kubera", "hi": "कुबेर"}]','B');
INSERT INTO knowledge_quiz VALUES(2457,'Which warrior took a vow to kill Jayadratha before sunset?','सूर्यास्त से पहले जयद्रथ का वध करने की प्रतिज्ञा किसने ली?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','B');
INSERT INTO knowledge_quiz VALUES(2458,'Who used illusion to hide the sun during Jayadratha’s killing?','जयद्रथ वध के समय सूर्य को छिपाने के लिए किसने माया रची?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Vyasa", "hi": "व्यास"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(2459,'Which weapon did Arjuna use to kill Jayadratha?','अर्जुन ने जयद्रथ का वध किस अस्त्र से किया?','[{"key": "A", "en": "Brahmastra", "hi": "ब्रह्मास्त्र"}, {"key": "B", "en": "Pashupatastra", "hi": "पाशुपतास्त्र"}, {"key": "C", "en": "Anjalika Astra", "hi": "अंजलिकास्त्र"}, {"key": "D", "en": "Agneyastra", "hi": "आग्नेयास्त्र"}]','C');
INSERT INTO knowledge_quiz VALUES(2460,'Who was the father of Abhimanyu?','अभिमन्यु के पिता कौन थे?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Yudhishthira", "hi": "युधिष्ठिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2461,'Who knew the complete Chakravyuha strategy?','चक्रव्यूह की पूरी रचना कौन जानता था?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Abhimanyu", "hi": "अभिमन्यु"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Drona", "hi": "द्रोण"}]','A');
INSERT INTO knowledge_quiz VALUES(2462,'Why did Abhimanyu not know how to exit the Chakravyuha?','अभिमन्यु को चक्रव्यूह से निकलने का ज्ञान क्यों नहीं था?','[{"key": "A", "en": "He was too young", "hi": "वह बहुत छोटा था"}, {"key": "B", "en": "He was injured", "hi": "वह घायल था"}, {"key": "C", "en": "He heard only half the knowledge", "hi": "उसने आधा ज्ञान ही सुना था"}, {"key": "D", "en": "He forgot", "hi": "वह भूल गया"}]','C');
INSERT INTO knowledge_quiz VALUES(2463,'Who was the teacher of the Kauravas and Pandavas?','कौरवों और पांडवों के गुरु कौन थे?','[{"key": "A", "en": "Kripa", "hi": "कृप"}, {"key": "B", "en": "Drona", "hi": "द्रोण"}, {"key": "C", "en": "Vyasa", "hi": "व्यास"}, {"key": "D", "en": "Bhishma", "hi": "भीष्म"}]','B');
INSERT INTO knowledge_quiz VALUES(2464,'Which temple in Vrindavan is built of red sandstone and was commissioned by Raja Man Singh of Amer in 1590?','वृंदावन का कौन सा मंदिर लाल बलुआ पत्थर से बना है और इसे 1590 में आमेर के राजा मान सिंह ने बनवाया था?','[{"key": "A", "en": "Radha Damodar", "hi": "राधा दामोदर"}, {"key": "B", "en": "Govind Dev Ji Temple", "hi": "गोविंद देव जी मंदिर"}, {"key": "C", "en": "Madan Mohan Temple", "hi": "मदन मोहन मंदिर"}, {"key": "D", "en": "Rangji Temple", "hi": "रंगजी मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2465,'What does Krishna perform at The ''Nidhivan'' in Vrindavan?','वृंदावन का ''निधिवन'' में हर रात भगवान कृष्ण यहाँ क्या करते हैं?','[{"key": "A", "en": "Yoga", "hi": "योग"}, {"key": "B", "en": "Raas Leela", "hi": "रास लीला"}, {"key": "C", "en": "Tapasya", "hi": "तपस्या"}, {"key": "D", "en": "Annadana", "hi": "अन्नदान"}]','B');
INSERT INTO knowledge_quiz VALUES(2466,'Who was Ekalavya devoted to as his guru?','एकलव्य किसे अपना गुरु मानता था?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Drona", "hi": "द्रोण"}, {"key": "C", "en": "Bhishma", "hi": "भीष्म"}, {"key": "D", "en": "Vyasa", "hi": "व्यास"}]','B');
INSERT INTO knowledge_quiz VALUES(2467,'What did Ekalavya offer as guru dakshina?','एकलव्य ने गुरु दक्षिणा में क्या अर्पित किया?','[{"key": "A", "en": "His thumb", "hi": "अंगूठा"}, {"key": "B", "en": "His bow", "hi": "धनुष"}, {"key": "C", "en": "Gold", "hi": "सोना"}, {"key": "D", "en": "His life", "hi": "अपना जीवन"}]','A');
INSERT INTO knowledge_quiz VALUES(2468,'Who was the maternal uncle of the Pandavas?','पांडवों के मामा कौन थे?','[{"key": "A", "en": "Shakuni", "hi": "शकुनि"}, {"key": "B", "en": "Kansa", "hi": "कंस"}, {"key": "C", "en": "Drupada", "hi": "द्रुपद"}, {"key": "D", "en": "Subala", "hi": "सुबला"}]','A');
INSERT INTO knowledge_quiz VALUES(2469,'Who was the mastermind behind the dice game?','जुए के खेल का षड्यंत्रकर्ता कौन था?','[{"key": "A", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "B", "en": "Karna", "hi": "कर्ण"}, {"key": "C", "en": "Shakuni", "hi": "शकुनि"}, {"key": "D", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}]','C');
INSERT INTO knowledge_quiz VALUES(2470,'Who invited Yudhishthira to the dice game?','युधिष्ठिर को जुए के खेल में किसने आमंत्रित किया?','[{"key": "A", "en": "Bhishma", "hi": "भीष्म"}, {"key": "B", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "C", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}, {"key": "D", "en": "Shakuni", "hi": "शकुनि"}]','C');
INSERT INTO knowledge_quiz VALUES(2471,'Who questioned the legality of Draupadi’s disrobing?','द्रौपदी के चीरहरण की वैधता पर किसने प्रश्न उठाया?','[{"key": "A", "en": "Bhishma", "hi": "भीष्म"}, {"key": "B", "en": "Vidura", "hi": "विदुर"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Drona", "hi": "द्रोण"}]','B');
INSERT INTO knowledge_quiz VALUES(2472,'Who saved Draupadi by making her saree endless?','द्रौपदी के चीर को अनंत किसने किया?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Kunti", "hi": "कुंती"}, {"key": "D", "en": "Gandhari", "hi": "गांधारी"}]','B');
INSERT INTO knowledge_quiz VALUES(2473,'For how many years were the Pandavas exiled?','पांडवों को कितने वर्षों का वनवास मिला?','[{"key": "A", "en": "12 years", "hi": "12 वर्ष"}, {"key": "B", "en": "13 years", "hi": "13 वर्ष"}, {"key": "C", "en": "14 years", "hi": "14 वर्ष"}, {"key": "D", "en": "15 years", "hi": "15 वर्ष"}]','B');
INSERT INTO knowledge_quiz VALUES(2474,'How many years did the Pandavas live in disguise?','पांडवों ने अज्ञातवास कितने वर्षों तक किया?','[{"key": "A", "en": "10 months", "hi": "10 महीने"}, {"key": "B", "en": "11 months", "hi": "11 महीने"}, {"key": "C", "en": "1 year", "hi": "1 वर्ष"}, {"key": "D", "en": "2 years", "hi": "2 वर्ष"}]','C');
INSERT INTO knowledge_quiz VALUES(2475,'Which kingdom did the Pandavas serve during their exile in disguise?','अज्ञातवास के समय पांडव किस राज्य में रहे?','[{"key": "A", "en": "Panchala", "hi": "पांचाल"}, {"key": "B", "en": "Matsya", "hi": "मत्स्य"}, {"key": "C", "en": "Kashi", "hi": "काशी"}, {"key": "D", "en": "Kosala", "hi": "कोसल"}]','B');
INSERT INTO knowledge_quiz VALUES(2476,'Who was the king of Matsya kingdom?','मत्स्य राज्य के राजा कौन थे?','[{"key": "A", "en": "Virata", "hi": "विराट"}, {"key": "B", "en": "Drupada", "hi": "द्रुपद"}, {"key": "C", "en": "Subala", "hi": "सुबला"}, {"key": "D", "en": "Ugrasena", "hi": "उग्रसेन"}]','A');
INSERT INTO knowledge_quiz VALUES(2477,'What name did Yudhishthira take during exile?','अज्ञातवास में युधिष्ठिर ने कौन सा नाम रखा?','[{"key": "A", "en": "Valala", "hi": "वलाल"}, {"key": "B", "en": "Kanka", "hi": "कंक"}, {"key": "C", "en": "Brihannala", "hi": "बृहन्नला"}, {"key": "D", "en": "Tantripala", "hi": "तंत्रीपाल"}]','B');
INSERT INTO knowledge_quiz VALUES(2478,'What name did Bhima take during exile?','अज्ञातवास में भीम ने कौन सा नाम रखा?','[{"key": "A", "en": "Valala", "hi": "वलाल"}, {"key": "B", "en": "Kanka", "hi": "कंक"}, {"key": "C", "en": "Granthika", "hi": "ग्रंथिक"}, {"key": "D", "en": "Brihannala", "hi": "बृहन्नला"}]','A');
INSERT INTO knowledge_quiz VALUES(2479,'What name did Arjuna take during exile?','अज्ञातवास में अर्जुन ने कौन सा नाम रखा?','[{"key": "A", "en": "Brihannala", "hi": "बृहन्नला"}, {"key": "B", "en": "Tantripala", "hi": "तंत्रीपाल"}, {"key": "C", "en": "Kanka", "hi": "कंक"}, {"key": "D", "en": "Valala", "hi": "वलाल"}]','A');
INSERT INTO knowledge_quiz VALUES(2480,'What name did Nakula take during exile?','अज्ञातवास में नकुल ने कौन सा नाम रखा?','[{"key": "A", "en": "Tantripala", "hi": "तंत्रीपाल"}, {"key": "B", "en": "Granthika", "hi": "ग्रंथिक"}, {"key": "C", "en": "Valala", "hi": "वलाल"}, {"key": "D", "en": "Kanka", "hi": "कंक"}]','A');
INSERT INTO knowledge_quiz VALUES(2481,'What name did Sahadeva take during exile?','अज्ञातवास में सहदेव ने कौन सा नाम रखा?','[{"key": "A", "en": "Tantripala", "hi": "तंत्रीपाल"}, {"key": "B", "en": "Granthika", "hi": "ग्रंथिक"}, {"key": "C", "en": "Kanka", "hi": "कंक"}, {"key": "D", "en": "Valala", "hi": "वलाल"}]','B');
INSERT INTO knowledge_quiz VALUES(2482,'What name did Draupadi take during exile?','अज्ञातवास में द्रौपदी ने कौन सा नाम रखा?','[{"key": "A", "en": "Sairandhri", "hi": "सैरंध्री"}, {"key": "B", "en": "Malini", "hi": "मालिनी"}, {"key": "C", "en": "Gandhari", "hi": "गांधारी"}, {"key": "D", "en": "Uttara", "hi": "उत्तरा"}]','A');
INSERT INTO knowledge_quiz VALUES(2483,'Who insulted Draupadi during exile in Matsya kingdom?','अज्ञातवास के समय मत्स्य राज्य में द्रौपदी का अपमान किसने किया?','[{"key": "A", "en": "Virata", "hi": "विराट"}, {"key": "B", "en": "Kichaka", "hi": "कीचक"}, {"key": "C", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "D", "en": "Shakuni", "hi": "शकुनि"}]','B');
INSERT INTO knowledge_quiz VALUES(2484,'Who killed Kichaka?','कीचक का वध किसने किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Nakula", "hi": "नकुल"}]','B');
INSERT INTO knowledge_quiz VALUES(2485,'Who was Kichaka related to in Matsya kingdom?','कीचक मत्स्य राज्य में किसका संबंधी था?','[{"key": "A", "en": "Brother of Virata", "hi": "विराट का भाई"}, {"key": "B", "en": "Son of Virata", "hi": "विराट का पुत्र"}, {"key": "C", "en": "Brother-in-law of Virata", "hi": "विराट का साला"}, {"key": "D", "en": "Cousin of Virata", "hi": "विराट का चचेरा भाई"}]','C');
INSERT INTO knowledge_quiz VALUES(2486,'Who led the Kaurava army to attack Matsya kingdom?','मत्स्य राज्य पर आक्रमण के लिए कौरव सेना का नेतृत्व किसने किया?','[{"key": "A", "en": "Drona", "hi": "द्रोण"}, {"key": "B", "en": "Bhishma", "hi": "भीष्म"}, {"key": "C", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "D", "en": "Karna", "hi": "कर्ण"}]','C');
INSERT INTO knowledge_quiz VALUES(2487,'Who revealed the identity of the Pandavas after exile?','अज्ञातवास के बाद पांडवों की पहचान किसने उजागर की?','[{"key": "A", "en": "Virata", "hi": "विराट"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Kauravas", "hi": "कौरव"}, {"key": "D", "en": "Krishna", "hi": "कृष्ण"}]','B');
INSERT INTO knowledge_quiz VALUES(2488,'Which weapon did Arjuna retrieve from the Shami tree?','शमी वृक्ष से अर्जुन ने कौन सा अस्त्र निकाला?','[{"key": "A", "en": "Bow Gandiva", "hi": "गांडीव धनुष"}, {"key": "B", "en": "Sword", "hi": "तलवार"}, {"key": "C", "en": "Trident", "hi": "त्रिशूल"}, {"key": "D", "en": "Gada", "hi": "गदा"}]','A');
INSERT INTO knowledge_quiz VALUES(2489,'Who was the teacher of Draupadi’s sons?','द्रौपदी के पुत्रों के गुरु कौन थे?','[{"key": "A", "en": "Drona", "hi": "द्रोण"}, {"key": "B", "en": "Kripa", "hi": "कृप"}, {"key": "C", "en": "Vyasa", "hi": "व्यास"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','D');
INSERT INTO knowledge_quiz VALUES(2490,'What were Draupadi’s sons collectively called?','द्रौपदी के पुत्रों को सामूहिक रूप से क्या कहा जाता था?','[{"key": "A", "en": "Pandavas", "hi": "पांडव"}, {"key": "B", "en": "Upapandavas", "hi": "उपपांडव"}, {"key": "C", "en": "Kauravas", "hi": "कौरव"}, {"key": "D", "en": "Yadavas", "hi": "यादव"}]','B');
INSERT INTO knowledge_quiz VALUES(2491,'Who killed Draupadi’s sons at night?','रात में द्रौपदी के पुत्रों का वध किसने किया?','[{"key": "A", "en": "Karna", "hi": "कर्ण"}, {"key": "B", "en": "Ashwatthama", "hi": "अश्वत्थामा"}, {"key": "C", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "D", "en": "Shakuni", "hi": "शकुनि"}]','B');
INSERT INTO knowledge_quiz VALUES(2492,'Which night massacre is known as Sauptika Parva?','कौन सा रात्रि वध सौप्तिक पर्व कहलाता है?','[{"key": "A", "en": "Death of Bhishma", "hi": "भीष्म वध"}, {"key": "B", "en": "Death of Abhimanyu", "hi": "अभिमन्यु वध"}, {"key": "C", "en": "Killing of Upapandavas", "hi": "उपपांडव वध"}, {"key": "D", "en": "Death of Duryodhana", "hi": "दुर्योधन वध"}]','C');
INSERT INTO knowledge_quiz VALUES(2493,'Who stopped Ashwatthama’s Brahmastra?','अश्वत्थामा के ब्रह्मास्त्र को किसने रोका?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','C');
INSERT INTO knowledge_quiz VALUES(2494,'Who cursed Ashwatthama to wander endlessly?','अश्वत्थामा को अनंत काल तक भटकने का श्राप किसने दिया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Vyasa", "hi": "व्यास"}]','C');
INSERT INTO knowledge_quiz VALUES(2495,'Who became king after the Pandavas retired?','पांडवों के संन्यास के बाद राजा कौन बना?','[{"key": "A", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "B", "en": "Parikshit", "hi": "परीक्षित"}, {"key": "C", "en": "Janamejaya", "hi": "जनमेजय"}, {"key": "D", "en": "Arjuna", "hi": "अर्जुन"}]','B');
INSERT INTO knowledge_quiz VALUES(2496,'Who cursed Parikshit to die by snake bite?','परीक्षित को सर्पदंश से मृत्यु का श्राप किसने दिया?','[{"key": "A", "en": "Shamika Rishi", "hi": "शमिक ऋषि"}, {"key": "B", "en": "Shringi", "hi": "शृंगी"}, {"key": "C", "en": "Vyasa", "hi": "व्यास"}, {"key": "D", "en": "Narada", "hi": "नारद"}]','B');
INSERT INTO knowledge_quiz VALUES(2497,'Which serpent killed King Parikshit?','किस सर्प ने राजा परीक्षित को मारा?','[{"key": "A", "en": "Vasuki", "hi": "वासुकी"}, {"key": "B", "en": "Takshaka", "hi": "तक्षक"}, {"key": "C", "en": "Ananta", "hi": "अनंत"}, {"key": "D", "en": "Kaliya", "hi": "कालिया"}]','B');
INSERT INTO knowledge_quiz VALUES(2498,'Who narrated the Bhagavata Purana to Parikshit?','परीक्षित को भागवत पुराण किसने सुनाया?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Narada", "hi": "नारद"}, {"key": "C", "en": "Shuka", "hi": "शुक"}, {"key": "D", "en": "Vaishampayana", "hi": "वैशंपायन"}]','C');
INSERT INTO knowledge_quiz VALUES(2499,'Who was the son of Vyasa that narrated the Bhagavata Purana?','भागवत पुराण का कथन करने वाले व्यास के पुत्र कौन थे?','[{"key": "A", "en": "Shuka", "hi": "शुक"}, {"key": "B", "en": "Sanjaya", "hi": "संजय"}, {"key": "C", "en": "Kripa", "hi": "कृप"}, {"key": "D", "en": "Parashara", "hi": "पराशर"}]','A');
INSERT INTO knowledge_quiz VALUES(2500,'Which Purana emphasizes devotion (Bhakti) as the supreme path?','कौन सा पुराण भक्ति को सर्वोच्च मार्ग बताता है?','[{"key": "A", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "B", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Brahma Purana", "hi": "ब्रह्म पुराण"}]','C');
INSERT INTO knowledge_quiz VALUES(2501,'Who was the father of Bhima?','भीम के पिता कौन थे?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Vayu", "hi": "वायु"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(2502,'Who was the father of Arjuna?','अर्जुन के पिता कौन थे?','[{"key": "A", "en": "Surya", "hi": "सूर्य"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Vayu", "hi": "वायु"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(2503,'Who was the father of Yudhishthira?','युधिष्ठिर के पिता कौन थे?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Yama", "hi": "यम"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Vayu", "hi": "वायु"}]','B');
INSERT INTO knowledge_quiz VALUES(2504,'Who was the father of Nakula and Sahadeva?','नकुल और सहदेव के पिता कौन थे?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Surya", "hi": "सूर्य"}, {"key": "C", "en": "Ashwini Kumaras", "hi": "अश्विनी कुमार"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','C');
INSERT INTO knowledge_quiz VALUES(2505,'Who was the wife of King Pandu?','राजा पांडु की पत्नी कौन थीं?','[{"key": "A", "en": "Kunti", "hi": "कुंती"}, {"key": "B", "en": "Madri", "hi": "माद्री"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Gandhari", "hi": "गांधारी"}]','C');
INSERT INTO knowledge_quiz VALUES(2506,'Who cursed King Pandu?','राजा पांडु को किसने श्राप दिया था?','[{"key": "A", "en": "Kindama Rishi", "hi": "किंदम ऋषि"}, {"key": "B", "en": "Durvasa", "hi": "दुर्वासा"}, {"key": "C", "en": "Vasistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Narada", "hi": "नारद"}]','A');
INSERT INTO knowledge_quiz VALUES(2507,'Who granted Kunti the boon to invoke gods?','कुंती को देवताओं का आह्वान करने का वरदान किसने दिया?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Durvasa", "hi": "दुर्वासा"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Vasistha", "hi": "वशिष्ठ"}]','B');
INSERT INTO knowledge_quiz VALUES(2508,'Who was the first son of Kunti?','कुंती का प्रथम पुत्र कौन था?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "D", "en": "Karna", "hi": "कर्ण"}]','D');
INSERT INTO knowledge_quiz VALUES(2509,'Who raised Karna after his birth?','कर्ण का पालन-पोषण किसने किया?','[{"key": "A", "en": "Kunti", "hi": "कुंती"}, {"key": "B", "en": "Radha", "hi": "राधा"}, {"key": "C", "en": "Adhiratha and Radha", "hi": "अधिरथ और राधा"}, {"key": "D", "en": "Shantanu", "hi": "शंतनु"}]','C');
INSERT INTO knowledge_quiz VALUES(2510,'Who made Karna the king of Anga?','कर्ण को अंग देश का राजा किसने बनाया?','[{"key": "A", "en": "Bhishma", "hi": "भीष्म"}, {"key": "B", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}, {"key": "C", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "D", "en": "Shakuni", "hi": "शकुनि"}]','C');
INSERT INTO knowledge_quiz VALUES(2511,'Who was the wife of Duryodhana?','दुर्योधन की पत्नी कौन थीं?','[{"key": "A", "en": "Gandhari", "hi": "गांधारी"}, {"key": "B", "en": "Bhanumati", "hi": "भानुमती"}, {"key": "C", "en": "Dussala", "hi": "दुश्शला"}, {"key": "D", "en": "Subhadra", "hi": "सुभद्रा"}]','B');
INSERT INTO knowledge_quiz VALUES(2512,'Who was the wife of Yudhishthira?','युधिष्ठिर की पत्नी कौन थीं?','[{"key": "A", "en": "Subhadra", "hi": "सुभद्रा"}, {"key": "B", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "C", "en": "Uttara", "hi": "उत्तरा"}, {"key": "D", "en": "Chitrangada", "hi": "चित्रांगदा"}]','B');
INSERT INTO knowledge_quiz VALUES(2513,'Who was the wife of Bhima?','भीम की पत्नी कौन थीं?','[{"key": "A", "en": "Hidimba", "hi": "हिडिंबा"}, {"key": "B", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Subhadra", "hi": "सुभद्रा"}]','C');
INSERT INTO knowledge_quiz VALUES(2514,'Who was the wife of Arjuna?','अर्जुन की पत्नी कौन थीं?','[{"key": "A", "en": "Subhadra", "hi": "सुभद्रा"}, {"key": "B", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "C", "en": "Chitrangada", "hi": "चित्रांगदा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2515,'Who was the wife of Nakula?','नकुल की पत्नी कौन थीं?','[{"key": "A", "en": "Karenumati", "hi": "कारेणुमती"}, {"key": "B", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "C", "en": "Subhadra", "hi": "सुभद्रा"}, {"key": "D", "en": "Uttara", "hi": "उत्तरा"}]','A');
INSERT INTO knowledge_quiz VALUES(2516,'Who was the wife of Sahadeva?','सहदेव की पत्नी कौन थीं?','[{"key": "A", "en": "Vijaya", "hi": "विजया"}, {"key": "B", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "C", "en": "Uttara", "hi": "उत्तरा"}, {"key": "D", "en": "Subhadra", "hi": "सुभद्रा"}]','A');
INSERT INTO knowledge_quiz VALUES(2517,'Who was the wife of Abhimanyu?','अभिमन्यु की पत्नी कौन थीं?','[{"key": "A", "en": "Uttara", "hi": "उत्तरा"}, {"key": "B", "en": "Subhadra", "hi": "सुभद्रा"}, {"key": "C", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "D", "en": "Iravan", "hi": "इरावान"}]','A');
INSERT INTO knowledge_quiz VALUES(2518,'Who was the father of Ghatotkacha?','घटोत्कच के पिता कौन थे?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Drona", "hi": "द्रोण"}]','A');
INSERT INTO knowledge_quiz VALUES(2519,'Who was the mother of Ghatotkacha?','घटोत्कच की माता कौन थीं?','[{"key": "A", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "B", "en": "Hidimba", "hi": "हिडिंबा"}, {"key": "C", "en": "Kunti", "hi": "कुंती"}, {"key": "D", "en": "Madri", "hi": "माद्री"}]','B');
INSERT INTO knowledge_quiz VALUES(2520,'Who was the ruler of Indraprastha?','इंद्रप्रस्थ का शासक कौन था?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "C", "en": "Bhima", "hi": "भीम"}, {"key": "D", "en": "Duryodhana", "hi": "दुर्योधन"}]','B');
INSERT INTO knowledge_quiz VALUES(2521,'Who built the Maya Sabha for the Pandavas?','पांडवों के लिए माया सभा किसने बनाई?','[{"key": "A", "en": "Vishwakarma", "hi": "विश्वकर्मा"}, {"key": "B", "en": "Maya Danava", "hi": "मय दानव"}, {"key": "C", "en": "Takshaka", "hi": "तक्षक"}, {"key": "D", "en": "Kubera", "hi": "कुबेर"}]','B');
INSERT INTO knowledge_quiz VALUES(2522,'Who fell into the illusion of Maya Sabha?','माया सभा के भ्रम में कौन गिरा था?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "D", "en": "Karna", "hi": "कर्ण"}]','C');
INSERT INTO knowledge_quiz VALUES(2523,'Who laughed at Duryodhana in the Maya Sabha?','माया सभा में दुर्योधन पर किसने हंसी उड़ाई?','[{"key": "A", "en": "Kunti", "hi": "कुंती"}, {"key": "B", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "C", "en": "Subhadra", "hi": "सुभद्रा"}, {"key": "D", "en": "Uttara", "hi": "उत्तरा"}]','B');
INSERT INTO knowledge_quiz VALUES(2524,'Which vow did Duryodhana take after being humiliated?','अपमान के बाद दुर्योधन ने कौन सी प्रतिज्ञा ली?','[{"key": "A", "en": "To defeat Arjuna", "hi": "अर्जुन को हराने की"}, {"key": "B", "en": "To destroy the Pandavas", "hi": "पांडवों के विनाश की"}, {"key": "C", "en": "To conquer Dwarka", "hi": "द्वारका जीतने की"}, {"key": "D", "en": "To kill Bhishma", "hi": "भीष्म को मारने की"}]','B');
INSERT INTO knowledge_quiz VALUES(2525,'Who suggested the dice game to Duryodhana?','दुर्योधन को जुए का खेल खेलने की सलाह किसने दी?','[{"key": "A", "en": "Karna", "hi": "कर्ण"}, {"key": "B", "en": "Shakuni", "hi": "शकुनि"}, {"key": "C", "en": "Bhishma", "hi": "भीष्म"}, {"key": "D", "en": "Drona", "hi": "द्रोण"}]','B');
INSERT INTO knowledge_quiz VALUES(2526,'Which Pandava was known for mastery over mace fighting?','गदा युद्ध में कौन सा पांडव निपुण था?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Nakula", "hi": "नकुल"}, {"key": "D", "en": "Sahadeva", "hi": "सहदेव"}]','B');
INSERT INTO knowledge_quiz VALUES(2527,'Which Panch Kedar is considered the ''Dwitiya'' (Second) Kedar in the pilgrimage sequence?','तीर्थयात्रा के क्रम में किस मंदिर को ''द्वितीय'' केदार माना जाता है?','[{"key": "A", "en": "Tungnath", "hi": "तुंगनाथ"}, {"key": "B", "en": "Rudranath", "hi": "रुद्रनाथ"}, {"key": "C", "en": "Madmaheshwar", "hi": "मदमहेश्वर"}, {"key": "D", "en": "Kalpeshwar", "hi": "कल्पेश्वर"}]','C');
INSERT INTO knowledge_quiz VALUES(2528,'Which Pandava was known for righteousness?','धर्म के लिए कौन सा पांडव प्रसिद्ध था?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "D", "en": "Sahadeva", "hi": "सहदेव"}]','C');
INSERT INTO knowledge_quiz VALUES(2529,'Which peak is situated just above the Tungnath temple?','तुंगनाथ मंदिर के ठीक ऊपर कौन सी चोटी स्थित है?','[{"key": "A", "en": "Chaukhamba", "hi": "चौखंबा"}, {"key": "B", "en": "Nanda Devi", "hi": "नंदा देवी"}, {"key": "C", "en": "Chandrashila", "hi": "चंद्रशिला"}, {"key": "D", "en": "Trishul", "hi": "त्रिशूल"}]','C');
INSERT INTO knowledge_quiz VALUES(2530,'In Madmaheshwar, there is a separate shrine dedicated to which deity alongside Lord Shiva?','मदमहेश्वर में भगवान शिव के साथ किस अन्य देवता/देवी को समर्पित एक अलग मंदिर है?','[{"key": "A", "en": "Goddess Parvati", "hi": "देवी पार्वती"}, {"key": "B", "en": "Goddess Saraswati", "hi": "देवी सरस्वती"}, {"key": "C", "en": "Lord Vishnu", "hi": "भगवान विष्णु"}, {"key": "D", "en": "Lord Ganesha", "hi": "भगवान गणेश"}]','A');
INSERT INTO knowledge_quiz VALUES(2531,'Who was the guru of the Pandavas before Drona?','द्रोण से पहले पांडवों के गुरु कौन थे?','[{"key": "A", "en": "Kripa", "hi": "कृप"}, {"key": "B", "en": "Vasistha", "hi": "वशिष्ठ"}, {"key": "C", "en": "Parashurama", "hi": "परशुराम"}, {"key": "D", "en": "Vyasa", "hi": "व्यास"}]','A');
INSERT INTO knowledge_quiz VALUES(2532,'Who was the guru of Karna?','कर्ण के गुरु कौन थे?','[{"key": "A", "en": "Drona", "hi": "द्रोण"}, {"key": "B", "en": "Parashurama", "hi": "परशुराम"}, {"key": "C", "en": "Kripa", "hi": "कृप"}, {"key": "D", "en": "Vyasa", "hi": "व्यास"}]','B');
INSERT INTO knowledge_quiz VALUES(2533,'Why did Parashurama curse Karna?','परशुराम ने कर्ण को क्यों श्राप दिया?','[{"key": "A", "en": "For arrogance", "hi": "अहंकार के कारण"}, {"key": "B", "en": "For lying about his caste", "hi": "अपने कुल के बारे में झूठ बोलने के कारण"}, {"key": "C", "en": "For insulting him", "hi": "अपमान करने के कारण"}, {"key": "D", "en": "For disobedience", "hi": "अवज्ञा के कारण"}]','B');
INSERT INTO knowledge_quiz VALUES(2534,'Which divine armor did Karna possess at birth?','कर्ण के पास जन्म से कौन सा दिव्य कवच था?','[{"key": "A", "en": "Kavacha and Kundala", "hi": "कवच और कुंडल"}, {"key": "B", "en": "Vajra", "hi": "वज्र"}, {"key": "C", "en": "Trishula", "hi": "त्रिशूल"}, {"key": "D", "en": "Sudarsana", "hi": "सुदर्शन"}]','A');
