INSERT INTO knowledge_quiz VALUES(2578,'Who tested Yudhishthira at the gates of heaven?','स्वर्ग द्वार पर युधिष्ठिर की परीक्षा किसने ली?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Dharma", "hi": "धर्म"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','B');
INSERT INTO knowledge_quiz VALUES(2579,'What quality allowed Yudhishthira to enter heaven alive?','किस गुण के कारण युधिष्ठिर जीवित स्वर्ग गए?','[{"key": "A", "en": "Strength", "hi": "बल"}, {"key": "B", "en": "Devotion", "hi": "भक्ति"}, {"key": "C", "en": "Truthfulness", "hi": "सत्यनिष्ठा"}, {"key": "D", "en": "Intelligence", "hi": "बुद्धिमत्ता"}]','C');
INSERT INTO knowledge_quiz VALUES(2580,'Which epic narrates the story of the Pandavas?','पांडवों की कथा किस महाकाव्य में है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(2581,'Who was the author of the Mahabharata?','महाभारत के रचयिता कौन थे?','[{"key": "A", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Vasistha", "hi": "वशिष्ठ"}]','B');
INSERT INTO knowledge_quiz VALUES(2582,'Who wrote the Mahabharata as dictated by Vyasa?','व्यास के कथन अनुसार महाभारत किसने लिखा?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "C", "en": "Ganesha", "hi": "गणेश"}, {"key": "D", "en": "Kripa", "hi": "कृप"}]','C');
INSERT INTO knowledge_quiz VALUES(2583,'What condition did Ganesha place before writing the Mahabharata?','महाभारत लिखने से पहले गणेश ने कौन सी शर्त रखी?','[{"key": "A", "en": "No breaks in dictation", "hi": "कथन में विराम नहीं होगा"}, {"key": "B", "en": "Only short verses", "hi": "केवल छोटे श्लोक"}, {"key": "C", "en": "Written in one day", "hi": "एक दिन में लेखन"}, {"key": "D", "en": "No repetitions", "hi": "कोई पुनरावृत्ति नहीं"}]','A');
INSERT INTO knowledge_quiz VALUES(2584,'What condition did Vyasa set for Ganesha?','व्यास ने गणेश के लिए कौन सी शर्त रखी?','[{"key": "A", "en": "Understand before writing", "hi": "समझकर ही लिखना"}, {"key": "B", "en": "Write fast", "hi": "तेज़ लिखना"}, {"key": "C", "en": "No mistakes", "hi": "कोई गलती नहीं"}, {"key": "D", "en": "Use gold pen", "hi": "स्वर्ण लेखनी"}]','A');
INSERT INTO knowledge_quiz VALUES(2585,'Approximately how many verses are there in the Mahabharata?','महाभारत में लगभग कितने श्लोक हैं?','[{"key": "A", "en": "24,000", "hi": "24,000"}, {"key": "B", "en": "50,000", "hi": "50,000"}, {"key": "C", "en": "85,000", "hi": "85,000"}, {"key": "D", "en": "100,000", "hi": "100,000"}]','D');
INSERT INTO knowledge_quiz VALUES(2586,'Which parva is the first parva of the Mahabharata?','महाभारत का प्रथम पर्व कौन सा है?','[{"key": "A", "en": "Sabha Parva", "hi": "सभा पर्व"}, {"key": "B", "en": "Adi Parva", "hi": "आदि पर्व"}, {"key": "C", "en": "Vana Parva", "hi": "वन पर्व"}, {"key": "D", "en": "Bhishma Parva", "hi": "भीष्म पर्व"}]','B');
INSERT INTO knowledge_quiz VALUES(2587,'Which parva contains the Bhagavad Gita?','भगवद्गीता किस पर्व में आती है?','[{"key": "A", "en": "Bhishma Parva", "hi": "भीष्म पर्व"}, {"key": "B", "en": "Drona Parva", "hi": "द्रोण पर्व"}, {"key": "C", "en": "Karna Parva", "hi": "कर्ण पर्व"}, {"key": "D", "en": "Udyoga Parva", "hi": "उद्योग पर्व"}]','A');
INSERT INTO knowledge_quiz VALUES(2588,'How many parvas are there in the Mahabharata?','महाभारत में कुल कितने पर्व हैं?','[{"key": "A", "en": "16", "hi": "16"}, {"key": "B", "en": "17", "hi": "17"}, {"key": "C", "en": "18", "hi": "18"}, {"key": "D", "en": "19", "hi": "19"}]','C');
INSERT INTO knowledge_quiz VALUES(2589,'Who narrated the Mahabharata to King Janamejaya?','राजा जनमेजय को महाभारत किसने सुनाया?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Sanjaya", "hi": "संजय"}, {"key": "C", "en": "Vaishampayana", "hi": "वैशंपायन"}, {"key": "D", "en": "Shuka", "hi": "शुक"}]','C');
INSERT INTO knowledge_quiz VALUES(2590,'At which yajna was the Mahabharata narrated?','किस यज्ञ में महाभारत का कथन हुआ?','[{"key": "A", "en": "Ashvamedha Yajna", "hi": "अश्वमेध यज्ञ"}, {"key": "B", "en": "Rajasuya Yajna", "hi": "राजसूय यज्ञ"}, {"key": "C", "en": "Sarpa Satra", "hi": "सर्पसत्र"}, {"key": "D", "en": "Somayajna", "hi": "सोमयज्ञ"}]','C');
INSERT INTO knowledge_quiz VALUES(2591,'Who was Janamejaya?','जनमेजय कौन थे?','[{"key": "A", "en": "Son of Arjuna", "hi": "अर्जुन के पुत्र"}, {"key": "B", "en": "Son of Parikshit", "hi": "परीक्षित के पुत्र"}, {"key": "C", "en": "Son of Abhimanyu", "hi": "अभिमन्यु के पुत्र"}, {"key": "D", "en": "Son of Yudhishthira", "hi": "युधिष्ठिर के पुत्र"}]','B');
INSERT INTO knowledge_quiz VALUES(2592,'Why did Janamejaya conduct the Sarpa Satra?','जनमेजय ने सर्पसत्र क्यों किया?','[{"key": "A", "en": "To gain power", "hi": "शक्ति प्राप्ति हेतु"}, {"key": "B", "en": "To kill all snakes", "hi": "सभी सर्पों के नाश हेतु"}, {"key": "C", "en": "To please gods", "hi": "देवताओं को प्रसन्न करने हेतु"}, {"key": "D", "en": "To become emperor", "hi": "सम्राट बनने हेतु"}]','B');
INSERT INTO knowledge_quiz VALUES(2593,'Which sage stopped the Sarpa Satra?','सर्पसत्र को किस ऋषि ने रोका?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Astika", "hi": "आस्तीक"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Parashara", "hi": "पराशर"}]','B');
INSERT INTO knowledge_quiz VALUES(2594,'Which snake was responsible for Parikshit’s death?','परीक्षित की मृत्यु के लिए कौन सा सर्प उत्तरदायी था?','[{"key": "A", "en": "Vasuki", "hi": "वासुकी"}, {"key": "B", "en": "Takshaka", "hi": "तक्षक"}, {"key": "C", "en": "Ananta", "hi": "अनंत"}, {"key": "D", "en": "Kaliya", "hi": "कालिया"}]','B');
INSERT INTO knowledge_quiz VALUES(2595,'Who was Astika’s mother?','आस्तीक की माता कौन थीं?','[{"key": "A", "en": "Kadru", "hi": "कद्रू"}, {"key": "B", "en": "Vinata", "hi": "विनता"}, {"key": "C", "en": "Manasa", "hi": "मनसा"}, {"key": "D", "en": "Amba", "hi": "अम्बा"}]','C');
INSERT INTO knowledge_quiz VALUES(2596,'Which character is known as the incarnation of Dharma?','धर्म का अवतार कौन माना जाता है?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "D", "en": "Nakula", "hi": "नकुल"}]','C');
INSERT INTO knowledge_quiz VALUES(2597,'Which goddess is worshipped as the protector of the Rudranath area?','रुद्रनाथ क्षेत्र की रक्षक के रूप में किस देवी की पूजा की जाती है?','[{"key": "A", "en": "Hariyali Devi", "hi": "हरियाली देवी"}, {"key": "B", "en": "Vandevi", "hi": "वनदेवी"}, {"key": "C", "en": "Nanda Devi", "hi": "नंदा देवी"}, {"key": "D", "en": "Surkanda Devi", "hi": "सुरकंडा देवी"}]','B');
INSERT INTO knowledge_quiz VALUES(2598,'Which lake, located near Kedarnath, is also known as ''Chorabari Tal''?','केदारनाथ के पास स्थित किस झील को ''चोराबारी ताल'' के नाम से भी जाना जाता है?','[{"key": "A", "en": "Vasuki Tal", "hi": "वासुकी ताल"}, {"key": "B", "en": "Gandhi Sarovar", "hi": "गांधी सरोवर"}, {"key": "C", "en": "Deoria Tal", "hi": "देवरिया ताल"}, {"key": "D", "en": "Roopkund", "hi": "रूपकुंड"}]','B');
INSERT INTO knowledge_quiz VALUES(2599,'The winter seat of Tungnath is located in which village?','तुंगनाथ की शीतकालीन गद्दी किस गाँव में स्थित है?','[{"key": "A", "en": "Makkumath", "hi": "मक्कूमठ"}, {"key": "B", "en": "Joshimath", "hi": "जोशीमठ"}, {"key": "C", "en": "Sari Village", "hi": "सारी गाँव"}, {"key": "D", "en": "Chopta", "hi": "चोपता"}]','A');
INSERT INTO knowledge_quiz VALUES(2600,'What is the unique architectural style of the Kedarnath temple?','केदारनाथ मंदिर की अनूठी स्थापत्य शैली क्या है?','[{"key": "A", "en": "Dravidian style", "hi": "द्रविड़ शैली"}, {"key": "B", "en": "Katyuri style", "hi": "कत्यूरी शैली"}, {"key": "C", "en": "Vesara style", "hi": "वेसर शैली"}, {"key": "D", "en": "Pagoda style", "hi": "पैगोडा शैली"}]','B');
INSERT INTO knowledge_quiz VALUES(2601,'Who was the wife of King Dhritarashtra?','राजा धृतराष्ट्र की पत्नी कौन थीं?','[{"key": "A", "en": "Kunti", "hi": "कुंती"}, {"key": "B", "en": "Gandhari", "hi": "गांधारी"}, {"key": "C", "en": "Madri", "hi": "माद्री"}, {"key": "D", "en": "Ambika", "hi": "अंबिका"}]','B');
INSERT INTO knowledge_quiz VALUES(2602,'Why did Gandhari blindfold herself?','गांधारी ने आँखों पर पट्टी क्यों बाँधी?','[{"key": "A", "en": "As a vow of penance", "hi": "तपस्या के लिए"}, {"key": "B", "en": "Out of devotion to husband", "hi": "पति के प्रति समर्पण से"}, {"key": "C", "en": "Due to curse", "hi": "श्राप के कारण"}, {"key": "D", "en": "Due to illness", "hi": "रोग के कारण"}]','B');
INSERT INTO knowledge_quiz VALUES(2603,'How many sons did Gandhari have?','गांधारी के कितने पुत्र थे?','[{"key": "A", "en": "99", "hi": "99"}, {"key": "B", "en": "100", "hi": "100"}, {"key": "C", "en": "101", "hi": "101"}, {"key": "D", "en": "102", "hi": "102"}]','C');
INSERT INTO knowledge_quiz VALUES(2604,'Who was the eldest Kaurava?','सबसे बड़ा कौरव कौन था?','[{"key": "A", "en": "Duhshasana", "hi": "दुःशासन"}, {"key": "B", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "C", "en": "Vikarna", "hi": "विकर्ण"}, {"key": "D", "en": "Chitrasena", "hi": "चित्रसेन"}]','B');
INSERT INTO knowledge_quiz VALUES(2605,'Which Kaurava opposed Draupadi’s disrobing?','द्रौपदी के चीरहरण का किस कौरव ने विरोध किया?','[{"key": "A", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "B", "en": "Duhshasana", "hi": "दुःशासन"}, {"key": "C", "en": "Vikarna", "hi": "विकर्ण"}, {"key": "D", "en": "Karna", "hi": "कर्ण"}]','C');
INSERT INTO knowledge_quiz VALUES(2606,'What is the name of the white lotus?','श्वेत कमल का नाम क्या है?','[{"key": "A", "en": "Utpala", "hi": "उत्पल"}, {"key": "B", "en": "Pundarika", "hi": "पुण्डरीक"}, {"key": "C", "en": "Kokunada", "hi": "कोकुनद"}, {"key": "D", "en": "Kamala", "hi": "कमल"}]','B');
INSERT INTO knowledge_quiz VALUES(2607,'How many horses are traditionally depicted pulling the chariot of the Sun God (Surya Dev)?','सूर्य देव के रथ को खींचते हुए पारंपरिक रूप से कितने घोड़े दर्शाए जाते हैं?','[{"key": "A", "en": "Five", "hi": "पांच"}, {"key": "B", "en": "Seven", "hi": "सात"}, {"key": "C", "en": "Nine", "hi": "नौ"}, {"key": "D", "en": "Twelve", "hi": "बारह"}]','B');
INSERT INTO knowledge_quiz VALUES(2608,'Who was the commander-in-chief of the Pandava army at the start of the war?','युद्ध के प्रारंभ में पांडव सेना के सेनापति कौन थे?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Dhrishtadyumna", "hi": "धृष्टद्युम्न"}, {"key": "C", "en": "Bhima", "hi": "भीम"}, {"key": "D", "en": "Yudhishthira", "hi": "युधिष्ठिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2609,'Who was the first commander-in-chief of the Kaurava army?','कौरव सेना के प्रथम सेनापति कौन थे?','[{"key": "A", "en": "Drona", "hi": "द्रोण"}, {"key": "B", "en": "Karna", "hi": "कर्ण"}, {"key": "C", "en": "Bhishma", "hi": "भीष्म"}, {"key": "D", "en": "Shalya", "hi": "शल्य"}]','C');
INSERT INTO knowledge_quiz VALUES(2610,'On which day of the war did Bhishma fall?','युद्ध के किस दिन भीष्म पितामह गिरे?','[{"key": "A", "en": "7th day", "hi": "सातवें दिन"}, {"key": "B", "en": "8th day", "hi": "आठवें दिन"}, {"key": "C", "en": "9th day", "hi": "नौवें दिन"}, {"key": "D", "en": "10th day", "hi": "दसवें दिन"}]','D');
INSERT INTO knowledge_quiz VALUES(2611,'Who placed Shikhandi in front of Arjuna to defeat Bhishma?','भीष्म को हराने के लिए अर्जुन के आगे शिखंडी को किसने रखा?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','A');
INSERT INTO knowledge_quiz VALUES(2612,'Which temple in Vrindavan is famous for its South Indian (Dravidian) architecture and its massive 50-feet high ''Dhwaja Stambha''?','वृंदावन का कौन सा मंदिर अपनी दक्षिण भारतीय (द्रविड़) वास्तुकला और अपने विशाल 50 फीट ऊंचे ''ध्वज स्तंभ'' के लिए प्रसिद्ध है?','[{"key": "A", "en": "Prem Mandir", "hi": "प्रेम मंदिर"}, {"key": "B", "en": "Sri Ranganatha (Rangji) Temple", "hi": "श्री रंगनाथ (रंगजी) मंदिर"}, {"key": "C", "en": "ISKCON Temple", "hi": "इस्कॉन मंदिर"}, {"key": "D", "en": "Priya Kant Ju", "hi": "प्रिया कांत जू"}]','B');
INSERT INTO knowledge_quiz VALUES(2613,'Which lie was told to Dronacharya to weaken him?','द्रोणाचार्य को दुर्बल करने के लिए कौन सा असत्य कहा गया?','[{"key": "A", "en": "Ashwatthama is wounded", "hi": "अश्वत्थामा घायल है"}, {"key": "B", "en": "Ashwatthama is captured", "hi": "अश्वत्थामा बंदी है"}, {"key": "C", "en": "Ashwatthama is dead", "hi": "अश्वत्थामा मारा गया"}, {"key": "D", "en": "Duryodhana is dead", "hi": "दुर्योधन मारा गया"}]','C');
INSERT INTO knowledge_quiz VALUES(2614,'Who killed Ghatotkacha?','घटोत्कच का वध किसने किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Karna", "hi": "कर्ण"}, {"key": "D", "en": "Duryodhana", "hi": "दुर्योधन"}]','C');
INSERT INTO knowledge_quiz VALUES(2615,'Which divine weapon did Karna use to kill Ghatotkacha?','घटोत्कच को मारने के लिए कर्ण ने कौन सा दिव्य अस्त्र प्रयोग किया?','[{"key": "A", "en": "Brahmastra", "hi": "ब्रह्मास्त्र"}, {"key": "B", "en": "Vasavi Shakti", "hi": "वासवी शक्ति"}, {"key": "C", "en": "Agneyastra", "hi": "आग्नेयास्त्र"}, {"key": "D", "en": "Pashupatastra", "hi": "पाशुपतास्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(2616,'Who killed Karna?','कर्ण का वध किसने किया?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','B');
INSERT INTO knowledge_quiz VALUES(2617,'Why was Karna unable to fight properly at the time of his death?','मृत्यु के समय कर्ण ठीक से युद्ध क्यों नहीं कर सके?','[{"key": "A", "en": "He was wounded", "hi": "वे घायल थे"}, {"key": "B", "en": "His bow broke", "hi": "धनुष टूट गया"}, {"key": "C", "en": "His chariot wheel was stuck", "hi": "रथ का पहिया धँस गया"}, {"key": "D", "en": "He lost consciousness", "hi": "वे मूर्छित हो गए"}]','C');
INSERT INTO knowledge_quiz VALUES(2618,'Who killed Duryodhana?','दुर्योधन का वध किसने किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','B');
INSERT INTO knowledge_quiz VALUES(2619,'Which weapon was used to defeat Duryodhana?','दुर्योधन को पराजित करने के लिए कौन सा अस्त्र प्रयोग हुआ?','[{"key": "A", "en": "Sword", "hi": "तलवार"}, {"key": "B", "en": "Mace", "hi": "गदा"}, {"key": "C", "en": "Arrow", "hi": "बाण"}, {"key": "D", "en": "Spear", "hi": "भाला"}]','B');
INSERT INTO knowledge_quiz VALUES(2620,'Where was the final duel between Bhima and Duryodhana fought?','भीम और दुर्योधन का अंतिम द्वंद्व कहाँ हुआ?','[{"key": "A", "en": "Kurukshetra", "hi": "कुरुक्षेत्र"}, {"key": "B", "en": "Hastinapur", "hi": "हस्तिनापुर"}, {"key": "C", "en": "Dwaitavana", "hi": "द्वैतवन"}, {"key": "D", "en": "Near a lake", "hi": "एक सरोवर के पास"}]','D');
INSERT INTO knowledge_quiz VALUES(2621,'Who was the mother of Draupadi?','द्रौपदी की माता कौन थीं?','[{"key": "A", "en": "Kunti", "hi": "कुंती"}, {"key": "B", "en": "Prishati", "hi": "पृषती"}, {"key": "C", "en": "Sudeshna", "hi": "सुदेशना"}, {"key": "D", "en": "Gandhari", "hi": "गांधारी"}]','B');
INSERT INTO knowledge_quiz VALUES(2622,'From which yajna was Draupadi born?','द्रौपदी किस यज्ञ से उत्पन्न हुई थीं?','[{"key": "A", "en": "Ashvamedha", "hi": "अश्वमेध"}, {"key": "B", "en": "Rajasuya", "hi": "राजसूय"}, {"key": "C", "en": "Putrakameshti", "hi": "पुत्रकामेष्टि"}, {"key": "D", "en": "Fire sacrifice of Drupada", "hi": "द्रुपद का यज्ञ"}]','D');
INSERT INTO knowledge_quiz VALUES(2623,'What was Draupadi’s original name?','द्रौपदी का मूल नाम क्या था?','[{"key": "A", "en": "Krishnaa", "hi": "कृष्णा"}, {"key": "B", "en": "Panchali", "hi": "पांचाली"}, {"key": "C", "en": "Yajnaseni", "hi": "याज्ञसेनी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2624,'Who won Draupadi’s swayamvara?','द्रौपदी के स्वयंवर को किसने जीता?','[{"key": "A", "en": "Karna", "hi": "कर्ण"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Bhima", "hi": "भीम"}, {"key": "D", "en": "Dhrishtadyumna", "hi": "धृष्टद्युम्न"}]','B');
INSERT INTO knowledge_quiz VALUES(2625,'Why did Draupadi marry all five Pandavas?','द्रौपदी ने पाँचों पांडवों से विवाह क्यों किया?','[{"key": "A", "en": "Kunti’s command", "hi": "कुंती के वचन से"}, {"key": "B", "en": "Divine decree", "hi": "दैवी विधान से"}, {"key": "C", "en": "Sage Vyasa’s advice", "hi": "व्यास की आज्ञा से"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2626,'What was the name of Lord Rama''s personal celestial bow?','भगवान राम के निजी दिव्य धनुष का क्या नाम था?','[{"key": "A", "en": "Pinaka", "hi": "पिनाक"}, {"key": "B", "en": "Sharanga", "hi": "शारंग"}, {"key": "C", "en": "Gandiva", "hi": "गांडीव"}, {"key": "D", "en": "Vijaya", "hi": "विजय"}]','B');
INSERT INTO knowledge_quiz VALUES(2627,'Which Saptarishi was born as a King (Rajarishi) and earned the title of Brahmarishi through intense penance?','कौन से सप्तर्षि एक राजा (राजर्षि) के रूप में पैदा हुए थे और कठिन तपस्या के माध्यम से उन्होंने ''ब्रह्मर्षि'' की उपाधि प्राप्त की थी?','[{"key": "A", "en": "Sage Vishwamitra", "hi": "ऋषि विश्वामित्र"}, {"key": "B", "en": "Sage Atri", "hi": "ऋषि अत्रि"}, {"key": "C", "en": "Sage Gautama", "hi": "ऋषि गौतम"}, {"key": "D", "en": "Sage Jamadagni", "hi": "ऋषि जमदग्नि"}]','A');
INSERT INTO knowledge_quiz VALUES(2628,'In which battle formation was Abhimanyu trapped?','अभिमन्यु किस युद्ध व्यूह में फँसे थे?','[{"key": "A", "en": "Makara Vyuh", "hi": "मकर व्यूह"}, {"key": "B", "en": "Chakra Vyuh", "hi": "चक्रव्यूह"}, {"key": "C", "en": "Garuda Vyuh", "hi": "गरुड़ व्यूह"}, {"key": "D", "en": "Padma Vyuh", "hi": "पद्म व्यूह"}]','B');
INSERT INTO knowledge_quiz VALUES(2629,'On which day of the war did Abhimanyu die?','युद्ध के किस दिन अभिमन्यु वीरगति को प्राप्त हुए?','[{"key": "A", "en": "12th day", "hi": "बारहवें दिन"}, {"key": "B", "en": "13th day", "hi": "तेरहवें दिन"}, {"key": "C", "en": "14th day", "hi": "चौदहवें दिन"}, {"key": "D", "en": "15th day", "hi": "पंद्रहवें दिन"}]','B');
INSERT INTO knowledge_quiz VALUES(2630,'Who vowed to kill Jayadratha by sunset?','सूर्यास्त तक जयद्रथ को मारने की प्रतिज्ञा किसने की?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','B');
INSERT INTO knowledge_quiz VALUES(2631,'Who killed Jayadratha?','जयद्रथ का वध किसने किया?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','B');
INSERT INTO knowledge_quiz VALUES(2632,'Which trick did Krishna use to help Arjuna kill Jayadratha?','जयद्रथ वध में अर्जुन की सहायता के लिए कृष्ण ने कौन सा उपाय किया?','[{"key": "A", "en": "Stopped the chariot", "hi": "रथ रोका"}, {"key": "B", "en": "Created darkness", "hi": "अंधकार किया"}, {"key": "C", "en": "Covered the sun", "hi": "सूर्य को ढक लिया"}, {"key": "D", "en": "Blew the conch", "hi": "शंख बजाया"}]','C');
INSERT INTO knowledge_quiz VALUES(2633,'Who was the son of Jayadratha?','जयद्रथ का पुत्र कौन था?','[{"key": "A", "en": "Sindhudesh", "hi": "सिंधुदेश"}, {"key": "B", "en": "Suratha", "hi": "सुरथ"}, {"key": "C", "en": "None", "hi": "कोई नहीं"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','C');
INSERT INTO knowledge_quiz VALUES(2634,'Who killed Shakuni?','शकुनि का वध किसने किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Nakula", "hi": "नकुल"}, {"key": "D", "en": "Sahadeva", "hi": "सहदेव"}]','D');
INSERT INTO knowledge_quiz VALUES(2635,'Who killed Duhshasana?','दुःशासन का वध किसने किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Satyaki", "hi": "सात्यकि"}, {"key": "D", "en": "Nakula", "hi": "नकुल"}]','B');
INSERT INTO knowledge_quiz VALUES(2636,'Whose blood did Bhima vow to drink?','भीम ने किसका रक्त पीने की प्रतिज्ञा की थी?','[{"key": "A", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "B", "en": "Karna", "hi": "कर्ण"}, {"key": "C", "en": "Duhshasana", "hi": "दुःशासन"}, {"key": "D", "en": "Shakuni", "hi": "शकुनि"}]','C');
INSERT INTO knowledge_quiz VALUES(2637,'Who killed Ashwatthama’s companions at night?','रात्रि में अश्वत्थामा के साथियों का वध किसने किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Ashwatthama", "hi": "अश्वत्थामा"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','C');
INSERT INTO knowledge_quiz VALUES(2638,'Which parva describes the night massacre?','रात्रि संहार का वर्णन किस पर्व में है?','[{"key": "A", "en": "Drona Parva", "hi": "द्रोण पर्व"}, {"key": "B", "en": "Shalya Parva", "hi": "शल्य पर्व"}, {"key": "C", "en": "Sauptika Parva", "hi": "सौप्तिक पर्व"}, {"key": "D", "en": "Stri Parva", "hi": "स्त्री पर्व"}]','C');
INSERT INTO knowledge_quiz VALUES(2639,'Which sons of Draupadi were killed at night?','रात्रि में द्रौपदी के कौन से पुत्र मारे गए?','[{"key": "A", "en": "All five sons", "hi": "पाँचों पुत्र"}, {"key": "B", "en": "Only eldest", "hi": "केवल ज्येष्ठ"}, {"key": "C", "en": "Only youngest", "hi": "केवल कनिष्ठ"}, {"key": "D", "en": "None", "hi": "कोई नहीं"}]','A');
INSERT INTO knowledge_quiz VALUES(2640,'In Harishchandragad, the Kedarheshwar cave''s pillars are said to represent the four Yugas. How many pillars are currently standing?','हरिश्चंद्रगढ़ में केदारेश्वर गुफा के स्तंभों के बारे में कहा जाता है कि वे चार युगों का प्रतिनिधित्व करते हैं। वर्तमान में कितने स्तंभ खड़े हैं?','[{"key": "A", "en": "Three", "hi": "तीन"}, {"key": "B", "en": "One", "hi": "एक"}, {"key": "C", "en": "Two", "hi": "दो"}, {"key": "D", "en": "None", "hi": "कोई नहीं"}]','B');
INSERT INTO knowledge_quiz VALUES(2641,'What was Ashwatthama cursed with?','अश्वत्थामा को किसका श्राप मिला?','[{"key": "A", "en": "Immediate death", "hi": "तत्काल मृत्यु"}, {"key": "B", "en": "Blindness", "hi": "अंधत्व"}, {"key": "C", "en": "Immortality with suffering", "hi": "दुःख सहित अमरता"}, {"key": "D", "en": "Loss of weapons", "hi": "अस्त्रों का नाश"}]','C');
INSERT INTO knowledge_quiz VALUES(2642,'Which jewel was taken from Ashwatthama?','अश्वत्थामा से कौन सा मणि छीना गया?','[{"key": "A", "en": "Kaustubha", "hi": "कौस्तुभ"}, {"key": "B", "en": "Syamantaka", "hi": "स्यामंतक"}, {"key": "C", "en": "Mani on forehead", "hi": "मस्तक का मणि"}, {"key": "D", "en": "Chintamani", "hi": "चिंतामणि"}]','C');
INSERT INTO knowledge_quiz VALUES(2643,'What was the name of the parrot that recited the Shrimad Bhagavatam to King Parikshit?','उस तोते का नाम क्या था जिसने राजा परीक्षित को श्रीमद्भागवत सुनाई थी (जो बाद में शुकदेव मुनि बने)?','[{"key": "A", "en": "Shuka", "hi": "शुक"}, {"key": "B", "en": "Vatapi", "hi": "वातापि"}, {"key": "C", "en": "Sampati", "hi": "सम्पाती"}, {"key": "D", "en": "Garuda", "hi": "गरुड़"}]','A');
INSERT INTO knowledge_quiz VALUES(2644,'Who crowned Parikshit as king?','परीक्षित का राज्याभिषेक किसने किया?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "D", "en": "Arjuna", "hi": "अर्जुन"}]','C');
INSERT INTO knowledge_quiz VALUES(2645,'Who cursed King Parikshit?','राजा परीक्षित को किसने श्राप दिया?','[{"key": "A", "en": "Shamika Rishi", "hi": "शमीक ऋषि"}, {"key": "B", "en": "Shringi", "hi": "शृंगी"}, {"key": "C", "en": "Vyasa", "hi": "व्यास"}, {"key": "D", "en": "Narada", "hi": "नारद"}]','B');
INSERT INTO knowledge_quiz VALUES(2646,'How did King Parikshit die?','राजा परीक्षित की मृत्यु कैसे हुई?','[{"key": "A", "en": "In battle", "hi": "युद्ध में"}, {"key": "B", "en": "Snake bite", "hi": "सर्पदंश से"}, {"key": "C", "en": "Illness", "hi": "रोग से"}, {"key": "D", "en": "Old age", "hi": "वृद्धावस्था से"}]','B');
INSERT INTO knowledge_quiz VALUES(2647,'Which snake killed King Parikshit?','राजा परीक्षित को किस सर्प ने मारा?','[{"key": "A", "en": "Vasuki", "hi": "वासुकी"}, {"key": "B", "en": "Ananta", "hi": "अनंत"}, {"key": "C", "en": "Takshaka", "hi": "तक्षक"}, {"key": "D", "en": "Kaliya", "hi": "कालिया"}]','C');
INSERT INTO knowledge_quiz VALUES(2648,'Which Purana continues the story after the Mahabharata?','महाभारत के बाद कथा किस पुराण में आगे बढ़ती है?','[{"key": "A", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "B", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "C", "en": "Brahmanda Purana", "hi": "ब्रह्माण्ड पुराण"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(2649,'Who narrated the Bhagavata Purana to Parikshit?','परीक्षित को भागवत पुराण किसने सुनाया?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Narada", "hi": "नारद"}, {"key": "C", "en": "Shuka", "hi": "शुक"}, {"key": "D", "en": "Vaishampayana", "hi": "वैशंपायन"}]','C');
INSERT INTO knowledge_quiz VALUES(2650,'How many days did Parikshit listen to the Bhagavata Purana?','परीक्षित ने कितने दिनों तक भागवत पुराण सुना?','[{"key": "A", "en": "5 days", "hi": "5 दिन"}, {"key": "B", "en": "7 days", "hi": "7 दिन"}, {"key": "C", "en": "9 days", "hi": "9 दिन"}, {"key": "D", "en": "11 days", "hi": "11 दिन"}]','B');
INSERT INTO knowledge_quiz VALUES(2651,'Who was the spiritual teacher of Shuka?','शुक के आध्यात्मिक गुरु कौन थे?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Vasistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Parashara", "hi": "पराशर"}]','B');
INSERT INTO knowledge_quiz VALUES(2652,'Which age (Yuga) began after Krishna’s departure?','कृष्ण के प्रस्थान के बाद कौन सा युग प्रारंभ हुआ?','[{"key": "A", "en": "Satya Yuga", "hi": "सत्य युग"}, {"key": "B", "en": "Treta Yuga", "hi": "त्रेता युग"}, {"key": "C", "en": "Dvapara Yuga", "hi": "द्वापर युग"}, {"key": "D", "en": "Kali Yuga", "hi": "कलियुग"}]','D');
INSERT INTO knowledge_quiz VALUES(2653,'Who is considered the narrator of the entire Mahabharata tradition?','महाभारत परंपरा के मुख्य कथावाचक कौन माने जाते हैं?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Vaishampayana", "hi": "वैशंपायन"}, {"key": "C", "en": "Sanjaya", "hi": "संजय"}, {"key": "D", "en": "Narada", "hi": "नारद"}]','A');
INSERT INTO knowledge_quiz VALUES(2654,'Which lesson is central to the Mahabharata?','महाभारत का केंद्रीय उपदेश क्या है?','[{"key": "A", "en": "Victory through power", "hi": "बल से विजय"}, {"key": "B", "en": "Supremacy of dharma", "hi": "धर्म की प्रधानता"}, {"key": "C", "en": "Importance of wealth", "hi": "धन का महत्व"}, {"key": "D", "en": "Fate is everything", "hi": "भाग्य ही सब कुछ है"}]','B');
INSERT INTO knowledge_quiz VALUES(2655,'Which epic is often called the ‘Fifth Veda’?','किस महाकाव्य को ‘पंचम वेद’ कहा जाता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(2656,'Who is known as Kodandapani?','कोदण्डपाणि के नाम से कौन जाने जाते हैं?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "C", "en": "Rama", "hi": "राम"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','C');
INSERT INTO knowledge_quiz VALUES(2657,'What was Bhishma’s original name?','भीष्म का मूल नाम क्या था?','[{"key": "A", "en": "Devavrata", "hi": "देवव्रत"}, {"key": "B", "en": "Gangaputra", "hi": "गंगापुत्र"}, {"key": "C", "en": "Shantanava", "hi": "शंतनव"}, {"key": "D", "en": "Kurunandana", "hi": "कुरुनंदन"}]','A');
INSERT INTO knowledge_quiz VALUES(2658,'Who was Bhishma’s mother?','भीष्म की माता कौन थीं?','[{"key": "A", "en": "Satyavati", "hi": "सत्यवती"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Ambika", "hi": "अंबिका"}, {"key": "D", "en": "Amba", "hi": "अंबा"}]','B');
INSERT INTO knowledge_quiz VALUES(2659,'Why was Devavrata called Bhishma?','देवव्रत को भीष्म क्यों कहा गया?','[{"key": "A", "en": "For his bravery", "hi": "वीरता के कारण"}, {"key": "B", "en": "For his terrible vow", "hi": "भयानक प्रतिज्ञा के कारण"}, {"key": "C", "en": "For his strength", "hi": "बल के कारण"}, {"key": "D", "en": "For his wisdom", "hi": "ज्ञान के कारण"}]','B');
INSERT INTO knowledge_quiz VALUES(2660,'What vow did Bhishma take?','भीष्म ने कौन सी प्रतिज्ञा ली थी?','[{"key": "A", "en": "To protect Hastinapur", "hi": "हस्तिनापुर की रक्षा"}, {"key": "B", "en": "To never marry", "hi": "आजीवन ब्रह्मचर्य"}, {"key": "C", "en": "To serve the king", "hi": "राजा की सेवा"}, {"key": "D", "en": "To renounce weapons", "hi": "अस्त्र त्याग"}]','B');
INSERT INTO knowledge_quiz VALUES(2661,'Who was the teacher of the Kuru princes?','कुरु राजकुमारों के गुरु कौन थे?','[{"key": "A", "en": "Kripa", "hi": "कृप"}, {"key": "B", "en": "Dronacharya", "hi": "द्रोणाचार्य"}, {"key": "C", "en": "Parashara", "hi": "पराशर"}, {"key": "D", "en": "Vyasa", "hi": "व्यास"}]','B');
INSERT INTO knowledge_quiz VALUES(2662,'The ''Dwarkadhish Temple'' in Mathura, famous for its colorful swings during Sravana, was built in 1814 by whom?','मथुरा का ''द्वारकाधीश मंदिर'', जो श्रावण के दौरान अपने रंगीन झूलों के लिए प्रसिद्ध है, 1814 में किसके द्वारा बनवाया गया था?','[{"key": "A", "en": "Seth Gokul Das Parikh", "hi": "सेठ गोकुल दास पारिख"}, {"key": "B", "en": "Rani Ahilyabai", "hi": "रानी अहिल्याबाई"}, {"key": "C", "en": "Maharaja Sawai Jai Singh", "hi": "महाराजा सवाई जय सिंह"}, {"key": "D", "en": "Scindia Dynasty", "hi": "सिंधिया राजवंश"}]','A');
INSERT INTO knowledge_quiz VALUES(2663,'How many kilometers is the traditional ''Govardhan Parikrama'' (circumambulation of the hill)?','पारंपरिक ''गोवर्धन परिक्रमा'' (पहाड़ी की परिक्रमा) कितने किलोमीटर की है?','[{"key": "A", "en": "11 km", "hi": "11 किमी"}, {"key": "B", "en": "21 km", "hi": "21 किमी"}, {"key": "C", "en": "40 km", "hi": "40 किमी"}, {"key": "D", "en": "51 km", "hi": "51 किमी"}]','B');
INSERT INTO knowledge_quiz VALUES(2664,'Who was Ekalavya?','एकलव्य कौन था?','[{"key": "A", "en": "A Kaurava prince", "hi": "एक कौरव राजकुमार"}, {"key": "B", "en": "A Nishada prince", "hi": "निषाद राजकुमार"}, {"key": "C", "en": "A Pandava", "hi": "एक पांडव"}, {"key": "D", "en": "A sage", "hi": "एक ऋषि"}]','B');
INSERT INTO knowledge_quiz VALUES(2665,'What did Dronacharya demand from Ekalavya?','द्रोणाचार्य ने एकलव्य से क्या गुरु-दक्षिणा माँगी?','[{"key": "A", "en": "Gold", "hi": "स्वर्ण"}, {"key": "B", "en": "His right thumb", "hi": "दायाँ अंगूठा"}, {"key": "C", "en": "His bow", "hi": "धनुष"}, {"key": "D", "en": "His kingdom", "hi": "राज्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2666,'What was the name of Lord Rama''s personal celestial bow?','भगवान राम के निजी दिव्य धनुष का क्या नाम था?','[{"key": "A", "en": "Pinaka", "hi": "पिनाक"}, {"key": "B", "en": "Kodanda", "hi": "कोदण्ड"}, {"key": "C", "en": "Gandiva", "hi": "गांडीव"}, {"key": "D", "en": "Vijaya", "hi": "विजय"}]','B');
INSERT INTO knowledge_quiz VALUES(2667,'Who was the childhood friend of Dronacharya?','द्रोणाचार्य के बाल्यकाल मित्र कौन थे?','[{"key": "A", "en": "Drupada", "hi": "द्रुपद"}, {"key": "B", "en": "Shantanu", "hi": "शंतनु"}, {"key": "C", "en": "Bhishma", "hi": "भीष्म"}, {"key": "D", "en": "Kripa", "hi": "कृप"}]','A');
INSERT INTO knowledge_quiz VALUES(2668,'Who was the king of Panchala?','पंचाल का राजा कौन था?','[{"key": "A", "en": "Drupada", "hi": "द्रुपद"}, {"key": "B", "en": "Virata", "hi": "विराट"}, {"key": "C", "en": "Shalya", "hi": "शल्य"}, {"key": "D", "en": "Jayadratha", "hi": "जयद्रथ"}]','A');
INSERT INTO knowledge_quiz VALUES(2669,'Who killed King Drupada?','राजा द्रुपद का वध किसने किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Dhrishtadyumna", "hi": "धृष्टद्युम्न"}, {"key": "D", "en": "Ashwatthama", "hi": "अश्वत्थामा"}]','C');
INSERT INTO knowledge_quiz VALUES(2670,'The newly inaugurated Shri Ram Janmabhoomi Mandir is built in which traditional Indian temple architectural style?','नवनिर्मित श्री राम जन्मभूमि मंदिर किस पारंपरिक भारतीय मंदिर वास्तुकला शैली में बना है?','[{"key": "A", "en": "Dravidian", "hi": "द्रविड़"}, {"key": "B", "en": "Nagara", "hi": "नागर"}, {"key": "C", "en": "Vesara", "hi": "वेसर"}, {"key": "D", "en": "Kalinga", "hi": "कलिंग"}]','B');
INSERT INTO knowledge_quiz VALUES(2671,'Who was the brother of Draupadi?','द्रौपदी के भाई कौन थे?','[{"key": "A", "en": "Shikhandi", "hi": "शिखंडी"}, {"key": "B", "en": "Dhrishtadyumna", "hi": "धृष्टद्युम्न"}, {"key": "C", "en": "Drupada", "hi": "द्रुपद"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','B');
INSERT INTO knowledge_quiz VALUES(2672,'Who was Shikhandi in a previous birth?','पूर्व जन्म में शिखंडी कौन था?','[{"key": "A", "en": "Amba", "hi": "अंबा"}, {"key": "B", "en": "Ambika", "hi": "अंबिका"}, {"key": "C", "en": "Ambalika", "hi": "अंबालिका"}, {"key": "D", "en": "Gandhari", "hi": "गांधारी"}]','A');
INSERT INTO knowledge_quiz VALUES(2673,'Why did Bhishma refuse to fight Shikhandi?','भीष्म ने शिखंडी से युद्ध क्यों नहीं किया?','[{"key": "A", "en": "He was too strong", "hi": "बहुत बलवान था"}, {"key": "B", "en": "He was a woman earlier", "hi": "पूर्व में स्त्री था"}, {"key": "C", "en": "He was a Brahmin", "hi": "ब्राह्मण था"}, {"key": "D", "en": "He was cursed", "hi": "श्रापित था"}]','B');
INSERT INTO knowledge_quiz VALUES(2674,'Which Saptarishi is closely associated with the River Ahalya?','कौन से सप्तर्षि अहल्या नदी से निकटता से जुड़े हैं?','[{"key": "A", "en": "Sage Gautama", "hi": "ऋषि गौतम"}, {"key": "B", "en": "Sage Kashyapa", "hi": "ऋषि कश्यप"}, {"key": "C", "en": "Sage Vishwamitra", "hi": "ऋषि विश्वामित्र"}, {"key": "D", "en": "Sage Atri", "hi": "ऋषि अत्रि"}]','A');
INSERT INTO knowledge_quiz VALUES(2675,'Who was the second wife of Pandu?','पांडु की दूसरी पत्नी कौन थीं?','[{"key": "A", "en": "Kunti", "hi": "कुंती"}, {"key": "B", "en": "Gandhari", "hi": "गांधारी"}, {"key": "C", "en": "Madri", "hi": "माद्री"}, {"key": "D", "en": "Ambalika", "hi": "अंबालिका"}]','C');
INSERT INTO knowledge_quiz VALUES(2676,'From which location did Bharata rule Ayodhya during Rama''s exile?','राम के वनवास के दौरान भरत ने अयोध्या पर शासन किस स्थान से किया?','[{"key": "A", "en": "Mithila", "hi": "मिथिला"}, {"key": "B", "en": "Nandigram", "hi": "नंदीग्राम"}, {"key": "C", "en": "Chitrakoot", "hi": "चित्रकूट"}, {"key": "D", "en": "Dandakaranya", "hi": "दंडकारण्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2677,'Who was the original owner of the Pushpaka Vimana before Ravana?','रावण से पहले पुष्पक विमान का मूल स्वामी कौन था?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Kubera", "hi": "कुबेर"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(2678,'Hanuman is considered an avatar of which primary deity?','हनुमान को किस मुख्य देवता का अवतार माना जाता है?','[{"key": "A", "en": "Lord Vishnu", "hi": "भगवान विष्णु"}, {"key": "B", "en": "Lord Shiva", "hi": "भगवान शिव"}, {"key": "C", "en": "Lord Brahma", "hi": "भगवान ब्रह्मा"}, {"key": "D", "en": "Lord Indra", "hi": "भगवान इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(2679,'Who were the fathers of Nakula and Sahadeva?','नकुल और सहदेव के पिता कौन थे?','[{"key": "A", "en": "Indra and Vayu", "hi": "इंद्र और वायु"}, {"key": "B", "en": "Ashwini Kumaras", "hi": "अश्विनीकुमार"}, {"key": "C", "en": "Surya and Chandra", "hi": "सूर्य और चंद्र"}, {"key": "D", "en": "Agni and Varuna", "hi": "अग्नि और वरुण"}]','B');
INSERT INTO knowledge_quiz VALUES(2680,'Which mantra did Kunti use to invoke gods?','कुंती ने देवताओं को बुलाने के लिए कौन सा मंत्र प्रयोग किया?','[{"key": "A", "en": "Gayatri Mantra", "hi": "गायत्री मंत्र"}, {"key": "B", "en": "Santana Mantra", "hi": "संतान मंत्र"}, {"key": "C", "en": "Durvasa Mantra", "hi": "दुर्वासा मंत्र"}, {"key": "D", "en": "Putrakameshti Mantra", "hi": "पुत्रकामेष्टि मंत्र"}]','C');
INSERT INTO knowledge_quiz VALUES(2681,'Who granted Kunti the divine mantra?','कुंती को दिव्य मंत्र किसने दिया?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Durvasa", "hi": "दुर्वासा"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2682,'Who was the biological father of Karna?','कर्ण के जैविक पिता कौन थे?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Surya", "hi": "सूर्य"}, {"key": "C", "en": "Vayu", "hi": "वायु"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(2683,'Who raised Karna as a child?','कर्ण का पालन-पोषण किसने किया?','[{"key": "A", "en": "Kunti", "hi": "कुंती"}, {"key": "B", "en": "Radha", "hi": "राधा"}, {"key": "C", "en": "Gandhari", "hi": "गांधारी"}, {"key": "D", "en": "Subhadra", "hi": "सुभद्रा"}]','B');
INSERT INTO knowledge_quiz VALUES(2684,'What was Karna’s social identity?','कर्ण की सामाजिक पहचान क्या थी?','[{"key": "A", "en": "Kshatriya", "hi": "क्षत्रिय"}, {"key": "B", "en": "Brahmin", "hi": "ब्राह्मण"}, {"key": "C", "en": "Vaishya", "hi": "वैश्य"}, {"key": "D", "en": "Suta", "hi": "सूत"}]','D');
INSERT INTO knowledge_quiz VALUES(2685,'Who was Karna’s foster father?','कर्ण के पालक पिता कौन थे?','[{"key": "A", "en": "Adhiratha", "hi": "अधिरथ"}, {"key": "B", "en": "Virata", "hi": "विराट"}, {"key": "C", "en": "Drupada", "hi": "द्रुपद"}, {"key": "D", "en": "Shantanu", "hi": "शंतनु"}]','A');
INSERT INTO knowledge_quiz VALUES(2686,'Who crowned Karna as king of Anga?','कर्ण को अंग देश का राजा किसने बनाया?','[{"key": "A", "en": "Bhishma", "hi": "भीष्म"}, {"key": "B", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "C", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}, {"key": "D", "en": "Krishna", "hi": "कृष्ण"}]','B');
INSERT INTO knowledge_quiz VALUES(2687,'Who cursed Karna to forget his mantras?','कर्ण को मंत्र भूलने का श्राप किसने दिया?','[{"key": "A", "en": "Parashurama", "hi": "परशुराम"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Narada", "hi": "नारद"}]','A');
INSERT INTO knowledge_quiz VALUES(2688,'According to local legends, what name did Krishna give to Parvati at Malinithan?','स्थानीय कथाओं के अनुसार, कृष्ण ने मालिनीथान में पार्वती को क्या नाम दिया था?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Malini", "hi": "मालिनी"}, {"key": "C", "en": "Shakti", "hi": "शक्ति"}, {"key": "D", "en": "Gauri", "hi": "गौरी"}]','B');
INSERT INTO knowledge_quiz VALUES(2689,'Who gave Karna the divine armor and earrings?','कर्ण को दिव्य कवच और कुंडल किसने दिए?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Surya", "hi": "सूर्य"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','B');
INSERT INTO knowledge_quiz VALUES(2690,'To whom did Karna give his armor and earrings?','कर्ण ने अपना कवच और कुंडल किसे दान दिए?','[{"key": "A", "en": "Surya", "hi": "सूर्य"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Parashurama", "hi": "परशुराम"}]','B');
INSERT INTO knowledge_quiz VALUES(2691,'What weapon did Indra give Karna in return?','प्रतिदान में इंद्र ने कर्ण को कौन सा अस्त्र दिया?','[{"key": "A", "en": "Brahmastra", "hi": "ब्रह्मास्त्र"}, {"key": "B", "en": "Vajra", "hi": "वज्र"}, {"key": "C", "en": "Vasavi Shakti", "hi": "वासवी शक्ति"}, {"key": "D", "en": "Agneyastra", "hi": "आग्नेयास्त्र"}]','C');
INSERT INTO knowledge_quiz VALUES(2692,'Who finally liberated Ahalya from her curse by touching her with his feet?','किसने अपने चरणों के स्पर्श से अंततः अहल्या को उनके श्राप से मुक्त किया था?','[{"key": "A", "en": "Lord Vishnu", "hi": "भगवान विष्णु"}, {"key": "B", "en": "Lord Rama", "hi": "भगवान राम"}, {"key": "C", "en": "Lord Krishna", "hi": "भगवान कृष्ण"}, {"key": "D", "en": "Lord Hanuman", "hi": "भगवान हनुमान"}]','B');
INSERT INTO knowledge_quiz VALUES(2693,'How long did Gandhari carry her pregnancy?','गांधारी ने कितने समय तक गर्भ धारण किया?','[{"key": "A", "en": "9 months", "hi": "9 महीने"}, {"key": "B", "en": "1 year", "hi": "1 वर्ष"}, {"key": "C", "en": "2 years", "hi": "2 वर्ष"}, {"key": "D", "en": "3 years", "hi": "3 वर्ष"}]','C');
INSERT INTO knowledge_quiz VALUES(2694,'What was born from Gandhari’s womb?','गांधारी के गर्भ से क्या उत्पन्न हुआ?','[{"key": "A", "en": "A baby boy", "hi": "एक पुत्र"}, {"key": "B", "en": "A girl", "hi": "एक कन्या"}, {"key": "C", "en": "A lump of flesh", "hi": "मांस का पिंड"}, {"key": "D", "en": "Twins", "hi": "जुड़वाँ"}]','C');
INSERT INTO knowledge_quiz VALUES(2695,'Who divided Gandhari’s flesh into pieces?','गांधारी के मांस पिंड को किसने विभाजित किया?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Narada", "hi": "नारद"}, {"key": "C", "en": "Kripa", "hi": "कृप"}, {"key": "D", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}]','A');
INSERT INTO knowledge_quiz VALUES(2696,'Who was the only Kaurava to oppose injustice in the dice hall?','सभा में अन्याय का विरोध करने वाला एकमात्र कौरव कौन था?','[{"key": "A", "en": "Duhshasana", "hi": "दुःशासन"}, {"key": "B", "en": "Vikarna", "hi": "विकर्ण"}, {"key": "C", "en": "Yuyutsu", "hi": "युयुत्सु"}, {"key": "D", "en": "Chitrasena", "hi": "चित्रसेन"}]','B');
INSERT INTO knowledge_quiz VALUES(2697,'Which Kaurava fought on the Pandavas’ side?','कौन सा कौरव पांडवों की ओर से लड़ा?','[{"key": "A", "en": "Vikarna", "hi": "विकर्ण"}, {"key": "B", "en": "Yuyutsu", "hi": "युयुत्सु"}, {"key": "C", "en": "Duhshasana", "hi": "दुःशासन"}, {"key": "D", "en": "Chitrasena", "hi": "चित्रसेन"}]','B');
INSERT INTO knowledge_quiz VALUES(2698,'What was the original name of the Ramayana as titled by Valmiki?','वाल्मीकि द्वारा रचित रामायण का मूल नाम क्या था?','[{"key": "A", "en": "Ram Charit", "hi": "राम चरित"}, {"key": "B", "en": "Paulatsya Vadha", "hi": "पौलस्त्य वध"}, {"key": "C", "en": "Sita Charitam", "hi": "सीता चरितम्"}, {"key": "D", "en": "Raghuvamsha", "hi": "रघुवंश"}]','B');
INSERT INTO knowledge_quiz VALUES(2699,'Why was Dhritarashtra blind?','धृतराष्ट्र अंधे क्यों थे?','[{"key": "A", "en": "Due to illness", "hi": "रोग के कारण"}, {"key": "B", "en": "Due to curse", "hi": "श्राप के कारण"}, {"key": "C", "en": "Blind from birth", "hi": "जन्म से अंधे"}, {"key": "D", "en": "In battle injury", "hi": "युद्ध चोट से"}]','C');
INSERT INTO knowledge_quiz VALUES(2700,'Who gave Dhritarashtra divine vision during the war?','युद्ध के दौरान धृतराष्ट्र को दिव्य दृष्टि किसने दी?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Narada", "hi": "नारद"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Bhishma", "hi": "भीष्म"}]','A');
INSERT INTO knowledge_quiz VALUES(2701,'Who narrated the events of the war to Dhritarashtra?','धृतराष्ट्र को युद्ध का वर्णन किसने सुनाया?','[{"key": "A", "en": "Sanjaya", "hi": "संजय"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Kripa", "hi": "कृप"}, {"key": "D", "en": "Vidura", "hi": "विदुर"}]','A');
