INSERT INTO knowledge_quiz VALUES(2748,'According to legend, the Nageshwarnath Temple in Ayodhya was established by which son of Lord Rama?','पौराणिक कथा के अनुसार, अयोध्या में नागेश्वरनाथ मंदिर की स्थापना भगवान राम के किस पुत्र ने की थी?','[{"key": "A", "en": "Luv", "hi": "लव"}, {"key": "B", "en": "Kush", "hi": "कुश"}, {"key": "C", "en": "Angad", "hi": "अंगद"}, {"key": "D", "en": "Bharat", "hi": "भरत"}]','B');
INSERT INTO knowledge_quiz VALUES(2749,'Which temple in Varanasi is famous for being built with red sandstone and is located near a sacred pond (Kund)?','वाराणसी का कौन सा मंदिर लाल बलुआ पत्थर से बने होने के लिए प्रसिद्ध है और एक पवित्र कुंड के पास स्थित है?','[{"key": "A", "en": "Sankat Mochan", "hi": "संकट मोचन"}, {"key": "B", "en": "Durga Kund Mandir", "hi": "दुर्गा कुंड मंदिर"}, {"key": "C", "en": "Tulsi Manas Mandir", "hi": "तुलसी मानस मंदिर"}, {"key": "D", "en": "Kaal Bhairav", "hi": "काल भैरव"}]','B');
INSERT INTO knowledge_quiz VALUES(2750,'Who became the Kaurava commander after Drona?','द्रोण के बाद कौरवों का सेनापति कौन बना?','[{"key": "A", "en": "Karna", "hi": "कर्ण"}, {"key": "B", "en": "Shalya", "hi": "शल्य"}, {"key": "C", "en": "Ashwatthama", "hi": "अश्वत्थामा"}, {"key": "D", "en": "Kripa", "hi": "कृप"}]','A');
INSERT INTO knowledge_quiz VALUES(2751,'On which day was Karna killed?','कर्ण का वध किस दिन हुआ?','[{"key": "A", "en": "14th day", "hi": "14वें दिन"}, {"key": "B", "en": "15th day", "hi": "15वें दिन"}, {"key": "C", "en": "16th day", "hi": "16वें दिन"}, {"key": "D", "en": "17th day", "hi": "17वें दिन"}]','D');
INSERT INTO knowledge_quiz VALUES(2752,'Who killed Karna?','कर्ण का वध किसने किया?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Yudhishthira", "hi": "युधिष्ठिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2753,'Who was the final commander of the Kauravas?','कौरवों का अंतिम सेनापति कौन था?','[{"key": "A", "en": "Shalya", "hi": "शल्य"}, {"key": "B", "en": "Ashwatthama", "hi": "अश्वत्थामा"}, {"key": "C", "en": "Kripa", "hi": "कृप"}, {"key": "D", "en": "Duryodhana", "hi": "दुर्योधन"}]','A');
INSERT INTO knowledge_quiz VALUES(2754,'Who killed Shalya?','शल्य का वध किसने किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Nakula", "hi": "नकुल"}, {"key": "C", "en": "Sahadeva", "hi": "सहदेव"}, {"key": "D", "en": "Bhima", "hi": "भीम"}]','C');
INSERT INTO knowledge_quiz VALUES(2755,'Who killed Duryodhana?','दुर्योधन का वध किसने किया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Sahadeva", "hi": "सहदेव"}]','B');
INSERT INTO knowledge_quiz VALUES(2756,'Ravana was an expert in playing which musical instrument?','रावण किस वाद्य यंत्र को बजाने में निपुण था?','[{"key": "A", "en": "Flute", "hi": "बांसुरी"}, {"key": "B", "en": "Veena", "hi": "वीणा"}, {"key": "C", "en": "Mridangam", "hi": "मृदंगम"}, {"key": "D", "en": "Damru", "hi": "डमरू"}]','B');
INSERT INTO knowledge_quiz VALUES(2757,'What was Bhishma''s original name?','भीष्म का मूल नाम क्या था?','[{"key": "A", "en": "Devavrata", "hi": "देवव्रत"}, {"key": "B", "en": "Gangeya", "hi": "गांगेय"}, {"key": "C", "en": "Partha", "hi": "पार्थ"}, {"key": "D", "en": "Kuru", "hi": "कुरु"}]','A');
INSERT INTO knowledge_quiz VALUES(2758,'Which king of the gods disguised himself as Sage Gautama to deceive Ahalya?','देवताओं के किस राजा ने अहल्या को छलने के लिए ऋषि गौतम का वेश धारण किया था?','[{"key": "A", "en": "Varuna", "hi": "वरुण"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Vayu", "hi": "वायु"}]','B');
INSERT INTO knowledge_quiz VALUES(2759,'Which vow made Devavrata known as Bhishma?','किस प्रतिज्ञा के कारण देवव्रत भीष्म कहलाए?','[{"key": "A", "en": "Truth vow", "hi": "सत्य प्रतिज्ञा"}, {"key": "B", "en": "Celibacy vow", "hi": "ब्रह्मचर्य प्रतिज्ञा"}, {"key": "C", "en": "War vow", "hi": "युद्ध प्रतिज्ञा"}, {"key": "D", "en": "Exile vow", "hi": "वनवास प्रतिज्ञा"}]','B');
INSERT INTO knowledge_quiz VALUES(2760,'Who granted Bhishma the boon of Ichchha Mrityu?','भीष्म को इच्छामृत्यु का वरदान किसने दिया?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "C", "en": "Shantanu", "hi": "शंतनु"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','C');
INSERT INTO knowledge_quiz VALUES(2761,'Who was the wife of King Shantanu?','राजा शंतनु की पत्नी कौन थीं?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Satyavati", "hi": "सत्यवती"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Kunti", "hi": "कुंती"}]','C');
INSERT INTO knowledge_quiz VALUES(2762,'Who was the father of Satyavati?','सत्यवती के पिता कौन थे?','[{"key": "A", "en": "Dasharaja", "hi": "दाशराज"}, {"key": "B", "en": "Parashara", "hi": "पराशर"}, {"key": "C", "en": "Vasudeva", "hi": "वसुदेव"}, {"key": "D", "en": "Yayati", "hi": "ययाति"}]','A');
INSERT INTO knowledge_quiz VALUES(2763,'Who was the son of Satyavati and Parashara?','सत्यवती और पराशर के पुत्र कौन थे?','[{"key": "A", "en": "Bhishma", "hi": "भीष्म"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Chitrangada", "hi": "चित्रांगद"}, {"key": "D", "en": "Vichitravirya", "hi": "विचित्रवीर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2764,'The Gadkalika Temple in Ujjain is associated with which famous Sanskrit poet and dramatist?','उज्जैन का गढ़कालिका मंदिर किस प्रसिद्ध संस्कृत कवि और नाटककार से जुड़ा है?','[{"key": "A", "en": "Tulsidas", "hi": "तुलसीदास"}, {"key": "B", "en": "Kalidasa", "hi": "कालिदास"}, {"key": "C", "en": "Bhartruhari", "hi": "भर्तृहरि"}, {"key": "D", "en": "Valmiki", "hi": "वाल्मीकि"}]','B');
INSERT INTO knowledge_quiz VALUES(2765,'Who wrote down the Mahabharata as Vyasa dictated?','व्यास के कथन अनुसार महाभारत किसने लिखी?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "C", "en": "Ganesha", "hi": "गणेश"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','C');
INSERT INTO knowledge_quiz VALUES(2766,'Who was the blind king of Hastinapura?','हस्तिनापुर के अंधे राजा कौन थे?','[{"key": "A", "en": "Pandu", "hi": "पांडु"}, {"key": "B", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}, {"key": "C", "en": "Shantanu", "hi": "शंतनु"}, {"key": "D", "en": "Yudhishthira", "hi": "युधिष्ठिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2767,'Who was the wife of Dhritarashtra?','धृतराष्ट्र की पत्नी कौन थीं?','[{"key": "A", "en": "Kunti", "hi": "कुंती"}, {"key": "B", "en": "Gandhari", "hi": "गांधारी"}, {"key": "C", "en": "Madri", "hi": "माद्री"}, {"key": "D", "en": "Satyavati", "hi": "सत्यवती"}]','B');
INSERT INTO knowledge_quiz VALUES(2768,'Why did Gandhari blindfold herself?','गांधारी ने अपनी आंखों पर पट्टी क्यों बांधी?','[{"key": "A", "en": "Out of devotion to her blind husband", "hi": "अपने अंधे पति के प्रति समर्पण से"}, {"key": "B", "en": "Due to curse", "hi": "श्राप के कारण"}, {"key": "C", "en": "For penance", "hi": "तपस्या के लिए"}, {"key": "D", "en": "Due to war", "hi": "युद्ध के कारण"}]','A');
INSERT INTO knowledge_quiz VALUES(2769,'How many sons did Gandhari have?','गांधारी के कितने पुत्र थे?','[{"key": "A", "en": "50", "hi": "50"}, {"key": "B", "en": "99", "hi": "99"}, {"key": "C", "en": "100", "hi": "100"}, {"key": "D", "en": "101", "hi": "101"}]','C');
INSERT INTO knowledge_quiz VALUES(2770,'Who was the eldest Kaurava?','सबसे बड़े कौरव कौन थे?','[{"key": "A", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "B", "en": "Dushasana", "hi": "दुःशासन"}, {"key": "C", "en": "Vikarna", "hi": "विकर्ण"}, {"key": "D", "en": "Yuyutsu", "hi": "युयुत्सु"}]','A');
INSERT INTO knowledge_quiz VALUES(2771,'Who was the second Kaurava after Duryodhana?','दुर्योधन के बाद दूसरा कौरव कौन था?','[{"key": "A", "en": "Vikarna", "hi": "विकर्ण"}, {"key": "B", "en": "Dushasana", "hi": "दुःशासन"}, {"key": "C", "en": "Yuyutsu", "hi": "युयुत्सु"}, {"key": "D", "en": "Chitrasena", "hi": "चित्रसेन"}]','B');
INSERT INTO knowledge_quiz VALUES(2772,'Who among the Kauravas opposed the disrobing of Draupadi?','द्रौपदी के चीरहरण का विरोध किस कौरव ने किया?','[{"key": "A", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "B", "en": "Dushasana", "hi": "दुःशासन"}, {"key": "C", "en": "Vikarna", "hi": "विकर्ण"}, {"key": "D", "en": "Shakuni", "hi": "शकुनि"}]','C');
INSERT INTO knowledge_quiz VALUES(2773,'Who was the illegitimate son of Dhritarashtra?','धृतराष्ट्र का अवैध पुत्र कौन था?','[{"key": "A", "en": "Vikarna", "hi": "विकर्ण"}, {"key": "B", "en": "Yuyutsu", "hi": "युयुत्सु"}, {"key": "C", "en": "Dushasana", "hi": "दुःशासन"}, {"key": "D", "en": "Chitrasena", "hi": "चित्रसेन"}]','B');
INSERT INTO knowledge_quiz VALUES(2774,'Who was the king of Hastinapura before Pandu?','पांडु से पहले हस्तिनापुर के राजा कौन थे?','[{"key": "A", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}, {"key": "B", "en": "Vichitravirya", "hi": "विचित्रवीर्य"}, {"key": "C", "en": "Chitrangada", "hi": "चित्रांगद"}, {"key": "D", "en": "Shantanu", "hi": "शंतनु"}]','B');
INSERT INTO knowledge_quiz VALUES(2775,'Who was the wife of King Pandu?','राजा पांडु की पत्नी कौन थीं?','[{"key": "A", "en": "Gandhari", "hi": "गांधारी"}, {"key": "B", "en": "Kunti", "hi": "कुंती"}, {"key": "C", "en": "Madri", "hi": "माद्री"}, {"key": "D", "en": "Both B and C", "hi": "B और C दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(2776,'Why did Pandu renounce the throne?','पांडु ने राजसिंहासन क्यों त्यागा?','[{"key": "A", "en": "Due to illness", "hi": "बीमारी के कारण"}, {"key": "B", "en": "Due to a curse", "hi": "श्राप के कारण"}, {"key": "C", "en": "Due to war", "hi": "युद्ध के कारण"}, {"key": "D", "en": "Due to age", "hi": "आयु के कारण"}]','B');
INSERT INTO knowledge_quiz VALUES(2777,'Who cursed King Pandu?','राजा पांडु को किसने श्राप दिया?','[{"key": "A", "en": "Kindama", "hi": "किंदम"}, {"key": "B", "en": "Durvasa", "hi": "दुर्वासा"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Narada", "hi": "नारद"}]','A');
INSERT INTO knowledge_quiz VALUES(2778,'Which sage gave Kunti the boon to invoke gods?','कुंती को देवताओं का आह्वान करने का वरदान किस ऋषि ने दिया?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Durvasa", "hi": "दुर्वासा"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Parashara", "hi": "पराशर"}]','B');
INSERT INTO knowledge_quiz VALUES(2779,'Which god blessed Kunti with Yudhishthira?','कुंती को युधिष्ठिर किस देवता से प्राप्त हुए?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Vayu", "hi": "वायु"}, {"key": "C", "en": "Dharma", "hi": "धर्म"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','C');
INSERT INTO knowledge_quiz VALUES(2780,'Which god blessed Kunti with Bhima?','कुंती को भीम किस देवता से प्राप्त हुए?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Vayu", "hi": "वायु"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','B');
INSERT INTO knowledge_quiz VALUES(2781,'Which god blessed Kunti with Arjuna?','कुंती को अर्जुन किस देवता से प्राप्त हुए?','[{"key": "A", "en": "Surya", "hi": "सूर्य"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Vayu", "hi": "वायु"}]','B');
INSERT INTO knowledge_quiz VALUES(2782,'Who were the twin sons of Madri?','माद्री के जुड़वां पुत्र कौन थे?','[{"key": "A", "en": "Nakula and Sahadeva", "hi": "नकुल और सहदेव"}, {"key": "B", "en": "Bhima and Arjuna", "hi": "भीम और अर्जुन"}, {"key": "C", "en": "Yudhishthira and Bhima", "hi": "युधिष्ठिर और भीम"}, {"key": "D", "en": "Arjuna and Nakula", "hi": "अर्जुन और नकुल"}]','A');
INSERT INTO knowledge_quiz VALUES(2783,'Which gods blessed Madri with her sons?','माद्री को पुत्र किस देवताओं से प्राप्त हुए?','[{"key": "A", "en": "Indra and Vayu", "hi": "इंद्र और वायु"}, {"key": "B", "en": "Ashwini Kumaras", "hi": "अश्विनी कुमार"}, {"key": "C", "en": "Surya and Agni", "hi": "सूर्य और अग्नि"}, {"key": "D", "en": "Varuna and Yama", "hi": "वरुण और यम"}]','B');
INSERT INTO knowledge_quiz VALUES(2784,'What were the five sons of Pandu collectively called?','पांडु के पाँचों पुत्र सामूहिक रूप से क्या कहलाए?','[{"key": "A", "en": "Kauravas", "hi": "कौरव"}, {"key": "B", "en": "Pandavas", "hi": "पांडव"}, {"key": "C", "en": "Kuravas", "hi": "कुरुव"}, {"key": "D", "en": "Bharatas", "hi": "भरत"}]','B');
INSERT INTO knowledge_quiz VALUES(2785,'Who was the eldest among the Pandavas?','पांडवों में सबसे बड़े कौन थे?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "D", "en": "Nakula", "hi": "नकुल"}]','C');
INSERT INTO knowledge_quiz VALUES(2786,'Who was the youngest Pandava?','सबसे छोटे पांडव कौन थे?','[{"key": "A", "en": "Nakula", "hi": "नकुल"}, {"key": "B", "en": "Sahadeva", "hi": "सहदेव"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Bhima", "hi": "भीम"}]','B');
INSERT INTO knowledge_quiz VALUES(2787,'Who trained the Pandavas and Kauravas in warfare?','पांडवों और कौरवों को युद्ध विद्या किसने सिखाई?','[{"key": "A", "en": "Kripacharya", "hi": "कृपाचार्य"}, {"key": "B", "en": "Dronacharya", "hi": "द्रोणाचार्य"}, {"key": "C", "en": "Bhishma", "hi": "भीष्म"}, {"key": "D", "en": "Parashara", "hi": "पराशर"}]','B');
INSERT INTO knowledge_quiz VALUES(2788,'The Tulsi Manas Temple is unique because its walls are inscribed with verses from which epic?','तुलसी मानस मंदिर अद्वितीय है क्योंकि इसकी दीवारों पर किस महाकाव्य की चौपाइयां और छंद अंकित हैं?','[{"key": "A", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "B", "en": "Ramcharitmanas", "hi": "रामचरितमानस"}, {"key": "C", "en": "Bhagavad Gita", "hi": "भगवद गीता"}, {"key": "D", "en": "Skanda Purana", "hi": "स्कंद पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(2789,'Who was Ekalavya devoted to as his guru?','एकलव्य किसे अपना गुरु मानते थे?','[{"key": "A", "en": "Kripacharya", "hi": "कृपाचार्य"}, {"key": "B", "en": "Bhishma", "hi": "भीष्म"}, {"key": "C", "en": "Dronacharya", "hi": "द्रोणाचार्य"}, {"key": "D", "en": "Parashara", "hi": "पराशर"}]','C');
INSERT INTO knowledge_quiz VALUES(2790,'The temple of Kalpeshwar is situated in which valley?','कल्पेश्वर का मंदिर किस घाटी में स्थित है?','[{"key": "A", "en": "Urgam Valley", "hi": "उर्गम घाटी"}, {"key": "B", "en": "Neeti Valley", "hi": "नीति घाटी"}, {"key": "C", "en": "Mana Valley", "hi": "माणा घाटी"}, {"key": "D", "en": "Johar Valley", "hi": "जोहार घाटी"}]','A');
INSERT INTO knowledge_quiz VALUES(2791,'Who was Karna''s biological mother?','कर्ण की जैविक माता कौन थीं?','[{"key": "A", "en": "Madri", "hi": "माद्री"}, {"key": "B", "en": "Gandhari", "hi": "गांधारी"}, {"key": "C", "en": "Kunti", "hi": "कुंती"}, {"key": "D", "en": "Satyavati", "hi": "सत्यवती"}]','C');
INSERT INTO knowledge_quiz VALUES(2792,'Which god was Karna the son of?','कर्ण किस देवता के पुत्र थे?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Surya", "hi": "सूर्य"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Vayu", "hi": "वायु"}]','B');
INSERT INTO knowledge_quiz VALUES(2793,'Who raised Karna after his birth?','कर्ण का पालन-पोषण किसने किया?','[{"key": "A", "en": "Adhiratha and Radha", "hi": "अधिरथ और राधा"}, {"key": "B", "en": "Dhritarashtra and Gandhari", "hi": "धृतराष्ट्र और गांधारी"}, {"key": "C", "en": "Pandu and Kunti", "hi": "पांडु और कुंती"}, {"key": "D", "en": "Shantanu and Ganga", "hi": "शंतनु और गंगा"}]','A');
INSERT INTO knowledge_quiz VALUES(2794,'What was Karna''s caste by upbringing?','पालन-पोषण के अनुसार कर्ण किस जाति के माने गए?','[{"key": "A", "en": "Kshatriya", "hi": "क्षत्रिय"}, {"key": "B", "en": "Brahmin", "hi": "ब्राह्मण"}, {"key": "C", "en": "Vaishya", "hi": "वैश्य"}, {"key": "D", "en": "Shudra (Suta)", "hi": "शूद्र (सूत)"}]','D');
INSERT INTO knowledge_quiz VALUES(2795,'Who made Karna the king of Anga?','कर्ण को अंग देश का राजा किसने बनाया?','[{"key": "A", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}, {"key": "B", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "C", "en": "Bhishma", "hi": "भीष्म"}, {"key": "D", "en": "Shakuni", "hi": "शकुनि"}]','B');
INSERT INTO knowledge_quiz VALUES(2796,'Which divine armor did Karna possess at birth?','कर्ण के पास जन्म से कौन सा दिव्य कवच था?','[{"key": "A", "en": "Vajra", "hi": "वज्र"}, {"key": "B", "en": "Divine bow", "hi": "दिव्य धनुष"}, {"key": "C", "en": "Kavacha and Kundala", "hi": "कवच और कुंडल"}, {"key": "D", "en": "Sudarshan Chakra", "hi": "सुदर्शन चक्र"}]','C');
INSERT INTO knowledge_quiz VALUES(2797,'To whom did Karna donate his Kavacha and Kundala?','कर्ण ने अपना कवच और कुंडल किसे दान किया?','[{"key": "A", "en": "Surya", "hi": "सूर्य"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','B');
INSERT INTO knowledge_quiz VALUES(2798,'Which temple in Tezpur is associated with the legend of the battle between Lord Krishna and Lord Shiva (Bana-Asura)?','तेजपुर का कौन सा मंदिर भगवान कृष्ण और भगवान शिव (बाणासुर) के बीच युद्ध की कथा से जुड़ा है?','[{"key": "A", "en": "Maha Bhairav Temple", "hi": "महा भैरव मंदिर"}, {"key": "B", "en": "Da Parbatia", "hi": "दा परबतिया"}, {"key": "C", "en": "Agnigarh", "hi": "अग्निगढ़"}, {"key": "D", "en": "Bhairabi Temple", "hi": "भैरवी मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2799,'The Umananda Temple is located on the Peacock Island in the middle of which river?','उमानंद मंदिर किस नदी के बीच में मयूर द्वीप (Peacock Island) पर स्थित है?','[{"key": "A", "en": "Barak", "hi": "बराक"}, {"key": "B", "en": "Brahmaputra", "hi": "ब्रह्मपुत्र"}, {"key": "C", "en": "Manas", "hi": "मानस"}, {"key": "D", "en": "Subansiri", "hi": "सुबनसिरी"}]','B');
INSERT INTO knowledge_quiz VALUES(2800,'In which epic does the story of Karna appear?','कर्ण की कथा किस महाकाव्य में आती है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Harivamsa", "hi": "हरिवंश"}, {"key": "D", "en": "Puranas", "hi": "पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(2801,'Which temple in Porbandar is the only temple in the world dedicated to Lord Krishna''s childhood friend?','पोरबंदर का कौन सा मंदिर दुनिया का एकमात्र मंदिर है जो भगवान कृष्ण के बचपन के मित्र को समर्पित है?','[{"key": "A", "en": "Sandipani Temple", "hi": "सांदीपनि मंदिर"}, {"key": "B", "en": "Sudama Temple", "hi": "सुदामा मंदिर"}, {"key": "C", "en": "Kirti Mandir", "hi": "कीर्ति मंदिर"}, {"key": "D", "en": "Dwarkadhish Temple", "hi": "द्वारकाधीश मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2802,'How many chapters are there in the Bhagavad Gita?','भगवद्गीता में कितने अध्याय हैं?','[{"key": "A", "en": "12", "hi": "12"}, {"key": "B", "en": "15", "hi": "15"}, {"key": "C", "en": "18", "hi": "18"}, {"key": "D", "en": "20", "hi": "20"}]','C');
INSERT INTO knowledge_quiz VALUES(2803,'Who narrated the Bhagavad Gita?','भगवद्गीता का उपदेश किसने दिया?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Vyasa", "hi": "व्यास"}, {"key": "D", "en": "Bhishma", "hi": "भीष्म"}]','B');
INSERT INTO knowledge_quiz VALUES(2804,'Where was the Bhagavad Gita preached?','भगवद्गीता का उपदेश कहाँ दिया गया?','[{"key": "A", "en": "Ayodhya", "hi": "अयोध्या"}, {"key": "B", "en": "Kurukshetra", "hi": "कुरुक्षेत्र"}, {"key": "C", "en": "Mathura", "hi": "मथुरा"}, {"key": "D", "en": "Dwaraka", "hi": "द्वारका"}]','B');
INSERT INTO knowledge_quiz VALUES(2805,'Which Veda is primarily associated with rituals?','कौन सा वेद मुख्य रूप से यज्ञ-कर्म से संबंधित है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "C", "en": "Samaveda", "hi": "सामवेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','B');
INSERT INTO knowledge_quiz VALUES(2806,'How many Vedas are there in Hinduism?','हिंदू धर्म में कितने वेद हैं?','[{"key": "A", "en": "2", "hi": "2"}, {"key": "B", "en": "3", "hi": "3"}, {"key": "C", "en": "4", "hi": "4"}, {"key": "D", "en": "5", "hi": "5"}]','C');
INSERT INTO knowledge_quiz VALUES(2807,'Which Veda is known for musical chants?','संगीतात्मक मंत्रों के लिए कौन सा वेद प्रसिद्ध है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "C", "en": "Samaveda", "hi": "सामवेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','C');
INSERT INTO knowledge_quiz VALUES(2808,'Which Veda contains hymns to various deities?','किस वेद में देवताओं की स्तुतियाँ हैं?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Samaveda", "hi": "सामवेद"}, {"key": "C", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','A');
INSERT INTO knowledge_quiz VALUES(2809,'Which Veda deals with daily life and social customs?','कौन सा वेद दैनिक जीवन और सामाजिक विषयों से संबंधित है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Yajurveda", "hi": "यजुर्वेद"}, {"key": "C", "en": "Samaveda", "hi": "सामवेद"}, {"key": "D", "en": "Atharvaveda", "hi": "अथर्ववेद"}]','D');
INSERT INTO knowledge_quiz VALUES(2810,'Which Upanishad contains the Mahavakya ''Tat Tvam Asi''?','‘तत्त्वमसि’ महावाक्य किस उपनिषद में है?','[{"key": "A", "en": "Isha Upanishad", "hi": "ईश उपनिषद"}, {"key": "B", "en": "Kena Upanishad", "hi": "केन उपनिषद"}, {"key": "C", "en": "Chandogya Upanishad", "hi": "छांदोग्य उपनिषद"}, {"key": "D", "en": "Mundaka Upanishad", "hi": "मुण्डक उपनिषद"}]','C');
INSERT INTO knowledge_quiz VALUES(2811,'Which river is considered the most sacred in Hinduism?','हिंदू धर्म में सबसे पवित्र नदी कौन सी मानी जाती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','B');
INSERT INTO knowledge_quiz VALUES(2812,'The Hatkeshwar Mahadev Temple, famous for its intricate carvings, is the family deity of the Nagar Brahmins. Where is it?','नक्काशी के लिए प्रसिद्ध हाटकेश्वर महादेव मंदिर नागर ब्राह्मणों के कुलदेवता हैं। यह कहाँ स्थित है?','[{"key": "A", "en": "Vadnagar", "hi": "वडनगर"}, {"key": "B", "en": "Patan", "hi": "पाटन"}, {"key": "C", "en": "Sidhpur", "hi": "सिद्धपुर"}, {"key": "D", "en": "Ahmedabad", "hi": "अहमदाबाद"}]','A');
INSERT INTO knowledge_quiz VALUES(2813,'Which Jyotirlinga is located in Varanasi?','वाराणसी में कौन सा ज्योतिर्लिंग स्थित है?','[{"key": "A", "en": "Somnath", "hi": "सोमनाथ"}, {"key": "B", "en": "Mahakaleshwar", "hi": "महाकालेश्वर"}, {"key": "C", "en": "Kashi Vishwanath", "hi": "काशी विश्वनाथ"}, {"key": "D", "en": "Baidyanath", "hi": "वैद्यनाथ"}]','C');
INSERT INTO knowledge_quiz VALUES(2814,'How many Jyotirlingas are there in Hinduism?','हिंदू धर्म में कितने ज्योतिर्लिंग हैं?','[{"key": "A", "en": "10", "hi": "10"}, {"key": "B", "en": "11", "hi": "11"}, {"key": "C", "en": "12", "hi": "12"}, {"key": "D", "en": "13", "hi": "13"}]','C');
INSERT INTO knowledge_quiz VALUES(2815,'Which famous temple in Karnataka is situated at the confluence of the rivers Tunga and Bhadra?','कर्नाटक का कौन सा प्रसिद्ध मंदिर तुंगा और भद्रा नदियों के संगम पर स्थित है?','[{"key": "A", "en": "Kudli Sangameshwara", "hi": "कुडली संगमेश्वर"}, {"key": "B", "en": "Hornadu Annapoorneshwari", "hi": "होरनाडु अन्नपूर्णेश्वरी"}, {"key": "C", "en": "Sigandur Chowdeshwari", "hi": "सिगांदुर चौडेश्वरी"}, {"key": "D", "en": "Kalaseshwara", "hi": "कलसेश्वर"}]','A');
INSERT INTO knowledge_quiz VALUES(2816,'Which pilgrimage is known as the Char Dham Yatra?','चार धाम यात्रा में कौन-कौन से धाम शामिल हैं?','[{"key": "A", "en": "Badrinath, Dwarka, Puri, Rameswaram", "hi": "बद्रीनाथ, द्वारका, पुरी, रामेश्वरम"}, {"key": "B", "en": "Kedarnath, Badrinath, Gangotri, Yamunotri", "hi": "केदारनाथ, बद्रीनाथ, गंगोत्री, यमुनोत्री"}, {"key": "C", "en": "Vaishno Devi, Amarnath, Kedarnath, Badrinath", "hi": "वैष्णो देवी, अमरनाथ, केदारनाथ, बद्रीनाथ"}, {"key": "D", "en": "Somnath, Dwarka, Ujjain, Nashik", "hi": "सोमनाथ, द्वारका, उज्जैन, नासिक"}]','A');
INSERT INTO knowledge_quiz VALUES(2817,'Which epic narrates the story of Lord Rama?','भगवान राम की कथा किस महाकाव्य में है?','[{"key": "A", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "B", "en": "Ramayana", "hi": "रामायण"}, {"key": "C", "en": "Harivamsa", "hi": "हरिवंश"}, {"key": "D", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(2818,'What is the name of the grand corridor project recently inaugurated at the Mahakaleshwar temple complex?','हाल ही में महाकालेश्वर मंदिर परिसर में उद्घाटित भव्य कॉरिडोर परियोजना का नाम क्या है?','[{"key": "A", "en": "Mahakal Lok", "hi": "महाकाल लोक"}, {"key": "B", "en": "Shiva Shrishti", "hi": "शिव सृष्टि"}, {"key": "C", "en": "Kashi Vishwanath Corridor", "hi": "काशी विश्वनाथ कॉरिडोर"}, {"key": "D", "en": "Dev Lok", "hi": "देव लोक"}]','A');
INSERT INTO knowledge_quiz VALUES(2819,'Which temple is located at the birthplace of Lord Rama?','भगवान राम के जन्मस्थान पर कौन सा मंदिर स्थित है?','[{"key": "A", "en": "Ayodhya Ram Mandir", "hi": "अयोध्या राम मंदिर"}, {"key": "B", "en": "Kashi Vishwanath", "hi": "काशी विश्वनाथ"}, {"key": "C", "en": "Somnath Temple", "hi": "सोमनाथ मंदिर"}, {"key": "D", "en": "Dwarkadhish Temple", "hi": "द्वारकाधीश मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2820,'Which Purana is dedicated to Lord Vishnu?','कौन सा पुराण भगवान विष्णु को समर्पित है?','[{"key": "A", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "D", "en": "Markandeya Purana", "hi": "मार्कण्डेय पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(2821,'Which temple is known as the Golden Temple?','स्वर्ण मंदिर किसे कहा जाता है?','[{"key": "A", "en": "Somnath Temple", "hi": "सोमनाथ मंदिर"}, {"key": "B", "en": "Meenakshi Temple", "hi": "मीनाक्षी मंदिर"}, {"key": "C", "en": "Harmandir Sahib", "hi": "हरमंदिर साहिब"}, {"key": "D", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}]','C');
INSERT INTO knowledge_quiz VALUES(2822,'In which city is the Golden Temple located?','स्वर्ण मंदिर किस शहर में स्थित है?','[{"key": "A", "en": "Delhi", "hi": "दिल्ली"}, {"key": "B", "en": "Amritsar", "hi": "अमृतसर"}, {"key": "C", "en": "Chandigarh", "hi": "चंडीगढ़"}, {"key": "D", "en": "Patiala", "hi": "पटियाला"}]','B');
INSERT INTO knowledge_quiz VALUES(2823,'Which temple in Tamil Nadu is famous for its towering gopurams?','तमिलनाडु का कौन सा मंदिर अपने ऊँचे गोपुरमों के लिए प्रसिद्ध है?','[{"key": "A", "en": "Ramanathaswamy Temple", "hi": "रामनाथस्वामी मंदिर"}, {"key": "B", "en": "Meenakshi Amman Temple", "hi": "मीनाक्षी अम्मन मंदिर"}, {"key": "C", "en": "Brihadeeswarar Temple", "hi": "बृहदीश्वर मंदिर"}, {"key": "D", "en": "Chidambaram Temple", "hi": "चिदंबरम मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2824,'The ''Right-sided trunk'' Ganesha is also known by which name, representing a more powerful and strict form?','दाईं ओर सूंड वाले गणेश जी को किस नाम से भी जाना जाता है, जो उनके अधिक शक्तिशाली और कठोर रूप का प्रतीक है?','[{"key": "A", "en": "Vighnaharta", "hi": "विघ्नहर्ता"}, {"key": "B", "en": "Ekdant", "hi": "एकदंत"}, {"key": "C", "en": "Navasacha Ganapati", "hi": "नवसाचा गणपति"}, {"key": "D", "en": "Lalbaugcha Raja", "hi": "लालबागचा राजा"}]','C');
INSERT INTO knowledge_quiz VALUES(2825,'Which temple is one of the twelve Jyotirlingas located in Gujarat?','गुजरात में स्थित बारह ज्योतिर्लिंगों में से कौन सा है?','[{"key": "A", "en": "Somnath Temple", "hi": "सोमनाथ मंदिर"}, {"key": "B", "en": "Nageshwar Temple", "hi": "नागेश्वर मंदिर"}, {"key": "C", "en": "Baidyanath Temple", "hi": "वैद्यनाथ मंदिर"}, {"key": "D", "en": "Mahakaleshwar Temple", "hi": "महाकालेश्वर मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2826,'Which pilgrimage town hosts the Kumbh Mela at the confluence of rivers?','किस तीर्थ नगर में नदियों के संगम पर कुंभ मेला लगता है?','[{"key": "A", "en": "Haridwar", "hi": "हरिद्वार"}, {"key": "B", "en": "Prayagraj", "hi": "प्रयागराज"}, {"key": "C", "en": "Ujjain", "hi": "उज्जैन"}, {"key": "D", "en": "Nashik", "hi": "नासिक"}]','B');
INSERT INTO knowledge_quiz VALUES(2827,'Which temple in Jaipur is famous because the idol of Krishna was brought here from Vrindavan to protect it from Mughal Emperor Aurangzeb?','जयपुर का कौन सा मंदिर प्रसिद्ध है क्योंकि मुगल सम्राट औरंगजेब से बचाने के लिए कृष्ण की मूर्ति को वृंदावन से यहाँ लाया गया था?','[{"key": "A", "en": "Birla Mandir", "hi": "बिड़ला मंदिर"}, {"key": "B", "en": "Govind Dev Ji Temple", "hi": "गोविंद देव जी मंदिर"}, {"key": "C", "en": "Moti Dungri Ganesh", "hi": "मोती डूंगरी गणेश"}, {"key": "D", "en": "Galta Ji", "hi": "गलता जी"}]','B');
INSERT INTO knowledge_quiz VALUES(2828,'Which temple is famous for the largest corridor in the world?','दुनिया के सबसे लंबे कॉरिडोर के लिए कौन सा मंदिर प्रसिद्ध है?','[{"key": "A", "en": "Ramanathaswamy Temple", "hi": "रामनाथस्वामी मंदिर"}, {"key": "B", "en": "Meenakshi Temple", "hi": "मीनाक्षी मंदिर"}, {"key": "C", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}, {"key": "D", "en": "Kashi Vishwanath Temple", "hi": "काशी विश्वनाथ मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2829,'In the Sree Padmanabhaswamy Temple, Lord Vishnu is depicted in which posture?','श्री पद्मनाभस्वामी मंदिर में भगवान विष्णु को किस मुद्रा में दर्शाया गया है?','[{"key": "A", "en": "Standing (Sthanaka)", "hi": "खड़ी मुद्रा"}, {"key": "B", "en": "Sitting (Asana)", "hi": "बैठी हुई मुद्रा"}, {"key": "C", "en": "Anantashayanam (Reclining)", "hi": "अनंतशयनम (शयन मुद्रा)"}, {"key": "D", "en": "Dancing", "hi": "नृत्य मुद्रा"}]','C');
INSERT INTO knowledge_quiz VALUES(2830,'Which temple in Odisha is famous for the Rath Yatra?','ओडिशा का कौन सा मंदिर रथ यात्रा के लिए प्रसिद्ध है?','[{"key": "A", "en": "Konark Sun Temple", "hi": "कोणार्क सूर्य मंदिर"}, {"key": "B", "en": "Lingaraja Temple", "hi": "लिंगराज मंदिर"}, {"key": "C", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}, {"key": "D", "en": "Mukteshwar Temple", "hi": "मुक्तेश्वर मंदिर"}]','C');
INSERT INTO knowledge_quiz VALUES(2831,'Which temple is also known as the ''Black Pagoda''?','‘ब्लैक पैगोडा’ के नाम से कौन सा मंदिर जाना जाता है?','[{"key": "A", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}, {"key": "B", "en": "Konark Sun Temple", "hi": "कोणार्क सूर्य मंदिर"}, {"key": "C", "en": "Brihadeeswarar Temple", "hi": "बृहदीश्वर मंदिर"}, {"key": "D", "en": "Somnath Temple", "hi": "सोमनाथ मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2832,'Which city is known as the gateway to the Char Dham Yatra?','चार धाम यात्रा का प्रवेश द्वार किस शहर को कहा जाता है?','[{"key": "A", "en": "Rishikesh", "hi": "ऋषिकेश"}, {"key": "B", "en": "Haridwar", "hi": "हरिद्वार"}, {"key": "C", "en": "Dehradun", "hi": "देहरादून"}, {"key": "D", "en": "Joshimath", "hi": "जोशीमठ"}]','B');
INSERT INTO knowledge_quiz VALUES(2833,'Which temple in Kerala is famous for its hidden treasures?','केरल का कौन सा मंदिर अपने गुप्त खजाने के लिए प्रसिद्ध है?','[{"key": "A", "en": "Guruvayur Temple", "hi": "गुरुवायुर मंदिर"}, {"key": "B", "en": "Sabarimala Temple", "hi": "सबरीमला मंदिर"}, {"key": "C", "en": "Padmanabhaswamy Temple", "hi": "पद्मनाभस्वामी मंदिर"}, {"key": "D", "en": "Vadakkunnathan Temple", "hi": "वडक्कुनाथन मंदिर"}]','C');
INSERT INTO knowledge_quiz VALUES(2834,'Which holy town is associated with Lord Krishna''s childhood?','भगवान कृष्ण के बाल्यकाल से कौन सा पवित्र नगर जुड़ा है?','[{"key": "A", "en": "Mathura", "hi": "मथुरा"}, {"key": "B", "en": "Dwarka", "hi": "द्वारका"}, {"key": "C", "en": "Vrindavan", "hi": "वृंदावन"}, {"key": "D", "en": "Gokul", "hi": "गोकुल"}]','A');
INSERT INTO knowledge_quiz VALUES(2835,'Which temple is dedicated to Lord Krishna in Dwarka?','द्वारका में भगवान कृष्ण को समर्पित कौन सा मंदिर है?','[{"key": "A", "en": "Dwarkadhish Temple", "hi": "द्वारकाधीश मंदिर"}, {"key": "B", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}, {"key": "C", "en": "Guruvayur Temple", "hi": "गुरुवायुर मंदिर"}, {"key": "D", "en": "Udupi Krishna Temple", "hi": "उडुपी कृष्ण मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2836,'Which city hosts the famous Mahakaleshwar Jyotirlinga?','महाकालेश्वर ज्योतिर्लिंग किस शहर में स्थित है?','[{"key": "A", "en": "Ujjain", "hi": "उज्जैन"}, {"key": "B", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "C", "en": "Nashik", "hi": "नासिक"}, {"key": "D", "en": "Haridwar", "hi": "हरिद्वार"}]','A');
INSERT INTO knowledge_quiz VALUES(2837,'Which religious place is associated with the Amarnath Yatra?','अमरनाथ यात्रा किस धार्मिक स्थल से संबंधित है?','[{"key": "A", "en": "Kedarnath Cave", "hi": "केदारनाथ गुफा"}, {"key": "B", "en": "Amarnath Cave", "hi": "अमरनाथ गुफा"}, {"key": "C", "en": "Vaishno Devi Cave", "hi": "वैष्णो देवी गुफा"}, {"key": "D", "en": "Badri Cave", "hi": "बद्री गुफा"}]','B');
INSERT INTO knowledge_quiz VALUES(2838,'Which Shakti Peetha is located in West Bengal?','पश्चिम बंगाल में कौन सा शक्ति पीठ स्थित है?','[{"key": "A", "en": "Kamakhya", "hi": "कामाख्या"}, {"key": "B", "en": "Kalighat", "hi": "कालीघाट"}, {"key": "C", "en": "Vaishno Devi", "hi": "वैष्णो देवी"}, {"key": "D", "en": "Ambaji", "hi": "अंबाजी"}]','B');
INSERT INTO knowledge_quiz VALUES(2839,'Which temple town is famous for the Ganga Aarti?','गंगा आरती के लिए कौन सा तीर्थ नगर प्रसिद्ध है?','[{"key": "A", "en": "Haridwar", "hi": "हरिद्वार"}, {"key": "B", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "C", "en": "Rishikesh", "hi": "ऋषिकेश"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2840,'Which Jain pilgrimage site is located on Mount Shatrunjaya?','माउंट शत्रुंजय पर कौन सा जैन तीर्थ स्थित है?','[{"key": "A", "en": "Shravanabelagola", "hi": "श्रवणबेलगोला"}, {"key": "B", "en": "Palitana", "hi": "पालीताना"}, {"key": "C", "en": "Girnar", "hi": "गिरनार"}, {"key": "D", "en": "Dilwara", "hi": "दिलवाड़ा"}]','B');
INSERT INTO knowledge_quiz VALUES(2841,'Which temple is dedicated to Goddess Kamakhya?','देवी कामाख्या को समर्पित कौन सा मंदिर है?','[{"key": "A", "en": "Kamakhya Temple", "hi": "कामाख्या मंदिर"}, {"key": "B", "en": "Kalighat Temple", "hi": "कालीघाट मंदिर"}, {"key": "C", "en": "Ambaji Temple", "hi": "अंबाजी मंदिर"}, {"key": "D", "en": "Chhinnamasta Temple", "hi": "छिन्नमस्ता मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2842,'Which Buddhist site is associated with Buddha''s enlightenment?','बुद्ध के ज्ञान प्राप्ति से कौन सा बौद्ध स्थल जुड़ा है?','[{"key": "A", "en": "Sarnath", "hi": "सारनाथ"}, {"key": "B", "en": "Kushinagar", "hi": "कुशीनगर"}, {"key": "C", "en": "Bodh Gaya", "hi": "बोधगया"}, {"key": "D", "en": "Rajgir", "hi": "राजगीर"}]','C');
INSERT INTO knowledge_quiz VALUES(2843,'Which Sikh Takht is located in Nanded?','नांदेड़ में कौन सा सिख तख्त स्थित है?','[{"key": "A", "en": "Takht Sri Patna Sahib", "hi": "तख्त श्री पटना साहिब"}, {"key": "B", "en": "Takht Sri Keshgarh Sahib", "hi": "तख्त श्री केशगढ़ साहिब"}, {"key": "C", "en": "Takht Sachkhand Sri Hazur Sahib", "hi": "तख्त सचखंड श्री हजूर साहिब"}, {"key": "D", "en": "Akal Takht", "hi": "अकाल तख्त"}]','C');
INSERT INTO knowledge_quiz VALUES(2844,'Which temple in Karnataka is dedicated to Lord Shiva and built by Cholas?','कर्नाटक में चोलों द्वारा निर्मित कौन सा शिव मंदिर है?','[{"key": "A", "en": "Murudeshwar Temple", "hi": "मुरुदेश्वर मंदिर"}, {"key": "B", "en": "Hoysaleswara Temple", "hi": "होयसलेश्वर मंदिर"}, {"key": "C", "en": "Brihadeeswarar Temple", "hi": "बृहदीश्वर मंदिर"}, {"key": "D", "en": "Virupaksha Temple", "hi": "विरुपाक्ष मंदिर"}]','D');
INSERT INTO knowledge_quiz VALUES(2845,'Which temple is known as the ''Gem of Odisha Architecture'' due to its exquisite carvings and arched gateway (Torana)?','अपनी उत्कृष्ट नक्काशी और मेहराबदार प्रवेश द्वार (तोरण) के कारण किस मंदिर को ''ओडिशा वास्तुकला का रत्न'' कहा जाता है?','[{"key": "A", "en": "Ananta Vasudeva", "hi": "अनंत वासुदेव"}, {"key": "B", "en": "Mukteshwar Temple", "hi": "मुक्तेश्वर मंदिर"}, {"key": "C", "en": "Parasurameswar", "hi": "परशुरामेश्वर"}, {"key": "D", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2846,'Which pilgrimage site is dedicated to Goddess Vaishno Devi?','देवी वैष्णो देवी को समर्पित कौन सा तीर्थ है?','[{"key": "A", "en": "Katra", "hi": "कटरा"}, {"key": "B", "en": "Jammu", "hi": "जम्मू"}, {"key": "C", "en": "Udhampur", "hi": "उधमपुर"}, {"key": "D", "en": "Srinagar", "hi": "श्रीनगर"}]','A');
INSERT INTO knowledge_quiz VALUES(2847,'Which temple is located at the southern tip of India?','भारत के दक्षिणी छोर पर कौन सा मंदिर स्थित है?','[{"key": "A", "en": "Rameswaram Temple", "hi": "रामेश्वरम मंदिर"}, {"key": "B", "en": "Kanyakumari Temple", "hi": "कन्याकुमारी मंदिर"}, {"key": "C", "en": "Chidambaram Temple", "hi": "चिदंबरम मंदिर"}, {"key": "D", "en": "Padmanabhaswamy Temple", "hi": "पद्मनाभस्वामी मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2848,'Which Jyotirlinga is located in Jharkhand?','झारखंड में कौन सा ज्योतिर्लिंग स्थित है?','[{"key": "A", "en": "Baidyanath Dham", "hi": "वैद्यनाथ धाम"}, {"key": "B", "en": "Nageshwar", "hi": "नागेश्वर"}, {"key": "C", "en": "Trimbakeshwar", "hi": "त्र्यंबकेश्वर"}, {"key": "D", "en": "Kedarnath", "hi": "केदारनाथ"}]','A');
INSERT INTO knowledge_quiz VALUES(2849,'Which temple is famous for the annual Thrissur Pooram?','वार्षिक त्रिशूर पूरम के लिए कौन सा मंदिर प्रसिद्ध है?','[{"key": "A", "en": "Guruvayur Temple", "hi": "गुरुवायुर मंदिर"}, {"key": "B", "en": "Vadakkunnathan Temple", "hi": "वडक्कुनाथन मंदिर"}, {"key": "C", "en": "Padmanabhaswamy Temple", "hi": "पद्मनाभस्वामी मंदिर"}, {"key": "D", "en": "Sabarimala Temple", "hi": "सबरीमला मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2850,'Which pilgrimage site is known as the ''Abode of the Gods''?','‘देवभूमि’ के नाम से कौन सा क्षेत्र जाना जाता है?','[{"key": "A", "en": "Himachal Pradesh", "hi": "हिमाचल प्रदेश"}, {"key": "B", "en": "Uttarakhand", "hi": "उत्तराखंड"}, {"key": "C", "en": "Jammu and Kashmir", "hi": "जम्मू और कश्मीर"}, {"key": "D", "en": "Sikkim", "hi": "सिक्किम"}]','B');
INSERT INTO knowledge_quiz VALUES(2851,'Which Vedic sage is credited with compiling the Rigveda?','ऋग्वेद के संकलन का श्रेय किस ऋषि को दिया जाता है?','[{"key": "A", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "B", "en": "Angiras", "hi": "अंगिरस"}, {"key": "C", "en": "Krishna Dvaipayana Vyasa", "hi": "कृष्ण द्वैपायन व्यास"}, {"key": "D", "en": "Atri", "hi": "अत्रि"}]','C');
INSERT INTO knowledge_quiz VALUES(2852,'Which ancient Hindu text mentions the concept of time cycles (Yugas) in detail?','युग चक्रों की विस्तृत अवधारणा किस ग्रंथ में मिलती है?','[{"key": "A", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "D", "en": "Natya Shastra", "hi": "नाट्यशास्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(2853,'Which river mentioned in the Rigveda is believed to have dried up?','ऋग्वेद में वर्णित कौन सी नदी अब लुप्त मानी जाती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Sindhu", "hi": "सिंधु"}]','C');
INSERT INTO knowledge_quiz VALUES(2854,'Which Hindu god is described as both male and female in one form?','कौन से देवता एक ही रूप में पुरुष और स्त्री दोनों माने गए हैं?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Ardhanarishvara", "hi": "अर्धनारीश्वर"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','C');
INSERT INTO knowledge_quiz VALUES(2855,'Which Upanishad uses dialogue between a father and son for teaching Brahman?','पिता-पुत्र संवाद द्वारा ब्रह्म ज्ञान किस उपनिषद में दिया गया है?','[{"key": "A", "en": "Katha Upanishad", "hi": "कठ उपनिषद"}, {"key": "B", "en": "Chandogya Upanishad", "hi": "छांदोग्य उपनिषद"}, {"key": "C", "en": "Isha Upanishad", "hi": "ईश उपनिषद"}, {"key": "D", "en": "Taittiriya Upanishad", "hi": "तैत्तिरीय उपनिषद"}]','B');
INSERT INTO knowledge_quiz VALUES(2856,'Which deity is considered the guardian of directions in Hinduism?','हिंदू धर्म में दिशाओं का रक्षक कौन माना जाता है?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Lokapalas", "hi": "लोकपाल"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(2857,'Which Purana is the largest among the eighteen Mahapuranas?','अठारह महापुराणों में सबसे बड़ा कौन सा है?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "C", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "D", "en": "Brahmanda Purana", "hi": "ब्रह्माण्ड पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(2858,'The ''Pana Kala Narasimha Swamy'' temple in Mangalagiri is famous for the deity ''drinking'' which liquid offered by devotees?','मंगलगीरी में ''पाना काल नरसिंह स्वामी'' मंदिर भक्तों द्वारा अर्पित किस तरल पदार्थ को देवता द्वारा ''पीने'' के लिए प्रसिद्ध है?','[{"key": "A", "en": "Milk", "hi": "दूध"}, {"key": "B", "en": "Jaggery Water", "hi": "गुड़ का पानी"}, {"key": "C", "en": "Honey", "hi": "शहद"}, {"key": "D", "en": "Coconut Water", "hi": "नारियल पानी"}]','B');
INSERT INTO knowledge_quiz VALUES(2859,'Which sage is believed to have lived through multiple Yugas?','कौन से ऋषि को कई युगों तक जीवित माना जाता है?','[{"key": "A", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "B", "en": "Narada", "hi": "नारद"}, {"key": "C", "en": "Markandeya", "hi": "मार्कण्डेय"}, {"key": "D", "en": "Bhrigu", "hi": "भृगु"}]','C');
INSERT INTO knowledge_quiz VALUES(2860,'Which mantra is considered the seed (Bija) of all mantras?','सभी मंत्रों का बीज मंत्र कौन सा माना जाता है?','[{"key": "A", "en": "Gayatri Mantra", "hi": "गायत्री मंत्र"}, {"key": "B", "en": "Om", "hi": "ॐ"}, {"key": "C", "en": "Mahamrityunjaya Mantra", "hi": "महामृत्युंजय मंत्र"}, {"key": "D", "en": "Shanti Mantra", "hi": "शांति मंत्र"}]','B');
INSERT INTO knowledge_quiz VALUES(2861,'Which temple is believed to grow a sacred flag naturally every year?','किस मंदिर में पवित्र ध्वज स्वयं बढ़ता हुआ माना जाता है?','[{"key": "A", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}, {"key": "B", "en": "Kashi Vishwanath", "hi": "काशी विश्वनाथ"}, {"key": "C", "en": "Meenakshi Temple", "hi": "मीनाक्षी मंदिर"}, {"key": "D", "en": "Sabarimala Temple", "hi": "सबरीमला मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2862,'Which Hindu scripture mentions airplanes (Vimanas)?','विमानों (विमान) का उल्लेख किस ग्रंथ में मिलता है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Vaimanika Shastra", "hi": "वैमानिक शास्त्र"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2863,'Which avatar of Vishnu is described as emerging from a pillar?','विष्णु का कौन सा अवतार स्तंभ से प्रकट हुआ माना जाता है?','[{"key": "A", "en": "Varaha", "hi": "वराह"}, {"key": "B", "en": "Narasimha", "hi": "नरसिंह"}, {"key": "C", "en": "Kurma", "hi": "कूर्म"}, {"key": "D", "en": "Vamana", "hi": "वामन"}]','B');
INSERT INTO knowledge_quiz VALUES(2864,'Which day is considered ideal for ancestor worship (Pitru Tarpan)?','पितृ तर्पण के लिए कौन सा समय सबसे उपयुक्त माना जाता है?','[{"key": "A", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "B", "en": "Shraddha Paksha", "hi": "श्राद्ध पक्ष"}, {"key": "C", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "D", "en": "Amavasya", "hi": "अमावस्या"}]','B');
INSERT INTO knowledge_quiz VALUES(2865,'Which ancient Hindu text classifies dreams and their meanings?','स्वप्नों के प्रकार और अर्थ किस ग्रंथ में वर्णित हैं?','[{"key": "A", "en": "Brihadaranyaka Upanishad", "hi": "बृहदारण्यक उपनिषद"}, {"key": "B", "en": "Garuda Purana", "hi": "गरुड़ पुराण"}, {"key": "C", "en": "Narada Purana", "hi": "नारद पुराण"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(2866,'Which Yuga is said to have the shortest duration in the cycle of time?','समय के चक्र में किस युग की अवधि सबसे कम बताई गई है?','[{"key": "A", "en": "Satya Yuga", "hi": "सत्य युग"}, {"key": "B", "en": "Treta Yuga", "hi": "त्रेता युग"}, {"key": "C", "en": "Dvapara Yuga", "hi": "द्वापर युग"}, {"key": "D", "en": "Kali Yuga", "hi": "कलयुग"}]','D');
INSERT INTO knowledge_quiz VALUES(2867,'The main tower (Gopuram) of the Tirumala Venkateswara temple is covered with gold and is known as?','तिरुपति वेंकटेश्वर मंदिर का मुख्य शिखर (गोपुरम) सोने से ढका है, इसे किस नाम से जाना जाता है?','[{"key": "A", "en": "Ananda Nilayam", "hi": "आनंद निलयम"}, {"key": "B", "en": "Rajagopuram", "hi": "राजगोपुरम"}, {"key": "C", "en": "Vimana Venkateswara", "hi": "विमान वेंकटेश्वर"}, {"key": "D", "en": "Bangaru Vakili", "hi": "बंगारू वाकिली"}]','A');
INSERT INTO knowledge_quiz VALUES(2868,'Which Hindu god is traditionally worshipped first in rituals?','पूजा में सबसे पहले किस देवता की वंदना की जाती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Ganesha", "hi": "गणेश"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','C');
INSERT INTO knowledge_quiz VALUES(2869,'Which sacred mountain is believed to be Lord Shiva’s abode?','भगवान शिव का निवास किस पवित्र पर्वत को माना जाता है?','[{"key": "A", "en": "Mount Meru", "hi": "मेरु पर्वत"}, {"key": "B", "en": "Mount Kailash", "hi": "कैलाश पर्वत"}, {"key": "C", "en": "Mount Mandara", "hi": "मंदराचल"}, {"key": "D", "en": "Mount Vindhya", "hi": "विंध्य पर्वत"}]','B');
INSERT INTO knowledge_quiz VALUES(2870,'Which festival celebrates Krishna lifting Govardhan Hill?','कृष्ण द्वारा गोवर्धन पर्वत उठाने की स्मृति में कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Janmashtami", "hi": "जन्माष्टमी"}, {"key": "B", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "C", "en": "Annakut", "hi": "अन्नकूट"}, {"key": "D", "en": "Both B and C", "hi": "B और C दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(2871,'Which Hindu text describes the science of temple architecture?','मंदिर वास्तुकला का विज्ञान किस ग्रंथ में वर्णित है?','[{"key": "A", "en": "Vastu Shastra", "hi": "वास्तु शास्त्र"}, {"key": "B", "en": "Silpa Shastra", "hi": "शिल्प शास्त्र"}, {"key": "C", "en": "Agni Purana", "hi": "अग्नि पुराण"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2872,'Which river is said to flow invisibly at Prayagraj?','प्रयागराज में कौन सी नदी अदृश्य रूप से बहती मानी जाती है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','C');
INSERT INTO knowledge_quiz VALUES(2873,'Which ancient sage is associated with Ayurveda?','आयुर्वेद से किस प्राचीन ऋषि का संबंध है?','[{"key": "A", "en": "Dhanvantari", "hi": "धन्वंतरि"}, {"key": "B", "en": "Charaka", "hi": "चरक"}, {"key": "C", "en": "Sushruta", "hi": "सुश्रुत"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2874,'Which Hindu symbol represents protection and power?','संरक्षण और शक्ति का प्रतीक कौन सा चिन्ह है?','[{"key": "A", "en": "Swastika", "hi": "स्वस्तिक"}, {"key": "B", "en": "Trishula", "hi": "त्रिशूल"}, {"key": "C", "en": "Lotus", "hi": "कमल"}, {"key": "D", "en": "Conch", "hi": "शंख"}]','B');
INSERT INTO knowledge_quiz VALUES(2875,'Which fast is observed for planetary peace (Navagraha Shanti)?','नवग्रह शांति के लिए कौन सा उपवास किया जाता है?','[{"key": "A", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "B", "en": "Navagraha Vrat", "hi": "नवग्रह व्रत"}, {"key": "C", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "D", "en": "Pradosh Vrat", "hi": "प्रदोष व्रत"}]','B');
INSERT INTO knowledge_quiz VALUES(2876,'Which Hindu epic mentions eclipses caused by Rahu and Ketu?','राहु और केतु द्वारा ग्रहण का वर्णन किस महाकाव्य में है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Vedas", "hi": "वेद"}]','C');
INSERT INTO knowledge_quiz VALUES(2877,'Which Hindu god is known as the divine architect?','दिव्य वास्तुकार के रूप में कौन से देवता जाने जाते हैं?','[{"key": "A", "en": "Vishwakarma", "hi": "विश्वकर्मा"}, {"key": "B", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','A');
INSERT INTO knowledge_quiz VALUES(2878,'Which sacred number frequently appears in Hindu rituals?','हिंदू अनुष्ठानों में कौन सी संख्या बार-बार आती है?','[{"key": "A", "en": "7", "hi": "7"}, {"key": "B", "en": "9", "hi": "9"}, {"key": "C", "en": "108", "hi": "108"}, {"key": "D", "en": "1000", "hi": "1000"}]','C');
INSERT INTO knowledge_quiz VALUES(2879,'Which goddess is worshipped as learning and knowledge?','विद्या और ज्ञान की देवी कौन हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','C');
INSERT INTO knowledge_quiz VALUES(2880,'Which Hindu scripture focuses on devotion (Bhakti)?','भक्ति पर केंद्रित कौन सा ग्रंथ है?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "C", "en": "Yoga Sutra", "hi": "योग सूत्र"}, {"key": "D", "en": "Arthashastra", "hi": "अर्थशास्त्र"}]','A');
INSERT INTO knowledge_quiz VALUES(2881,'Which ancient Hindu practice emphasizes breath control?','श्वास नियंत्रण पर आधारित प्राचीन अभ्यास कौन सा है?','[{"key": "A", "en": "Pranayama", "hi": "प्राणायाम"}, {"key": "B", "en": "Dhyana", "hi": "ध्यान"}, {"key": "C", "en": "Yajna", "hi": "यज्ञ"}, {"key": "D", "en": "Tapasya", "hi": "तपस्या"}]','A');
INSERT INTO knowledge_quiz VALUES(2882,'Which sacred tree is associated with Lord Vishnu?','भगवान विष्णु से कौन सा पवित्र वृक्ष जुड़ा है?','[{"key": "A", "en": "Peepal", "hi": "पीपल"}, {"key": "B", "en": "Banyan", "hi": "बरगद"}, {"key": "C", "en": "Neem", "hi": "नीम"}, {"key": "D", "en": "Bilva", "hi": "बिल्व"}]','A');
INSERT INTO knowledge_quiz VALUES(2883,'Which Hindu festival marks the victory of light over darkness?','अंधकार पर प्रकाश की विजय का पर्व कौन सा है?','[{"key": "A", "en": "Holi", "hi": "होली"}, {"key": "B", "en": "Diwali", "hi": "दीवाली"}, {"key": "C", "en": "Dussehra", "hi": "दशहरा"}, {"key": "D", "en": "Navratri", "hi": "नवरात्रि"}]','B');
INSERT INTO knowledge_quiz VALUES(2884,'Which Hindu god is worshipped in the form of a stone (Lingam)?','पत्थर के लिंग रूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2885,'Which Hindu ritual symbolizes offering the ego to fire?','अहंकार को अग्नि में अर्पित करने का प्रतीक कौन सा कर्म है?','[{"key": "A", "en": "Yajna", "hi": "यज्ञ"}, {"key": "B", "en": "Puja", "hi": "पूजा"}, {"key": "C", "en": "Havan", "hi": "हवन"}, {"key": "D", "en": "Both A and C", "hi": "A और C दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(2886,'Which deity is worshipped in the form of Salagrama stone?','शालिग्राम शिला के रूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Ganesha", "hi": "गणेश"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2887,'Which Hindu concept explains cause and effect of actions?','कर्म के कारण-परिणाम को कौन सी अवधारणा समझाती है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Karma", "hi": "कर्म"}, {"key": "C", "en": "Moksha", "hi": "मोक्ष"}, {"key": "D", "en": "Bhakti", "hi": "भक्ति"}]','B');
INSERT INTO knowledge_quiz VALUES(2888,'In the Hanuman Chalisa, the line ''Saba para Rama tapasvi raja'' describes Lord Rama as a ''Tapasvi'' king. What does ''Tapasvi'' signify?','हनुमान चालीसा की पंक्ति ''सब पर राम तपस्वी राजा'' में भगवान राम को ''तपस्वी'' राजा बताया गया है। यहाँ ''तपस्वी'' का क्या अर्थ है?','[{"key": "A", "en": "Wealthy", "hi": "धनवान"}, {"key": "B", "en": "One who practices penance", "hi": "तपस्या करने वाला"}, {"key": "C", "en": "Aggressive", "hi": "आक्रामक"}, {"key": "D", "en": "Old", "hi": "वृद्ध"}]','B');
INSERT INTO knowledge_quiz VALUES(2889,'Which Hindu belief explains rebirth?','पुनर्जन्म की व्याख्या कौन सा सिद्धांत करता है?','[{"key": "A", "en": "Maya", "hi": "माया"}, {"key": "B", "en": "Samsara", "hi": "संसार"}, {"key": "C", "en": "Yoga", "hi": "योग"}, {"key": "D", "en": "Tapas", "hi": "तपस"}]','B');
INSERT INTO knowledge_quiz VALUES(2890,'Which sacred sound is believed to represent the universe?','कौन सी पवित्र ध्वनि ब्रह्मांड का प्रतीक मानी जाती है?','[{"key": "A", "en": "Hum", "hi": "हुम्"}, {"key": "B", "en": "Om", "hi": "ॐ"}, {"key": "C", "en": "Ram", "hi": "राम"}, {"key": "D", "en": "Hreem", "hi": "ह्रीं"}]','B');
INSERT INTO knowledge_quiz VALUES(2891,'Which ancient Hindu practice includes eight limbs?','आठ अंगों वाला प्राचीन अभ्यास कौन सा है?','[{"key": "A", "en": "Hatha Yoga", "hi": "हठ योग"}, {"key": "B", "en": "Ashtanga Yoga", "hi": "अष्टांग योग"}, {"key": "C", "en": "Bhakti Yoga", "hi": "भक्ति योग"}, {"key": "D", "en": "Karma Yoga", "hi": "कर्म योग"}]','B');
INSERT INTO knowledge_quiz VALUES(2892,'Which Hindu scripture explains the duties of kings?','राजाओं के कर्तव्यों का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "B", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "C", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2893,'Which Hindu god rides a mouse?','किस देवता का वाहन मूषक है?','[{"key": "A", "en": "Kartikeya", "hi": "कार्तिकेय"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Shani", "hi": "शनि"}, {"key": "D", "en": "Yama", "hi": "यम"}]','B');
INSERT INTO knowledge_quiz VALUES(2894,'Which ritual marks the beginning of formal education?','औपचारिक शिक्षा की शुरुआत कौन सा संस्कार करता है?','[{"key": "A", "en": "Upanayana", "hi": "उपनयन"}, {"key": "B", "en": "Vidyarambha", "hi": "विद्यारंभ"}, {"key": "C", "en": "Namakarana", "hi": "नामकरण"}, {"key": "D", "en": "Annaprashana", "hi": "अन्नप्राशन"}]','B');
INSERT INTO knowledge_quiz VALUES(2895,'Which Hindu belief emphasizes liberation from rebirth?','पुनर्जन्म से मुक्ति पर कौन सी धारणा केंद्रित है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Moksha", "hi": "मोक्ष"}, {"key": "C", "en": "Artha", "hi": "अर्थ"}, {"key": "D", "en": "Kama", "hi": "काम"}]','B');
INSERT INTO knowledge_quiz VALUES(2896,'Which ancient Hindu text discusses music and dance?','संगीत और नृत्य पर कौन सा प्राचीन ग्रंथ है?','[{"key": "A", "en": "Natya Shastra", "hi": "नाट्यशास्त्र"}, {"key": "B", "en": "Silpa Shastra", "hi": "शिल्प शास्त्र"}, {"key": "C", "en": "Vastu Shastra", "hi": "वास्तु शास्त्र"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(2897,'Which Hindu deity is associated with time and justice?','समय और न्याय से कौन से देवता जुड़े हैं?','[{"key": "A", "en": "Yama", "hi": "यम"}, {"key": "B", "en": "Shani", "hi": "शनि"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','C');
INSERT INTO knowledge_quiz VALUES(2898,'Which Hindu festival is celebrated by worshipping tools and weapons?','औजारों और अस्त्रों की पूजा किस पर्व में होती है?','[{"key": "A", "en": "Ayudha Puja", "hi": "आयुध पूजा"}, {"key": "B", "en": "Vishwakarma Puja", "hi": "विश्वकर्मा पूजा"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}]','C');
INSERT INTO knowledge_quiz VALUES(2899,'Which Hindu text describes cosmic dissolution (Pralaya)?','प्रलय (सृष्टि विनाश) का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "B", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "C", "en": "Markandeya Purana", "hi": "मार्कण्डेय पुराण"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2900,'Which Hindu philosophy teaches non-dualism?','अद्वैत दर्शन किस दर्शन से संबंधित है?','[{"key": "A", "en": "Dvaita", "hi": "द्वैत"}, {"key": "B", "en": "Vishishtadvaita", "hi": "विशिष्टाद्वैत"}, {"key": "C", "en": "Advaita Vedanta", "hi": "अद्वैत वेदांत"}, {"key": "D", "en": "Samkhya", "hi": "सांख्य"}]','C');
INSERT INTO knowledge_quiz VALUES(2901,'What is the vahana (vehicle) of Lord Ganesha?','भगवान गणेश का वाहन कौन सा है?','[{"key": "A", "en": "Peacock", "hi": "मोर"}, {"key": "B", "en": "Mouse", "hi": "मूषक"}, {"key": "C", "en": "Bull", "hi": "बैल"}, {"key": "D", "en": "Lion", "hi": "सिंह"}]','B');
INSERT INTO knowledge_quiz VALUES(2902,'Which animal serves as the vahana of Lord Shiva?','भगवान शिव का वाहन कौन सा है?','[{"key": "A", "en": "Lion", "hi": "सिंह"}, {"key": "B", "en": "Horse", "hi": "घोड़ा"}, {"key": "C", "en": "Bull (Nandi)", "hi": "बैल (नंदी)"}, {"key": "D", "en": "Elephant", "hi": "हाथी"}]','C');
