INSERT INTO knowledge_quiz VALUES(2908,'Which animal is the vahana of Lord Yama?','भगवान यम का वाहन कौन सा है?','[{"key": "A", "en": "Buffalo", "hi": "भैंस"}, {"key": "B", "en": "Horse", "hi": "घोड़ा"}, {"key": "C", "en": "Bull", "hi": "बैल"}, {"key": "D", "en": "Dog", "hi": "कुत्ता"}]','A');
INSERT INTO knowledge_quiz VALUES(2909,'Which bird is the vahana of Lord Brahma?','भगवान ब्रह्मा का वाहन कौन सा पक्षी है?','[{"key": "A", "en": "Garuda", "hi": "गरुड़"}, {"key": "B", "en": "Peacock", "hi": "मोर"}, {"key": "C", "en": "Swan (Hamsa)", "hi": "हंस (हंस)"}, {"key": "D", "en": "Crow", "hi": "कौआ"}]','C');
INSERT INTO knowledge_quiz VALUES(2910,'Which animal is associated as the vahana of Goddess Kali?','देवी काली का वाहन कौन सा माना जाता है?','[{"key": "A", "en": "Lion", "hi": "सिंह"}, {"key": "B", "en": "Tiger", "hi": "बाघ"}, {"key": "C", "en": "Jackal", "hi": "सियार"}, {"key": "D", "en": "Owl", "hi": "उल्लू"}]','C');
INSERT INTO knowledge_quiz VALUES(2911,'What is the vahana of Lord Indra?','भगवान इंद्र का वाहन कौन सा है?','[{"key": "A", "en": "Horse", "hi": "घोड़ा"}, {"key": "B", "en": "Elephant (Airavata)", "hi": "हाथी (ऐरावत)"}, {"key": "C", "en": "Lion", "hi": "सिंह"}, {"key": "D", "en": "Bull", "hi": "बैल"}]','B');
INSERT INTO knowledge_quiz VALUES(2912,'Which animal is the vahana of Goddess Ganga?','देवी गंगा का वाहन कौन सा है?','[{"key": "A", "en": "Crocodile (Makara)", "hi": "मगरमच्छ (मकर)"}, {"key": "B", "en": "Swan", "hi": "हंस"}, {"key": "C", "en": "Fish", "hi": "मछली"}, {"key": "D", "en": "Turtle", "hi": "कछुआ"}]','A');
INSERT INTO knowledge_quiz VALUES(2913,'Which deity rides a horse as part of the Kalki avatar?','कल्कि अवतार में कौन से देवता घोड़े पर सवार हैं?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(2914,'Which animal is the vahana of Lord Shani?','भगवान शनि का वाहन कौन सा है?','[{"key": "A", "en": "Crow", "hi": "कौआ"}, {"key": "B", "en": "Eagle", "hi": "गरुड़"}, {"key": "C", "en": "Horse", "hi": "घोड़ा"}, {"key": "D", "en": "Buffalo", "hi": "भैंस"}]','A');
INSERT INTO knowledge_quiz VALUES(2915,'Which animal serves as the vahana of Lord Varuna?','भगवान वरुण का वाहन कौन सा है?','[{"key": "A", "en": "Fish", "hi": "मछली"}, {"key": "B", "en": "Makara", "hi": "मकर"}, {"key": "C", "en": "Turtle", "hi": "कछुआ"}, {"key": "D", "en": "Snake", "hi": "सर्प"}]','B');
INSERT INTO knowledge_quiz VALUES(2916,'Which goddess rides a tiger as her vahana?','कौन सी देवी का वाहन बाघ है?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Chamunda", "hi": "चामुंडा"}, {"key": "D", "en": "Both B and C", "hi": "B और C दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(2917,'Which bird acts as the vahana of Lord Kamadeva?','भगवान कामदेव का वाहन कौन सा पक्षी है?','[{"key": "A", "en": "Parrot", "hi": "तोता"}, {"key": "B", "en": "Swan", "hi": "हंस"}, {"key": "C", "en": "Peacock", "hi": "मोर"}, {"key": "D", "en": "Crow", "hi": "कौआ"}]','A');
INSERT INTO knowledge_quiz VALUES(2918,'Which animal is the vahana of Lord Agni?','भगवान अग्नि का वाहन कौन सा है?','[{"key": "A", "en": "Ram", "hi": "मेढ़ा"}, {"key": "B", "en": "Horse", "hi": "घोड़ा"}, {"key": "C", "en": "Elephant", "hi": "हाथी"}, {"key": "D", "en": "Bull", "hi": "बैल"}]','A');
INSERT INTO knowledge_quiz VALUES(2919,'Which deity rides a chariot drawn by seven horses?','सात घोड़ों वाले रथ पर कौन से देवता सवार होते हैं?','[{"key": "A", "en": "Surya", "hi": "सूर्य"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','A');
INSERT INTO knowledge_quiz VALUES(2920,'Which animal is the vahana of Lord Vayu?','भगवान वायु का वाहन कौन सा है?','[{"key": "A", "en": "Horse", "hi": "घोड़ा"}, {"key": "B", "en": "Deer", "hi": "हिरण"}, {"key": "C", "en": "Antelope", "hi": "मृग"}, {"key": "D", "en": "Gazelle", "hi": "चिंकारा"}]','B');
INSERT INTO knowledge_quiz VALUES(2921,'Which temple in Kerala opens only for a few days every year?','केरल का कौन सा मंदिर वर्ष में केवल कुछ दिनों के लिए ही खुलता है?','[{"key": "A", "en": "Guruvayur Temple", "hi": "गुरुवायुर मंदिर"}, {"key": "B", "en": "Sabarimala Temple", "hi": "सबरीमला मंदिर"}, {"key": "C", "en": "Padmanabhaswamy Temple", "hi": "पद्मनाभस्वामी मंदिर"}, {"key": "D", "en": "Chottanikkara Temple", "hi": "चोट्टानिक्करा मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2922,'Which temple in Tamil Nadu has inscriptions in multiple ancient scripts?','तमिलनाडु का कौन सा मंदिर अनेक प्राचीन लिपियों के अभिलेखों के लिए प्रसिद्ध है?','[{"key": "A", "en": "Chidambaram Temple", "hi": "चिदंबरम मंदिर"}, {"key": "B", "en": "Brihadeeswarar Temple", "hi": "बृहदीश्वर मंदिर"}, {"key": "C", "en": "Rameswaram Temple", "hi": "रामेश्वरम मंदिर"}, {"key": "D", "en": "Madurai Meenakshi Temple", "hi": "मदुरै मीनाक्षी मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2923,'Which temple in Karnataka is carved entirely out of a single rock?','कर्नाटक का कौन सा मंदिर एक ही चट्टान से तराशा गया है?','[{"key": "A", "en": "Virupaksha Temple", "hi": "विरुपाक्ष मंदिर"}, {"key": "B", "en": "Badami Cave Temple", "hi": "बादामी गुफा मंदिर"}, {"key": "C", "en": "Chennakesava Temple", "hi": "चेन्नकेशव मंदिर"}, {"key": "D", "en": "Shravanabelagola", "hi": "श्रवणबेलगोला"}]','B');
INSERT INTO knowledge_quiz VALUES(2924,'Which temple is known as the wealthiest temple in the world?','दुनिया का सबसे धनी मंदिर कौन सा माना जाता है?','[{"key": "A", "en": "Tirupati Balaji Temple", "hi": "तिरुपति बालाजी मंदिर"}, {"key": "B", "en": "Kashi Vishwanath Temple", "hi": "काशी विश्वनाथ मंदिर"}, {"key": "C", "en": "Padmanabhaswamy Temple", "hi": "पद्मनाभस्वामी मंदिर"}, {"key": "D", "en": "Somnath Temple", "hi": "सोमनाथ मंदिर"}]','C');
INSERT INTO knowledge_quiz VALUES(2925,'Which temple in Odisha is famous for its floating Sudarshan Chakra?','ओडिशा का कौन सा मंदिर अपने तैरते सुदर्शन चक्र के लिए प्रसिद्ध है?','[{"key": "A", "en": "Konark Sun Temple", "hi": "कोणार्क सूर्य मंदिर"}, {"key": "B", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}, {"key": "C", "en": "Lingaraja Temple", "hi": "लिंगराज मंदिर"}, {"key": "D", "en": "Mukteshwar Temple", "hi": "मुक्तेश्वर मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2926,'Which temple is associated with the legend of 64 Yoginis?','64 योगिनियों की कथा से जुड़ा कौन सा मंदिर है?','[{"key": "A", "en": "Khajuraho Yogini Temple", "hi": "खजुराहो योगिनी मंदिर"}, {"key": "B", "en": "Kalighat Temple", "hi": "कालीघाट मंदिर"}, {"key": "C", "en": "Kamakhya Temple", "hi": "कामाख्या मंदिर"}, {"key": "D", "en": "Ambaji Temple", "hi": "अंबाजी मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2927,'Which temple town is believed to never face a full natural disaster?','किस मंदिर नगर को कभी पूर्ण प्राकृतिक आपदा से प्रभावित न होने वाला माना जाता है?','[{"key": "A", "en": "Kanchipuram", "hi": "कांचीपुरम"}, {"key": "B", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "C", "en": "Puri", "hi": "पुरी"}, {"key": "D", "en": "Rameswaram", "hi": "रामेश्वरम"}]','B');
INSERT INTO knowledge_quiz VALUES(2928,'Which temple in Rajasthan is entirely made of white marble?','राजस्थान का कौन सा मंदिर पूरी तरह सफेद संगमरमर से बना है?','[{"key": "A", "en": "Eklingji Temple", "hi": "एकलिंगजी मंदिर"}, {"key": "B", "en": "Dilwara Temples", "hi": "दिलवाड़ा मंदिर"}, {"key": "C", "en": "Karni Mata Temple", "hi": "करणी माता मंदिर"}, {"key": "D", "en": "Brahma Temple", "hi": "ब्रह्मा मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2929,'Which temple in Bihar is associated with Goddess Sita’s birthplace?','बिहार का कौन सा मंदिर देवी सीता के जन्मस्थान से जुड़ा है?','[{"key": "A", "en": "Janaki Mandir", "hi": "जानकी मंदिर"}, {"key": "B", "en": "Mundeshwari Temple", "hi": "मुंडेश्वरी मंदिर"}, {"key": "C", "en": "Mahabodhi Temple", "hi": "महाबोधि मंदिर"}, {"key": "D", "en": "Vishnupad Temple", "hi": "विष्णुपद मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2930,'Which temple in Assam celebrates the Ambubachi Mela?','असम में अंबुबाची मेला किस मंदिर में मनाया जाता है?','[{"key": "A", "en": "Umananda Temple", "hi": "उमानंद मंदिर"}, {"key": "B", "en": "Kamakhya Temple", "hi": "कामाख्या मंदिर"}, {"key": "C", "en": "Navagraha Temple", "hi": "नवग्रह मंदिर"}, {"key": "D", "en": "Hajo Temple", "hi": "हाजो मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(2931,'Which temple is known as the oldest functioning temple in India?','भारत का सबसे प्राचीन कार्यरत मंदिर कौन सा माना जाता है?','[{"key": "A", "en": "Mundeshwari Temple", "hi": "मुंडेश्वरी मंदिर"}, {"key": "B", "en": "Kedarnath Temple", "hi": "केदारनाथ मंदिर"}, {"key": "C", "en": "Badrinath Temple", "hi": "बद्रीनाथ मंदिर"}, {"key": "D", "en": "Somnath Temple", "hi": "सोमनाथ मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2932,'Which temple is famous for being guarded by rats?','चूहों द्वारा संरक्षित मंदिर के रूप में कौन सा मंदिर प्रसिद्ध है?','[{"key": "A", "en": "Karni Mata Temple", "hi": "करणी माता मंदिर"}, {"key": "B", "en": "Chamunda Devi Temple", "hi": "चामुंडा देवी मंदिर"}, {"key": "C", "en": "Kalika Mata Temple", "hi": "कालिका माता मंदिर"}, {"key": "D", "en": "Tulja Bhavani Temple", "hi": "तुलजा भवानी मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2933,'Which temple is located at the highest altitude among the Chhota Char Dham?','छोटा चार धामों में सबसे अधिक ऊँचाई पर स्थित मंदिर कौन सा है?','[{"key": "A", "en": "Badrinath", "hi": "बद्रीनाथ"}, {"key": "B", "en": "Kedarnath", "hi": "केदारनाथ"}, {"key": "C", "en": "Gangotri", "hi": "गंगोत्री"}, {"key": "D", "en": "Yamunotri", "hi": "यमुनोत्री"}]','B');
INSERT INTO knowledge_quiz VALUES(2934,'Which temple is famous for its hanging pillar?','अपने झूलते स्तंभ के लिए कौन सा मंदिर प्रसिद्ध है?','[{"key": "A", "en": "Chidambaram Temple", "hi": "चिदंबरम मंदिर"}, {"key": "B", "en": "Virupaksha Temple, Hampi", "hi": "विरुपाक्ष मंदिर, हम्पी"}, {"key": "C", "en": "Meenakshi Temple", "hi": "मीनाक्षी मंदिर"}, {"key": "D", "en": "Lepakshi Temple", "hi": "लेपाक्षी मंदिर"}]','D');
INSERT INTO knowledge_quiz VALUES(2935,'Which temple complex is famous for erotic sculptures?','कामुक मूर्तियों के लिए कौन सा मंदिर परिसर प्रसिद्ध है?','[{"key": "A", "en": "Khajuraho Temples", "hi": "खजुराहो मंदिर"}, {"key": "B", "en": "Sun Temple Konark", "hi": "सूर्य मंदिर कोणार्क"}, {"key": "C", "en": "Ellora Temples", "hi": "एलोरा मंदिर"}, {"key": "D", "en": "Elephanta Caves", "hi": "एलीफेंटा गुफाएँ"}]','A');
INSERT INTO knowledge_quiz VALUES(2936,'Which temple is associated with the legend of Lord Rama building a bridge?','भगवान राम द्वारा सेतु निर्माण की कथा से कौन सा मंदिर जुड़ा है?','[{"key": "A", "en": "Rameswaram Temple", "hi": "रामेश्वरम मंदिर"}, {"key": "B", "en": "Kanyakumari Temple", "hi": "कन्याकुमारी मंदिर"}, {"key": "C", "en": "Badrinath Temple", "hi": "बद्रीनाथ मंदिर"}, {"key": "D", "en": "Dwarkadhish Temple", "hi": "द्वारकाधीश मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2937,'Which temple in Maharashtra is one of the Ashtavinayaka temples?','महाराष्ट्र का कौन सा मंदिर अष्टविनायक में से एक है?','[{"key": "A", "en": "Siddhivinayak Temple", "hi": "सिद्धिविनायक मंदिर"}, {"key": "B", "en": "Dagdusheth Temple", "hi": "दगडूशेठ मंदिर"}, {"key": "C", "en": "Morgaon Ganpati Temple", "hi": "मोरगांव गणपति मंदिर"}, {"key": "D", "en": "Trimbakeshwar Temple", "hi": "त्र्यंबकेश्वर मंदिर"}]','C');
INSERT INTO knowledge_quiz VALUES(2938,'Which temple is famous for the annual Brahmotsavam festival?','वार्षिक ब्रह्मोत्सवम उत्सव के लिए कौन सा मंदिर प्रसिद्ध है?','[{"key": "A", "en": "Tirupati Balaji Temple", "hi": "तिरुपति बालाजी मंदिर"}, {"key": "B", "en": "Guruvayur Temple", "hi": "गुरुवायुर मंदिर"}, {"key": "C", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}, {"key": "D", "en": "Meenakshi Temple", "hi": "मीनाक्षी मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2939,'Which temple is dedicated to the Sun God in Gujarat?','गुजरात में सूर्य देव को समर्पित कौन सा मंदिर है?','[{"key": "A", "en": "Modhera Sun Temple", "hi": "मोढेरा सूर्य मंदिर"}, {"key": "B", "en": "Konark Sun Temple", "hi": "कोणार्क सूर्य मंदिर"}, {"key": "C", "en": "Martand Sun Temple", "hi": "मार्तंड सूर्य मंदिर"}, {"key": "D", "en": "Arasavalli Sun Temple", "hi": "आरासावल्ली सूर्य मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2940,'Which temple is known for allowing devotees of all castes from ancient times?','प्राचीन काल से सभी जातियों के भक्तों को प्रवेश देने के लिए कौन सा मंदिर जाना जाता है?','[{"key": "A", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}, {"key": "B", "en": "Guruvayur Temple", "hi": "गुरुवायुर मंदिर"}, {"key": "C", "en": "Chidambaram Temple", "hi": "चिदंबरम मंदिर"}, {"key": "D", "en": "Srirangam Temple", "hi": "श्रीरंगम मंदिर"}]','D');
INSERT INTO knowledge_quiz VALUES(2941,'Which Vedic concept refers to the moral order of the universe?','ब्रह्मांड के नैतिक नियम को कौन सी वैदिक अवधारणा दर्शाती है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Rta", "hi": "ऋत"}, {"key": "C", "en": "Karma", "hi": "कर्म"}, {"key": "D", "en": "Maya", "hi": "माया"}]','B');
INSERT INTO knowledge_quiz VALUES(2942,'Which Hindu scripture first mentions the four Ashramas of life?','जीवन के चार आश्रमों का उल्लेख सबसे पहले किस ग्रंथ में मिलता है?','[{"key": "A", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "B", "en": "Rigveda", "hi": "ऋग्वेद"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Mahabharata", "hi": "महाभारत"}]','A');
INSERT INTO knowledge_quiz VALUES(2943,'Which ancient Hindu text describes surgical techniques?','शल्य चिकित्सा की तकनीकों का वर्णन किस प्राचीन ग्रंथ में है?','[{"key": "A", "en": "Charaka Samhita", "hi": "चरक संहिता"}, {"key": "B", "en": "Sushruta Samhita", "hi": "सुश्रुत संहिता"}, {"key": "C", "en": "Atharvaveda", "hi": "अथर्ववेद"}, {"key": "D", "en": "Agni Purana", "hi": "अग्नि पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(2944,'Which Hindu deity is worshipped in the form of time (Kala)?','समय (काल) के रूप में किस देवता की उपासना की जाती है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Yama", "hi": "यम"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','A');
INSERT INTO knowledge_quiz VALUES(2945,'Which Upanishad contains the famous dialogue of Nachiketa?','नचिकेता का प्रसिद्ध संवाद किस उपनिषद में है?','[{"key": "A", "en": "Katha Upanishad", "hi": "कठ उपनिषद"}, {"key": "B", "en": "Isha Upanishad", "hi": "ईश उपनिषद"}, {"key": "C", "en": "Mundaka Upanishad", "hi": "मुण्डक उपनिषद"}, {"key": "D", "en": "Kena Upanishad", "hi": "केन उपनिषद"}]','A');
INSERT INTO knowledge_quiz VALUES(2946,'Which Hindu belief explains illusion masking reality?','वास्तविकता को ढकने वाले भ्रम की व्याख्या कौन सी अवधारणा करती है?','[{"key": "A", "en": "Maya", "hi": "माया"}, {"key": "B", "en": "Karma", "hi": "कर्म"}, {"key": "C", "en": "Bhakti", "hi": "भक्ति"}, {"key": "D", "en": "Tapas", "hi": "तपस"}]','A');
INSERT INTO knowledge_quiz VALUES(2947,'Which ancient Hindu sage is associated with grammar?','व्याकरण से जुड़े प्राचीन ऋषि कौन हैं?','[{"key": "A", "en": "Panini", "hi": "पाणिनि"}, {"key": "B", "en": "Yajnavalkya", "hi": "याज्ञवल्क्य"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Atri", "hi": "अत्रि"}]','A');
INSERT INTO knowledge_quiz VALUES(2948,'Which Hindu symbol represents auspicious beginnings?','शुभ आरंभ का प्रतीक कौन सा चिह्न है?','[{"key": "A", "en": "Swastika", "hi": "स्वस्तिक"}, {"key": "B", "en": "Om", "hi": "ॐ"}, {"key": "C", "en": "Trishula", "hi": "त्रिशूल"}, {"key": "D", "en": "Shankha", "hi": "शंख"}]','A');
INSERT INTO knowledge_quiz VALUES(2949,'Which Purana narrates the story of Devi Mahatmya?','देवी महात्म्य की कथा किस पुराण में है?','[{"key": "A", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "B", "en": "Markandeya Purana", "hi": "मार्कण्डेय पुराण"}, {"key": "C", "en": "Agni Purana", "hi": "अग्नि पुराण"}, {"key": "D", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(2950,'Which Hindu concept refers to liberation while living?','जीवित रहते मुक्ति को कौन सी अवधारणा कहा जाता है?','[{"key": "A", "en": "Moksha", "hi": "मोक्ष"}, {"key": "B", "en": "Jivanmukti", "hi": "जीवनमुक्ति"}, {"key": "C", "en": "Kaivalya", "hi": "कैवल्य"}, {"key": "D", "en": "Sannyasa", "hi": "संन्यास"}]','B');
INSERT INTO knowledge_quiz VALUES(2951,'Which river is symbolically associated with knowledge?','ज्ञान से प्रतीकात्मक रूप से जुड़ी नदी कौन सी है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','C');
INSERT INTO knowledge_quiz VALUES(2952,'Which Hindu ritual involves symbolic rebirth?','प्रतीकात्मक पुनर्जन्म किस संस्कार से जुड़ा है?','[{"key": "A", "en": "Upanayana", "hi": "उपनयन"}, {"key": "B", "en": "Vivaha", "hi": "विवाह"}, {"key": "C", "en": "Antyeshti", "hi": "अंत्येष्टि"}, {"key": "D", "en": "Namakarana", "hi": "नामकरण"}]','A');
INSERT INTO knowledge_quiz VALUES(2953,'Which deity represents the balance of creation, preservation, and destruction?','सृष्टि, संरक्षण और संहार के संतुलन का प्रतीक कौन है?','[{"key": "A", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Trimurti", "hi": "त्रिमूर्ति"}]','D');
INSERT INTO knowledge_quiz VALUES(2954,'Which ancient text explains planetary motions in detail?','ग्रहों की गति का विस्तृत वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Surya Siddhanta", "hi": "सूर्य सिद्धांत"}, {"key": "B", "en": "Vedanga Jyotisha", "hi": "वेदांग ज्योतिष"}, {"key": "C", "en": "Brihat Samhita", "hi": "बृहत संहिता"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2955,'Which Hindu goddess is associated with fertility and earth?','उर्वरता और पृथ्वी से जुड़ी देवी कौन हैं?','[{"key": "A", "en": "Prithvi", "hi": "पृथ्वी"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Bhumi Devi", "hi": "भूमि देवी"}]','D');
INSERT INTO knowledge_quiz VALUES(2956,'Which practice involves chanting the same mantra repeatedly?','एक ही मंत्र के बार-बार जप को क्या कहा जाता है?','[{"key": "A", "en": "Stotra", "hi": "स्तोत्र"}, {"key": "B", "en": "Japa", "hi": "जप"}, {"key": "C", "en": "Homa", "hi": "होम"}, {"key": "D", "en": "Dhyana", "hi": "ध्यान"}]','B');
INSERT INTO knowledge_quiz VALUES(2957,'Which Hindu festival celebrates the changing of seasons?','ऋतु परिवर्तन का उत्सव कौन सा पर्व है?','[{"key": "A", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}, {"key": "B", "en": "Holi", "hi": "होली"}, {"key": "C", "en": "Vasant Panchami", "hi": "वसंत पंचमी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2958,'Which sacred direction is associated with ancestors?','पूर्वजों से जुड़ी पवित्र दिशा कौन सी मानी जाती है?','[{"key": "A", "en": "East", "hi": "पूर्व"}, {"key": "B", "en": "West", "hi": "पश्चिम"}, {"key": "C", "en": "South", "hi": "दक्षिण"}, {"key": "D", "en": "North", "hi": "उत्तर"}]','C');
INSERT INTO knowledge_quiz VALUES(2959,'Which Hindu deity is invoked during house construction?','गृह निर्माण के समय किस देवता की पूजा की जाती है?','[{"key": "A", "en": "Vishwakarma", "hi": "विश्वकर्मा"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Vastu Purusha", "hi": "वास्तु पुरुष"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2960,'Which Hindu belief explains duties based on one''s role in life?','जीवन में भूमिका के अनुसार कर्तव्यों की व्याख्या कौन सी धारणा करती है?','[{"key": "A", "en": "Sanatana Dharma", "hi": "सनातन धर्म"}, {"key": "B", "en": "Varna Dharma", "hi": "वर्ण धर्म"}, {"key": "C", "en": "Svadharma", "hi": "स्वधर्म"}, {"key": "D", "en": "Ashrama Dharma", "hi": "आश्रम धर्म"}]','C');
INSERT INTO knowledge_quiz VALUES(2961,'Which ancient Hindu concept emphasizes non-violence?','अहिंसा पर बल देने वाली अवधारणा कौन सी है?','[{"key": "A", "en": "Satya", "hi": "सत्य"}, {"key": "B", "en": "Ahimsa", "hi": "अहिंसा"}, {"key": "C", "en": "Daya", "hi": "दया"}, {"key": "D", "en": "Shanti", "hi": "शांति"}]','B');
INSERT INTO knowledge_quiz VALUES(2962,'What is the name of the rock that saved the Kedarnath temple during the 2013 floods?','2013 की बाढ़ के दौरान केदारनाथ मंदिर को बचाने वाली चट्टान का नाम क्या है?','[{"key": "A", "en": "Bheem Shila", "hi": "भीम शिला"}, {"key": "B", "en": "Divya Shila", "hi": "दिव्य शिला"}, {"key": "C", "en": "Narad Shila", "hi": "नारद शिला"}, {"key": "D", "en": "Garud Shila", "hi": "गरुड़ शिला"}]','A');
INSERT INTO knowledge_quiz VALUES(2963,'Which Hindu scripture explains the philosophy of yoga?','योग दर्शन की व्याख्या किस ग्रंथ में है?','[{"key": "A", "en": "Bhagavad Gita", "hi": "भगवद्गीता"}, {"key": "B", "en": "Yoga Sutra", "hi": "योग सूत्र"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2964,'Which Hindu ritual symbolizes feeding the universe?','संपूर्ण ब्रह्मांड को भोजन कराने का प्रतीक कौन सा कर्म है?','[{"key": "A", "en": "Annadanam", "hi": "अन्नदान"}, {"key": "B", "en": "Yajna", "hi": "यज्ञ"}, {"key": "C", "en": "Homa", "hi": "होम"}, {"key": "D", "en": "Shraddha", "hi": "श्राद्ध"}]','A');
INSERT INTO knowledge_quiz VALUES(2965,'Which Hindu belief sees divinity in all living beings?','सभी जीवों में ईश्वर को देखने वाली धारणा कौन सी है?','[{"key": "A", "en": "Vasudhaiva Kutumbakam", "hi": "वसुधैव कुटुम्बकम्"}, {"key": "B", "en": "Sarvam Khalvidam Brahma", "hi": "सर्वं खल्विदं ब्रह्म"}, {"key": "C", "en": "Tat Tvam Asi", "hi": "तत्त्वमसि"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2966,'In Ayodhya, which temple is famous for having 76 steps and is dedicated to the ''protector'' of the city?','अयोध्या में कौन सा मंदिर 76 सीढ़ियों के लिए प्रसिद्ध है और शहर के ''रक्षक'' को समर्पित है?','[{"key": "A", "en": "Kanak Bhawan", "hi": "कनक भवन"}, {"key": "B", "en": "Hanuman Garhi", "hi": "हनुमान गढ़ी"}, {"key": "C", "en": "Nageshwarnath Temple", "hi": "नागेश्वरनाथ मंदिर"}, {"key": "D", "en": "Ram Janmabhoomi", "hi": "राम जन्मभूमि"}]','B');
INSERT INTO knowledge_quiz VALUES(2967,'Which Hindu deity symbolizes cosmic dance?','ब्रह्मांडीय नृत्य का प्रतीक कौन सा देवता है?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Shiva Nataraja", "hi": "शिव नटराज"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','B');
INSERT INTO knowledge_quiz VALUES(2968,'Which ancient Hindu festival is linked with ancestor remembrance?','पूर्वजों की स्मृति से जुड़ा कौन सा प्राचीन पर्व है?','[{"key": "A", "en": "Shraddha", "hi": "श्राद्ध"}, {"key": "B", "en": "Pitru Paksha", "hi": "पितृ पक्ष"}, {"key": "C", "en": "Amavasya", "hi": "अमावस्या"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2969,'Which Hindu concept emphasizes balance between material and spiritual life?','भौतिक और आध्यात्मिक जीवन के संतुलन पर कौन सी अवधारणा बल देती है?','[{"key": "A", "en": "Purusharthas", "hi": "पुरुषार्थ"}, {"key": "B", "en": "Bhakti", "hi": "भक्ति"}, {"key": "C", "en": "Yoga", "hi": "योग"}, {"key": "D", "en": "Tapasya", "hi": "तपस्या"}]','A');
INSERT INTO knowledge_quiz VALUES(2970,'Which sacred animal is considered the carrier of prayers to ancestors?','प्रार्थनाओं को पूर्वज तक पहुँचाने वाला पवित्र पशु कौन सा माना जाता है?','[{"key": "A", "en": "Cow", "hi": "गाय"}, {"key": "B", "en": "Horse", "hi": "घोड़ा"}, {"key": "C", "en": "Bull", "hi": "बैल"}, {"key": "D", "en": "Crow", "hi": "कौआ"}]','D');
INSERT INTO knowledge_quiz VALUES(2971,'Which Vedic deity is associated with cosmic order and truth?','ब्रह्मांडीय नियम और सत्य से कौन सा वैदिक देवता जुड़ा है?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Varuna", "hi": "वरुण"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Soma", "hi": "सोम"}]','B');
INSERT INTO knowledge_quiz VALUES(2972,'Which ancient Hindu text explains duties during times of crisis (Apaddharma)?','आपद्कालीन धर्म (आपद्धर्म) का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Arthashastra", "hi": "अर्थशास्त्र"}, {"key": "D", "en": "Vedas", "hi": "वेद"}]','B');
INSERT INTO knowledge_quiz VALUES(2973,'Which Hindu concept describes the latent impressions of past actions?','पूर्व कर्मों के संस्कारों को कौन सी अवधारणा बताती है?','[{"key": "A", "en": "Karma", "hi": "कर्म"}, {"key": "B", "en": "Vasana", "hi": "वासनाएँ"}, {"key": "C", "en": "Samskara", "hi": "संस्कार"}, {"key": "D", "en": "Maya", "hi": "माया"}]','C');
INSERT INTO knowledge_quiz VALUES(2974,'Which Purana gives the most detailed description of pilgrimages (Tirthas)?','तीर्थों का विस्तृत वर्णन किस पुराण में मिलता है?','[{"key": "A", "en": "Skanda Purana", "hi": "स्कंद पुराण"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Agni Purana", "hi": "अग्नि पुराण"}, {"key": "D", "en": "Brahma Purana", "hi": "ब्रह्म पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(2975,'Which Hindu goddess is worshipped in the form of a yantra without an idol?','मूर्ति के बिना यंत्र रूप में किस देवी की पूजा होती है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Kali", "hi": "काली"}, {"key": "C", "en": "Tripura Sundari", "hi": "त्रिपुरा सुंदरी"}, {"key": "D", "en": "Lakshmi", "hi": "लक्ष्मी"}]','C');
INSERT INTO knowledge_quiz VALUES(2976,'Which ancient Hindu system classifies human personality into three Gunas?','मानव स्वभाव को तीन गुणों में बाँटने वाली प्रणाली कौन सी है?','[{"key": "A", "en": "Yoga", "hi": "योग"}, {"key": "B", "en": "Vedanta", "hi": "वेदांत"}, {"key": "C", "en": "Samkhya", "hi": "सांख्य"}, {"key": "D", "en": "Nyaya", "hi": "न्याय"}]','C');
INSERT INTO knowledge_quiz VALUES(2977,'Which Hindu ritual involves offering water to the Sun at dawn?','सूर्योदय पर सूर्य को जल अर्पित करने की परंपरा क्या कहलाती है?','[{"key": "A", "en": "Sandhya Vandana", "hi": "संध्या वंदन"}, {"key": "B", "en": "Surya Namaskar", "hi": "सूर्य नमस्कार"}, {"key": "C", "en": "Tarpana", "hi": "तर्पण"}, {"key": "D", "en": "Homa", "hi": "होम"}]','A');
INSERT INTO knowledge_quiz VALUES(2978,'Which sacred syllable is associated with Goddess Lakshmi?','देवी लक्ष्मी से जुड़ा बीज अक्षर कौन सा है?','[{"key": "A", "en": "Hreem", "hi": "ह्रीं"}, {"key": "B", "en": "Shreem", "hi": "श्रीं"}, {"key": "C", "en": "Kreem", "hi": "क्रीं"}, {"key": "D", "en": "Aim", "hi": "ऐं"}]','B');
INSERT INTO knowledge_quiz VALUES(2979,'Which Hindu belief explains the subtle body (Sukshma Sharira)?','सूक्ष्म शरीर की अवधारणा किस दर्शन में मिलती है?','[{"key": "A", "en": "Vedanta", "hi": "वेदांत"}, {"key": "B", "en": "Samkhya", "hi": "सांख्य"}, {"key": "C", "en": "Yoga", "hi": "योग"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2980,'Which ancient Hindu text discusses omens and signs?','शकुन और लक्षणों का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Brihat Samhita", "hi": "बृहत संहिता"}, {"key": "B", "en": "Narada Purana", "hi": "नारद पुराण"}, {"key": "C", "en": "Atharvaveda", "hi": "अथर्ववेद"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','A');
INSERT INTO knowledge_quiz VALUES(2981,'Which Hindu deity is worshipped as the personification of fire in rituals?','अनुष्ठानों में अग्नि के स्वरूप में किस देवता की पूजा होती है?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','A');
INSERT INTO knowledge_quiz VALUES(2982,'Which concept refers to disciplined austerity in Hinduism?','अनुशासित तपस्या को कौन सी अवधारणा कहा जाता है?','[{"key": "A", "en": "Tapas", "hi": "तपस"}, {"key": "B", "en": "Yoga", "hi": "योग"}, {"key": "C", "en": "Vrata", "hi": "व्रत"}, {"key": "D", "en": "Sannyasa", "hi": "संन्यास"}]','A');
INSERT INTO knowledge_quiz VALUES(2983,'Which Hindu festival is linked with the worship of serpents?','सर्प पूजा से जुड़ा कौन सा पर्व है?','[{"key": "A", "en": "Nag Panchami", "hi": "नाग पंचमी"}, {"key": "B", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}, {"key": "C", "en": "Raksha Bandhan", "hi": "रक्षा बंधन"}, {"key": "D", "en": "Kartika Purnima", "hi": "कार्तिक पूर्णिमा"}]','A');
INSERT INTO knowledge_quiz VALUES(2984,'Which Hindu scripture emphasizes devotion through music and stories?','संगीत और कथाओं द्वारा भक्ति पर बल देने वाला ग्रंथ कौन सा है?','[{"key": "A", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "D", "en": "Skanda Purana", "hi": "स्कंद पुराण"}]','A');
INSERT INTO knowledge_quiz VALUES(2985,'Which Hindu belief connects breath with life force?','श्वास को जीवन शक्ति से जोड़ने वाली अवधारणा कौन सी है?','[{"key": "A", "en": "Prana", "hi": "प्राण"}, {"key": "B", "en": "Apana", "hi": "अपान"}, {"key": "C", "en": "Udana", "hi": "उदान"}, {"key": "D", "en": "Samana", "hi": "समान"}]','A');
INSERT INTO knowledge_quiz VALUES(2986,'Which Hindu temple tradition involves daily offering of thousands of meals?','प्रतिदिन हजारों भोजन अर्पित करने की परंपरा किस मंदिर से जुड़ी है?','[{"key": "A", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}, {"key": "B", "en": "Tirupati Temple", "hi": "तिरुपति मंदिर"}, {"key": "C", "en": "Golden Temple", "hi": "स्वर्ण मंदिर"}, {"key": "D", "en": "Srirangam Temple", "hi": "श्रीरंगम मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(2987,'Which Hindu deity is associated with wisdom and intelligence?','बुद्धि और विवेक से कौन सा देवता जुड़ा है?','[{"key": "A", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Ganesha", "hi": "गणेश"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2988,'Which Hindu concept describes renunciation after fulfilling duties?','कर्तव्यों की पूर्ति के बाद त्याग की अवस्था को क्या कहा जाता है?','[{"key": "A", "en": "Vanaprastha", "hi": "वानप्रस्थ"}, {"key": "B", "en": "Sannyasa", "hi": "संन्यास"}, {"key": "C", "en": "Brahmacharya", "hi": "ब्रह्मचर्य"}, {"key": "D", "en": "Grihastha", "hi": "गृहस्थ"}]','A');
INSERT INTO knowledge_quiz VALUES(2989,'Which sacred sound is believed to awaken spiritual energy?','आध्यात्मिक ऊर्जा को जाग्रत करने वाली ध्वनि कौन सी मानी जाती है?','[{"key": "A", "en": "Om", "hi": "ॐ"}, {"key": "B", "en": "Hreem", "hi": "ह्रीं"}, {"key": "C", "en": "Kundalini", "hi": "कुण्डलिनी"}, {"key": "D", "en": "Nada", "hi": "नाद"}]','A');
INSERT INTO knowledge_quiz VALUES(2990,'Which Hindu text explains duties of women and family life?','स्त्री और पारिवारिक जीवन के कर्तव्यों का वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Manusmriti", "hi": "मनुस्मृति"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Smritis", "hi": "स्मृतियाँ"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2991,'Which Hindu deity is regarded as the first guru (Adi Guru)?','आदि गुरु के रूप में किस देवता को माना जाता है?','[{"key": "A", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Dakshinamurti", "hi": "दक्षिणामूर्ति"}]','D');
INSERT INTO knowledge_quiz VALUES(2992,'Which Hindu practice emphasizes silence as spiritual discipline?','मौन को साधना मानने वाली प्रथा कौन सी है?','[{"key": "A", "en": "Mauna", "hi": "मौन"}, {"key": "B", "en": "Dhyana", "hi": "ध्यान"}, {"key": "C", "en": "Tapas", "hi": "तपस"}, {"key": "D", "en": "Japa", "hi": "जप"}]','A');
INSERT INTO knowledge_quiz VALUES(2993,'Which Hindu belief links food with spiritual purity?','भोजन को आध्यात्मिक शुद्धता से जोड़ने वाली अवधारणा कौन सी है?','[{"key": "A", "en": "Ahara", "hi": "आहार"}, {"key": "B", "en": "Satvik Diet", "hi": "सात्त्विक आहार"}, {"key": "C", "en": "Prasada", "hi": "प्रसाद"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2994,'Which Hindu symbol represents cyclical time?','चक्राकार समय का प्रतीक कौन सा चिन्ह है?','[{"key": "A", "en": "Chakra", "hi": "चक्र"}, {"key": "B", "en": "Swastika", "hi": "स्वस्तिक"}, {"key": "C", "en": "Mandala", "hi": "मंडल"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2995,'Which Hindu belief views the universe as a cosmic sacrifice?','ब्रह्मांड को यज्ञ के रूप में देखने वाली धारणा कौन सी है?','[{"key": "A", "en": "Purusha Sukta", "hi": "पुरुष सूक्त"}, {"key": "B", "en": "Nasadiya Sukta", "hi": "नासदीय सूक्त"}, {"key": "C", "en": "Hiranyagarbha Sukta", "hi": "हिरण्यगर्भ सूक्त"}, {"key": "D", "en": "Gayatri Mantra", "hi": "गायत्री मंत्र"}]','A');
INSERT INTO knowledge_quiz VALUES(2996,'Which of these deities are placed on either side of Lord Ganesha in the main temple?','मुख्य मंदिर में भगवान गणेश के दोनों ओर इनमें से कौन सी देवियां विराजमान हैं?','[{"key": "A", "en": "Lakshmi and Saraswati", "hi": "लक्ष्मी और सरस्वती"}, {"key": "B", "en": "Riddhi and Siddhi", "hi": "रिद्धि और सिद्धि"}, {"key": "C", "en": "Ganga and Yamuna", "hi": "गंगा और यमुना"}, {"key": "D", "en": "Jaya and Vijaya", "hi": "जया और विजया"}]','B');
INSERT INTO knowledge_quiz VALUES(2997,'Which Hindu concept teaches detachment while performing duties?','कर्तव्य करते हुए आसक्ति त्याग सिखाने वाली अवधारणा कौन सी है?','[{"key": "A", "en": "Bhakti Yoga", "hi": "भक्ति योग"}, {"key": "B", "en": "Jnana Yoga", "hi": "ज्ञान योग"}, {"key": "C", "en": "Karma Yoga", "hi": "कर्म योग"}, {"key": "D", "en": "Raja Yoga", "hi": "राज योग"}]','C');
INSERT INTO knowledge_quiz VALUES(2998,'Which sacred geometry diagram represents the universe?','ब्रह्मांड का प्रतिनिधित्व करने वाला पवित्र ज्यामितीय चित्र कौन सा है?','[{"key": "A", "en": "Yantra", "hi": "यंत्र"}, {"key": "B", "en": "Sri Chakra", "hi": "श्री चक्र"}, {"key": "C", "en": "Mandala", "hi": "मंडल"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(2999,'Which Hindu belief emphasizes respect for teachers?','गुरुओं के प्रति सम्मान पर बल देने वाली धारणा कौन सी है?','[{"key": "A", "en": "Guru-Shishya Parampara", "hi": "गुरु-शिष्य परंपरा"}, {"key": "B", "en": "Bhakti", "hi": "भक्ति"}, {"key": "C", "en": "Seva", "hi": "सेवा"}, {"key": "D", "en": "Tapasya", "hi": "तपस्या"}]','A');
INSERT INTO knowledge_quiz VALUES(3000,'Which Hindu worldview sees life as a sacred journey toward liberation?','जीवन को मोक्ष की ओर पवित्र यात्रा मानने वाला दृष्टिकोण कौन सा है?','[{"key": "A", "en": "Sanatana Dharma", "hi": "सनातन धर्म"}, {"key": "B", "en": "Purushartha", "hi": "पुरुषार्थ"}, {"key": "C", "en": "Yoga", "hi": "योग"}, {"key": "D", "en": "Vedanta", "hi": "वेदांत"}]','A');
INSERT INTO knowledge_quiz VALUES(3001,'What are the five elements of the Hindu Panchang?','हिंदू पंचांग के पाँच अंग कौन-कौन से हैं?','[{"key": "A", "en": "Tithi, Vara, Nakshatra, Yoga, Karana", "hi": "तिथि, वार, नक्षत्र, योग, करण"}, {"key": "B", "en": "Tithi, Masa, Paksha, Yoga, Karana", "hi": "तिथि, मास, पक्ष, योग, करण"}, {"key": "C", "en": "Vara, Masa, Ritu, Yoga, Karana", "hi": "वार, मास, ऋतु, योग, करण"}, {"key": "D", "en": "Nakshatra, Yoga, Rashi, Karana, Masa", "hi": "नक्षत्र, योग, राशि, करण, मास"}]','A');
INSERT INTO knowledge_quiz VALUES(3002,'Which element of Panchang is based on lunar days?','पंचांग का कौन सा अंग चंद्र दिवसों पर आधारित है?','[{"key": "A", "en": "Vara", "hi": "वार"}, {"key": "B", "en": "Tithi", "hi": "तिथि"}, {"key": "C", "en": "Yoga", "hi": "योग"}, {"key": "D", "en": "Karana", "hi": "करण"}]','B');
INSERT INTO knowledge_quiz VALUES(3003,'How many Tithis are there in a lunar month?','एक चंद्र मास में कुल कितनी तिथियाँ होती हैं?','[{"key": "A", "en": "28", "hi": "28"}, {"key": "B", "en": "30", "hi": "30"}, {"key": "C", "en": "27", "hi": "27"}, {"key": "D", "en": "31", "hi": "31"}]','B');
INSERT INTO knowledge_quiz VALUES(3004,'Which Paksha begins after Amavasya?','अमावस्या के बाद कौन सा पक्ष प्रारंभ होता है?','[{"key": "A", "en": "Krishna Paksha", "hi": "कृष्ण पक्ष"}, {"key": "B", "en": "Shukla Paksha", "hi": "शुक्ल पक्ष"}, {"key": "C", "en": "Adhika Paksha", "hi": "अधिक पक्ष"}, {"key": "D", "en": "Kshaya Paksha", "hi": "क्षय पक्ष"}]','B');
INSERT INTO knowledge_quiz VALUES(3005,'Which Paksha ends with Purnima?','पूर्णिमा किस पक्ष में आती है?','[{"key": "A", "en": "Krishna Paksha", "hi": "कृष्ण पक्ष"}, {"key": "B", "en": "Shukla Paksha", "hi": "शुक्ल पक्ष"}, {"key": "C", "en": "Adhika Paksha", "hi": "अधिक पक्ष"}, {"key": "D", "en": "None", "hi": "कोई नहीं"}]','B');
INSERT INTO knowledge_quiz VALUES(3006,'Which Panchang element is based on the weekday?','पंचांग का कौन सा अंग सप्ताह के दिन पर आधारित है?','[{"key": "A", "en": "Tithi", "hi": "तिथि"}, {"key": "B", "en": "Vara", "hi": "वार"}, {"key": "C", "en": "Nakshatra", "hi": "नक्षत्र"}, {"key": "D", "en": "Karana", "hi": "करण"}]','B');
INSERT INTO knowledge_quiz VALUES(3007,'How many Nakshatras are used in the Hindu Panchang?','हिंदू पंचांग में कुल कितने नक्षत्र होते हैं?','[{"key": "A", "en": "12", "hi": "12"}, {"key": "B", "en": "27", "hi": "27"}, {"key": "C", "en": "28", "hi": "28"}, {"key": "D", "en": "30", "hi": "30"}]','B');
INSERT INTO knowledge_quiz VALUES(3008,'Which Nakshatra is considered the first in sequence?','नक्षत्रों में प्रथम नक्षत्र कौन सा है?','[{"key": "A", "en": "Ashwini", "hi": "अश्विनी"}, {"key": "B", "en": "Bharani", "hi": "भरणी"}, {"key": "C", "en": "Krittika", "hi": "कृत्तिका"}, {"key": "D", "en": "Rohini", "hi": "रोहिणी"}]','A');
INSERT INTO knowledge_quiz VALUES(3009,'Which Panchang element is formed by the sum of Sun and Moon positions?','सूर्य और चंद्र की स्थिति के योग से कौन सा अंग बनता है?','[{"key": "A", "en": "Karana", "hi": "करण"}, {"key": "B", "en": "Yoga", "hi": "योग"}, {"key": "C", "en": "Tithi", "hi": "तिथि"}, {"key": "D", "en": "Nakshatra", "hi": "नक्षत्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3010,'How many Yogas are there in Panchang?','पंचांग में कुल कितने योग होते हैं?','[{"key": "A", "en": "12", "hi": "12"}, {"key": "B", "en": "27", "hi": "27"}, {"key": "C", "en": "30", "hi": "30"}, {"key": "D", "en": "60", "hi": "60"}]','B');
INSERT INTO knowledge_quiz VALUES(3011,'Which Panchang element divides a Tithi into two halves?','तिथि को दो भागों में बाँटने वाला अंग कौन सा है?','[{"key": "A", "en": "Yoga", "hi": "योग"}, {"key": "B", "en": "Karana", "hi": "करण"}, {"key": "C", "en": "Vara", "hi": "वार"}, {"key": "D", "en": "Nakshatra", "hi": "नक्षत्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3012,'How many Karanas are there in total?','कुल कितने करण होते हैं?','[{"key": "A", "en": "7", "hi": "7"}, {"key": "B", "en": "11", "hi": "11"}, {"key": "C", "en": "27", "hi": "27"}, {"key": "D", "en": "30", "hi": "30"}]','B');
INSERT INTO knowledge_quiz VALUES(3013,'Which Karana occurs only once in a lunar month?','कौन सा करण चंद्र मास में केवल एक बार आता है?','[{"key": "A", "en": "Bava", "hi": "बव"}, {"key": "B", "en": "Balava", "hi": "बालव"}, {"key": "C", "en": "Kimstughna", "hi": "किंस्तुघ्न"}, {"key": "D", "en": "Kaulava", "hi": "कौलव"}]','C');
INSERT INTO knowledge_quiz VALUES(3014,'Which month is considered the first month of the Hindu lunar calendar?','हिंदू चंद्र कैलेंडर का पहला महीना कौन सा है?','[{"key": "A", "en": "Chaitra", "hi": "चैत्र"}, {"key": "B", "en": "Vaishakha", "hi": "वैशाख"}, {"key": "C", "en": "Kartika", "hi": "कार्तिक"}, {"key": "D", "en": "Ashadha", "hi": "आषाढ़"}]','A');
INSERT INTO knowledge_quiz VALUES(3015,'Which month is known for the festival of Diwali?','दीवाली किस मास में आती है?','[{"key": "A", "en": "Ashwin", "hi": "आश्विन"}, {"key": "B", "en": "Kartika", "hi": "कार्तिक"}, {"key": "C", "en": "Bhadrapada", "hi": "भाद्रपद"}, {"key": "D", "en": "Margashirsha", "hi": "मार्गशीर्ष"}]','B');
INSERT INTO knowledge_quiz VALUES(3016,'Which Panchang concept refers to an extra lunar month?','अतिरिक्त चंद्र मास को क्या कहा जाता है?','[{"key": "A", "en": "Kshaya Masa", "hi": "क्षय मास"}, {"key": "B", "en": "Adhika Masa", "hi": "अधिक मास"}, {"key": "C", "en": "Nija Masa", "hi": "निज मास"}, {"key": "D", "en": "Saura Masa", "hi": "सौर मास"}]','B');
INSERT INTO knowledge_quiz VALUES(3017,'Which time period is considered inauspicious in Panchang?','पंचांग में कौन सा समय अशुभ माना जाता है?','[{"key": "A", "en": "Abhijit Muhurta", "hi": "अभिजीत मुहूर्त"}, {"key": "B", "en": "Rahu Kalam", "hi": "राहु काल"}, {"key": "C", "en": "Brahma Muhurta", "hi": "ब्रह्म मुहूर्त"}, {"key": "D", "en": "Amrit Kalam", "hi": "अमृत काल"}]','B');
INSERT INTO knowledge_quiz VALUES(3018,'Which Muhurta is considered highly auspicious for new beginnings?','नए कार्यों के लिए कौन सा मुहूर्त अत्यंत शुभ माना जाता है?','[{"key": "A", "en": "Rahu Kalam", "hi": "राहु काल"}, {"key": "B", "en": "Abhijit Muhurta", "hi": "अभिजीत मुहूर्त"}, {"key": "C", "en": "Yamaganda", "hi": "यमगंड"}, {"key": "D", "en": "Gulika Kalam", "hi": "गुलिक काल"}]','B');
INSERT INTO knowledge_quiz VALUES(3019,'Which Panchang element is mainly used to determine marriage compatibility?','विवाह मिलान में मुख्य रूप से किस अंग का उपयोग होता है?','[{"key": "A", "en": "Tithi", "hi": "तिथि"}, {"key": "B", "en": "Nakshatra", "hi": "नक्षत्र"}, {"key": "C", "en": "Vara", "hi": "वार"}, {"key": "D", "en": "Karana", "hi": "करण"}]','B');
INSERT INTO knowledge_quiz VALUES(3020,'Which Nakshatra is traditionally associated with Lord Krishna’s birth?','भगवान कृष्ण के जन्म से कौन सा नक्षत्र जुड़ा है?','[{"key": "A", "en": "Rohini", "hi": "रोहिणी"}, {"key": "B", "en": "Ashwini", "hi": "अश्विनी"}, {"key": "C", "en": "Revati", "hi": "रेवती"}, {"key": "D", "en": "Shravana", "hi": "श्रवण"}]','A');
INSERT INTO knowledge_quiz VALUES(3021,'Which Hindu festival is associated with the worship of cattle and bulls?','पशु और बैलों की पूजा से जुड़ा कौन सा हिंदू पर्व है?','[{"key": "A", "en": "Gopashtami", "hi": "गोपाष्टमी"}, {"key": "B", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "C", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}, {"key": "D", "en": "Pola", "hi": "पोला"}]','D');
INSERT INTO knowledge_quiz VALUES(3022,'Which festival commemorates the birth of Goddess Ganga on Earth?','धरती पर गंगा के अवतरण की स्मृति में कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Ganga Dussehra", "hi": "गंगा दशहरा"}, {"key": "B", "en": "Ganga Jayanti", "hi": "गंगा जयंती"}, {"key": "C", "en": "Kartika Purnima", "hi": "कार्तिक पूर्णिमा"}, {"key": "D", "en": "Magha Purnima", "hi": "माघ पूर्णिमा"}]','A');
INSERT INTO knowledge_quiz VALUES(3023,'Which Hindu festival is dedicated to brothers praying for their sisters’ well-being?','बहनों की मंगल कामना के लिए भाइयों द्वारा मनाया जाने वाला पर्व कौन सा है?','[{"key": "A", "en": "Raksha Bandhan", "hi": "रक्षा बंधन"}, {"key": "B", "en": "Bhai Dooj", "hi": "भाई दूज"}, {"key": "C", "en": "Karwa Chauth", "hi": "करवा चौथ"}, {"key": "D", "en": "Teej", "hi": "तीज"}]','B');
INSERT INTO knowledge_quiz VALUES(3024,'Which festival marks the end of the monsoon season in many regions?','कई क्षेत्रों में मानसून की समाप्ति का संकेत कौन सा पर्व देता है?','[{"key": "A", "en": "Sharad Purnima", "hi": "शरद पूर्णिमा"}, {"key": "B", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "C", "en": "Onam", "hi": "ओणम"}, {"key": "D", "en": "Anant Chaturdashi", "hi": "अनंत चतुर्दशी"}]','A');
INSERT INTO knowledge_quiz VALUES(3025,'Which Hindu festival is celebrated to honor tools, machines, and weapons?','औजारों, मशीनों और अस्त्र-शस्त्रों की पूजा का पर्व कौन सा है?','[{"key": "A", "en": "Ayudha Puja", "hi": "आयुध पूजा"}, {"key": "B", "en": "Vishwakarma Puja", "hi": "विश्वकर्मा पूजा"}, {"key": "C", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}, {"key": "D", "en": "Both A and B", "hi": "A और B दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(3026,'Which festival is believed to be the night when divine nectar falls on Earth?','किस पर्व की रात्रि को अमृत वर्षा होने की मान्यता है?','[{"key": "A", "en": "Maha Shivaratri", "hi": "महाशिवरात्रि"}, {"key": "B", "en": "Sharad Purnima", "hi": "शरद पूर्णिमा"}, {"key": "C", "en": "Kartika Purnima", "hi": "कार्तिक पूर्णिमा"}, {"key": "D", "en": "Magha Purnima", "hi": "माघ पूर्णिमा"}]','B');
INSERT INTO knowledge_quiz VALUES(3027,'Which festival celebrates the victory of King Mahabali in Kerala?','केरल में राजा महाबली की स्मृति में कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Vishu", "hi": "विशु"}, {"key": "B", "en": "Onam", "hi": "ओणम"}, {"key": "C", "en": "Thiruvathira", "hi": "तिरुवातिरा"}, {"key": "D", "en": "Navratri", "hi": "नवरात्रि"}]','B');
INSERT INTO knowledge_quiz VALUES(3028,'What is the divine weapon associated with Lord Murugan?','भगवान मुरुगन से जुड़ा दिव्य शस्त्र कौन सा है?','[{"key": "A", "en": "Trishul", "hi": "त्रिशूल"}, {"key": "B", "en": "Vel (Spear)", "hi": "वेल (भाला)"}, {"key": "C", "en": "Sudarshana Chakra", "hi": "सुदर्शन चक्र"}, {"key": "D", "en": "Gada", "hi": "गदा"}]','B');
INSERT INTO knowledge_quiz VALUES(3029,'Which festival involves worship of young girls as forms of the Goddess?','कन्याओं को देवी स्वरूप मानकर पूजा करने वाला पर्व कौन सा है?','[{"key": "A", "en": "Kanya Puja", "hi": "कन्या पूजा"}, {"key": "B", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "C", "en": "Durga Ashtami", "hi": "दुर्गा अष्टमी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3030,'Which festival marks the end of Ganesh Chaturthi celebrations?','गणेश चतुर्थी उत्सव का समापन किस दिन होता है?','[{"key": "A", "en": "Anant Chaturdashi", "hi": "अनंत चतुर्दशी"}, {"key": "B", "en": "Bhadrapada Purnima", "hi": "भाद्रपद पूर्णिमा"}, {"key": "C", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "D", "en": "Sankashti Chaturthi", "hi": "संकष्टी चतुर्थी"}]','A');
INSERT INTO knowledge_quiz VALUES(3031,'Which Hindu festival celebrates the bond between a married woman and her husband through fasting?','विवाहित स्त्री द्वारा पति की दीर्घायु के लिए उपवास रखने वाला पर्व कौन सा है?','[{"key": "A", "en": "Teej", "hi": "तीज"}, {"key": "B", "en": "Karwa Chauth", "hi": "करवा चौथ"}, {"key": "C", "en": "Vat Savitri", "hi": "वट सावित्री"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3032,'Which festival celebrates the lifting of Govardhan Hill by Lord Krishna?','भगवान कृष्ण द्वारा गोवर्धन पर्वत उठाने की स्मृति में कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Janmashtami", "hi": "जन्माष्टमी"}, {"key": "B", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "C", "en": "Annakut", "hi": "अन्नकूट"}, {"key": "D", "en": "Both B and C", "hi": "B और C दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(3033,'Which festival is associated with swinging rituals and monsoon joy?','झूला झूलने और मानसून उत्सव से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Teej", "hi": "तीज"}, {"key": "B", "en": "Holi", "hi": "होली"}, {"key": "C", "en": "Vasant Panchami", "hi": "वसंत पंचमी"}, {"key": "D", "en": "Baisakhi", "hi": "बैसाखी"}]','A');
INSERT INTO knowledge_quiz VALUES(3034,'Which festival is believed to grant liberation to ancestors when rituals are performed at Gaya?','गया में अनुष्ठान करने से पितरों को मोक्ष देने वाला पर्व कौन सा है?','[{"key": "A", "en": "Pitru Paksha", "hi": "पितृ पक्ष"}, {"key": "B", "en": "Amavasya", "hi": "अमावस्या"}, {"key": "C", "en": "Magha Mela", "hi": "माघ मेला"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','A');
INSERT INTO knowledge_quiz VALUES(3035,'Which festival celebrates the arrival of spring and harvest together?','वसंत ऋतु और फसल दोनों के आगमन का पर्व कौन सा है?','[{"key": "A", "en": "Holi", "hi": "होली"}, {"key": "B", "en": "Baisakhi", "hi": "बैसाखी"}, {"key": "C", "en": "Vasant Panchami", "hi": "वसंत पंचमी"}, {"key": "D", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}]','A');
INSERT INTO knowledge_quiz VALUES(3036,'Which festival is associated with floating lamps on rivers and water bodies?','नदियों और जलाशयों में दीप प्रवाहित करने से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Kartika Purnima", "hi": "कार्तिक पूर्णिमा"}, {"key": "B", "en": "Dev Deepawali", "hi": "देव दीपावली"}, {"key": "C", "en": "Ganga Dussehra", "hi": "गंगा दशहरा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3037,'Which festival marks the traditional Hindu New Year in many regions?','कई क्षेत्रों में हिंदू नववर्ष के रूप में कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Gudi Padwa", "hi": "गुड़ी पड़वा"}, {"key": "B", "en": "Ugadi", "hi": "उगादी"}, {"key": "C", "en": "Cheti Chand", "hi": "चेटी चंड"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3038,'The Rajiv Lochan Temple, famous for its architecture and the ''Kumbh Mela'' of Chhattisgarh, is located in which town?','राजीव लोचन मंदिर, जो अपनी वास्तुकला और छत्तीसगढ़ के ''कुंभ मेले'' के लिए प्रसिद्ध है, किस शहर में स्थित है?','[{"key": "A", "en": "Rajim", "hi": "राजिम"}, {"key": "B", "en": "Raipur", "hi": "रायपुर"}, {"key": "C", "en": "Bilaspur", "hi": "बिलासपुर"}, {"key": "D", "en": "Ratanpur", "hi": "रतनपुर"}]','A');
INSERT INTO knowledge_quiz VALUES(3039,'Which festival celebrates the divine love of Radha and Krishna?','राधा-कृष्ण के दिव्य प्रेम का उत्सव कौन सा है?','[{"key": "A", "en": "Holi", "hi": "होली"}, {"key": "B", "en": "Sharad Purnima", "hi": "शरद पूर्णिमा"}, {"key": "C", "en": "Janmashtami", "hi": "जन्माष्टमी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3040,'Which grain is considered the most sacred to be offered to Goddess Annapurna?','देवी अन्नपूर्णा को अर्पित किया जाने वाला सबसे पवित्र अनाज कौन सा माना जाता है?','[{"key": "A", "en": "Wheat", "hi": "गेहूं"}, {"key": "B", "en": "Barley", "hi": "जौ"}, {"key": "C", "en": "Rice", "hi": "चावल"}, {"key": "D", "en": "Maize", "hi": "मक्का"}]','C');
INSERT INTO knowledge_quiz VALUES(3041,'Which festival symbolizes the return of Lord Rama to Ayodhya?','भगवान राम के अयोध्या लौटने का प्रतीक कौन सा पर्व है?','[{"key": "A", "en": "Dussehra", "hi": "दशहरा"}, {"key": "B", "en": "Diwali", "hi": "दीवाली"}, {"key": "C", "en": "Ram Navami", "hi": "राम नवमी"}, {"key": "D", "en": "Chaitra Purnima", "hi": "चैत्र पूर्णिमा"}]','B');
INSERT INTO knowledge_quiz VALUES(3042,'Which festival involves worship of rivers, trees, and natural elements together?','नदियों, वृक्षों और प्रकृति तत्वों की सामूहिक पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Chhath Puja", "hi": "छठ पूजा"}, {"key": "B", "en": "Vana Mahotsava", "hi": "वन महोत्सव"}, {"key": "C", "en": "Kartik Purnima", "hi": "कार्तिक पूर्णिमा"}, {"key": "D", "en": "Teej", "hi": "तीज"}]','A');
INSERT INTO knowledge_quiz VALUES(3043,'Which festival is celebrated by worshipping nine forms of Goddess Durga?','देवी दुर्गा के नौ रूपों की पूजा का पर्व कौन सा है?','[{"key": "A", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "B", "en": "Durga Puja", "hi": "दुर्गा पूजा"}, {"key": "C", "en": "Chaitra Navratri", "hi": "चैत्र नवरात्रि"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3044,'Parshuram Kund, a famous Hindu pilgrimage site where devotees take a holy dip, is situated on the banks of which river?','परशुराम कुंड, एक प्रसिद्ध हिंदू तीर्थ स्थल जहाँ भक्त पवित्र डुबकी लगाते हैं, किस नदी के तट पर स्थित है?','[{"key": "A", "en": "Siang", "hi": "सियांग"}, {"key": "B", "en": "Lohit", "hi": "लोहित"}, {"key": "C", "en": "Kameng", "hi": "कामेंग"}, {"key": "D", "en": "Subansiri", "hi": "सुबनसिरी"}]','B');
INSERT INTO knowledge_quiz VALUES(3045,'Which festival is also known as Annakut in many regions?','कई क्षेत्रों में अन्नकूट के नाम से कौन सा पर्व जाना जाता है?','[{"key": "A", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "B", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}, {"key": "C", "en": "Pongal", "hi": "पोंगल"}, {"key": "D", "en": "Baisakhi", "hi": "बैसाखी"}]','A');
INSERT INTO knowledge_quiz VALUES(3046,'Which Hindu festival is celebrated to seek blessings for children?','संतान सुख की कामना के लिए कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Putrada Ekadashi", "hi": "पुत्रदा एकादशी"}, {"key": "B", "en": "Santana Saptami", "hi": "संतान सप्तमी"}, {"key": "C", "en": "Chhath Puja", "hi": "छठ पूजा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3047,'Which festival celebrates the divine marriage of Lord Shiva and Goddess Parvati?','भगवान शिव और माता पार्वती के विवाह से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Maha Shivaratri", "hi": "महाशिवरात्रि"}, {"key": "B", "en": "Teej", "hi": "तीज"}, {"key": "C", "en": "Gauri Tritiya", "hi": "गौरी तृतीया"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3048,'Which festival marks the beginning of Uttarayana, the northward journey of the Sun?','सूर्य के उत्तरायण गमन की शुरुआत किस पर्व से होती है?','[{"key": "A", "en": "Ratha Saptami", "hi": "रथ सप्तमी"}, {"key": "B", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}, {"key": "C", "en": "Magha Purnima", "hi": "माघ पूर्णिमा"}, {"key": "D", "en": "Vasant Panchami", "hi": "वसंत पंचमी"}]','B');
INSERT INTO knowledge_quiz VALUES(3049,'Which festival involves night-long vigil and chanting of mantras?','रात्रि भर जागरण और मंत्र जप से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Maha Shivaratri", "hi": "महाशिवरात्रि"}, {"key": "B", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "C", "en": "Janmashtami", "hi": "जन्माष्टमी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3050,'Which Hindu festival is associated with honoring teachers and gurus?','गुरुओं और आचार्यों के सम्मान से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Guru Purnima", "hi": "गुरु पूर्णिमा"}, {"key": "B", "en": "Vyas Puja", "hi": "व्यास पूजा"}, {"key": "C", "en": "Ashadha Purnima", "hi": "आषाढ़ पूर्णिमा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3051,'Which festival in Tamil Nadu involves worshipping rain and clouds for agriculture?','तमिलनाडु में वर्षा और बादलों की पूजा से जुड़ा कौन सा पर्व है?','[{"key": "A", "en": "Aadi Perukku", "hi": "आदि पेरुक्कु"}, {"key": "B", "en": "Pongal", "hi": "पोंगल"}, {"key": "C", "en": "Thai Poosam", "hi": "थाई पूसम"}, {"key": "D", "en": "Karthigai Deepam", "hi": "कार्तिगै दीपम"}]','A');
INSERT INTO knowledge_quiz VALUES(3052,'Which Hindu festival is associated with worship of rivers during monsoon floods?','मानसून की बाढ़ के समय नदियों की पूजा से जुड़ा कौन सा पर्व है?','[{"key": "A", "en": "Narmada Jayanti", "hi": "नर्मदा जयंती"}, {"key": "B", "en": "Aadi Perukku", "hi": "आदि पेरुक्कु"}, {"key": "C", "en": "Ganga Dussehra", "hi": "गंगा दशहरा"}, {"key": "D", "en": "Magha Mela", "hi": "माघ मेला"}]','B');
INSERT INTO knowledge_quiz VALUES(3053,'Which festival is dedicated to worshipping medicinal herbs and plants?','औषधीय जड़ी-बूटियों और पौधों की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Amla Navami", "hi": "आंवला नवमी"}, {"key": "B", "en": "Van Mahotsava", "hi": "वन महोत्सव"}, {"key": "C", "en": "Tulsi Vivah", "hi": "तुलसी विवाह"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3054,'Which festival involves worship of the Amla (Indian gooseberry) tree?','आंवला वृक्ष की पूजा से जुड़ा कौन सा पर्व है?','[{"key": "A", "en": "Amla Navami", "hi": "आंवला नवमी"}, {"key": "B", "en": "Tulsi Vivah", "hi": "तुलसी विवाह"}, {"key": "C", "en": "Kartik Purnima", "hi": "कार्तिक पूर्णिमा"}, {"key": "D", "en": "Vat Savitri", "hi": "वट सावित्री"}]','A');
INSERT INTO knowledge_quiz VALUES(3055,'Which festival celebrates the symbolic wedding of Tulsi plant and Lord Vishnu?','तुलसी पौधे और भगवान विष्णु के प्रतीकात्मक विवाह का पर्व कौन सा है?','[{"key": "A", "en": "Dev Uthani Ekadashi", "hi": "देव उठनी एकादशी"}, {"key": "B", "en": "Tulsi Vivah", "hi": "तुलसी विवाह"}, {"key": "C", "en": "Kartika Purnima", "hi": "कार्तिक पूर्णिमा"}, {"key": "D", "en": "Both A and B", "hi": "A और B दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(3056,'Which festival marks the awakening of Lord Vishnu from cosmic sleep?','भगवान विष्णु के योगनिद्रा से जागरण का पर्व कौन सा है?','[{"key": "A", "en": "Devshayani Ekadashi", "hi": "देवशयनी एकादशी"}, {"key": "B", "en": "Dev Uthani Ekadashi", "hi": "देव उठनी एकादशी"}, {"key": "C", "en": "Prabodhini Ekadashi", "hi": "प्रबोधिनी एकादशी"}, {"key": "D", "en": "Both B and C", "hi": "B और C दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(3057,'Which festival involves worship of tools by farmers and artisans in South India?','दक्षिण भारत में किसानों और कारीगरों द्वारा औजारों की पूजा का पर्व कौन सा है?','[{"key": "A", "en": "Ayudha Puja", "hi": "आयुध पूजा"}, {"key": "B", "en": "Mattu Pongal", "hi": "मट्टू पोंगल"}, {"key": "C", "en": "Vishwakarma Puja", "hi": "विश्वकर्मा पूजा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3058,'Which festival honors cattle as divine contributors to agriculture?','कृषि में योगदान के लिए पशुओं को दिव्य मानकर पूजा का पर्व कौन सा है?','[{"key": "A", "en": "Mattu Pongal", "hi": "मट्टू पोंगल"}, {"key": "B", "en": "Pola", "hi": "पोला"}, {"key": "C", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3059,'Which festival is celebrated by offering 56 varieties of food to the deity?','देवता को 56 प्रकार के भोग अर्पित करने वाला पर्व कौन सा है?','[{"key": "A", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "B", "en": "Annakut", "hi": "अन्नकूट"}, {"key": "C", "en": "Janmashtami", "hi": "जन्माष्टमी"}, {"key": "D", "en": "Both A and B", "hi": "A और B दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(3060,'Which festival in Bengal celebrates the harvest of new rice?','बंगाल में नई फसल के चावल के उत्सव का पर्व कौन सा है?','[{"key": "A", "en": "Nabanna", "hi": "नबन्ना"}, {"key": "B", "en": "Poush Parbon", "hi": "पौष पर्वण"}, {"key": "C", "en": "Durga Puja", "hi": "दुर्गा पूजा"}, {"key": "D", "en": "Ratha Yatra", "hi": "रथ यात्रा"}]','A');
INSERT INTO knowledge_quiz VALUES(3061,'Which festival celebrates the worship of Mother Earth after monsoon?','मानसून के बाद धरती माता की पूजा का पर्व कौन सा है?','[{"key": "A", "en": "Bhoomi Puja", "hi": "भूमि पूजा"}, {"key": "B", "en": "Bali Pratipada", "hi": "बलि प्रतिपदा"}, {"key": "C", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','C');
INSERT INTO knowledge_quiz VALUES(3062,'Which festival involves worship of the banyan tree by married women?','विवाहित महिलाओं द्वारा वट वृक्ष की पूजा का पर्व कौन सा है?','[{"key": "A", "en": "Vat Savitri", "hi": "वट सावित्री"}, {"key": "B", "en": "Karwa Chauth", "hi": "करवा चौथ"}, {"key": "C", "en": "Hartalika Teej", "hi": "हरतालिका तीज"}, {"key": "D", "en": "Ahoi Ashtami", "hi": "अहोई अष्टमी"}]','A');
INSERT INTO knowledge_quiz VALUES(3063,'Which festival is linked with worship of nine forms of plants symbolizing Navadurga?','नवदुर्गा के प्रतीक नौ पौधों की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Navratri Ghat Sthapana", "hi": "नवरात्रि घट स्थापना"}, {"key": "B", "en": "Batheuk Puja", "hi": "बथेउक पूजा"}, {"key": "C", "en": "Kanya Puja", "hi": "कन्या पूजा"}, {"key": "D", "en": "Akhanda Navratri", "hi": "अखंड नवरात्रि"}]','B');
INSERT INTO knowledge_quiz VALUES(3064,'Which festival is celebrated to honor serpents for protecting crops?','फसलों की रक्षा के लिए सर्पों के सम्मान में कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Nag Panchami", "hi": "नाग पंचमी"}, {"key": "B", "en": "Ananta Chaturdashi", "hi": "अनंत चतुर्दशी"}, {"key": "C", "en": "Shravan Amavasya", "hi": "श्रावण अमावस्या"}, {"key": "D", "en": "Both A and C", "hi": "A और C दोनों"}]','A');
INSERT INTO knowledge_quiz VALUES(3065,'Which festival is associated with worship of ancestors using sesame seeds?','तिल द्वारा पितरों की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Pitru Paksha", "hi": "पितृ पक्ष"}, {"key": "B", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}, {"key": "C", "en": "Amavasya", "hi": "अमावस्या"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3066,'Which festival is celebrated to ward off evil spirits from homes?','घरों से नकारात्मक शक्तियों को दूर रखने के लिए कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Naraka Chaturdashi", "hi": "नरक चतुर्दशी"}, {"key": "B", "en": "Kali Chaudas", "hi": "काली चौदस"}, {"key": "C", "en": "Chhoti Diwali", "hi": "छोटी दीवाली"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3067,'Which festival marks the beginning of temple chariot processions?','मंदिर रथ यात्राओं की शुरुआत का पर्व कौन सा है?','[{"key": "A", "en": "Ratha Saptami", "hi": "रथ सप्तमी"}, {"key": "B", "en": "Ratha Yatra", "hi": "रथ यात्रा"}, {"key": "C", "en": "Magha Purnima", "hi": "माघ पूर्णिमा"}, {"key": "D", "en": "Panguni Uthiram", "hi": "पंगुनी उथिरम"}]','A');
INSERT INTO knowledge_quiz VALUES(3068,'Which festival is associated with worship of horses in some regions?','कुछ क्षेत्रों में घोड़ों की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Ashwa Puja", "hi": "अश्व पूजा"}, {"key": "B", "en": "Ayudha Puja", "hi": "आयुध पूजा"}, {"key": "C", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "D", "en": "Pola", "hi": "पोला"}]','A');
INSERT INTO knowledge_quiz VALUES(3069,'Which festival honors Lord Shiva as the cosmic dancer?','भगवान शिव को नटराज रूप में सम्मान देने वाला पर्व कौन सा है?','[{"key": "A", "en": "Maha Shivaratri", "hi": "महाशिवरात्रि"}, {"key": "B", "en": "Arudra Darshan", "hi": "आरुद्र दर्शन"}, {"key": "C", "en": "Karthigai Deepam", "hi": "कार्तिगै दीपम"}, {"key": "D", "en": "Pradosham", "hi": "प्रदोषम"}]','B');
INSERT INTO knowledge_quiz VALUES(3070,'Which festival celebrates the victory of light over ignorance through lamps?','दीपों द्वारा अज्ञान पर प्रकाश की विजय का पर्व कौन सा है?','[{"key": "A", "en": "Karthigai Deepam", "hi": "कार्तिगै दीपम"}, {"key": "B", "en": "Diwali", "hi": "दीवाली"}, {"key": "C", "en": "Dev Deepawali", "hi": "देव दीपावली"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3071,'Which festival is linked with offering milk to snakes and anthills?','सर्पों और बांबी में दूध अर्पित करने से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Nag Panchami", "hi": "नाग पंचमी"}, {"key": "B", "en": "Shravan Purnima", "hi": "श्रावण पूर्णिमा"}, {"key": "C", "en": "Hartalika Teej", "hi": "हरतालिका तीज"}, {"key": "D", "en": "Ananta Chaturdashi", "hi": "अनंत चतुर्दशी"}]','A');
INSERT INTO knowledge_quiz VALUES(3072,'Which festival is celebrated for family prosperity after Diwali?','दीवाली के बाद पारिवारिक समृद्धि के लिए कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Bhai Dooj", "hi": "भाई दूज"}, {"key": "B", "en": "Balipratipada", "hi": "बलिप्रतिपदा"}, {"key": "C", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "D", "en": "Annakut", "hi": "अन्नकूट"}]','B');
INSERT INTO knowledge_quiz VALUES(3073,'Which festival is dedicated to children’s longevity and protection?','बच्चों की दीर्घायु और रक्षा के लिए कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Ahoi Ashtami", "hi": "अहोई अष्टमी"}, {"key": "B", "en": "Santana Saptami", "hi": "संतान सप्तमी"}, {"key": "C", "en": "Putrada Ekadashi", "hi": "पुत्रदा एकादशी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3074,'Which festival celebrates the divine appearance of Goddess Lakshmi from the ocean?','समुद्र मंथन से देवी लक्ष्मी के प्राकट्य का पर्व कौन सा है?','[{"key": "A", "en": "Kojagiri Purnima", "hi": "कोजागिरी पूर्णिमा"}, {"key": "B", "en": "Sharad Purnima", "hi": "शरद पूर्णिमा"}, {"key": "C", "en": "Lakshmi Puja", "hi": "लक्ष्मी पूजा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3075,'Which festival involves offering new clothes to deities before wearing them?','देवताओं को नए वस्त्र अर्पित कर स्वयं पहनने का पर्व कौन सा है?','[{"key": "A", "en": "Kartik Purnima", "hi": "कार्तिक पूर्णिमा"}, {"key": "B", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "C", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "D", "en": "Janmashtami", "hi": "जन्माष्टमी"}]','C');
INSERT INTO knowledge_quiz VALUES(3076,'Which festival is associated with worship of household kitchens and stoves?','रसोईघर और चूल्हे की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Pongal", "hi": "पोंगल"}, {"key": "B", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "C", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}, {"key": "D", "en": "Chhath Puja", "hi": "छठ पूजा"}]','A');
INSERT INTO knowledge_quiz VALUES(3077,'Which festival symbolizes renewal of social bonds after harvest?','फसल के बाद सामाजिक संबंधों के नवीनीकरण का प्रतीक कौन सा पर्व है?','[{"key": "A", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}, {"key": "B", "en": "Baisakhi", "hi": "बैसाखी"}, {"key": "C", "en": "Lohri", "hi": "लोहड़ी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3078,'Which festival is associated with worship of stars and constellations?','तारों और नक्षत्रों की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Krittika Deepam", "hi": "कृत्तिका दीपम"}, {"key": "B", "en": "Karthigai Deepam", "hi": "कार्तिगै दीपम"}, {"key": "C", "en": "Ratha Saptami", "hi": "रथ सप्तमी"}, {"key": "D", "en": "Magha Purnima", "hi": "माघ पूर्णिमा"}]','B');
INSERT INTO knowledge_quiz VALUES(3079,'Which festival involves worship of the Sun at both sunrise and sunset?','सूर्योदय और सूर्यास्त दोनों समय सूर्य पूजा का पर्व कौन सा है?','[{"key": "A", "en": "Chhath Puja", "hi": "छठ पूजा"}, {"key": "B", "en": "Ratha Saptami", "hi": "रथ सप्तमी"}, {"key": "C", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}, {"key": "D", "en": "Surya Shashti", "hi": "सूर्य षष्ठी"}]','A');
INSERT INTO knowledge_quiz VALUES(3080,'Which festival is believed to remove ancestral debts when properly observed?','विधिवत पालन से पितृ ऋण से मुक्ति दिलाने वाला पर्व कौन सा है?','[{"key": "A", "en": "Pitru Paksha", "hi": "पितृ पक्ष"}, {"key": "B", "en": "Magha Amavasya", "hi": "माघ अमावस्या"}, {"key": "C", "en": "Gaya Shraddha", "hi": "गया श्राद्ध"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3081,'Which festival in Gujarat involves creating and worshipping cow-dung replicas of Govardhan Hill?','गुजरात में गोवर्धन पर्वत की गोबर से प्रतिकृति बनाकर पूजा करने वाला पर्व कौन सा है?','[{"key": "A", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "B", "en": "Annakut", "hi": "अन्नकूट"}, {"key": "C", "en": "Balipratipada", "hi": "बलिप्रतिपदा"}, {"key": "D", "en": "Pola", "hi": "पोला"}]','A');
INSERT INTO knowledge_quiz VALUES(3082,'Which festival in Maharashtra celebrates the mythical return of King Bali?','महाराष्ट्र में राजा बलि के आगमन से जुड़ा कौन सा पर्व है?','[{"key": "A", "en": "Balipratipada", "hi": "बलिप्रतिपदा"}, {"key": "B", "en": "Onam", "hi": "ओणम"}, {"key": "C", "en": "Gudi Padwa", "hi": "गुड़ी पड़वा"}, {"key": "D", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}]','A');
INSERT INTO knowledge_quiz VALUES(3083,'Which Hindu festival involves worshipping nine types of grains symbolizing prosperity?','समृद्धि के प्रतीक नौ प्रकार के अनाज की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Navanna", "hi": "नवन्न"}, {"key": "B", "en": "Navadhanya Puja", "hi": "नवधान्य पूजा"}, {"key": "C", "en": "Annakut", "hi": "अन्नकूट"}, {"key": "D", "en": "Pongal", "hi": "पोंगल"}]','B');
INSERT INTO knowledge_quiz VALUES(3084,'Which festival is associated with lighting lamps on hilltops in Tamil Nadu?','तमिलनाडु में पहाड़ियों पर दीप प्रज्वलन से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Karthigai Deepam", "hi": "कार्तिगै दीपम"}, {"key": "B", "en": "Thai Poosam", "hi": "थाई पूसम"}, {"key": "C", "en": "Chithirai Festival", "hi": "चिथिरै उत्सव"}, {"key": "D", "en": "Vaikasi Visakam", "hi": "वैशाखी विशाखम"}]','A');
INSERT INTO knowledge_quiz VALUES(3085,'Which festival celebrates the symbolic descent of Ganga into household water pots?','घरों के कलशों में गंगा के प्रतीकात्मक अवतरण से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Ganga Dussehra", "hi": "गंगा दशहरा"}, {"key": "B", "en": "Jal Yatra", "hi": "जल यात्रा"}, {"key": "C", "en": "Aadi Perukku", "hi": "आदि पेरुक्कु"}, {"key": "D", "en": "Kartika Purnima", "hi": "कार्तिक पूर्णिमा"}]','B');
INSERT INTO knowledge_quiz VALUES(3086,'Which festival in Odisha celebrates the divine bathing of Lord Jagannath?','ओडिशा में भगवान जगन्नाथ के स्नान से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Snana Yatra", "hi": "स्नान यात्रा"}, {"key": "B", "en": "Ratha Yatra", "hi": "रथ यात्रा"}, {"key": "C", "en": "Chandan Yatra", "hi": "चंदन यात्रा"}, {"key": "D", "en": "Magha Saptami", "hi": "माघ सप्तमी"}]','A');
INSERT INTO knowledge_quiz VALUES(3087,'Which festival marks the temporary seclusion of deities after ritual bathing?','स्नान के बाद देवताओं के अस्थायी एकांतवास से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Anavasara", "hi": "अनवसरा"}, {"key": "B", "en": "Ratha Yatra", "hi": "रथ यात्रा"}, {"key": "C", "en": "Pradosham", "hi": "प्रदोषम"}, {"key": "D", "en": "Chandan Yatra", "hi": "चंदन यात्रा"}]','A');
INSERT INTO knowledge_quiz VALUES(3088,'Which festival is associated with offering neem leaves for health and protection?','स्वास्थ्य और रक्षा के लिए नीम पत्तों के उपयोग से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Ugadi", "hi": "उगादी"}, {"key": "B", "en": "Gudi Padwa", "hi": "गुड़ी पड़वा"}, {"key": "C", "en": "Vishu", "hi": "विशु"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3089,'Which festival involves worship of household doors and thresholds?','घर के द्वार और देहरी की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Griha Pravesh rituals", "hi": "गृह प्रवेश अनुष्ठान"}, {"key": "B", "en": "Lakshmi Puja", "hi": "लक्ष्मी पूजा"}, {"key": "C", "en": "Margashirsha Thursdays", "hi": "मार्गशीर्ष गुरुवार"}, {"key": "D", "en": "Tula Sankranti", "hi": "तुला संक्रांति"}]','B');
INSERT INTO knowledge_quiz VALUES(3090,'Which festival celebrates the union of Shiva and Shakti through cosmic energy?','शिव और शक्ति के ब्रह्मांडीय मिलन का उत्सव कौन सा है?','[{"key": "A", "en": "Maha Shivaratri", "hi": "महाशिवरात्रि"}, {"key": "B", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "C", "en": "Ardhanarishvara Jayanti", "hi": "अर्धनारीश्वर जयंती"}, {"key": "D", "en": "Pradosham", "hi": "प्रदोषम"}]','C');
INSERT INTO knowledge_quiz VALUES(3091,'Which festival is associated with worshipping ancestral weapons of clans?','कुलों के पारंपरिक अस्त्र-शस्त्रों की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Ayudha Puja", "hi": "आयुध पूजा"}, {"key": "B", "en": "Dussehra", "hi": "दशहरा"}, {"key": "C", "en": "Vijayadashami", "hi": "विजयादशमी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3092,'Which festival is linked with worship of household account books?','व्यापारिक बहीखातों की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Lakshmi Puja", "hi": "लक्ष्मी पूजा"}, {"key": "B", "en": "Bhai Dooj", "hi": "भाई दूज"}, {"key": "C", "en": "Gudi Padwa", "hi": "गुड़ी पड़वा"}, {"key": "D", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}]','A');
INSERT INTO knowledge_quiz VALUES(3093,'Which festival in Rajasthan involves worship of camels?','राजस्थान में ऊँटों की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Pola", "hi": "पोला"}, {"key": "B", "en": "Nagaur Festival", "hi": "नागौर उत्सव"}, {"key": "C", "en": "Pushkar Fair rituals", "hi": "पुष्कर मेला अनुष्ठान"}, {"key": "D", "en": "Gangaur", "hi": "गणगौर"}]','C');
INSERT INTO knowledge_quiz VALUES(3094,'Which festival involves worship of rain-bearing clouds using symbolic pots?','प्रतीकात्मक कलशों द्वारा वर्षा लाने वाले मेघों की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Varuna Puja", "hi": "वरुण पूजा"}, {"key": "B", "en": "Aadi Perukku", "hi": "आदि पेरुक्कु"}, {"key": "C", "en": "Jal Yatra", "hi": "जल यात्रा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','A');
INSERT INTO knowledge_quiz VALUES(3095,'Which festival celebrates divine play (Leela) through dramatic enactments?','नाट्य प्रस्तुतियों द्वारा ईश्वरीय लीला का उत्सव कौन सा है?','[{"key": "A", "en": "Ramlila", "hi": "रामलीला"}, {"key": "B", "en": "Krishna Leela festivals", "hi": "कृष्ण लीला उत्सव"}, {"key": "C", "en": "Yakshagana festivals", "hi": "यक्षगान उत्सव"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3096,'Which festival marks the ceremonial opening of temple chariots after monsoon?','मानसून के बाद मंदिर रथों के शुभारंभ से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Ratha Saptami", "hi": "रथ सप्तमी"}, {"key": "B", "en": "Kartika Purnima", "hi": "कार्तिक पूर्णिमा"}, {"key": "C", "en": "Vaikunta Ekadashi", "hi": "वैकुंठ एकादशी"}, {"key": "D", "en": "Panguni Uthiram", "hi": "पंगुनी उथिरम"}]','B');
INSERT INTO knowledge_quiz VALUES(3097,'Which festival involves worship of household wells and water sources?','कुओं और जल स्रोतों की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Aadi Perukku", "hi": "आदि पेरुक्कु"}, {"key": "B", "en": "Varuna Jayanthi", "hi": "वरुण जयंती"}, {"key": "C", "en": "Jal Yatra", "hi": "जल यात्रा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3098,'Which festival is associated with worship of village boundary deities?','ग्राम सीमाओं की रक्षा करने वाले देवताओं की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Gram Devata Puja", "hi": "ग्राम देवता पूजा"}, {"key": "B", "en": "Shitala Ashtami", "hi": "शीतला अष्टमी"}, {"key": "C", "en": "Poleramma Jatara", "hi": "पोलेरम्मा जातरा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3099,'Which festival celebrates the symbolic renewal of fire in households?','घरों में अग्नि के नवीनीकरण का प्रतीक कौन सा पर्व है?','[{"key": "A", "en": "Lohri", "hi": "लोहड़ी"}, {"key": "B", "en": "Pongal", "hi": "पोंगल"}, {"key": "C", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3100,'Which festival involves offering first produce of forests and fields to deities?','वन और खेत की पहली उपज देवताओं को अर्पित करने वाला पर्व कौन सा है?','[{"key": "A", "en": "Nabanna", "hi": "नबन्ना"}, {"key": "B", "en": "Annakut", "hi": "अन्नकूट"}, {"key": "C", "en": "Pongal", "hi": "पोंगल"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3101,'Which festival is associated with worship of ancestral village spirits?','पूर्वज ग्राम आत्माओं की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Pitru Paksha", "hi": "पितृ पक्ष"}, {"key": "B", "en": "Gram Devata Jatara", "hi": "ग्राम देवता जातरा"}, {"key": "C", "en": "Amavasya", "hi": "अमावस्या"}, {"key": "D", "en": "Shraddha", "hi": "श्राद्ध"}]','B');
INSERT INTO knowledge_quiz VALUES(3102,'Which festival involves worship of hills as living deities?','पर्वतों को जीवंत देवता मानकर पूजा करने वाला पर्व कौन सा है?','[{"key": "A", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "B", "en": "Karthigai Deepam", "hi": "कार्तिगै दीपम"}, {"key": "C", "en": "Nanda Devi Raj Jat", "hi": "नंदा देवी राज जात"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3103,'Which festival is linked with worship of domestic animals as family members?','पालतू पशुओं को परिवार का सदस्य मानकर पूजा करने वाला पर्व कौन सा है?','[{"key": "A", "en": "Mattu Pongal", "hi": "मट्टू पोंगल"}, {"key": "B", "en": "Pola", "hi": "पोला"}, {"key": "C", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3104,'Which festival is associated with the symbolic return of deities from temples to homes?','देवताओं के मंदिरों से घरों में आगमन के प्रतीकात्मक उत्सव का पर्व कौन सा है?','[{"key": "A", "en": "Ganesh Visarjan (before immersion)", "hi": "गणेश विसर्जन (पूर्व चरण)"}, {"key": "B", "en": "Gauri Avahan", "hi": "गौरी आवाहन"}, {"key": "C", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "D", "en": "Durga Ashtami", "hi": "दुर्गा अष्टमी"}]','B');
INSERT INTO knowledge_quiz VALUES(3105,'Which festival is celebrated to honor village protectors before sowing season?','बुवाई से पहले ग्राम रक्षकों के सम्मान में कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Bhoomi Puja", "hi": "भूमि पूजा"}, {"key": "B", "en": "Gram Devata Puja", "hi": "ग्राम देवता पूजा"}, {"key": "C", "en": "Varuna Puja", "hi": "वरुण पूजा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3106,'Which festival celebrates the cyclical return of seasons through ritual fasting?','अनुष्ठानिक उपवास द्वारा ऋतु चक्र के उत्सव का पर्व कौन सा है?','[{"key": "A", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "B", "en": "Pradosham", "hi": "प्रदोषम"}, {"key": "C", "en": "Chaturmas observances", "hi": "चातुर्मास व्रत"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3107,'Which festival involves worship of confluence points of rivers?','नदियों के संगम स्थलों की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Magha Mela", "hi": "माघ मेला"}, {"key": "B", "en": "Kumbh Mela", "hi": "कुंभ मेला"}, {"key": "C", "en": "Kartika Purnima", "hi": "कार्तिक पूर्णिमा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3108,'Which festival is associated with worship of village granaries?','ग्राम अन्न भंडारों की पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Annakut", "hi": "अन्नकूट"}, {"key": "B", "en": "Pongal", "hi": "पोंगल"}, {"key": "C", "en": "Nabanna", "hi": "नबन्ना"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3109,'Which festival symbolizes gratitude to unseen natural forces?','अदृश्य प्राकृतिक शक्तियों के प्रति कृतज्ञता का प्रतीक कौन सा पर्व है?','[{"key": "A", "en": "Pongal", "hi": "पोंगल"}, {"key": "B", "en": "Chhath Puja", "hi": "छठ पूजा"}, {"key": "C", "en": "Varuna Puja", "hi": "वरुण पूजा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3110,'Which festival emphasizes harmony between humans, animals, and nature?','मानव, पशु और प्रकृति के बीच सामंजस्य पर बल देने वाला पर्व कौन सा है?','[{"key": "A", "en": "Pongal", "hi": "पोंगल"}, {"key": "B", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "C", "en": "Chhath Puja", "hi": "छठ पूजा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3111,'Which ancient Hindu concept describes the idea that the universe undergoes endless cycles of creation and destruction?','सृष्टि के निरंतर सृजन और विनाश के चक्र को दर्शाने वाली हिंदू अवधारणा कौन सी है?','[{"key": "A", "en": "Karma", "hi": "कर्म"}, {"key": "B", "en": "Samsara", "hi": "संसार"}, {"key": "C", "en": "Kalpa", "hi": "कल्प"}, {"key": "D", "en": "Moksha", "hi": "मोक्ष"}]','C');
INSERT INTO knowledge_quiz VALUES(3112,'Which Hindu scripture describes geography with continents like Jambudvipa?','जंबूद्वीप जैसे भूभागों का वर्णन किस हिंदू ग्रंथ में मिलता है?','[{"key": "A", "en": "Rig Veda", "hi": "ऋग्वेद"}, {"key": "B", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "C", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "D", "en": "Aranyakas", "hi": "आरण्यक"}]','B');
INSERT INTO knowledge_quiz VALUES(3113,'What is the lesser-known name of Lord Shiva as the guardian of cremation grounds?','श्मशान के रक्षक के रूप में भगवान शिव का कम ज्ञात नाम क्या है?','[{"key": "A", "en": "Mahadeva", "hi": "महादेव"}, {"key": "B", "en": "Bhairava", "hi": "भैरव"}, {"key": "C", "en": "Pashupati", "hi": "पशुपति"}, {"key": "D", "en": "Nataraja", "hi": "नटराज"}]','B');
INSERT INTO knowledge_quiz VALUES(3114,'Which Hindu concept teaches that duties change with age and stage of life?','आयु और जीवन अवस्था के अनुसार कर्तव्यों के परिवर्तन की शिक्षा कौन सी अवधारणा देती है?','[{"key": "A", "en": "Varna", "hi": "वर्ण"}, {"key": "B", "en": "Ashrama", "hi": "आश्रम"}, {"key": "C", "en": "Karma", "hi": "कर्म"}, {"key": "D", "en": "Rita", "hi": "ऋत"}]','B');
INSERT INTO knowledge_quiz VALUES(3115,'Which river is personified as both fierce and compassionate in Hindu texts?','किस नदी को हिंदू ग्रंथों में उग्र और करुणामयी दोनों रूपों में दर्शाया गया है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Ganga", "hi": "गंगा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','B');
INSERT INTO knowledge_quiz VALUES(3116,'Which ancient Hindu text focuses extensively on rituals rather than philosophy?','कौन सा प्राचीन हिंदू ग्रंथ दर्शन की अपेक्षा अनुष्ठानों पर अधिक केंद्रित है?','[{"key": "A", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "B", "en": "Brahmanas", "hi": "ब्राह्मण ग्रंथ"}, {"key": "C", "en": "Aranyakas", "hi": "आरण्यक"}, {"key": "D", "en": "Smritis", "hi": "स्मृतियाँ"}]','B');
INSERT INTO knowledge_quiz VALUES(3117,'Which Hindu deity is symbolically represented as time itself?','समय के प्रतीक रूप में किस हिंदू देवता को दर्शाया गया है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Kali", "hi": "काली"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','C');
INSERT INTO knowledge_quiz VALUES(3118,'Which lesser-known Upanishad focuses on renunciation and wandering monks?','संन्यास और परिव्राजकों पर केंद्रित कम ज्ञात उपनिषद कौन सा है?','[{"key": "A", "en": "Isha Upanishad", "hi": "ईशा उपनिषद"}, {"key": "B", "en": "Jabala Upanishad", "hi": "जाबाल उपनिषद"}, {"key": "C", "en": "Katha Upanishad", "hi": "कठ उपनिषद"}, {"key": "D", "en": "Mandukya Upanishad", "hi": "माण्डूक्य उपनिषद"}]','B');
INSERT INTO knowledge_quiz VALUES(3119,'What is the lesser-known meaning of the term ''Yajna''?','‘यज्ञ’ शब्द का कम ज्ञात अर्थ क्या है?','[{"key": "A", "en": "Fire sacrifice only", "hi": "केवल अग्नि यज्ञ"}, {"key": "B", "en": "Selfless offering and cooperation", "hi": "निःस्वार्थ अर्पण और सहयोग"}, {"key": "C", "en": "Temple worship", "hi": "मंदिर पूजा"}, {"key": "D", "en": "Meditation practice", "hi": "ध्यान अभ्यास"}]','B');
INSERT INTO knowledge_quiz VALUES(3120,'Which Hindu concept explains why different paths lead to the same truth?','विभिन्न मार्गों से एक ही सत्य तक पहुँचने की अवधारणा कौन सी है?','[{"key": "A", "en": "Ekam Sat Vipra Bahudha Vadanti", "hi": "एकं सत् विप्रा बहुधा वदन्ति"}, {"key": "B", "en": "Ahimsa", "hi": "अहिंसा"}, {"key": "C", "en": "Maya", "hi": "माया"}, {"key": "D", "en": "Dharma", "hi": "धर्म"}]','A');
INSERT INTO knowledge_quiz VALUES(3121,'Which Hindu deity is considered the presiding deity of learning obstacles?','विद्या में आने वाली बाधाओं के अधिष्ठाता देवता कौन माने जाते हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Brihaspati", "hi": "बृहस्पति"}, {"key": "D", "en": "Skanda", "hi": "स्कंद"}]','B');
INSERT INTO knowledge_quiz VALUES(3122,'Which ancient Hindu practice viewed rivers as living ecosystems rather than resources?','कौन सी प्राचीन हिंदू परंपरा नदियों को संसाधन नहीं बल्कि जीवित तंत्र मानती थी?','[{"key": "A", "en": "Yajna", "hi": "यज्ञ"}, {"key": "B", "en": "Nadi Stuti", "hi": "नदी स्तुति"}, {"key": "C", "en": "Teertha Yatra", "hi": "तीर्थ यात्रा"}, {"key": "D", "en": "Panchamahabhuta worship", "hi": "पंचमहाभूत पूजा"}]','B');
INSERT INTO knowledge_quiz VALUES(3123,'Which Hindu philosophy emphasizes non-duality?','अद्वैत (एकत्व) पर बल देने वाला दर्शन कौन सा है?','[{"key": "A", "en": "Dvaita", "hi": "द्वैत"}, {"key": "B", "en": "Vishishtadvaita", "hi": "विशिष्टाद्वैत"}, {"key": "C", "en": "Advaita Vedanta", "hi": "अद्वैत वेदांत"}, {"key": "D", "en": "Samkhya", "hi": "सांख्य"}]','C');
INSERT INTO knowledge_quiz VALUES(3124,'Which Hindu concept suggests the moral law governing the universe?','ब्रह्मांड को संचालित करने वाले नैतिक नियम की अवधारणा कौन सी है?','[{"key": "A", "en": "Karma", "hi": "कर्म"}, {"key": "B", "en": "Rita", "hi": "ऋत"}, {"key": "C", "en": "Dharma", "hi": "धर्म"}, {"key": "D", "en": "Maya", "hi": "माया"}]','B');
INSERT INTO knowledge_quiz VALUES(3125,'Which Hindu god is symbolically shown with half-open eyes to represent balance?','संतुलन के प्रतीक रूप में आधी खुली आँखों के साथ किस देवता को दर्शाया जाता है?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Buddha (in Hindu tradition)", "hi": "बुद्ध (हिंदू परंपरा में)"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','A');
INSERT INTO knowledge_quiz VALUES(3126,'Which lesser-known fact links Hindu temples to astronomy?','हिंदू मंदिरों को खगोल विज्ञान से जोड़ने वाला कम ज्ञात तथ्य क्या है?','[{"key": "A", "en": "Temple bells measure time", "hi": "मंदिर घंटियाँ समय मापती हैं"}, {"key": "B", "en": "Temple alignments with solstices", "hi": "अयनांत के साथ मंदिर संरेखण"}, {"key": "C", "en": "Idols change positions", "hi": "मूर्तियाँ स्थान बदलती हैं"}, {"key": "D", "en": "Priests observe stars daily", "hi": "पुजारी प्रतिदिन तारे देखते हैं"}]','B');
INSERT INTO knowledge_quiz VALUES(3127,'Which Hindu concept teaches balance between material and spiritual life?','भौतिक और आध्यात्मिक जीवन में संतुलन की शिक्षा कौन सी अवधारणा देती है?','[{"key": "A", "en": "Purusharthas", "hi": "पुरुषार्थ"}, {"key": "B", "en": "Samsara", "hi": "संसार"}, {"key": "C", "en": "Tapasya", "hi": "तपस्या"}, {"key": "D", "en": "Sannyasa", "hi": "संन्यास"}]','A');
INSERT INTO knowledge_quiz VALUES(3128,'Which lesser-known deity is associated with dreams and sleep?','स्वप्न और निद्रा से जुड़ा कम ज्ञात देवता कौन है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Yoganidra", "hi": "योगनिद्रा"}, {"key": "C", "en": "Chandra", "hi": "चंद्र"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','B');
INSERT INTO knowledge_quiz VALUES(3129,'Which Hindu ritual emphasizes gratitude to teachers?','गुरुओं के प्रति कृतज्ञता पर बल देने वाला अनुष्ठान कौन सा है?','[{"key": "A", "en": "Upanayana", "hi": "उपनयन"}, {"key": "B", "en": "Guru Dakshina", "hi": "गुरु दक्षिणा"}, {"key": "C", "en": "Vrat", "hi": "व्रत"}, {"key": "D", "en": "Homa", "hi": "होम"}]','B');
INSERT INTO knowledge_quiz VALUES(3130,'Which lesser-known Hindu belief views the Earth as a mother figure?','पृथ्वी को माता के रूप में देखने वाली हिंदू मान्यता कौन सी है?','[{"key": "A", "en": "Bhumi Devi", "hi": "भूमि देवी"}, {"key": "B", "en": "Prithvi Sukta", "hi": "पृथ्वी सूक्त"}, {"key": "C", "en": "Annapurna", "hi": "अन्नपूर्णा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3131,'Which Hindu concept explains illusion as a veil over reality?','वास्तविकता पर पड़े आवरण के रूप में भ्रम को कौन सी अवधारणा समझाती है?','[{"key": "A", "en": "Karma", "hi": "कर्म"}, {"key": "B", "en": "Maya", "hi": "माया"}, {"key": "C", "en": "Lila", "hi": "लीला"}, {"key": "D", "en": "Tapas", "hi": "तपस्"}]','B');
INSERT INTO knowledge_quiz VALUES(3132,'Which lesser-known Hindu practice emphasizes silence as spiritual discipline?','आध्यात्मिक अनुशासन के रूप में मौन पर बल देने वाली प्रथा कौन सी है?','[{"key": "A", "en": "Mauna Vrata", "hi": "मौन व्रत"}, {"key": "B", "en": "Upavasa", "hi": "उपवास"}, {"key": "C", "en": "Japa", "hi": "जप"}, {"key": "D", "en": "Dana", "hi": "दान"}]','A');
INSERT INTO knowledge_quiz VALUES(3133,'Which Hindu god is known as the lord of directions?','दिशाओं के अधिपति के रूप में किस देवता को जाना जाता है?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Kubera", "hi": "कुबेर"}, {"key": "C", "en": "Vastu Purusha", "hi": "वास्तु पुरुष"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','C');
INSERT INTO knowledge_quiz VALUES(3134,'Which Hindu scripture presents dialogues between a teacher and student?','गुरु और शिष्य के संवाद किस ग्रंथ की विशेषता हैं?','[{"key": "A", "en": "Brahmanas", "hi": "ब्राह्मण ग्रंथ"}, {"key": "B", "en": "Upanishads", "hi": "उपनिषद"}, {"key": "C", "en": "Puranas", "hi": "पुराण"}, {"key": "D", "en": "Smritis", "hi": "स्मृतियाँ"}]','B');
INSERT INTO knowledge_quiz VALUES(3135,'Which lesser-known Hindu belief associates sound with cosmic creation?','ध्वनि को ब्रह्मांडीय सृष्टि से जोड़ने वाली मान्यता कौन सी है?','[{"key": "A", "en": "Nada Brahma", "hi": "नाद ब्रह्म"}, {"key": "B", "en": "Shabda Yoga", "hi": "शब्द योग"}, {"key": "C", "en": "Omkara", "hi": "ओंकार"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3136,'Which Hindu concept promotes duty without attachment to results?','फल की आसक्ति के बिना कर्तव्य करने की शिक्षा कौन सी अवधारणा देती है?','[{"key": "A", "en": "Bhakti Yoga", "hi": "भक्ति योग"}, {"key": "B", "en": "Jnana Yoga", "hi": "ज्ञान योग"}, {"key": "C", "en": "Karma Yoga", "hi": "कर्म योग"}, {"key": "D", "en": "Raja Yoga", "hi": "राज योग"}]','C');
INSERT INTO knowledge_quiz VALUES(3137,'Which lesser-known goddess represents nourishment and food?','पोषण और अन्न की देवी के रूप में कौन सी देवी जानी जाती हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Annapurna", "hi": "अन्नपूर्णा"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Shitala", "hi": "शीतला"}]','B');
INSERT INTO knowledge_quiz VALUES(3138,'Which Hindu idea suggests life is a divine play?','जीवन को ईश्वरीय खेल मानने वाली धारणा कौन सी है?','[{"key": "A", "en": "Maya", "hi": "माया"}, {"key": "B", "en": "Lila", "hi": "लीला"}, {"key": "C", "en": "Rita", "hi": "ऋत"}, {"key": "D", "en": "Tapas", "hi": "तपस्"}]','B');
INSERT INTO knowledge_quiz VALUES(3139,'Which lesser-known Hindu tradition respects forests as sacred?','वनों को पवित्र मानने वाली कम ज्ञात हिंदू परंपरा कौन सी है?','[{"key": "A", "en": "Aranyaka tradition", "hi": "आरण्यक परंपरा"}, {"key": "B", "en": "Smriti tradition", "hi": "स्मृति परंपरा"}, {"key": "C", "en": "Tantra", "hi": "तंत्र"}, {"key": "D", "en": "Bhakti", "hi": "भक्ति"}]','A');
INSERT INTO knowledge_quiz VALUES(3140,'Which Hindu belief sees death as a transition rather than an end?','मृत्यु को अंत नहीं बल्कि परिवर्तन मानने वाली मान्यता कौन सी है?','[{"key": "A", "en": "Karma theory", "hi": "कर्म सिद्धांत"}, {"key": "B", "en": "Reincarnation", "hi": "पुनर्जन्म"}, {"key": "C", "en": "Moksha", "hi": "मोक्ष"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3141,'Which lesser-known Hindu symbol represents spiritual awakening?','आध्यात्मिक जागरण का प्रतीक कौन सा कम ज्ञात चिह्न है?','[{"key": "A", "en": "Lotus", "hi": "कमल"}, {"key": "B", "en": "Conch", "hi": "शंख"}, {"key": "C", "en": "Flame", "hi": "ज्वाला"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3142,'Which Hindu belief emphasizes universal family?','समस्त विश्व को एक परिवार मानने वाली धारणा कौन सी है?','[{"key": "A", "en": "Vasudhaiva Kutumbakam", "hi": "वसुधैव कुटुम्बकम्"}, {"key": "B", "en": "Sarve Bhavantu Sukhinah", "hi": "सर्वे भवन्तु सुखिनः"}, {"key": "C", "en": "Ahimsa", "hi": "अहिंसा"}, {"key": "D", "en": "Rita", "hi": "ऋत"}]','A');
INSERT INTO knowledge_quiz VALUES(3143,'Which lesser-known Hindu festival honors household snakes symbolically?','घरों में प्रतीकात्मक रूप से सर्पों के सम्मान से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Nag Panchami", "hi": "नाग पंचमी"}, {"key": "B", "en": "Shravan Amavasya", "hi": "श्रावण अमावस्या"}, {"key": "C", "en": "Ananta Chaturdashi", "hi": "अनंत चतुर्दशी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3144,'Which Hindu teaching sees service as worship?','सेवा को पूजा मानने की शिक्षा कौन सी है?','[{"key": "A", "en": "Seva Bhava", "hi": "सेवा भाव"}, {"key": "B", "en": "Bhakti", "hi": "भक्ति"}, {"key": "C", "en": "Dana", "hi": "दान"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3145,'Which lesser-known Hindu belief links breath with life force?','श्वास को प्राण शक्ति से जोड़ने वाली मान्यता कौन सी है?','[{"key": "A", "en": "Pranayama", "hi": "प्राणायाम"}, {"key": "B", "en": "Prana", "hi": "प्राण"}, {"key": "C", "en": "Hatha Yoga", "hi": "हठ योग"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3146,'Which Hindu idea suggests ethical living sustains cosmic order?','नैतिक जीवन को ब्रह्मांडीय व्यवस्था बनाए रखने वाला कौन सा विचार है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Rita", "hi": "ऋत"}, {"key": "C", "en": "Karma", "hi": "कर्म"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3147,'Which lesser-known Hindu view sees knowledge as liberation?','ज्ञान को मुक्ति का साधन मानने वाली धारणा कौन सी है?','[{"key": "A", "en": "Jnana Yoga", "hi": "ज्ञान योग"}, {"key": "B", "en": "Bhakti Yoga", "hi": "भक्ति योग"}, {"key": "C", "en": "Karma Yoga", "hi": "कर्म योग"}, {"key": "D", "en": "Raja Yoga", "hi": "राज योग"}]','A');
INSERT INTO knowledge_quiz VALUES(3148,'Which Hindu practice symbolically cleanses both body and mind?','शरीर और मन दोनों की शुद्धि का प्रतीक कौन सी प्रथा है?','[{"key": "A", "en": "Snana (ritual bathing)", "hi": "स्नान"}, {"key": "B", "en": "Upavasa", "hi": "उपवास"}, {"key": "C", "en": "Japa", "hi": "जप"}, {"key": "D", "en": "Dana", "hi": "दान"}]','A');
INSERT INTO knowledge_quiz VALUES(3149,'Which lesser-known Hindu idea links gratitude with prosperity?','कृतज्ञता को समृद्धि से जोड़ने वाली धारणा कौन सी है?','[{"key": "A", "en": "Dana", "hi": "दान"}, {"key": "B", "en": "Yajna spirit", "hi": "यज्ञ भाव"}, {"key": "C", "en": "Seva", "hi": "सेवा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3150,'Which Hindu worldview accepts diversity of beliefs as natural?','विश्वासों की विविधता को स्वाभाविक मानने वाला दृष्टिकोण कौन सा है?','[{"key": "A", "en": "Pluralism", "hi": "बहुलवाद"}, {"key": "B", "en": "Monism", "hi": "एकत्ववाद"}, {"key": "C", "en": "Dualism", "hi": "द्वैतवाद"}, {"key": "D", "en": "Asceticism", "hi": "संन्यास"}]','A');
INSERT INTO knowledge_quiz VALUES(3151,'Which lesser-known Hindu belief connects time with cyclic ages?','समय को युग चक्र से जोड़ने वाली मान्यता कौन सी है?','[{"key": "A", "en": "Yuga theory", "hi": "युग सिद्धांत"}, {"key": "B", "en": "Kalpa system", "hi": "कल्प प्रणाली"}, {"key": "C", "en": "Manvantara", "hi": "मन्वंतर"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3152,'Which part of Sati fell at the Mithila Peetha (Janakpur)?','मिथिला पीठ (जनकपुर) में सती का कौन सा अंग गिरा था?','[{"key": "A", "en": "Eyes", "hi": "आंखें"}, {"key": "B", "en": "Shoulders", "hi": "कंधे"}, {"key": "C", "en": "Left Shoulder", "hi": "बायां कंधा"}, {"key": "D", "en": "Right Leg", "hi": "दायां पैर"}]','C');
INSERT INTO knowledge_quiz VALUES(3153,'Which lesser-known Hindu idea emphasizes harmony with nature?','प्रकृति के साथ सामंजस्य पर बल देने वाली अवधारणा कौन सी है?','[{"key": "A", "en": "Rita", "hi": "ऋत"}, {"key": "B", "en": "Prakriti-Purusha balance", "hi": "प्रकृति-पुरुष संतुलन"}, {"key": "C", "en": "Pancha Mahabhuta", "hi": "पंचमहाभूत"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3154,'Which Hindu practice symbolizes surrender of ego?','अहंकार के त्याग का प्रतीक कौन सी प्रथा है?','[{"key": "A", "en": "Namaskara", "hi": "नमस्कार"}, {"key": "B", "en": "Pada Seva", "hi": "पाद सेवा"}, {"key": "C", "en": "Sannyasa", "hi": "संन्यास"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3155,'Which lesser-known Hindu deity guards thresholds and entrances?','द्वारों और देहरी की रक्षा करने वाले कम ज्ञात देवता कौन हैं?','[{"key": "A", "en": "Ganesha", "hi": "गणेश"}, {"key": "B", "en": "Dvarapala", "hi": "द्वारपाल"}, {"key": "C", "en": "Kubera", "hi": "कुबेर"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(3156,'Which Hindu belief views learning as lifelong?','सीखने को आजीवन प्रक्रिया मानने वाली मान्यता कौन सी है?','[{"key": "A", "en": "Vidya", "hi": "विद्या"}, {"key": "B", "en": "Svadhyaya", "hi": "स्वाध्याय"}, {"key": "C", "en": "Jnana", "hi": "ज्ञान"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3157,'Which lesser-known Hindu teaching promotes contentment?','संतोष पर बल देने वाली शिक्षा कौन सी है?','[{"key": "A", "en": "Santosha", "hi": "संतोष"}, {"key": "B", "en": "Aparigraha", "hi": "अपरिग्रह"}, {"key": "C", "en": "Tapas", "hi": "तपस्"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3158,'Which Hindu view accepts uncertainty as part of wisdom?','अनिश्चितता को भी ज्ञान का अंग मानने वाला दृष्टिकोण कौन सा है?','[{"key": "A", "en": "Nasadiya Sukta philosophy", "hi": "नासदीय सूक्त दर्शन"}, {"key": "B", "en": "Samkhya", "hi": "सांख्य"}, {"key": "C", "en": "Nyaya", "hi": "न्याय"}, {"key": "D", "en": "Mimamsa", "hi": "मीमांसा"}]','A');
INSERT INTO knowledge_quiz VALUES(3159,'Which lesser-known Hindu idea treats life stages as sacred?','जीवन की अवस्थाओं को पवित्र मानने वाली अवधारणा कौन सी है?','[{"key": "A", "en": "Ashrama system", "hi": "आश्रम व्यवस्था"}, {"key": "B", "en": "Varna system", "hi": "वर्ण व्यवस्था"}, {"key": "C", "en": "Purusharthas", "hi": "पुरुषार्थ"}, {"key": "D", "en": "Samsara", "hi": "संसार"}]','A');
INSERT INTO knowledge_quiz VALUES(3160,'Which Hindu belief emphasizes inner purity over outer ritual?','बाह्य अनुष्ठान से अधिक आंतरिक शुद्धता पर बल देने वाली धारणा कौन सी है?','[{"key": "A", "en": "Upanishadic thought", "hi": "उपनिषदिक विचार"}, {"key": "B", "en": "Bhakti movement", "hi": "भक्ति आंदोलन"}, {"key": "C", "en": "Yoga philosophy", "hi": "योग दर्शन"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3161,'Which lesser-known Hindu concept describes the inner witness consciousness?','आंतरिक साक्षी चेतना का वर्णन करने वाली कम ज्ञात हिंदू अवधारणा कौन सी है?','[{"key": "A", "en": "Atman", "hi": "आत्मा"}, {"key": "B", "en": "Sakshi Bhava", "hi": "साक्षी भाव"}, {"key": "C", "en": "Chitta", "hi": "चित्त"}, {"key": "D", "en": "Manas", "hi": "मनस्"}]','B');
INSERT INTO knowledge_quiz VALUES(3162,'Which Hindu belief holds that sound existed before matter?','कौन सी हिंदू मान्यता मानती है कि पदार्थ से पहले ध्वनि अस्तित्व में थी?','[{"key": "A", "en": "Nada Siddhanta", "hi": "नाद सिद्धांत"}, {"key": "B", "en": "Pancha Mahabhuta", "hi": "पंचमहाभूत"}, {"key": "C", "en": "Samkhya", "hi": "सांख्य"}, {"key": "D", "en": "Nyaya", "hi": "न्याय"}]','A');
INSERT INTO knowledge_quiz VALUES(3163,'Which lesser-known Hindu practice involves offering water daily to the Sun?','प्रतिदिन सूर्य को जल अर्पित करने की कम ज्ञात हिंदू प्रथा कौन सी है?','[{"key": "A", "en": "Surya Namaskar", "hi": "सूर्य नमस्कार"}, {"key": "B", "en": "Arghya Daan", "hi": "अर्घ्य दान"}, {"key": "C", "en": "Sandhya Vandana", "hi": "संध्या वंदना"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
