INSERT INTO knowledge_quiz VALUES(3238,'Which Hindu idea views nature as scripture?','प्रकृति को शास्त्र मानने वाला विचार कौन सा है?','[{"key": "A", "en": "Prakriti Shastra", "hi": "प्रकृति शास्त्र"}, {"key": "B", "en": "Rita", "hi": "ऋत"}, {"key": "C", "en": "Pancha Mahabhuta", "hi": "पंचमहाभूत"}, {"key": "D", "en": "Both B and C", "hi": "B और C दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(3239,'Which lesser-known Hindu belief treats patience as power?','धैर्य को शक्ति मानने वाली मान्यता कौन सी है?','[{"key": "A", "en": "Kshanti", "hi": "क्षांति"}, {"key": "B", "en": "Tapasya", "hi": "तपस्या"}, {"key": "C", "en": "Sahishnuta", "hi": "सहिष्णुता"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3240,'Which Hindu worldview encourages unity in diversity?','विविधता में एकता को बढ़ावा देने वाला दृष्टिकोण कौन सा है?','[{"key": "A", "en": "Ekam Sat", "hi": "एकं सत्"}, {"key": "B", "en": "Vasudhaiva Kutumbakam", "hi": "वसुधैव कुटुम्बकम्"}, {"key": "C", "en": "Pluralism", "hi": "बहुलवाद"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3241,'Which lesser-known Hindu idea treats doubt as inquiry?','संदेह को जिज्ञासा मानने वाली धारणा कौन सी है?','[{"key": "A", "en": "Vichara", "hi": "विचार"}, {"key": "B", "en": "Nyaya", "hi": "न्याय"}, {"key": "C", "en": "Upanishadic inquiry", "hi": "उपनिषदिक जिज्ञासा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3242,'Which Hindu belief treats self-control as freedom?','संयम को स्वतंत्रता मानने वाली मान्यता कौन सी है?','[{"key": "A", "en": "Brahmacharya", "hi": "ब्रह्मचर्य"}, {"key": "B", "en": "Yama-Niyama", "hi": "यम-नियम"}, {"key": "C", "en": "Tapasya", "hi": "तपस्या"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3243,'Which lesser-known Hindu practice honors rivers as teachers?','नदियों को गुरु मानने वाली प्रथा कौन सी है?','[{"key": "A", "en": "Nadi Stuti", "hi": "नदी स्तुति"}, {"key": "B", "en": "Teertha Yatra", "hi": "तीर्थ यात्रा"}, {"key": "C", "en": "Jala Upasana", "hi": "जल उपासना"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3244,'Which Hindu idea treats death as transition, not end?','मृत्यु को अंत नहीं बल्कि संक्रमण मानने वाला विचार कौन सा है?','[{"key": "A", "en": "Reincarnation", "hi": "पुनर्जन्म"}, {"key": "B", "en": "Karma Siddhanta", "hi": "कर्म सिद्धांत"}, {"key": "C", "en": "Moksha", "hi": "मोक्ष"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3245,'Which lesser-known Hindu belief treats gratitude as strength?','कृतज्ञता को शक्ति मानने वाली मान्यता कौन सी है?','[{"key": "A", "en": "Yajna Bhava", "hi": "यज्ञ भाव"}, {"key": "B", "en": "Dana Dharma", "hi": "दान धर्म"}, {"key": "C", "en": "Seva Bhava", "hi": "सेवा भाव"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3246,'Which Hindu worldview treats life as sacred duty?','जीवन को पवित्र कर्तव्य मानने वाला दृष्टिकोण कौन सा है?','[{"key": "A", "en": "Dharma", "hi": "धर्म"}, {"key": "B", "en": "Purusharthas", "hi": "पुरुषार्थ"}, {"key": "C", "en": "Ashrama system", "hi": "आश्रम व्यवस्था"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3247,'Which lesser-known Hindu idea treats ethics as cosmic alignment?','नैतिकता को ब्रह्मांडीय संरेखण मानने वाली धारणा कौन सी है?','[{"key": "A", "en": "Rita", "hi": "ऋत"}, {"key": "B", "en": "Dharma", "hi": "धर्म"}, {"key": "C", "en": "Satya", "hi": "सत्य"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3248,'Which Hindu belief treats awareness as worship?','जागरूकता को पूजा मानने वाली मान्यता कौन सी है?','[{"key": "A", "en": "Smriti", "hi": "स्मृति"}, {"key": "B", "en": "Dhyana", "hi": "ध्यान"}, {"key": "C", "en": "Sakshi Bhava", "hi": "साक्षी भाव"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3249,'Which lesser-known Hindu belief treats creativity as divine?','सृजनात्मकता को दैवी मानने वाली मान्यता कौन सी है?','[{"key": "A", "en": "Shakti Tattva", "hi": "शक्ति तत्त्व"}, {"key": "B", "en": "Lila", "hi": "लीला"}, {"key": "C", "en": "Kala Shastra", "hi": "कला शास्त्र"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3250,'Which Hindu worldview treats inner peace as success?','आंतरिक शांति को सफलता मानने वाला दृष्टिकोण कौन सा है?','[{"key": "A", "en": "Shanti Patha", "hi": "शांति पाठ"}, {"key": "B", "en": "Santosha", "hi": "संतोष"}, {"key": "C", "en": "Yoga Darshana", "hi": "योग दर्शन"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3251,'Who was the celestial sage born from Brahma''s mind?','ब्रह्मा के मन से उत्पन्न हुए दिव्य ऋषि कौन थे?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Bhrigu", "hi": "भृगु"}, {"key": "C", "en": "Atri", "hi": "अत्रि"}, {"key": "D", "en": "Vashistha", "hi": "वशिष्ठ"}]','A');
INSERT INTO knowledge_quiz VALUES(3252,'Which demon received a boon that he could only be killed by a woman?','किस असुर को यह वरदान मिला था कि उसका वध केवल एक स्त्री कर सकती है?','[{"key": "A", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "B", "en": "Bhasmasura", "hi": "भस्मासुर"}, {"key": "C", "en": "Hiranyaksha", "hi": "हिरण्याक्ष"}, {"key": "D", "en": "Shumbha", "hi": "शुम्भ"}]','A');
INSERT INTO knowledge_quiz VALUES(3253,'Who was the divine architect of the gods?','देवताओं के दिव्य शिल्पकार कौन थे?','[{"key": "A", "en": "Tvashta", "hi": "त्वष्टा"}, {"key": "B", "en": "Vishwakarma", "hi": "विश्वकर्मा"}, {"key": "C", "en": "Mayasura", "hi": "मयासुर"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','B');
INSERT INTO knowledge_quiz VALUES(3254,'Which serpent king served as the couch of Lord Vishnu?','भगवान विष्णु के शयन के रूप में कौन से नागराज सेवा करते थे?','[{"key": "A", "en": "Vasuki", "hi": "वासुकि"}, {"key": "B", "en": "Takshaka", "hi": "तक्षक"}, {"key": "C", "en": "Shesha", "hi": "शेष"}, {"key": "D", "en": "Kaliya", "hi": "कालिय"}]','C');
INSERT INTO knowledge_quiz VALUES(3255,'The Siddhivinayak Temple is located in which specific area of Mumbai?','सिद्धिविनायक मंदिर मुंबई के किस विशिष्ट क्षेत्र में स्थित है?','[{"key": "A", "en": "Colaba", "hi": "कुलाबा"}, {"key": "B", "en": "Prabhadevi", "hi": "प्रभादेवी"}, {"key": "C", "en": "Andheri", "hi": "अंधेरी"}, {"key": "D", "en": "Bandra", "hi": "बांद्रा"}]','B');
INSERT INTO knowledge_quiz VALUES(3256,'Which avatar of Vishnu rescued the Earth from the cosmic ocean?','विष्णु के किस अवतार ने पृथ्वी को समुद्र से बाहर निकाला?','[{"key": "A", "en": "Matsya", "hi": "मत्स्य"}, {"key": "B", "en": "Kurma", "hi": "कूर्म"}, {"key": "C", "en": "Varaha", "hi": "वराह"}, {"key": "D", "en": "Vamana", "hi": "वामन"}]','C');
INSERT INTO knowledge_quiz VALUES(3257,'Who was the celestial nymph cursed to become a stone?','कौन सी अप्सरा शाप के कारण पत्थर बन गई थीं?','[{"key": "A", "en": "Menaka", "hi": "मेनका"}, {"key": "B", "en": "Rambha", "hi": "रंभा"}, {"key": "C", "en": "Urvashi", "hi": "उर्वशी"}, {"key": "D", "en": "Ahalya", "hi": "अहल्या"}]','D');
INSERT INTO knowledge_quiz VALUES(3258,'Which demon king was granted immortality but was slain by Narasimha?','किस असुर राजा को अमरता का वरदान मिला था लेकिन नरसिंह ने उसका वध किया?','[{"key": "A", "en": "Hiranyaksha", "hi": "हिरण्याक्ष"}, {"key": "B", "en": "Hiranyakashipu", "hi": "हिरण्यकशिपु"}, {"key": "C", "en": "Ravana", "hi": "रावण"}, {"key": "D", "en": "Bali", "hi": "बलि"}]','B');
INSERT INTO knowledge_quiz VALUES(3259,'Who churned the ocean using Mount Mandara?','मंदराचल पर्वत का उपयोग कर समुद्र मंथन किसने किया?','[{"key": "A", "en": "Devas alone", "hi": "केवल देवता"}, {"key": "B", "en": "Asuras alone", "hi": "केवल असुर"}, {"key": "C", "en": "Devas and Asuras", "hi": "देवता और असुर"}, {"key": "D", "en": "Gandharvas", "hi": "गंधर्व"}]','C');
INSERT INTO knowledge_quiz VALUES(3260,'The ''Sankat Mochan Hanuman Temple'' in Varanasi was established by which famous medieval saint and poet?','वाराणसी के ''संकट मोचन हनुमान मंदिर'' की स्थापना किस प्रसिद्ध मध्यकालीन संत और कवि ने की थी?','[{"key": "A", "en": "Kabir Das", "hi": "कबीर दास"}, {"key": "B", "en": "Tulsidas", "hi": "तुलसीदास"}, {"key": "C", "en": "Surdas", "hi": "सूरदास"}, {"key": "D", "en": "Raidas", "hi": "रैदास"}]','B');
INSERT INTO knowledge_quiz VALUES(3261,'Who was the teacher of both gods and demons?','देवताओं और असुरों दोनों के गुरु कौन थे?','[{"key": "A", "en": "Brihaspati", "hi": "बृहस्पति"}, {"key": "B", "en": "Shukracharya", "hi": "शुक्राचार्य"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Dattatreya", "hi": "दत्तात्रेय"}]','B');
INSERT INTO knowledge_quiz VALUES(3262,'Brahmagiri Hill in Nashik is famous as the source of which holy river?','नासिक की ब्रह्मगिरी पहाड़ी किस पवित्र नदी के उद्गम स्थल के रूप में प्रसिद्ध है?','[{"key": "A", "en": "Krishna", "hi": "कृष्णा"}, {"key": "B", "en": "Godavari", "hi": "गोदावरी"}, {"key": "C", "en": "Tapi", "hi": "तापी"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','B');
INSERT INTO knowledge_quiz VALUES(3263,'Who was the foster mother of Lord Krishna?','भगवान कृष्ण की पालक माता कौन थीं?','[{"key": "A", "en": "Devaki", "hi": "देवकी"}, {"key": "B", "en": "Rohini", "hi": "रोहिणी"}, {"key": "C", "en": "Yashoda", "hi": "यशोदा"}, {"key": "D", "en": "Radha", "hi": "राधा"}]','C');
INSERT INTO knowledge_quiz VALUES(3264,'Which weapon of Vishnu always returns to him after use?','भगवान विष्णु का कौन सा अस्त्र प्रयोग के बाद स्वयं लौट आता है?','[{"key": "A", "en": "Gada", "hi": "गदा"}, {"key": "B", "en": "Shankha", "hi": "शंख"}, {"key": "C", "en": "Chakra", "hi": "चक्र"}, {"key": "D", "en": "Bow", "hi": "धनुष"}]','C');
INSERT INTO knowledge_quiz VALUES(3265,'Who was the demon architect who built Maya Sabha?','मायासभा का निर्माण करने वाला असुर शिल्पी कौन था?','[{"key": "A", "en": "Vishwakarma", "hi": "विश्वकर्मा"}, {"key": "B", "en": "Mayasura", "hi": "मयासुर"}, {"key": "C", "en": "Tvashta", "hi": "त्वष्टा"}, {"key": "D", "en": "Shukra", "hi": "शुक्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3266,'Which river is said to flow in heaven according to mythology?','पुराणों के अनुसार स्वर्ग में कौन सी नदी बहती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Godavari", "hi": "गोदावरी"}, {"key": "C", "en": "Mandakini", "hi": "मंदाकिनी"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','C');
INSERT INTO knowledge_quiz VALUES(3267,'Which goddess sat on Kumbhakarna''s tongue to change his boon request?','कुंभकर्ण की जिह्वा पर कौन सी देवी विराजमान हुई थीं ताकि उनका वरदान बदल जाए?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Gayatri", "hi": "गायत्री"}]','B');
INSERT INTO knowledge_quiz VALUES(3268,'Which asura was granted the power to burn anyone he touched?','किस असुर को स्पर्श मात्र से भस्म करने की शक्ति मिली थी?','[{"key": "A", "en": "Bhasmasura", "hi": "भस्मासुर"}, {"key": "B", "en": "Rahu", "hi": "राहु"}, {"key": "C", "en": "Ketu", "hi": "केतु"}, {"key": "D", "en": "Andhaka", "hi": "अंधक"}]','A');
INSERT INTO knowledge_quiz VALUES(3269,'Who was the divine cow that fulfilled wishes?','इच्छाएँ पूर्ण करने वाली दिव्य गाय कौन थी?','[{"key": "A", "en": "Kamadhenu", "hi": "कामधेनु"}, {"key": "B", "en": "Nandini", "hi": "नंदिनी"}, {"key": "C", "en": "Surabhi", "hi": "सुरभि"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3270,'Who was the king cursed to become an elephant?','किस राजा को हाथी बनने का शाप मिला था?','[{"key": "A", "en": "Gajendra", "hi": "गजेन्द्र"}, {"key": "B", "en": "Indradyumna", "hi": "इंद्रद्युम्न"}, {"key": "C", "en": "Nahusha", "hi": "नहुष"}, {"key": "D", "en": "Bali", "hi": "बलि"}]','C');
INSERT INTO knowledge_quiz VALUES(3271,'Who was the mother of Skanda (Kartikeya)?','स्कंद (कार्तिकेय) की माता कौन थीं?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Krittikas", "hi": "कृत्तिकाएँ"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3272,'Which demon was slain by Goddess Kali during battle?','युद्ध में देवी काली ने किस असुर का वध किया?','[{"key": "A", "en": "Raktabija", "hi": "रक्तबीज"}, {"key": "B", "en": "Shumbha", "hi": "शुम्भ"}, {"key": "C", "en": "Nishumbha", "hi": "निशुम्भ"}, {"key": "D", "en": "Mahishasura", "hi": "महिषासुर"}]','A');
INSERT INTO knowledge_quiz VALUES(3273,'The seven horses of Surya Dev are said to represent the seven meters. What are these meters called?','सूर्य देव के सात घोड़े शास्त्र के सात मीटरों का प्रतिनिधित्व करते हैं। इन छंदों को क्या कहा जाता है?','[{"key": "A", "en": "Sapta Rishi", "hi": "सप्त ऋषि"}, {"key": "B", "en": "Sapta Chhandas", "hi": "सप्त छंद"}, {"key": "C", "en": "Sapta Sindhu", "hi": "सप्त सिंधु"}, {"key": "D", "en": "Sapta Loka", "hi": "सप्त लोक"}]','B');
INSERT INTO knowledge_quiz VALUES(3274,'Which sage authored the Ramayana?','रामायण की रचना किस ऋषि ने की?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','B');
INSERT INTO knowledge_quiz VALUES(3275,'Who was the wife of Sage Agastya?','ऋषि अगस्त्य की पत्नी कौन थीं?','[{"key": "A", "en": "Arundhati", "hi": "अरुंधती"}, {"key": "B", "en": "Lopamudra", "hi": "लोपामुद्रा"}, {"key": "C", "en": "Anasuya", "hi": "अनसूया"}, {"key": "D", "en": "Renuka", "hi": "रेणुका"}]','B');
INSERT INTO knowledge_quiz VALUES(3276,'Which celestial bird is the vehicle of Lord Vishnu?','भगवान विष्णु का वाहन कौन सा दिव्य पक्षी है?','[{"key": "A", "en": "Garuda", "hi": "गरुड़"}, {"key": "B", "en": "Hamsa", "hi": "हंस"}, {"key": "C", "en": "Peacock", "hi": "मोर"}, {"key": "D", "en": "Eagle", "hi": "गरुड़"}]','A');
INSERT INTO knowledge_quiz VALUES(3277,'Who cursed Indra to have a thousand marks on his body?','इंद्र को शरीर पर हजार चिह्नों का शाप किसने दिया था?','[{"key": "A", "en": "Gautama", "hi": "गौतम"}, {"key": "B", "en": "Durvasa", "hi": "दुर्वासा"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Narada", "hi": "नारद"}]','A');
INSERT INTO knowledge_quiz VALUES(3278,'Which demon was the brother of Ravana?','रावण का भाई कौन सा असुर था?','[{"key": "A", "en": "Vibhishana", "hi": "विभीषण"}, {"key": "B", "en": "Kumbhakarna", "hi": "कुंभकर्ण"}, {"key": "C", "en": "Ahiravana", "hi": "अहिरावण"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3279,'Who was the king of Ayodhya before Lord Rama?','भगवान राम से पहले अयोध्या के राजा कौन थे?','[{"key": "A", "en": "Ikshvaku", "hi": "इक्ष्वाकु"}, {"key": "B", "en": "Dasharatha", "hi": "दशरथ"}, {"key": "C", "en": "Harishchandra", "hi": "हरिश्चंद्र"}, {"key": "D", "en": "Raghu", "hi": "रघु"}]','B');
INSERT INTO knowledge_quiz VALUES(3280,'Which demon was killed by Krishna as a child?','बाल्यकाल में कृष्ण ने किस असुर का वध किया?','[{"key": "A", "en": "Putana", "hi": "पूतना"}, {"key": "B", "en": "Kamsa", "hi": "कंस"}, {"key": "C", "en": "Jarasandha", "hi": "जरासंध"}, {"key": "D", "en": "Shishupala", "hi": "शिशुपाल"}]','A');
INSERT INTO knowledge_quiz VALUES(3281,'Who was the sage whose curse caused the drying of Saraswati river?','किस ऋषि के शाप से सरस्वती नदी के सूखने की कथा मिलती है?','[{"key": "A", "en": "Durvasa", "hi": "दुर्वासा"}, {"key": "B", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "C", "en": "Uttanka", "hi": "उत्तंक"}, {"key": "D", "en": "Parashurama", "hi": "परशुराम"}]','C');
INSERT INTO knowledge_quiz VALUES(3282,'Who was the divine sage known for extreme anger?','अत्यधिक क्रोध के लिए प्रसिद्ध ऋषि कौन थे?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Durvasa", "hi": "दुर्वासा"}, {"key": "C", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "D", "en": "Atri", "hi": "अत्रि"}]','B');
INSERT INTO knowledge_quiz VALUES(3283,'Which king was known for his unwavering truthfulness?','अपने अटल सत्य के लिए प्रसिद्ध राजा कौन थे?','[{"key": "A", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "B", "en": "Harishchandra", "hi": "हरिश्चंद्र"}, {"key": "C", "en": "Raghu", "hi": "रघु"}, {"key": "D", "en": "Janaka", "hi": "जनक"}]','B');
INSERT INTO knowledge_quiz VALUES(3284,'Who was the wife of King Shantanu before Ganga?','गंगा से पहले राजा शंतनु की पत्नी कौन थीं?','[{"key": "A", "en": "Satyavati", "hi": "सत्यवती"}, {"key": "B", "en": "Ambika", "hi": "अंबिका"}, {"key": "C", "en": "Ambalika", "hi": "अंबालिका"}, {"key": "D", "en": "None", "hi": "कोई नहीं"}]','D');
INSERT INTO knowledge_quiz VALUES(3285,'Which celestial musician is known for divine music?','दिव्य संगीत के लिए कौन सा गंधर्व प्रसिद्ध है?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Tumburu", "hi": "तुम्बुरु"}, {"key": "C", "en": "Chitraratha", "hi": "चित्ररथ"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3286,'Who was the father of Sage Vyasa?','महर्षि व्यास के पिता कौन थे?','[{"key": "A", "en": "Shantanu", "hi": "शंतनु"}, {"key": "B", "en": "Parashara", "hi": "पराशर"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','B');
INSERT INTO knowledge_quiz VALUES(3287,'Which demon king was killed by Lord Rama?','भगवान राम ने किस असुर राजा का वध किया?','[{"key": "A", "en": "Kumbhakarna", "hi": "कुंभकर्ण"}, {"key": "B", "en": "Bali", "hi": "बालि"}, {"key": "C", "en": "Ravana", "hi": "रावण"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3288,'Who was the guardian of the northern direction?','उत्तर दिशा के दिक्पाल कौन थे?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Kubera", "hi": "कुबेर"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Yama", "hi": "यम"}]','B');
INSERT INTO knowledge_quiz VALUES(3289,'Which queen was the mother of Abhimanyu?','अभिमन्यु की माता कौन थीं?','[{"key": "A", "en": "Subhadra", "hi": "सुभद्रा"}, {"key": "B", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "C", "en": "Uttara", "hi": "उत्तरा"}, {"key": "D", "en": "Gandhari", "hi": "गांधारी"}]','A');
INSERT INTO knowledge_quiz VALUES(3290,'Who was the king of monkeys before Sugriva?','सुग्रीव से पहले वानरों का राजा कौन था?','[{"key": "A", "en": "Hanuman", "hi": "हनुमान"}, {"key": "B", "en": "Bali", "hi": "बालि"}, {"key": "C", "en": "Angada", "hi": "अंगद"}, {"key": "D", "en": "Nala", "hi": "नल"}]','B');
INSERT INTO knowledge_quiz VALUES(3291,'Which divine weapon was used to behead Shishupala?','शिशुपाल का वध करने के लिए किस दिव्य अस्त्र का प्रयोग हुआ?','[{"key": "A", "en": "Trishula", "hi": "त्रिशूल"}, {"key": "B", "en": "Brahmastra", "hi": "ब्रह्मास्त्र"}, {"key": "C", "en": "Sudarshana Chakra", "hi": "सुदर्शन चक्र"}, {"key": "D", "en": "Pashupatastra", "hi": "पाशुपतास्त्र"}]','C');
INSERT INTO knowledge_quiz VALUES(3292,'Who was the daughter of King Janaka?','राजा जनक की पुत्री कौन थीं?','[{"key": "A", "en": "Urmila", "hi": "उर्मिला"}, {"key": "B", "en": "Sita", "hi": "सीता"}, {"key": "C", "en": "Mandavi", "hi": "मांडवी"}, {"key": "D", "en": "Shrutakirti", "hi": "श्रुतकीर्ति"}]','B');
INSERT INTO knowledge_quiz VALUES(3293,'Which sage raised Shakuntala?','शकुंतला का पालन-पोषण किस ऋषि ने किया?','[{"key": "A", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "B", "en": "Kanva", "hi": "कण्व"}, {"key": "C", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "D", "en": "Bharadvaja", "hi": "भरद्वाज"}]','B');
INSERT INTO knowledge_quiz VALUES(3294,'Who was the charioteer of King Dhritarashtra?','राजा धृतराष्ट्र के सारथी कौन थे?','[{"key": "A", "en": "Sanjaya", "hi": "संजय"}, {"key": "B", "en": "Vidura", "hi": "विदुर"}, {"key": "C", "en": "Kripa", "hi": "कृप"}, {"key": "D", "en": "Ashwatthama", "hi": "अश्वत्थामा"}]','A');
INSERT INTO knowledge_quiz VALUES(3295,'Which demon was granted half-immortality by Brahma?','ब्रह्मा से आधी अमरता का वरदान किस असुर को मिला था?','[{"key": "A", "en": "Hiranyakashipu", "hi": "हिरण्यकशिपु"}, {"key": "B", "en": "Ravana", "hi": "रावण"}, {"key": "C", "en": "Andhaka", "hi": "अंधक"}, {"key": "D", "en": "Mahabali", "hi": "महाबलि"}]','A');
INSERT INTO knowledge_quiz VALUES(3296,'Who was the queen of King Bali?','राजा बलि की पत्नी कौन थीं?','[{"key": "A", "en": "Tara", "hi": "तारा"}, {"key": "B", "en": "Vindhyavali", "hi": "विंध्यावली"}, {"key": "C", "en": "Rati", "hi": "रति"}, {"key": "D", "en": "Sharmishtha", "hi": "शर्मिष्ठा"}]','B');
INSERT INTO knowledge_quiz VALUES(3297,'Which sage drank the entire ocean according to legend?','किंवदंती के अनुसार किस ऋषि ने पूरा समुद्र पी लिया था?','[{"key": "A", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "B", "en": "Durvasa", "hi": "दुर्वासा"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Atri", "hi": "अत्रि"}]','A');
INSERT INTO knowledge_quiz VALUES(3298,'Which warrior took a vow to kill Jayadratha?','जयद्रथ के वध की प्रतिज्ञा किस योद्धा ने ली थी?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Nakula", "hi": "नकुल"}, {"key": "D", "en": "Sahadeva", "hi": "सहदेव"}]','B');
INSERT INTO knowledge_quiz VALUES(3299,'Which part of Sati fell at the Bahula Peetha in West Bengal?','पश्चिम बंगाल के बहुला पीठ में सती का कौन सा अंग गिरा था?','[{"key": "A", "en": "Right Hand", "hi": "दायां हाथ"}, {"key": "B", "en": "Left Arm", "hi": "बाईं भुजा"}, {"key": "C", "en": "Chest", "hi": "छाती"}, {"key": "D", "en": "Navel", "hi": "नाभि"}]','B');
INSERT INTO knowledge_quiz VALUES(3300,'Which goddess is known as the consort of Kubera?','कुबेर की पत्नी के रूप में किस देवी को जाना जाता है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Kauberi", "hi": "कौबेरी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','B');
INSERT INTO knowledge_quiz VALUES(3301,'Who was the son of Arjuna and the Naga princess Ulupi?','अर्जुन और नागराजकुमारी उलूपी के पुत्र कौन थे?','[{"key": "A", "en": "Babruvahana", "hi": "बभ्रुवाहन"}, {"key": "B", "en": "Iravan", "hi": "इरावान"}, {"key": "C", "en": "Abhimanyu", "hi": "अभिमन्यु"}, {"key": "D", "en": "Ghatotkacha", "hi": "घटोत्कच"}]','B');
INSERT INTO knowledge_quiz VALUES(3302,'Which demon was killed by Goddess Durga on Navami?','नवमी के दिन देवी दुर्गा ने किस असुर का वध किया?','[{"key": "A", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "B", "en": "Raktabija", "hi": "रक्तबीज"}, {"key": "C", "en": "Shumbha", "hi": "शुम्भ"}, {"key": "D", "en": "Nishumbha", "hi": "निशुम्भ"}]','D');
INSERT INTO knowledge_quiz VALUES(3303,'Which Gandharva is said to have protected the Soma (divine nectar) before the Devas?','किस गंधर्व के बारे में कहा जाता है कि उन्होंने देवताओं से पहले ''सोम'' की रक्षा की थी?','[{"key": "A", "en": "Chitrasena", "hi": "चित्रसेन"}, {"key": "B", "en": "Vishvavasu", "hi": "विश्वावसु"}, {"key": "C", "en": "Tumburu", "hi": "तुम्बुरु"}, {"key": "D", "en": "Haha", "hi": "हाहा"}]','B');
INSERT INTO knowledge_quiz VALUES(3304,'Which celestial weapon could destroy the entire universe?','कौन सा दिव्य अस्त्र पूरे ब्रह्मांड का विनाश कर सकता था?','[{"key": "A", "en": "Brahmastra", "hi": "ब्रह्मास्त्र"}, {"key": "B", "en": "Narayanastra", "hi": "नारायणास्त्र"}, {"key": "C", "en": "Pashupatastra", "hi": "पाशुपतास्त्र"}, {"key": "D", "en": "Brahmashirsha Astra", "hi": "ब्रह्मशीर्ष अस्त्र"}]','D');
INSERT INTO knowledge_quiz VALUES(3305,'Who was the brother of Yudhishthira?','युधिष्ठिर के भाई कौन थे?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "C", "en": "Shakuni", "hi": "शकुनि"}, {"key": "D", "en": "Abhimanyu", "hi": "अभिमन्यु"}]','A');
INSERT INTO knowledge_quiz VALUES(3306,'Which king was cursed to become a lizard?','किस राजा को छिपकली बनने का शाप मिला था?','[{"key": "A", "en": "Indradyumna", "hi": "इंद्रद्युम्न"}, {"key": "B", "en": "Sauviraja", "hi": "सौवीरराज"}, {"key": "C", "en": "Sudarshana", "hi": "सुदर्शन"}, {"key": "D", "en": "Nahusha", "hi": "नहुष"}]','C');
INSERT INTO knowledge_quiz VALUES(3307,'Who was the commander of the Pandava army on the first day of war?','युद्ध के पहले दिन पांडव सेना के सेनापति कौन थे?','[{"key": "A", "en": "Bhishma", "hi": "भीष्म"}, {"key": "B", "en": "Dhrishtadyumna", "hi": "धृष्टद्युम्न"}, {"key": "C", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "D", "en": "Bhima", "hi": "भीम"}]','B');
INSERT INTO knowledge_quiz VALUES(3308,'Which asura was born from the sweat of Brahma?','कौन सा असुर ब्रह्मा के पसीने से उत्पन्न हुआ था?','[{"key": "A", "en": "Madhu", "hi": "मधु"}, {"key": "B", "en": "Kaitabha", "hi": "कैटभ"}, {"key": "C", "en": "Andhaka", "hi": "अंधक"}, {"key": "D", "en": "Both A and B", "hi": "A और B दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(3309,'Which son of Ravana was known as the ''Conqueror of Indra''?','रावण के किस पुत्र को ''इंद्रजीत'' के नाम से जाना जाता था?','[{"key": "A", "en": "Akshaya Kumara", "hi": "अक्षय कुमार"}, {"key": "B", "en": "Meghanada", "hi": "मेघनाद"}, {"key": "C", "en": "Prahasta", "hi": "प्रहस्त"}, {"key": "D", "en": "Atikaya", "hi": "अतिकाय"}]','B');
INSERT INTO knowledge_quiz VALUES(3310,'Which sage stopped the Kurukshetra war at sunset?','किस ऋषि के कारण सूर्यास्त पर युद्ध रुक जाता था?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Narada", "hi": "नारद"}, {"key": "C", "en": "Bharadwaja", "hi": "भरद्वाज"}, {"key": "D", "en": "Kripa", "hi": "कृप"}]','A');
INSERT INTO knowledge_quiz VALUES(3311,'The Ashwini Kumaras were born when Surya and Sandhya took the form of which animal?','अश्विनी कुमारों का जन्म तब हुआ जब सूर्य और संध्या ने किस पशु का रूप धारण किया था?','[{"key": "A", "en": "Lions", "hi": "सिंह"}, {"key": "B", "en": "Swans", "hi": "हंस"}, {"key": "C", "en": "Horses", "hi": "घोड़े"}, {"key": "D", "en": "Eagles", "hi": "गरुड़/बाज"}]','C');
INSERT INTO knowledge_quiz VALUES(3312,'Which demon disguised himself as a deer to abduct Sita?','सीता का हरण करने के लिए किस असुर ने मृग का रूप धारण किया?','[{"key": "A", "en": "Maricha", "hi": "मारीच"}, {"key": "B", "en": "Subahu", "hi": "सुभाहु"}, {"key": "C", "en": "Khara", "hi": "खर"}, {"key": "D", "en": "Dushana", "hi": "दूषण"}]','A');
INSERT INTO knowledge_quiz VALUES(3313,'Who was the father of Karna?','कर्ण के पिता कौन थे?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Surya", "hi": "सूर्य"}, {"key": "C", "en": "Pandu", "hi": "पांडु"}, {"key": "D", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3314,'Which divine conch belonged to Yudhishthira?','युधिष्ठिर का शंख कौन सा था?','[{"key": "A", "en": "Panchajanya", "hi": "पाञ्चजन्य"}, {"key": "B", "en": "Devadatta", "hi": "देवदत्त"}, {"key": "C", "en": "Anantavijaya", "hi": "अनंतविजय"}, {"key": "D", "en": "Sughosha", "hi": "सुघोष"}]','C');
INSERT INTO knowledge_quiz VALUES(3315,'Who was the mother of Parashurama?','परशुराम की माता कौन थीं?','[{"key": "A", "en": "Renuka", "hi": "रेणुका"}, {"key": "B", "en": "Anasuya", "hi": "अनसूया"}, {"key": "C", "en": "Satyavati", "hi": "सत्यवती"}, {"key": "D", "en": "Aditi", "hi": "अदिति"}]','A');
INSERT INTO knowledge_quiz VALUES(3316,'Which demon was killed by Vamana avatar?','वामन अवतार ने किस असुर का वध किया?','[{"key": "A", "en": "Bali", "hi": "बलि"}, {"key": "B", "en": "Mahabali", "hi": "महाबलि"}, {"key": "C", "en": "Namuchi", "hi": "नमुचि"}, {"key": "D", "en": "None", "hi": "कोई नहीं"}]','D');
INSERT INTO knowledge_quiz VALUES(3317,'Who was the king of Hastinapura during the Kurukshetra war?','कुरुक्षेत्र युद्ध के समय हस्तिनापुर का राजा कौन था?','[{"key": "A", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "B", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}, {"key": "C", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "D", "en": "Bheeshma", "hi": "भीष्म"}]','B');
INSERT INTO knowledge_quiz VALUES(3318,'Which rakshasa tried to kill Bhima with poisoned food?','भीम को विष देकर मारने का प्रयास किसने किया?','[{"key": "A", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "B", "en": "Shakuni", "hi": "शकुनि"}, {"key": "C", "en": "Dushasana", "hi": "दुःशासन"}, {"key": "D", "en": "Karna", "hi": "कर्ण"}]','A');
INSERT INTO knowledge_quiz VALUES(3319,'Who was the son of Ravana who fought Lakshmana?','रावण का कौन सा पुत्र लक्ष्मण से युद्ध करता है?','[{"key": "A", "en": "Meghanada", "hi": "मेघनाद"}, {"key": "B", "en": "Atikaya", "hi": "अतिकाय"}, {"key": "C", "en": "Akshayakumara", "hi": "अक्षयकुमार"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3320,'Which god tested King Harishchandra the most?','राजा हरिश्चंद्र की सबसे कठिन परीक्षा किस देवता ने ली?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','C');
INSERT INTO knowledge_quiz VALUES(3321,'Who was the foster father of Lord Krishna?','भगवान कृष्ण के पालक पिता कौन थे?','[{"key": "A", "en": "Vasudeva", "hi": "वसुदेव"}, {"key": "B", "en": "Nanda", "hi": "नंद"}, {"key": "C", "en": "Ugrasena", "hi": "उग्रसेन"}, {"key": "D", "en": "Akrura", "hi": "अक्रूर"}]','B');
INSERT INTO knowledge_quiz VALUES(3322,'Which queen was the mother of Kauravas?','कौरवों की माता कौन थीं?','[{"key": "A", "en": "Kunti", "hi": "कुंती"}, {"key": "B", "en": "Gandhari", "hi": "गांधारी"}, {"key": "C", "en": "Madri", "hi": "माद्री"}, {"key": "D", "en": "Ambika", "hi": "अंबिका"}]','B');
INSERT INTO knowledge_quiz VALUES(3323,'Which weapon did Indra give to Arjuna?','इंद्र ने अर्जुन को कौन सा अस्त्र दिया था?','[{"key": "A", "en": "Vajra", "hi": "वज्र"}, {"key": "B", "en": "Pashupatastra", "hi": "पाशुपतास्त्र"}, {"key": "C", "en": "Brahmastra", "hi": "ब्रह्मास्त्र"}, {"key": "D", "en": "Vajranabha", "hi": "वज्रनाभ"}]','A');
INSERT INTO knowledge_quiz VALUES(3324,'Who was the guru of Duryodhana in mace fighting?','गदा युद्ध में दुर्योधन के गुरु कौन थे?','[{"key": "A", "en": "Kripa", "hi": "कृप"}, {"key": "B", "en": "Drona", "hi": "द्रोण"}, {"key": "C", "en": "Balarama", "hi": "बलराम"}, {"key": "D", "en": "Bhishma", "hi": "भीष्म"}]','C');
INSERT INTO knowledge_quiz VALUES(3325,'Who built the city of Lanka?','लंका नगरी का निर्माण किसने किया?','[{"key": "A", "en": "Ravana", "hi": "रावण"}, {"key": "B", "en": "Kubera", "hi": "कुबेर"}, {"key": "C", "en": "Mayasura", "hi": "मयासुर"}, {"key": "D", "en": "Vishwakarma", "hi": "विश्वकर्मा"}]','B');
INSERT INTO knowledge_quiz VALUES(3326,'Who was the mother of Luv and Kush?','लव और कुश की माता कौन थीं?','[{"key": "A", "en": "Sita", "hi": "सीता"}, {"key": "B", "en": "Urmila", "hi": "उर्मिला"}, {"key": "C", "en": "Mandavi", "hi": "मांडवी"}, {"key": "D", "en": "Shrutakirti", "hi": "श्रुतकीर्ति"}]','A');
INSERT INTO knowledge_quiz VALUES(3327,'Which demon was killed by Krishna in Mathura arena?','मथुरा की रंगभूमि में कृष्ण ने किस असुर का वध किया?','[{"key": "A", "en": "Chanura", "hi": "चाणूर"}, {"key": "B", "en": "Mushtika", "hi": "मुष्टिक"}, {"key": "C", "en": "Kamsa", "hi": "कंस"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3328,'Who was the wife of Indra?','इंद्र की पत्नी कौन थीं?','[{"key": "A", "en": "Aditi", "hi": "अदिति"}, {"key": "B", "en": "Shachi", "hi": "शची"}, {"key": "C", "en": "Diti", "hi": "दिति"}, {"key": "D", "en": "Rati", "hi": "रति"}]','B');
INSERT INTO knowledge_quiz VALUES(3329,'Which sage cursed Menaka to forget Vishwamitra?','मेनका को विश्वामित्र को भूलने का शाप किसने दिया?','[{"key": "A", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "B", "en": "Kanva", "hi": "कण्व"}, {"key": "C", "en": "Durvasa", "hi": "दुर्वासा"}, {"key": "D", "en": "Bharata", "hi": "भरत"}]','C');
INSERT INTO knowledge_quiz VALUES(3330,'Who was the guardian deity of Ayodhya?','अयोध्या के अधिष्ठाता देव कौन माने जाते हैं?','[{"key": "A", "en": "Rama", "hi": "राम"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Kubera", "hi": "कुबेर"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','D');
INSERT INTO knowledge_quiz VALUES(3331,'Who was the son of Krishna and Rukmini?','कृष्ण और रुक्मिणी के पुत्र कौन थे?','[{"key": "A", "en": "Pradyumna", "hi": "प्रद्युम्न"}, {"key": "B", "en": "Samba", "hi": "सांब"}, {"key": "C", "en": "Aniruddha", "hi": "अनिरुद्ध"}, {"key": "D", "en": "Charudeshna", "hi": "चारुदेष्ण"}]','A');
INSERT INTO knowledge_quiz VALUES(3332,'Which demon tried to crush Krishna with a cart?','कृष्ण को शकट के नीचे दबाने का प्रयास किस असुर ने किया?','[{"key": "A", "en": "Putana", "hi": "पूतना"}, {"key": "B", "en": "Trinavarta", "hi": "तृणावर्त"}, {"key": "C", "en": "Shakatasura", "hi": "शकटासुर"}, {"key": "D", "en": "Bakāsura", "hi": "बकासुर"}]','C');
INSERT INTO knowledge_quiz VALUES(3333,'Who was the guru of Parashurama?','परशुराम के गुरु कौन थे?','[{"key": "A", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "B", "en": "Dattatreya", "hi": "दत्तात्रेय"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','C');
INSERT INTO knowledge_quiz VALUES(3334,'Which queen was known for her chastity and devotion?','पतिव्रता और भक्ति के लिए कौन सी रानी प्रसिद्ध थीं?','[{"key": "A", "en": "Damayanti", "hi": "दमयंती"}, {"key": "B", "en": "Savitri", "hi": "सावित्री"}, {"key": "C", "en": "Anasuya", "hi": "अनसूया"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3335,'Who killed the demoness Tadaka?','ताड़का राक्षसी का वध किसने किया था?','[{"key": "A", "en": "Laxmana", "hi": "लक्ष्मण"}, {"key": "B", "en": "Lord Rama", "hi": "भगवान राम"}, {"key": "C", "en": "Bharata", "hi": "भरत"}, {"key": "D", "en": "Sage Vishwamitra", "hi": "ऋषि विश्वामित्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3336,'Which sage composed the Vishnu Purana?','विष्णु पुराण की रचना किस ऋषि ने की?','[{"key": "A", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "B", "en": "Vyasa", "hi": "व्यास"}, {"key": "C", "en": "Parashara", "hi": "पराशर"}, {"key": "D", "en": "Narada", "hi": "नारद"}]','C');
INSERT INTO knowledge_quiz VALUES(3337,'Who was the wife of Yudhishthira?','युधिष्ठिर की पत्नी कौन थीं?','[{"key": "A", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "B", "en": "Devika", "hi": "देविका"}, {"key": "C", "en": "Bhanumati", "hi": "भानुमती"}, {"key": "D", "en": "Subhadra", "hi": "सुभद्रा"}]','B');
INSERT INTO knowledge_quiz VALUES(3338,'Which demon was killed by Matsya avatar?','मत्स्य अवतार ने किस असुर का वध किया?','[{"key": "A", "en": "Hayagriva", "hi": "हयग्रीव"}, {"key": "B", "en": "Madhu", "hi": "मधु"}, {"key": "C", "en": "Kaitabha", "hi": "कैटभ"}, {"key": "D", "en": "Shankhasura", "hi": "शंखासुर"}]','D');
INSERT INTO knowledge_quiz VALUES(3339,'Who is the son of Ahalya and Sage Gautama, who served as the chief priest in the court of King Janaka?','अहल्या और ऋषि गौतम के पुत्र कौन हैं, जिन्होंने राजा जनक के दरबार में मुख्य पुरोहित के रूप में सेवा की थी?','[{"key": "A", "en": "Satananda", "hi": "शतानंद"}, {"key": "B", "en": "Nachiketa", "hi": "नचिकेता"}, {"key": "C", "en": "Shringi", "hi": "शृंगी"}, {"key": "D", "en": "Markandeya", "hi": "मार्केन्डेय"}]','A');
INSERT INTO knowledge_quiz VALUES(3340,'Who was the commander of Kaurava army after Bhishma fell?','भीष्म के पतन के बाद कौरव सेना का सेनापति कौन बना?','[{"key": "A", "en": "Drona", "hi": "द्रोण"}, {"key": "B", "en": "Karna", "hi": "कर्ण"}, {"key": "C", "en": "Shalya", "hi": "शल्य"}, {"key": "D", "en": "Ashwatthama", "hi": "अश्वत्थामा"}]','A');
INSERT INTO knowledge_quiz VALUES(3341,'Which sage cursed Urvashi to become mortal?','उर्वशी को नश्वर बनने का शाप किसने दिया?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "C", "en": "Bharata", "hi": "भरत"}, {"key": "D", "en": "Durvasa", "hi": "दुर्वासा"}]','D');
INSERT INTO knowledge_quiz VALUES(3342,'Who was the father of Sugriva?','सुग्रीव के पिता कौन थे?','[{"key": "A", "en": "Surya", "hi": "सूर्य"}, {"key": "B", "en": "Indra", "hi": "इंद्र"}, {"key": "C", "en": "Vayu", "hi": "वायु"}, {"key": "D", "en": "Kubera", "hi": "कुबेर"}]','A');
INSERT INTO knowledge_quiz VALUES(3343,'Which demon was slain by Kurma avatar?','कूर्म अवतार ने किस असुर का वध किया?','[{"key": "A", "en": "None", "hi": "कोई नहीं"}, {"key": "B", "en": "Hiranyaksha", "hi": "हिरण्याक्ष"}, {"key": "C", "en": "Madhu", "hi": "मधु"}, {"key": "D", "en": "Kaitabha", "hi": "कैटभ"}]','A');
INSERT INTO knowledge_quiz VALUES(3344,'Who was the daughter of King Daksha married to Shiva?','दक्ष प्रजापति की कौन सी पुत्री शिव से विवाह करती हैं?','[{"key": "A", "en": "Sati", "hi": "सती"}, {"key": "B", "en": "Uma", "hi": "उमा"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3345,'Who was the son of Ravana known for his righteousness?','रावण का कौन सा पुत्र धर्मनिष्ठ माना जाता है?','[{"key": "A", "en": "Meghanada", "hi": "मेघनाद"}, {"key": "B", "en": "Akshayakumara", "hi": "अक्षयकुमार"}, {"key": "C", "en": "Atikaya", "hi": "अतिकाय"}, {"key": "D", "en": "Vibhishana", "hi": "विभीषण"}]','D');
INSERT INTO knowledge_quiz VALUES(3346,'Which sage taught the Gayatri Mantra?','गायत्री मंत्र के द्रष्टा ऋषि कौन हैं?','[{"key": "A", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "B", "en": "Vishwamitra", "hi": "विश्वामित्र"}, {"key": "C", "en": "Atri", "hi": "अत्रि"}, {"key": "D", "en": "Bharadvaja", "hi": "भरद्वाज"}]','B');
INSERT INTO knowledge_quiz VALUES(3347,'Who was the wife of Bhima?','भीम की पत्नी कौन थीं?','[{"key": "A", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "B", "en": "Hidimba", "hi": "हिडिंबा"}, {"key": "C", "en": "Kunti", "hi": "कुंती"}, {"key": "D", "en": "Subhadra", "hi": "सुभद्रा"}]','B');
INSERT INTO knowledge_quiz VALUES(3348,'At the Nalhati Peetha, which part of Sati fell?','नलहटी पीठ में सती का कौन सा अंग गिरा था?','[{"key": "A", "en": "Vocal cords", "hi": "कंठ"}, {"key": "B", "en": "Fingers", "hi": "उंगलियां"}, {"key": "C", "en": "Stomach", "hi": "पेट"}, {"key": "D", "en": "Leg bone", "hi": "पैर की हड्डी (नली)"}]','A');
INSERT INTO knowledge_quiz VALUES(3349,'Who was the maternal uncle of the Pandavas?','पांडवों के मामा कौन थे?','[{"key": "A", "en": "Shakuni", "hi": "शकुनि"}, {"key": "B", "en": "Vasudeva", "hi": "वसुदेव"}, {"key": "C", "en": "Shalya", "hi": "शल्य"}, {"key": "D", "en": "Drupada", "hi": "द्रुपद"}]','C');
INSERT INTO knowledge_quiz VALUES(3350,'The Jejuri Temple, famous for the ''Bhandara'' (turmeric powder) festival, is dedicated to which deity?','जेजुरी मंदिर, जो ''भंडारा'' (हल्दी पाउडर) उत्सव के लिए प्रसिद्ध है, किस देवता को समर्पित है?','[{"key": "A", "en": "Khandoba", "hi": "खंडोबा"}, {"key": "B", "en": "Bhairav", "hi": "भैरव"}, {"key": "C", "en": "Vithoba", "hi": "विठोबा"}, {"key": "D", "en": "Kartikeya", "hi": "कार्तिकेय"}]','A');
INSERT INTO knowledge_quiz VALUES(3351,'Who was the son of Sage Atri and Anasuya?','ऋषि अत्रि और अनसूया के पुत्र कौन थे?','[{"key": "A", "en": "Dattatreya", "hi": "दत्तात्रेय"}, {"key": "B", "en": "Durvasa", "hi": "दुर्वासा"}, {"key": "C", "en": "Chandra", "hi": "चंद्र"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3352,'Which king was turned into a woman by a curse and later regained manhood?','कौन सा राजा शाप से स्त्री बना और बाद में पुनः पुरुष बना?','[{"key": "A", "en": "Ila", "hi": "इला"}, {"key": "B", "en": "Nahusha", "hi": "नहुष"}, {"key": "C", "en": "Yayati", "hi": "ययाति"}, {"key": "D", "en": "Pururava", "hi": "पुरूरवा"}]','A');
INSERT INTO knowledge_quiz VALUES(3353,'Who was the son of Krishna and Jambavati?','कृष्ण और जाम्बवती के पुत्र कौन थे?','[{"key": "A", "en": "Pradyumna", "hi": "प्रद्युम्न"}, {"key": "B", "en": "Samba", "hi": "सांब"}, {"key": "C", "en": "Aniruddha", "hi": "अनिरुद्ध"}, {"key": "D", "en": "Charudeshna", "hi": "चारुदेष्ण"}]','B');
INSERT INTO knowledge_quiz VALUES(3354,'Which sage cursed King Yayati with premature old age?','राजा ययाति को अकाल वृद्धावस्था का शाप किस ऋषि ने दिया?','[{"key": "A", "en": "Shukracharya", "hi": "शुक्राचार्य"}, {"key": "B", "en": "Brihaspati", "hi": "बृहस्पति"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Vashistha", "hi": "वशिष्ठ"}]','A');
INSERT INTO knowledge_quiz VALUES(3355,'Who was the mother of King Bharata (of Bharata dynasty)?','भरत वंश के राजा भरत की माता कौन थीं?','[{"key": "A", "en": "Shakuntala", "hi": "शकुंतला"}, {"key": "B", "en": "Devayani", "hi": "देवयानी"}, {"key": "C", "en": "Madri", "hi": "माद्री"}, {"key": "D", "en": "Kunti", "hi": "कुंती"}]','A');
INSERT INTO knowledge_quiz VALUES(3356,'Which asura was slain by Lord Vishnu as Hayagriva?','हयग्रीव अवतार में विष्णु ने किस असुर का वध किया?','[{"key": "A", "en": "Madhu", "hi": "मधु"}, {"key": "B", "en": "Kaitabha", "hi": "कैटभ"}, {"key": "C", "en": "Hayagriva", "hi": "हयग्रीव"}, {"key": "D", "en": "Shankhasura", "hi": "शंखासुर"}]','D');
INSERT INTO knowledge_quiz VALUES(3357,'Who was the wife of Sage Vashistha?','ऋषि वशिष्ठ की पत्नी कौन थीं?','[{"key": "A", "en": "Anasuya", "hi": "अनसूया"}, {"key": "B", "en": "Arundhati", "hi": "अरुंधती"}, {"key": "C", "en": "Lopamudra", "hi": "लोपामुद्रा"}, {"key": "D", "en": "Sati", "hi": "सती"}]','B');
INSERT INTO knowledge_quiz VALUES(3358,'Which king was cursed to become a python by Sage Agastya?','ऋषि अगस्त्य के शाप से कौन सा राजा अजगर बना?','[{"key": "A", "en": "Nahusha", "hi": "नहुष"}, {"key": "B", "en": "Bali", "hi": "बलि"}, {"key": "C", "en": "Kusha", "hi": "कुश"}, {"key": "D", "en": "Dilipa", "hi": "दिलिप"}]','A');
INSERT INTO knowledge_quiz VALUES(3359,'Who was the divine horse used in the Ashvamedha Yajna?','अश्वमेध यज्ञ में प्रयुक्त दिव्य घोड़े का क्या नाम था?','[{"key": "A", "en": "Uchchaihshravas", "hi": "उच्चैःश्रवस"}, {"key": "B", "en": "Hayagriva", "hi": "हयग्रीव"}, {"key": "C", "en": "Devadatta", "hi": "देवदत्त"}, {"key": "D", "en": "No specific name", "hi": "कोई निश्चित नाम नहीं"}]','D');
INSERT INTO knowledge_quiz VALUES(3360,'Which queen gave birth to the hundred Kauravas?','किस रानी ने सौ कौरवों को जन्म दिया?','[{"key": "A", "en": "Kunti", "hi": "कुंती"}, {"key": "B", "en": "Gandhari", "hi": "गांधारी"}, {"key": "C", "en": "Ambika", "hi": "अंबिका"}, {"key": "D", "en": "Ambalika", "hi": "अंबालिका"}]','B');
INSERT INTO knowledge_quiz VALUES(3361,'Who was the son of Bhishma''s half-brother Vichitravirya?','भीष्म के सौतेले भाई विचित्रवीर्य के पुत्र कौन थे?','[{"key": "A", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}, {"key": "B", "en": "Pandu", "hi": "पांडु"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Vidura", "hi": "विदुर"}]','C');
INSERT INTO knowledge_quiz VALUES(3362,'Which demon was killed by Lord Shiva in the form of Kirata?','किरात रूप में शिव ने किस असुर का वध किया?','[{"key": "A", "en": "Andhaka", "hi": "अंधक"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Banasura", "hi": "बाणासुर"}, {"key": "D", "en": "None", "hi": "कोई नहीं"}]','D');
INSERT INTO knowledge_quiz VALUES(3363,'Who is the creator of Ahalya, considered as the most beautiful woman in the world?','विश्व की सबसे सुंदर स्त्री के रूप में अहल्या की रचना किसने की थी?','[{"key": "A", "en": "Lord Vishnu", "hi": "भगवान विष्णु"}, {"key": "B", "en": "Lord Brahma", "hi": "भगवान ब्रह्मा"}, {"key": "C", "en": "Lord Shiva", "hi": "भगवान शिव"}, {"key": "D", "en": "Sage Kashyapa", "hi": "ऋषि कश्यप"}]','B');
