INSERT INTO knowledge_quiz VALUES(3406,'Which temple in Gujarat is dedicated to the ''Goddess of Curse'' and has a crocodile as its vahana?','गुजरात का कौन सा मंदिर ''शाप की देवी'' को समर्पित है और जिनका वाहन मगरमच्छ है?','[{"key": "A", "en": "Matangi Modheshwari", "hi": "मातंगी मोधेश्वरी"}, {"key": "B", "en": "Khodiyar Dham, Kagvad", "hi": "खोड़ियार धाम, कागवद"}, {"key": "C", "en": "Bahucharaji", "hi": "बहुचराजी"}, {"key": "D", "en": "Chamunda Mata", "hi": "चामुंडा माता"}]','B');
INSERT INTO knowledge_quiz VALUES(3407,'Who was the mother of Sage Agastya?','ऋषि अगस्त्य की माता कौन थीं?','[{"key": "A", "en": "Lopamudra", "hi": "लोपामुद्रा"}, {"key": "B", "en": "Urvashi", "hi": "उर्वशी"}, {"key": "C", "en": "None (born from a pot)", "hi": "कोई नहीं (घड़े से उत्पन्न)"}, {"key": "D", "en": "Arundhati", "hi": "अरुंधती"}]','C');
