INSERT INTO knowledge_quiz VALUES(3409,'Who was the teacher of Prince Rama?','राजकुमार राम के गुरु कौन थे?','[{"key": "A", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "B", "en": "Vishwamitra", "hi": "विश्वामित्र"}, {"key": "C", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "D", "en": "Bharadvaja", "hi": "भरद्वाज"}]','B');
