INSERT INTO knowledge_quiz VALUES(3414,'Which demon was reduced to ashes by Kapila’s glance?','कपिल मुनि की दृष्टि से कौन भस्म हुआ?','[{"key": "A", "en": "Sagara’s sons", "hi": "सगर के पुत्र"}, {"key": "B", "en": "Kaitabha", "hi": "कैटभ"}, {"key": "C", "en": "Madhu", "hi": "मधु"}, {"key": "D", "en": "Andhaka", "hi": "अंधक"}]','A');
INSERT INTO knowledge_quiz VALUES(3415,'Who was the mother of Sage Atri’s children?','ऋषि अत्रि के पुत्रों की माता कौन थीं?','[{"key": "A", "en": "Arundhati", "hi": "अरुंधती"}, {"key": "B", "en": "Anasuya", "hi": "अनसूया"}, {"key": "C", "en": "Lopamudra", "hi": "लोपामुद्रा"}, {"key": "D", "en": "Renuka", "hi": "रेणुका"}]','B');
