INSERT INTO knowledge_quiz VALUES(3422,'Which demon was slain by Skanda (Kartikeya)?','कार्तिकेय ने किस असुर का वध किया?','[{"key": "A", "en": "Tarakasura", "hi": "तारकासुर"}, {"key": "B", "en": "Banasura", "hi": "बाणासुर"}, {"key": "C", "en": "Andhaka", "hi": "अंधक"}, {"key": "D", "en": "Jalandhara", "hi": "जलंधर"}]','A');
