INSERT INTO knowledge_quiz VALUES(3491,'Which sage cursed Parvati to be reborn as a human?','पार्वती को मानव रूप में जन्म लेने का शाप किसने दिया?','[{"key": "A", "en": "Daksha", "hi": "दक्ष"}, {"key": "B", "en": "Narada", "hi": "नारद"}, {"key": "C", "en": "None (divine will)", "hi": "कोई नहीं (दैवी इच्छा)"}, {"key": "D", "en": "Durvasa", "hi": "दुर्वासा"}]','C');
INSERT INTO knowledge_quiz VALUES(3492,'Who was the father of Lord Ganesha?','भगवान गणेश के पिता कौन हैं?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','A');
INSERT INTO knowledge_quiz VALUES(3493,'Which weapon did Shiva use to behead Ganesha?','गणेश का मस्तक काटने के लिए शिव ने कौन सा अस्त्र प्रयोग किया?','[{"key": "A", "en": "Trishula", "hi": "त्रिशूल"}, {"key": "B", "en": "Sudarshana Chakra", "hi": "सुदर्शन चक्र"}, {"key": "C", "en": "Sword", "hi": "खड्ग"}, {"key": "D", "en": "None specified", "hi": "विशेष उल्लेख नहीं"}]','D');
INSERT INTO knowledge_quiz VALUES(3494,'Which animal’s head was placed on Ganesha?','गणेश को किस प्राणी का मस्तक लगाया गया?','[{"key": "A", "en": "Horse", "hi": "घोड़ा"}, {"key": "B", "en": "Elephant", "hi": "हाथी"}, {"key": "C", "en": "Lion", "hi": "सिंह"}, {"key": "D", "en": "Bull", "hi": "बैल"}]','B');
INSERT INTO knowledge_quiz VALUES(3495,'Who was the vehicle of Lord Ganesha?','भगवान गणेश का वाहन कौन है?','[{"key": "A", "en": "Mouse", "hi": "मूषक"}, {"key": "B", "en": "Peacock", "hi": "मोर"}, {"key": "C", "en": "Bull", "hi": "बैल"}, {"key": "D", "en": "Lion", "hi": "सिंह"}]','A');
INSERT INTO knowledge_quiz VALUES(3496,'Who was the brother of Lord Ganesha?','भगवान गणेश के भाई कौन हैं?','[{"key": "A", "en": "Skanda (Kartikeya)", "hi": "स्कंद (कार्तिकेय)"}, {"key": "B", "en": "Ayyappa", "hi": "अय्यप्पा"}, {"key": "C", "en": "Hanuman", "hi": "हनुमान"}, {"key": "D", "en": "None", "hi": "कोई नहीं"}]','A');
INSERT INTO knowledge_quiz VALUES(3497,'Which temple is famous for the ''Thrissur Pooram'' festival, featuring a spectacular display of caparisoned elephants and fireworks?','कौन सा मंदिर ''त्रिशूर पूरम'' उत्सव के लिए प्रसिद्ध है, जिसमें सजे हुए हाथियों और आतिशबाजी का भव्य प्रदर्शन होता है?','[{"key": "A", "en": "Vadakkunnathan Temple", "hi": "वडक्कुन्नाथन मंदिर"}, {"key": "B", "en": "Chottanikkara Temple", "hi": "छोटानिक्करा मंदिर"}, {"key": "C", "en": "Ettumanoor Mahadeva", "hi": "एट्टुमानूर महादेव"}, {"key": "D", "en": "Ambalappuzha Krishna", "hi": "अम्बलप्पुझा कृष्ण"}]','A');
INSERT INTO knowledge_quiz VALUES(3498,'According to the Brahma Purana, which Saptarishi brought the River Ganga to the South?','ब्रह्म पुराण के अनुसार, किस सप्तर्षि ने गंगा नदी को दक्षिण में उतारा था?','[{"key": "A", "en": "Sage Vashistha", "hi": "ऋषि वशिष्ठ"}, {"key": "B", "en": "Sage Gautama", "hi": "ऋषि गौतम"}, {"key": "C", "en": "Sage Agastya", "hi": "ऋषि अगस्त्य"}, {"key": "D", "en": "Sage Vishwamitra", "hi": "ऋषि विश्वामित्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3499,'Which demon was slain by Skanda at a young age?','बाल्यावस्था में स्कंद ने किस असुर का वध किया?','[{"key": "A", "en": "Taraka", "hi": "तारक"}, {"key": "B", "en": "Banasura", "hi": "बाणासुर"}, {"key": "C", "en": "Shumbha", "hi": "शुम्भ"}, {"key": "D", "en": "Andhaka", "hi": "अंधक"}]','A');
INSERT INTO knowledge_quiz VALUES(3500,'The Walkeshwar Temple in Malabar Hill has a pond nearby which is believed to have been created by an arrow shot by Lord Rama. What is its name?','मालाबार हिल स्थित वाळकेश्वर मंदिर के पास एक तालाब है जिसके बारे में माना जाता है कि इसे भगवान राम के बाण से बनाया गया था। इसका नाम क्या है?','[{"key": "A", "en": "Rama Kund", "hi": "राम कुंड"}, {"key": "B", "en": "Banganga Tank", "hi": "बाणगंगा टैंक"}, {"key": "C", "en": "Pushkarani", "hi": "पुष्करणी"}, {"key": "D", "en": "Surya Kund", "hi": "सूर्य कुंड"}]','B');
INSERT INTO knowledge_quiz VALUES(3501,'Who is the narrator of the Shiva Purana?','शिव पुराण के कथावाचक कौन हैं?','[{"key": "A", "en": "Ved Vyasa", "hi": "वेदव्यास"}, {"key": "B", "en": "Suta Lomaharshana", "hi": "सूत लोमहर्षण"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Shiva", "hi": "शिव"}]','B');
INSERT INTO knowledge_quiz VALUES(3502,'To whom was the Shiva Purana narrated by Suta?','सूत जी ने शिव पुराण किसे सुनाया?','[{"key": "A", "en": "Pandavas", "hi": "पांडव"}, {"key": "B", "en": "Sages of Naimisharanya", "hi": "नैमिषारण्य के ऋषि"}, {"key": "C", "en": "Devas", "hi": "देवता"}, {"key": "D", "en": "Kings", "hi": "राजा"}]','B');
INSERT INTO knowledge_quiz VALUES(3503,'Who is the consort of Lord Shiva according to Shiva Purana?','शिव पुराण के अनुसार भगवान शिव की पत्नी कौन हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','C');
INSERT INTO knowledge_quiz VALUES(3504,'What is the symbolic form of Lord Shiva worshipped in Shiva Purana?','शिव पुराण में भगवान शिव का कौन सा प्रतीक रूप पूजित है?','[{"key": "A", "en": "Murti", "hi": "मूर्ति"}, {"key": "B", "en": "Lingam", "hi": "लिंग"}, {"key": "C", "en": "Yantra", "hi": "यंत्र"}, {"key": "D", "en": "Mandala", "hi": "मंडल"}]','B');
INSERT INTO knowledge_quiz VALUES(3505,'Who was the first wife of Lord Shiva?','भगवान शिव की प्रथम पत्नी कौन थीं?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Sati", "hi": "सती"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Uma", "hi": "उमा"}]','B');
INSERT INTO knowledge_quiz VALUES(3506,'Who was the father of Goddess Sati?','देवी सती के पिता कौन थे?','[{"key": "A", "en": "Himavan", "hi": "हिमवान"}, {"key": "B", "en": "Daksha", "hi": "दक्ष"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Kashyapa", "hi": "कश्यप"}]','B');
INSERT INTO knowledge_quiz VALUES(3507,'What event led to the self-immolation of Goddess Sati?','किस घटना के कारण देवी सती ने आत्मदाह किया?','[{"key": "A", "en": "Battle with demons", "hi": "दानवों से युद्ध"}, {"key": "B", "en": "Daksha Yajna insult", "hi": "दक्ष यज्ञ में अपमान"}, {"key": "C", "en": "Curse of sages", "hi": "ऋषियों का शाप"}, {"key": "D", "en": "Command of Shiva", "hi": "शिव की आज्ञा"}]','B');
INSERT INTO knowledge_quiz VALUES(3508,'Who carried the body of Goddess Sati after her death?','देवी सती के शरीर को कौन लेकर चले?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3509,'What are the sacred places formed from Sati’s body called?','सती के शरीर से बने पवित्र स्थान क्या कहलाते हैं?','[{"key": "A", "en": "Jyotirlingas", "hi": "ज्योतिर्लिंग"}, {"key": "B", "en": "Shakti Peethas", "hi": "शक्ति पीठ"}, {"key": "C", "en": "Char Dham", "hi": "चार धाम"}, {"key": "D", "en": "Tirthas", "hi": "तीर्थ"}]','B');
INSERT INTO knowledge_quiz VALUES(3510,'Who cut the body of Sati into pieces?','सती के शरीर को किसने खंड-खंड किया?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3511,'The Guruvayur Temple is dedicated to Lord Krishna in which specific form?','गुरुवायुर मंदिर भगवान कृष्ण के किस विशिष्ट रूप को समर्पित है?','[{"key": "A", "en": "Parthasarathy", "hi": "पार्थसारथी"}, {"key": "B", "en": "Guruvayurappan (Child Krishna)", "hi": "गुरुवायुरप्पन (बाल कृष्ण)"}, {"key": "C", "en": "Venugopala", "hi": "वेणुगोपाल"}, {"key": "D", "en": "Jagannath", "hi": "जगन्नाथ"}]','B');
INSERT INTO knowledge_quiz VALUES(3512,'What is the vehicle of Lord Shiva?','भगवान शिव का वाहन क्या है?','[{"key": "A", "en": "Garuda", "hi": "गरुड़"}, {"key": "B", "en": "Nandi", "hi": "नंदी"}, {"key": "C", "en": "Lion", "hi": "सिंह"}, {"key": "D", "en": "Horse", "hi": "घोड़ा"}]','B');
INSERT INTO knowledge_quiz VALUES(3513,'Which poison did Lord Shiva consume during Samudra Manthan?','समुद्र मंथन के समय भगवान शिव ने कौन सा विष पिया?','[{"key": "A", "en": "Amrita", "hi": "अमृत"}, {"key": "B", "en": "Halahala", "hi": "हलाहल"}, {"key": "C", "en": "Kalakuta", "hi": "कालकूट"}, {"key": "D", "en": "Visha", "hi": "विष"}]','C');
INSERT INTO knowledge_quiz VALUES(3514,'What title did Shiva receive after consuming poison?','विष पीने के बाद शिव को कौन सी उपाधि मिली?','[{"key": "A", "en": "Neelkanth", "hi": "नीलकंठ"}, {"key": "B", "en": "Mahadev", "hi": "महादेव"}, {"key": "C", "en": "Trilokinath", "hi": "त्रिलोकीनाथ"}, {"key": "D", "en": "Bholenath", "hi": "भोलेनाथ"}]','A');
INSERT INTO knowledge_quiz VALUES(3515,'Who is the son of Lord Shiva and Goddess Parvati with an elephant head?','हाथी के मस्तक वाले शिव-पार्वती के पुत्र कौन हैं?','[{"key": "A", "en": "Kartikeya", "hi": "कार्तिकेय"}, {"key": "B", "en": "Nandi", "hi": "नंदी"}, {"key": "C", "en": "Ganesha", "hi": "गणेश"}, {"key": "D", "en": "Veerabhadra", "hi": "वीरभद्र"}]','C');
INSERT INTO knowledge_quiz VALUES(3516,'Who was created from Shiva’s wrath at Daksha Yajna?','दक्ष यज्ञ में शिव के क्रोध से किसकी उत्पत्ति हुई?','[{"key": "A", "en": "Ganesha", "hi": "गणेश"}, {"key": "B", "en": "Kartikeya", "hi": "कार्तिकेय"}, {"key": "C", "en": "Veerabhadra", "hi": "वीरभद्र"}, {"key": "D", "en": "Nandi", "hi": "नंदी"}]','C');
INSERT INTO knowledge_quiz VALUES(3517,'Which Purana is considered the greatest devotee of Shiva?','कौन सा पुराण शिवभक्ति को सर्वश्रेष्ठ मानता है?','[{"key": "A", "en": "Vishnu Purana", "hi": "विष्णु पुराण"}, {"key": "B", "en": "Shiva Purana", "hi": "शिव पुराण"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Markandeya Purana", "hi": "मार्कण्डेय पुराण"}]','B');
INSERT INTO knowledge_quiz VALUES(3518,'Who is the chief of Shiva’s ganas?','शिव के गणों के प्रधान कौन हैं?','[{"key": "A", "en": "Nandi", "hi": "नंदी"}, {"key": "B", "en": "Ganesha", "hi": "गणेश"}, {"key": "C", "en": "Veerabhadra", "hi": "वीरभद्र"}, {"key": "D", "en": "Bhringi", "hi": "भृंगी"}]','A');
INSERT INTO knowledge_quiz VALUES(3519,'What form of Shiva represents cosmic destruction?','शिव का कौन सा रूप ब्रह्मांडीय संहार का प्रतीक है?','[{"key": "A", "en": "Sadashiva", "hi": "सदाशिव"}, {"key": "B", "en": "Rudra", "hi": "रुद्र"}, {"key": "C", "en": "Nataraja", "hi": "नटराज"}, {"key": "D", "en": "Shankara", "hi": "शंकर"}]','C');
INSERT INTO knowledge_quiz VALUES(3520,'What is the sacred mantra associated with Lord Shiva?','भगवान शिव से संबंधित पवित्र मंत्र कौन सा है?','[{"key": "A", "en": "Gayatri Mantra", "hi": "गायत्री मंत्र"}, {"key": "B", "en": "Mahamrityunjaya Mantra", "hi": "महामृत्युंजय मंत्र"}, {"key": "C", "en": "Purusha Sukta", "hi": "पुरुष सूक्त"}, {"key": "D", "en": "Narayan Mantra", "hi": "नारायण मंत्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3521,'Who is considered the greatest devotee of Lord Shiva?','भगवान शिव के सबसे बड़े भक्त कौन माने जाते हैं?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Prahlada", "hi": "प्रह्लाद"}, {"key": "C", "en": "Markandeya", "hi": "मार्कण्डेय"}, {"key": "D", "en": "Ravana", "hi": "रावण"}]','D');
INSERT INTO knowledge_quiz VALUES(3522,'Which demon king was blessed by Shiva with immense power?','किस असुर राजा को शिव से अपार शक्ति का वरदान मिला?','[{"key": "A", "en": "Hiranyakashipu", "hi": "हिरण्यकशिपु"}, {"key": "B", "en": "Bhasmasura", "hi": "भस्मासुर"}, {"key": "C", "en": "Ravana", "hi": "रावण"}, {"key": "D", "en": "Tarakasura", "hi": "तारकासुर"}]','C');
INSERT INTO knowledge_quiz VALUES(3523,'Who ultimately killed Tarakasura?','तारकासुर का वध किसने किया?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Kartikeya", "hi": "कार्तिकेय"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','C');
INSERT INTO knowledge_quiz VALUES(3524,'What does the crescent moon on Shiva’s head symbolize?','शिव के मस्तक पर चंद्रमा किसका प्रतीक है?','[{"key": "A", "en": "Time", "hi": "समय"}, {"key": "B", "en": "Immortality", "hi": "अमरत्व"}, {"key": "C", "en": "Mind", "hi": "मन"}, {"key": "D", "en": "Beauty", "hi": "सौंदर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(3525,'What river flows from Lord Shiva’s matted hair?','भगवान शिव की जटाओं से कौन सी नदी निकलती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','C');
INSERT INTO knowledge_quiz VALUES(3526,'Who is the main narrator of the Bhagavata Purana?','भागवत पुराण के मुख्य कथावाचक कौन हैं?','[{"key": "A", "en": "Ved Vyasa", "hi": "वेदव्यास"}, {"key": "B", "en": "Narada", "hi": "नारद"}, {"key": "C", "en": "Shukadeva", "hi": "शुकदेव"}, {"key": "D", "en": "Suta Lomaharshana", "hi": "सूत लोमहर्षण"}]','C');
INSERT INTO knowledge_quiz VALUES(3527,'To whom was the Bhagavata Purana narrated by Shukadeva?','शुकदेव जी ने भागवत पुराण किसे सुनाया?','[{"key": "A", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "B", "en": "Parikshit", "hi": "परीक्षित"}, {"key": "C", "en": "Janamejaya", "hi": "जनमेजय"}, {"key": "D", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3528,'Which incarnation of Vishnu is primarily glorified in the Bhagavata Purana?','भागवत पुराण में विष्णु के किस अवतार की विशेष महिमा है?','[{"key": "A", "en": "Rama", "hi": "राम"}, {"key": "B", "en": "Narasimha", "hi": "नरसिंह"}, {"key": "C", "en": "Krishna", "hi": "कृष्ण"}, {"key": "D", "en": "Vamana", "hi": "वामन"}]','C');
INSERT INTO knowledge_quiz VALUES(3529,'How many Skandhas (books) are there in the Bhagavata Purana?','भागवत पुराण में कुल कितने स्कंध हैं?','[{"key": "A", "en": "10", "hi": "10"}, {"key": "B", "en": "12", "hi": "12"}, {"key": "C", "en": "14", "hi": "14"}, {"key": "D", "en": "18", "hi": "18"}]','B');
INSERT INTO knowledge_quiz VALUES(3530,'What herb did Hanuman bring to save Laxmana''s life?','लक्ष्मण के प्राण बचाने के लिए हनुमान कौन सी औषधि लाए थे?','[{"key": "A", "en": "Tulsi", "hi": "तुलसी"}, {"key": "B", "en": "Sanjivani", "hi": "संजीवनी"}, {"key": "C", "en": "Ashwagandha", "hi": "अश्वगंधा"}, {"key": "D", "en": "Neem", "hi": "नीम"}]','B');
INSERT INTO knowledge_quiz VALUES(3531,'Which river was brought down to Earth by Sage Gautama to purify himself from the sin of ''Go-hatya'' (accidental killing of a cow)?','अनजाने में हुई ''गौ-हत्या'' के पाप से मुक्ति पाने के लिए ऋषि गौतम किस नदी को पृथ्वी पर लाए थे?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Godavari", "hi": "गोदावरी"}, {"key": "C", "en": "Yamuna", "hi": "यमुना"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','B');
INSERT INTO knowledge_quiz VALUES(3532,'Who raised Krishna in Gokul?','गोकुल में कृष्ण का पालन-पोषण किसने किया?','[{"key": "A", "en": "Devaki", "hi": "देवकी"}, {"key": "B", "en": "Rohini", "hi": "रोहिणी"}, {"key": "C", "en": "Yashoda", "hi": "यशोदा"}, {"key": "D", "en": "Kunti", "hi": "कुंती"}]','C');
INSERT INTO knowledge_quiz VALUES(3533,'Who was the tyrant king defeated by Lord Krishna in Mathura?','मथुरा में भगवान कृष्ण ने किस अत्याचारी राजा का वध किया?','[{"key": "A", "en": "Jarasandha", "hi": "जरासंध"}, {"key": "B", "en": "Kamsa", "hi": "कंस"}, {"key": "C", "en": "Shishupala", "hi": "शिशुपाल"}, {"key": "D", "en": "Dantavakra", "hi": "दंतवक्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3534,'Who is the elder brother of Lord Krishna?','भगवान कृष्ण के बड़े भाई कौन हैं?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Balarama", "hi": "बलराम"}, {"key": "C", "en": "Sudama", "hi": "सुदामा"}, {"key": "D", "en": "Satyaki", "hi": "सात्यकि"}]','B');
INSERT INTO knowledge_quiz VALUES(3535,'Which demon did Krishna kill by lifting Govardhan Hill?','गोवर्धन पर्वत उठाने की लीला किस प्रसंग से जुड़ी है?','[{"key": "A", "en": "Kaliya", "hi": "कालिय"}, {"key": "B", "en": "Indra’s pride", "hi": "इंद्र का अभिमान"}, {"key": "C", "en": "Putana", "hi": "पूतना"}, {"key": "D", "en": "Aghasura", "hi": "अघासुर"}]','B');
INSERT INTO knowledge_quiz VALUES(3536,'Who was the serpent subdued by Krishna in the Yamuna river?','यमुना नदी में कृष्ण ने किस नाग का दमन किया?','[{"key": "A", "en": "Takshaka", "hi": "तक्षक"}, {"key": "B", "en": "Kaliya", "hi": "कालिय"}, {"key": "C", "en": "Vasuki", "hi": "वासुकि"}, {"key": "D", "en": "Shesha", "hi": "शेष"}]','B');
INSERT INTO knowledge_quiz VALUES(3537,'Who is considered the supreme devotee among Krishna’s friends?','कृष्ण के मित्रों में परम भक्त कौन माने जाते हैं?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Uddhava", "hi": "उद्धव"}, {"key": "C", "en": "Sudama", "hi": "सुदामा"}, {"key": "D", "en": "Akrura", "hi": "अक्रूर"}]','C');
INSERT INTO knowledge_quiz VALUES(3538,'Which teaching is emphasized as the highest path in the Bhagavata Purana?','भागवत पुराण में सर्वोच्च मार्ग किसे बताया गया है?','[{"key": "A", "en": "Karma Yoga", "hi": "कर्म योग"}, {"key": "B", "en": "Jnana Yoga", "hi": "ज्ञान योग"}, {"key": "C", "en": "Bhakti Yoga", "hi": "भक्ति योग"}, {"key": "D", "en": "Raja Yoga", "hi": "राज योग"}]','C');
INSERT INTO knowledge_quiz VALUES(3539,'Who cursed King Parikshit to die in seven days?','राजा परीक्षित को सात दिन में मृत्यु का शाप किसने दिया?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Shukadeva", "hi": "शुकदेव"}, {"key": "C", "en": "Shamika Rishi’s son", "hi": "शमीक ऋषि के पुत्र"}, {"key": "D", "en": "Vashistha", "hi": "वशिष्ठ"}]','C');
INSERT INTO knowledge_quiz VALUES(3540,'The ''Banke Bihari Temple'' in Vrindavan is unique because the deity''s darshan is frequently interrupted by what?','वृंदावन का ''बांके बिहारी मंदिर'' अद्वितीय है क्योंकि यहाँ देवता के दर्शन में बार-बार क्या किया जाता है?','[{"key": "A", "en": "Ringing of bells", "hi": "घंटी बजाना"}, {"key": "B", "en": "Drawing a curtain (Parda)", "hi": "पर्दा खींचना"}, {"key": "C", "en": "Blowing a conch", "hi": "शंख बजाना"}, {"key": "D", "en": "Chanting mantras", "hi": "मंत्रोच्चार"}]','B');
INSERT INTO knowledge_quiz VALUES(3541,'Who was the devoted son protected by Narasimha?','नरसिंह द्वारा संरक्षित भक्त पुत्र कौन थे?','[{"key": "A", "en": "Dhruva", "hi": "ध्रुव"}, {"key": "B", "en": "Prahlada", "hi": "प्रह्लाद"}, {"key": "C", "en": "Ambarisha", "hi": "अंबरीष"}, {"key": "D", "en": "Bali", "hi": "बलि"}]','B');
INSERT INTO knowledge_quiz VALUES(3542,'Which king was blessed by Vishnu as Vamana?','वामन अवतार द्वारा किस राजा को वरदान मिला?','[{"key": "A", "en": "Bali", "hi": "बलि"}, {"key": "B", "en": "Ravana", "hi": "रावण"}, {"key": "C", "en": "Kamsa", "hi": "कंस"}, {"key": "D", "en": "Jarasandha", "hi": "जरासंध"}]','A');
INSERT INTO knowledge_quiz VALUES(3543,'Who compiled the Bhagavata Purana?','भागवत पुराण की रचना किसने की?','[{"key": "A", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "B", "en": "Ved Vyasa", "hi": "वेदव्यास"}, {"key": "C", "en": "Tulsidas", "hi": "तुलसीदास"}, {"key": "D", "en": "Parashara", "hi": "पराशर"}]','B');
INSERT INTO knowledge_quiz VALUES(3544,'Which devotee attained salvation by constant remembrance of Krishna?','निरंतर कृष्ण स्मरण से किस भक्त को मोक्ष प्राप्त हुआ?','[{"key": "A", "en": "Ajamila", "hi": "अजामिल"}, {"key": "B", "en": "Dhruva", "hi": "ध्रुव"}, {"key": "C", "en": "Prahlada", "hi": "प्रह्लाद"}, {"key": "D", "en": "Sudama", "hi": "सुदामा"}]','A');
INSERT INTO knowledge_quiz VALUES(3545,'Who received divine knowledge directly from Krishna before His departure?','कृष्ण के प्रस्थान से पूर्व किसे दिव्य उपदेश मिला?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Balarama", "hi": "बलराम"}, {"key": "C", "en": "Uddhava", "hi": "उद्धव"}, {"key": "D", "en": "Sudama", "hi": "सुदामा"}]','C');
INSERT INTO knowledge_quiz VALUES(3546,'Which place is associated with Krishna’s childhood pastimes?','कृष्ण की बाल लीलाओं से कौन सा स्थान जुड़ा है?','[{"key": "A", "en": "Ayodhya", "hi": "अयोध्या"}, {"key": "B", "en": "Gokul", "hi": "गोकुल"}, {"key": "C", "en": "Hastinapura", "hi": "हस्तिनापुर"}, {"key": "D", "en": "Dwaraka", "hi": "द्वारका"}]','B');
INSERT INTO knowledge_quiz VALUES(3547,'Which city was established by Krishna as his kingdom?','कृष्ण ने अपनी राजधानी के रूप में कौन सा नगर बसाया?','[{"key": "A", "en": "Mathura", "hi": "मथुरा"}, {"key": "B", "en": "Vrindavan", "hi": "वृंदावन"}, {"key": "C", "en": "Dwaraka", "hi": "द्वारका"}, {"key": "D", "en": "Indraprastha", "hi": "इंद्रप्रस्थ"}]','C');
INSERT INTO knowledge_quiz VALUES(3548,'What is described as the essence of all scriptures in the Bhagavata Purana?','भागवत पुराण में सभी शास्त्रों का सार किसे बताया गया है?','[{"key": "A", "en": "Sacrifice", "hi": "यज्ञ"}, {"key": "B", "en": "Knowledge", "hi": "ज्ञान"}, {"key": "C", "en": "Devotion to Krishna", "hi": "कृष्ण भक्ति"}, {"key": "D", "en": "Renunciation", "hi": "त्याग"}]','C');
INSERT INTO knowledge_quiz VALUES(3549,'Which bird carrier is associated with Lord Vishnu in the Bhagavata Purana?','भागवत पुराण में विष्णु का वाहन कौन सा पक्षी है?','[{"key": "A", "en": "Hamsa", "hi": "हंस"}, {"key": "B", "en": "Garuda", "hi": "गरुड़"}, {"key": "C", "en": "Peacock", "hi": "मोर"}, {"key": "D", "en": "Eagle", "hi": "चील"}]','B');
INSERT INTO knowledge_quiz VALUES(3550,'What is the ultimate goal of life according to the Bhagavata Purana?','भागवत पुराण के अनुसार जीवन का परम लक्ष्य क्या है?','[{"key": "A", "en": "Heaven", "hi": "स्वर्ग"}, {"key": "B", "en": "Wealth", "hi": "धन"}, {"key": "C", "en": "Liberation through devotion", "hi": "भक्ति द्वारा मोक्ष"}, {"key": "D", "en": "Power", "hi": "शक्ति"}]','C');
INSERT INTO knowledge_quiz VALUES(3551,'Who was the foster father of Lord Krishna in Gokul?','गोकुल में भगवान कृष्ण के पालक पिता कौन थे?','[{"key": "A", "en": "Vasudeva", "hi": "वसुदेव"}, {"key": "B", "en": "Nanda", "hi": "नंद"}, {"key": "C", "en": "Ugrasena", "hi": "उग्रसेन"}, {"key": "D", "en": "Akrura", "hi": "अक्रूर"}]','B');
INSERT INTO knowledge_quiz VALUES(3552,'Which demoness tried to kill infant Krishna by poisoning?','शैशव अवस्था में किस राक्षसी ने विष देकर कृष्ण को मारने का प्रयास किया?','[{"key": "A", "en": "Trinavarta", "hi": "तृणावर्त"}, {"key": "B", "en": "Putana", "hi": "पूतना"}, {"key": "C", "en": "Kesi", "hi": "केशी"}, {"key": "D", "en": "Aghasura", "hi": "अघासुर"}]','B');
INSERT INTO knowledge_quiz VALUES(3553,'Which demon was killed by Krishna in the form of a whirlwind?','कृष्ण ने बवंडर रूपी किस असुर का वध किया?','[{"key": "A", "en": "Kesi", "hi": "केशी"}, {"key": "B", "en": "Aghasura", "hi": "अघासुर"}, {"key": "C", "en": "Trinavarta", "hi": "तृणावर्त"}, {"key": "D", "en": "Bakāsura", "hi": "बकासुर"}]','C');
INSERT INTO knowledge_quiz VALUES(3554,'Which pastime shows Krishna lifting a cart as a baby?','बालक कृष्ण द्वारा गाड़ी उलटने की लीला किस नाम से जानी जाती है?','[{"key": "A", "en": "Govardhan Leela", "hi": "गोवर्धन लीला"}, {"key": "B", "en": "Shakata Bhanjana", "hi": "शकट भंजन"}, {"key": "C", "en": "Rasa Leela", "hi": "रास लीला"}, {"key": "D", "en": "Damodara Leela", "hi": "दामोदर लीला"}]','B');
INSERT INTO knowledge_quiz VALUES(3555,'Who bound Krishna with a rope during Damodara Leela?','दामोदर लीला में किसने कृष्ण को रस्सी से बांधा?','[{"key": "A", "en": "Devaki", "hi": "देवकी"}, {"key": "B", "en": "Rohini", "hi": "रोहिणी"}, {"key": "C", "en": "Yashoda", "hi": "यशोदा"}, {"key": "D", "en": "Radha", "hi": "राधा"}]','C');
INSERT INTO knowledge_quiz VALUES(3556,'Which two beings were liberated by Krishna by pulling a mortar?','उखल से बंधे कृष्ण ने किन दो को मुक्त किया?','[{"key": "A", "en": "Jaya and Vijaya", "hi": "जय-विजय"}, {"key": "B", "en": "Nalakuvara and Manigriva", "hi": "नलकूबर और मणिग्रीव"}, {"key": "C", "en": "Bali and Sugriva", "hi": "बलि और सुग्रीव"}, {"key": "D", "en": "Shankha and Chuda", "hi": "शंख-चूड़"}]','B');
INSERT INTO knowledge_quiz VALUES(3557,'Which dance did Krishna perform with the Gopis?','कृष्ण ने गोपियों के साथ कौन सा नृत्य किया?','[{"key": "A", "en": "Tandava", "hi": "तांडव"}, {"key": "B", "en": "Lasya", "hi": "लास्य"}, {"key": "C", "en": "Rasa", "hi": "रास"}, {"key": "D", "en": "Nritya", "hi": "नृत्य"}]','C');
INSERT INTO knowledge_quiz VALUES(3558,'Which river is closely associated with Krishna’s childhood pastimes?','कृष्ण की बाल लीलाओं से कौन सी नदी जुड़ी है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Yamuna", "hi": "यमुना"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','B');
INSERT INTO knowledge_quiz VALUES(3559,'Who sent Akrura to bring Krishna to Mathura?','कृष्ण को मथुरा लाने के लिए अक्रूर को किसने भेजा?','[{"key": "A", "en": "Ugrasena", "hi": "उग्रसेन"}, {"key": "B", "en": "Jarasandha", "hi": "जरासंध"}, {"key": "C", "en": "Kamsa", "hi": "कंस"}, {"key": "D", "en": "Balarama", "hi": "बलराम"}]','C');
INSERT INTO knowledge_quiz VALUES(3560,'Which wrestler was defeated by Krishna in Mathura?','मथुरा में कृष्ण ने किस मल्ल का वध किया?','[{"key": "A", "en": "Chanura", "hi": "चाणूर"}, {"key": "B", "en": "Mushtika", "hi": "मुष्टिक"}, {"key": "C", "en": "Both A and B", "hi": "दोनों"}, {"key": "D", "en": "Kesi", "hi": "केशी"}]','C');
INSERT INTO knowledge_quiz VALUES(3561,'Who became the king of Mathura after Kamsa’s death?','कंस के वध के बाद मथुरा का राजा कौन बना?','[{"key": "A", "en": "Krishna", "hi": "कृष्ण"}, {"key": "B", "en": "Ugrasena", "hi": "उग्रसेन"}, {"key": "C", "en": "Balarama", "hi": "बलराम"}, {"key": "D", "en": "Akrura", "hi": "अक्रूर"}]','B');
INSERT INTO knowledge_quiz VALUES(3562,'How many sacred water wells (Theerthams) are located inside the Rameshwaram temple complex?','रामेश्वरम मंदिर परिसर के भीतर कितने पवित्र जल कुंड (तीर्थम) स्थित हैं?','[{"key": "A", "en": "12", "hi": "12"}, {"key": "B", "en": "22", "hi": "22"}, {"key": "C", "en": "108", "hi": "108"}, {"key": "D", "en": "51", "hi": "51"}]','B');
INSERT INTO knowledge_quiz VALUES(3563,'What gift did Krishna bring back for his guru Sandipani?','गुरु सांदीपनि के लिए कृष्ण क्या वापस लाए?','[{"key": "A", "en": "Gold", "hi": "सोना"}, {"key": "B", "en": "His lost son", "hi": "उनका पुत्र"}, {"key": "C", "en": "Sacred scriptures", "hi": "शास्त्र"}, {"key": "D", "en": "Divine weapons", "hi": "दिव्य अस्त्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3564,'Which king repeatedly attacked Mathura?','कौन सा राजा बार-बार मथुरा पर आक्रमण करता था?','[{"key": "A", "en": "Shishupala", "hi": "शिशुपाल"}, {"key": "B", "en": "Dantavakra", "hi": "दंतवक्र"}, {"key": "C", "en": "Jarasandha", "hi": "जरासंध"}, {"key": "D", "en": "Bali", "hi": "बलि"}]','C');
INSERT INTO knowledge_quiz VALUES(3565,'Why did Krishna establish the city of Dwaraka?','कृष्ण ने द्वारका नगर क्यों बसाया?','[{"key": "A", "en": "For trade", "hi": "व्यापार हेतु"}, {"key": "B", "en": "For pilgrimage", "hi": "तीर्थ के लिए"}, {"key": "C", "en": "To protect Yadavas", "hi": "यादवों की रक्षा के लिए"}, {"key": "D", "en": "For penance", "hi": "तपस्या के लिए"}]','C');
INSERT INTO knowledge_quiz VALUES(3566,'Who was Krishna’s principal queen in Dwaraka?','द्वारका में कृष्ण की प्रमुख रानी कौन थीं?','[{"key": "A", "en": "Radha", "hi": "राधा"}, {"key": "B", "en": "Satyabhama", "hi": "सत्यभामा"}, {"key": "C", "en": "Rukmini", "hi": "रुक्मिणी"}, {"key": "D", "en": "Jambavati", "hi": "जाम्बवती"}]','C');
INSERT INTO knowledge_quiz VALUES(3567,'Who kidnapped Rukmini before her marriage?','रुक्मिणी का विवाह से पूर्व हरण किसने किया?','[{"key": "A", "en": "Balarama", "hi": "बलराम"}, {"key": "B", "en": "Krishna", "hi": "कृष्ण"}, {"key": "C", "en": "Shishupala", "hi": "शिशुपाल"}, {"key": "D", "en": "Jarasandha", "hi": "जरासंध"}]','B');
INSERT INTO knowledge_quiz VALUES(3568,'Which devotee offered beaten rice to Krishna?','किस भक्त ने कृष्ण को चिवड़ा अर्पित किया?','[{"key": "A", "en": "Uddhava", "hi": "उद्धव"}, {"key": "B", "en": "Akrura", "hi": "अक्रूर"}, {"key": "C", "en": "Sudama", "hi": "सुदामा"}, {"key": "D", "en": "Vidura", "hi": "विदुर"}]','C');
INSERT INTO knowledge_quiz VALUES(3569,'Which scripture emphasizes Navadha Bhakti?','नवधा भक्ति का विशेष वर्णन किस ग्रंथ में है?','[{"key": "A", "en": "Ramayana", "hi": "रामायण"}, {"key": "B", "en": "Mahabharata", "hi": "महाभारत"}, {"key": "C", "en": "Bhagavata Purana", "hi": "भागवत पुराण"}, {"key": "D", "en": "Vedas", "hi": "वेद"}]','C');
INSERT INTO knowledge_quiz VALUES(3570,'Who taught Navadha Bhakti to Prahlada?','प्रह्लाद को नवधा भक्ति का उपदेश किसने दिया?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Shukadeva", "hi": "शुकदेव"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Brahma", "hi": "ब्रह्मा"}]','A');
INSERT INTO knowledge_quiz VALUES(3571,'Who was Dhruva’s stepmother?','ध्रुव की सौतेली माता कौन थीं?','[{"key": "A", "en": "Suniti", "hi": "सुनीति"}, {"key": "B", "en": "Suruchi", "hi": "सुरुचि"}, {"key": "C", "en": "Devahuti", "hi": "देवहूति"}, {"key": "D", "en": "Diti", "hi": "दिति"}]','B');
INSERT INTO knowledge_quiz VALUES(3572,'Which sage guided Dhruva in his penance?','ध्रुव को तपस्या का मार्ग किस ऋषि ने बताया?','[{"key": "A", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "B", "en": "Narada", "hi": "नारद"}, {"key": "C", "en": "Kapila", "hi": "कपिल"}, {"key": "D", "en": "Bhrigu", "hi": "भृगु"}]','B');
INSERT INTO knowledge_quiz VALUES(3573,'Which boon did Dhruva receive from Vishnu?','ध्रुव को विष्णु से कौन सा वरदान मिला?','[{"key": "A", "en": "Kingdom", "hi": "राज्य"}, {"key": "B", "en": "Immortality", "hi": "अमरत्व"}, {"key": "C", "en": "A fixed star position", "hi": "ध्रुव तारा पद"}, {"key": "D", "en": "Wealth", "hi": "धन"}]','C');
INSERT INTO knowledge_quiz VALUES(3574,'Who is considered the ideal king in the Bhagavata Purana?','भागवत पुराण में आदर्श राजा किसे माना गया है?','[{"key": "A", "en": "Rama", "hi": "राम"}, {"key": "B", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "C", "en": "Prithu", "hi": "पृथु"}, {"key": "D", "en": "Harishchandra", "hi": "हरिश्चंद्र"}]','C');
INSERT INTO knowledge_quiz VALUES(3575,'Who instructed King Parikshit in his final days?','अंतिम दिनों में राजा परीक्षित को किसने उपदेश दिया?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Ved Vyasa", "hi": "वेदव्यास"}, {"key": "C", "en": "Shukadeva", "hi": "शुकदेव"}, {"key": "D", "en": "Suta Lomaharshana", "hi": "सूत लोमहर्षण"}]','C');
INSERT INTO knowledge_quiz VALUES(3576,'Who is regarded as the supreme deity in the Shiva Purana?','शिव पुराण में किसे परम देवता माना गया है?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','C');
INSERT INTO knowledge_quiz VALUES(3577,'How many sections (Samhitas) are there in the Shiva Purana?','शिव पुराण में कुल कितनी संहिताएँ हैं?','[{"key": "A", "en": "4", "hi": "4"}, {"key": "B", "en": "5", "hi": "5"}, {"key": "C", "en": "6", "hi": "6"}, {"key": "D", "en": "7", "hi": "7"}]','D');
INSERT INTO knowledge_quiz VALUES(3578,'Who requested Sage Vyasa to narrate the Shiva Purana?','महर्षि व्यास से शिव पुराण सुनाने का अनुरोध किसने किया?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Sages", "hi": "ऋषिगण"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Parvati", "hi": "पार्वती"}]','B');
