INSERT INTO knowledge_quiz VALUES(3581,'Who is considered Shiva’s greatest devotee among sages?','ऋषियों में शिव का महान भक्त कौन माना जाता है?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Markandeya", "hi": "मार्कण्डेय"}, {"key": "C", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "D", "en": "Vashistha", "hi": "वशिष्ठ"}]','B');
INSERT INTO knowledge_quiz VALUES(3582,'Which demon received the boon of invincibility from Shiva?','शिव से अजेयता का वरदान किस असुर को मिला?','[{"key": "A", "en": "Bhasmasura", "hi": "भस्मासुर"}, {"key": "B", "en": "Tripurasura", "hi": "त्रिपुरासुर"}, {"key": "C", "en": "Andhaka", "hi": "अंधक"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
