INSERT INTO knowledge_quiz VALUES(3588,'Who cursed Brahma for lying during the Lingodbhava episode?','लिंगोद्भव प्रसंग में झूठ बोलने पर ब्रह्मा को किसने शाप दिया?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Sages", "hi": "ऋषि"}]','B');
INSERT INTO knowledge_quiz VALUES(3589,'What form of Shiva grants liberation to devotees?','शिव का कौन सा रूप भक्तों को मोक्ष देता है?','[{"key": "A", "en": "Sadashiva", "hi": "सदाशिव"}, {"key": "B", "en": "Mahakala", "hi": "महाकाल"}, {"key": "C", "en": "Nataraja", "hi": "नटराज"}, {"key": "D", "en": "Ishwara", "hi": "ईश्वर"}]','A');
INSERT INTO knowledge_quiz VALUES(3590,'Which vrata is described as most sacred in Shiva Purana?','शिव पुराण में कौन सा व्रत अत्यंत पवित्र बताया गया है?','[{"key": "A", "en": "Somavara Vrata", "hi": "सोमवार व्रत"}, {"key": "B", "en": "Shivaratri Vrata", "hi": "शिवरात्रि व्रत"}, {"key": "C", "en": "Pradosha Vrata", "hi": "प्रदोष व्रत"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
