INSERT INTO knowledge_quiz VALUES(3592,'Which river is said to originate from Shiva’s locks?','शिव की जटाओं से कौन सी नदी निकलती मानी जाती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Narmada", "hi": "नर्मदा"}]','C');
