INSERT INTO knowledge_quiz VALUES(3642,'Which demon was slain during Naraka Chaturdashi?','नरक चतुर्दशी के दिन किस असुर का वध हुआ?','[{"key": "A", "en": "Kamsa", "hi": "कंस"}, {"key": "B", "en": "Narakasura", "hi": "नरकासुर"}, {"key": "C", "en": "Banasura", "hi": "बाणासुर"}, {"key": "D", "en": "Shishupala", "hi": "शिशुपाल"}]','B');
