INSERT INTO knowledge_quiz VALUES(3645,'Who married Subhadra with Krishna’s support?','कृष्ण की सहायता से सुभद्रा का विवाह किससे हुआ?','[{"key": "A", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "B", "en": "Bhima", "hi": "भीम"}, {"key": "C", "en": "Abhimanyu", "hi": "अभिमन्यु"}, {"key": "D", "en": "Duryodhana", "hi": "दुर्योधन"}]','A');
INSERT INTO knowledge_quiz VALUES(3646,'Which son of Arjuna was Krishna’s nephew?','अर्जुन का कौन सा पुत्र कृष्ण का भांजा था?','[{"key": "A", "en": "Parikshit", "hi": "परीक्षित"}, {"key": "B", "en": "Ghatotkacha", "hi": "घटोत्कच"}, {"key": "C", "en": "Abhimanyu", "hi": "अभिमन्यु"}, {"key": "D", "en": "Shrutakarma", "hi": "श्रुतकर्मा"}]','C');
INSERT INTO knowledge_quiz VALUES(3647,'Where did Krishna spend his childhood?','कृष्ण ने अपना बाल्यकाल कहाँ बिताया?','[{"key": "A", "en": "Mathura", "hi": "मथुरा"}, {"key": "B", "en": "Dwarka", "hi": "द्वारका"}, {"key": "C", "en": "Gokul and Vrindavan", "hi": "गोकुल और वृंदावन"}, {"key": "D", "en": "Hastinapura", "hi": "हस्तिनापुर"}]','C');
INSERT INTO knowledge_quiz VALUES(3648,'Which serpent did Krishna subdue in the Yamuna?','कृष्ण ने यमुना में किस नाग का दमन किया?','[{"key": "A", "en": "Takshaka", "hi": "तक्षक"}, {"key": "B", "en": "Kaliya", "hi": "कालिय"}, {"key": "C", "en": "Vasuki", "hi": "वासुकि"}, {"key": "D", "en": "Ananta", "hi": "अनंत"}]','B');
INSERT INTO knowledge_quiz VALUES(3649,'Which quality of Krishna is most emphasized in devotion?','भक्ति में कृष्ण के किस गुण पर विशेष बल दिया जाता है?','[{"key": "A", "en": "Power", "hi": "शक्ति"}, {"key": "B", "en": "Beauty", "hi": "सौंदर्य"}, {"key": "C", "en": "Compassion", "hi": "करुणा"}, {"key": "D", "en": "Supreme love", "hi": "परम प्रेम"}]','D');
INSERT INTO knowledge_quiz VALUES(3650,'What is the ultimate message of Lord Krishna’s life?','भगवान कृष्ण के जीवन का अंतिम संदेश क्या है?','[{"key": "A", "en": "Renunciation", "hi": "त्याग"}, {"key": "B", "en": "Devotion with duty", "hi": "कर्तव्य सहित भक्ति"}, {"key": "C", "en": "Worldly success", "hi": "सांसारिक सफलता"}, {"key": "D", "en": "Power and victory", "hi": "शक्ति और विजय"}]','B');
INSERT INTO knowledge_quiz VALUES(3651,'Which city is known as the land of Lord Krishna’s birth?','भगवान कृष्ण की जन्मभूमि के रूप में कौन सा नगर प्रसिद्ध है?','[{"key": "A", "en": "Vrindavan", "hi": "वृंदावन"}, {"key": "B", "en": "Mathura", "hi": "मथुरा"}, {"key": "C", "en": "Dwarka", "hi": "द्वारका"}, {"key": "D", "en": "Ujjain", "hi": "उज्जैन"}]','B');
INSERT INTO knowledge_quiz VALUES(3652,'Which famous Krishna temple is located in Dwarka, Gujarat?','गुजरात के द्वारका में कौन सा प्रसिद्ध कृष्ण मंदिर स्थित है?','[{"key": "A", "en": "Banke Bihari Temple", "hi": "बांके बिहारी मंदिर"}, {"key": "B", "en": "Dwarkadhish Temple", "hi": "द्वारकाधीश मंदिर"}, {"key": "C", "en": "ISKCON Temple", "hi": "इस्कॉन मंदिर"}, {"key": "D", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}]','B');
