INSERT INTO knowledge_quiz VALUES(3686,'Which Ganesha temple in Pune is famous during Ganesh Chaturthi?','गणेश चतुर्थी के दौरान पुणे का कौन सा गणेश मंदिर प्रसिद्ध है?','[{"key": "A", "en": "Kasba Ganpati", "hi": "कसबा गणपति"}, {"key": "B", "en": "Dagdu Sheth Halwai Ganpati", "hi": "दगडूशेठ हलवाई गणपति"}, {"key": "C", "en": "Parvati Ganpati", "hi": "पर्वती गणपति"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
