INSERT INTO knowledge_quiz VALUES(3688,'Which Ganesha temple is located near Rameshwaram?','रामेश्वरम के निकट कौन सा गणेश मंदिर स्थित है?','[{"key": "A", "en": "Karpaga Vinayagar Temple", "hi": "कर्पग विनायगर मंदिर"}, {"key": "B", "en": "Ucchi Pillayar Temple", "hi": "उच्ची पिल्लैयार मंदिर"}, {"key": "C", "en": "Varasiddhi Vinayagar Temple", "hi": "वरसिद्धि विनायगर मंदिर"}, {"key": "D", "en": "Rockfort Temple", "hi": "रॉकफोर्ट मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(3689,'Which Ganesha temple is also known as ‘Vighneshwar’?','कौन सा गणेश मंदिर ‘विघ्नेश्वर’ के नाम से भी जाना जाता है?','[{"key": "A", "en": "Vighnahar Temple", "hi": "विघ्नहर मंदिर"}, {"key": "B", "en": "Varadvinayak Temple", "hi": "वरदविनायक मंदिर"}, {"key": "C", "en": "Siddhivinayak Temple", "hi": "सिद्धिविनायक मंदिर"}, {"key": "D", "en": "Moreshwar Temple", "hi": "मोरेश्वर मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(3690,'Which Ashtavinayaka temple is located at Mahad?','महाड में कौन सा अष्टविनायक मंदिर स्थित है?','[{"key": "A", "en": "Varadvinayak", "hi": "वरदविनायक"}, {"key": "B", "en": "Chintamani", "hi": "चिंतामणि"}, {"key": "C", "en": "Ballaleshwar", "hi": "बल्लालेश्वर"}, {"key": "D", "en": "Siddhatek", "hi": "सिद्धटेक"}]','A');
INSERT INTO knowledge_quiz VALUES(3691,'Which Ashtavinayaka temple is associated with removing worries?','चिंताओं को दूर करने वाला कौन सा अष्टविनायक मंदिर माना जाता है?','[{"key": "A", "en": "Chintamani", "hi": "चिंतामणि"}, {"key": "B", "en": "Vighnahar", "hi": "विघ्नहर"}, {"key": "C", "en": "Moreshwar", "hi": "मोरेश्वर"}, {"key": "D", "en": "Siddhatek", "hi": "सिद्धटेक"}]','A');
INSERT INTO knowledge_quiz VALUES(3692,'Which Ganesha temple is famous for a single large rock idol in Karnataka?','कर्नाटक में एक विशाल शिला से बनी गणेश प्रतिमा के लिए कौन सा मंदिर प्रसिद्ध है?','[{"key": "A", "en": "Dodda Ganapathi Temple", "hi": "दोद्दा गणपति मंदिर"}, {"key": "B", "en": "Hampi Ganesh Temple", "hi": "हंपी गणेश मंदिर"}, {"key": "C", "en": "Pillayar Temple", "hi": "पिल्लैयार मंदिर"}, {"key": "D", "en": "Both A and B", "hi": "A और B दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(3693,'Which Ganesha temple is worshipped before starting any new work?','किस गणेश मंदिर की पूजा नए कार्य के आरंभ से पहले की जाती है?','[{"key": "A", "en": "Moreshwar Temple", "hi": "मोरेश्वर मंदिर"}, {"key": "B", "en": "Siddhivinayak Temple", "hi": "सिद्धिविनायक मंदिर"}, {"key": "C", "en": "Mahaganapati Temple", "hi": "महागणपति मंदिर"}, {"key": "D", "en": "All Ganesha temples", "hi": "सभी गणेश मंदिर"}]','D');
INSERT INTO knowledge_quiz VALUES(3694,'Which Ganesha temple is located in Hampi, Karnataka?','कर्नाटक के हंपी में कौन सा गणेश मंदिर स्थित है?','[{"key": "A", "en": "Virupaksha Ganapathi", "hi": "विरुपाक्ष गणपति"}, {"key": "B", "en": "Hampi Ganesh Temple", "hi": "हंपी गणेश मंदिर"}, {"key": "C", "en": "Dodda Ganapathi", "hi": "दोद्दा गणपति"}, {"key": "D", "en": "Chintamani Ganpati", "hi": "चिंतामणि गणपति"}]','B');
INSERT INTO knowledge_quiz VALUES(3695,'Which Ganesha temple is also known as ‘Mahaganapati’?','‘महागणपति’ नाम से कौन सा गणेश मंदिर जाना जाता है?','[{"key": "A", "en": "Ranjangaon Temple", "hi": "रणजणगांव मंदिर"}, {"key": "B", "en": "Moreshwar Temple", "hi": "मोरेश्वर मंदिर"}, {"key": "C", "en": "Siddhatek Temple", "hi": "सिद्धटेक मंदिर"}, {"key": "D", "en": "Varadvinayak Temple", "hi": "वरदविनायक मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(3696,'Which festival is most widely celebrated in Ganesha temples?','गणेश मंदिरों में सबसे व्यापक रूप से कौन सा त्योहार मनाया जाता है?','[{"key": "A", "en": "Diwali", "hi": "दीवाली"}, {"key": "B", "en": "Ganesh Chaturthi", "hi": "गणेश चतुर्थी"}, {"key": "C", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "D", "en": "Holi", "hi": "होली"}]','B');
INSERT INTO knowledge_quiz VALUES(3697,'Which Ganesha temple in Maharashtra is known as ‘Varad Vinayak’?','महाराष्ट्र में ‘वरद विनायक’ नाम से कौन सा गणेश मंदिर प्रसिद्ध है?','[{"key": "A", "en": "Mahad Temple", "hi": "महाड मंदिर"}, {"key": "B", "en": "Siddhatek Temple", "hi": "सिद्धटेक मंदिर"}, {"key": "C", "en": "Ranjangaon Temple", "hi": "रणजणगांव मंदिर"}, {"key": "D", "en": "Ozar Temple", "hi": "ओझर मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(3698,'Which Ganesha temple is known for granting success (Siddhi)?','सिद्धि प्रदान करने के लिए कौन सा गणेश मंदिर प्रसिद्ध है?','[{"key": "A", "en": "Siddhivinayak Temple", "hi": "सिद्धिविनायक मंदिर"}, {"key": "B", "en": "Vighnahar Temple", "hi": "विघ्नहर मंदिर"}, {"key": "C", "en": "Moreshwar Temple", "hi": "मोरेश्वर मंदिर"}, {"key": "D", "en": "Girijatmaj Temple", "hi": "गिरिजात्मज मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(3699,'Which Ashtavinayaka temple is located at Ozar?','ओझर में कौन सा अष्टविनायक मंदिर स्थित है?','[{"key": "A", "en": "Vighnahar", "hi": "विघ्नहर"}, {"key": "B", "en": "Mahaganapati", "hi": "महागणपति"}, {"key": "C", "en": "Chintamani", "hi": "चिंतामणि"}, {"key": "D", "en": "Varadvinayak", "hi": "वरदविनायक"}]','B');
INSERT INTO knowledge_quiz VALUES(3700,'Which Ashtavinayaka temple is associated with victory over obstacles?','विघ्नों पर विजय से कौन सा अष्टविनायक मंदिर जुड़ा है?','[{"key": "A", "en": "Vighnahar Temple", "hi": "विघ्नहर मंदिर"}, {"key": "B", "en": "Chintamani Temple", "hi": "चिंतामणि मंदिर"}, {"key": "C", "en": "Moreshwar Temple", "hi": "मोरेश्वर मंदिर"}, {"key": "D", "en": "Girijatmaj Temple", "hi": "गिरिजात्मज मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(3701,'Which temple in Gujarat is dedicated to Lord Hanuman and is famous for ''Sarangpur Hanuman''?','गुजरात का कौन सा मंदिर भगवान हनुमान को समर्पित है और ''सारंगपुर हनुमान'' के नाम से प्रसिद्ध है?','[{"key": "A", "en": "Bhadkeshwar Mahadev", "hi": "भड़केश्वर महादेव"}, {"key": "B", "en": "Salangpur Kashtbhanjan", "hi": "सांरगपुर कष्टभंजन"}, {"key": "C", "en": "Camp Hanuman", "hi": "कैंप हनुमान"}, {"key": "D", "en": "Hanuman Dhara", "hi": "हनुमान धारा"}]','B');
INSERT INTO knowledge_quiz VALUES(3702,'Which of these temples is part of the ''Cultural Triangle'' of Sri Lanka and was built inside a cave?','इनमें से कौन सा मंदिर श्रीलंका के ''सांस्कृतिक त्रिकोण'' का हिस्सा है और एक गुफा के अंदर बनाया गया था?','[{"key": "A", "en": "Dambulla Cave Temple", "hi": "दाम्बुला गुफा मंदिर"}, {"key": "B", "en": "Kelaniya Raja Maha Vihara", "hi": "केलनिया राजा महा विहार"}, {"key": "C", "en": "Buduruwagala", "hi": "बुदुरुवागला"}, {"key": "D", "en": "Pidurangala", "hi": "पिदुरुंगला"}]','A');
INSERT INTO knowledge_quiz VALUES(3703,'Which pilgrimage site is famous for the Kumbh Mela?','कुंभ मेला किस तीर्थ स्थल पर प्रसिद्ध है?','[{"key": "A", "en": "Haridwar", "hi": "हरिद्वार"}, {"key": "B", "en": "Prayagraj", "hi": "प्रयागराज"}, {"key": "C", "en": "Ujjain", "hi": "उज्जैन"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3704,'Which Sikh shrine is known as the Golden Temple?','स्वर्ण मंदिर किस सिख तीर्थ को कहा जाता है?','[{"key": "A", "en": "Anandpur Sahib", "hi": "आनंदपुर साहिब"}, {"key": "B", "en": "Hemkund Sahib", "hi": "हेमकुंड साहिब"}, {"key": "C", "en": "Harmandir Sahib", "hi": "हरमंदिर साहिब"}, {"key": "D", "en": "Patna Sahib", "hi": "पटना साहिब"}]','C');
INSERT INTO knowledge_quiz VALUES(3705,'Which sacred mountain range is the Sabarimala temple located in?','सबरीमाला मंदिर किस पवित्र पर्वत श्रृंखला में स्थित है?','[{"key": "A", "en": "Western Ghats", "hi": "पश्चिमी घाट"}, {"key": "B", "en": "Eastern Ghats", "hi": "पूर्वी घाट"}, {"key": "C", "en": "Nilgiri Hills", "hi": "नीलगिरी पहाड़ियाँ"}, {"key": "D", "en": "Cardamom Hills", "hi": "इलायची पहाड़ियाँ"}]','A');
INSERT INTO knowledge_quiz VALUES(3706,'Which Char Dham is located in Uttarakhand?','चार धाम में से कौन सा उत्तराखंड में स्थित है?','[{"key": "A", "en": "Dwarka", "hi": "द्वारका"}, {"key": "B", "en": "Puri", "hi": "पुरी"}, {"key": "C", "en": "Badrinath", "hi": "बद्रीनाथ"}, {"key": "D", "en": "Rameshwaram", "hi": "रामेश्वरम"}]','C');
INSERT INTO knowledge_quiz VALUES(3707,'In which direction is the trunk of the idol at the Siddhivinayak Temple turned?','सिद्धिविनायक मंदिर में मूर्ति की सूंड किस दिशा में मुड़ी हुई है?','[{"key": "A", "en": "Left", "hi": "बाईं ओर"}, {"key": "B", "en": "Right", "hi": "दाईं ओर"}, {"key": "C", "en": "Straight", "hi": "सीधी"}, {"key": "D", "en": "Upwards", "hi": "ऊपर की ओर"}]','B');
INSERT INTO knowledge_quiz VALUES(3708,'Which Buddhist site is associated with Buddha’s enlightenment?','बुद्ध के ज्ञान प्राप्ति से कौन सा बौद्ध स्थल जुड़ा है?','[{"key": "A", "en": "Sarnath", "hi": "सारनाथ"}, {"key": "B", "en": "Kushinagar", "hi": "कुशीनगर"}, {"key": "C", "en": "Bodh Gaya", "hi": "बोधगया"}, {"key": "D", "en": "Rajgir", "hi": "राजगीर"}]','C');
INSERT INTO knowledge_quiz VALUES(3709,'Which Jain site is famous for the statue of Gomateshwara?','गोमतेश्वर प्रतिमा के लिए कौन सा जैन तीर्थ प्रसिद्ध है?','[{"key": "A", "en": "Palitana", "hi": "पालीताना"}, {"key": "B", "en": "Shravanabelagola", "hi": "श्रवणबेलगोला"}, {"key": "C", "en": "Mount Abu", "hi": "माउंट आबू"}, {"key": "D", "en": "Girnar", "hi": "गिरनार"}]','B');
INSERT INTO knowledge_quiz VALUES(3710,'The temple of Samaleswari, the presiding deity of Western Odisha, is situated on the banks of which river?','पश्चिमी ओडिशा की अधिष्ठात्री देवी समलेश्वरी का मंदिर किस नदी के तट पर स्थित है?','[{"key": "A", "en": "Ganga", "hi": "गंगा"}, {"key": "B", "en": "Mahanadi", "hi": "महानदी"}, {"key": "C", "en": "Brahmani", "hi": "ब्राह्मणी"}, {"key": "D", "en": "Baitarani", "hi": "वैतरणी"}]','B');
INSERT INTO knowledge_quiz VALUES(3711,'Which Shakti Peetha is located in Assam?','असम में स्थित शक्ति पीठ कौन सा है?','[{"key": "A", "en": "Kalighat", "hi": "कालीघाट"}, {"key": "B", "en": "Kamakhya", "hi": "कामाख्या"}, {"key": "C", "en": "Vaishno Devi", "hi": "वैष्णो देवी"}, {"key": "D", "en": "Ambaji", "hi": "अंबाजी"}]','B');
INSERT INTO knowledge_quiz VALUES(3712,'Which cave temples are UNESCO World Heritage Sites?','यूनेस्को विश्व धरोहर सूची में शामिल गुफा मंदिर कौन से हैं?','[{"key": "A", "en": "Ajanta", "hi": "अजंता"}, {"key": "B", "en": "Ellora", "hi": "एलोरा"}, {"key": "C", "en": "Elephanta", "hi": "एलीफेंटा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3713,'The deity of Lord Ayyappa in Sabarimala is believed to be in which state of life?','सबरीमाला में भगवान अयप्पा की मूर्ति जीवन की किस अवस्था में मानी जाती है?','[{"key": "A", "en": "Grihastha (Householder)", "hi": "गृहस्थ"}, {"key": "B", "en": "Naishtika Brahmachari (Celibate)", "hi": "नैष्ठिक ब्रह्मचारी"}, {"key": "C", "en": "Vanaprastha", "hi": "वानप्रस्थ"}, {"key": "D", "en": "Sanyasi", "hi": "संन्यासी"}]','B');
INSERT INTO knowledge_quiz VALUES(3714,'Which temple is known for the world’s richest treasury?','विश्व के सबसे समृद्ध मंदिर के रूप में कौन सा जाना जाता है?','[{"key": "A", "en": "Tirupati", "hi": "तिरुपति"}, {"key": "B", "en": "Padmanabhaswamy", "hi": "पद्मनाभस्वामी"}, {"key": "C", "en": "Somnath", "hi": "सोमनाथ"}, {"key": "D", "en": "Meenakshi", "hi": "मीनाक्षी"}]','B');
INSERT INTO knowledge_quiz VALUES(3715,'Which holy site is associated with the confluence of three rivers?','तीन नदियों के संगम से कौन सा पवित्र स्थल जुड़ा है?','[{"key": "A", "en": "Haridwar", "hi": "हरिद्वार"}, {"key": "B", "en": "Prayagraj", "hi": "प्रयागराज"}, {"key": "C", "en": "Varanasi", "hi": "वाराणसी"}, {"key": "D", "en": "Ujjain", "hi": "उज्जैन"}]','B');
INSERT INTO knowledge_quiz VALUES(3716,'Which temple in Karnataka is famous for its ''inverted shadow'' of the main tower (Gopuram) falling on the wall of the temple?','कर्नाटक का कौन सा मंदिर अपने मुख्य शिखर (गोपुरम) की ''उल्टी छाया'' के लिए प्रसिद्ध है जो मंदिर की दीवार पर गिरती है?','[{"key": "A", "en": "Vitthala Temple", "hi": "विट्ठल मंदिर"}, {"key": "B", "en": "Virupaksha Temple", "hi": "विरुपाक्ष मंदिर"}, {"key": "C", "en": "Hoysaleswara Temple", "hi": "होयसलेश्वर मंदिर"}, {"key": "D", "en": "Someshwara Temple", "hi": "सोमेश्वर मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(3717,'Which Jain pilgrimage is known as Shatrunjaya?','शत्रुंजय के नाम से कौन सा जैन तीर्थ प्रसिद्ध है?','[{"key": "A", "en": "Girnar", "hi": "गिरनार"}, {"key": "B", "en": "Palitana", "hi": "पालीताना"}, {"key": "C", "en": "Mount Abu", "hi": "माउंट आबू"}, {"key": "D", "en": "Taranga", "hi": "तारंगा"}]','B');
INSERT INTO knowledge_quiz VALUES(3718,'Which temple is famous for the Sun God?','सूर्य देव को समर्पित प्रसिद्ध मंदिर कौन सा है?','[{"key": "A", "en": "Martand Sun Temple", "hi": "मार्तंड सूर्य मंदिर"}, {"key": "B", "en": "Konark Sun Temple", "hi": "कोणार्क सूर्य मंदिर"}, {"key": "C", "en": "Modhera Sun Temple", "hi": "मोढेरा सूर्य मंदिर"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3719,'Which sacred hill is associated with Lord Murugan?','भगवान मुरुगन से कौन सी पवित्र पहाड़ी जुड़ी है?','[{"key": "A", "en": "Tirumala", "hi": "तिरुमला"}, {"key": "B", "en": "Palani", "hi": "पलनी"}, {"key": "C", "en": "Arunachala", "hi": "अरुणाचल"}, {"key": "D", "en": "Girnar", "hi": "गिरनार"}]','B');
