INSERT INTO knowledge_quiz VALUES(3799,'Which sacred site is associated with the Ashoka Pillars?','अशोक स्तंभों से कौन सा पवित्र स्थल जुड़ा है?','[{"key": "A", "en": "Sarnath", "hi": "सारनाथ"}, {"key": "B", "en": "Bodh Gaya", "hi": "बोधगया"}, {"key": "C", "en": "Vaishali", "hi": "वैशाली"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3800,'Which sacred site is associated with Lord Rama’s exile period?','भगवान राम के वनवास काल से कौन सा स्थल जुड़ा है?','[{"key": "A", "en": "Chitrakoot", "hi": "चित्रकूट"}, {"key": "B", "en": "Ayodhya", "hi": "अयोध्या"}, {"key": "C", "en": "Nasik", "hi": "नासिक"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3801,'Which Hindu festival is known as the festival of lights?','प्रकाशों का पर्व किस हिंदू त्योहार को कहा जाता है?','[{"key": "A", "en": "Holi", "hi": "होली"}, {"key": "B", "en": "Diwali", "hi": "दीवाली"}, {"key": "C", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "D", "en": "Dussehra", "hi": "दशहरा"}]','B');
INSERT INTO knowledge_quiz VALUES(3802,'Which festival celebrates the victory of Lord Rama over Ravana?','भगवान राम की रावण पर विजय का उत्सव कौन सा है?','[{"key": "A", "en": "Diwali", "hi": "दीवाली"}, {"key": "B", "en": "Dussehra", "hi": "दशहरा"}, {"key": "C", "en": "Holi", "hi": "होली"}, {"key": "D", "en": "Ram Navami", "hi": "राम नवमी"}]','B');
INSERT INTO knowledge_quiz VALUES(3803,'The ''Temple of the Vedic Planetarium'', which aims to be one of the largest religious monuments in the world, is located in which town?','''वैदिक तारामंडल का मंदिर'', जिसका लक्ष्य दुनिया के सबसे बड़े धार्मिक स्मारकों में से एक होना है, किस शहर में स्थित है?','[{"key": "A", "en": "Nabadwip", "hi": "नवद्वीप"}, {"key": "B", "en": "Mayapur", "hi": "मायापुर"}, {"key": "C", "en": "Tarapith", "hi": "तारापीठ"}, {"key": "D", "en": "Shantipur", "hi": "शांतिपुर"}]','B');
