INSERT INTO knowledge_quiz VALUES(3805,'Which festival celebrates the bond between brother and sister?','भाई-बहन के प्रेम का पर्व कौन सा है?','[{"key": "A", "en": "Bhai Dooj", "hi": "भाई दूज"}, {"key": "B", "en": "Raksha Bandhan", "hi": "रक्षा बंधन"}, {"key": "C", "en": "Teej", "hi": "तीज"}, {"key": "D", "en": "Karva Chauth", "hi": "करवा चौथ"}]','B');
INSERT INTO knowledge_quiz VALUES(3806,'Which festival marks the Hindu New Year in many parts of India?','भारत के कई भागों में हिंदू नववर्ष कौन सा त्योहार माना जाता है?','[{"key": "A", "en": "Gudi Padwa", "hi": "गुड़ी पड़वा"}, {"key": "B", "en": "Diwali", "hi": "दीवाली"}, {"key": "C", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}, {"key": "D", "en": "Holi", "hi": "होली"}]','A');
INSERT INTO knowledge_quiz VALUES(3807,'Which festival is dedicated to Goddess Durga and celebrated for nine nights?','नौ रातों तक देवी दुर्गा को समर्पित कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "B", "en": "Durga Puja", "hi": "दुर्गा पूजा"}, {"key": "C", "en": "Vasant Panchami", "hi": "वसंत पंचमी"}, {"key": "D", "en": "Teej", "hi": "तीज"}]','A');
INSERT INTO knowledge_quiz VALUES(3808,'Which festival celebrates the worship of Goddess Saraswati?','देवी सरस्वती की पूजा का त्योहार कौन सा है?','[{"key": "A", "en": "Vasant Panchami", "hi": "वसंत पंचमी"}, {"key": "B", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "C", "en": "Durga Puja", "hi": "दुर्गा पूजा"}, {"key": "D", "en": "Diwali", "hi": "दीवाली"}]','A');
INSERT INTO knowledge_quiz VALUES(3809,'Which festival is associated with the Sun’s transition into Capricorn?','सूर्य के मकर राशि में प्रवेश से जुड़ा त्योहार कौन सा है?','[{"key": "A", "en": "Pongal", "hi": "पोंगल"}, {"key": "B", "en": "Makar Sankranti", "hi": "मकर संक्रांति"}, {"key": "C", "en": "Onam", "hi": "ओणम"}, {"key": "D", "en": "Baisakhi", "hi": "बैसाखी"}]','B');
INSERT INTO knowledge_quiz VALUES(3810,'Which harvest festival is celebrated mainly in Punjab?','मुख्य रूप से पंजाब में मनाया जाने वाला फसल उत्सव कौन सा है?','[{"key": "A", "en": "Onam", "hi": "ओणम"}, {"key": "B", "en": "Pongal", "hi": "पोंगल"}, {"key": "C", "en": "Baisakhi", "hi": "बैसाखी"}, {"key": "D", "en": "Lohri", "hi": "लोहड़ी"}]','C');
INSERT INTO knowledge_quiz VALUES(3811,'Which festival is celebrated to welcome King Mahabali?','राजा महाबली के स्वागत में कौन सा त्योहार मनाया जाता है?','[{"key": "A", "en": "Pongal", "hi": "पोंगल"}, {"key": "B", "en": "Onam", "hi": "ओणम"}, {"key": "C", "en": "Vishu", "hi": "विशु"}, {"key": "D", "en": "Bihu", "hi": "बिहू"}]','B');
INSERT INTO knowledge_quiz VALUES(3812,'Temple in Birbhum is famous for being a ''Siddha Peetha'' dedicated to which form of the Goddess?','बीरभूम का मंदिर देवी के किस रूप को समर्पित एक ''सिद्ध पीठ'' होने के लिए प्रसिद्ध है?','[{"key": "A", "en": "Durga", "hi": "दुर्गा"}, {"key": "B", "en": "Tara (one of the Das Mahavidyas)", "hi": "तारा (दस महाविद्याओं में से एक)"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Lakshmi", "hi": "लक्ष्मी"}]','B');
INSERT INTO knowledge_quiz VALUES(3813,'Which festival honors Lord Shiva with fasting and night-long vigil?','उपवास और रात्रि जागरण के साथ भगवान शिव को समर्पित पर्व कौन सा है?','[{"key": "A", "en": "Maha Shivaratri", "hi": "महाशिवरात्रि"}, {"key": "B", "en": "Pradosh Vrat", "hi": "प्रदोष व्रत"}, {"key": "C", "en": "Somvati Amavasya", "hi": "सोमवती अमावस्या"}, {"key": "D", "en": "Nag Panchami", "hi": "नाग पंचमी"}]','A');
