INSERT INTO knowledge_quiz VALUES(3815,'Which festival is observed by married women for the long life of their husbands?','पति की दीर्घायु के लिए विवाहित महिलाओं द्वारा रखा जाने वाला व्रत कौन सा है?','[{"key": "A", "en": "Teej", "hi": "तीज"}, {"key": "B", "en": "Karva Chauth", "hi": "करवा चौथ"}, {"key": "C", "en": "Vat Savitri", "hi": "वट सावित्री"}, {"key": "D", "en": "Hartalika Teej", "hi": "हरतालिका तीज"}]','B');
INSERT INTO knowledge_quiz VALUES(3816,'What is the traditional offering for Lord Bhairava in many temples?','कई मंदिरों में भगवान भैरव को दिया जाने वाला पारंपरिक भोग क्या है?','[{"key": "A", "en": "Sweet Kheer", "hi": "मीठी खीर"}, {"key": "B", "en": "Urad Dal Vada (Imarti/Vada)", "hi": "उड़द दाल वड़ा या इमरती"}, {"key": "C", "en": "Fruit juice", "hi": "फलों का रस"}, {"key": "D", "en": "Saffron milk", "hi": "केसर दूध"}]','B');
INSERT INTO knowledge_quiz VALUES(3817,'Which festival is celebrated to honor Anjani putra?','अंजनी पुत्र को समर्पित पर्व कौन सा है?','[{"key": "A", "en": "Ram Navami", "hi": "राम नवमी"}, {"key": "B", "en": "Hanuman Jayanti", "hi": "हनुमान जयंती"}, {"key": "C", "en": "Maha Shivaratri", "hi": "महाशिवरात्रि"}, {"key": "D", "en": "Basant Panchami", "hi": "बसंत पंचमी"}]','B');
INSERT INTO knowledge_quiz VALUES(3818,'Which festival is celebrated as the beginning of the harvest season in Tamil Nadu?','तमिलनाडु में फसल कटाई की शुरुआत का त्योहार कौन सा है?','[{"key": "A", "en": "Onam", "hi": "ओणम"}, {"key": "B", "en": "Pongal", "hi": "पोंगल"}, {"key": "C", "en": "Vishu", "hi": "विशु"}, {"key": "D", "en": "Bihu", "hi": "बिहू"}]','B');
INSERT INTO knowledge_quiz VALUES(3819,'Which festival is associated with lighting lamps on the banks of rivers?','नदियों के तट पर दीप जलाने से जुड़ा त्योहार कौन सा है?','[{"key": "A", "en": "Kartik Purnima", "hi": "कार्तिक पूर्णिमा"}, {"key": "B", "en": "Chhath Puja", "hi": "छठ पूजा"}, {"key": "C", "en": "Diwali", "hi": "दीवाली"}, {"key": "D", "en": "Ganga Dussehra", "hi": "गंगा दशहरा"}]','A');
