INSERT INTO knowledge_quiz VALUES(3821,'Which festival is celebrated in Assam as a harvest festival?','असम में फसल उत्सव के रूप में कौन सा त्योहार मनाया जाता है?','[{"key": "A", "en": "Bihu", "hi": "बिहू"}, {"key": "B", "en": "Onam", "hi": "ओणम"}, {"key": "C", "en": "Pongal", "hi": "पोंगल"}, {"key": "D", "en": "Baisakhi", "hi": "बैसाखी"}]','A');
INSERT INTO knowledge_quiz VALUES(3822,'Which festival commemorates the lifting of Govardhan Hill by Lord Krishna?','भगवान कृष्ण द्वारा गोवर्धन पर्वत उठाने की स्मृति में कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Annakut", "hi": "अन्नकूट"}, {"key": "B", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "C", "en": "Janmashtami", "hi": "जन्माष्टमी"}, {"key": "D", "en": "Holi", "hi": "होली"}]','B');
