INSERT INTO knowledge_quiz VALUES(3825,'Which festival is observed on the full moon of Kartik month?','कार्तिक मास की पूर्णिमा को कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Guru Purnima", "hi": "गुरु पूर्णिमा"}, {"key": "B", "en": "Kartik Purnima", "hi": "कार्तिक पूर्णिमा"}, {"key": "C", "en": "Sharad Purnima", "hi": "शरद पूर्णिमा"}, {"key": "D", "en": "Buddha Purnima", "hi": "बुद्ध पूर्णिमा"}]','B');
