INSERT INTO knowledge_quiz VALUES(3834,'Which festival celebrates the marriage of Lord Shiva and Goddess Parvati?','भगवान शिव और माता पार्वती के विवाह का पर्व कौन सा है?','[{"key": "A", "en": "Maha Shivaratri", "hi": "महाशिवरात्रि"}, {"key": "B", "en": "Teej", "hi": "तीज"}, {"key": "C", "en": "Gangaur", "hi": "गंगौर"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3835,'Which festival is celebrated mainly in Rajasthan to honor Goddess Gauri?','राजस्थान में देवी गौरी के सम्मान में कौन सा त्योहार मनाया जाता है?','[{"key": "A", "en": "Teej", "hi": "तीज"}, {"key": "B", "en": "Gangaur", "hi": "गंगौर"}, {"key": "C", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "D", "en": "Karva Chauth", "hi": "करवा चौथ"}]','B');
INSERT INTO knowledge_quiz VALUES(3836,'Which festival is celebrated by worshipping cows and bulls?','गाय और बैलों की पूजा से संबंधित पर्व कौन सा है?','[{"key": "A", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}, {"key": "B", "en": "Mattu Pongal", "hi": "मट्टू पोंगल"}, {"key": "C", "en": "Gopashtami", "hi": "गोपाष्टमी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3837,'Which festival is associated with floating lamps in water in Odisha?','ओडिशा में जल में दीप प्रवाहित करने से जुड़ा त्योहार कौन सा है?','[{"key": "A", "en": "Boita Bandana", "hi": "बोइता बंदना"}, {"key": "B", "en": "Kartik Purnima", "hi": "कार्तिक पूर्णिमा"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Rath Yatra", "hi": "रथ यात्रा"}]','C');
INSERT INTO knowledge_quiz VALUES(3838,'Which festival is celebrated with the worship of nine forms of Goddess Durga?','देवी दुर्गा के नौ रूपों की पूजा किस पर्व में की जाती है?','[{"key": "A", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "B", "en": "Durga Puja", "hi": "दुर्गा पूजा"}, {"key": "C", "en": "Vasant Panchami", "hi": "वसंत पंचमी"}, {"key": "D", "en": "Kali Puja", "hi": "काली पूजा"}]','A');
INSERT INTO knowledge_quiz VALUES(3839,'Which festival is mainly celebrated in West Bengal with grand pandals?','भव्य पंडालों के साथ मुख्य रूप से पश्चिम बंगाल में कौन सा त्योहार मनाया जाता है?','[{"key": "A", "en": "Kali Puja", "hi": "काली पूजा"}, {"key": "B", "en": "Durga Puja", "hi": "दुर्गा पूजा"}, {"key": "C", "en": "Saraswati Puja", "hi": "सरस्वती पूजा"}, {"key": "D", "en": "Diwali", "hi": "दीवाली"}]','B');
INSERT INTO knowledge_quiz VALUES(3840,'Which festival is celebrated on the new moon of Kartik month?','कार्तिक अमावस्या को कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Diwali", "hi": "दीवाली"}, {"key": "B", "en": "Kali Puja", "hi": "काली पूजा"}, {"key": "C", "en": "Amavasya", "hi": "अमावस्या"}, {"key": "D", "en": "Both A and B", "hi": "A और B दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(3841,'Which festival is celebrated to welcome spring season?','वसंत ऋतु के स्वागत में कौन सा त्योहार मनाया जाता है?','[{"key": "A", "en": "Vasant Panchami", "hi": "वसंत पंचमी"}, {"key": "B", "en": "Holi", "hi": "होली"}, {"key": "C", "en": "Basant Utsav", "hi": "बसंत उत्सव"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3842,'Which festival is celebrated by fasting on Ekadashi?','एकादशी के दिन उपवास से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Devshayani Ekadashi", "hi": "देवशयनी एकादशी"}, {"key": "B", "en": "Prabodhini Ekadashi", "hi": "प्रबोधिनी एकादशी"}, {"key": "C", "en": "Vaikuntha Ekadashi", "hi": "वैकुंठ एकादशी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3843,'Which festival is celebrated mainly in Gujarat with Garba dance?','गरबा नृत्य के साथ मुख्य रूप से गुजरात में कौन सा त्योहार मनाया जाता है?','[{"key": "A", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "B", "en": "Diwali", "hi": "दीवाली"}, {"key": "C", "en": "Holi", "hi": "होली"}, {"key": "D", "en": "Janmashtami", "hi": "जन्माष्टमी"}]','A');
INSERT INTO knowledge_quiz VALUES(3844,'Which festival is associated with lighting earthen lamps for ancestors?','पितरों के लिए दीप जलाने से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Pitru Paksha", "hi": "पितृ पक्ष"}, {"key": "B", "en": "Kartik Purnima", "hi": "कार्तिक पूर्णिमा"}, {"key": "C", "en": "Diwali", "hi": "दीवाली"}, {"key": "D", "en": "Shraddha", "hi": "श्राद्ध"}]','D');
INSERT INTO knowledge_quiz VALUES(3845,'Which festival marks the beginning of Sharad season?','शरद ऋतु की शुरुआत का पर्व कौन सा है?','[{"key": "A", "en": "Sharad Purnima", "hi": "शरद पूर्णिमा"}, {"key": "B", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "C", "en": "Dussehra", "hi": "दशहरा"}, {"key": "D", "en": "Kartik Purnima", "hi": "कार्तिक पूर्णिमा"}]','A');
INSERT INTO knowledge_quiz VALUES(3846,'Which festival is celebrated with night-long worship of Goddess Lakshmi?','देवी लक्ष्मी की रात्रि पूजा से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Diwali", "hi": "दीवाली"}, {"key": "B", "en": "Kojagiri Purnima", "hi": "कोजागिरी पूर्णिमा"}, {"key": "C", "en": "Sharad Purnima", "hi": "शरद पूर्णिमा"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3847,'Which festival is celebrated to honor brothers by sisters after Diwali?','दीवाली के बाद बहनों द्वारा भाइयों के सम्मान में कौन सा पर्व मनाया जाता है?','[{"key": "A", "en": "Raksha Bandhan", "hi": "रक्षा बंधन"}, {"key": "B", "en": "Bhai Dooj", "hi": "भाई दूज"}, {"key": "C", "en": "Karva Chauth", "hi": "करवा चौथ"}, {"key": "D", "en": "Govardhan Puja", "hi": "गोवर्धन पूजा"}]','B');
INSERT INTO knowledge_quiz VALUES(3848,'Which festival is celebrated mainly in Mithila region of Bihar?','बिहार के मिथिला क्षेत्र में मुख्य रूप से कौन सा त्योहार मनाया जाता है?','[{"key": "A", "en": "Chhath Puja", "hi": "छठ पूजा"}, {"key": "B", "en": "Vivah Panchami", "hi": "विवाह पंचमी"}, {"key": "C", "en": "Durga Puja", "hi": "दुर्गा पूजा"}, {"key": "D", "en": "Buddha Purnima", "hi": "बुद्ध पूर्णिमा"}]','B');
INSERT INTO knowledge_quiz VALUES(3849,'Which festival celebrates the marriage of Lord Rama and Goddess Sita?','भगवान राम और माता सीता के विवाह का पर्व कौन सा है?','[{"key": "A", "en": "Vivah Panchami", "hi": "विवाह पंचमी"}, {"key": "B", "en": "Ram Navami", "hi": "राम नवमी"}, {"key": "C", "en": "Dussehra", "hi": "दशहरा"}, {"key": "D", "en": "Diwali", "hi": "दीवाली"}]','A');
INSERT INTO knowledge_quiz VALUES(3850,'Which festival is associated with offering water to ancestors at Gaya?','गया में पितरों को जल अर्पण से जुड़ा पर्व कौन सा है?','[{"key": "A", "en": "Pitru Paksha", "hi": "पितृ पक्ष"}, {"key": "B", "en": "Shraddha", "hi": "श्राद्ध"}, {"key": "C", "en": "Gaya Shraddha", "hi": "गया श्राद्ध"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3851,'What is the Hindu practice of fasting called?','हिंदू धर्म में उपवास को क्या कहा जाता है?','[{"key": "A", "en": "Tapasya", "hi": "तपस्या"}, {"key": "B", "en": "Vrat", "hi": "व्रत"}, {"key": "C", "en": "Yajna", "hi": "यज्ञ"}, {"key": "D", "en": "Daan", "hi": "दान"}]','B');
INSERT INTO knowledge_quiz VALUES(3852,'Which fast is observed on Mondays for Lord Shiva?','भगवान शिव के लिए सोमवार को कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "B", "en": "Pradosh Vrat", "hi": "प्रदोष व्रत"}, {"key": "C", "en": "Maha Shivaratri", "hi": "महाशिवरात्रि"}, {"key": "D", "en": "Sankashti", "hi": "संकष्टी"}]','A');
INSERT INTO knowledge_quiz VALUES(3853,'At Thiruchendur, which demon was defeated by Lord Murugan using His ''Vel''?','तिरुचेंदूर में, भगवान मुरुगन ने अपने ''वेल'' का उपयोग करके किस असुर को पराजित किया था?','[{"key": "A", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "B", "en": "Soorapadman", "hi": "सूरपद्मन"}, {"key": "C", "en": "Tarakasura", "hi": "तारकासुर"}, {"key": "D", "en": "Bhasmasura", "hi": "भस्मासुर"}]','B');
INSERT INTO knowledge_quiz VALUES(3854,'Which fast is dedicated to Lord Vishnu?','भगवान विष्णु को समर्पित प्रमुख व्रत कौन सा है?','[{"key": "A", "en": "Pradosh Vrat", "hi": "प्रदोष व्रत"}, {"key": "B", "en": "Ekadashi Vrat", "hi": "एकादशी व्रत"}, {"key": "C", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "D", "en": "Chhath Vrat", "hi": "छठ व्रत"}]','B');
INSERT INTO knowledge_quiz VALUES(3855,'How many Ekadashi fasts occur in a year?','एक वर्ष में लगभग कितनी एकादशी होती हैं?','[{"key": "A", "en": "12", "hi": "12"}, {"key": "B", "en": "18", "hi": "18"}, {"key": "C", "en": "24", "hi": "24"}, {"key": "D", "en": "30", "hi": "30"}]','C');
INSERT INTO knowledge_quiz VALUES(3856,'Which fast is observed on Thursdays for Lord Vishnu and Brihaspati?','गुरुवार को भगवान विष्णु और बृहस्पति के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Guruvar Vrat", "hi": "गुरुवार व्रत"}, {"key": "B", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "C", "en": "Shukravar Vrat", "hi": "शुक्रवार व्रत"}, {"key": "D", "en": "Mangalvar Vrat", "hi": "मंगलवार व्रत"}]','A');
INSERT INTO knowledge_quiz VALUES(3857,'Which fast is observed on Fridays for Goddess Lakshmi?','देवी लक्ष्मी के लिए शुक्रवार को कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Shukravar Vrat", "hi": "शुक्रवार व्रत"}, {"key": "B", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "C", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "D", "en": "Pradosh", "hi": "प्रदोष"}]','A');
INSERT INTO knowledge_quiz VALUES(3858,'Which object was created by Vishwakarma from the dust of the Sun to help Sanjna endure its heat?','विश्वकर्मा ने सूर्य की धूल से किस वस्तु का निर्माण किया था ताकि संज्ञा उसकी गर्मी सह सके?','[{"key": "A", "en": "The Moon", "hi": "चंद्रमा"}, {"key": "B", "en": "Sudarshana Chakra", "hi": "सुदर्शन चक्र"}, {"key": "C", "en": "Pushpaka Vimana", "hi": "पुष्पक विमान"}, {"key": "D", "en": "Trishula", "hi": "त्रिशूल"}]','B');
INSERT INTO knowledge_quiz VALUES(3859,'Which fast is observed on the fourth lunar day for Lord Ganesha?','चतुर्थी को भगवान गणेश के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "B", "en": "Chaturthi", "hi": "चतुर्थी"}, {"key": "C", "en": "Pradosh", "hi": "प्रदोष"}, {"key": "D", "en": "Amavasya", "hi": "अमावस्या"}]','B');
INSERT INTO knowledge_quiz VALUES(3860,'Which monthly fast is known as Sankashti Chaturthi?','संकष्टी चतुर्थी किस देवता से संबंधित व्रत है?','[{"key": "A", "en": "Lord Shiva", "hi": "भगवान शिव"}, {"key": "B", "en": "Lord Vishnu", "hi": "भगवान विष्णु"}, {"key": "C", "en": "Lord Ganesha", "hi": "भगवान गणेश"}, {"key": "D", "en": "Lord Hanuman", "hi": "भगवान हनुमान"}]','C');
INSERT INTO knowledge_quiz VALUES(3861,'Which fast is observed by married women for their husbands’ long life?','पति की दीर्घायु के लिए विवाहित महिलाएं कौन सा व्रत रखती हैं?','[{"key": "A", "en": "Vat Savitri Vrat", "hi": "वट सावित्री व्रत"}, {"key": "B", "en": "Karva Chauth", "hi": "करवा चौथ"}, {"key": "C", "en": "Teej", "hi": "तीज"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3862,'Which fast is observed on Karva Chauth?','करवा चौथ में व्रती क्या करती हैं?','[{"key": "A", "en": "Fruit fast", "hi": "फलाहार"}, {"key": "B", "en": "Water-only fast", "hi": "केवल जल"}, {"key": "C", "en": "Nirjala fast", "hi": "निर्जला व्रत"}, {"key": "D", "en": "Partial fast", "hi": "आंशिक व्रत"}]','C');
INSERT INTO knowledge_quiz VALUES(3863,'Which Ekadashi is considered the most strict fast?','सबसे कठोर एकादशी कौन सी मानी जाती है?','[{"key": "A", "en": "Mokshada Ekadashi", "hi": "मोक्षदा एकादशी"}, {"key": "B", "en": "Nirjala Ekadashi", "hi": "निर्जला एकादशी"}, {"key": "C", "en": "Vaikuntha Ekadashi", "hi": "वैकुंठ एकादशी"}, {"key": "D", "en": "Devshayani Ekadashi", "hi": "देवशयनी एकादशी"}]','B');
INSERT INTO knowledge_quiz VALUES(3864,'Which fast marks the beginning of Chaturmas?','चातुर्मास की शुरुआत किस व्रत से होती है?','[{"key": "A", "en": "Prabodhini Ekadashi", "hi": "प्रबोधिनी एकादशी"}, {"key": "B", "en": "Devshayani Ekadashi", "hi": "देवशयनी एकादशी"}, {"key": "C", "en": "Ashadhi Ekadashi", "hi": "आषाढ़ी एकादशी"}, {"key": "D", "en": "Both B and C", "hi": "B और C दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(3865,'Which fast ends the Chaturmas period?','चातुर्मास का समापन किस व्रत से होता है?','[{"key": "A", "en": "Devshayani Ekadashi", "hi": "देवशयनी एकादशी"}, {"key": "B", "en": "Prabodhini Ekadashi", "hi": "प्रबोधिनी एकादशी"}, {"key": "C", "en": "Vaikuntha Ekadashi", "hi": "वैकुंठ एकादशी"}, {"key": "D", "en": "Kartik Purnima", "hi": "कार्तिक पूर्णिमा"}]','B');
