INSERT INTO knowledge_quiz VALUES(3868,'Which fast is observed on Amavasya?','अमावस्या के दिन कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "B", "en": "Amavasya Vrat", "hi": "अमावस्या व्रत"}, {"key": "C", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "D", "en": "Chaturthi", "hi": "चतुर्थी"}]','B');
INSERT INTO knowledge_quiz VALUES(3869,'Which fast is observed for ancestors during Pitru Paksha?','पितृ पक्ष में किस व्रत का पालन किया जाता है?','[{"key": "A", "en": "Shraddha", "hi": "श्राद्ध"}, {"key": "B", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "C", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "D", "en": "Pradosh Vrat", "hi": "प्रदोष व्रत"}]','A');
INSERT INTO knowledge_quiz VALUES(3870,'Which fast is observed twice a month on Trayodashi?','त्रयोदशी को महीने में दो बार कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "B", "en": "Pradosh Vrat", "hi": "प्रदोष व्रत"}, {"key": "C", "en": "Chaturthi", "hi": "चतुर्थी"}, {"key": "D", "en": "Amavasya", "hi": "अमावस्या"}]','B');
INSERT INTO knowledge_quiz VALUES(3871,'Which fast is observed for Goddess Santoshi?','संतोषी माता के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Shukravar Vrat", "hi": "शुक्रवार व्रत"}, {"key": "B", "en": "Santoshi Mata Vrat", "hi": "संतोषी माता व्रत"}, {"key": "C", "en": "Navratri Vrat", "hi": "नवरात्रि व्रत"}, {"key": "D", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}]','B');
INSERT INTO knowledge_quiz VALUES(3872,'Which fast is observed on Purnima?','पूर्णिमा के दिन कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Purnima Vrat", "hi": "पूर्णिमा व्रत"}, {"key": "B", "en": "Amavasya Vrat", "hi": "अमावस्या व्रत"}, {"key": "C", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "D", "en": "Chaturthi", "hi": "चतुर्थी"}]','A');
INSERT INTO knowledge_quiz VALUES(3873,'Which fast is associated with Tulsi Vivah?','तुलसी विवाह किस व्रत से जुड़ा है?','[{"key": "A", "en": "Prabodhini Ekadashi", "hi": "प्रबोधिनी एकादशी"}, {"key": "B", "en": "Devshayani Ekadashi", "hi": "देवशयनी एकादशी"}, {"key": "C", "en": "Vaikuntha Ekadashi", "hi": "वैकुंठ एकादशी"}, {"key": "D", "en": "Nirjala Ekadashi", "hi": "निर्जला एकादशी"}]','A');
