INSERT INTO knowledge_quiz VALUES(3876,'Which fast involves consuming only fruits and milk?','केवल फल और दूध ग्रहण करने वाला व्रत कौन सा है?','[{"key": "A", "en": "Nirjala Vrat", "hi": "निर्जला व्रत"}, {"key": "B", "en": "Phalahar Vrat", "hi": "फलाहार व्रत"}, {"key": "C", "en": "Upvas", "hi": "उपवास"}, {"key": "D", "en": "Tapasya", "hi": "तपस्या"}]','B');
INSERT INTO knowledge_quiz VALUES(3877,'Which fast is associated with Goddess Parvati for marital bliss?','वैवाहिक सुख के लिए देवी पार्वती से जुड़ा कौन सा व्रत है?','[{"key": "A", "en": "Hartalika Teej", "hi": "हरतालिका तीज"}, {"key": "B", "en": "Vat Savitri", "hi": "वट सावित्री"}, {"key": "C", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3878,'Which site in the Lower Subansiri district is home to a massive 25-feet high naturally formed Shiva Linga?','लोअर सुबनसिरी जिले के किस स्थान पर 25 फीट ऊंचा प्राकृतिक रूप से निर्मित विशाल शिव लिंग स्थित है?','[{"key": "A", "en": "Malinithan", "hi": "मालिनीथान"}, {"key": "B", "en": "Kardo Hills, Ziro", "hi": "कार्दो हिल्स, जीरो"}, {"key": "C", "en": "Tirap", "hi": "तिराप"}, {"key": "D", "en": "Anini", "hi": "अनिनी"}]','B');
