INSERT INTO knowledge_quiz VALUES(3880,'Which fast is considered a penance for spiritual purification?','आध्यात्मिक शुद्धि के लिए कौन सा व्रत किया जाता है?','[{"key": "A", "en": "Upvas", "hi": "उपवास"}, {"key": "B", "en": "Tapasya", "hi": "तपस्या"}, {"key": "C", "en": "Vrat", "hi": "व्रत"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3881,'Which fast is observed by unmarried girls for a good husband?','अविवाहित कन्याएं अच्छे वर के लिए कौन सा व्रत रखती हैं?','[{"key": "A", "en": "Hartalika Teej", "hi": "हरतालिका तीज"}, {"key": "B", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "C", "en": "Katyayani Vrat", "hi": "कात्यायनी व्रत"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3882,'Which fast is described in Bhagavata Purana for Gopis?','भागवत पुराण में गोपियों द्वारा किया गया कौन सा व्रत वर्णित है?','[{"key": "A", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "B", "en": "Katyayani Vrat", "hi": "कात्यायनी व्रत"}, {"key": "C", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "D", "en": "Nirjala Vrat", "hi": "निर्जला व्रत"}]','B');
INSERT INTO knowledge_quiz VALUES(3883,'Which fast is observed for Goddess Durga during Navratri?','नवरात्रि में देवी दुर्गा के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Durga Ashtami Vrat", "hi": "दुर्गा अष्टमी व्रत"}, {"key": "B", "en": "Navratri Vrat", "hi": "नवरात्रि व्रत"}, {"key": "C", "en": "Phalahar", "hi": "फलाहार"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3884,'Which fast is observed on Gauri Tritiya?','गौरी तृतीया पर कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Teej Vrat", "hi": "तीज व्रत"}, {"key": "B", "en": "Hartalika Teej", "hi": "हरतालिका तीज"}, {"key": "C", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "D", "en": "Ekadashi", "hi": "एकादशी"}]','A');
