INSERT INTO knowledge_quiz VALUES(3886,'Which fast is observed on Skanda Shashti?','स्कंद षष्ठी पर कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Murugan Vrat", "hi": "मुरुगन व्रत"}, {"key": "B", "en": "Kartikeya Vrat", "hi": "कार्तिकेय व्रत"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Ekadashi", "hi": "एकादशी"}]','C');
INSERT INTO knowledge_quiz VALUES(3887,'Which fast is associated with worship of nine planets?','नवग्रहों की पूजा से कौन सा व्रत जुड़ा है?','[{"key": "A", "en": "Navagraha Vrat", "hi": "नवग्रह व्रत"}, {"key": "B", "en": "Shani Vrat", "hi": "शनि व्रत"}, {"key": "C", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "D", "en": "Guruvar Vrat", "hi": "गुरुवार व्रत"}]','A');
