INSERT INTO knowledge_quiz VALUES(3889,'Which fast is observed on Kamika Ekadashi?','कामिका एकादशी किस देवता से संबंधित है?','[{"key": "A", "en": "Lord Vishnu", "hi": "भगवान विष्णु"}, {"key": "B", "en": "Lord Shiva", "hi": "भगवान शिव"}, {"key": "C", "en": "Lord Brahma", "hi": "भगवान ब्रह्मा"}, {"key": "D", "en": "Sun God", "hi": "सूर्य देव"}]','A');
