INSERT INTO knowledge_quiz VALUES(3892,'Which fast is observed for Goddess Sheetala?','देवी शीतला के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Sheetala Ashtami", "hi": "शीतला अष्टमी"}, {"key": "B", "en": "Navratri", "hi": "नवरात्रि"}, {"key": "C", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "D", "en": "Amavasya", "hi": "अमावस्या"}]','A');
