INSERT INTO knowledge_quiz VALUES(3894,'Which fast is observed for mental peace and prosperity?','मानसिक शांति और समृद्धि के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "B", "en": "Guruvar Vrat", "hi": "गुरुवार व्रत"}, {"key": "C", "en": "Shukravar Vrat", "hi": "शुक्रवार व्रत"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3895,'Which fast is observed for removal of obstacles?','विघ्नों के नाश के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Sankashti Chaturthi", "hi": "संकष्टी चतुर्थी"}, {"key": "B", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "C", "en": "Pradosh Vrat", "hi": "प्रदोष व्रत"}, {"key": "D", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}]','A');
INSERT INTO knowledge_quiz VALUES(3896,'Which fast is associated with Lord Rama?','भगवान राम से कौन सा व्रत जुड़ा है?','[{"key": "A", "en": "Ram Navami Vrat", "hi": "राम नवमी व्रत"}, {"key": "B", "en": "Ekadashi", "hi": "एकादशी"}, {"key": "C", "en": "Somvar Vrat", "hi": "सोमवार व्रत"}, {"key": "D", "en": "Pradosh Vrat", "hi": "प्रदोष व्रत"}]','A');
INSERT INTO knowledge_quiz VALUES(3897,'Which fast is observed on Janmashtami?','जन्माष्टमी पर कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Krishna Vrat", "hi": "कृष्ण व्रत"}, {"key": "B", "en": "Nirjala or Phalahar", "hi": "निर्जला या फलाहार"}, {"key": "C", "en": "Upvas till midnight", "hi": "मध्यरात्रि तक उपवास"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3898,'Which fast is observed on Maha Shivaratri?','महाशिवरात्रि पर कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Shiva Vrat", "hi": "शिव व्रत"}, {"key": "B", "en": "Nirjala or Phalahar", "hi": "निर्जला या फलाहार"}, {"key": "C", "en": "Night vigil fast", "hi": "रात्रि जागरण व्रत"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3899,'Which fast is observed to please Goddess Lakshmi?','देवी लक्ष्मी को प्रसन्न करने के लिए कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Shukravar Vrat", "hi": "शुक्रवार व्रत"}, {"key": "B", "en": "Kojagiri Vrat", "hi": "कोजागिरी व्रत"}, {"key": "C", "en": "Varalakshmi Vratam", "hi": "वरलक्ष्मी व्रतम"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3900,'Which fast is observed mainly in South India for Goddess Lakshmi?','दक्षिण भारत में देवी लक्ष्मी के लिए प्रमुख रूप से कौन सा व्रत रखा जाता है?','[{"key": "A", "en": "Varalakshmi Vratam", "hi": "वरलक्ष्मी व्रतम"}, {"key": "B", "en": "Karva Chauth", "hi": "करवा चौथ"}, {"key": "C", "en": "Vat Savitri", "hi": "वट सावित्री"}, {"key": "D", "en": "Ekadashi", "hi": "एकादशी"}]','A');
INSERT INTO knowledge_quiz VALUES(3901,'The Kailasa Temple, a massive monolithic structure carved out of a single rock, is part of which UNESCO World Heritage site?','कैलाश मंदिर, जो एक ही चट्टान से तराशा गया विशाल अखंड ढांचा है, किस यूनेस्को विश्व धरोहर स्थल का हिस्सा है?','[{"key": "A", "en": "Ajanta Caves", "hi": "अजंता की गुफाएं"}, {"key": "B", "en": "Ellora Caves", "hi": "एलोरा की गुफाएं"}, {"key": "C", "en": "Elephanta Caves", "hi": "एलिफेंटा की गुफाएं"}, {"key": "D", "en": "Kanheri Caves", "hi": "कान्हेरी की गुफाएं"}]','B');
INSERT INTO knowledge_quiz VALUES(3902,'Who is known as the preserver in Hindu mythology?','हिंदू पौराणिक कथाओं में पालनकर्ता कौन हैं?','[{"key": "A", "en": "Shiva", "hi": "शिव"}, {"key": "B", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "C", "en": "Vishnu", "hi": "विष्णु"}, {"key": "D", "en": "Agni", "hi": "अग्नि"}]','C');
INSERT INTO knowledge_quiz VALUES(3903,'Which of the following Jyotirlingas is located at the source of the river Bhima?','निम्नलिखित में से कौन सा ज्योतिर्लिंग भीमा नदी के उद्गम स्थल पर स्थित है?','[{"key": "A", "en": "Trimbakeshwar", "hi": "त्रयंबकेश्वर"}, {"key": "B", "en": "Grishneshwar", "hi": "घृष्णेश्वर"}, {"key": "C", "en": "Bhimashankar", "hi": "भीमाशंकर"}, {"key": "D", "en": "Aundha Nagnath", "hi": "औंढा नागनाथ"}]','C');
INSERT INTO knowledge_quiz VALUES(3904,'Which temple is located at the origin of the river Vishwamitri in Pavagadh?','पावागढ़ में विश्वामित्री नदी के उद्गम स्थल पर कौन सा मंदिर स्थित है?','[{"key": "A", "en": "Kalika Mata", "hi": "कालिका माता"}, {"key": "B", "en": "Lakulish Temple", "hi": "लकुलीश मंदिर"}, {"key": "C", "en": "Jain Temples", "hi": "जैन मंदिर"}, {"key": "D", "en": "Navlakha Temple", "hi": "नवलखा मंदिर"}]','B');
INSERT INTO knowledge_quiz VALUES(3905,'Who is the author of the Ramayana?','रामायण के रचयिता कौन हैं?','[{"key": "A", "en": "Ved Vyasa", "hi": "वेदव्यास"}, {"key": "B", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "C", "en": "Tulsidas", "hi": "तुलसीदास"}, {"key": "D", "en": "Bharavi", "hi": "भारवि"}]','B');
INSERT INTO knowledge_quiz VALUES(3906,'Which deity was born from the shadow of Surya''s wife, Sandhya?','सूर्य की पत्नी संध्या की छाया से किस देवता का जन्म हुआ था?','[{"key": "A", "en": "Lord Yama", "hi": "भगवान यम"}, {"key": "B", "en": "Lord Shani", "hi": "भगवान शनि"}, {"key": "C", "en": "Lord Mangal", "hi": "भगवान मंगल"}, {"key": "D", "en": "Lord Varuna", "hi": "भगवान वरुण"}]','B');
INSERT INTO knowledge_quiz VALUES(3907,'What was the name of the forest where Rama, Laxmana, and Sita built their hut during the early years of exile?','वनवास के शुरुआती वर्षों में राम, लक्ष्मण और सीता ने अपनी कुटिया किस वन में बनाई थी?','[{"key": "A", "en": "Naimisharanya", "hi": "नैमिषारण्य"}, {"key": "B", "en": "Panchavati", "hi": "पंचवटी"}, {"key": "C", "en": "Madhuvana", "hi": "मधुवन"}, {"key": "D", "en": "Kamyaka Vana", "hi": "काम्यक वन"}]','B');
INSERT INTO knowledge_quiz VALUES(3908,'Who raised Lord Krishna in Gokul?','गोकुल में भगवान कृष्ण का पालन-पोषण किसने किया?','[{"key": "A", "en": "Vasudeva and Devaki", "hi": "वसुदेव और देवकी"}, {"key": "B", "en": "Nanda and Yashoda", "hi": "नंद और यशोदा"}, {"key": "C", "en": "Ugrasena and Devaki", "hi": "उग्रसेन और देवकी"}, {"key": "D", "en": "Balarama and Rohini", "hi": "बलराम और रोहिणी"}]','B');
INSERT INTO knowledge_quiz VALUES(3909,'Who was the demon king defeated by Lord Rama?','भगवान राम ने किस राक्षस राजा का वध किया?','[{"key": "A", "en": "Kumbhakarna", "hi": "कुंभकर्ण"}, {"key": "B", "en": "Ravana", "hi": "रावण"}, {"key": "C", "en": "Bali", "hi": "बालि"}, {"key": "D", "en": "Meghnad", "hi": "मेघनाद"}]','B');
INSERT INTO knowledge_quiz VALUES(3910,'Who was the devoted wife of Lord Rama?','भगवान राम की पतिव्रता पत्नी कौन थीं?','[{"key": "A", "en": "Urmila", "hi": "उर्मिला"}, {"key": "B", "en": "Mandodari", "hi": "मंदोदरी"}, {"key": "C", "en": "Sita", "hi": "सीता"}, {"key": "D", "en": "Tara", "hi": "तारा"}]','C');
INSERT INTO knowledge_quiz VALUES(3911,'Which of these is not the name of one of the seven horses of the Sun God?','इनमें से कौन सा सूर्य देव के सात घोड़ों में से एक का नाम नहीं है?','[{"key": "A", "en": "Gayatri", "hi": "गायत्री"}, {"key": "B", "en": "Brihati", "hi": "बृहती"}, {"key": "C", "en": "Anustup", "hi": "अनुष्टुप"}, {"key": "D", "en": "Uchaihshravas", "hi": "उच्चैःश्रवा"}]','D');
INSERT INTO knowledge_quiz VALUES(3912,'The temple of Gadhada is one of the most important pilgrimage sites for which sect?','गढड़ा का मंदिर किस संप्रदाय के लिए सबसे महत्वपूर्ण तीर्थ स्थलों में से एक है?','[{"key": "A", "en": "Vaishnavism", "hi": "वैष्णव धर्म"}, {"key": "B", "en": "Shaivism", "hi": "शैव धर्म"}, {"key": "C", "en": "Swaminarayan Sampraday", "hi": "स्वामीनारायण संप्रदाय"}, {"key": "D", "en": "Jainism", "hi": "जैन धर्म"}]','C');
INSERT INTO knowledge_quiz VALUES(3913,'Who was the eldest of the Pandavas?','पांडवों में सबसे बड़े कौन थे?','[{"key": "A", "en": "Bhima", "hi": "भीम"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "D", "en": "Nakula", "hi": "नकुल"}]','C');
INSERT INTO knowledge_quiz VALUES(3914,'Which ancient temple in Dumka district is known as the ''Village of Temples'' and contains 108 terracotta temples?','दुमका जिले के किस प्राचीन मंदिर स्थल को ''मंदिरों का गाँव'' कहा जाता है और यहाँ 108 टेराकोटा मंदिर हैं?','[{"key": "A", "en": "Maluti Temples", "hi": "मलूटी मंदिर"}, {"key": "B", "en": "Deori Temple", "hi": "देउड़ी मंदिर"}, {"key": "C", "en": "Jagannath Temple", "hi": "जगन्नाथ मंदिर"}, {"key": "D", "en": "Sun Temple", "hi": "सूर्य मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(3915,'Who was the mother of the Pandavas?','पांडवों की माता कौन थीं?','[{"key": "A", "en": "Gandhari", "hi": "गांधारी"}, {"key": "B", "en": "Kunti", "hi": "कुंती"}, {"key": "C", "en": "Madri", "hi": "माद्री"}, {"key": "D", "en": "Both B and C", "hi": "B और C दोनों"}]','D');
INSERT INTO knowledge_quiz VALUES(3916,'Who was the blind king of Hastinapura?','हस्तिनापुर का अंधा राजा कौन था?','[{"key": "A", "en": "Pandu", "hi": "पांडु"}, {"key": "B", "en": "Dhritarashtra", "hi": "धृतराष्ट्र"}, {"key": "C", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "D", "en": "Shantanu", "hi": "शंतनु"}]','B');
INSERT INTO knowledge_quiz VALUES(3917,'Who was the wife of Dhritarashtra?','धृतराष्ट्र की पत्नी कौन थीं?','[{"key": "A", "en": "Kunti", "hi": "कुंती"}, {"key": "B", "en": "Gandhari", "hi": "गांधारी"}, {"key": "C", "en": "Madri", "hi": "माद्री"}, {"key": "D", "en": "Urmila", "hi": "उर्मिला"}]','B');
INSERT INTO knowledge_quiz VALUES(3918,'Who was the son of Bhima and Hidimba?','भीम और हिडिंबा का पुत्र कौन था?','[{"key": "A", "en": "Ghatotkacha", "hi": "घटोत्कच"}, {"key": "B", "en": "Abhimanyu", "hi": "अभिमन्यु"}, {"key": "C", "en": "Barbarika", "hi": "बर्बरीक"}, {"key": "D", "en": "Sahadeva", "hi": "सहदेव"}]','A');
INSERT INTO knowledge_quiz VALUES(3919,'Who was Arjuna’s son who died in the Chakravyuha?','चक्रव्यूह में अर्जुन का कौन सा पुत्र वीरगति को प्राप्त हुआ?','[{"key": "A", "en": "Ghatotkacha", "hi": "घटोत्कच"}, {"key": "B", "en": "Abhimanyu", "hi": "अभिमन्यु"}, {"key": "C", "en": "Pradyumna", "hi": "प्रद्युम्न"}, {"key": "D", "en": "Aniruddha", "hi": "अनिरुद्ध"}]','B');
INSERT INTO knowledge_quiz VALUES(3920,'Who was the wife of Arjuna?','अर्जुन की पत्नी कौन थीं?','[{"key": "A", "en": "Subhadra", "hi": "सुभद्रा"}, {"key": "B", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "C", "en": "Ulupi", "hi": "उलूपी"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3921,'Who was the common wife of the five Pandavas?','पांचों पांडवों की साझा पत्नी कौन थीं?','[{"key": "A", "en": "Kunti", "hi": "कुंती"}, {"key": "B", "en": "Subhadra", "hi": "सुभद्रा"}, {"key": "C", "en": "Draupadi", "hi": "द्रौपदी"}, {"key": "D", "en": "Gandhari", "hi": "गांधारी"}]','C');
INSERT INTO knowledge_quiz VALUES(3922,'Which of Ravana''s brothers was the ruler of the Patala?','रावण का कौन सा भाई पाताल लोक का शासक था?','[{"key": "A", "en": "Kumbhakarna", "hi": "कुंभकर्ण"}, {"key": "B", "en": "Ahiravana", "hi": "अहिरावण"}, {"key": "C", "en": "Vibhishana", "hi": "विभीषण"}, {"key": "D", "en": "Khara", "hi": "खर"}]','B');
INSERT INTO knowledge_quiz VALUES(3923,'What boon made Bhishma invincible?','भीष्म को अजेय बनाने वाला वरदान क्या था?','[{"key": "A", "en": "Boon of immortality", "hi": "अमरता का वरदान"}, {"key": "B", "en": "Choice of death", "hi": "इच्छा मृत्यु"}, {"key": "C", "en": "Divine weapons", "hi": "दिव्य अस्त्र"}, {"key": "D", "en": "Blessing of Vishnu", "hi": "विष्णु का आशीर्वाद"}]','B');
INSERT INTO knowledge_quiz VALUES(3924,'Who was the teacher of Karna?','कर्ण के गुरु कौन थे?','[{"key": "A", "en": "Dronacharya", "hi": "द्रोणाचार्य"}, {"key": "B", "en": "Parashurama", "hi": "परशुराम"}, {"key": "C", "en": "Kripacharya", "hi": "कृपाचार्य"}, {"key": "D", "en": "Vashistha", "hi": "वशिष्ठ"}]','B');
INSERT INTO knowledge_quiz VALUES(3925,'Who was Karna’s biological mother?','कर्ण की जैविक माता कौन थीं?','[{"key": "A", "en": "Madri", "hi": "माद्री"}, {"key": "B", "en": "Gandhari", "hi": "गांधारी"}, {"key": "C", "en": "Kunti", "hi": "कुंती"}, {"key": "D", "en": "Radha", "hi": "राधा"}]','C');
INSERT INTO knowledge_quiz VALUES(3926,'Who was the king of Lanka in Ramayana?','रामायण में लंका का राजा कौन था?','[{"key": "A", "en": "Vibhishana", "hi": "विभीषण"}, {"key": "B", "en": "Ravana", "hi": "रावण"}, {"key": "C", "en": "Kumbhakarna", "hi": "कुंभकर्ण"}, {"key": "D", "en": "Meghnad", "hi": "मेघनाद"}]','B');
INSERT INTO knowledge_quiz VALUES(3927,'Who helped Rama build the bridge to Lanka?','लंका जाने के लिए सेतु निर्माण में राम की सहायता किसने की?','[{"key": "A", "en": "Sugriva", "hi": "सुग्रीव"}, {"key": "B", "en": "Hanuman", "hi": "हनुमान"}, {"key": "C", "en": "Vanara Sena", "hi": "वानर सेना"}, {"key": "D", "en": "All of the above", "hi": "उपरोक्त सभी"}]','D');
INSERT INTO knowledge_quiz VALUES(3928,'Who were the original founders/builders of the Siddhivinayak temple?','सिद्धिविनायक मंदिर के मूल संस्थापक/निर्माता कौन थे?','[{"key": "A", "en": "Ahilyabai Holkar", "hi": "अहिल्याबाई होल्कर"}, {"key": "B", "en": "Laxman Vithu and Deubai Patil", "hi": "लक्ष्मण विठू और देउबाई पाटिल"}, {"key": "C", "en": "Nana Phadnavis", "hi": "नाना फड़नवीस"}, {"key": "D", "en": "Bal Gangadhar Tilak", "hi": "बाल गंगाधर तिलक"}]','B');
INSERT INTO knowledge_quiz VALUES(3929,'Who was the brother of Gandhari?','गांधारी के भाई कौन थे?','[{"key": "A", "en": "Shalya", "hi": "शल्य"}, {"key": "B", "en": "Shakuni", "hi": "शकुनि"}, {"key": "C", "en": "Vidura", "hi": "विदुर"}, {"key": "D", "en": "Ashwatthama", "hi": "अश्वत्थामा"}]','B');
INSERT INTO knowledge_quiz VALUES(3930,'Who was the sage that cursed Indra to have a thousand eyes?','इंद्र को सहस्र नेत्रों का शाप किस ऋषि ने दिया?','[{"key": "A", "en": "Gautama", "hi": "गौतम"}, {"key": "B", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "C", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "D", "en": "Durvasa", "hi": "दुर्वासा"}]','A');
INSERT INTO knowledge_quiz VALUES(3931,'Who is the king of the gods in Hindu mythology?','हिंदू पौराणिक कथाओं में देवताओं का राजा कौन है?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Varuna", "hi": "वरुण"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','C');
INSERT INTO knowledge_quiz VALUES(3932,'Who is the god of death in Hindu mythology?','हिंदू धर्म में मृत्यु के देवता कौन हैं?','[{"key": "A", "en": "Yama", "hi": "यम"}, {"key": "B", "en": "Agni", "hi": "अग्नि"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Shani", "hi": "शनि"}]','A');
INSERT INTO knowledge_quiz VALUES(3933,'Who is the god of fire?','अग्नि के देवता कौन हैं?','[{"key": "A", "en": "Vayu", "hi": "वायु"}, {"key": "B", "en": "Agni", "hi": "अग्नि"}, {"key": "C", "en": "Surya", "hi": "सूर्य"}, {"key": "D", "en": "Varuna", "hi": "वरुण"}]','B');
INSERT INTO knowledge_quiz VALUES(3934,'Who is the god of the sun?','सूर्य के देवता कौन हैं?','[{"key": "A", "en": "Surya", "hi": "सूर्य"}, {"key": "B", "en": "Agni", "hi": "अग्नि"}, {"key": "C", "en": "Vayu", "hi": "वायु"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','A');
INSERT INTO knowledge_quiz VALUES(3935,'Who is the god of wind?','वायु के देवता कौन हैं?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Vayu", "hi": "वायु"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','B');
INSERT INTO knowledge_quiz VALUES(3936,'Who is the god of water?','जल के देवता कौन हैं?','[{"key": "A", "en": "Indra", "hi": "इंद्र"}, {"key": "B", "en": "Agni", "hi": "अग्नि"}, {"key": "C", "en": "Varuna", "hi": "वरुण"}, {"key": "D", "en": "Vayu", "hi": "वायु"}]','C');
INSERT INTO knowledge_quiz VALUES(3937,'Who is the goddess of wealth?','धन की देवी कौन हैं?','[{"key": "A", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Parvati", "hi": "पार्वती"}, {"key": "D", "en": "Durga", "hi": "दुर्गा"}]','B');
INSERT INTO knowledge_quiz VALUES(3938,'Which temple in Nagpur is famous for being dedicated to Lord Rama and is built with white marble?','नागपुर का कौन सा मंदिर भगवान राम को समर्पित होने के लिए प्रसिद्ध है और सफेद संगमरमर से बना है?','[{"key": "A", "en": "Poddareshwar Ram Mandir", "hi": "पोद्दारेश्वर राम मंदिर"}, {"key": "B", "en": "Ramtek Temple", "hi": "रामटेक मंदिर"}, {"key": "C", "en": "Koradi Temple", "hi": "कोराडी मंदिर"}, {"key": "D", "en": "Tekdi Ganpati", "hi": "टेकड़ी गणपति"}]','A');
INSERT INTO knowledge_quiz VALUES(3939,'Who is the consort of Lord Shiva?','भगवान शिव की पत्नी कौन हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Parvati", "hi": "पार्वती"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','B');
INSERT INTO knowledge_quiz VALUES(3940,'In which year was the original small structure of the Siddhivinayak Temple first consecrated?','सिद्धिविनायक मंदिर की मूल छोटी संरचना पहली बार किस वर्ष प्रतिष्ठित की गई थी?','[{"key": "A", "en": "1801", "hi": "1801"}, {"key": "B", "en": "1901", "hi": "1901"}, {"key": "C", "en": "1750", "hi": "1750"}, {"key": "D", "en": "1857", "hi": "1857"}]','A');
INSERT INTO knowledge_quiz VALUES(3941,'Who is the commander of the gods’ army?','देवताओं की सेना का सेनापति कौन है?','[{"key": "A", "en": "Ganesha", "hi": "गणेश"}, {"key": "B", "en": "Kartikeya", "hi": "कार्तिकेय"}, {"key": "C", "en": "Hanuman", "hi": "हनुमान"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3942,'Who is known as the monkey god?','वानर देवता के रूप में कौन प्रसिद्ध हैं?','[{"key": "A", "en": "Sugriva", "hi": "सुग्रीव"}, {"key": "B", "en": "Hanuman", "hi": "हनुमान"}, {"key": "C", "en": "Vali", "hi": "वालि"}, {"key": "D", "en": "Angada", "hi": "अंगद"}]','B');
INSERT INTO knowledge_quiz VALUES(3943,'Who churned the ocean during Samudra Manthan?','समुद्र मंथन में किसने भाग लिया?','[{"key": "A", "en": "Devas", "hi": "देवता"}, {"key": "B", "en": "Asuras", "hi": "असुर"}, {"key": "C", "en": "Both Devas and Asuras", "hi": "देवता और असुर दोनों"}, {"key": "D", "en": "Nagas", "hi": "नाग"}]','C');
INSERT INTO knowledge_quiz VALUES(3944,'What was used as the churning rope in Samudra Manthan?','समुद्र मंथन में रस्सी के रूप में किसका उपयोग हुआ?','[{"key": "A", "en": "Vasuki", "hi": "वासुकी"}, {"key": "B", "en": "Ananta", "hi": "अनंत"}, {"key": "C", "en": "Takshaka", "hi": "तक्षक"}, {"key": "D", "en": "Shesha", "hi": "शेष"}]','A');
INSERT INTO knowledge_quiz VALUES(3945,'Which mountain was used for churning the ocean?','समुद्र मंथन में किस पर्वत का उपयोग हुआ?','[{"key": "A", "en": "Mount Kailash", "hi": "कैलाश पर्वत"}, {"key": "B", "en": "Mount Meru", "hi": "मेरु पर्वत"}, {"key": "C", "en": "Mandara Mountain", "hi": "मंदराचल पर्वत"}, {"key": "D", "en": "Vindhya", "hi": "विंध्य"}]','C');
INSERT INTO knowledge_quiz VALUES(3946,'Who drank the poison that emerged during Samudra Manthan?','समुद्र मंथन से निकले विष को किसने पिया?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3947,'Which temple near Mysuru is unique because it is submerged under the waters of the KRS Dam for most of the year?','मैसूरु के पास कौन सा मंदिर अद्वितीय है क्योंकि यह वर्ष के अधिकांश समय KRS बांध के पानी में डूबा रहता है?','[{"key": "A", "en": "Venugopala Swamy Temple", "hi": "वेणुगोपाल स्वामी मंदिर"}, {"key": "B", "en": "Nimishamba Temple", "hi": "निमिषांबा मंदिर"}, {"key": "C", "en": "Srikanteshwara Temple", "hi": "श्रीकांतेश्वर मंदिर"}, {"key": "D", "en": "Somnathpur Temple", "hi": "सोमनाथपुर मंदिर"}]','A');
INSERT INTO knowledge_quiz VALUES(3948,'Who emerged with the pot of nectar during Samudra Manthan?','समुद्र मंथन के दौरान अमृत कलश लेकर कौन प्रकट हुआ?','[{"key": "A", "en": "Dhanvantari", "hi": "धन्वंतरि"}, {"key": "B", "en": "Mohini", "hi": "मोहिनी"}, {"key": "C", "en": "Indra", "hi": "इंद्र"}, {"key": "D", "en": "Vishnu", "hi": "विष्णु"}]','A');
INSERT INTO knowledge_quiz VALUES(3949,'Who distributed nectar to the gods?','देवताओं को अमृत कौन पिलाया?','[{"key": "A", "en": "Parvati", "hi": "पार्वती"}, {"key": "B", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "C", "en": "Mohini", "hi": "मोहिनी"}, {"key": "D", "en": "Saraswati", "hi": "सरस्वती"}]','C');
INSERT INTO knowledge_quiz VALUES(3950,'Who is considered the preserver of dharma in Hindu mythology?','हिंदू पौराणिक कथाओं में धर्म का रक्षक किसे माना जाता है?','[{"key": "A", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "B", "en": "Vishnu", "hi": "विष्णु"}, {"key": "C", "en": "Shiva", "hi": "शिव"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3951,'Which other temple, is considered a part of the Omkareshwar Jyotirlinga?','किस अन्य मंदिर को ओंकारेश्वर ज्योतिर्लिंग का ही हिस्सा माना जाता है?','[{"key": "A", "en": "Mamleshwar", "hi": "ममलेश्वर"}, {"key": "B", "en": "Harsiddhi", "hi": "हरसिद्धि"}, {"key": "C", "en": "Kaal Bhairav", "hi": "काल भैरव"}, {"key": "D", "en": "Mangalnath", "hi": "मंगलनाथ"}]','A');
INSERT INTO knowledge_quiz VALUES(3952,'Who is regarded as the founder of Sankhya philosophy?','सांख्य दर्शन के प्रवर्तक कौन माने जाते हैं?','[{"key": "A", "en": "Kapila", "hi": "कपिल"}, {"key": "B", "en": "Gautama", "hi": "गौतम"}, {"key": "C", "en": "Kanada", "hi": "कणाद"}, {"key": "D", "en": "Jaimini", "hi": "जैमिनि"}]','A');
INSERT INTO knowledge_quiz VALUES(3953,'Who was the son of Lord Shiva and Goddess Parvati?','भगवान शिव और देवी पार्वती के पुत्र कौन हैं?','[{"key": "A", "en": "Ganesha", "hi": "गणेश"}, {"key": "B", "en": "Kartikeya", "hi": "कार्तिकेय"}, {"key": "C", "en": "Both A and B", "hi": "A और B दोनों"}, {"key": "D", "en": "Nandi", "hi": "नंदी"}]','C');
INSERT INTO knowledge_quiz VALUES(3954,'What is the vehicle of Lord Vishnu?','भगवान विष्णु का वाहन कौन है?','[{"key": "A", "en": "Nandi", "hi": "नंदी"}, {"key": "B", "en": "Garuda", "hi": "गरुड़"}, {"key": "C", "en": "Mouse", "hi": "मूषक"}, {"key": "D", "en": "Peacock", "hi": "मोर"}]','B');
INSERT INTO knowledge_quiz VALUES(3955,'What is the vehicle of Lord Shiva?','भगवान शिव का वाहन कौन है?','[{"key": "A", "en": "Lion", "hi": "सिंह"}, {"key": "B", "en": "Bull (Nandi)", "hi": "वृषभ (नंदी)"}, {"key": "C", "en": "Elephant", "hi": "हाथी"}, {"key": "D", "en": "Horse", "hi": "घोड़ा"}]','B');
INSERT INTO knowledge_quiz VALUES(3956,'Which river is considered the most sacred in Hinduism?','हिंदू धर्म में सबसे पवित्र नदी कौन सी मानी जाती है?','[{"key": "A", "en": "Yamuna", "hi": "यमुना"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Ganga", "hi": "गंगा"}, {"key": "D", "en": "Godavari", "hi": "गोदावरी"}]','C');
INSERT INTO knowledge_quiz VALUES(3957,'Who brought the river Ganga to earth?','गंगा नदी को पृथ्वी पर कौन लाए?','[{"key": "A", "en": "Bhagiratha", "hi": "भागीरथ"}, {"key": "B", "en": "Shantanu", "hi": "शंतनु"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Jahnu", "hi": "जह्नु"}]','A');
INSERT INTO knowledge_quiz VALUES(3958,'Who held the river Ganga in his hair?','गंगा को अपनी जटाओं में किसने धारण किया?','[{"key": "A", "en": "Vishnu", "hi": "विष्णु"}, {"key": "B", "en": "Shiva", "hi": "शिव"}, {"key": "C", "en": "Brahma", "hi": "ब्रह्मा"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3959,'Who was the sage that cursed King Harishchandra?','राजा हरिश्चंद्र को किस ऋषि ने शाप दिया?','[{"key": "A", "en": "Vishwamitra", "hi": "विश्वामित्र"}, {"key": "B", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "C", "en": "Gautama", "hi": "गौतम"}, {"key": "D", "en": "Agastya", "hi": "अगस्त्य"}]','A');
INSERT INTO knowledge_quiz VALUES(3960,'Who is known for his unwavering truthfulness?','अडिग सत्यनिष्ठा के लिए कौन प्रसिद्ध हैं?','[{"key": "A", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "B", "en": "Harishchandra", "hi": "हरिश्चंद्र"}, {"key": "C", "en": "Rama", "hi": "राम"}, {"key": "D", "en": "Bhishma", "hi": "भीष्म"}]','B');
INSERT INTO knowledge_quiz VALUES(3961,'Who was the mother of Shatrughna in the Ramayana?','रामायण में शत्रुघ्न की माता कौन थीं?','[{"key": "A", "en": "Kaushalya", "hi": "कौशल्या"}, {"key": "B", "en": "Sumitra", "hi": "सुमित्रा"}, {"key": "C", "en": "Kaikeyi", "hi": "कैकेयी"}, {"key": "D", "en": "Urmila", "hi": "उर्मिला"}]','B');
INSERT INTO knowledge_quiz VALUES(3962,'Which demon was killed by Goddess Durga?','देवी दुर्गा ने किस असुर का वध किया?','[{"key": "A", "en": "Ravana", "hi": "रावण"}, {"key": "B", "en": "Mahishasura", "hi": "महिषासुर"}, {"key": "C", "en": "Bhasmasura", "hi": "भस्मासुर"}, {"key": "D", "en": "Hiranyaksha", "hi": "हिरण्याक्ष"}]','B');
INSERT INTO knowledge_quiz VALUES(3963,'Who killed the demon Hiranyakashipu?','हिरण्यकशिपु का वध किसने किया?','[{"key": "A", "en": "Vamana", "hi": "वामन"}, {"key": "B", "en": "Narasimha", "hi": "नरसिंह"}, {"key": "C", "en": "Parashurama", "hi": "परशुराम"}, {"key": "D", "en": "Krishna", "hi": "कृष्ण"}]','B');
INSERT INTO knowledge_quiz VALUES(3964,'Who was the devoted son of Hiranyakashipu?','हिरण्यकशिपु का भक्त पुत्र कौन था?','[{"key": "A", "en": "Bali", "hi": "बलि"}, {"key": "B", "en": "Prahlada", "hi": "प्रह्लाद"}, {"key": "C", "en": "Virochana", "hi": "विरोचन"}, {"key": "D", "en": "Andhaka", "hi": "अंधक"}]','B');
INSERT INTO knowledge_quiz VALUES(3965,'Which avatar of Vishnu measured the universe in three steps?','विष्णु के किस अवतार ने तीन पगों में ब्रह्मांड नापा?','[{"key": "A", "en": "Vamana", "hi": "वामन"}, {"key": "B", "en": "Varaha", "hi": "वराह"}, {"key": "C", "en": "Rama", "hi": "राम"}, {"key": "D", "en": "Krishna", "hi": "कृष्ण"}]','A');
INSERT INTO knowledge_quiz VALUES(3966,'Which of these objects is NOT held by Goddess Kamakshi in her four hands?','देवी कामक्षी ने अपने चार हाथों में इनमें से कौन सी वस्तु धारण नहीं की है?','[{"key": "A", "en": "Sugarcane Bow", "hi": "गन्ने का धनुष"}, {"key": "B", "en": "Lotus Flower", "hi": "कमल का फूल"}, {"key": "C", "en": "Pasha (Noose)", "hi": "पाश"}, {"key": "D", "en": "Trishul (Trident)", "hi": "त्रिशूल"}]','D');
INSERT INTO knowledge_quiz VALUES(3967,'Which avatar of Vishnu lifted the earth from the ocean?','विष्णु के किस अवतार ने पृथ्वी को समुद्र से उठाया?','[{"key": "A", "en": "Kurma", "hi": "कूर्म"}, {"key": "B", "en": "Varaha", "hi": "वराह"}, {"key": "C", "en": "Matsya", "hi": "मत्स्य"}, {"key": "D", "en": "Vamana", "hi": "वामन"}]','B');
INSERT INTO knowledge_quiz VALUES(3968,'Which avatar of Vishnu took the form of a fish?','विष्णु का मत्स्य अवतार किस रूप में था?','[{"key": "A", "en": "Fish", "hi": "मछली"}, {"key": "B", "en": "Tortoise", "hi": "कछुआ"}, {"key": "C", "en": "Boar", "hi": "वराह"}, {"key": "D", "en": "Lion", "hi": "सिंह"}]','A');
INSERT INTO knowledge_quiz VALUES(3969,'Who was the first avatar of Vishnu?','विष्णु का प्रथम अवतार कौन था?','[{"key": "A", "en": "Kurma", "hi": "कूर्म"}, {"key": "B", "en": "Matsya", "hi": "मत्स्य"}, {"key": "C", "en": "Varaha", "hi": "वराह"}, {"key": "D", "en": "Vamana", "hi": "वामन"}]','B');
INSERT INTO knowledge_quiz VALUES(3970,'Who was the mother of Lakshmana in the Ramayana?','रामायण में लक्ष्मण की माता कौन थीं?','[{"key": "A", "en": "Kaushalya", "hi": "कौशल्या"}, {"key": "B", "en": "Kaikeyi", "hi": "कैकेयी"}, {"key": "C", "en": "Sumitra", "hi": "सुमित्रा"}, {"key": "D", "en": "Urmila", "hi": "उर्मिला"}]','C');
INSERT INTO knowledge_quiz VALUES(3971,'Who was the brother of Ravana?','रावण के भाई कौन थे?','[{"key": "A", "en": "Vibhishana", "hi": "विभीषण"}, {"key": "B", "en": "Sugriva", "hi": "सुग्रीव"}, {"key": "C", "en": "Angada", "hi": "अंगद"}, {"key": "D", "en": "Jambavan", "hi": "जाम्बवान"}]','A');
INSERT INTO knowledge_quiz VALUES(3972,'Who was the brother of Kartikeya?','कार्तिकेय के भाई कौन थे?','[{"key": "A", "en": "Ganesha", "hi": "गणेश"}, {"key": "B", "en": "Indra", "hi": "इन्द्र"}, {"key": "C", "en": "Agni", "hi": "अग्नि"}, {"key": "D", "en": "Surya", "hi": "सूर्य"}]','A');
INSERT INTO knowledge_quiz VALUES(3973,'Who was the childhood friend and beloved of Krishna?','कृष्ण की बाल सखी और प्रेयसी कौन थीं?','[{"key": "A", "en": "Rukmini", "hi": "रुक्मिणी"}, {"key": "B", "en": "Satyabhama", "hi": "सत्यभामा"}, {"key": "C", "en": "Radha", "hi": "राधा"}, {"key": "D", "en": "Draupadi", "hi": "द्रौपदी"}]','C');
INSERT INTO knowledge_quiz VALUES(3974,'Who was the main queen of Lord Krishna?','भगवान कृष्ण की मुख्य रानी कौन थीं?','[{"key": "A", "en": "Radha", "hi": "राधा"}, {"key": "B", "en": "Rukmini", "hi": "रुक्मिणी"}, {"key": "C", "en": "Satyabhama", "hi": "सत्यभामा"}, {"key": "D", "en": "Jambavati", "hi": "जाम्बवती"}]','B');
INSERT INTO knowledge_quiz VALUES(3975,'Who was the enemy king defeated by Krishna in Mathura?','मथुरा में कृष्ण ने किस शत्रु राजा का वध किया?','[{"key": "A", "en": "Jarasandha", "hi": "जरासंध"}, {"key": "B", "en": "Kamsa", "hi": "कंस"}, {"key": "C", "en": "Shishupala", "hi": "शिशुपाल"}, {"key": "D", "en": "Dantavakra", "hi": "दंतवक्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3976,'Who was the maternal uncle of Lord Krishna?','भगवान कृष्ण के मामा कौन थे?','[{"key": "A", "en": "Jarasandha", "hi": "जरासंध"}, {"key": "B", "en": "Kamsa", "hi": "कंस"}, {"key": "C", "en": "Ugrasena", "hi": "उग्रसेन"}, {"key": "D", "en": "Akrura", "hi": "अक्रूर"}]','B');
INSERT INTO knowledge_quiz VALUES(3977,'Who was the king of Magadha and enemy of Krishna?','मगध का राजा और कृष्ण का शत्रु कौन था?','[{"key": "A", "en": "Shishupala", "hi": "शिशुपाल"}, {"key": "B", "en": "Jarasandha", "hi": "जरासंध"}, {"key": "C", "en": "Kamsa", "hi": "कंस"}, {"key": "D", "en": "Salva", "hi": "शाल्व"}]','B');
INSERT INTO knowledge_quiz VALUES(3978,'Who was beheaded by Krishna during Rajasuya Yajna?','राजसूय यज्ञ में कृष्ण ने किसका वध किया?','[{"key": "A", "en": "Jarasandha", "hi": "जरासंध"}, {"key": "B", "en": "Shishupala", "hi": "शिशुपाल"}, {"key": "C", "en": "Kamsa", "hi": "कंस"}, {"key": "D", "en": "Dantavakra", "hi": "दंतवक्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3979,'Who sculpted the main Lingam worshipped in the Rameswaram Temple?','रामेश्वरम मंदिर में पूजे जाने वाले मुख्य लिंग को किसने बनाया था?','[{"key": "A", "en": "Lord Rama", "hi": "भगवान राम"}, {"key": "B", "en": "Goddess Sita", "hi": "देवी सीता"}, {"key": "C", "en": "Lord Hanuman", "hi": "भगवान हनुमान"}, {"key": "D", "en": "Sage Vishwamitra", "hi": "ऋषि विश्वामित्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3980,'Who was the friend of Krishna and ruler of Hastinapura?','कृष्ण के मित्र और हस्तिनापुर के राजा कौन थे?','[{"key": "A", "en": "Yudhishthira", "hi": "युधिष्ठिर"}, {"key": "B", "en": "Arjuna", "hi": "अर्जुन"}, {"key": "C", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "D", "en": "Bhima", "hi": "भीम"}]','A');
INSERT INTO knowledge_quiz VALUES(3981,'Who was the eldest of the Kauravas?','कौरवों में सबसे बड़ा कौन था?','[{"key": "A", "en": "Dushasana", "hi": "दुःशासन"}, {"key": "B", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "C", "en": "Vikarna", "hi": "विकर्ण"}, {"key": "D", "en": "Chitrasena", "hi": "चित्रसेन"}]','B');
INSERT INTO knowledge_quiz VALUES(3982,'Who humiliated Draupadi in the Kaurava court?','कौरव सभा में द्रौपदी का अपमान किसने किया?','[{"key": "A", "en": "Karna", "hi": "कर्ण"}, {"key": "B", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "C", "en": "Dushasana", "hi": "दुःशासन"}, {"key": "D", "en": "Shakuni", "hi": "शकुनि"}]','C');
INSERT INTO knowledge_quiz VALUES(3983,'Who was the mastermind behind the dice game?','पासों के खेल का षड्यंत्रकर्ता कौन था?','[{"key": "A", "en": "Duryodhana", "hi": "दुर्योधन"}, {"key": "B", "en": "Shakuni", "hi": "शकुनि"}, {"key": "C", "en": "Karna", "hi": "कर्ण"}, {"key": "D", "en": "Bhishma", "hi": "भीष्म"}]','B');
INSERT INTO knowledge_quiz VALUES(3984,'How many days did the Kurukshetra war last?','कुरुक्षेत्र युद्ध कितने दिनों तक चला?','[{"key": "A", "en": "10", "hi": "10"}, {"key": "B", "en": "12", "hi": "12"}, {"key": "C", "en": "18", "hi": "18"}, {"key": "D", "en": "21", "hi": "21"}]','C');
INSERT INTO knowledge_quiz VALUES(3985,'Who narrated the Mahabharata to King Janamejaya?','राजा जनमेजय को महाभारत किसने सुनाई?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Vaishampayana", "hi": "वैशंपायन"}, {"key": "C", "en": "Sauti", "hi": "सौति"}, {"key": "D", "en": "Narada", "hi": "नारद"}]','B');
INSERT INTO knowledge_quiz VALUES(3986,'Who was the son of Arjuna and Subhadra?','अर्जुन और सुभद्रा का पुत्र कौन था?','[{"key": "A", "en": "Ghatotkacha", "hi": "घटोत्कच"}, {"key": "B", "en": "Abhimanyu", "hi": "अभिमन्यु"}, {"key": "C", "en": "Parikshit", "hi": "परीक्षित"}, {"key": "D", "en": "Pradyumna", "hi": "प्रद्युम्न"}]','B');
INSERT INTO knowledge_quiz VALUES(3987,'Who was the grandson of Arjuna and son of Abhimanyu?','अर्जुन का पौत्र और अभिमन्यु का पुत्र कौन था?','[{"key": "A", "en": "Parikshit", "hi": "परीक्षित"}, {"key": "B", "en": "Janamejaya", "hi": "जनमेजय"}, {"key": "C", "en": "Uttara", "hi": "उत्तरा"}, {"key": "D", "en": "Pradyumna", "hi": "प्रद्युम्न"}]','A');
INSERT INTO knowledge_quiz VALUES(3988,'Who cursed King Parikshit to die by snake bite?','राजा परीक्षित को सर्पदंश से मृत्यु का शाप किसने दिया?','[{"key": "A", "en": "Shukacharya", "hi": "शुकाचार्य"}, {"key": "B", "en": "Shringi", "hi": "शृंगी"}, {"key": "C", "en": "Narada", "hi": "नारद"}, {"key": "D", "en": "Vashistha", "hi": "वशिष्ठ"}]','B');
INSERT INTO knowledge_quiz VALUES(3989,'Who narrated the Bhagavata Purana to King Parikshit?','राजा परीक्षित को भागवत पुराण किसने सुनाया?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Shukadeva", "hi": "शुकदेव"}, {"key": "C", "en": "Vyasa", "hi": "व्यास"}, {"key": "D", "en": "Sauti", "hi": "सौति"}]','B');
INSERT INTO knowledge_quiz VALUES(3990,'Who was the son of Sage Vyasa?','ऋषि व्यास के पुत्र कौन थे?','[{"key": "A", "en": "Shukadeva", "hi": "शुकदेव"}, {"key": "B", "en": "Parashara", "hi": "पराशर"}, {"key": "C", "en": "Satyavati", "hi": "सत्यवती"}, {"key": "D", "en": "Drona", "hi": "द्रोण"}]','A');
INSERT INTO knowledge_quiz VALUES(3991,'Sage Jamadagni, one of the Saptarishis, was the father of which famous avatar of Lord Vishnu?','सप्तर्षियों में से एक, ऋषि जमदग्नि, भगवान विष्णु के किस प्रसिद्ध अवतार के पिता थे?','[{"key": "A", "en": "Lord Rama", "hi": "भगवान राम"}, {"key": "B", "en": "Lord Krishna", "hi": "भगवान कृष्ण"}, {"key": "C", "en": "Lord Parashurama", "hi": "भगवान परशुराम"}, {"key": "D", "en": "Lord Vamana", "hi": "भगवान वामन"}]','C');
INSERT INTO knowledge_quiz VALUES(3992,'How many Vedas are there?','वेदों की संख्या कितनी है?','[{"key": "A", "en": "2", "hi": "2"}, {"key": "B", "en": "3", "hi": "3"}, {"key": "C", "en": "4", "hi": "4"}, {"key": "D", "en": "5", "hi": "5"}]','C');
INSERT INTO knowledge_quiz VALUES(3993,'Which Veda is the oldest?','सबसे प्राचीन वेद कौन सा है?','[{"key": "A", "en": "Yajur Veda", "hi": "यजुर्वेद"}, {"key": "B", "en": "Rig Veda", "hi": "ऋग्वेद"}, {"key": "C", "en": "Sama Veda", "hi": "सामवेद"}, {"key": "D", "en": "Atharva Veda", "hi": "अथर्ववेद"}]','B');
INSERT INTO knowledge_quiz VALUES(3994,'Who is the sage associated with the Ramayana?','रामायण से संबंधित ऋषि कौन हैं?','[{"key": "A", "en": "Vyasa", "hi": "व्यास"}, {"key": "B", "en": "Valmiki", "hi": "वाल्मीकि"}, {"key": "C", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "D", "en": "Narada", "hi": "नारद"}]','B');
INSERT INTO knowledge_quiz VALUES(3995,'Who is the sage associated with devotion (Bhakti)?','भक्ति परंपरा से जुड़े प्रमुख ऋषि कौन हैं?','[{"key": "A", "en": "Narada", "hi": "नारद"}, {"key": "B", "en": "Agastya", "hi": "अगस्त्य"}, {"key": "C", "en": "Vashistha", "hi": "वशिष्ठ"}, {"key": "D", "en": "Kapila", "hi": "कपिल"}]','A');
INSERT INTO knowledge_quiz VALUES(3996,'Who is known as the divine messenger among gods?','देवताओं का दूत किसे कहा जाता है?','[{"key": "A", "en": "Agni", "hi": "अग्नि"}, {"key": "B", "en": "Narada", "hi": "नारद"}, {"key": "C", "en": "Vayu", "hi": "वायु"}, {"key": "D", "en": "Indra", "hi": "इंद्र"}]','B');
INSERT INTO knowledge_quiz VALUES(3997,'Who is the goddess of strength and power?','शक्ति और बल की देवी कौन हैं?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Durga", "hi": "दुर्गा"}, {"key": "C", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','B');
INSERT INTO knowledge_quiz VALUES(3998,'Who is the fierce form of Goddess Parvati?','देवी पार्वती का उग्र रूप कौन सा है?','[{"key": "A", "en": "Lakshmi", "hi": "लक्ष्मी"}, {"key": "B", "en": "Saraswati", "hi": "सरस्वती"}, {"key": "C", "en": "Kali", "hi": "काली"}, {"key": "D", "en": "Ganga", "hi": "गंगा"}]','C');
INSERT INTO knowledge_quiz VALUES(3999,'The ''Narasimha Temple'' in Joshimath is the winter seat for which Dham?','जोशीमठ में ''नृसिंह मंदिर'' किस धाम की शीतकालीन गद्दी है?','[{"key": "A", "en": "Kedarnath", "hi": "केदारनाथ"}, {"key": "B", "en": "Gangotri", "hi": "गंगोत्री"}, {"key": "C", "en": "Badrinath", "hi": "बद्रीनाथ"}, {"key": "D", "en": "Yamunotri", "hi": "यमुनोत्री"}]','C');
INSERT INTO knowledge_quiz VALUES(4000,'The inner roof of the Siddhivinayak temple''s sanctum sanctorum is plated with which precious metal?','सिद्धिविनायक मंदिर के गर्भगृह की आंतरिक छत किस बहुमूल्य धातु से मढ़ी हुई है?','[{"key": "A", "en": "Silver", "hi": "चांदी"}, {"key": "B", "en": "Copper", "hi": "तांबा"}, {"key": "C", "en": "Gold", "hi": "सोना"}, {"key": "D", "en": "Platinum", "hi": "प्लेटिनम"}]','C');
INSERT INTO clue_riddles VALUES(1,'HAMSA','["I appeared in the form of a graceful white bird", "I am a lesser-known incarnation of Vishnu", "I symbolize purity, knowledge, and discrimination", "I taught the essence of Yoga and the Vedas to the sons of Lord Brahma", "I am the Sanskrit word for swan"]','["मैं एक सुंदर सफेद पक्षी के रूप में प्रकट हुआ", "मैं विष्णु का एक कम ज्ञात अवतार हूँ", "मैं पवित्रता, ज्ञान और विवेक का प्रतीक हूँ", "मैंने ब्रह्मा जी के मानस पुत्रों को योग और वेदों का परम सार सिखाया था", "मैं स्वान का संस्कृत और हिंदी शब्द हूँ"]');
INSERT INTO clue_riddles VALUES(2,'ASTIKA','["I am a wise sage who intervened to stop a great sacrificial ritual", "I was born to a sage and a serpent lineage", "I played a key role during King Janamejaya’s serpent sacrifice", "I am the sage who protected the Nagas", "My spelling is similar to a word meaning ''one who believes in God''"]','["मैं एक बुद्धिमान ऋषि हूँ जिसने एक महान यज्ञ को रोकने के लिए हस्तक्षेप किया", "मेरा जन्म एक ऋषि और नाग वंश से हुआ था", "मैंने राजा जनमेजय के सर्प यज्ञ के समय महत्वपूर्ण भूमिका निभाई", "मैं वह ऋषि हूँ जिसने नागों की रक्षा की", "मेरी स्पेलिंग उस शब्द से मिलती-जुलती है जिसका मतलब है ''भगवान को मानने वाला''"]');
INSERT INTO clue_riddles VALUES(3,'PRALAYA','["I signify the dissolution of the universe at the end of a cosmic cycle", "In me, all creation returns to its unmanifest state", "I occur after vast periods of time measured in yugas and kalpas", "I am often associated with destruction brought by divine forces", "I mark the end before a new creation begins"]','["मैं ब्रह्मांड के एक चक्र के अंत में होने वाला पूर्ण विलय हूँ", "मेरे भीतर समस्त सृष्टि अव्यक्त रूप में लौट जाती है", "मैं युगों और कल्पों के लंबे समय के बाद घटित होता हूँ", "मेरा संबंध दिव्य शक्तियों द्वारा होने वाले संहार से जोड़ा जाता है", "मैं अंत का प्रतीक हूँ जिसके बाद नई सृष्टि आरंभ होती है"]');
INSERT INTO clue_riddles VALUES(4,'RAMA','["I am the prince of Ayodhya", "I lived in exile for fourteen years", "I broke the mighty bow of Shiva", "My wife was abducted by a demon king", "I built a bridge across the sea"]','["मैं अयोध्या का राजकुमार हूँ", "मैंने चौदह वर्ष वनवास में बिताए", "मैंने शिव के महान धनुष को तोड़ा", "मेरी पत्नी का एक राक्षस राजा ने अपहरण किया", "मैंने समुद्र पर एक सेतु बनाया"]');
INSERT INTO clue_riddles VALUES(5,'SVARGA','["I am the celestial realm of pleasure and reward", "I am ruled by Indra, the king of gods", "Souls come to me after performing good deeds", "I am home to legendary treasures like the Kamadhenu and the Kalpavriksha", "I am the third of the seven upper worlds in Hindu cosmology"]','["मैं सुख और पुण्य का स्वर्गीय लोक हूँ", "मेरा शासन देवताओं के राजा इंद्र करते हैं", "पुण्य कर्म करने वाले जीव मेरे पास आते हैं", "मैं कामधेनु और कल्पवृक्ष जैसे पौराणिक रत्नों का निवास स्थान हूँ", "मैं हिंदू ब्रह्मांड विज्ञान में सात उच्च लोकों (व्याहृति) में से तीसरा लोक हूँ"]');
INSERT INTO clue_riddles VALUES(6,'KHAJURAHO','["I was hidden by forests for centuries before being rediscovered", "My temples celebrate the beauty of human form in stone", "Only about twenty of my original eighty temples survive", "The Chandela dynasty built me over two centuries", "I am the UNESCO temple complex in Madhya Pradesh"]','["मैं सदियों तक जंगलों में छिपा रहा फिर पुनः खोजा गया", "मेरे मंदिर पत्थर में मानव रूप की सुंदरता का उत्सव मनाते हैं", "मेरे मूल अस्सी मंदिरों में से केवल बीस के लगभग बचे हैं", "चंदेल वंश ने मुझे दो शताब्दियों में बनाया", "मैं मध्य प्रदेश में स्थित यूनेस्को विश्व धरोहर स्थल हूँ"]');
INSERT INTO clue_riddles VALUES(7,'DRAUPADI','["I was born from a sacred fire", "I married five brothers", "I was humiliated in a royal court", "Krishna saved my honor", "I am the queen of Indraprastha"]','["मेरा जन्म पवित्र अग्नि से हुआ", "मैंने पाँच भाइयों से विवाह किया", "राजसभा में मेरा अपमान हुआ", "कृष्ण ने मेरी लाज बचाई", "मैं इंद्रप्रस्थ की रानी हूँ"]');
INSERT INTO clue_riddles VALUES(8,'AHINSA','["I represent a principle where even intention avoids causing harm to any living being", "I extend beyond actions to include thoughts and words rooted in compassion", "Great spiritual leaders upheld me as a path to truth and inner purity", "I encourage kindness and respect toward all forms of life", "I simply mean non-violence"]','["मैं वह सिद्धांत हूँ जिसमें किसी भी जीव को हानि पहुँचाने का विचार भी त्याग दिया जाता है", "मैं कर्म के साथ-साथ विचार और वाणी में भी करुणा को शामिल करता हूँ", "महान आध्यात्मिक नेताओं ने मुझे सत्य और शुद्धता का मार्ग माना है", "मैं सभी जीवों के प्रति दया और सम्मान का संदेश देता हूँ", "मैं सरल शब्दों में किसी को भी हानि न पहुँचाने का भाव हूँ।"]');
INSERT INTO clue_riddles VALUES(9,'HAYAGRIVA','["I rescued the stolen Vedas from the depths of the sea", "I am worshipped before beginning any study", "I have the head of a horse on a human body", "I am Vishnu''s avatar as the god of knowledge", "I have the same name as the demon who was killed by Matsya Avatar of Vishnu"]','["मैंने समुद्र की गहराइयों से चुराए गए वेदों को बचाया", "किसी भी अध्ययन से पहले मेरी पूजा की जाती है", "मानव शरीर पर मेरा सिर अश्व का है", "मैं ज्ञान के देवता के रूप में विष्णु का अवतार हूँ", "मेरा नाम उस असुर के समान भी है, जिसका वध भगवान विष्णु के मत्स्य अवतार ने किया था।"]');
INSERT INTO clue_riddles VALUES(10,'SURYA','["I ride a chariot pulled by seven horses", "Without me, life on earth would perish", "I am one of the Navagrahas worshipped in Vedic tradition", "I am the father of Karna, the great warrior of the Mahabharata", "I am the god who rises every morning in the east"]','["मैं सात घोड़ों के रथ पर सवार होता हूँ", "मेरे बिना पृथ्वी पर जीवन समाप्त हो जाएगा", "मैं वैदिक परंपरा में नवग्रहों में से एक हूँ", "मैं कर्ण का पिता हूँ, जो महाभारत के महान योद्धा थे", "मैं वह देवता हूँ जो प्रतिदिन पूर्व में उदय होता है"]');
INSERT INTO clue_riddles VALUES(11,'ADITI','["I am the boundless mother associated with the infinite and the cosmic order", "I am revered as the divine mother of the Adityas, including Surya", "My name signifies freedom, unbroken and limitless nature", "I am often invoked as a protector and nurturer of all beings", "I hold a central place among the earliest goddesses of the Vedas"]','["मैं अनंतता और ब्रह्मांडीय व्यवस्था से जुड़ी एक असीम माता हूँ", "मैं आदित्यों की दिव्य माता हूँ, जिनमें सूर्य भी शामिल हैं", "मेरा नाम ही स्वतंत्रता और असीमितता का प्रतीक है", "मुझे सभी प्राणियों की रक्षक और पालन करने वाली माना जाता है", "मैं वेदों की प्राचीन और प्रमुख देवियों में से एक हूँ"]');
INSERT INTO clue_riddles VALUES(12,'GANDHARI','["I blindfolded myself for life in Mahabharata", "My pregnancy lasted for two years", "I cursed the one who killed my sons", "My gaze could have made my son invincible", "I am the mother of a hundred sons"]','["मैंने महाभारत में जीवन भर के लिए अपनी आँखों पर पट्टी बाँधी", "मेरी गर्भावस्था दो वर्ष तक रही", "मैंने अपने पुत्रों के हत्यारे को श्राप दिया", "मेरी दृष्टि मेरे पुत्र को अजेय बना सकती थी", "मैं सौ पुत्रों की माता हूँ"]');
INSERT INTO clue_riddles VALUES(13,'VISHNU','["I rest on a serpent in the cosmic ocean", "I have taken ten avatars on earth", "I hold a discus and a conch", "I am the preserver of the universe", "Garuda is my mount"]','["मैं क्षीरसागर में शेषनाग पर विश्राम करता हूँ", "मैंने पृथ्वी पर दस अवतार लिए हैं", "मेरे हाथ में चक्र और शंख हैं", "मैं सृष्टि का पालनकर्ता हूँ", "गरुड़ मेरा वाहन है"]');
INSERT INTO clue_riddles VALUES(14,'NAKUL','["I am a character in Mahabharata", "I am a master of horse training and Ayurveda", "My twin and I were born from the Ashwini gods", "I was one of the five who went into exile", "I am the fourth Pandava brother"]','["मैं महाभारत का एक पात्र हूँ", "मैं अश्व प्रशिक्षण और आयुर्वेद का विशेषज्ञ हूँ", "मेरा जन्म मेरे जुड़वाँ के साथ अश्विनी कुमारों से हुआ", "मैं वनवास में गए पाँच में से एक था", "मैं चौथा पांडव भाई हूँ"]');
INSERT INTO clue_riddles VALUES(15,'ANGKOR','["I am the world''s largest religious monument", "I was originally built as a Vishnu temple", "My towers represent the peaks of Mount Meru", "I appear on the flag of a Southeast Asian nation", "I am the great temple of Cambodia"]','["मैं दुनिया का सबसे बड़ा धार्मिक स्मारक हूँ", "मूल रूप से मेरा निर्माण विष्णु मंदिर के रूप में हुआ", "मेरे शिखर मेरु पर्वत की चोटियों का प्रतिनिधित्व करते हैं", "मैं एक दक्षिण-पूर्व एशियाई देश के झंडे पर दिखाई देता हूँ", "मैं कंबोडिया का महान मंदिर हूँ"]');
INSERT INTO clue_riddles VALUES(16,'SAMPATI','["I am a character in Ramayana", "I lost my wings trying to protect my younger brother", "I spotted a captive princess across a vast ocean", "My vision helped a monkey army find their goal", "I am the elder brother of Jatayu"]','["मैं रामायण का एक पात्र हूँ", "मैंने अपने छोटे भाई की रक्षा करते हुए अपने पंख खो दिए", "मैंने विशाल समुद्र के पार एक बंदी राजकुमारी को देखा", "मेरी दृष्टि ने वानर सेना को उनका लक्ष्य खोजने में सहायता की", "मैं जटायु का बड़ा भाई हूँ"]');
INSERT INTO clue_riddles VALUES(17,'NARAD','["I travel across all three worlds", "I sometimes create mischief for a greater good", "I always chant ''Narayan Narayan''", "I carry a veena called Mahati", "I am known as the divine messenger"]','["मैं तीनों लोकों में विचरण करता हूँ", "मैं कभी-कभी बड़े भले के लिए शरारत करता हूँ", "मैं सदा ''नारायण नारायण'' का जाप करता हूँ", "मेरे पास ''महती'' नामक वीणा है", "मैं देव दूत के रूप में जाना जाता हूँ"]');
INSERT INTO clue_riddles VALUES(18,'PARVATI','["I performed severe penance to win my husband", "I am the mother of Ganesha and Kartikeya", "I am the daughter of the mountain king", "I am the gentle form of Shakti", "My husband meditates on Mount Kailash"]','["मैंने अपने पति को पाने के लिए कठोर तपस्या की", "मैं गणेश और कार्तिकेय की माता हूँ", "मैं पर्वतराज की पुत्री हूँ", "मैं शक्ति का सौम्य रूप हूँ", "मेरे पति कैलाश पर्वत पर ध्यान करते हैं"]');
INSERT INTO clue_riddles VALUES(19,'BHIMA','["I am the strongest of five brothers", "I killed a demon in the forest of Ekachakra", "I defeated a hundred brothers in battle", "Wind god Vayu is my father", "I once fought a demon to get lotus flowers"]','["मैं पाँच भाइयों में सबसे बलवान हूँ", "मैंने एकचक्र के वन में एक राक्षस का वध किया", "मैंने सौ भाइयों को युद्ध में पराजित किया", "वायुदेव मेरे पिता हैं", "मैंने कमल लाने के लिए एक राक्षस से युद्ध किया"]');
INSERT INTO clue_riddles VALUES(20,'CONCH','["I am a sacred object whose sound is believed to purify the surroundings", "My origin is linked to the depths of the ocean and divine symbolism", "I am often blown at the beginning of rituals and battles", "My resonant sound is believed to represent the primordial sound ''Om'' and ward off negative energy", "I am held by deities like Vishnu and used in auspicious ceremonies"]','["मैं एक पवित्र वस्तु हूँ जिसकी ध्वनि वातावरण को शुद्ध करती है", "मेरा संबंध समुद्र की गहराइयों और दिव्यता से है", "मुझे अनुष्ठानों और युद्ध की शुरुआत में बजाया जाता है", "माना जाता है कि मेरी गूँजती ध्वनि आदि ध्वनि ''ओम'' का प्रतिनिधित्व करती है और नकारात्मक ऊर्जा को दूर करती है", "मुझे विष्णु जैसे देवता धारण करते हैं और शुभ कार्यों में उपयोग करते हैं"]');
INSERT INTO clue_riddles VALUES(21,'LAKSHMAN','["I followed my brother into fourteen years of exile", "I drew a protective line around a hut", "I cut the nose of a demoness", "I was struck by a powerful weapon and fell unconscious", "A magical herb brought me back to life"]','["मैंने अपने भाई के साथ चौदह वर्ष का वनवास किया", "मैंने कुटिया के चारों ओर एक रक्षा रेखा खींची", "मैंने एक राक्षसी की नाक काटी", "मैं एक शक्तिशाली अस्त्र से मूर्छित हो गया", "एक जादुई जड़ी-बूटी ने मुझे पुनर्जीवित किया"]');
INSERT INTO clue_riddles VALUES(22,'INDRA','["I am the king of all the gods", "I wield a thunderbolt as my weapon", "I ride a white elephant named Airavata", "My abode is called Amaravati", "I once fought with Krishna over a mountain"]','["मैं सभी देवताओं का राजा हूँ", "वज्र मेरा अस्त्र है", "मेरा वाहन ऐरावत नामक श्वेत हाथी है", "मेरा निवास अमरावती कहलाता है", "मैंने एक बार कृष्ण से एक पर्वत पर युद्ध किया"]');
INSERT INTO clue_riddles VALUES(23,'SHUKLA','["I represent brightness and purity in Sanskrit", "I denote the fortnight when the moon grows from new to full", "Festivals like Navratri and Ekadashi often fall during my phase", "I am associated with light, clarity, and positivity", "I stand opposite to the darker lunar phase called Krishna"]','["मैं संस्कृत में उज्ज्वलता और पवित्रता का प्रतीक हूँ", "मैं चंद्रमा के बढ़ते हुए चरण को दर्शाता हूँ", "नवरात्रि और एकादशी जैसे कई पर्व मेरे दौरान आते हैं", "मैं प्रकाश, स्पष्टता और सकारात्मकता से जुड़ा हूँ", "मैं कृष्ण नामक अंधकारमय पक्ष के विपरीत हूँ"]');
INSERT INTO clue_riddles VALUES(24,'KRISHNA','["I am the divine charioteer", "I lifted a mountain on my little finger", "I played the flute in Vrindavan", "Butter was my favorite treat as a child", "I revealed the Bhagavad Gita on the battlefield"]','["मैं दिव्य सारथी हूँ", "मैंने अपनी छोटी उंगली पर पर्वत उठाया", "मैंने वृंदावन में बांसुरी बजाई", "बचपन में मक्खन मेरा प्रिय भोजन था", "मैंने युद्धभूमि पर भगवद्गीता का ज्ञान दिया"]');
INSERT INTO clue_riddles VALUES(25,'EKLAVYA','["I learned archery by watching from a distance", "I made a clay idol of my guru", "I gave my thumb as guru dakshina", "I was a tribal prince", "My devotion to my teacher is unmatched"]','["मैंने दूर से देखकर धनुर्विद्या सीखी", "मैंने अपने गुरु की मिट्टी की मूर्ति बनाई", "मैंने गुरु दक्षिणा में अपना अंगूठा दिया", "मैं एक आदिवासी राजकुमार था", "मेरा गुरु के प्रति समर्पण अद्वितीय है"]');
INSERT INTO clue_riddles VALUES(26,'SWASTIK','["I am a symbol of auspiciousness and good fortune", "I represent harmony and positivity", "I am drawn at the start of rituals", "I bring blessings and prosperity", "I am a sacred Hindu symbol"]','["मैं शुभता और सौभाग्य का प्रतीक हूँ", "मैं संतुलन और सकारात्मकता दर्शाता हूँ", "मुझे अनुष्ठानों की शुरुआत में बनाया जाता है", "मैं आशीर्वाद और समृद्धि लाता हूँ", "मैं एक पवित्र हिंदू चिन्ह हूँ"]');
INSERT INTO clue_riddles VALUES(27,'SHIVA','["I drank poison to save the world", "A river flows from my hair", "My third eye can destroy anything", "I wear a crescent moon on my head", "I sit in meditation on Mount Kailash"]','["मैंने संसार को बचाने के लिए विष पिया", "मेरे बालों से एक नदी बहती है", "मेरा तीसरा नेत्र सब कुछ भस्म कर सकता है", "मेरे मस्तक पर अर्धचंद्र सुशोभित है", "मैं कैलाश पर्वत पर ध्यान में बैठता हूँ"]');
INSERT INTO clue_riddles VALUES(28,'BAISAKHI','["I am a festival that marks the joyous harvest of the rabi crops", "My day witnessed the formation of a warrior community by a revered guru", "I am deeply significant in Punjab with vibrant dances and fairs", "I coincide with the beginning of a new solar year in North India", "I am a major festival celebrated in April"]','["मैं रबी फसलों की कटाई का उत्सव हूँ", "मेरे दिन एक गुरु ने एक वीर समुदाय की स्थापना की थी", "मैं पंजाब में नृत्य और मेलों के साथ बड़े उत्साह से मनाया जाता हूँ", "मैं उत्तर भारत में सौर नववर्ष की शुरुआत के साथ आता हूँ", "मैं अप्रैल में मनाया जाने वाला प्रमुख पर्व हूँ"]');
INSERT INTO clue_riddles VALUES(29,'VALMIKI','["I composed the first epic poem", "I was transformed by chanting God''s name", "An ant hill grew around me during meditation", "I sheltered Sita in my ashram", "I am known as the Adi Kavi"]','["मैंने पहले महाकाव्य की रचना की", "भगवान के नाम के जाप से मेरा रूपांतरण हुआ", "तपस्या के दौरान मेरे चारों ओर दीमक का घर बन गया", "मैंने सीता को अपने आश्रम में आश्रय दिया", "मैं आदि कवि के रूप में जाना जाता हूँ"]');
INSERT INTO clue_riddles VALUES(30,'KARTIKEYA','["I am the god of war", "I ride a peacock", "I defeated the demon Tarakasura", "I am the son of Shiva and Parvati", "I have six faces and twelve arms"]','["मैं युद्ध का देवता हूँ", "मेरा वाहन मयूर है", "मैंने तारकासुर राक्षस का वध किया", "मैं शिव और पार्वती का पुत्र हूँ", "मेरे छह मुख और बारह भुजाएँ हैं"]');
INSERT INTO clue_riddles VALUES(31,'ADIPARVA','["I am the first book of a great Indian epic", "I narrate the origins of a legendary dynasty", "My narrative includes the Samudra Manthan", "I introduce key characters like the Pandavas and Kauravas", "I lay the foundation for the events of the Mahabharata"]','["मैं एक महान भारतीय महाकाव्य का पहला पर्व हूँ", "मैं एक प्रसिद्ध वंश की उत्पत्ति का वर्णन करता हूँ", "मेरी कथाओं में समुद्र मंथन की कथा शामिल है", "मैं पांडवों और कौरवों जैसे प्रमुख पात्रों का परिचय देता हूँ", "मैं महाभारत की घटनाओं की नींव रखता हूँ"]');
INSERT INTO clue_riddles VALUES(32,'GANPATI','["I love modaks and laddoos", "One of my tusks is broken", "I wrote a great epic while listening continuously", "I am the son of Shiva and Parvati", "I am also known as Ganesha"]','["मुझे मोदक और लड्डू बहुत प्रिय हैं", "मेरी एक दांत टूटी हुई है", "मैंने एक महान ग्रंथ को सुनते-सुनते लिखा", "मैं शिव और पार्वती का पुत्र हूँ", "मुझे गणेश के नाम से भी जाना जाता है"]');
INSERT INTO clue_riddles VALUES(33,'RADHA','["I am the embodiment of divine love", "My beloved played the flute for me", "I danced the Raas Leela under moonlight", "I am inseparable from the lord of Vrindavan", "My name is always spoken before Krishna''s"]','["मैं दिव्य प्रेम का साकार रूप हूँ", "मेरे प्रियतम ने मेरे लिए बांसुरी बजाई", "मैंने चांदनी रात में रासलीला रची", "मैं वृंदावन के स्वामी से अभिन्न हूँ", "मेरा नाम कृष्ण से पहले लिया जाता है"]');
INSERT INTO clue_riddles VALUES(34,'ABHIMANYU','["I learned warfare while still in the womb", "I entered a deadly military formation alone", "I could not exit the trap I entered in Kurukshetra", "I was an incarnation of Varchas, son of Chandra", "I am the brave son of Arjuna"]','["मैंने गर्भ में रहते हुए युद्ध कला सीखी", "मैं अकेले एक घातक व्यूह में घुसा", "मैं कुरुक्षेत्र में जिस जाल में घुसा उससे बाहर नहीं निकल सका", "मैं चंद्र देव के पुत्र वर्चस का अवतार था", "मैं अर्जुन का वीर पुत्र हूँ"]');
INSERT INTO clue_riddles VALUES(35,'AMARAVATI','["I am the magnificent capital of the celestial king, Indra", "I am located in the realm of Svarga", "Celestial dancers like Urvashi and Rambha perform in my halls", "I also share my name with a city on the banks of the Krishna River", "I have the same name as the capital city of Andhra Pradesh"]','["मैं देवराज की भव्य राजधानी हूँ", "मैं स्वर्ग लोक में स्थित हूँ", "उर्वशी और रंभा जैसी अप्सराएँ मेरे प्रांगण में नृत्य करती हैं", "मेरा नाम कृष्णा नदी के तट पर स्थित एक शहर से भी जुड़ा है", "मेरा नाम आंध्र प्रदेश की राजधानी के साथ समान है"]');
INSERT INTO clue_riddles VALUES(36,'PRAMBANAN','["I am the largest Hindu temple in Southeast Asia", "I am dedicated to the Trimurti of Brahma, Vishnu, and Shiva", "I was built in the ninth century on the island of Java", "I was abandoned and collapsed in an earthquake centuries ago", "I am the great Hindu temple complex in Indonesia"]','["मैं दक्षिण-पूर्व एशिया का सबसे बड़ा हिंदू मंदिर हूँ", "मैं ब्रह्मा, विष्णु और शिव की त्रिमूर्ति को समर्पित हूँ", "मेरा निर्माण नौवीं शताब्दी में जावा द्वीप पर हुआ", "सदियों पहले भूकंप में मैं परित्यक्त हो गया और ढह गया", "मैं इंडोनेशिया का महान हिंदू मंदिर परिसर हूँ"]');
INSERT INTO clue_riddles VALUES(37,'DUSSEHRA','["I celebrate the victory of good over evil", "I mark the defeat of Ravana by Lord Rama", "I fall on Ashvin Shukla Dashami", "Ravana effigies are burned during my celebration", "I am also known as Vijayadashami"]','["मैं अच्छाई की बुराई पर विजय का पर्व हूँ", "मैं रावण पर भगवान राम की विजय का प्रतीक हूँ", "मैं अश्विन शुक्ल दशमी को मनाया जाता हूँ", "मेरे दिन रावण के पुतले जलाए जाते हैं", "मुझे विजयादशमी भी कहा जाता है"]');
INSERT INTO clue_riddles VALUES(38,'DURYODHAN','["I was the crown prince of Hastinapur", "I was born from a lump of flesh", "I invited my cousins to a rigged game of dice", "I am the eldest of a hundred brothers", "I am the son of Gandhari and Dhritarashtra"]','["मैं हस्तिनापुर का राजकुमार था", "मेरा जन्म मांस के लोथड़े से हुआ", "मैंने अपने भाइयों को छल के जुए में आमंत्रित किया", "मैं सौ भाइयों में सबसे बड़ा हूँ", "मैं गांधारी और धृतराष्ट्र का पुत्र हूँ"]');
INSERT INTO clue_riddles VALUES(39,'KALI','["I wear a garland of skulls", "I stand on my own husband in battle fury", "My tongue stops destruction when I realize my act", "I was born from the forehead of a goddess", "I am the dark fierce destroyer of evil"]','["मैं मुंडमाला पहनती हूँ", "मैं युद्ध के उन्माद में अपने पति पर खड़ी हो जाती हूँ", "जब मुझे अपने कृत्य का बोध होता है तो मेरी जिह्वा विनाश रोकती है", "मेरा जन्म एक देवी के ललाट से हुआ", "मैं बुराई को नष्ट करने वाली उग्र काली शक्ति हूँ"]');
INSERT INTO clue_riddles VALUES(40,'SUGRIV','["I was exiled by my own brother", "I formed an alliance with a prince in exile, Rama", "I sent my vanara armies to search in all four directions", "My brother was killed by a divine arrow from hiding", "I am the monkey king who helped Rama"]','["मुझे मेरे अपने भाई ने निर्वासित किया", "मैंने वनवासी राजकुमार राम के साथ मित्रता की", "मैंने अपनी वानर सेनाओं को चारों दिशाओं में खोज के लिए भेजा", "मेरे भाई को छिपकर दिव्य बाण से मारा गया", "मैं वह वानर राजा हूँ जिसने राम की सहायता की"]');
INSERT INTO clue_riddles VALUES(41,'KUNTI','["I am a character in Mahabharata", "I had a secret son before my marriage", "I received a mantra to invoke any god", "I am the paternal aunt of Krishna", "I am the mother of the Pandavas"]','["मैं महाभारत की एक पात्र हूँ", "विवाह से पहले मेरा एक गुप्त पुत्र था", "मुझे किसी भी देवता को आमंत्रित करने का मंत्र प्राप्त था", "मैं कृष्ण की बुआ हूँ", "मैं पांडवों की माता हूँ"]');
INSERT INTO clue_riddles VALUES(42,'DANU','["I am a primordial goddess and a daughter of Daksha", "I am the wife of Sage Kashyapa", "I am the mother of the powerful race of Danavas", "My name is anciently linked to the cosmic waters", "I am often identified as the mother of the demon Vritra"]','["मैं एक आदिम देवी और दक्ष प्रजापति की पुत्री हूँ", "मैं महर्षि कश्यप की धर्मपत्नी हूँ", "मैं शक्तिशाली ''दानव'' जाति की जननी हूँ", "मेरे नाम का प्राचीन संबंध ब्रह्मांडीय जल से है", "मुझे अक्सर असुर वृत्र की माता के रूप में पहचाना जाता है"]');
INSERT INTO clue_riddles VALUES(43,'DHRUVA','["I was rejected by my father''s lap as a child", "Guided by Narada, I chose deep meditation", "My devotion pleased Lord Vishnu at a young age", "I was granted an eternal, unshakable position", "I became the Pole Star in the sky"]','["बचपन में मुझे मेरे पिता की गोद से हटा दिया गया", "नारद के मार्गदर्शन में मैंने तपस्या की", "कम उम्र में मेरी भक्ति से भगवान विष्णु प्रसन्न हुए", "मुझे एक शाश्वत अटल स्थान प्रदान किया गया", "मैं आकाश में स्थिर तारा बन गया"]');
INSERT INTO clue_riddles VALUES(44,'SUDAMA','["I was once a poor Brahmin", "I am childhood friend of Krishna", "I hesitated to visit my wealthy friend", "I carried a humble gift of beaten rice", "Krishna transformed my life overnight"]','["मैं कभी एक गरीब ब्राह्मण था", "मैं अपने धनी मित्र कृष्ण से मिलने में हिचकिचाया", "मैं चिवड़े का साधारण उपहार लेकर गया", "कृष्ण ने एक रात में मेरा जीवन बदल दिया"]');
INSERT INTO clue_riddles VALUES(45,'SAVITRI','["I chose my husband knowing he would die in a year", "I followed death God itself through the forest", "I won boons through my wisdom and devotion", "I brought my husband back from the dead", "I outsmarted Yama, the god of death"]','["मैंने जानते हुए भी उससे विवाह किया कि वह एक वर्ष में मर जाएगा", "मैंने वन में मृत्यु देवता का पीछा किया", "मैंने अपनी बुद्धि और भक्ति से वरदान जीते", "मैंने अपने पति को मृत्यु से वापस लाया", "मैंने यमराज को अपनी चतुराई से हराया"]');
INSERT INTO clue_riddles VALUES(46,'GOMTI','["I am a sacred water body at the ancient city of Dwarka", "I meet the Arabian Sea near the temple of Krishna", "Pilgrims take a holy dip in me before darshan", "I share the same name as one of the tributary of Ganga", "I share the same name as a sacred river in Lucknow"]','["मैं द्वारका नगरी में स्थित एक पवित्र जलधारा हूँ", "मैं कृष्ण मंदिर के पास अरब सागर से मिलती हूँ", "भक्त दर्शन से पहले मुझमें स्नान करते हैं", "मैं गंगा की एक सहायक नदी के समान नाम साझा करता हूँ", "मैं लखनऊ की एक पवित्र नदी के समान नाम साझा करता हूँ"]');
INSERT INTO clue_riddles VALUES(47,'VIDUR','["I was born of a maid yet wise beyond kings", "I served as a trusted advisor in the Kuru court", "I am the son of Vyasa", "I am considered an incarnation of Dharma", "I am the wise uncle in the Mahabharata"]','["मेरा जन्म दासी से हुआ फिर भी मैं राजाओं से अधिक बुद्धिमान था", "मैं कुरु दरबार में एक विश्वसनीय सलाहकार था", "मैं व्यास का पुत्र हूँ", "मुझे धर्म का अवतार माना जाता है", "मैं महाभारत का बुद्धिमान चाचा हूँ"]');
INSERT INTO clue_riddles VALUES(48,'SATYUG','["I am the first and most virtuous age in the cyclical concept of time", "In me, righteousness stands firmly on all four pillars", "Truth, purity, and harmony define my existence", "I precede Treta, Dvapara, and Kali", "I am also called the Golden Age"]','["मैं समय चक्र का पहला और सबसे पुण्य युग हूँ", "मेरे समय में धर्म चारों पादों पर स्थित रहता है", "सत्य, पवित्रता और संतुलन मेरी विशेषता हैं", "मैं त्रेता, द्वापर और कलि से पहले आता हूँ", "मुझे स्वर्ण युग भी कहा जाता है"]');
INSERT INTO clue_riddles VALUES(49,'JATAYU','["I am an ancient being who witnessed ages pass", "I am a demigod in the form of a vulture", "My wings were cut by a demon''s sword", "I tried to stop the abduction of a princess Sita", "I died in Rama''s arms after telling him the truth"]','["मैं युगों को बीतते देखने वाला प्राचीन प्राणी हूँ", "मैं एक गिद्ध के रूप में एक देवता हूँ", "एक राक्षस की तलवार ने मेरे पंख काट दिए", "मैंने एक राजकुमारी सीता के अपहरण को रोकने का प्रयास किया", "मैंने राम की गोद में सत्य बताकर प्राण त्यागे"]');
INSERT INTO clue_riddles VALUES(50,'HARIDWAR','["This is where a sacred river enters the plains", "Footprints of a god are imprinted on a stone here", "Evening aarti here on the river ghats is world famous", "One of the four sites of the Kumbh Mela", "I am the gateway to the gods in Uttarakhand"]','["यहाँ एक पवित्र नदी मैदानों में प्रवेश करती है", "यहाँ एक पत्थर पर एक देवता के पदचिह्न अंकित हैं", "नदी के घाटों पर यहाँ की संध्या आरती विश्व प्रसिद्ध है", "कुंभ मेले के चार स्थलों में से एक", "मैं उत्तराखंड में देवताओं का द्वार हूँ"]');
INSERT INTO clue_riddles VALUES(51,'CHANDAN','["I am a fragrant wood used in sacred rituals", "My paste is applied on the forehead as a mark of devotion", "I bring a cooling effect when applied to the skin", "I am offered to deities in temples", "You also collect me in Ishvar Vaani App"]','["मैं एक सुगंधित लकड़ी हूँ जो पूजा में उपयोग होती है", "मेरा लेप माथे पर तिलक के रूप में लगाया जाता है", "मुझे लगाने से शीतलता का अनुभव होता है", "मुझे मंदिरों में देवताओं को अर्पित किया जाता है", "आप मुझे इश्वर वाणी ऍप में भी इकट्ठा करते हैं"]');
INSERT INTO clue_riddles VALUES(52,'KOLAM','["I am a traditional floor art like rangoli", "I am drawn using rice flour or powder", "I welcome prosperity and positive energy dedicated to Goddess Laxmi", "My patterns are often geometric and symmetrical with dots", "I am commonly seen in South Indian households"]','["मैं घर के प्रवेश द्वार पर बनाई जाने वाली पारंपरिक कला हूँ", "मुझे चावल के आटे या पाउडर से बनाया जाता है", "मैं समृद्धि और सकारात्मक ऊर्जा का स्वागत करती हूँ समर्पित देवी लक्ष्मी को", "मेरे डिजाइन ज्यामितीय और सममित होते हैं बिंदुओं के साथ", "मैं दक्षिण भारतीय घरों में आमतौर पर देखी जाती हूँ"]');
INSERT INTO clue_riddles VALUES(53,'MANDAVI','["I married one of the four princes of Ayodhya", "My husband went on a long mission during the exile period", "I am the daughter of King Janaka''s brother Kushadhwaja", "My sister is Shrutakirti who also married a prince", "I am the wife of Bharata from the Ramayana"]','["मैंने अयोध्या के चार राजकुमारों में से एक से विवाह किया", "वनवास काल में मेरे पति एक लंबे मिशन पर गए", "मैं राजा जनक के भाई कुशध्वज की पुत्री हूँ", "मेरी बहन श्रुतकीर्ति है जिसने भी एक राजकुमार से विवाह किया", "मैं रामायण में भरत की पत्नी हूँ"]');
INSERT INTO clue_riddles VALUES(54,'VASISHTHA','["I own the divine wish-fulfilling cow Kamadhenu", "I am one of the seven immortal sages", "I had a long rivalry with Vishvamitra", "I am the family priest of the solar dynasty", "I am the guru of Lord Rama"]','["मेरे पास दिव्य कामधेनु गाय है", "मैं सात अमर ऋषियों में से एक हूँ", "विश्वामित्र से मेरी लंबी प्रतिद्वंद्विता थी", "मैं सूर्यवंश का कुलगुरु हूँ", "मैं भगवान राम के गुरु हूँ"]');
INSERT INTO clue_riddles VALUES(55,'DASHARATH','["I am a character in Ramayana", "A curse from a blind sage sealed my fate", "I was bound by a promise to my youngest queen", "I died of grief when my beloved son left", "I am the king of Ayodhya and father of Rama"]','["मैं रामायण का एक पात्र हूँ", "एक अंधे ऋषि के श्राप ने मेरा भाग्य तय किया", "मैं अपनी सबसे छोटी रानी से वचनबद्ध था", "मेरे प्रिय पुत्र के जाने पर मैंने प्राण त्याग दिए", "मैं अयोध्या का राजा और राम का पिता हूँ"]');
INSERT INTO clue_riddles VALUES(56,'TAKSHILA','["I was an ancient center of learning that attracted scholars from distant lands", "Chanakya and Panini are closely associated with me", "I flourished as a hub of education, trade, and culture in early times", "I am associated with subjects ranging from politics to medicine", "I am one of the world’s earliest universities in ancient India"]','["मैं प्राचीन काल का एक महान शिक्षा केंद्र था जहाँ दूर-दूर से विद्यार्थी आते थे", "चाणक्य और पाणिनि का मुझसे गहरा संबंध है", "मैं शिक्षा, व्यापार और संस्कृति का प्रमुख केंद्र था", "मेरा संबंध राजनीति से लेकर चिकित्सा तक विभिन्न विषयों से है", "मैं प्राचीन भारत का एक प्राचीन विश्वविद्यालय हूँ"]');
INSERT INTO clue_riddles VALUES(57,'BRAHMI','["I am associated with the creator of the universe", "I share my name with an ancient script from which many Indian writings evolved", "I represent knowledge, creation, and sacred wisdom", "I share my name with the script used in Emperor Ashoka’s inscriptions", "I am considered a feminine form linked to Brahma"]','["मैं सृष्टि के रचयिता से जुड़ी हुई हूँ", "मेरा नाम एक प्राचीन लिपि से जुड़ा है जिससे कई भारतीय लिपियों का विकास हुआ", "मैं ज्ञान, सृजन और पवित्र बुद्धि का प्रतीक हूँ", "मेरा नाम उस लिपि से जुड़ा है जिसका उपयोग सम्राट अशोक के शिलालेखों में किया गया था", "मुझे ब्रह्मा से जुड़ी स्त्री शक्ति माना जाता है"]');
INSERT INTO clue_riddles VALUES(58,'INDRAJIT','["I could become invisible during battle", "I am a character in Ramayana", "I used a serpent weapon to paralyze an entire army", "I was killed only through a special ritual warfare", "I am Ravana''s most powerful son, Meghanada"]','["मैं युद्ध में अदृश्य हो सकता था", "मैं रामायण का एक पात्र हूँ", "मैंने नागास्त्र से पूरी सेना को पंगु कर दिया", "मुझे केवल विशेष अनुष्ठान युद्ध से ही मारा जा सका", "मैं रावण का सबसे शक्तिशाली पुत्र मेघनाद हूँ"]');
INSERT INTO clue_riddles VALUES(59,'NANDI','["I guard the entrance to a sacred abode", "I am the leader of all divine attendants", "Devotees whisper their wishes in my ear", "I am always found facing my master", "I am Lord Shiva''s bull mount"]','["मैं एक पवित्र निवास के द्वार की रक्षा करता हूँ", "मैं सभी दिव्य सेवकों का नेता हूँ", "भक्त मेरे कान में अपनी इच्छाएँ कहते हैं", "मैं सदा अपने स्वामी की ओर मुख करके बैठता हूँ", "मैं भगवान शिव का वृषभ वाहन हूँ"]');
INSERT INTO clue_riddles VALUES(60,'SURPANAKHA','["I am a character in Ramayana", "I fell in love with an exiled prince", "My humiliation sparked a great war", "My nose was cut as punishment", "I am the sister of the king of Lanka"]','["मैं रामायण का एक पात्र हूँ", "मैं एक वनवासी राजकुमार पर मोहित हो गई", "मेरे अपमान ने एक महान युद्ध को जन्म दिया", "दंड के रूप में मेरी नाक काटी गई", "मैं लंका के राजा की बहन हूँ"]');
INSERT INTO clue_riddles VALUES(61,'ACHYUTA','["I represent the eternal, unchanging, and imperishable Supreme Being", "Arjuna addresses me by this name in the Bhagavad Gita while on the battlefield", "I am the one who never deviates from His divine nature or status", "I am a prominent name of Lord Vishnu and Lord Krishna", "My name literally means One who never falls"]','["मैं सर्वोच्च सत्ता के शाश्वत, अपरिवर्तनीय और अविनाशी रूप का प्रतीक हूँ", "भगवद गीता में युद्ध के मैदान में अर्जुन ने मुझे इसी नाम से पुकारा था", "मैं वह हूँ जो अपने दिव्य स्वरूप या स्थिति से कभी विचलित नहीं होता", "मैं भगवान विष्णु और भगवान कृष्ण का एक प्रमुख नाम हूँ", "मेरे नाम का शाब्दिक अर्थ है वह जिसका कभी पतन नहीं होता"]');
INSERT INTO clue_riddles VALUES(62,'KUBER','["I am the treasurer of the gods", "I fly in a divine aerial chariot called Pushpaka", "I rule over a golden city in the north", "My half-brother took my kingdom by force", "I am the god of wealth"]','["मैं देवताओं का कोषाध्यक्ष हूँ", "मैं पुष्पक नामक दिव्य विमान में उड़ता हूँ", "मैं उत्तर में एक स्वर्ण नगरी पर राज करता हूँ", "मेरे सौतेले भाई ने बलपूर्वक मेरा राज्य छीन लिया", "मैं धन का देवता हूँ"]');
INSERT INTO clue_riddles VALUES(63,'KAMADEVA','["I shoot arrows made of flowers", "A parrot is my companion", "I was burnt to ashes by a third eye", "I am reborn as the son of Krishna", "I am the god of love and desire"]','["मैं फूलों के बाण चलाता हूँ", "तोता मेरा साथी है", "मुझे एक तीसरे नेत्र ने भस्म कर दिया", "मैं कृष्ण के पुत्र के रूप में पुनर्जन्म लेता हूँ", "मैं प्रेम और काम का देवता हूँ"]');
INSERT INTO clue_riddles VALUES(64,'ANJANA','["I am the mother of the mighty Hanuman", "I was once an apsara who was cursed to be born on earth", "Through divine blessings of Vayu, I gave birth to a powerful son", "My husband was Kesari", "I am also known as Anjali"]','["मैं महान हनुमान की माता हूँ", "मैं एक अप्सरा थी जिसे श्राप के कारण पृथ्वी पर जन्म लेना पड़ा", "वायु देव के दिव्य आशीर्वाद से मैंने एक शक्तिशाली पुत्र को जन्म दिया", "मेरे पति केसरी थे", "मैं अंजलि के नाम से भी जानी जाती हूँ"]');
INSERT INTO clue_riddles VALUES(65,'MATSYA','["I appeared first as a tiny creature in a palm", "I kept growing until no vessel could hold me", "I warned a sage about a coming catastrophe", "I pulled a boat through a great deluge", "I am Vishnu''s fish avatar who saved creation"]','["मैं पहले हथेली में एक छोटे प्राणी के रूप में प्रकट हुआ", "मैं बढ़ता गया जब तक कोई पात्र मुझे रख न सका", "मैंने एक ऋषि को आने वाली प्रलय की चेतावनी दी", "मैंने महाप्रलय में एक नाव को खींचा", "मैं विष्णु का मत्स्य अवतार हूँ जिसने सृष्टि को बचाया"]');
INSERT INTO clue_riddles VALUES(66,'JAMBAVAN','["I witnessed the avatar of Vamana cover the universe", "I am the oldest being in Rama''s monkey army", "I reminded Hanuman of his forgotten powers", "I fought Krishna for twenty-one days over a jewel", "I am the immortal bear king from the Ramayana"]','["मैंने वामन अवतार को ब्रह्मांड नापते देखा", "मैं राम की वानर सेना का सबसे वृद्ध प्राणी हूँ", "मैंने हनुमान को उनकी भूली हुई शक्तियाँ याद दिलाईं", "मैंने एक मणि के लिए कृष्ण से इक्कीस दिन युद्ध किया", "मैं रामायण का अमर भालू राजा हूँ"]');
INSERT INTO clue_riddles VALUES(67,'VAYU','["I am invisible yet felt by all living beings", "I am the father of two mighty warriors in two different epics", "I carry fragrance from one place to another", "Without me no creature can survive even a moment", "I am the god of wind"]','["मैं अदृश्य हूँ फिर भी सभी प्राणी मुझे अनुभव करते हैं", "मैं दो अलग महाकाव्यों में दो महान योद्धाओं का पिता हूँ", "मैं सुगंध को एक स्थान से दूसरे स्थान तक ले जाता हूँ", "मेरे बिना कोई प्राणी एक पल भी जीवित नहीं रह सकता", "मैं पवन देव हूँ"]');
INSERT INTO clue_riddles VALUES(68,'VIBHISHAN','["I am a character from Ramayana", "I left my brother''s kingdom to join his enemy", "I revealed the secret of my brother''s immortality", "I was crowned king after a great war", "I am the brother of Ravana"]','["मैं रामायण का एक पात्र हूँ", "मैंने अपने भाई का राज्य छोड़कर उसके शत्रु का साथ दिया", "मैंने अपने भाई की अमरता का रहस्य बताया", "एक महान युद्ध के बाद मुझे राजा बनाया गया", "मैं रावण का भाई हूँ"]');
INSERT INTO clue_riddles VALUES(69,'VARAHA','["I am an incarnation of God", "I fought Hiranyaksha who had hidden the earth", "I lifted the entire world on my tusks", "I am the third avatar in the Dashavatara", "I am Vishnu''s boar avatar"]','["मैं भगवान का अवतार हूँ", "मैंने हिरण्याक्ष से युद्ध किया जिसने पृथ्वी को छिपा दिया था", "मैंने पूरी पृथ्वी को अपने दाँतों पर उठाया", "मैं दशावतार का तीसरा अवतार हूँ", "मैं विष्णु का वराह अवतार हूँ"]');
INSERT INTO clue_riddles VALUES(70,'TRETA','["I am the second age in the great cyclical timeline of existence", "In me, righteousness stands on three pillars instead of four", "Many divine incarnations, including a prince of Ayodhya, appeared during my time", "I follow Satya and precede Dvapara", "I am one of the four yugas in Hindu cosmology"]','["मैं समय चक्र का दूसरा युग हूँ", "मेरे समय में धर्म तीन पादों पर स्थित रहता है", "मेरे काल में अयोध्या के एक दिव्य अवतार का जन्म हुआ", "मैं सत्य के बाद और द्वापर से पहले आता हूँ", "मैं हिंदू मान्यता के चार युगों में से एक हूँ"]');
INSERT INTO clue_riddles VALUES(71,'AHALYA','["I was created as the most beautiful woman ever", "I was deceived by a god in disguise", "I was cursed to become a stone", "I waited ages for redemption in silence", "The touch of Rama''s feet freed me from my curse"]','["मेरी रचना अब तक की सबसे सुंदर स्त्री के रूप में हुई", "मुझे एक भेष बदले देवता ने छला", "मुझे पत्थर बनने का श्राप मिला", "मैंने मौन में युगों तक मुक्ति की प्रतीक्षा की", "राम के चरण स्पर्श ने मुझे श्राप से मुक्त किया"]');
INSERT INTO clue_riddles VALUES(72,'MANDODARI','["I am a character in Ramayana", "I am considered one of the five ideal women", "I knew my husband''s actions would destroy our kingdom", "I was a devoted wife to a powerful demon king", "I am the wise queen of Lanka"]','["मैं रामायण का एक पात्र हूँ", "मुझे पाँच आदर्श नारियों में से एक माना जाता है", "मैं जानती थी कि मेरे पति के कार्य हमारे राज्य को नष्ट कर देंगे", "मैं एक शक्तिशाली राक्षस राजा की समर्पित पत्नी थी", "मैं लंका की बुद्धिमान रानी हूँ"]');
INSERT INTO clue_riddles VALUES(73,'SHAKUNI','["I am a character in Mahabharata", "I avenged my family through manipulation and deceit", "I engineered a game that led to a great war", "I could make dice fall any way I wished", "I am the cunning uncle of the Kauravas"]','["मैं महाभारत का एक पात्र हूँ", "मैंने छल और कपट से अपने परिवार का बदला लिया", "मैंने वह खेल रचा जो महायुद्ध का कारण बना", "मैं पासों को अपनी इच्छा से गिरा सकता था", "मैं कौरवों का चालाक मामा हूँ"]');
INSERT INTO clue_riddles VALUES(74,'SHARABHA','["I am a fierce and mythical creature from Hindu mythology", "I am often depicted with giant wings and two heads in temple sculptures", "I am associated with Lord Shiva’s powerful form", "I was manifested to calm an uncontrollable divine force Narasimha", "I am part lion and part bird, possessing strength greater than a lion or elephant"]','["मैं हिंदू पौराणिक कथाओं का एक उग्र और रहस्यमयी प्राणी हूँ", "मुझे अक्सर मंदिरों में विशाल पंखों और दो सिरों के साथ दिखाया जाता है", "मेरा संबंध भगवान शिव के शक्तिशाली रूप से है", "मुझे एक अनियंत्रित दिव्य शक्ति नरसिम्हा को शांत करने के लिए प्रकट किया गया था", "मैं आधा सिंह और आधा पक्षी हूँ, जिसके पास सिंह और गज से भी अधिक शक्ति है"]');
INSERT INTO clue_riddles VALUES(75,'SAHADEV','["I am a character in Mahabharata", "I knew the future but was cursed to never reveal it", "I am the youngest of five royal brothers", "My twin brother is the most handsome Pandava", "I am the fifth Pandava born of the Ashwini gods"]','["मैं महाभारत का एक पात्र हूँ", "मैं भविष्य जानता था पर उसे बताने का श्राप था", "मैं पाँच राजकुमार भाइयों में सबसे छोटा हूँ", "मेरा जुड़वाँ भाई सबसे सुंदर पांडव है", "मैं अश्विनी कुमारों से जन्मा पाँचवाँ पांडव हूँ"]');
INSERT INTO clue_riddles VALUES(76,'MITHILA','["I was a great ancient center of Vedic learning and spirituality", "I am an ancient kingdom located in the Videha region of modern Bihar and Nepal", "I am world-renowned for my vibrant folk art and Madhubani paintings", "I was ruled by the philosopher-king Janaka", "I am the sacred birthplace of Goddess Sita, also known as Maithili"]','["मैं प्राचीन काल में वैदिक विद्या और आध्यात्मिकता का एक महान केंद्र था", "मैं विदेह क्षेत्र (आधुनिक बिहार और नेपाल) में स्थित एक प्राचीन साम्राज्य हूँ", "मैं अपनी जीवंत लोक कला और मधुबनी चित्रों के लिए विश्व प्रसिद्ध हूँ", "मुझ पर परम ज्ञानी राजा जनक का शासन था", "मैं माता सीता की पावन जन्मभूमि हूँ, जिन्हें ''मैथिली'' भी कहा जाता है"]');
INSERT INTO clue_riddles VALUES(77,'KALIDAS','["Goddess Kali blessed me with extraordinary wisdom", "I wrote about the cloud as a messenger of love", "My plays and poems are gems of Sanskrit literature", "I am the greatest Sanskrit poet, author of Shakuntala", "I am called Indian Shakespeare"]','["देवी काली ने मुझे असाधारण बुद्धि का वरदान दिया", "मैंने बादल को प्रेम का दूत बनाकर लिखा", "मेरे नाटक और काव्य संस्कृत साहित्य के रत्न हैं", "मैं सबसे महान संस्कृत कवि हूँ, शकुंतला का लेखक", "मुझे भारतीय शेक्सपियर भी कहा जाता है"]');
INSERT INTO clue_riddles VALUES(78,'HIDIMBI','["I am a character in Mahabharata", "I was a demoness who fell in love with one of the Pandavas", "I lived in the forest and raised my son alone", "I am the rakshasi wife of Bhima", "I am the sister of Hidimba"]','["मैं महाभारत का एक पात्र हूँ", "मैं एक राक्षसी थी जो पांडवों में से एक से प्रेम कर बैठी", "मैं वन में रही और अपने पुत्र को अकेले पाला", "मैं भीम की राक्षसी पत्नी हूँ", "मैं हिडिम्ब की बहन हूँ"]');
INSERT INTO clue_riddles VALUES(79,'CHAITRA','["I mark the beginning of the Hindu lunar year", "Spring arrives with my onset", "Navratri is celebrated during my period", "I bring renewal, festivals, and new beginnings", "I fall in the month of March or April"]','["मैं हिंदू चंद्र वर्ष की शुरुआत करता हूँ", "मेरे आगमन के साथ वसंत ऋतु आती है", "मेरे समय में नवरात्रि मनाई जाती है", "मैं नव आरंभ और उत्सव लेकर आता हूँ", "मैं मार्च या अप्रैल के महीने में आता हूँ"]');
INSERT INTO clue_riddles VALUES(80,'MANTHARA','["I am a character in Ramayana", "I am a hunchback", "I was a trusted servant who gave poisonous advice", "I convinced a queen to demand exile for a prince", "I turned Kaikeyi against Rama"]','["मैं रामायण का एक पात्र हूँ", "मैं कुबड़ी हूँ", "मैं एक दासी थी जिसने विषैली सलाह दी", "मैंने एक रानी को राजकुमार के वनवास की माँग करने के लिए प्रेरित किया", "मैंने कैकेयी को राम के विरुद्ध भड़काया"]');
INSERT INTO clue_riddles VALUES(81,'TITHI','["I am a subtle measure of time based on the angular relationship between the sun and the moon", "My calculation changes daily and is central to traditional lunar calendars", "Rituals and festivals are often determined according to me", "I divide a lunar month into specific phases", "I represent a lunar day in the Hindu calendar"]','["मैं समय की वह सूक्ष्म इकाई हूँ जो सूर्य और चंद्रमा के कोणीय संबंध पर आधारित है", "मेरा निर्धारण प्रतिदिन बदलता है और मैं पंचांग का महत्वपूर्ण भाग हूँ", "अनुष्ठान और त्योहार अक्सर मेरे अनुसार तय किए जाते हैं", "मैं एक चंद्र मास को विशेष भागों में विभाजित करता हूँ", "मैं हिंदू पंचांग का एक चंद्र दिवस हूँ"]');
INSERT INTO clue_riddles VALUES(82,'ANGAD','["I am a character in Ramayana", "I am part of Vanara Sena", "I was sent as a peace messenger before a great war", "No one in the enemy court could move my foot", "I am the monkey prince, son of Vali"]','["मैं रामायण का एक पात्र हूँ", "मैं वानर सेना का हिस्सा हूँ", "मुझे एक महान युद्ध से पहले शांति दूत के रूप में भेजा गया", "शत्रु दरबार में कोई मेरा पैर नहीं हिला सका", "मैं वालि का पुत्र वानर राजकुमार हूँ"]');
INSERT INTO clue_riddles VALUES(83,'MANASA','["I protect devotees from snakebites", "I was rejected by my own father initially", "I am the wife of Jaratkaru and mother of Astika", "I am the sister of the serpent king Vasuki", "I am the goddess of snakes in Hindu mythology"]','["मैं भक्तों को सर्पदंश से बचाती हूँ", "मेरे अपने पिता ने शुरू में मुझे अस्वीकार किया", "मैं जरत्कारु की पत्नी और आस्तीक की माँ हूँ", "मैं नागराज वासुकि की बहन हूँ", "मैं हिंदू पुराणों में सर्पों की देवी हूँ"]');
INSERT INTO clue_riddles VALUES(84,'GULIGA','["I am a powerful Daiva from Tulu Nadu and Kerala", "I was born from the thumb of Lord Shiva", "I am closely associated with the planet Saturn (Shani)", "I am a central figure in the Theyyam ritual", "I challenged Yama to protect Markandeya"]','["मैं तुलु नाडु और केरल का एक शक्तिशाली ''दैव'' हूँ", "मेरा जन्म शिवजी के अंगूठे से हुआ था", "मुझे शनि ग्रह का रूप माना जाता है", "मैं थेय्यम परंपरा का एक प्रमुख देवता हूँ", "मैंने मार्कण्डेय के लिए यमराज को रोका था"]');
INSERT INTO clue_riddles VALUES(85,'DURVASA','["I am a Sage and my anger is feared by gods and humans alike", "I cursed Krishna and Rukmini", "I once gave a mantra to Kunti that could summon gods", "I cursed Shakuntala to be forgotten by her beloved", "I am the short-tempered sage known for my curses"]','["मैं एक ऋषि हूँ और मेरे क्रोध से देवता और मनुष्य दोनों डरते हैं", "मैंने कृष्ण और रुक्मिणी को श्राप दिया", "मैंने एक बार कुंती को देवताओं को बुलाने का मंत्र दिया", "मैंने शकुंतला को उसके प्रियतम द्वारा भुला दिए जाने का श्राप दिया", "मैं अपने श्रापों के लिए प्रसिद्ध क्रोधी ऋषि हूँ"]');
INSERT INTO clue_riddles VALUES(86,'MARKANDEYA','["I am a Sage who was destined to die at the age of sixteen", "I embraced a Shiva lingam when death came for me", "Death himself was kicked away by my protector", "I am the son of Mrikanda", "I am the sage who was granted eternal youth by Shiva"]','["मैं एक ऋषि हूँ और मेरी नियति सोलह वर्ष की आयु में मरने की थी", "जब मृत्यु आई तो मैंने शिवलिंग को गले लगा लिया", "मेरे रक्षक ने मृत्यु को ही लात मारकर हटाया", "मैं मृकंडु का पुत्र हूँ", "मैं वह ऋषि हूँ जिसे शिव ने शाश्वत यौवन का वरदान दिया"]');
INSERT INTO clue_riddles VALUES(87,'STOTRA','["A lyrical outpouring of devotion praising the Divine", "I arise from the Sanskrit root ''stu'', meaning to praise", "Unlike mantras, I flow freely as poetic Bhakti", "Famous forms of me include Shiva Tandava and Ram Raksha", "I am a sacred hymn recited in worship"]','["मैं दिव्यता की स्तुति में बहने वाली भक्तिपूर्ण काव्य धारा हूँ", "मेरा उद्गम संस्कृत धातु ''स्तु'' से है, जिसका अर्थ है स्तुति करना", "मंत्रों के विपरीत, मैं स्वतंत्र रूप से बहने वाली भक्ति कविता हूँ", "मेरे प्रसिद्ध रूपों में शिव तांडव और राम रक्षा शामिल हैं", "मैं एक पवित्र स्तुति गीत हूँ"]');
INSERT INTO clue_riddles VALUES(88,'YAJNA','["I am a sacred ritual central to Vedic tradition", "I am often performed for prosperity, purification, or blessings", "Agni is my primary witness and carrier of offerings", "I am also known as Havan", "I arise from the Sanskrit root ''yaj'', meaning to worship"]','["मैं वैदिक परंपरा का एक पवित्र अनुष्ठान हूँ", "मुझे समृद्धि, शुद्धि और आशीर्वाद के लिए किया जाता है", "अग्नि देव मेरे माध्यम से आहुति देवताओं तक पहुँचाते हैं", "मुझे हवन के नाम से भी जाना जाता है", "मेरा उद्गम संस्कृत धातु ''यज्'' से है, जिसका अर्थ है पूजा"]');
INSERT INTO clue_riddles VALUES(89,'SWAMI','["I am a title given to a spiritual master or teacher", "My name comes from Sanskrit meaning owner or self-controller", "I signify one who has mastery over mind and senses", "I am often used before the names of saints and monks", "I represent authority rooted in wisdom and renunciation"]','["मैं एक आध्यात्मिक गुरु या शिक्षक को दिया जाने वाला सम्मान सूचक नाम हूँ", "मेरा अर्थ संस्कृत में मालिक या आत्मसंयमी होता है", "मैं उस व्यक्ति को दर्शाता हूँ जिसने मन और इंद्रियों पर नियंत्रण पाया है", "मेरा उपयोग संतों और संन्यासियों के नाम से पहले किया जाता है", "मैं ज्ञान और त्याग पर आधारित अधिकार का प्रतीक हूँ"]');
INSERT INTO clue_riddles VALUES(90,'BALI','["I was the most generous Asura king of all time", "I am the grandson of Prahlada", "I am allowed to return to earth once a year during Onam", "I was defeated by Lord Vamana", "I share the same name as Vanara King in Ramayana"]','["मैं सर्वकाल का सबसे उदार असुर राजा था", "मैं प्रहलाद का पोता हूँ", "मुझे ओणम पर वर्ष में एक बार पृथ्वी पर आने की अनुमति है", "मुझे भगवान वामन ने पराजित किया", "मैं रामायण में वानर राजा के समान नाम साझा करता हूँ"]');
INSERT INTO clue_riddles VALUES(91,'NALA','["I am a vanara and an architect who could make stones float", "I led the construction of Rama Setu", "My bridge connected the mainland to an island kingdom", "I built the Rama Setu across the ocean", "I am twin brother of Nila"]','["मैं एक वानर और एक वास्तुकार हूँ जो पत्थरों को तैरा सकता था", "मैंने राम सेतु के निर्माण का नेतृत्व किया", "मेरे पुल ने मुख्य भूमि को एक द्वीप राज्य से जोड़ा", "मैंने समुद्र पर राम सेतु का निर्माण किया", "मैं नील का जुड़वां भाई हूँ"]');
INSERT INTO clue_riddles VALUES(92,'TULSIDAS','["I was rejected by my wife which changed my life forever", "I rewrote an ancient epic in the language of the common people", "I composed the Hanuman Chalisa", "I had a vision of Rama and Hanuman", "I wrote the Ramcharitmanas in Awadhi"]','["मेरी पत्नी ने मुझे अस्वीकार किया जिसने मेरा जीवन बदल दिया", "मैंने एक प्राचीन महाकाव्य को आम लोगों की भाषा में लिखा", "मैंने हनुमान चालीसा की रचना की", "मुझे राम और हनुमान के दर्शन हुए", "मैंने अवधी में रामचरितमानस लिखी"]');
INSERT INTO clue_riddles VALUES(93,'CAMPHOR','["I burn completely without leaving any residue", "I am used in aarti during Hindu rituals", "I release a strong, purifying fragrance when lit", "I am white in color", "I am called kapoor in hindi"]','["मैं जलने पर कोई अवशेष नहीं छोड़ता", "मेरा उपयोग आरती में किया जाता है", "जलने पर मैं सुगंधित और शुद्ध वातावरण बनाता हूँ", "मैं सफेद रंग का होता हूँ", "मुझे हिंदी में कपूर कहते हैं"]');
INSERT INTO clue_riddles VALUES(94,'KAIKEYI','["I am a character in Ramayana", "I once saved my husband''s life in a fierce battle", "I demanded the throne for my own son", "I sent Rama into exile for fourteen years", "I am the third wife of King Dasharatha"]','["मैं रामायण का एक पात्र हूँ", "मैंने एक बार भयंकर युद्ध में अपने पति की जान बचाई", "मैंने अपने पुत्र के लिए सिंहासन की माँग की", "मैंने राम को चौदह वर्ष के वनवास पर भेजा", "मैं राजा दशरथ की तीसरी पत्नी हूँ"]');
INSERT INTO clue_riddles VALUES(95,'GHATOTKACH','["I am a character in Mahabharata", "I could fly and grow to enormous size", "My death saved Arjuna''s life", "Karna used his supreme weapon to kill me", "I am the demon son of Bhima and Hidimbi"]','["मैं महाभारत का एक पात्र हूँ", "मैं उड़ सकता था और विशाल आकार ले सकता था", "मेरी मृत्यु ने अर्जुन की जान बचाई", "कर्ण ने मुझे मारने के लिए अपना सर्वोच्च अस्त्र चलाया", "मैं भीम और हिडिम्बी का राक्षस पुत्र हूँ"]');
INSERT INTO clue_riddles VALUES(96,'MEERA','["I drank poison sent by my own family and survived", "I gave up royal life for devotion", "I danced and sang in the streets without shame", "I considered myself married to a deity", "I am the princess who devoted her life to Krishna"]','["मैंने अपने ही परिवार द्वारा भेजा विष पिया और जीवित रही", "मैंने भक्ति के लिए राजसी जीवन त्याग दिया", "मैं बिना लज्जा के गलियों में नाचती और गाती थी", "मैं स्वयं को एक देवता से विवाहित मानती थी", "मैं वह राजकुमारी हूँ जिसने अपना जीवन कृष्ण को समर्पित किया"]');
INSERT INTO clue_riddles VALUES(97,'KEDARNATH','["I stand at an altitude where few dare to tread", "I survived a devastating flood that destroyed everything around me", "I am the Himalayan temple of Lord Shiva", "One of the twelve Jyotirlingas resides within me", "I am a part of Chhota Char Dham"]','["मैं उस ऊँचाई पर खड़ा हूँ जहाँ कम लोग जाने का साहस करते हैं", "मैं उस विनाशकारी बाढ़ में बचा जिसने आसपास सब कुछ नष्ट कर दिया", "मैं हिमालय में भगवान शिव का मंदिर हूँ", "बारह पवित्र ज्योतिर्लिंगों में से एक मेरे अंदर विराजमान है", "मैं छोटा चार धाम का हिस्सा हूँ"]');
INSERT INTO clue_riddles VALUES(98,'THANJAVUR','["I am a historic city known for my rich cultural and architectural heritage in South India", "Brihadeeswarar Temple dedicated to a powerful deity stands as my pride", "I flourished under a Chola dynasty famous for art and architecture", "I am a famous city in Tamil Nadu", "I am also known as Tanjore"]','["मैं दक्षिण भारत का एक ऐतिहासिक नगर हूँ जो अपनी समृद्ध संस्कृति और स्थापत्य के लिए प्रसिद्ध है", "मेरे यहाँ बृहदीश्वर मंदिर है जो मेरी पहचान है", "मैं चोल वंश के अधीन फला-फूला", "मैं तमिलनाडु का एक प्रसिद्ध शहर हूँ", "मुझे तंजौर के नाम से भी जाना जाता है"]');
INSERT INTO clue_riddles VALUES(99,'JAGANNATH','["My idol has no hands or feet yet is most powerful", "My kitchen feeds thousands of devotees every day", "My chariot festival is world famous", "I am the lord of Puri in Odisha", "The word Juggernaut comes from my name"]','["मेरी मूर्ति के हाथ-पैर नहीं हैं फिर भी सबसे शक्तिशाली है", "मेरी रसोई प्रतिदिन हजारों भक्तों को भोजन कराती है", "मेरा रथ उत्सव विश्व प्रसिद्ध है", "मैं ओडिशा के पुरी का स्वामी हूँ", "जगरनॉट शब्द मेरे नाम से आया है"]');
INSERT INTO clue_riddles VALUES(100,'KURMA','["I am an incarnation of a deity", "I kept a mountain from sinking into the ocean during Samudra Manthan", "I am a slow creature but I held the cosmos steady", "I am Vishnu''s tortoise avatar", "I am the second avatar of Dashavatar"]','["मैं एक देवता का अवतार हूँ", "मैंने समुद्र मंथन के दौरान एक पर्वत को समुद्र में डूबने से बचाया", "मैं एक धीमा प्राणी हूँ पर मैंने ब्रह्मांड को स्थिर रखा", "मैं विष्णु का कूर्म अवतार हूँ", "मैं दशावतार का दूसरा अवतार हूँ"]');
INSERT INTO clue_riddles VALUES(101,'TIRUPATI','["I am the richest temple in the world", "Devotees shave their heads as an offering here", "I sit atop seven hills in southern India", "Laddoo prasadam from here is world famous", "I am the abode of Lord Venkateswara"]','["मैं दुनिया का सबसे धनी मंदिर हूँ", "भक्त यहाँ अर्पण के रूप में अपने बाल चढ़ाते हैं", "मैं दक्षिण भारत की सात पहाड़ियों पर स्थित हूँ", "यहाँ का लड्डू प्रसाद विश्व प्रसिद्ध है", "मैं भगवान वेंकटेश्वर का निवास हूँ"]');
INSERT INTO clue_riddles VALUES(102,'YAMUNA','["I am the daughter of the Sun God", "My brother is the God of Death, Yamraj", "A divine child danced on a serpent''s hood in my waters", "I am the main river of Delhi", "I am the sacred river of Krishna''s childhood"]','["मैं सूर्य देव की पुत्री हूँ", "मेरा भाई मृत्यु का देवता, यमराज है", "एक दिव्य बालक ने मेरे जल में एक सर्प के फन पर नृत्य किया", "मैं दिल्ली की मुख्य नदी हूँ", "मैं कृष्ण के बचपन की पवित्र नदी हूँ"]');
INSERT INTO clue_riddles VALUES(103,'MEENAKSHI','["I was born with three breasts and a prophecy", "I am an avatar of Parvati", "My third breast vanished when I saw my future husband, Shiva", "My temple has a thousand pillars and a golden lotus tank", "I am the fish-eyed goddess queen of Madurai"]','["मेरा जन्म तीन स्तनों और एक भविष्यवाणी के साथ हुआ", "मैं पार्वती का अवतार हूँ", "मेरा तीसरा स्तन मेरे होने वाले पति शिव को देखकर लुप्त हो गया", "मेरे मंदिर में हजार स्तंभ और स्वर्ण कमल सरोवर है", "मैं मदुरै की मत्स्य नेत्री देवी रानी हूँ"]');
INSERT INTO clue_riddles VALUES(104,'SOMNATH','["I am a temple that was destroyed and rebuilt seventeen times", "I was the first among twelve Jyotirlingas", "Foreign invaders looted me for my legendary wealth", "The moon god built me to honor Shiva after a curse was lifted", "I am the eternal temple on the coast of Gujarat"]','["मैं एक मंदिर हूँ जिसे सत्रह बार तोड़ा और पुनर्निर्मित किया गया", "मैं बारह पवित्र ज्योतिर्लिंगों में प्रथम हूँ", "विदेशी आक्रमणकारियों ने मेरी पौराणिक संपत्ति को लूटा", "चंद्र देव ने शिव के सम्मान में श्राप मुक्ति के बाद मेरा निर्माण किया", "मैं गुजरात के तट पर शाश्वत मंदिर हूँ"]');
INSERT INTO clue_riddles VALUES(105,'AYODHYA','["I am one of the seven sacred cities of India", "A prince was born here who became an ideal king", "A magnificent temple has recently risen on my soil", "I am the birthplace of Lord Rama", "I am located on the banks of the Sarayu River"]','["मैं भारत के सात पवित्र नगरों में से एक हूँ", "यहाँ एक राजकुमार का जन्म हुआ जो आदर्श राजा बना", "हाल ही में मेरी धरती पर एक भव्य मंदिर बना है", "मैं भगवान राम की जन्मभूमि हूँ", "मैं सरयू नदी के तट पर स्थित हूँ"]');
INSERT INTO clue_riddles VALUES(106,'MAHADEV','["I am known as the great god among all deities", "I dwell in the Himalayas in deep meditation", "The Ganga flows from my matted locks", "I am worshipped as the destroyer and transformer in the Trimurti", "I am a revered name of Lord Shiva"]','["मैं सभी देवताओं में महान देव के रूप में जाना जाता हूँ", "मैं हिमालय में गहन ध्यान में लीन रहता हूँ", "गंगा मेरी जटाओं से प्रवाहित होती है", "मैं त्रिमूर्ति में संहारक और परिवर्तनकर्ता के रूप में पूजित हूँ", "मैं भगवान शिव का एक पवित्र नाम हूँ"]');
INSERT INTO clue_riddles VALUES(107,'VRINDAVAN','["The sound of a divine flute still echoes here", "Raas Leela was performed here under moonlit nights", "Thousands of widows come here seeking refuge", "I have more temples than houses", "I am the sacred land of Krishna''s childhood"]','["यहाँ अभी भी दिव्य बांसुरी की गूँज सुनाई देती है", "चांदनी रातों में यहाँ रासलीला रची गई", "हजारों विधवाएँ यहाँ शरण लेने आती हैं", "मुझमें घरों से अधिक मंदिर हैं", "मैं कृष्ण के बचपन की पवित्र भूमि हूँ"]');
INSERT INTO clue_riddles VALUES(108,'BHAKTI','["Pure love and surrender to the Divine", "Through me, love becomes the path to union with the ultimate", "One of the three paths to Moksha in the Gita", "Followed by saints like Mirabai and Tulsidas", "I simply mean devotion toward God"]','["ईश्वर के प्रति पूर्ण प्रेम और समर्पण", "मेरे माध्यम से प्रेम ही परम सत्य से मिलने का मार्ग बन जाता है", "गीता में मोक्ष के तीन मार्गों में से एक", "मीरा और तुलसीदास जैसे संतों का मार्ग", "मैं साधारण रूप में ईश्वर के प्रति अटूट प्रेम और विश्वास हूँ"]');
INSERT INTO clue_riddles VALUES(109,'UJJAIN','["One of the four places where drops of immortal nectar fell", "The prime meridian of ancient Indian astronomy passes through me", "Kumbh Mela is held here on the banks of river Shipra", "I house the Mahakaleshwar Jyotirlinga", "I am the city of Mahakal in Madhya Pradesh"]','["मैं उन चार स्थानों में से एक हूँ जहाँ अमृत की बूँदें गिरी थीं", "प्राचीन भारतीय खगोल विज्ञान की प्रमुख याम्योत्तर रेखा मुझसे गुजरती है", "क्षिप्रा नदी के तट पर यहाँ कुंभ मेला लगता है", "मेरे अंदर महाकालेश्वर ज्योतिर्लिंग है", "मैं मध्य प्रदेश में महाकाल की नगरी हूँ"]');
INSERT INTO clue_riddles VALUES(110,'SHABARI','["I am a character in Ramayana", "I tasted berries before offering them to Lord Rama", "I lived as a simple tribal devotee in the forest", "My guru Matanga told me God would come to me one day", "Lord Rama ate my half-eaten berries with love"]','["मैं रामायण की एक पात्र हूँ", "मैंने भगवान राम को बेर चखकर अर्पित किए", "मैं वन में एक साधारण आदिवासी भक्त के रूप में रहती थी", "मेरे गुरु मातंग ने कहा था कि एक दिन भगवान मेरे पास आएंगे", "भगवान राम ने मेरे जूठे बेर प्रेम से खाए"]');
INSERT INTO clue_riddles VALUES(111,'RISHIKESH','["The Beatles came here seeking spiritual awakening", "I am surrounded by forests and the Himalayas", "Suspension bridges connect my two banks", "I am known as the yoga capital of the world", "I am the holy city where sages meditate by the Ganga"]','["बीटल्स यहाँ आध्यात्मिक जागृति की खोज में आए थे", "मैं वनों और हिमालय से घिरा हूँ", "झूले के पुल मेरे दो किनारों को जोड़ते हैं", "मुझे विश्व की योग राजधानी कहा जाता है", "मैं वह पवित्र नगर हूँ जहाँ ऋषि गंगा किनारे ध्यान करते हैं"]');
INSERT INTO clue_riddles VALUES(112,'GODAVARI','["I am the longest river in southern India", "Sage Gautama brought me to earth through penance", "I am called the Ganga of the south", "Kumbh Mela is celebrated on my banks at Nashik", "I originate from Brahmagiri hills in Maharashtra"]','["मैं दक्षिण भारत की सबसे लंबी नदी हूँ", "ऋषि गौतम ने तपस्या से मुझे पृथ्वी पर लाया", "मुझे दक्षिण की गंगा कहा जाता है", "नासिक में मेरे तट पर कुंभ मेला मनाया जाता है", "मैं महाराष्ट्र की ब्रह्मगिरि पहाड़ियों से निकलती हूँ"]');
INSERT INTO clue_riddles VALUES(113,'PURANAS','["I preserve ancient narratives that explain creation, cosmology, and divine lineages", "Through stories and legends, I make complex spiritual ideas accessible to all", "I am traditionally attributed to the sage Vyasa, who is said to have compiled me", "There are eighteen major texts that belong to my tradition", "My name literally translates to ancient in Sanskrit"]','["मैं प्राचीन कथाओं का संग्रह हूँ जो सृष्टि, ब्रह्मांड और वंशावली का वर्णन करता है", "कथाओं और आख्यानों के माध्यम से मैं गूढ़ आध्यात्मिक विचारों को सरल बनाता हूँ", "पारंपरिक रूप से मेरा संकलन महर्षि वेदव्यास द्वारा किया गया माना जाता है", "मेरे अंतर्गत अठारह प्रमुख ग्रंथ आते हैं", "संस्कृत में मेरे नाम का शाब्दिक अर्थ प्राचीन होता है"]');
INSERT INTO clue_riddles VALUES(114,'AMARNATH','["I am a cave hidden high in the mountains", "I can only be reached by a difficult trek", "A pair of sacred pigeons guards my secret", "An ice formation inside me grows and shrinks with the moon", "I am the cave where Shiva told the secret of immortality"]','["मैं पहाड़ों में ऊँचाई पर छिपी एक गुफा हूँ", "मुझ तक केवल कठिन यात्रा से पहुँचा जा सकता है", "पवित्र कबूतरों का एक जोड़ा मेरे रहस्य की रक्षा करता है", "मेरे अंदर एक बर्फ की आकृति चंद्रमा के साथ बढ़ती-घटती है", "मैं वह गुफा हूँ जहाँ शिव ने अमरत्व का रहस्य बताया"]');
INSERT INTO clue_riddles VALUES(115,'AIRAVAT','["I emerged from the churning of the cosmic ocean", "I have multiple tusks and am pure white", "I can produce rain clouds from my trunk", "I guard one of the eight directions of the cosmos", "I am the divine white elephant of Lord Indra"]','["मैं समुद्र मंथन से प्रकट हुआ", "मेरे अनेक दाँत हैं और मैं शुद्ध श्वेत हूँ", "मैं अपनी सूंड से वर्षा के बादल उत्पन्न कर सकता हूँ", "मैं ब्रह्मांड की आठ दिशाओं में से एक की रक्षा करता हूँ", "मैं भगवान इंद्र का दिव्य श्वेत हाथी हूँ"]');
INSERT INTO clue_riddles VALUES(116,'GANGA','["I descended from heaven to earth through divine hair", "A sage''s penance brought me down for his ancestors", "My water is believed to never decay", "Millions bathe in me to wash away their sins", "I am India''s holiest river"]','["मैं स्वर्ग से दिव्य जटाओं से होकर पृथ्वी पर उतरी", "एक ऋषि की तपस्या ने मुझे उसके पूर्वजों के लिए नीचे लाया", "माना जाता है कि मेरा जल कभी खराब नहीं होता", "लाखों लोग अपने पाप धोने के लिए मुझमें स्नान करते हैं", "मैं भारत की सबसे पवित्र नदी हूँ"]');
INSERT INTO clue_riddles VALUES(117,'KONARK','["I am shaped like a giant chariot with stone wheels", "My wheels can tell the time of day by their shadows", "I was built in the thirteenth century by a great king", "I am also called the Black Pagoda by European sailors", "I am the Sun Temple of Odisha"]','["मेरा आकार पत्थर के पहियों वाले विशाल रथ जैसा है", "मेरे पहिये अपनी छाया से दिन का समय बता सकते हैं", "मेरा निर्माण तेरहवीं शताब्दी में एक महान राजा ने कराया", "यूरोपीय नाविक मुझे ब्लैक पैगोडा कहते थे", "मैं ओडिशा का सूर्य मंदिर हूँ"]');
INSERT INTO clue_riddles VALUES(118,'DADHICHI','["I am a sage whose ultimate sacrifice became a weapon against evil", "My bones were transformed into a divine thunderbolt", "My sacrifice enabled the defeat of a powerful asura named Vritra", "I am the rishi whose body formed Indra’s Vajra", "I have a kund named after me in Sitapur, Uttar Pradesh"]','["मैं एक ऋषि हूँ जिनका सर्वोच्च त्याग बुराई के विरुद्ध अस्त्र बना", "मेरी अस्थियों से एक दिव्य वज्र का निर्माण हुआ", "मेरे त्याग से वृत्र नामक असुर का वध संभव हुआ", "मैं वह ऋषि हूँ जिनके शरीर से इंद्र का वज्र बना", "उत्तर प्रदेश के सीतापुर में मेरे नाम पर एक कुंड है"]');
INSERT INTO clue_riddles VALUES(119,'VRITRA','["I caused a terrible drought across the universe", "I am also known as Ahi in the Vedas", "No weapon could pierce my body at first", "I was defeated only by a weapon made of Sage Dadhichi bones", "I am the serpent demon slain by Indra''s thunderbolt"]','["मैंने पूरे ब्रह्मांड में भयानक सूखा पैदा किया", "मैं वेदों में अहि के नाम से भी जाना जाता हूँ", "पहले कोई हथियार मेरे शरीर को भेद नहीं सकता था", "मुझे केवल एक ऋषि दधीचि की हड्डियों से बने अस्त्र ने पराजित किया", "मैं वह सर्प राक्षस हूँ जिसे इंद्र के वज्र ने मारा"]');
INSERT INTO clue_riddles VALUES(120,'LANKA','["I am a place in Ramayana", "I am a golden city built by a divine architect ", "I was originally ruled by the god of wealth, Kuber", "A great war was fought to rescue a princess held here", "I am the island kingdom of Ravana"]','["मैं रामायण में एक स्थान हूँ", "मैं एक दिव्य वास्तुकार द्वारा निर्मित स्वर्ण नगरी हूँ", "मूल रूप से मुझ पर धन के देवता कुबेर का शासन था", "यहाँ बंदी राजकुमारी को छुड़ाने के लिए महान युद्ध लड़ा गया", "मैं रावण का द्वीप राज्य हूँ"]');
INSERT INTO clue_riddles VALUES(121,'PRAYAGRAJ','["Three rivers meet at my sacred confluence", "One of the rivers here is invisible to the eye", "The largest human gathering on earth happens here", "I am a city in Uttar Pradesh", "I am the city of Triveni Sangam and Kumbh Mela"]','["मेरे पवित्र संगम पर तीन नदियाँ मिलती हैं", "यहाँ की एक नदी आँखों से दिखाई नहीं देती", "पृथ्वी का सबसे बड़ा मानव समागम यहाँ होता है", "मैं उत्तर प्रदेश का एक शहर हूँ", "मैं त्रिवेणी संगम और कुंभ मेले की नगरी हूँ"]');
INSERT INTO clue_riddles VALUES(122,'HARIHARA','["I represent the unity of two supreme deities into a single form", "My form symbolizes harmony between preservation and destruction", "I am depicted as half one deity and half another", "I combine Vishnu and Shiva in a single manifestation", "My name combines the Preserver and the Destroyer"]','["मैं दो परम देवताओं के एक रूप में एकत्व का प्रतीक हूँ", "मेरा स्वरूप पालन और संहार के संतुलन को दर्शाता है", "मुझे आधा एक और आधा दूसरे देवता के रूप में दर्शाया जाता है", "मैं विष्णु और शिव का संयुक्त रूप हूँ", "मेरा नाम पालनकर्ता और संहारकर्ता के मेल से बना है"]');
INSERT INTO clue_riddles VALUES(123,'RAMESWARAM','["A bridge to an island begins from my shores", "I am the southernmost of the Char Dham Yatra", "A god himself installed a sacred lingam here", "I am located in Tamil Nadu", "I am the place where Rama worshipped Shiva before battle"]','["मेरे तट से एक द्वीप तक का पुल शुरू होता है", "मैं चार धाम यात्रा में सबसे दक्षिणी धाम हूँ", "स्वयं एक भगवान ने यहाँ पवित्र लिंग स्थापित किया", "मैं तमिलनाडु में स्थित हूँ", "मैं वह स्थान हूँ जहाँ राम ने युद्ध से पहले शिव की पूजा की"]');
INSERT INTO clue_riddles VALUES(124,'AMRIT','["Gods and demons churned the ocean to obtain me", "I was stolen by demons moments after I appeared", "Vishnu took a female form to retrieve me", "Four drops of me fell at four sacred places on earth", "I am the nectar of immortality"]','["देवताओं और राक्षसों ने मुझे प्राप्त करने के लिए समुद्र मंथन किया", "मेरे प्रकट होते ही राक्षसों ने मुझे छीन लिया", "विष्णु ने मुझे वापस लेने के लिए स्त्री रूप धारण किया", "मेरी चार बूँदें पृथ्वी पर चार पवित्र स्थानों पर गिरीं", "मैं अमरत्व का पेय हूँ"]');
INSERT INTO clue_riddles VALUES(125,'BADRINATH','["I am open to pilgrims only a few months each year", "I sit between two mountain peaks called Nar and Narayan", "A sage meditated here for thousands of years", "I am one of the four sacred abodes in India", "I am the Himalayan temple of Lord Vishnu"]','["मैं तीर्थयात्रियों के लिए साल में केवल कुछ महीने खुलता हूँ", "मैं नर और नारायण नामक दो पर्वत शिखरों के बीच स्थित हूँ", "एक ऋषि ने यहाँ हजारों वर्षों तक तपस्या की", "मैं भारत के चार पवित्र धामों में से एक हूँ", "मैं हिमालय में भगवान विष्णु का मंदिर हूँ"]');
INSERT INTO clue_riddles VALUES(126,'DRONA','["I am the supreme teacher of warfare", "I taught both Kauravas and Pandavas", "I asked for a prince''s thumb as my fee", "I was born from a pot, not a womb", "I fell in battle when I heard my son had died"]','["मैं युद्ध कला का सर्वोच्च गुरु हूँ", "मैंने कौरवों और पांडवों दोनों को शिक्षा दी", "मैंने गुरु दक्षिणा में एक राजकुमार का अंगूठा माँगा", "मेरा जन्म गर्भ से नहीं, द्रोण (पात्र) से हुआ", "मैं अपने पुत्र की मृत्यु का समाचार सुनकर युद्ध में गिर गया"]');
INSERT INTO clue_riddles VALUES(127,'ATHARVA','["I am associated with knowledge that blends ritual, healing, and everyday life", "My hymns include spells, prayers, and practical wisdom", "I differ from other sacred collections by focusing on worldly concerns as well", "I am one among four ancient bodies of revealed knowledge", "I am the Veda linked with healing and mystic practices"]','["मैं ऐसे ज्ञान से जुड़ा हूँ जिसमें अनुष्ठान, उपचार और दैनिक जीवन का समावेश है", "मेरे मंत्रों में प्रार्थनाएँ, औषधीय ज्ञान और रहस्यमय विधियाँ शामिल हैं", "मैं अन्य ग्रंथों से अलग हूँ क्योंकि मैं सांसारिक विषयों पर भी ध्यान देता हूँ", "मैं चार प्राचीन वेदों में से एक हूँ", "मैं उपचार और रहस्यमय विधियों से जुड़ा वेद हूँ"]');
INSERT INTO clue_riddles VALUES(128,'KALKI','["I have not yet appeared on this earth", "I will come riding a white horse with a blazing sword", "I will end the current age of darkness and sin", "I am the tenth and final avatar", "I am Vishnu''s future incarnation who will restore Dharma"]','["मैं अभी तक इस पृथ्वी पर प्रकट नहीं हुआ", "मैं श्वेत अश्व पर सवार होकर प्रज्वलित तलवार लेकर आऊँगा", "मैं अंधकार और पाप के वर्तमान युग को समाप्त करूँगा", "मैं दसवाँ और अंतिम अवतार हूँ", "मैं विष्णु का भविष्य अवतार हूँ जो धर्म की पुनर्स्थापना करेगा"]');
INSERT INTO clue_riddles VALUES(129,'HAMPI','["I was once the second largest city in the world", "My ruins stretch across a boulder-strewn landscape", "A mighty empire ruled half of India from here", "I am the ruined capital of the Vijayanagara Empire", "I am a UNESCO World Heritage Site in Karnataka"]','["मैं कभी दुनिया का दूसरा सबसे बड़ा शहर था", "मेरे खंडहर पत्थरों से भरे भूदृश्य में फैले हैं", "एक शक्तिशाली साम्राज्य ने यहाँ से आधे भारत पर राज किया", "मैं विजयनगर साम्राज्य की ध्वस्त राजधानी हूँ", "मैं कर्नाटक में एक यूनेस्को विश्व धरोहर स्थल हूँ"]');
INSERT INTO clue_riddles VALUES(130,'ANNAPURNA','["I feed every hungry soul who comes to me", "Even the greatest ascetic had to seek food from me", "My kitchen in Kashi never runs empty", "I hold a golden ladle in one hand and a bowl in another", "I am the goddess of food and nourishment"]','["मैं हर भूखी आत्मा को भोजन देती हूँ जो मेरे पास आती है", "सबसे बड़े तपस्वी को भी मुझसे भोजन माँगना पड़ा", "काशी में मेरी रसोई कभी खाली नहीं होती", "एक हाथ में स्वर्ण कलछी और दूसरे में पात्र है", "मैं भोजन और पोषण की देवी हूँ"]');
INSERT INTO clue_riddles VALUES(131,'SITA','["I am a character in Ramayana", "I was found in a furrow of the earth", "I was kidnapped and taken to an island", "My husband is the king of Ayodhya", "I am the daughter of King Janaka"]','["मैं रामायण का एक पात्र हूँ", "मैं पृथ्वी की रेखा से प्रकट हुई", "मेरा अपहरण कर एक द्वीप पर ले जाया गया", "मेरे पति अयोध्या के राजा हैं", "मैं राजा जनक की पुत्री हूँ"]');
INSERT INTO clue_riddles VALUES(132,'HANUMAN','["I am a devoted servant", "I crossed an ocean in a single leap", "My father is the wind", "I set Lanka on fire with my own tail", "I carry a mountain in my hand"]','["मैं एक समर्पित सेवक हूँ", "मैंने एक ही छलांग में समुद्र पार किया", "मेरे पिता पवन देव हैं", "मैंने अपनी पूँछ से लंका में आग लगा दी", "मैं अपने हाथ में पर्वत उठाता हूँ"]');
INSERT INTO clue_riddles VALUES(133,'KASHI','["I am known as the City of Light", "My lanes are narrower than most but holier than all", "I am built on the trident of Shiva", "I am the ancient name of the city of light on the Ganga", "I am also known as Varanasi"]','["मैं प्रकाश के नगर के नाम से जाना जाता हूँ", "मेरी गलियाँ सबसे संकरी हैं पर सबसे पवित्र", "मैं शिव के त्रिशूल पर बसी हूँ", "मैं गंगा पर प्रकाश के नगर का प्राचीन नाम हूँ", "मैं वाराणसी के नाम से भी जाना जाता हूँ"]');
INSERT INTO clue_riddles VALUES(134,'ASHVINS','["We symbolize the transition from darkness to light at dawn", "We are the divine physicians of the Devas", "We are the twin Vedic gods of medicine and health", "We are the sons of the Sun God Surya and Saranya", "We are the spiritual fathers of Nakula and Sahadeva"]','["हम अंधकार से प्रकाश की ओर जाने वाली भोर के प्रतीक हैं", "हम देवताओं के दिव्य चिकित्सक के रूप में प्रसिद्ध हैं", "हम देवों के जुड़वां वैद्य और स्वास्थ्य के देवता हैं", "हम सूर्य देव और माता संज्ञा के पुत्र हैं", "हम पांडव नकुल और सहदेव के आध्यात्मिक पिता हैं"]');
INSERT INTO clue_riddles VALUES(135,'ELLORA','["I house caves carved by three different religions", "My greatest cave is carved from a single rock from top to bottom", "It took over a century to carve my most famous structure", "Hindu, Buddhist, and Jain artisans worked on me", "I am the rock-cut cave complex with the Kailasa temple"]','["मेरे अंदर तीन अलग-अलग धर्मों द्वारा तराशी गई गुफाएँ हैं", "मेरी सबसे बड़ी गुफा ऊपर से नीचे तक एक चट्टान से तराशी गई है", "मेरी सबसे प्रसिद्ध संरचना को तराशने में एक शताब्दी से अधिक लगा", "हिंदू, बौद्ध और जैन कारीगरों ने मुझ पर काम किया", "मैं कैलास मंदिर वाला शैलकृत गुफा परिसर हूँ"]');
INSERT INTO clue_riddles VALUES(136,'TAPAS','["I am a practice of intense discipline and austerity", "Through me, sages gain spiritual power and clarity", "My name implies heat or fire, symbolizing inner purification", "I involve meditation, restraint, and self-control", "In Patanjali''s Eight Limbs of Yoga, it is listed as one of the five Niyamas"]','["मैं कठोर साधना का अभ्यास हूँ", "मेरे माध्यम से ऋषि आध्यात्मिक शक्ति प्राप्त करते हैं", "मेरा अर्थ ऊष्मा या अग्नि है, जो आंतरिक शुद्धि का प्रतीक है", "मैं ध्यान, संयम और आत्मनियंत्रण से जुड़ा हूँ", "पतंजलि के अष्टांग योग में, इसे पांच ''नियमों'' में से एक माना गया है"]');
INSERT INTO clue_riddles VALUES(137,'BHAIRAV','["I guard the eight directions of the universe", "A dog is my constant companion and mount", "I punished even Brahma by cutting off his fifth head", "I am the fierce guardian of Kashi", "I am the terrifying form of Shiva"]','["मैं ब्रह्मांड की आठ दिशाओं की रक्षा करता हूँ", "कुत्ता मेरा स्थायी साथी और वाहन है", "मैंने ब्रह्मा का पाँचवाँ सिर काटकर उन्हें दंडित किया", "मैं काशी का उग्र संरक्षक हूँ", "मैं शिव का भयंकर रूप हूँ"]');
INSERT INTO clue_riddles VALUES(138,'CHAMUNDI','["I emerged to destroy demons that even gods could not defeat", "I killed two mighty brothers with different strategies", "A famous hill in Mysuru is named after me", "I wear the heads of my defeated enemies as a garland", "I am the form of Durga who slew Chanda and Munda"]','["मैं उन राक्षसों को नष्ट करने के लिए प्रकट हुई जिन्हें देवता भी नहीं हरा सके", "मैंने दो शक्तिशाली भाइयों को अलग-अलग रणनीतियों से मारा", "मैसूरु की एक प्रसिद्ध पहाड़ी मेरे नाम पर है", "मैं अपने पराजित शत्रुओं के सिरों की माला पहनती हूँ", "मैं दुर्गा का वह रूप हूँ जिसने चंड और मुंड का वध किया"]');
INSERT INTO clue_riddles VALUES(139,'KAILASH','["No human has ever reached my summit", "Four great rivers originate near me", "My reflection in a lake forms a swastika shape", "Hindus, Buddhists, Jains, and Bon followers all revere me", "I am the mountain abode of Lord Shiva"]','["कोई मनुष्य कभी मेरी चोटी पर नहीं पहुँचा", "चार महान नदियाँ मेरे निकट से निकलती हैं", "एक झील में मेरा प्रतिबिम्ब स्वस्तिक का आकार बनाता है", "हिंदू, बौद्ध, जैन और बोन अनुयायी सभी मुझे पूजते हैं", "मैं भगवान शिव का पर्वतीय निवास हूँ"]');
INSERT INTO clue_riddles VALUES(140,'TIRTHA','["I am a sacred place of pilgrimage", "I serve as a crossing between the earthly and the divine", "Rivers, temples, and holy sites are known by my name", "Pilgrims visit me for purification and spiritual merit", "My name implies a ford or a passage across"]','["मैं एक पवित्र स्थान हूँ", "मैं सांसारिक और दिव्य के बीच सेतु का कार्य करता हूँ", "नदियाँ, मंदिर और पवित्र स्थल मेरे नाम से जाने जाते हैं", "भक्त शुद्धि और पुण्य के लिए मेरे पास आते हैं", "मेरा अर्थ है पार करने का मार्ग या घाट"]');
INSERT INTO clue_riddles VALUES(141,'GANESHA','["I am worshipped before every new beginning", "I have the head of an elephant", "A mouse is my vehicle", "I love modak sweets", "My father gave me this head"]','["हर शुभ कार्य से पहले मेरी पूजा होती है", "मेरा सिर हाथी का है", "मूषक मेरा वाहन है", "मुझे मोदक बहुत प्रिय हैं", "मेरे पिता ने मुझे यह सिर दिया"]');
INSERT INTO clue_riddles VALUES(142,'PANCHANG','["I combine multiple celestial elements to determine auspicious timing", "My structure includes components like lunar day, star, and planetary positions", "Priests and astrologers consult me before important rituals and events", "I guide festivals, fasts, and daily spiritual practices", "I am a traditional Hindu calendar system"]','["मैं विभिन्न खगोलीय तत्वों को मिलाकर शुभ समय निर्धारित करता हूँ", "मेरे अंगों में तिथि, नक्षत्र और ग्रहों की स्थिति शामिल होती है", "पुजारी और ज्योतिषी महत्वपूर्ण कार्यों से पहले मुझसे परामर्श करते हैं", "मैं त्योहारों, व्रतों और दैनिक धार्मिक क्रियाओं का मार्गदर्शन करता हूँ", "मैं एक पारंपरिक हिंदू कैलेंडर हूँ"]');
INSERT INTO clue_riddles VALUES(143,'PIPLAAD','["I cursed Shani Dev for causing my childhood suffering and my father''s death", "I am a sage known from ancient Indian scriptures", "I was born under a Peepal tree, which gave me my name", "I am the author of the ''Prashna Upanishad''", "I am an incarnation of Lord Shiva and the son of Sage Dadhichi"]','["मैंने बचपन के कष्टों और पिता की मृत्यु के कारण शनि देव को श्राप दिया था", "मैं प्राचीन भारतीय शास्त्रों में वर्णित एक ऋषि हूँ", "मेरा जन्म एक पीपल के पेड़ के नीचे हुआ था, जिससे मुझे मेरा नाम मिला", "मैं ''प्रश्न उपनिषद'' का रचयिता हूँ", "मैं भगवान शिव का अवतार और महर्षि दधीचि का पुत्र हूँ"]');
INSERT INTO clue_riddles VALUES(144,'VASUKI','["I served as the great rope in a cosmic event involving gods and demons", "Wrapped around a mountain, I endured immense strain during a divine endeavor", "My role was central in the churning of the ocean for nectar", "I am the king of serpents in Hindu mythology", "I am the serpent used in Samudra Manthan"]','["मैं देवताओं और असुरों के बीच हुए एक महान कार्य में रस्सी बना था", "पर्वत के चारों ओर लिपटकर मैंने उस दिव्य प्रयास में कष्ट सहा", "अमृत प्राप्ति के लिए समुद्र मंथन में मेरी महत्वपूर्ण भूमिका थी", "मैं नागों का राजा हूँ", "मैं समुद्र मंथन में प्रयुक्त सर्प हूँ"]');
INSERT INTO clue_riddles VALUES(145,'KAMADHENU','["I am a cow that can grant any wish to my owner", "I emerged from the churning of the ocean", "Wars were fought between sages and kings over me", "I am the mother of all cattle", "I am also called Surabhi"]','["मैं एक गाय हूँ जो अपने स्वामी की हर इच्छा पूरी कर सकती हूँ", "मैं समुद्र मंथन से प्रकट हुई", "मेरे लिए ऋषियों और राजाओं के बीच युद्ध हुए", "मैं सभी गायों की माता हूँ", "मुझे सुरभि भी कहा जाता है"]');
INSERT INTO clue_riddles VALUES(146,'PUSHKAR','["A lotus dropped from a god''s hand created my lake", "I host the world''s largest camel fair", "I have the only temple in India dedicated to Brahma", "My lake has fifty-two bathing ghats", "I am the sacred lake town in Rajasthan"]','["एक देवता के हाथ से गिरे कमल ने मेरी झील बनाई", "मैं दुनिया का सबसे बड़ा ऊँट मेला आयोजित करता हूँ", "भारत में ब्रह्मा को समर्पित एकमात्र मंदिर मेरे पास है", "मेरी झील पर बावन स्नान घाट हैं", "मैं राजस्थान का पवित्र झील नगर हूँ"]');
INSERT INTO clue_riddles VALUES(147,'ASHRAMA','["I divide human life into structured phases guiding spiritual and social duties", "Each of my stages emphasizes different responsibilities and goals", "From learning to renunciation, I map the journey of life", "I include stages like Brahmacharya, Grihastha, Vanaprastha, and Sannyasa", "My name also refers to a hermitage"]','["मैं मानव जीवन को विभिन्न चरणों में विभाजित करता हूँ जो कर्तव्यों और धर्म का मार्ग दिखाते हैं", "मेरे प्रत्येक चरण में अलग-अलग जिम्मेदारियाँ और उद्देश्य होते हैं", "मैं शिक्षा से लेकर त्याग तक जीवन की यात्रा को दर्शाता हूँ", "मेरे अंतर्गत ब्रह्मचर्य, गृहस्थ, वानप्रस्थ और संन्यास आते हैं", "मेरा नाम एक जगह को भी संदर्भित करता है जहाँ ऋषि-मुनि तपस्या करते हैं"]');
INSERT INTO clue_riddles VALUES(148,'NALANDA','["I was the world''s first residential university", "Students from China, Korea, and Tibet came to study at me", "I was burned for months when invaders destroyed my library", "I had nine million manuscripts in my collection", "I am the ancient center of Buddhist and Hindu learning in Bihar"]','["मैं विश्व का पहला आवासीय विश्वविद्यालय था", "चीन, कोरिया और तिब्बत से विद्यार्थी मुझमें पढ़ने आते थे", "आक्रमणकारियों ने मेरे पुस्तकालय को जलाया जो महीनों तक जलता रहा", "मेरे संग्रह में नब्बे लाख पांडुलिपियाँ थीं", "मैं बिहार में बौद्ध और हिंदू शिक्षा का प्राचीन केंद्र हूँ"]');
INSERT INTO clue_riddles VALUES(149,'BRAHMA','["I have four faces looking in all directions", "I am the creator of the universe", "I sit on a lotus that grows from Vishnu", "A swan is my vehicle", "There is only one major temple dedicated to me"]','["मेरे चार मुख चारों दिशाओं में देखते हैं", "मैं सृष्टि का रचयिता हूँ", "मैं विष्णु से उत्पन्न कमल पर विराजमान हूँ", "हंस मेरा वाहन है", "मेरा केवल एक प्रमुख मंदिर है"]');
INSERT INTO clue_riddles VALUES(150,'VASUDEVA','["I am the brother of Kunti, making me the maternal uncle of the Pandavas", "I was imprisoned for years by my brother-in-law, the tyrant Kansa", "I am the husband of Devaki and Rohini", "I miraculously carried baby Krishna across the Yamuna in a basket", "I am a Yadava prince and the biological father of Lord Krishna"]','["मैं कुंती का भाई हूँ, इस नाते मैं पांडवों का मामा लगता हूँ", "मुझे मेरे साले कंस ने कई वर्षों तक कारागार में बंदी बनाकर रखा था", "मैं देवकी और रोहिणी का पति हूँ", "मैं नन्हे कृष्ण को टोकरी में रखकर चमत्कारिक रूप से यमुना पार ले गया था", "मैं एक यादव राजकुमार और भगवान कृष्ण का जन्मदाता पिता हूँ"]');
INSERT INTO clue_riddles VALUES(151,'BHUMI','["I am one of the five great elements", "I am the consort of Lord Vishnu''s Varaha avatar", "I am the mother of the demon Narakasura", "I am the personification of Mother Earth", "I am the mother of Goddess Sita"]','["मैं पंचमहाभूतों में से एक हूँ", "मैं भगवान विष्णु के वराह अवतार की पत्नी हूँ", "मैं नरकासुर की माता और धैर्य का प्रतीक हूँ", "मैं धरती माता और पृथ्वी का साक्षात स्वरूप हूँ", "मैं माता सीता की जननी और उनका आधार हूँ"]');
INSERT INTO clue_riddles VALUES(152,'GIRNAR','["Ten thousand steps lead to my sacred summit", "Emperor Ashoka inscribed edicts on my rocks", "Hindus and Jains both worship at my peaks", "Dattatreya meditated on my highest point", "I am the sacred mountain in Gujarat"]','["दस हजार सीढ़ियाँ मेरे पवित्र शिखर तक जाती हैं", "सम्राट अशोक ने मेरी चट्टानों पर शिलालेख खुदवाए", "हिंदू और जैन दोनों मेरे शिखरों पर पूजा करते हैं", "दत्तात्रेय ने मेरे सर्वोच्च बिंदु पर ध्यान किया", "मैं गुजरात का पवित्र पर्वत हूँ"]');
INSERT INTO clue_riddles VALUES(153,'KUMBHMELA','["I am a massive spiritual gathering that occurs at specific intervals based on celestial alignments", "Millions of devotees assemble at sacred riverbanks to participate in me", "My origins are linked to a myth involving a pot of divine nectar", "Ritual bathing during me is believed to cleanse sins and grant spiritual merit", "I am one of the largest religious gatherings in the world"]','["मैं एक विशाल आध्यात्मिक आयोजन हूँ जो ग्रह-नक्षत्रों की स्थिति के अनुसार होता है", "मेरे दौरान लाखों श्रद्धालु पवित्र नदियों के तट पर एकत्रित होते हैं", "मेरा संबंध अमृत कलश की पौराणिक कथा से है", "मेरे समय स्नान करना पापों से मुक्ति और पुण्य प्रदान करने वाला माना जाता है", "मैं दुनिया के सबसे बड़े धार्मिक आयोजनों में से एक हूँ"]');
INSERT INTO clue_riddles VALUES(154,'NARMADA','["I am the only river in India that is circumambulated", "Every stone in my riverbed is considered sacred", "I am older than the Ganga according to legends", "My pebbles are naturally shaped like Shiva lingams", "I am the lifeline of Madhya Pradesh"]','["मैं भारत की एकमात्र नदी हूँ जिसकी परिक्रमा की जाती है", "मेरे तल का हर पत्थर पवित्र माना जाता है", "किंवदंतियों के अनुसार मैं गंगा से भी पुरानी हूँ", "मेरे कंकड़ प्राकृतिक रूप से शिवलिंग के आकार के होते हैं", "मैं मध्य प्रदेश की जीवन रेखा हूँ"]');
INSERT INTO clue_riddles VALUES(155,'VYASA','["I divided one Veda into four parts", "I am the biological father of three royal sons", "I dictated the longest epic ever written", "Ganesha was my scribe", "I composed the Mahabharata"]','["मैंने एक वेद को चार भागों में विभाजित किया", "मैं तीन राजपुत्रों का जैविक पिता हूँ", "मैंने अब तक लिखे सबसे लंबे महाकाव्य का वाचन किया", "गणेश मेरे लेखक थे", "मैंने महाभारत की रचना की"]');
INSERT INTO clue_riddles VALUES(156,'RUDRAKSH','["I was born from the tears of meditation", "My faces can range from one to twenty-one", "Wearing me brings peace and protection", "I am strung into malas of one hundred and eight beads", "I am the sacred seed bead worn by Shiva devotees"]','["मेरा जन्म ध्यान के आँसुओं से हुआ", "मेरे मुख एक से इक्कीस तक हो सकते हैं", "मुझे पहनने से शांति और सुरक्षा मिलती है", "मुझे एक सौ आठ मनकों की माला में पिरोया जाता है", "मैं शिव भक्तों द्वारा पहना जाने वाला पवित्र बीज मनका हूँ"]');
INSERT INTO clue_riddles VALUES(157,'TULSI','["I am found in the courtyard of almost every Hindu home", "I am worshipped every evening with a lamp", "My leaves are offered to Vishnu in every puja", "I am considered the most sacred plant in Hinduism", "My stems are used to make beads for japa malas"]','["मैं लगभग हर हिंदू घर के आँगन में पाई जाती हूँ", "हर शाम मेरे सामने दीपक जलाकर मेरी पूजा होती है", "हर पूजा में मेरे पत्ते विष्णु को अर्पित किए जाते हैं", "हिंदू धर्म में मुझे सबसे पवित्र पौधा माना जाता है", "मेरे तनों का उपयोग जप माला के लिए मनके बनाने के लिए किया जाता है"]');
INSERT INTO clue_riddles VALUES(158,'LAKSHMI','["I emerged from the ocean of milk", "I am the goddess of wealth and fortune", "An owl is one of my symbols", "I am worshipped on Diwali night", "I sit on a lotus flower"]','["मैं क्षीरसागर से प्रकट हुई", "मैं धन और सौभाग्य की देवी हूँ", "उल्लू मेरा एक प्रतीक है", "दीपावली की रात मेरी पूजा होती है", "मैं कमल के फूल पर विराजमान हूँ"]');
INSERT INTO clue_riddles VALUES(159,'SUDARSHAN','["I spin faster than anything in the universe", "I have one hundred and eight serrated edges", "I return to my master after every strike", "I severed the head of a demon during a sacrifice", "I am the divine discus weapon of Lord Vishnu"]','["मैं ब्रह्मांड में किसी भी चीज़ से तेज़ घूमता हूँ", "मेरे एक सौ आठ दाँतेदार किनारे हैं", "हर प्रहार के बाद मैं अपने स्वामी के पास लौट आता हूँ", "मैंने एक यज्ञ के दौरान एक राक्षस का सिर काटा", "मैं भगवान विष्णु का दिव्य चक्र हूँ"]');
INSERT INTO clue_riddles VALUES(160,'GANDIVA','["I was gifted by the fire god after a forest was burned", "I never miss my target when my master wields me", "Brahma created me and I passed through many divine hands", "Two inexhaustible quivers accompany me always", "I am the legendary bow of Arjuna"]','["अग्नि देव ने एक वन दहन के बाद मुझे उपहार में दिया", "जब मेरा स्वामी मुझे चलाता है तो मैं कभी चूकता नहीं", "ब्रह्मा ने मुझे बनाया और मैं कई दिव्य हाथों से गुज़रा", "दो अक्षय तूणीर सदा मेरे साथ रहते हैं", "मैं अर्जुन का पौराणिक धनुष गांडीव हूँ"]');
INSERT INTO clue_riddles VALUES(161,'GAURI','["I represent purity, grace, and the gentle aspect of a powerful goddess", "My name is often associated with fair complexion and auspiciousness", "I am worshipped especially by married women for marital happiness", "I am another form of Parvati, the consort of Shiva", "The sacred hot water spring and the final motorable base camp for the Kedarnath trek is named after me."]','["मैं पवित्रता, सौम्यता और एक शक्तिशाली देवी के कोमल रूप का प्रतीक हूँ", "मेरा नाम गौर वर्ण और शुभता से जुड़ा है", "मुझे विशेष रूप से विवाहित महिलाएँ सौभाग्य के लिए पूजती हैं", "मैं पार्वती का एक रूप हूँ जो शिव की पत्नी हैं", "केदारनाथ यात्रा का अंतिम मोटर योग्य बेस कैंप और एक पवित्र गर्म पानी का कुंड इन्हीं के नाम पर है"]');
INSERT INTO clue_riddles VALUES(162,'TRISHUL','["I have three prongs representing creation, preservation, and destruction", "I destroyed the three flying cities of demons", "I am held by the most powerful deity in the cosmos", "My three points also symbolize past, present, and future", "I am the trident weapon of Lord Shiva"]','["मेरे तीन फल सृष्टि, पालन और विनाश का प्रतीक हैं", "मैंने राक्षसों के तीन उड़ने वाले नगरों को नष्ट किया", "ब्रह्मांड का सबसे शक्तिशाली देवता मुझे धारण करता है", "मेरे तीन बिंदु भूत, वर्तमान और भविष्य का भी प्रतीक हैं", "मैं भगवान शिव का अस्त्र हूँ"]');
INSERT INTO clue_riddles VALUES(163,'ASHTAMI','["I occur as a specific phase within both halves of a lunar cycle", "Many important fasts and celebrations are observed on my day", "I fall on the eighth day of the waxing and waning moon", "I am associated with festivals dedicated to powerful deities", "I am a significant lunar date in the Hindu calendar"]','["मैं चंद्र मास के दोनों पक्षों में आने वाली एक विशेष तिथि हूँ", "मेरे दिन कई महत्वपूर्ण व्रत और त्योहार मनाए जाते हैं", "मैं शुक्ल और कृष्ण पक्ष की आठवीं तिथि होती हूँ", "मेरा संबंध शक्तिशाली देवताओं के उत्सवों से है", "मैं हिंदू पंचांग की एक महत्वपूर्ण तिथि हूँ"]');
INSERT INTO clue_riddles VALUES(164,'VAJRA','["I am made from the bones of a sage who sacrificed himself", "I am both a thunderbolt and an unbreakable diamond", "I shattered a demon that had swallowed all the waters", "I am the most feared weapon in the heavens", "I am the thunderbolt weapon of Lord Indra"]','["मैं एक ऋषि की हड्डियों से बना हूँ जिन्होंने आत्मबलिदान किया", "मैं वज्र भी हूँ और अटूट हीरा भी", "मैंने उस राक्षस को चूर किया जिसने सारा जल निगल लिया था", "मैं स्वर्ग का सबसे भयंकर अस्त्र हूँ", "मैं भगवान इंद्र का वज्र अस्त्र हूँ"]');
INSERT INTO clue_riddles VALUES(165,'DIWALI','["A prince returned home after fourteen years on this day", "Goddess Lakshmi is worshipped on my darkest night", "I am celebrated with millions of oil lamps and firecrackers", "I mark the victory of light over darkness", "I am the festival of lights"]','["एक राजकुमार इस दिन चौदह वर्ष बाद घर लौटे", "मेरी सबसे अंधेरी रात को देवी लक्ष्मी की पूजा होती है", "मुझे लाखों दीपकों और पटाखों से मनाया जाता है", "मैं अंधकार पर प्रकाश की विजय का प्रतीक हूँ", "मैं दीपों का त्योहार हूँ"]');
INSERT INTO clue_riddles VALUES(166,'TRIMURTI','["I represent the threefold manifestation of the divine governing creation, preservation, and dissolution", "My concept unites different cosmic functions into a single philosophical understanding", "I embody the cyclical nature of existence through three distinct forms", "I include Brahma, Vishnu, and Shiva", "I simply mean three forms of one supreme reality"]','["मैं सृष्टि, पालन और संहार की तीन दिव्य शक्तियों का समेकित रूप हूँ", "मेरा सिद्धांत विभिन्न ब्रह्मांडीय कार्यों को एक समझ में जोड़ता है", "मैं अस्तित्व के चक्र को तीन रूपों में दर्शाता हूँ", "मेरे अंतर्गत ब्रह्मा, विष्णु और शिव आते हैं", "मैं सरल रूप में एक ही परम सत्य के तीन रूप हूँ"]');
INSERT INTO clue_riddles VALUES(167,'PONGAL','["I am a harvest festival celebrated in South India", "I honor the Sun God for agricultural abundance", "I am named after a sweet dish cooked during my celebration", "I last for four days with rituals like Bhogi", "I am celebrated in the month of January"]','["मैं दक्षिण भारत में मनाया जाने वाला एक फसल उत्सव हूँ", "मैं सूर्य देव को समर्पित हूँ", "मेरा नाम एक विशेष मीठे पकवान पर रखा गया है", "मैं चार दिनों तक मनाया जाता हूँ, जैसे भोगी", "मैं जनवरी के महीने में मनाया जाता हूँ"]');
INSERT INTO clue_riddles VALUES(168,'VEDAS','["I am the oldest body of sacred knowledge revealed to ancient seers", "My verses were preserved through oral tradition across generations", "I form the foundation of rituals, philosophy, and spiritual understanding", "I am divided into four collections including Rig, Sama, Yajur, and Atharva", "I am the primary scriptures of Hinduism"]','["मैं प्राचीन ऋषियों को प्राप्त सबसे प्राचीन दिव्य ज्ञान हूँ", "मेरे मंत्र पीढ़ियों तक मौखिक परंपरा से संरक्षित रहे", "मैं अनुष्ठानों, दर्शन और आध्यात्मिक समझ की आधारशिला हूँ", "मैं चार भागों में विभाजित हूँ—ऋग, साम, यजुर और अथर्व", "मैं हिंदू धर्म के प्रमुख शास्त्र हूँ"]');
INSERT INTO clue_riddles VALUES(169,'RAMAYANA','["I was born from the grief of a sage who saw a bird killed", "I tell the journey of a prince exiled for fourteen years", "I have been retold in every language of South and Southeast Asia", "Valmiki composed me as the first poem ever written", "I am the great epic of Lord Rama"]','["मेरा जन्म एक ऋषि के दुख से हुआ जिन्होंने एक पक्षी को मारते देखा", "मैं चौदह वर्ष के वनवास पर भेजे गए एक राजकुमार की यात्रा कथा हूँ", "मुझे दक्षिण और दक्षिण-पूर्व एशिया की हर भाषा में दोहराया गया है", "वाल्मीकि ने मुझे प्रथम काव्य के रूप में रचा", "मैं भगवान राम का महान महाकाव्य हूँ"]');
INSERT INTO clue_riddles VALUES(170,'BELPATRA','["I am a sacred offering usually appearing as three leaves", "I am especially dear to a deity associated with asceticism and destruction", "Devotees place me on a symbolic form during worship rituals", "My leaves are believed to purify and please the divine", "I am a sacred leaf offered to Lord Shiva"]','["मैं एक पवित्र पत्ता हूँ जो अक्सर तीन पत्तियों के रूप में दिखाई देता हूँ", "मैं विशेष रूप से एक ऐसे देवता को प्रिय हूँ जो तपस्या और संहार से जुड़े हैं", "भक्त मुझे पूजा के दौरान एक प्रतीकात्मक रूप पर चढ़ाते हैं", "मेरी पत्तियाँ शुद्धि और ईश्वर को प्रसन्न करने वाली मानी जाती हैं", "मैं भगवान शिव को अर्पित किया जाने वाला पवित्र पत्ता हूँ"]');
INSERT INTO clue_riddles VALUES(171,'VEENA','["I am held by the goddess of knowledge and arts", "My resonance is said to mimic the sound of creation", "I have gourds at both ends of my long neck", "Sage Narada carries me wherever he goes", "I am the ancient stringed instrument of Saraswati"]','["मुझे ज्ञान और कला की देवी धारण करती हैं", "कहा जाता है कि मेरी गूँज सृष्टि की ध्वनि की नकल करती है", "मेरे लंबे डंड के दोनों छोर पर तुम्बे हैं", "नारद ऋषि मुझे जहाँ भी जाते हैं साथ ले जाते हैं", "मैं सरस्वती का प्राचीन तंतु वाद्य यंत्र हूँ"]');
INSERT INTO clue_riddles VALUES(172,'DAMARU','["My beats created the sounds of the Sanskrit alphabet", "I am shaped like two triangles joined at their tips", "I am played by shaking, not by striking", "The Maheshwara Sutras emerged from my fourteen beats", "I am the hand drum of Lord Shiva"]','["मेरी ध्वनि से संस्कृत वर्णमाला के स्वर उत्पन्न हुए", "मेरा आकार दो त्रिकोणों के शीर्षों पर जुड़े जैसा है", "मुझे थपकी से नहीं हिलाकर बजाया जाता है", "माहेश्वर सूत्र मेरे चौदह बोलों से निकले", "मैं भगवान शिव का हस्त ढोल हूँ"]');
INSERT INTO clue_riddles VALUES(173,'GARUDA','["I was born from an egg that glowed like the sun", "I freed my mother from slavery by stealing nectar", "Serpents flee at the mere sight of me", "I am the king of all birds in Hindu mythology", "I am the divine eagle mount of Lord Vishnu"]','["मेरा जन्म सूर्य जैसे चमकते अंडे से हुआ", "मैंने अमृत चुराकर अपनी माता को दासता से मुक्त किया", "साँप मुझे देखते ही भाग जाते हैं", "मैं हिंदू पुराणों में सभी पक्षियों का राजा हूँ", "मैं भगवान विष्णु का दिव्य गरुड़ वाहन हूँ"]');
INSERT INTO clue_riddles VALUES(174,'SHESHA','["I have a thousand heads with a thousand crowns", "I hold all the planets of the universe on my hoods", "Vishnu sleeps on my coiled body in the cosmic ocean", "I am the first being created and the last to remain", "I am the infinite serpent on whom Vishnu rests"]','["मेरे हजार सिर हैं और हजार मुकुट", "मैं अपने फनों पर ब्रह्मांड के सभी ग्रह धारण करता हूँ", "विष्णु क्षीर सागर में मेरे कुंडलित शरीर पर सोते हैं", "मैं सबसे पहले बनाया गया और सबसे अंत तक रहूँगा", "मैं वह अनंत सर्प हूँ जिस पर विष्णु विश्राम करते हैं"]');
INSERT INTO clue_riddles VALUES(175,'YAMA','["I was the first mortal to ever die", "I ride a black buffalo and carry a noose", "My sister celebrates my visit once a year during Bhai Dooj", "I judge every soul based on their deeds in life", "I am the god of death and dharma"]','["मैं पहला नश्वर प्राणी था जिसकी मृत्यु हुई", "मैं काली भैंस पर सवार होता हूँ और पाश रखता हूँ", "मेरी बहन हर वर्ष भाई दूज पर मेरी यात्रा का उत्सव मनाती है", "मैं हर आत्मा को उसके जीवन के कर्मों के आधार पर न्याय करता हूँ", "मैं मृत्यु और धर्म का देवता हूँ"]');
INSERT INTO clue_riddles VALUES(176,'CHANDRA','["I was cursed to wane because of favoritism among my wives", "I married twenty-seven star maidens but loved one the most", "Shiva wears me as an ornament on his head", "My waxing and waning controls the tides and moods", "I am the moon god"]','["मुझे मेरी पत्नियों में पक्षपात के कारण क्षीण होने का श्राप मिला", "मैंने सत्ताईस नक्षत्र कन्याओं से विवाह किया पर एक से सबसे अधिक प्रेम किया", "शिव मुझे अपने सिर पर आभूषण के रूप में धारण करते हैं", "मेरा बढ़ना और घटना ज्वार और मनोदशा को नियंत्रित करता है", "मैं निशाकर हूँ"]');
INSERT INTO clue_riddles VALUES(177,'BUDH','["I am the child of a forbidden union between the moon and a star", "I represent intellect and communication", "I am considered the wisest among the nine celestial bodies", "Wednesday is my sacred day", "I am the first planet from the sun"]','["मैं चंद्रमा और एक तारे के निषिद्ध मिलन की संतान हूँ", "मैं बुद्धि और संवाद का प्रतीक हूँ", "नौ ग्रहों में मुझे सबसे बुद्धिमान माना जाता है", "बुधवार मेरा पवित्र दिन है", "मैं सूर्य से पहला ग्रह हूँ"]');
INSERT INTO clue_riddles VALUES(178,'RAHU','["I was beheaded but my head became immortal", "I swallow the sun and moon causing eclipses", "I sneaked into the line of gods during nectar distribution", "Vishnu''s discus cut me in two but I survived", "Along with Ketu, I form the two halves of a single entity"]','["मेरा सिर काटा गया पर मेरा सिर अमर हो गया", "मैं सूर्य और चंद्रमा को निगलकर ग्रहण करता हूँ", "अमृत वितरण के दौरान मैं देवताओं की पंक्ति में घुस गया", "विष्णु के चक्र ने मुझे दो टुकड़ों में काटा पर मैं बचा", "केतु के साथ मिलकर मैं एक ही अस्तित्व के दो भाग हूँ"]');
INSERT INTO clue_riddles VALUES(179,'KAMAKHYA','["My temple has no idol but a natural rock formation", "I am one of the most powerful Shakti Peethas", "My temple closes for three days when the goddess bleeds", "I sit atop Nilachal Hill in Assam", "I am the tantric goddess temple of Assam"]','["मेरे मंदिर में कोई मूर्ति नहीं बल्कि एक प्राकृतिक शिला है", "मैं सबसे शक्तिशाली शक्तिपीठों में से एक हूँ", "देवी के रक्तस्राव के समय मेरा मंदिर तीन दिन बंद रहता है", "मैं असम की नीलाचल पहाड़ी पर स्थित हूँ", "मैं असम का तांत्रिक देवी मंदिर हूँ"]');
INSERT INTO clue_riddles VALUES(180,'SHAKTI','["I represent the divine feminine energy of the universe", "Without me even the greatest gods are powerless", "I manifest in countless forms from gentle to fierce", "I am worshipped in forms like Durga, Kali, and Parvati", "Without me, even Shiva is said to be incomplete"]','["मैं ब्रह्मांड की दिव्य स्त्री ऊर्जा का प्रतीक हूँ", "मेरे बिना महानतम देवता भी बलहीन हैं", "मैं सौम्य से उग्र तक अनगिनत रूपों में प्रकट होती हूँ", "मुझे दुर्गा, काली और पार्वती के रूप में पूजा जाता है", "मेरे बिना शिव भी अपूर्ण माने जाते हैं"]');
INSERT INTO clue_riddles VALUES(181,'MARUTI','["I am often used to refer to the son of the Wind God", "I am the son of Anjana", "I symbolize strength, speed, and devotion", "I am known as Hanuman or Bajrangbali", "I represent courage and unwavering service to Lord Rama"]','["मुझे वायु पुत्र के रूप में भी जाना जाता है", "मैं अंजना का पुत्र हूँ", "मैं शक्ति, गति और भक्ति का प्रतीक हूँ", "मैं हनुमान या बजरंगबली के नाम से जाना जाता हूँ", "मैं भगवान राम के प्रति साहस और अटूट सेवा का प्रतीक हूँ"]');
INSERT INTO clue_riddles VALUES(182,'NARASIMHA','["I appeared from a pillar to prove God is everywhere", "I killed a demon at twilight, neither day nor night", "I placed my enemy on my lap, neither earth nor sky", "I used my bare claws, no weapon made of metal or wood", "I am the half-man half-lion avatar of Vishnu"]','["मैं एक स्तंभ से प्रकट हुआ यह सिद्ध करने कि ईश्वर सर्वत्र है", "मैंने संध्या काल में एक राक्षस को मारा, न दिन न रात", "मैंने अपने शत्रु को गोद में रखा, न पृथ्वी न आकाश", "मैंने अपने नंगे पंजों का उपयोग किया, कोई धातु या लकड़ी का हथियार नहीं", "मैं विष्णु का नर-सिंह अवतार हूँ"]');
INSERT INTO clue_riddles VALUES(183,'MADRI','["I am a character from the Mahabharata", "Through divine invocation, I became the mother of twin sons", "My children are known for their beauty and skill among the Pandavas", "I chose to follow my husband in death rather than live on", "I am the second wife of Pandu"]','["मैं महाभारत की एक पात्र हूँ", "दिव्य आह्वान के माध्यम से मैं जुड़वां पुत्रों की माता बनी", "मेरे पुत्र पांडवों में अपने रूप और कौशल के लिए प्रसिद्ध हैं", "मैंने अपने पति के साथ मृत्यु को चुन लिया", "मैं पांडु की दूसरी पत्नी हूँ"]');
INSERT INTO clue_riddles VALUES(184,'SHYAM','["My name means dark or dusky in complexion", "Devotees call me with love in bhajans and kirtans", "I am associated with charm, compassion, and divine play", "I am a beloved name of Lord Krishna", "I am often paired with Radha in devotion"]','["मेरा अर्थ है सांवला या श्याम वर्ण", "भक्त मुझे प्रेम से भजन और कीर्तन में पुकारते हैं", "मैं आकर्षण, करुणा और दिव्य लीला से जुड़ा हूँ", "मैं भगवान कृष्ण का प्रिय नाम हूँ", "मेरा नाम राधा के साथ अक्सर लिया जाता है"]');
INSERT INTO clue_riddles VALUES(185,'PADMANABHA','["I recline on the cosmic serpent in an ocean of milk", "A lotus grows from my navel bearing the creator god", "My temple in Kerala holds unimaginable treasure", "I am the presiding deity of Travancore", "I am Vishnu in the form from whose navel a lotus springs"]','["मैं क्षीरसागर में दिव्य सर्प पर लेटा हूँ", "मेरी नाभि से एक कमल उगता है जिस पर सृष्टिकर्ता विराजते हैं", "केरल में मेरे मंदिर में अकल्पनीय खजाना है", "मैं त्रावणकोर के अधिष्ठाता देवता हूँ", "मैं विष्णु का वह रूप हूँ जिनकी नाभि से कमल प्रकट होता है"]');
INSERT INTO clue_riddles VALUES(186,'YAMUNOTRI','["I am the source of the river that Krishna played in", "I sit near a glacier at over ten thousand feet", "Hot springs near me allow pilgrims to cook rice", "I am the first stop of the Chota Char Dham pilgrimage", "I am the origin temple of the river Yamuna"]','["मैं उस नदी का स्रोत हूँ जिसमें कृष्ण खेला करते थे", "मैं दस हजार फुट से अधिक ऊँचाई पर एक हिमनद के निकट स्थित हूँ", "मेरे निकट गर्म जलधाराएँ तीर्थयात्रियों को चावल पकाने देती हैं", "मैं छोटा चार धाम यात्रा का पहला पड़ाव हूँ", "मैं यमुना नदी का उद्गम मंदिर हूँ"]');
INSERT INTO clue_riddles VALUES(187,'SADHANA','["I am a disciplined path followed for spiritual growth", "I involve practices like meditation, mantra, and devotion", "Through me, a seeker moves closer to self-realization", "Saints and yogis rely on me to attain higher states of consciousness", "I simply mean a dedicated spiritual practice"]','["मैं आध्यात्मिक उन्नति के लिए अपनाया गया अनुशासित मार्ग हूँ", "मैं ध्यान, मंत्र और भक्ति से जुड़ी हूँ", "मेरे माध्यम से साधक आत्म-साक्षात्कार के निकट पहुँचता है", "संत और योगी उच्च चेतना प्राप्त करने के लिए मुझ पर निर्भर रहते हैं", "मैं सरल रूप में एक समर्पित आध्यात्मिक अभ्यास हूँ"]');
INSERT INTO clue_riddles VALUES(188,'NAVARATRI','["I last for nine nights dedicated to the divine feminine", "Each of my nine nights worships a different form of the goddess", "Garba and Dandiya dances are performed during me", "I culminate on the tenth day called Vijayadashami", "I am the nine-night festival celebrating Goddess Durga"]','["मैं दिव्य स्त्री शक्ति को समर्पित नौ रातों तक चलता हूँ", "मेरी प्रत्येक नौ रातों में देवी के एक अलग रूप की पूजा होती है", "मेरे दौरान गरबा और डांडिया नृत्य किए जाते हैं", "मैं दसवें दिन विजयादशमी पर समाप्त होता हूँ", "मैं देवी दुर्गा का नौ रातों का उत्सव हूँ"]');
INSERT INTO clue_riddles VALUES(189,'BHAGIRATH','["I convinced the heavenly river to descend to earth", "I asked Shiva to catch the falling river in his hair", "I led the river through plains to the ocean", "I am the king who brought the Ganga down to earth", "Ganga, at its origin is named after me"]','["मैंने स्वर्गीय नदी को पृथ्वी पर उतरने के लिए मनाया", "मैंने शिव से गिरती नदी को अपनी जटाओं में रोकने का अनुरोध किया", "मैंने नदी का मैदानों से समुद्र तक नेतृत्व किया", "मैं वह राजा हूँ जो गंगा को पृथ्वी पर लाया", "गंगोत्री में गंगा को मेरे नाम से जाना जाता है"]');
INSERT INTO clue_riddles VALUES(190,'MADURAI','["I hosted twenty-eight Tamil literary gatherings called Sangams", "Lord Shiva performed sixty-four divine sports in my streets", "I lie on the banks of the Vaigai River", "I am called the cultural capital of Tamil Nadu", "I am famous for the Meenakshi Amman Temple"]','["मैंने संगम नामक अट्ठाईस तमिल साहित्यिक सभाओं की मेजबानी की", "शिव ने मेरी गलियों में चौसठ दिव्य लीलाएँ कीं", "मैं वैगई नदी के तट पर स्थित हूँ", "मुझे तमिलनाडु की सांस्कृतिक राजधानी कहा जाता है", "मैं मीनाक्षी अम्मन मंदिर के लिए प्रसिद्ध हूँ"]');
INSERT INTO clue_riddles VALUES(191,'MAHISHASUR','["I received a boon that no man or god could kill me", "I conquered all three worlds through my power", "I assumed the form of a buffalo in battle", "The gods combined their powers to create my slayer", "I am the buffalo demon killed by goddess Durga"]','["मुझे वरदान था कि न कोई पुरुष न देवता मुझे मार सके", "मैंने अपनी शक्ति से तीनों लोकों पर विजय प्राप्त की", "मैंने युद्ध में भैंसे का रूप धारण किया", "देवताओं ने मुझे मारने के लिए अपनी शक्तियाँ मिलाकर मेरी संहारक बनाई", "मैं देवी दुर्गा द्वारा मारा गया महिष राक्षस हूँ"]');
INSERT INTO clue_riddles VALUES(192,'PUSHPAKA','["I was built by the divine architect for the god of wealth", "I was seized by Ravana from his own brother", "I can fly anywhere at the speed of thought", "I expand to fit any number of passengers", "I am the flying chariot that Rama used to return to Ayodhya"]','["दिव्य वास्तुकार ने मुझे धन के देवता के लिए बनाया", "रावण ने मुझे अपने ही भाई से छीना", "मैं विचार की गति से कहीं भी उड़ सकता हूँ", "मैं कितने भी यात्रियों के लिए विस्तारित हो सकता हूँ", "मैं वह उड़ने वाला रथ हूँ जिससे राम अयोध्या लौटे"]');
INSERT INTO clue_riddles VALUES(193,'NIRVANA','["I am the ultimate state where the cycle of birth and death ceases completely", "I represent the extinguishing of desire, attachment, and ego", "Sages and seekers strive for me through deep meditation and discipline", "I am beyond suffering, illusion, and worldly existence", "I am the highest state of liberation and peace"]','["मैं वह अंतिम अवस्था हूँ जहाँ जन्म और मृत्यु का चक्र पूरी तरह समाप्त हो जाता है", "मैं इच्छा, आसक्ति और अहंकार के पूर्ण नाश का प्रतीक हूँ", "ऋषि और साधक मुझे पाने के लिए गहन ध्यान और साधना करते हैं", "मैं दुख, माया और सांसारिक बंधनों से परे हूँ", "मैं मुक्ति और शांति की सर्वोच्च अवस्था हूँ"]');
INSERT INTO clue_riddles VALUES(194,'MURUGAN','["I was raised by six mothers called the Krittikas", "I ride a peacock into battle against demons", "I was created specifically to kill a demon named Tarakasura", "I am the warrior son of Shiva and Parvati", "I am also known as Kartikeya"]','["मुझे कृत्तिका नामक छह माताओं ने पाला", "मैं मोर पर सवार होकर राक्षसों से युद्ध करता हूँ", "मुझे विशेष रूप से तारकासुर नामक राक्षस को मारने के लिए बनाया गया", "मैं शिव और पार्वती का योद्धा पुत्र हूँ", "मुझे कार्तिकेय के नाम से भी जाना जाता है"]');
INSERT INTO clue_riddles VALUES(195,'VANARA','["I belong to a forest-dwelling race in the Ramayana", "I am known for strength, agility, and loyalty", "I served under kings like Sugriva and Bali", "My army helped Lord Rama in his quest to rescue Sita", "Hanuman is the most famous among us"]','["मैं रामायण में वन में रहने वाली एक जाति से हूँ", "मैं अपनी शक्ति, फुर्ती और निष्ठा के लिए जाना जाता हूँ", "मैं सुग्रीव और बाली जैसे राजाओं के अधीन रहा", "मेरी सेना ने सीता की खोज में राम की सहायता की", "हनुमान हममें सबसे प्रसिद्ध हैं"]');
INSERT INTO clue_riddles VALUES(196,'KAURAVAS','["I represent a large group of royal brothers central to a great epic conflict", "Born to a blind king, my members were raised in rivalry and ambition", "My leader is known for his jealousy and refusal to share power", "I opposed the Pandavas in a legendary war", "I am the hundred sons of Dhritarashtra"]','["मैं राजकुमारों का वह समूह हूँ जो एक महान युद्ध के केंद्र में था", "मैं अंधे राजा के पुत्रों के रूप में जन्मा और प्रतिद्वंद्विता में पला-बढ़ा", "मेरा प्रमुख अपने ईर्ष्या और सत्ता न छोड़ने के स्वभाव के लिए जाना जाता है", "मैंने पांडवों के विरुद्ध युद्ध किया", "मैं धृतराष्ट्र के सौ पुत्र हूँ"]');
INSERT INTO clue_riddles VALUES(197,'AMBA','["I was abducted on my wedding day against my will in Mahabharata", "I was rejected by both my captor and my beloved", "I swore revenge against Bhishma who ruined my life", "I performed fierce penance to be reborn as a warrior", "I was reborn as Shikhandi to destroy Bhishma"]','["महाभारत में मेरे विवाह के दिन मुझे मेरी इच्छा के विरुद्ध अपहरण किया गया", "मेरे अपहर्ता और मेरे प्रियतम दोनों ने मुझे अस्वीकार किया", "मैंने भीष्म से बदला लेने की शपथ ली जिसने मेरा जीवन बर्बाद किया", "मैंने योद्धा के रूप में पुनर्जन्म लेने के लिए कठोर तपस्या की", "भीष्म को नष्ट करने के लिए मैं शिखंडी के रूप में पुनर्जन्मी"]');
INSERT INTO clue_riddles VALUES(198,'REVATI','["My father took me to Brahma to find a suitable husband", "Millions of years passed on earth while we waited", "I married the elder brother of Krishna", "I am the wife of Balarama who travelled through time", "I am also referred to as 27th Nakshatra"]','["मेरे पिता मुझे उपयुक्त वर खोजने ब्रह्मा के पास ले गए", "हमारे प्रतीक्षा करते समय पृथ्वी पर लाखों वर्ष बीत गए", "मैंने कृष्ण के बड़े भाई से विवाह किया", "मैं बलराम की पत्नी हूँ जिसने समय के पार यात्रा की", "मुझे 27वें नक्षत्र के रूप में भी जाना जाता है"]');
INSERT INTO clue_riddles VALUES(199,'KARNA','["I was abandoned at birth and raised by a charioteer", "I gave away my divine armor and earrings to my enemy''s father", "I was cursed by my guru for hiding my true identity", "I fought against my own brothers without knowing it", "I am the tragic hero of the Mahabharata, son of Surya"]','["मुझे जन्म के समय त्याग दिया गया और एक सारथी ने मुझे पाला", "मैंने अपने दिव्य कवच और कुंडल अपने शत्रु के पिता को दे दिए", "मेरे गुरु ने मेरी असली पहचान छिपाने पर मुझे श्राप दिया", "मैं बिना जाने अपने ही भाइयों के विरुद्ध लड़ा", "मैं महाभारत का दुखद नायक, सूर्य पुत्र हूँ"]');
INSERT INTO clue_riddles VALUES(200,'PRAHLADA','["I was thrown off cliffs, fed poison, and trampled by elephants", "Nothing could kill me because of my unshakeable faith", "My own father Hiranyaksha tortured me for worshipping Vishnu", "I am the devotee child for whom Narasimha appeared", "I was placed in fire with Holika but remained unharmed"]','["मुझे चट्टानों से गिराया, विष दिया, और हाथियों से कुचलवाया गया", "मेरी अडिग श्रद्धा के कारण कुछ भी मुझे मार नहीं सका", "मेरे पिता हिरण्याक्ष ने मुझे विष्णु की पूजा करने पर प्रताड़ित किया", "मैं वह भक्त बालक हूँ जिसके लिए नरसिंह प्रकट हुए", "मुझे होलिका के साथ अग्नि में बैठाया गया लेकिन मैं सुरक्षित रहा"]');
INSERT INTO clue_riddles VALUES(201,'SANJEEVANI','["I glow with a divine light on a mountain slope", "I can bring the dead back to life", "A warrior could not identify me so he carried the entire mountain", "I saved the life of a prince struck by a deadly weapon", "I am the life-giving herb that saved Lakshmana"]','["मैं एक पर्वत की ढलान पर दिव्य प्रकाश से चमकती हूँ", "मैं मृतकों को वापस जीवित कर सकती हूँ", "एक योद्धा मुझे पहचान न सका तो पूरा पर्वत उठा लाया", "मैंने एक घातक अस्त्र से मारे गए राजकुमार की जान बचाई", "मैं वह जीवनदायी बूटी हूँ जिसने लक्ष्मण को बचाया"]');
INSERT INTO clue_riddles VALUES(202,'GANGOTRI','["I am the origin point of India''s holiest river", "I sit at the foot of a glacier high in the Himalayas", "King Bhagiratha meditated here for the river to descend", "I am one of the four Chota Char Dham sites", "I am the source temple of the river Ganga"]','["मैं भारत की सबसे पवित्र नदी का उद्गम स्थल हूँ", "मैं हिमालय में ऊँचाई पर एक हिमनद के चरण में स्थित हूँ", "राजा भगीरथ ने नदी के अवतरण के लिए यहाँ ध्यान किया", "मैं छोटा चार धाम के चार स्थलों में से एक हूँ", "मैं गंगा नदी का स्रोत मंदिर हूँ"]');
INSERT INTO clue_riddles VALUES(203,'DEVAKI','["A prophecy said my eighth child would kill my brother", "My brother imprisoned me and killed my first six children", "My seventh child was miraculously transferred to another womb", "My eighth child was smuggled out on a stormy night", "I am the biological mother of Lord Krishna"]','["भविष्यवाणी हुई कि मेरा आठवाँ बच्चा मेरे भाई को मारेगा", "मेरे भाई ने मुझे कैद किया और मेरे पहले छह बच्चों को मारा", "मेरा सातवाँ बच्चा चमत्कारिक रूप से दूसरे गर्भ में स्थानांतरित हुआ", "मेरा आठवाँ बच्चा एक तूफानी रात को चुपके से बाहर ले जाया गया", "मैं भगवान कृष्ण की जन्मदात्री माता हूँ"]');
INSERT INTO clue_riddles VALUES(204,'LINGARAJ','["I am the tallest temple in a city of temples", "My tower rises one hundred and eighty feet in the sky", "I represent both Shiva and Vishnu in one deity", "I am built in the Kalinga style of architecture", "I am the great temple of Bhubaneswar in Odisha"]','["मैं मंदिरों के शहर का सबसे ऊँचा मंदिर हूँ", "मेरा शिखर एक सौ अस्सी फुट आकाश में उठता है", "मैं एक ही देवता में शिव और विष्णु दोनों का प्रतिनिधित्व करता हूँ", "मैं कलिंग शैली की वास्तुकला में बना हूँ", "मैं ओडिशा के भुवनेश्वर का महान मंदिर हूँ"]');
INSERT INTO clue_riddles VALUES(205,'AGNI','["I am the messenger between gods and humans", "Every offering reaches heaven through me", "I have two faces and seven tongues", "I consumed a vast forest with Krishna''s help", "I am the god of fire"]','["मैं देवताओं और मनुष्यों के बीच दूत हूँ", "हर आहुति मेरे माध्यम से स्वर्ग पहुँचती है", "मेरे दो मुख और सात जिह्वाएँ हैं", "मैंने कृष्ण की सहायता से एक विशाल वन को भस्म किया", "मैं अग्नि देव हूँ"]');
INSERT INTO clue_riddles VALUES(206,'DHARMA','["I am the cosmic law that holds the universe together", "I am represented as a bull standing on four legs", "In each age I lose one leg as righteousness declines", "Following me is considered the highest purpose of life", "I am the eternal moral order in Hindu philosophy"]','["मैं वह ब्रह्मांडीय नियम हूँ जो संसार को एक साथ रखता है", "मुझे चार पैरों पर खड़े बैल के रूप में दर्शाया जाता है", "हर युग में पवित्रता के पतन से मेरा एक पैर कम होता है", "मेरा पालन जीवन का सर्वोच्च उद्देश्य माना जाता है", "मैं हिंदू दर्शन में शाश्वत नैतिक व्यवस्था हूँ"]');
INSERT INTO clue_riddles VALUES(207,'DANDAKA','["I am a vast forest that stretches across central India", "A sage''s curse turned a kingdom into this dense wilderness", "Rama wandered through me for most of his fourteen-year exile", "Many sages lived here seeking protection from demons", "I am the great forest of the Ramayana"]','["मैं मध्य भारत में फैला एक विशाल वन हूँ", "एक ऋषि के श्राप ने एक राज्य को इस घने जंगल में बदला", "राम अपने चौदह वर्ष के वनवास का अधिकांश समय मुझमें घूमे", "कई ऋषि राक्षसों से सुरक्षा माँगते हुए यहाँ रहे", "मैं रामायण का महान वन हूँ"]');
INSERT INTO clue_riddles VALUES(208,'AHIRAVAN','["I am a powerful sorcerer-king who ruled a hidden realm beneath the earth", "I abducted Laxman and Rama during a great war to offer them in sacrifice", "My strength was protected by a unique condition tied to multiple sources of life", "Hanuman took Panchmukhi form to defeat me and save the princes", "I am the brother of Ravana associated with the underworld"]','["मैं एक शक्तिशाली मायावी राजा हूँ जो पाताल लोक में शासन करता था", "मैंने एक महान युद्ध के दौरान लक्ष्मण और राम का अपहरण किया था", "मेरी शक्ति एक विशेष रहस्य से सुरक्षित थी जो मेरे जीवन से जुड़ा था", "हनुमान ने मुझे पराजित करने और राजकुमारों को बचाने के लिए पंचमुखी रूप धारण किया", "मैं रावण का भाई हूँ जो पाताल लोक से जुड़ा है"]');
INSERT INTO clue_riddles VALUES(209,'MOKSHA','["I am the ultimate goal of every soul", "Achieving me means freedom from the cycle of birth and death", "I can be reached through knowledge, devotion, or selfless action", "I am the state where the individual soul merges with the supreme", "I am liberation in Hindu philosophy"]','["मैं हर आत्मा का परम लक्ष्य हूँ", "मुझे प्राप्त करने का अर्थ है जन्म-मृत्यु के चक्र से मुक्ति", "मुझ तक ज्ञान, भक्ति या निष्काम कर्म से पहुँचा जा सकता है", "मैं वह अवस्था हूँ जहाँ जीवात्मा परमात्मा में विलीन हो जाती है", "मैं हिंदू दर्शन में मुक्ति हूँ"]');
INSERT INTO clue_riddles VALUES(210,'MAYA','["I make the unreal appear real and the real invisible", "I am the veil that prevents souls from seeing the truth", "Even the wisest are caught in my web", "Adi Shankaracharya called me the great cosmic illusion", "I am usually used with Moh"]','["मैं असत्य को सत्य और सत्य को अदृश्य बनाती हूँ", "मैं वह पर्दा हूँ जो आत्माओं को सत्य देखने से रोकती है", "बुद्धिमान से बुद्धिमान भी मेरे जाल में फँसे हैं", "आदि शंकराचार्य ने मुझे महान ब्रह्मांडीय भ्रम कहा", "मेरा अक्सर मोह के साथ प्रयोग किया जाता हूँ"]');
INSERT INTO clue_riddles VALUES(211,'PANCHAVATI','["Five sacred banyan trees gave me my name", "A prince built a hut here during his exile", "A princess was abducted from my grounds", "A demoness had her nose cut here", "I am the forest hermitage of Rama near Nashik"]','["पाँच पवित्र वट वृक्षों ने मुझे मेरा नाम दिया", "एक राजकुमार ने वनवास के दौरान यहाँ कुटिया बनाई", "एक राजकुमारी का मेरी भूमि से अपहरण हुआ", "एक राक्षसी की यहाँ नाक काटी गई", "मैं नासिक के निकट राम का वन आश्रम हूँ"]');
INSERT INTO clue_riddles VALUES(212,'NIDHI','["I am a hidden repository of wealth often associated with divine guardianship", "In mythology, I am linked to the treasures of Kubera, the lord of riches", "I can symbolize both material abundance and spiritual wealth", "There are traditionally nine of me mentioned in scriptures", "I simply mean a treasure or store of riches"]','["मैं धन का वह भंडार हूँ जो अक्सर दिव्य संरक्षण से जुड़ा होता है", "पौराणिक कथाओं में मेरा संबंध धन के देवता कुबेर के खजानों से है", "मैं भौतिक समृद्धि और आध्यात्मिक संपदा दोनों का प्रतीक हो सकता हूँ", "शास्त्रों में मेरे नौ प्रकार बताए गए हैं", "मैं सरल रूप में खजाना या धन का भंडार हूँ"]');
INSERT INTO clue_riddles VALUES(213,'SHANI','["My gaze is so powerful that it can bring misfortune", "I move the slowest among all celestial bodies", "I test people through hardship and suffering", "Saturday is named after me in Indian tradition", "I am the planet Saturn and god of justice"]','["मेरी दृष्टि इतनी शक्तिशाली है कि दुर्भाग्य ला सकती है", "मैं सभी ग्रहों में सबसे धीमा चलता हूँ", "मैं कठिनाई और कष्ट के माध्यम से लोगों की परीक्षा लेता हूँ", "भारतीय परंपरा में शनिवार मेरे नाम पर है", "मैं न्याय का देवता हूँ"]');
INSERT INTO clue_riddles VALUES(214,'SAMAVEDA','["My verses are primarily taken from the Rig Veda and set to musical notes", "I am considered the foundational root of Indian classical music", "In the Bhagavad Gita, Lord Krishna identifies himself with me among the four Vedas", "My hymns are traditionally sung by the ''Udgatar'' priest during Vedic sacrifices", "I am one of the four Vedas associated with music"]','["मेरी ऋचाएँ मुख्य रूप से ऋग्वेद से ली गई हैं और उन्हें संगीतमय सुरों में पिरोया गया है", "मुझे भारतीय शास्त्रीय संगीत की आधारशिला और मूल जड़ माना जाता है", "श्रीमद्भगवद्गीता में, भगवान कृष्ण ने चारों वेदों में स्वयं को मेरा स्वरूप बताया है", "मेरे भजनों का गायन पारंपरिक रूप से वैदिक यज्ञों के दौरान ''उद्गाता'' पुरोहित द्वारा किया जाता है", "मैं संगीत से जुड़ा चार वेदों में से एक हूँ"]');
INSERT INTO clue_riddles VALUES(215,'HALAHALA','["I emerged before any treasure during the great churning", "I was so deadly that I could destroy all of creation", "No one dared to touch me except the greatest god", "Shiva drank me and held me in his throat turning it blue", "I am the deadly poison from the churning of the ocean"]','["मैं महा मंथन के दौरान किसी भी रत्न से पहले निकला", "मैं इतना घातक था कि सम्पूर्ण सृष्टि को नष्ट कर सकता था", "सबसे महान देवता के अलावा कोई मुझे छूने का साहस नहीं कर सका", "शिव ने मुझे पिया और अपने गले में रोका जिससे वह नीला हो गया", "मैं समुद्र मंथन से निकला घातक विष हूँ"]');
INSERT INTO clue_riddles VALUES(216,'VISHVARUP','["I contain all of creation within my body", "Millions of suns could not match my brilliance", "Seeing me filled the bravest warrior with terror", "I showed birth and death happening simultaneously", "I am Krishna''s cosmic universal form shown to Arjuna"]','["मेरे शरीर में सम्पूर्ण सृष्टि समाहित है", "लाखों सूर्य भी मेरी चमक की बराबरी नहीं कर सकते", "मुझे देखकर सबसे बहादुर योद्धा भी भयभीत हो गया", "मैंने जन्म और मृत्यु को एक साथ घटते दिखाया", "मैं कृष्ण का विराट विश्वरूप हूँ जो अर्जुन को दिखाया गया"]');
INSERT INTO clue_riddles VALUES(217,'MANGAL','["I am the red planet associated with war and valor", "I was born from a drop of Shiva''s sweat", "My day Tuesday is considered auspicious for Hanuman worship", "I grant courage and strength to those who please me", "I am the planet Mars in Hindu astrology"]','["मैं युद्ध और वीरता से जुड़ा लाल ग्रह हूँ", "मेरा जन्म शिव के पसीने की एक बूँद से हुआ", "मेरा दिन मंगलवार हनुमान पूजा के लिए शुभ माना जाता है", "मैं उन्हें साहस और शक्ति प्रदान करता हूँ जो मुझे प्रसन्न करते हैं", "मैं हिंदू ज्योतिष में ग्रह हूँ"]');
INSERT INTO clue_riddles VALUES(218,'KUBERA','["I guard the treasures of the north", "My half-brother Ravana stole my golden city from me", "I fly in the Pushpaka Vimana that was later taken", "I am one of the eight guardians of the directions", "I am the god of wealth in Hindu mythology"]','["मैं उत्तर के खजानों की रक्षा करता हूँ", "मेरे सौतेले भाई रावण ने मेरी स्वर्ण नगरी मुझसे छीन ली", "मैं पुष्पक विमान में उड़ता था जो बाद में छीन लिया गया", "मैं आठ दिक्पालों में से एक हूँ", "मैं हिंदू पुराणों में धन का देवता हूँ"]');
INSERT INTO clue_riddles VALUES(219,'SADESATI','["I am believed to be a period of intense spiritual growth and karmic cleansing", "I usually occur about three times in a typical human lifespan", "I am often feared for bringing significant challenges and life lessons", "Even Shiva could not escape me", "I occur when Shani passes through the 12th, 1st, and 2nd houses from the natal Moon"]','["मुझे आध्यात्मिक विकास और कर्मों के शुद्धिकरण की अवधि माना जाता है", "मैं आमतौर पर एक मनुष्य के जीवनकाल में तीन बार आती हूँ", "मुझे अक्सर बड़ी चुनौतियों और जीवन के कठिन पाठों के लिए जाना जाता है", "मुझसे शिव भी नहीं बच पाए थे", "मैं तब शुरू होती हूँ जब शनि चंद्रमा से 12वें, पहले और दूसरे भाव से गुजरता है"]');
INSERT INTO clue_riddles VALUES(220,'UDUPI','["Sri Krishna temple in my city serves free meals to thousands daily", "Eight monasteries take turns managing Sri Krishna temple", "My cuisine is famous across the world", "I am the Krishna temple town in Karnataka", "It has beaches like Malpe and Kaup"]','["मेरा मंदिर प्रतिदिन हजारों लोगों को मुफ्त भोजन कराता है", "आठ मठ बारी-बारी से श्री कृष्ण मंदिर का प्रबंधन करते हैं", "मेरा भोजन विश्व भर में प्रसिद्ध है", "मैं कर्नाटक का कृष्ण मंदिर नगर हूँ", "यहाँ मालपे और कौप जैसे समुद्र तट हैं"]');
INSERT INTO clue_riddles VALUES(221,'SARASWATI','["I hold a veena in my hands", "I wear white robes", "I am the goddess of knowledge and arts", "A swan is my vehicle", "Students pray to me during exams"]','["मेरे हाथों में वीणा है", "मैं श्वेत वस्त्र धारण करती हूँ", "मैं ज्ञान और कला की देवी हूँ", "हंस मेरा वाहन है", "विद्यार्थी परीक्षा में मेरी प्रार्थना करते हैं"]');
INSERT INTO clue_riddles VALUES(222,'VRINDA','["Lord Vishnu had to take the form of my husband to break my penance", "My immense piety and chastity made my husband invincible in battle", "I was the wife of the powerful demon king Jalandhara", "I cursed Lord Vishnu to turn into a black stone called Shaligram", "I am worshipped in every Hindu household as the sacred Tulsi plant"]','["भगवान विष्णु को मेरा तप भंग करने के लिए मेरे पति का रूप लेना पड़ा", "मेरे सतीत्व की शक्ति ने मेरे पति को युद्ध में अजेय बना दिया था", "मैं शक्तिशाली असुर राज जालंधर की धर्मपत्नी थी", "मैंने विष्णु जी को ''शालिग्राम'' पत्थर बनने का श्राप दिया था", "आज मुझे हर हिंदू घर में पवित्र ''तुलसी'' के रूप में पूजा जाता है"]');
INSERT INTO clue_riddles VALUES(223,'RUKMINI','["I wrote a secret letter begging to be rescued from an unwanted marriage", "My beloved came on a chariot and took me away", "I am considered an incarnation of Lakshmi", "I am the principal queen of Dwarka", "I am the chief wife of Lord Krishna"]','["मैंने एक अवांछित विवाह से बचाने के लिए गुप्त पत्र लिखा", "मेरे प्रियतम रथ पर आए और मुझे ले गए", "मुझे लक्ष्मी का अवतार माना जाता है", "मैं द्वारका की प्रमुख रानी हूँ", "मैं भगवान कृष्ण की मुख्य पत्नी हूँ"]');
INSERT INTO clue_riddles VALUES(224,'VAIKUNTHA','["I am the supreme abode where no sorrow exists", "The cosmic ocean of milk surrounds my golden realm", "Vishnu rests here on the infinite serpent", "Reaching me means permanent freedom from rebirth", "I am the heavenly paradise of Lord Vishnu"]','["मैं वह सर्वोच्च धाम हूँ जहाँ कोई दुख नहीं है", "क्षीरसागर मेरे स्वर्णिम लोक को घेरे हुए है", "विष्णु यहाँ अनंत सर्प पर विश्राम करते हैं", "मुझ तक पहुँचने का अर्थ है पुनर्जन्म से स्थायी मुक्ति", "मैं भगवान विष्णु का स्वर्गीय लोक हूँ"]');
INSERT INTO clue_riddles VALUES(225,'KAILASH','["No human has ever climbed my summit", "A sacred lake mirrors my snow-covered peak", "Four of Asia''s greatest rivers begin near me", "I am shaped like a perfect pyramid of ice", "I am the heavenly abode of Lord Shiva"]','["कोई मनुष्य कभी मेरे शिखर पर नहीं चढ़ा", "एक पवित्र झील मेरे बर्फ से ढके शिखर को दर्पण की भाँति दिखाती है", "एशिया की चार महान नदियाँ मेरे निकट से शुरू होती हैं", "मेरा आकार बर्फ के एक पूर्ण पिरामिड जैसा है", "मैं भगवान शिव का स्वर्गीय निवास हूँ"]');
INSERT INTO clue_riddles VALUES(226,'MANDARA','["I was uprooted and placed in the ocean by gods", "A divine tortoise held me on its back during a great event", "A serpent was wrapped around me as a rope", "I served as the churning rod for the cosmic ocean", "I am the mountain used in the Samudra Manthan"]','["देवताओं ने मुझे उखाड़कर समुद्र में रखा", "एक महान घटना के दौरान एक दिव्य कछुए ने मुझे अपनी पीठ पर रखा", "एक सर्प को रस्सी के रूप में मेरे चारों ओर लपेटा गया", "मैंने ब्रह्मांडीय समुद्र की मथनी का काम किया", "मैं समुद्र मंथन में प्रयुक्त पर्वत हूँ"]');
INSERT INTO clue_riddles VALUES(227,'SATI','["I married the greatest god against my father''s wishes", "My father insulted my husband at a grand sacrifice", "I immolated myself in the fire of my own rage", "My body was cut into fifty-one pieces that became sacred sites", "I am the first wife of Shiva who was reborn as Parvati"]','["मैंने अपने पिता की इच्छा के विरुद्ध सबसे महान देवता से विवाह किया", "मेरे पिता ने एक महायज्ञ में मेरे पति का अपमान किया", "मैंने अपने ही क्रोध की अग्नि में स्वयं को भस्म कर लिया", "मेरे शरीर को इक्यावन टुकड़ों में काटा गया जो पवित्र स्थल बने", "मैं शिव की पहली पत्नी हूँ जो पार्वती के रूप में पुनर्जन्मी"]');
INSERT INTO clue_riddles VALUES(228,'VITHOBA','["I am often depicted with my arms akimbo, hands on my hips", "I am a popular form of Lord Vishnu in Maharashtra", "My main temple is in Pandharpur on the banks of the Chandrabhaga", "I am the central deity of the Varkari pilgrimage tradition", "I am also known as Vitthala"]','["मुझे अक्सर अपनी कमर पर हाथ रखे हुए मुद्रा में दिखाया जाता है", "मैं महाराष्ट्र में भगवान विष्णु का एक अत्यंत प्रिय स्वरूप हूँ", "मेरा मुख्य मंदिर पंढरपुर में चंद्रभागा नदी के तट पर स्थित है", "मैं वारकरी संप्रदाय और उनकी प्रसिद्ध पदयात्रा का आधार हूँ", "मैं विट्ठल के नाम से भी जाना जाता हूँ"]');
INSERT INTO clue_riddles VALUES(229,'DURGAPUJA','["The rhythmic sound of the Dhak is central to my ritual", "I am famous for grand Pandals and artistic idols", "I am the heart of West Bengal''s cultural heritage", "I conclude with the immersion on Bijoya Dashami", "I celebrate Durga''s victory over the demon Mahishasura"]','["ढाक की आवाज़ मेरे अनुष्ठानों की मुख्य पहचान है", "मैं भव्य पंडालों और सुंदर मूर्तियों के लिए प्रसिद्ध हूँ", "मैं पश्चिम बंगाल की सांस्कृतिक विरासत की आत्मा हूँ", "मेरा समापन विजयादशमी और मूर्ति विसर्जन के साथ होता है", "मैं महिषासुर पर देवी दुर्गा की विजय का महापर्व हूँ"]');
INSERT INTO clue_riddles VALUES(230,'BALARAM','["I carry a plough as my weapon of choice", "I taught both Duryodhana and Bhima the art of mace fighting", "I am an incarnation of the cosmic serpent Shesha", "I was transferred between wombs before my brother''s birth", "I am the elder brother of Lord Krishna"]','["मैं अपने पसंदीदा हथियार के रूप में हल रखता हूँ", "मैंने दुर्योधन और भीम दोनों को गदा युद्ध सिखाया", "मैं ब्रह्मांडीय सर्प शेषनाग का अवतार हूँ", "मेरे भाई के जन्म से पहले मुझे एक गर्भ से दूसरे में स्थानांतरित किया गया", "मैं भगवान कृष्ण का बड़ा भाई हूँ"]');
INSERT INTO clue_riddles VALUES(231,'ARUNACHAL','["I am considered the physical form of Shiva himself", "A column of fire appeared here that had no beginning or end", "Ramana Maharshi spent his entire life at my foot", "I am the sacred hill of fire in Tiruvannamalai", "I have the same name as one of the North-Eastern states in India"]','["मुझे स्वयं शिव का भौतिक रूप माना जाता है", "यहाँ अग्नि का एक स्तंभ प्रकट हुआ जिसका न आदि था न अंत", "रमण महर्षि ने अपना पूरा जीवन मेरे चरणों में बिताया", "मैं तिरुवन्नामलै की पवित्र अग्नि पहाड़ी हूँ", "मेरा नाम भारत के उत्तर-पूर्वी राज्यों में से एक के समान है"]');
INSERT INTO clue_riddles VALUES(232,'YASHODA','["I saw the entire universe inside my child''s mouth", "I tried to tie my naughty child but the rope was always too short", "I loved my foster child more than life itself", "I was the queen of Gokul and wife of Nanda", "I am the foster mother of Lord Krishna"]','["मैंने अपने बच्चे के मुँह में पूरा ब्रह्मांड देखा", "मैंने अपने शरारती बच्चे को बाँधने की कोशिश की पर रस्सी हमेशा छोटी पड़ी", "मैंने अपने पालक पुत्र को अपने प्राणों से भी अधिक प्रेम किया", "मैं गोकुल की रानी और नंद की पत्नी थी", "मैं भगवान कृष्ण की पालक माता हूँ"]');
INSERT INTO clue_riddles VALUES(233,'DAKSH','["I fathered twenty-seven daughters who married the moon", "I organized a grand sacrifice and excluded my own son-in-law", "My arrogance led to the destruction of my own ceremony", "Shiva''s warriors destroyed my sacrifice and cut off my head", "I am the father of Sati whose head was replaced with a goat''s"]','["मैंने सत्ताईस पुत्रियों को जन्म दिया जिनका विवाह चंद्रमा से हुआ", "मैंने एक महायज्ञ आयोजित किया और अपने ही दामाद को बहिष्कृत किया", "मेरे अहंकार ने मेरे ही यज्ञ का विनाश किया", "शिव के गणों ने मेरे यज्ञ को नष्ट कर मेरा सिर काट दिया", "मैं सती का पिता हूँ जिसके सिर की जगह बकरे का सिर लगाया गया"]');
INSERT INTO clue_riddles VALUES(234,'KANS','["I imprisoned my own sister and her husband out of fear", "I killed babies trying to prevent a prophecy", "I sent many demons to kill a child in a village", "I was finally killed by my own nephew", "I am the tyrannical uncle of Krishna"]','["मैंने डर से अपनी ही बहन और उसके पति को कैद किया", "मैंने एक भविष्यवाणी रोकने के लिए शिशुओं को मारा", "मैंने एक गाँव में एक बच्चे को मारने के लिए कई राक्षस भेजे", "अंततः मुझे मेरे अपने भतीजे ने मारा", "मैं कृष्ण का अत्याचारी मामा हूँ"]');
INSERT INTO clue_riddles VALUES(235,'RAVANA','["I was the greatest scholar of the Vedas despite being a demon", "I could play the veena so beautifully that even gods wept", "I had ten heads representing mastery over all knowledge", "I abducted another man''s wife which led to my downfall", "I am the mighty king of Lanka"]','["राक्षस होते हुए भी मैं वेदों का सबसे बड़ा विद्वान था", "मैं इतनी सुंदर वीणा बजाता था कि देवता भी रो पड़ते थे", "मेरे दस सिर सभी ज्ञान पर प्रभुत्व का प्रतीक थे", "मैंने दूसरे की पत्नी का अपहरण किया जो मेरे पतन का कारण बना", "मैं लंका का शक्तिशाली राजा हूँ"]');
INSERT INTO clue_riddles VALUES(236,'GOVARDHAN','["I was lifted on a single finger for seven days", "I sheltered an entire village from a devastating storm", "I was used to teach the king of gods a lesson in humility", "Devotees walk around me in a sacred circumambulation", "I am the hill Krishna lifted to protect Vrindavan from Indra''s wrath"]','["मुझे एक उँगली पर सात दिन उठाया गया", "मैंने एक पूरे गाँव को विनाशकारी तूफान से बचाया", "मुझे देवताओं के राजा को विनम्रता का पाठ पढ़ाने के लिए उपयोग किया गया", "भक्त मेरी पवित्र परिक्रमा करते हैं", "मैं वह पहाड़ी हूँ जिसे कृष्ण ने इंद्र के प्रकोप से वृंदावन की रक्षा के लिए उठाया"]');
INSERT INTO clue_riddles VALUES(237,'KALIYA','["My venom poisoned an entire river and its surroundings", "A child jumped on my hoods and danced on my heads", "I had multiple hoods that sprayed deadly poison", "I was banished from the Yamuna river forever", "I am the serpent demon subdued by Krishna''s dance"]','["मेरे विष ने एक पूरी नदी और उसके आसपास को ज़हरीला कर दिया", "एक बच्चे ने मेरे फनों पर कूदकर मेरे सिरों पर नृत्य किया", "मेरे अनेक फन थे जो घातक विष छिड़कते थे", "मुझे यमुना नदी से सदा के लिए निष्कासित किया गया", "मैं वह सर्प राक्षस हूँ जिसे कृष्ण के नृत्य ने वश में किया"]');
INSERT INTO clue_riddles VALUES(238,'PUTANA','["I was a demoness who disguised myself as a beautiful woman", "I applied poison on my body to kill a divine child", "The infant I tried to kill sucked the life out of me instead", "I was granted salvation because I nursed the lord", "I am the demoness who tried to poison baby Krishna"]','["मैं एक राक्षसी थी जिसने सुंदर स्त्री का वेश धारण किया", "मैंने एक दिव्य शिशु को मारने के लिए अपने शरीर पर विष लगाया", "जिस शिशु को मैंने मारने की कोशिश की उसने मेरे प्राण ही चूस लिए", "मुझे उद्धार मिला क्योंकि मैंने भगवान को स्तनपान कराया", "मैं वह राक्षसी हूँ जिसने बाल कृष्ण को विष देने का प्रयास किया"]');
INSERT INTO clue_riddles VALUES(239,'BHARATA','["I am a character in Ramayana", "I placed my brother''s sandals on the throne", "I begged my exiled brother to return", "I am an incarnation of Panchajanya of Lord Vishnu", "I am Rama''s devoted younger brother"]','["मैं रामायण का एक पात्र हूँ", "मैंने सिंहासन पर अपने भाई की चरण पादुकाएँ रखीं", "मैंने अपने निर्वासित भाई से लौटने की विनती की", "मैं भगवान विष्णु के पांचजन्य शंख का अवतार हूँ", "मैं राम का समर्पित छोटा भाई हूँ"]');
INSERT INTO clue_riddles VALUES(240,'APSARA','["We emerged from the churning of the cosmic ocean", "We dance in the court of Indra to entertain the gods", "We are often sent to break the meditation of powerful sages", "Urvashi and Menaka are the most famous among us", "We are the celestial nymphs of Hindu mythology"]','["हमारा उद्भव ब्रह्मांडीय समुद्र मंथन से हुआ", "हम देवताओं के मनोरंजन के लिए इंद्र के दरबार में नृत्य करती हैं", "शक्तिशाली ऋषियों का ध्यान भंग करने के लिए हमें भेजा जाता है", "उर्वशी और मेनका हममें सबसे प्रसिद्ध हैं", "हम हिंदू पुराणों की स्वर्गीय अप्सराएँ हैं"]');
INSERT INTO clue_riddles VALUES(241,'MARICHA','["I was once thrown across the ocean by a young prince''s arrow", "I was forced by my king to play a dangerous role", "I took the form of a golden deer to lure a princess", "I cried out in a fake voice to draw the protectors away", "I am the demon who became the golden deer in Ramayana"]','["मुझे एक युवा राजकुमार के बाण से समुद्र पार फेंक दिया गया था", "मेरे राजा ने मुझे एक खतरनाक भूमिका निभाने के लिए मजबूर किया", "मैंने एक राजकुमारी को लुभाने के लिए सुनहरे हिरण का रूप धारण किया", "मैंने रक्षकों को हटाने के लिए नकली आवाज़ में चिल्लाया", "मैं रामायण में सुनहरा हिरण बनने वाला राक्षस हूँ"]');
INSERT INTO clue_riddles VALUES(242,'SHALIGRAM','["I am a sacred black stone found primarily in the Gandaki River", "I am worshipped as an iconic representation of Lord Vishnu", "I am naturally formed and often contain fossilized ammonite shells", "I am usually kept in household altars along with the Tulsi plant", "My origin is linked to the curse given by the devoted Vrinda"]','["मैं गंडकी नदी में पाया जाने वाला एक अत्यंत पवित्र काला पत्थर हूँ", "मुझे भगवान विष्णु के साक्षात स्वरूप के रूप में पूजा जाता है", "मेरा निर्माण प्राकृतिक है और मुझमें चक्र जैसे जीवाश्म के निशान होते हैं", "मुझे अक्सर घरों के मंदिरों में तुलसी के पौधे के पास रखा जाता है", "मेरी उत्पत्ति सती वृंदा द्वारा दिए गए एक श्राप से जुड़ी हुई है"]');
INSERT INTO clue_riddles VALUES(243,'NAVAGRAHA','["We are nine celestial bodies that influence human destiny", "We are worshipped together in a special arrangement in temples", "We include the sun, moon, and five visible planets", "Two of us are shadow planets with no physical form", "We are the nine planetary deities of Hindu astrology"]','["हम नौ खगोलीय पिंड हैं जो मानव भाग्य को प्रभावित करते हैं", "मंदिरों में हमारी एक विशेष व्यवस्था में एक साथ पूजा होती है", "हमारे में सूर्य, चंद्रमा और पाँच दृश्य ग्रह शामिल हैं", "हमारे दो छाया ग्रह हैं जिनका कोई भौतिक रूप नहीं", "हम हिंदू ज्योतिष के नौ ग्रह देवता हैं"]');
INSERT INTO clue_riddles VALUES(244,'URMILA','["I slept for fourteen years so my husband could stay awake", "I sacrificed my waking life for my husband''s duty", "I am the lesser known princess of Mithila", "My sister is Sita who married the eldest prince", "I am the wife of Lakshmana from the Ramayana"]','["मैंने चौदह वर्ष सोकर बिताए ताकि मेरे पति जागते रह सकें", "मैंने अपने पति के कर्तव्य के लिए अपने जाग्रत जीवन का बलिदान किया", "मैं मिथिला की कम ज्ञात राजकुमारी हूँ", "मेरी बहन सीता है जिसने सबसे बड़े राजकुमार से विवाह किया", "मैं रामायण में लक्ष्मण की पत्नी हूँ"]');
INSERT INTO clue_riddles VALUES(245,'KALIYUG','["I am the final phase in a great cyclical division of time where righteousness declines", "In me, virtue stands on only one leg while adharma dominates", "I am marked by increasing ignorance, conflict, and moral decay", "I follow Dvapara and precede the renewal of the cycle", "I am the present age according to Hindu cosmology"]','["मैं समय के चक्र का अंतिम चरण हूँ जिसमें धर्म का ह्रास होता है", "मेरे समय में धर्म केवल एक पाद पर टिकता है और अधर्म बढ़ता है", "मैं अज्ञान, संघर्ष और नैतिक पतन से पहचाना जाता हूँ", "मैं द्वापर के बाद आता हूँ और नए चक्र से पहले होता हूँ", "मैं वर्तमान युग हूँ हिंदू मान्यता के अनुसार"]');
INSERT INTO clue_riddles VALUES(246,'RAKTABIJA','["Every drop of my blood that touched the ground created a clone of me", "Only drinking my blood before it fell could stop my multiplication", "A fierce goddess had to drink all my blood to kill me", "I am the demon whose blood created duplicates on the battlefield", "My name means ''seed of blood''"]','["मेरे खून की हर बूँद ज़मीन पर गिरने पर मेरा प्रतिरूप बनती थी", "मेरे गुणन को रोकने के लिए मेरा खून गिरने से पहले पीना पड़ा", "एक उग्र देवी को मुझे मारने के लिए मेरा सारा खून पीना पड़ा", "मैं वह राक्षस हूँ जिसके खून से रणभूमि में प्रतिलिपियाँ बनती थीं", "मेरे नाम का अर्थ है ''खून का बीज''"]');
INSERT INTO clue_riddles VALUES(247,'TIRUPATI','["I am the richest temple in the world", "Millions of devotees donate their hair to me every year", "Seven hills must be climbed to reach my sanctum", "My deity''s real form is hidden behind a diamond crown", "I am the abode of Lord Venkateswara in Andhra Pradesh"]','["मैं दुनिया का सबसे अमीर मंदिर हूँ", "हर साल लाखों भक्त मुझे अपने बाल दान करते हैं", "मेरे गर्भगृह तक पहुँचने के लिए सात पहाड़ियाँ चढ़नी पड़ती हैं", "मेरे देवता का असली रूप हीरे के मुकुट के पीछे छिपा है", "मैं आंध्र प्रदेश में भगवान वेंकटेश्वर का निवास हूँ"]');
INSERT INTO clue_riddles VALUES(248,'KATRA','["I am a small town known for a famous pilgrimage", "I am closely associated with a revered goddess shrine", "The trek to the Trikuta Mountains begins from my land", "I am located in the Reasi district of Jammu and Kashmir", "I am the base camp for the holy pilgrimage of Mata Vaishno Devi"]','["मैं एक छोटा सा नगर हूँ जो एक प्रसिद्ध तीर्थ के लिए जाना जाता है", "मेरा संबंध एक पूजनीय देवी मंदिर से है", "त्रिकुटा पर्वत की चढ़ाई मेरी ही धरती से शुरू होती है", "मैं जम्मू और कश्मीर के रियासी जिले में स्थित हूँ", "मैं माता वैष्णो देवी की पवित्र यात्रा का आधार हूँ"]');
INSERT INTO clue_riddles VALUES(249,'SHUKRA','["I possess the secret of bringing the dead back to life", "I am the only one who knows the Sanjeevani Vidya", "Friday is named after me in Indian tradition", "My eye was blinded by Vishnu''s discus", "I am the planet Venus and guru of the Asuras"]','["मेरे पास मृतकों को जीवित करने का रहस्य है", "संजीवनी विद्या को जानने वाला मैं एकमात्र हूँ", "भारतीय परंपरा में शुक्रवार मेरे नाम पर है", "मेरी एक आँख विष्णु के चक्र से अंधी हो गई", "मैं ग्रह और असुरों का गुरु हूँ"]');
INSERT INTO clue_riddles VALUES(250,'GANDHARVA','["We are celestial musicians who play at divine courts", "Our music can enchant any being in the three worlds", "We guard the sacred Soma drink", "Our marriages without rituals are named after us", "We are the heavenly singers and musicians of Indra''s court"]','["हम दिव्य संगीतकार हैं जो देव दरबारों में बजाते हैं", "हमारा संगीत तीनों लोकों के किसी भी प्राणी को मोहित कर सकता है", "हम पवित्र सोमरस की रक्षा करते हैं", "बिना अनुष्ठान के विवाह को हमारे नाम पर गंधर्व विवाह कहते हैं", "हम इंद्र के दरबार के स्वर्गीय गायक और संगीतकार हैं"]');
INSERT INTO clue_riddles VALUES(251,'AGASTYA','["I drank the entire ocean to expose hiding demons", "I brought Vedic knowledge to the lands south of the Vindhyas", "I humbled the Vindhya mountains by asking them to bow", "I gave Rama divine weapons before his battle with Ravana", "I am the great sage who is revered across South India"]','["मैंने छिपे राक्षसों को उजागर करने के लिए पूरा समुद्र पी लिया", "मैंने विंध्य के दक्षिण की भूमि में वैदिक ज्ञान लाया", "मैंने विंध्य पर्वत को नतमस्तक होने को कहकर विनम्र किया", "मैंने रावण से युद्ध से पहले राम को दिव्य अस्त्र दिए", "मैं वह महान ऋषि हूँ जो पूरे दक्षिण भारत में पूजनीय हैं"]');
INSERT INTO clue_riddles VALUES(252,'ARJUNA','["I won a princess by shooting a fish eye while looking at its reflection", "I received the most powerful divine weapon from Shiva after combat", "Krishna chose to be my charioteer instead of leading an army", "I was given divine vision to see the cosmic form of God", "I am the greatest archer among the Pandavas"]','["मैंने मछली की आँख का प्रतिबिंब देखकर उसे मारकर राजकुमारी जीती", "मैंने युद्ध के बाद शिव से सबसे शक्तिशाली दिव्यास्त्र प्राप्त किया", "कृष्ण ने सेना की जगह मेरे सारथी बनने का चुनाव किया", "मुझे ईश्वर का विश्वरूप देखने के लिए दिव्य दृष्टि दी गई", "मैं पांडवों में सबसे महान धनुर्धर हूँ"]');
INSERT INTO clue_riddles VALUES(253,'SHANKAR','["My name means one who brings auspiciousness and welfare", "I am a popular name of Lord Shiva", "I am associated with peace, destruction, and transformation", "Devotees chant my name in temples and prayers", "I am often called with Gauri"]','["मेरा अर्थ है कल्याण और मंगल करने वाला", "मैं भगवान शिव का एक लोकप्रिय नाम हूँ", "मैं शांति, संहार और परिवर्तन से जुड़ा हूँ", "भक्त मंदिरों और प्रार्थनाओं में मेरा नाम जपते हैं", "मुझे अक्सर गौरी के साथ पुकारा जाता है"]');
INSERT INTO clue_riddles VALUES(254,'ONAM','["I celebrate the annual return of a beloved king from the netherworld", "My origins are tied to a story of humility and a divine incarnation", "Floral designs and grand feasts are an essential part of my traditions", "I am the biggest festival of Kerala", "I mark a time of harvest and joy"]','["मैं उस प्रिय राजा की वार्षिक वापसी का उत्सव हूँ जो पाताल लोक से आते हैं", "मेरा संबंध विनम्रता और एक दिव्य अवतार की कथा से जुड़ा है", "मेरे उत्सव में फूलों की सजावट और भव्य भोज महत्वपूर्ण होते हैं", "मैं केरल का सबसे बड़ा पर्व हूँ", "मैं फसल और आनंद का प्रतीक हूँ"]');
INSERT INTO clue_riddles VALUES(255,'YAMRAJ','["I ride a buffalo across the sky when I come to claim souls", "My servants called Yamadutas carry out my commands", "Savitri once debated me to win back her husband''s life", "Nachiketa visited my realm and gained supreme knowledge", "I am the lord of death who judges all departed souls"]','["जब मैं आत्माओं को लेने आता हूँ तो आकाश में भैंसे पर सवार होता हूँ", "मेरे सेवक यमदूत मेरे आदेश पालन करते हैं", "सावित्री ने कभी अपने पति का जीवन वापस पाने के लिए मुझसे वाद-विवाद किया", "नचिकेता ने मेरे लोक में आकर परम ज्ञान प्राप्त किया", "मैं मृत्यु का स्वामी हूँ जो सभी दिवंगत आत्माओं को न्याय करता है"]');
INSERT INTO clue_riddles VALUES(256,'MOHAN','["My name means one who attracts or enchants", "I am a beloved name of Lord Krishna", "My flute draws hearts and souls toward me", "I am known for my charm and divine play", "Devotees lovingly call me by this name"]','["मेरा अर्थ है आकर्षित करने वाला या मोहित करने वाला", "मैं भगवान कृष्ण का एक प्रिय नाम हूँ", "मेरी बांसुरी सबके मन को अपनी ओर खींचती है", "मैं अपने आकर्षण और लीला के लिए जाना जाता हूँ", "भक्त मुझे प्रेम से इस नाम से पुकारते हैं"]');
INSERT INTO clue_riddles VALUES(257,'NASHIK','["I am a sacred city linked to the Ramayana", "I am where Lakshmana is believed to have cut Surpanakha’s nose", "I lie on the banks of the Godavari River", "I host one of the Kumbh Mela gatherings", "I am a major pilgrimage site in Maharashtra"]','["मैं रामायण से जुड़ा एक पवित्र शहर हूँ", "यहीं लक्ष्मण ने शूर्पणखा की नाक काटी थी", "मैं गोदावरी नदी के तट पर स्थित हूँ", "मैं कुंभ मेले के प्रमुख स्थलों में से एक हूँ", "मैं महाराष्ट्र का एक प्रमुख तीर्थ स्थल हूँ"]');
INSERT INTO clue_riddles VALUES(258,'MERU','["I am the axis around which the entire universe revolves", "The sun, moon, and stars orbit around me", "The abode of Brahma sits at my summit", "All the gods reside on my golden slopes", "I am the cosmic mountain at the center of the universe"]','["मैं वह अक्ष हूँ जिसके चारों ओर पूरा ब्रह्मांड घूमता है", "सूर्य, चंद्रमा और तारे मेरे चारों ओर परिक्रमा करते हैं", "ब्रह्मा का निवास मेरे शिखर पर है", "सभी देवता मेरी स्वर्णिम ढलानों पर निवास करते हैं", "मैं ब्रह्मांड के केंद्र में स्थित ब्रह्मांडीय पर्वत हूँ"]');
INSERT INTO clue_riddles VALUES(259,'CHARDHAM','["We are four sacred destinations at four corners of India", "Visiting all four of us ensures liberation of the soul", "Shankaracharya established us in the four directions", "We include Badrinath, Dwarka, Puri, and Rameshwaram", "We are the four holy pilgrimage sites of Hinduism"]','["हम भारत के चार कोनों पर चार पवित्र गंतव्य हैं", "हम चारों की यात्रा आत्मा की मुक्ति सुनिश्चित करती है", "शंकराचार्य ने हमें चार दिशाओं में स्थापित किया", "हम में बदरीनाथ, द्वारका, पुरी और रामेश्वरम शामिल हैं", "हम हिंदू धर्म के चार पवित्र तीर्थ स्थल हैं"]');
INSERT INTO clue_riddles VALUES(260,'VAISHNO','["I am a revered form of the Divine Mother worshipped in the mountains", "My shrine lies in the Trikuta Hills of Jammu", "Millions of devotees undertake a pilgrimage to reach me", "I am associated with the sacred cave known as a holy dham", "I am often remembered along with the word ‘Mata’"]','["मैं पर्वतों में पूजित दिव्य माता का एक रूप हूँ", "मेरा धाम जम्मू के त्रिकुट पर्वतों में स्थित है", "लाखों भक्त मेरी यात्रा के लिए तीर्थ करते हैं", "मैं एक पवित्र गुफा धाम से जुड़ी हूँ", "मुझे अक्सर ‘माता’ के साथ याद किया जाता है"]');
INSERT INTO clue_riddles VALUES(261,'SRISAILAM','["I am a sacred pilgrimage site in South India", "I am situated on the banks of the holy Krishna River in Andhra Pradesh", "Adi Shankara is said to have composed his ''Shivananda Lahari'' here", "I am home to one of the twelve Jyotirlingas", "I am associated with both Shiva and Shakti worship"]','["मैं दक्षिण भारत का एक पवित्र तीर्थ स्थल हूँ", "मैं आंध्र प्रदेश में पवित्र कृष्णा नदी के तट पर स्थित हूँ", "कहा जाता है कि आदि शंकराचार्य ने यहीं ''शिवानन्द लहरी'' की रचना की थी", "यहाँ बारह ज्योतिर्लिंगों में से एक स्थित है", "मेरा संबंध शिव और शक्ति दोनों की उपासना से है"]');
INSERT INTO clue_riddles VALUES(262,'MOHINI','["I am a captivating form taken to restore balance during a cosmic event", "My appearance was used to outwit powerful beings and protect divine nectar", "I enchanted even Lord Shiva, a divine play that led to the birth of Lord Ayyappa in certain traditions", "I famously defeated the demon Bhasmasura by making him dance and place his hand on his own head", "I am the female avatar of Vishnu"]','["मैं वह मोहक रूप हूँ जिसे एक महान घटना में संतुलन स्थापित करने के लिए धारण किया गया", "मेरे रूप का उपयोग शक्तिशाली असुरों को भ्रमित कर अमृत की रक्षा के लिए किया गया", "मैंने अपनी दिव्य लीला से भगवान शिव को भी मोहित कर लिया था", "मैंने भस्मासुर को नृत्य कराकर और फिर उसके ही सिर पर हाथ रखवाकर उसका अंत किया", "मैं विष्णु का स्त्री रूप अवतार हूँ"]');
INSERT INTO clue_riddles VALUES(263,'UPANISHAD','["My name means sitting near the guru to receive wisdom", "I form the end portion of the Vedas called Vedanta", "Tat Tvam Asi is one of my most famous declarations", "Aitereya, Brihadaranyaka, and Mandukya are some of my famous texts", "I am the sacred philosophical texts at the core of Hindu thought"]','["मेरे नाम का अर्थ है गुरु के निकट बैठकर ज्ञान प्राप्त करना", "मैं वेदों का अंतिम भाग हूँ जिसे वेदांत कहते हैं", "तत् त्वम् असि मेरी सबसे प्रसिद्ध उद्घोषणाओं में से एक है", "ऐतरेय, बृहदारण्यक और मांडूक्य मेरे कुछ प्रसिद्ध ग्रंथ हैं", "मैं हिंदू चिंतन के मूल में पवित्र दार्शनिक ग्रंथ हूँ"]');
INSERT INTO clue_riddles VALUES(264,'NAGALOKA','["I exist beneath the earthly plane", "I am the abode of serpent beings", "My capital city, Bhogavati, is said to be more beautiful and wealthy than Indra''s heaven", "Kings like Vasuki and Takshaka reside in my Loka", "Great figures like Arjuna and Garuda have journeyed to my depths in various legends"]','["मैं पृथ्वी के नीचे स्थित माना जाता हूँ", "मैं नागों का निवास स्थान हूँ", "मेरी राजधानी भोगवती को इंद्र के स्वर्ग से भी अधिक सुंदर और समृद्ध बताया गया है", "वासुकी और तक्षक जैसे नागराज मेरे लोक में रहते हैं", "अर्जुन और गरुड़ जैसे महान पात्रों ने विभिन्न कथाओं में मेरी गहराइयों की यात्रा की है"]');
INSERT INTO clue_riddles VALUES(265,'SHAIVISM','["I am a tradition focused on the worship of Shiva", "My followers see Shiva as the supreme deity", "The lingam is my main symbol of worship", "I include paths of devotion and meditation", "I am one of the major sects of Hinduism"]','["मैं शिव की उपासना पर आधारित एक परंपरा हूँ", "मेरे अनुयायी शिव को सर्वोच्च मानते हैं", "लिंग मेरा प्रमुख पूजनीय प्रतीक है", "मैं भक्ति और ध्यान के मार्ग को अपनाता हूँ", "मैं हिंदू धर्म के प्रमुख संप्रदायों में से एक हूँ"]');
INSERT INTO clue_riddles VALUES(266,'SATYAVATI','["I was born to a fisherman and carried a distinct fragrance", "I became the queen of Hastinapur", "I played a crucial role in the lineage of the Kuru dynasty", "I am the mother of Vyasa", "My marriage to King Shantanu led to the famous Bhishma Pratigya"]','["मेरा जन्म एक मछुआरे के घर हुआ और मुझमें विशेष सुगंध थी", "मैं हस्तिनापुर की रानी बनी", "मैंने कुरु वंश की परंपरा में महत्वपूर्ण भूमिका निभाई", "मैं व्यास की माता हूँ", "राजा शांतनु के साथ मेरे विवाह की शर्त के कारण ही भीष्म को अपनी भीषण प्रतिज्ञा लेनी पड़ी थी"]');
INSERT INTO clue_riddles VALUES(267,'DURGA','["I was created from the combined powers of all gods", "I ride a lion or tiger into battle", "I hold a weapon from each god in my ten hands", "I am worshipped for nine nights every autumn", "I am the invincible warrior goddess who slew Mahishasura"]','["मेरी रचना सभी देवताओं की संयुक्त शक्ति से हुई", "मैं सिंह या बाघ पर सवार होकर युद्ध में जाती हूँ", "मेरे दस हाथों में प्रत्येक देवता का एक अस्त्र है", "हर शरद ऋतु में नौ रातों तक मेरी पूजा होती है", "मैं अजेय योद्धा देवी हूँ जिसने महिषासुर का वध किया"]');
INSERT INTO clue_riddles VALUES(268,'TRIJATA','["I am a kind-hearted rakshasi in Lanka", "I saw a prophetic dream that foretold the downfall of Lanka", "I offered comfort and hope to a sorrowful queen held in captivity", "Unlike others around me, I showed kindness and wisdom in a hostile environment", "I am the rakshasi who supported Sita in the Ramayana"]','["मैं लंका में रहने वाली एक दयालु राक्षसी हूँ", "मैंने एक भविष्यसूचक स्वप्न देखा जिसमें लंका के पतन का संकेत था", "मैंने बंदी बनी एक रानी को सांत्वना और आशा दी", "अपने आसपास के लोगों से अलग, मैंने कठिन परिस्थितियों में भी करुणा और बुद्धिमत्ता दिखाई", "मैं वह राक्षसी हूँ जिसने रामायण में सीता का साथ दिया"]');
INSERT INTO clue_riddles VALUES(269,'SUBHADRA','["I am a princess connected to both the Yadava and Pandava lineages", "I was married to Arjuna", "I am the mother of a brave warrior who played a key role in a great war", "I am the sister of Krishna and Balarama", "I am worshipped alongside my brothers in the famous Jagannath Temple at Puri"]','["मैं एक राजकुमारी हूँ जो यादव और पांडव वंश दोनों से जुड़ी हूँ", "मेरा विवाह अर्जुन के साथ हुआ था", "मैं एक वीर योद्धा की माता हूँ जिसने महान युद्ध में महत्वपूर्ण भूमिका निभाई", "मैं कृष्ण और बलराम की बहन हूँ", "पुरी के प्रसिद्ध जगन्नाथ मंदिर में मेरी पूजा मेरे दोनों भाइयों के साथ की जाती है"]');
INSERT INTO clue_riddles VALUES(270,'BHISHMA','["I took a terrible vow of lifelong celibacy for my father", "I have the boon of dying only when I choose to", "I lay on a bed of arrows waiting for an auspicious day to die", "I could not be killed by anyone except through deception", "I am the grandsire of both Pandavas and Kauravas"]','["मैंने अपने पिता के लिए आजीवन ब्रह्मचर्य की भीषण प्रतिज्ञा ली", "मुझे इच्छामृत्यु का वरदान है", "मैं मृत्यु के शुभ दिन की प्रतीक्षा में बाणों की शय्या पर लेटा", "छल के अलावा कोई मुझे मार नहीं सकता था", "मैं पांडवों और कौरवों दोनों का पितामह हूँ"]');
INSERT INTO clue_riddles VALUES(271,'SAMBA','["I was born to a great deity and am known for my mischievous nature", "A prank involving sages led to a powerful curse upon my lineage", "I was cursed with leprosy and found my cure by worshipping the Sun God, Surya", "I am credited with establishing the famous Sun Temple at Maitravana", "I am one of the sons of Lord Krishna"]','["मैं एक महान देवता का पुत्र हूँ और अपने शरारती स्वभाव के लिए जाना जाता हूँ", "ऋषियों के साथ किए गए एक मज़ाक के कारण मुझे भयंकर श्राप मिला", "मुझे कुष्ठ रोग का श्राप मिला और मैंने सूर्य देव की पूजा करके अपना उद्धार किया", "मुझे मैत्रवन में प्रसिद्ध सूर्य मंदिर की स्थापना का श्रेय दिया जाता है", "मैं भगवान कृष्ण का पुत्र हूँ"]');
INSERT INTO clue_riddles VALUES(272,'AMAVASYA','["I am the 15th lunar day of the dark fortnight, signaling the peak of Krishna Paksha", "On my night, the moon remains hidden from view, leaving the sky in complete darkness", "I am considered a powerful time for honoring ancestors through Tarpana and Shradh", "I mark the conclusion of one lunar month and the birth of the next cycle", "The grand festival of Diwali is celebrated on me during the month of Kartika"]','["मैं कृष्ण पक्ष की पंद्रहवीं और सबसे अंधेरी चंद्र तिथि हूँ", "मेरी रात में चंद्रमा पूरी तरह अदृश्य रहता है और आकाश अंधकारमय होता है", "मुझे पितरों के तर्पण और श्राद्ध कर्म के लिए विशेष रूप से महत्वपूर्ण माना जाता है", "मैं एक चंद्र मास के समापन और अगले चक्र की शुरुआत का प्रतीक हूँ", "कार्तिक मास की मेरी ही रात को दीपावली का भव्य उत्सव मनाया जाता है"]');
INSERT INTO clue_riddles VALUES(273,'JANAKA','["I am a character in Ramayana", "My daughter emerged from the earth and became central to an epic tale", "I am often associated with deep spiritual knowledge and discussions with sages", "My kingdom is Mithila, a place of learning and virtue", "I am the father of Sita in the Ramayana"]','["मैं रामायण का एक पात्र हूँ", "मेरी पुत्री पृथ्वी से उत्पन्न हुई और एक महान कथा का केंद्र बनी", "मेरा संबंध गहन आध्यात्मिक ज्ञान और ऋषियों के साथ संवाद से है", "मेरा राज्य मिथिला है, जो ज्ञान और धर्म के लिए प्रसिद्ध है", "मैं रामायण में सीता के पिता हूँ"]');
INSERT INTO clue_riddles VALUES(274,'MENAKA','["I was sent to distract the most powerful meditating sage", "I succeeded in breaking his penance that threatened heaven", "I gave birth to a daughter whom I abandoned by a river", "My daughter was raised by birds and became Shakuntala", "I am the celestial nymph who distracted sage Vishwamitra"]','["मुझे सबसे शक्तिशाली ध्यानस्थ ऋषि का ध्यान भटकाने भेजा गया", "मैं उनकी तपस्या भंग करने में सफल हुई जो स्वर्ग के लिए खतरा थी", "मैंने एक पुत्री को जन्म दिया जिसे नदी किनारे छोड़ दिया", "मेरी पुत्री को पक्षियों ने पाला और वह शकुंतला बनी", "मैं वह अप्सरा हूँ जिसने ऋषि विश्वामित्र का ध्यान भटकाया"]');
INSERT INTO clue_riddles VALUES(275,'VAYU','["I am invisible yet I can uproot the mightiest trees", "Without me no living creature can survive", "My son carried a mountain through the sky", "The mightiest Pandava was born from my blessing", "I am the god of wind"]','["मैं अदृश्य हूँ फिर भी सबसे शक्तिशाली वृक्षों को उखाड़ सकता हूँ", "मेरे बिना कोई जीवित प्राणी जीवित नहीं रह सकता", "मेरे पुत्र ने एक पर्वत आकाश में उठाकर ले गया", "सबसे बलशाली पांडव मेरे आशीर्वाद से जन्मा", "मैं पवन देव हूँ"]');
INSERT INTO clue_riddles VALUES(276,'BHULOKA','["I am one of the realms in a multi-layered cosmic structure described in scriptures", "I exist between higher celestial worlds and lower realms", "I am the plane where humans experience karma through action and consequence", "I am associated with the physical world of life and existence", "I am the earthly realm in Hindu cosmology"]','["मैं शास्त्रों में वर्णित अनेक लोकों में से एक हूँ", "मैं ऊँचे दिव्य लोकों और नीचे के लोकों के बीच स्थित हूँ", "मैं वह स्थान हूँ जहाँ मनुष्य कर्म और उसके फल का अनुभव करता है", "मेरा संबंध भौतिक जीवन और अस्तित्व से है", "मैं हिंदू मान्यता में पृथ्वी लोक हूँ"]');
INSERT INTO clue_riddles VALUES(277,'KUBJA','["I prepared the finest sandalwood paste in all of Mathura", "I offered my precious paste to a divine prince walking to the arena", "My hunched back was straightened by a gentle divine touch", "My devotion earned me beauty and grace", "I am the hunchbacked perfume maker blessed by Krishna"]','["मैं पूरी मथुरा में सबसे उत्तम चंदन का लेप बनाती थी", "मैंने अपना बहुमूल्य लेप अखाड़े की ओर जाते एक दिव्य राजकुमार को अर्पित किया", "एक कोमल दिव्य स्पर्श से मेरी कुबड़ी पीठ सीधी हो गई", "मेरी भक्ति ने मुझे सुंदरता और शालीनता प्रदान की", "मैं कृष्ण द्वारा आशीर्वादित कुबड़ी इत्र निर्माता हूँ"]');
INSERT INTO clue_riddles VALUES(278,'HAVAN','["I am a sacred ritual where offerings are made into a consecrated fire", "Through me, mantras are chanted to invoke divine presence and blessings", "I symbolize purification of the environment and the inner self", "Ghee, herbs, and grains are commonly offered in me", "I simply mean a fire ritual"]','["मैं वह पवित्र अनुष्ठान हूँ जिसमें अग्नि में आहुति दी जाती है", "मेरे माध्यम से मंत्रों का उच्चारण कर दिव्य शक्तियों का आह्वान किया जाता है", "मैं वातावरण और आत्मा की शुद्धि का प्रतीक हूँ", "मेरे भीतर घी, जड़ी-बूटियाँ और अन्न की आहुति दी जाती है", "मैं सरल रूप में एक अग्नि अनुष्ठान हूँ"]');
INSERT INTO clue_riddles VALUES(279,'TRIVIKRAM','["I grew from a dwarf to cover the entire universe", "My first step covered the earth, my second the heavens", "I had no place for my third step so a king offered his head", "I sent a generous demon king to rule the underworld", "I am the cosmic form of Vishnu''s Vamana avatar"]','["मैं एक बौने से बढ़कर पूरे ब्रह्मांड को ढकने वाला हो गया", "मेरे पहले कदम ने पृथ्वी और दूसरे ने स्वर्ग को ढका", "मेरे तीसरे कदम के लिए जगह नहीं थी तो एक राजा ने अपना सिर अर्पित किया", "मैंने एक उदार राक्षस राजा को पाताल लोक पर राज करने भेजा", "मैं विष्णु के वामन अवतार का विराट रूप हूँ"]');
INSERT INTO clue_riddles VALUES(280,'AYYAPPA','["I am a deity born from the union of Shiva and a form of Vishnu", "My devotees undertake strict vows before visiting my sacred shrine in the hills", "I am associated with discipline, celibacy, and spiritual austerity", "My temple pilgrimage involves climbing eighteen sacred steps", "I am the deity worshipped at Sabarimala"]','["मैं शिव और विष्णु के एक रूप के मिलन से उत्पन्न देवता हूँ", "मेरे भक्त मेरे दर्शन से पहले कठोर व्रत का पालन करते हैं", "मेरा संबंध अनुशासन, ब्रह्मचर्य और तपस्या से है", "मेरे मंदिर की यात्रा में अठारह पवित्र सीढ़ियाँ चढ़नी होती हैं", "मैं सबरीमाला में पूजे जाने वाले भगवान हूँ"]');
INSERT INTO clue_riddles VALUES(281,'RATHYATRA','["Millions pull giant wooden chariots through the streets during me", "Three massive chariots carry three deities during my celebration", "My English name comes from the unstoppable force of the chariot", "I am celebrated most grandly in the city of Puri", "I am the great chariot festival of Lord Jagannath"]','["मेरे दौरान लाखों लोग विशाल लकड़ी के रथों को सड़कों पर खींचते हैं", "मेरे उत्सव में तीन विशाल रथ तीन देवताओं को ले जाते हैं", "मेरा अंग्रेजी नाम रथ की अजेय शक्ति से आता है", "मुझे पुरी शहर में सबसे भव्य रूप से मनाया जाता है", "मैं भगवान जगन्नाथ का महान रथ यात्रा उत्सव हूँ"]');
INSERT INTO clue_riddles VALUES(282,'BHRIGU','["I kicked Vishnu on his chest to test his patience", "I tested all three gods of the trinity for worthiness", "I declared Vishnu the most worthy of worship", "My descendants include both Shukracharya and Parashurama", "I am the sage who tested Brahma, Vishnu, and Shiva"]','["मैंने विष्णु की सहनशीलता परखने के लिए उनकी छाती पर लात मारी", "मैंने त्रिमूर्ति के तीनों देवताओं की योग्यता परखी", "मैंने विष्णु को पूजा के सबसे योग्य घोषित किया", "मेरे वंशजों में शुक्राचार्य और परशुराम दोनों शामिल हैं", "मैं वह ऋषि हूँ जिसने ब्रह्मा, विष्णु और शिव की परीक्षा ली"]');
INSERT INTO clue_riddles VALUES(283,'MAHABALI','["I was a righteous demon king more generous than any god", "I gave away my entire kingdom in three steps", "I am allowed to visit my people once a year", "The festival of Onam celebrates my annual return", "I am the demon king pushed to the underworld by Vamana"]','["मैं किसी भी देवता से अधिक उदार एक धर्मनिष्ठ राक्षस राजा था", "मैंने अपना पूरा राज्य तीन कदमों में दे दिया", "मुझे वर्ष में एक बार अपनी प्रजा से मिलने की अनुमति है", "ओणम त्योहार मेरी वार्षिक वापसी का उत्सव मनाता है", "मैं वह राक्षस राजा हूँ जिसे वामन ने पाताल लोक भेजा"]');
INSERT INTO clue_riddles VALUES(284,'ASHOK','["I am the garden where Sita was kept captive in Lanka", "Hanuman met Sita for the first time in me", "I witnessed her devotion and patience during exile", "I am filled with beautiful trees in Ravana’s kingdom", "My full name ends with ''Vatika''"]','["मैं वह उपवन हूँ जहाँ सीता को लंका में रखा गया था", "हनुमान ने पहली बार सीता से यहीं भेंट की", "मैंने उनके धैर्य और भक्ति को देखा", "मैं रावण के राज्य में सुंदर वृक्षों से भरा हूँ", "मेरा पूरा नाम ''वाटिका'' पर समाप्त होता है"]');
INSERT INTO clue_riddles VALUES(285,'PADMAVYUH','["I am a military formation shaped like a lotus flower", "A young prince entered me but could not find his way out", "Seven great warriors trapped and killed a teenager inside me", "I am the deadly lotus formation that killed Abhimanyu", "I am also known by the name Chakravyuh"]','["मैं कमल के फूल के आकार का सैन्य व्यूह हूँ", "एक युवा राजकुमार मुझमें प्रवेश किया पर बाहर का रास्ता नहीं पाया", "सात महान योद्धाओं ने एक किशोर को मेरे अंदर फँसाकर मारा", "मैं वह घातक कमल व्यूह हूँ जिसने अभिमन्यु को मारा", "मुझे चक्रव्यूह के नाम से भी जाना जाता है"]');
INSERT INTO clue_riddles VALUES(286,'JATASURA','["I am a demon mentioned in the Mahabharata", "I disguised myself as a Brahmin to deceive the Pandavas", "I attempted to kidnap Yudhishthira, Nakula, Sahadeva, and Draupadi", "I attempted to seize the Pandavas’ weapons", "I was ultimately slain by Bhima"]','["मैं महाभारत में वर्णित एक राक्षस हूँ", "मैंने ब्राह्मण का रूप धारण कर पांडवों को धोखा दिया", "मैंने युधिष्ठिर, नकुल, सहदेव और द्रौपदी के अपहरण का प्रयास किया था", "मैंने पांडवों के अस्त्रों को छीनने का प्रयास किया", "अंततः मेरा वध भीम द्वारा किया गया"]');
INSERT INTO clue_riddles VALUES(287,'NAGAS','["I am a race of semi-divine beings, often depicted as half-human and half-cobra", "I dwell in the subterranean realm of Patala, specifically in the city of Bhogavati", "I am known as the guardian of treasures, rivers, and lakes", "My prominent leaders include Shesha, who supports Lord Vishnu, and Vasuki, who coils around Shiva''s neck", "A major Hindu festival involving the offering of milk is dedicated to me during the month of Shravana"]','["मैं अर्ध-दिव्य प्राणियों की एक जाति हूँ, जिन्हें अक्सर आधा मानव और आधा नाग दिखाया जाता है", "मेरा निवास पाताल लोक में है, विशेष रूप से भोगवती नगरी में", "मुझे खजानों, नदियों और झीलों का रक्षक माना जाता है", "मेरे प्रमुख नायकों में शेषनाग (विष्णु के सेवक) और वासुकी (शिव के आभूषण) शामिल हैं", "श्रावण मास में दूध अर्पित करने वाला एक प्रमुख हिंदू त्योहार मुझे समर्पित है"]');
INSERT INTO clue_riddles VALUES(288,'RAKSHASA','["I am a race of powerful, shapeshifting supernatural beings in Hindu mythology", "I am often depicted as fierce, with large fangs and superhuman strength", "While many of my kind are antagonists, some like Vibhishana are known for their righteousness", "I am typically nocturnal and thrive in the darkness of the night", "The most famous king of my race ruled over the golden city of Lanka"]','["मैं हिंदू पौराणिक कथाओं में शक्तिशाली और मायावी शक्तियों वाले जीवों की एक जाति हूँ", "मुझे अक्सर बड़े दांतों, डरावने रूप और अलौकिक शक्ति के साथ चित्रित किया जाता है", "हालांकि मेरी जाति के अधिकांश जीव क्रूर माने जाते हैं, लेकिन विभीषण जैसे कुछ अपनी धार्मिकता के लिए जाने जाते हैं", "मैं आमतौर पर रात्रिचर हूँ और रात के अंधेरे में अधिक शक्तिशाली हो जाता हूँ", "मेरी जाति के सबसे प्रसिद्ध राजा ने सोने की लंका पर शासन किया था"]');
INSERT INTO clue_riddles VALUES(289,'PARSHURAM','["I cleared the earth of warriors twenty-one times", "I received my axe from Shiva after intense penance", "I am a Brahmin warrior, seemingly a contradiction", "I taught archery to both Bhishma and Karna", "I am the axe-wielding avatar of Vishnu"]','["मैंने इक्कीस बार पृथ्वी को क्षत्रियों से मुक्त किया", "मैंने कठोर तपस्या के बाद शिव से अपना फरसा प्राप्त किया", "मैं ब्राह्मण योद्धा हूँ, एक विरोधाभास सा प्रतीत होता", "मैंने भीष्म और कर्ण दोनों को धनुर्विद्या सिखाई", "मैं विष्णु का फरसा धारी अवतार हूँ"]');
INSERT INTO clue_riddles VALUES(290,'VARANASI','["I am one of the oldest continuously inhabited cities in the world", "Dying within my boundaries is believed to grant liberation", "Burning ghats on my riverbank never stop cremating the dead", "Buddha gave his first sermon near my outskirts", "I am the eternal city of Shiva on the banks of the Ganga"]','["मैं दुनिया की सबसे पुरानी लगातार बसी नगरियों में से एक हूँ", "मेरी सीमाओं में मरने पर मोक्ष मिलता है ऐसी मान्यता है", "मेरे नदी तट पर जलते घाट कभी अंत्येष्टि बंद नहीं करते", "बुद्ध ने मेरे बाहरी इलाके में अपना पहला उपदेश दिया", "मैं गंगा तट पर शिव की शाश्वत नगरी हूँ"]');
INSERT INTO clue_riddles VALUES(291,'KALKI','["I have not yet arrived but I am destined to come", "I will ride a white horse and carry a blazing sword", "I will appear when darkness covers the earth completely", "I will end the current age and begin a new golden age", "I am the future and final avatar of Vishnu"]','["मैं अभी तक नहीं आया हूँ पर मेरा आना निश्चित है", "मैं श्वेत घोड़े पर सवार होकर प्रज्वलित तलवार लिए आऊँगा", "मैं तब प्रकट होऊँगा जब अंधकार पूरी तरह पृथ्वी को ढक लेगा", "मैं वर्तमान युग को समाप्त कर नया स्वर्ण युग शुरू करूँगा", "मैं विष्णु का भविष्य और अंतिम अवतार हूँ"]');
INSERT INTO clue_riddles VALUES(292,'KETU','["I am the headless shadow in celestial mythology, born from a divided being", "I represent detachment, liberation, and spiritual insight in astrology", "I am paired with another entity that forms the eclipse-causing nodes", "My presence is linked with sudden transformation and karmic influence", "I am one of the nine celestial influencers in Hindu astrology"]','["मैं वह छायाग्रह हूँ जिसका सिर नहीं है और जो एक विभाजित अस्तित्व से उत्पन्न हुआ", "ज्योतिष में मैं वैराग्य, मुक्ति और आध्यात्मिक ज्ञान का प्रतिनिधित्व करता हूँ", "मैं एक अन्य ग्रह के साथ मिलकर ग्रहण के कारण बनता हूँ", "मेरा प्रभाव अचानक परिवर्तन और कर्म से जुड़ा होता है", "मैं हिंदू ज्योतिष के नौ ग्रहों में से एक हूँ"]');
INSERT INTO clue_riddles VALUES(293,'BHAJAN','["I am a heartfelt expression of devotion often performed in melody and rhythm", "Through me, the divine is remembered with love and emotion", "Communities gather to perform me in temples and homes alike", "I often include the names and glories of deities in lyrical form", "I simply mean a devotional song"]','["मैं भक्ति की भावनाओं को सुर और ताल में व्यक्त करने का माध्यम हूँ", "मेरे द्वारा ईश्वर को प्रेम और भावना से स्मरण किया जाता है", "मंदिरों और घरों में लोग मिलकर मुझे गाते हैं", "मेरे गीतों में देवताओं के नाम और महिमा का वर्णन होता है", "मैं सरल रूप में एक भक्ति गीत हूँ"]');
INSERT INTO clue_riddles VALUES(294,'YAKSHI','["I am a female nature spirit of forests and trees", "I am a guardian of hidden treasures for Lord Kubera", "You may find my sculptures adorning ancient temples", "I appear in Hindu, Jain, and Buddhist mythologies", "I am often depicted in temple sculptures as Salabhanjika"]','["मैं वनों और वृक्षों की एक स्त्री प्रकृति आत्मा हूँ", "मैं कुबेर देव के गुप्त खजानों की रक्षक मानी जाती हूँ", "मेरी मूर्तियाँ प्राचीन मंदिरों में देखी जा सकती हैं", "मेरा वर्णन हिंदू, जैन और बौद्ध कथाओं में मिलता है", "मुझे अक्सर मंदिरों में ''शालभंजिका'' के रूप में दिखाया जाता है"]');
INSERT INTO clue_riddles VALUES(295,'VAMANA','["I appeared as a small boy carrying an umbrella", "I asked for only three steps of land as a gift", "My tiny form fooled a generous king", "With two steps I covered the entire universe", "I am the dwarf avatar of Vishnu"]','["मैं छाता लिए एक छोटे बालक के रूप में प्रकट हुआ", "मैंने उपहार में केवल तीन पग भूमि माँगी", "मेरे छोटे रूप ने एक उदार राजा को भ्रमित किया", "दो कदमों में मैंने पूरा ब्रह्मांड ढक लिया", "मैं विष्णु का वामन अवतार हूँ"]');
INSERT INTO clue_riddles VALUES(296,'TILAK','["I am applied on the forehead between the eyebrows", "I am made from sandalwood paste, kumkum, or sacred ash", "I mark the spot of the spiritual third eye", "My shape indicates which deity a person worships", "I am the sacred forehead mark worn by Hindus"]','["मुझे भौहों के बीच माथे पर लगाया जाता है", "मैं चंदन, कुमकुम या पवित्र भस्म से बनता हूँ", "मैं आध्यात्मिक तीसरी आँख का स्थान चिह्नित करता हूँ", "मेरा आकार बताता है कि व्यक्ति किस देवता की पूजा करता है", "मैं हिंदुओं द्वारा लगाया जाने वाला पवित्र तिलक हूँ"]');
INSERT INTO clue_riddles VALUES(297,'NATARAJA','["I dance within a ring of cosmic fire", "My dance creates, preserves, and destroys the universe", "I have four arms each representing a different cosmic function", "A small dwarf of ignorance is crushed under my foot", "I am Lord Shiva in his cosmic dancing form"]','["मैं ब्रह्मांडीय अग्नि के वलय में नृत्य करता हूँ", "मेरा नृत्य ब्रह्मांड की सृष्टि, पालन और विनाश करता है", "मेरी चार भुजाएँ प्रत्येक एक अलग ब्रह्मांडीय कार्य का प्रतीक हैं", "अज्ञानता का एक छोटा बौना मेरे पैर के नीचे कुचला जाता है", "मैं नटराज रूप में भगवान शिव हूँ"]');
INSERT INTO clue_riddles VALUES(298,'CHAKRA','["I symbolize the eternal cycle of time, dharma, and cosmic order", "I am associated with both spiritual energy centers and divine weaponry", "In yogic traditions, I exist within the human body as points of power", "In epics, I appear as a spinning weapon wielded by Lord Vishnu", "I am often depicted as a circular disc or wheel"]','["मैं समय, धर्म और सृष्टि के सतत प्रवाह का प्रतीक हूँ", "मेरा संबंध आध्यात्मिक ऊर्जा केंद्रों और दिव्य अस्त्र दोनों से है", "योग परंपरा में मैं मानव शरीर में शक्ति केंद्रों के रूप में स्थित हूँ", "महाकाव्यों में मैं भगवान विष्णु के घूमते हुए अस्त्र के रूप में प्रकट होता हूँ", "मुझे अक्सर एक गोल पहिए या डिस्क के रूप में दर्शाया जाता है"]');
INSERT INTO clue_riddles VALUES(299,'VEDANTA','["I explore the ultimate nature of reality and the self beyond ritual and form", "My teachings are primarily derived from the concluding portions of ancient scriptures", "Philosophers interpret me to explain the relationship between Atman and Brahman", "I am one of the six orthodox schools of Hindu philosophy", "I simply mean the end or culmination of the Vedas"]','["मैं परम सत्य और आत्मा के स्वरूप का अध्ययन करता हूँ जो कर्मकांड से परे है", "मेरी शिक्षाएँ प्राचीन शास्त्रों के अंतिम भागों से प्राप्त होती हैं", "दार्शनिक मेरे माध्यम से आत्मा और ब्रह्म के संबंध को समझाते हैं", "मैं हिंदू दर्शन के छह आस्तिक दर्शनों में से एक हूँ", "मैं सरल रूप में वेदों का निष्कर्ष और सार हूँ।"]');
INSERT INTO clue_riddles VALUES(300,'GAYATRI','["I am chanted at sunrise by millions every day", "I am considered the mother of all Vedic mantras", "I have twenty-four syllables arranged in a sacred meter", "Sage Vishwamitra revealed me to the world", "I am the most sacred mantra addressed to the sun"]','["हर रोज़ सूर्योदय पर लाखों लोग मेरा जाप करते हैं", "मुझे सभी वैदिक मंत्रों की जननी माना जाता है", "मेरे चौबीस अक्षर एक पवित्र छंद में व्यवस्थित हैं", "ऋषि विश्वामित्र ने मुझे संसार के सामने प्रकट किया", "मैं सूर्य को संबोधित सबसे पवित्र मंत्र हूँ"]');
INSERT INTO clue_riddles VALUES(301,'JAPA','["I am a practice where sound becomes a bridge between the mind and the divine", "Through repetition, I help still the fluctuations of thought", "I am often performed using beads to maintain rhythm and focus", "Mantras are softly or silently repeated in me", "I simply mean chanting or repetition of sacred names"]','["मैं वह साधना हूँ जिसमें ध्वनि मन और ईश्वर के बीच सेतु बनती है", "मेरे माध्यम से विचारों की चंचलता शांत होती है", "मुझे अक्सर माला के साथ किया जाता है ताकि ध्यान और लय बनी रहे", "मेरे भीतर मंत्रों का धीमे या मौन रूप से जप किया जाता है", "मैं सरल रूप में मंत्रों के दोहराव की क्रिया हूँ"]');
INSERT INTO clue_riddles VALUES(302,'AYODHYA','["My name means the city that cannot be conquered", "I was the capital of the greatest solar dynasty kings", "A prince left me for fourteen years of exile in the forest", "The entire city wept when its beloved prince departed", "I am the birthplace and capital city of Lord Rama"]','["मेरे नाम का अर्थ है वह नगरी जिसे जीता नहीं जा सकता", "मैं महानतम सूर्यवंशी राजाओं की राजधानी थी", "एक राजकुमार चौदह वर्ष के वनवास के लिए मुझसे गया", "जब प्रिय राजकुमार गए तो पूरी नगरी रो पड़ी", "मैं भगवान राम की जन्मभूमि और राजधानी हूँ"]');
INSERT INTO clue_riddles VALUES(303,'DWARKA','["I was built on the western coast reclaimed from the sea", "My golden walls and crystal palaces shone like the sun", "I sank beneath the ocean after my lord departed earth", "Underwater ruins near Gujarat may be my remains", "I am the legendary coastal kingdom of Lord Krishna"]','["मेरा निर्माण समुद्र से प्राप्त पश्चिमी तट पर हुआ", "मेरी स्वर्ण दीवारें और स्फटिक महल सूर्य की भाँति चमकते थे", "मेरे प्रभु के पृथ्वी छोड़ने के बाद मैं समुद्र में डूब गया", "गुजरात के निकट पानी के नीचे के खंडहर मेरे अवशेष हो सकते हैं", "मैं भगवान कृष्ण का पौराणिक तटीय राज्य हूँ"]');
INSERT INTO clue_riddles VALUES(304,'PURI','["My temple kitchen feeds a hundred thousand people daily", "The flag on my temple always flies against the wind", "No bird or plane flies over my main temple", "The shadow of my temple''s tower is never visible", "I am the sacred city of Lord Jagannath in Odisha"]','["मेरे मंदिर की रसोई प्रतिदिन एक लाख लोगों को भोजन कराती है", "मेरे मंदिर का ध्वज सदा हवा के विपरीत लहराता है", "कोई पक्षी या विमान मेरे मुख्य मंदिर के ऊपर नहीं उड़ता", "मेरे मंदिर के शिखर की छाया कभी दिखाई नहीं देती", "मैं ओडिशा में भगवान जगन्नाथ की पवित्र नगरी हूँ"]');
INSERT INTO clue_riddles VALUES(305,'KATYAYANI','["I am a fierce form of the divine feminine invoked to destroy evil forces", "My origin is linked to the penance of a sage after whom I am named", "Young maidens worship me seeking a worthy life partner", "I am one among the nine celebrated forms of a powerful goddess", "I am a form of Goddess Durga"]','["मैं दिव्य स्त्री शक्ति का उग्र रूप हूँ जिसे बुराई के नाश के लिए पूजते हैं", "मेरा जन्म एक ऋषि की तपस्या से जुड़ा है जिनके नाम पर मेरा नाम पड़ा", "कन्याएँ मुझे उत्तम जीवनसाथी की कामना से पूजती हैं", "मैं देवी के नौ रूपों में से एक हूँ", "मैं देवी दुर्गा का एक रूप हूँ"]');
INSERT INTO clue_riddles VALUES(306,'MATHURA','["A divine child was born in my prison on a stormy night", "A tyrant king ruled me with fear and cruelty", "The child returned years later to free me from tyranny", "I am one of the seven sacred cities of Hinduism", "I am the birthplace of Lord Krishna"]','["एक तूफानी रात मेरे कारागार में एक दिव्य शिशु का जन्म हुआ", "एक अत्याचारी राजा ने भय और क्रूरता से मुझ पर शासन किया", "वह बालक वर्षों बाद मुझे अत्याचार से मुक्त करने लौटा", "मैं हिंदू धर्म के सात पवित्र नगरों में से एक हूँ", "मैं भगवान कृष्ण की जन्मभूमि हूँ"]');
INSERT INTO clue_riddles VALUES(307,'TULSIDAS','["My parents abandoned me because I was born under an unlucky star", "My wife''s taunt about my attachment turned me towards God", "I retold the greatest epic in the language of the common people", "My version of the Ramayana is recited in every Hindu home in north India", "I am the poet-saint who wrote the Ramcharitmanas"]','["मेरे माता-पिता ने मुझे अशुभ नक्षत्र में जन्म होने के कारण त्याग दिया", "मेरी पत्नी की आसक्ति पर फटकार ने मुझे ईश्वर की ओर मोड़ा", "मैंने महानतम महाकाव्य को आम लोगों की भाषा में पुनः कथित किया", "उत्तर भारत के हर हिंदू घर में मेरी रामायण का पाठ होता है", "मैं रामचरितमानस के रचयिता कवि-संत हूँ"]');
INSERT INTO clue_riddles VALUES(308,'KALIDASA','["I was supposedly foolish until the goddess of learning blessed me", "I wrote about a cloud carrying a message of love across India", "My play about a forgotten ring is performed worldwide", "I am considered the Shakespeare of Sanskrit literature", "I am the greatest poet and dramatist of ancient India"]','["माना जाता है कि विद्या की देवी के आशीर्वाद से पहले मैं मूर्ख था", "मैंने एक बादल के बारे में लिखा जो भारत भर में प्रेम संदेश ले जाता है", "मेरा भूली हुई अँगूठी वाला नाटक विश्वभर में खेला जाता है", "मुझे संस्कृत साहित्य का शेक्सपियर माना जाता है", "मैं प्राचीन भारत का महानतम कवि और नाटककार हूँ"]');
INSERT INTO clue_riddles VALUES(309,'PATANJALI','["I fell from heaven as a tiny snake into the palms of a praying woman", "I systematized an ancient practice into eight limbs", "My sutras are the foundation of one of the six schools of Hindu philosophy", "Every yoga teacher in the world follows my framework", "I am the ancient sage who authored the Yoga Sutras"]','["मैं स्वर्ग से एक छोटे सर्प के रूप में एक प्रार्थना करती महिला की हथेलियों में गिरा", "मैंने एक प्राचीन अभ्यास को आठ अंगों में व्यवस्थित किया", "मेरे सूत्र हिंदू दर्शन के छह स्कूलों में से एक की नींव हैं", "दुनिया का हर योग शिक्षक मेरे ढाँचे का अनुसरण करता है", "मैं योग सूत्र के रचयिता प्राचीन ऋषि हूँ"]');
INSERT INTO clue_riddles VALUES(310,'SUSHRUTA','["I performed surgeries thousands of years before modern medicine", "I described over a hundred surgical instruments in my texts", "I pioneered rhinoplasty, the reconstruction of the nose", "My students practiced surgery on vegetables and dead animals", "I am the father of surgery in ancient India"]','["मैंने आधुनिक चिकित्सा से हजारों वर्ष पहले शल्य चिकित्सा की", "मैंने अपने ग्रंथों में सौ से अधिक शल्य उपकरणों का वर्णन किया", "मैंने नाक के पुनर्निर्माण, राइनोप्लास्टी का बीड़ा उठाया", "मेरे शिष्यों ने सब्जियों और मृत जानवरों पर शल्य अभ्यास किया", "मैं प्राचीन भारत में शल्य चिकित्सा का जनक हूँ"]');
INSERT INTO clue_riddles VALUES(311,'CHARAKA','["I documented hundreds of medicinal plants and their uses", "I believed that prevention is better than cure", "My text is one of the foundational works of Ayurveda", "I described the human body as composed of three doshas", "I am the ancient physician who wrote the Charaka Samhita"]','["मैंने सैकड़ों औषधीय पौधों और उनके उपयोगों का प्रलेखन किया", "मैं मानता था कि इलाज से बेहतर बचाव है", "मेरा ग्रंथ आयुर्वेद की मूलभूत कृतियों में से एक है", "मैंने मानव शरीर को तीन दोषों से बना बताया", "मैं चरक संहिता लिखने वाला प्राचीन चिकित्सक हूँ"]');
INSERT INTO clue_riddles VALUES(312,'ARYABHATA','["I calculated the value of pi to remarkable accuracy", "I proposed that the earth rotates on its axis", "I gave the world the concept of zero in mathematics", "I explained lunar and solar eclipses correctly", "I am the great ancient Indian mathematician and astronomer"]','["मैंने पाई का मान उल्लेखनीय सटीकता से निकाला", "मैंने प्रस्तावित किया कि पृथ्वी अपनी धुरी पर घूमती है", "मैंने संसार को गणित में शून्य की अवधारणा दी", "मैंने चंद्र और सूर्य ग्रहण को सही ढंग से समझाया", "मैं महान प्राचीन भारतीय गणितज्ञ और खगोलशास्त्री हूँ"]');
INSERT INTO clue_riddles VALUES(313,'EKADASHI','["I occur twice in a lunar month and hold special significance for spiritual discipline", "Observing me often involves fasting and devotion to a preserver deity", "I fall on the eleventh day of both waxing and waning moon phases", "Devotees often observe a fast on this day to cleanse the body and mind", "I am a sacred fasting day in the Hindu calendar"]','["मैं एक चंद्र मास में दो बार आता हूँ और आध्यात्मिक अनुशासन के लिए महत्वपूर्ण हूँ", "मेरे दिन उपवास और भगवान विष्णु की भक्ति की जाती है", "मैं शुक्ल और कृष्ण पक्ष की ग्यारहवीं तिथि को पड़ता हूँ", "भक्त शरीर और मन की शुद्धि के लिए इस दिन व्रत रखते हैं", "मैं हिंदू पंचांग का एक पवित्र व्रत दिवस हूँ"]');
INSERT INTO clue_riddles VALUES(314,'MEGHADUTA','["I tell the story of a lovesick exile who sends a message through the sky", "A passing cloud becomes a messenger of love in my verses", "I describe the beautiful landscapes of India from south to north", "My narrator is a celestial being cursed to live apart from his beloved", "I am the cloud messenger poem by Kalidasa"]','["मैं एक प्रेम व्याकुल निर्वासित की कहानी कहता हूँ जो आकाश से संदेश भेजता है", "मेरे छंदों में एक गुज़रता बादल प्रेम का दूत बनता है", "मैं भारत के सुंदर परिदृश्यों का दक्षिण से उत्तर तक वर्णन करता हूँ", "मेरा कथावाचक एक श्रापित दिव्य प्राणी है जो अपनी प्रियतमा से अलग रहता है", "मैं कालिदास का मेघदूत काव्य हूँ"]');
INSERT INTO clue_riddles VALUES(315,'UGADI','["I mark the beginning of a new cosmic cycle according to a lunar-solar calendar", "My arrival is determined by the first day of the Chaitra month", "I am celebrated with a special mixture symbolizing different flavors of life", "I signify the New Year in parts of South India like Andhra Pradesh and Karnataka", "I am a festival that welcomes a fresh start and new beginnings"]','["मैं चंद्र-सौर पंचांग के अनुसार एक नए कालचक्र की शुरुआत का संकेत हूँ", "मेरा आगमन चैत्र मास के पहले दिन होता है", "मेरे अवसर पर जीवन के विभिन्न स्वादों का प्रतीक एक विशेष मिश्रण बनाया जाता है", "मैं आंध्र प्रदेश और कर्नाटक जैसे दक्षिण भारतीय राज्यों का नववर्ष हूँ", "मैं एक ऐसा पर्व हूँ जो नई शुरुआत और नए आरंभ का स्वागत करता है"]');
INSERT INTO clue_riddles VALUES(316,'PURNIMA','["I mark the peak of the Shukla Paksha (waxing phase) of the moon", "Many spiritual observances and rituals are aligned with my occurrence", "I occur once every lunar month during the bright fortnight", "Festivals like Guru and Buddha celebrations often fall on me", "I am the full moon day in the Hindu calendar"]','["मैं उस रात का प्रतीक हूँ जब चंद्रमा अपनी पूर्ण कलाओं के साथ आकाश में शोभायमान होता है", "कई धार्मिक अनुष्ठान और व्रत मेरे दिन किए जाते हैं", "मैं हर चंद्र मास में शुक्ल पक्ष के अंत में आता हूँ", "गुरु और बुद्ध से जुड़े कई पर्व मेरे दिन पड़ते हैं", "मैं हिंदू पंचांग में पूर्णिमा तिथि हूँ"]');
INSERT INTO clue_riddles VALUES(317,'ACHARYA','["I am one who not only teaches knowledge but also lives it as an example", "In tradition, I guide disciples through both instruction and conduct", "I hold authority in interpreting sacred texts and philosophical systems", "Students look to me for wisdom, discipline, and spiritual direction", "I simply mean a revered teacher or गुरु"]','["मैं वह हूँ जो केवल ज्ञान नहीं सिखाता बल्कि स्वयं उसे आचरण में भी लाता है", "परंपरा में मैं शिष्यों का मार्गदर्शन शिक्षा और आचरण दोनों से करता हूँ", "मुझे शास्त्रों और दर्शन की व्याख्या करने का अधिकार प्राप्त होता है", "विद्यार्थी मुझसे ज्ञान, अनुशासन और आध्यात्मिक दिशा प्राप्त करते हैं", "मैं सरल रूप में एक आदरणीय गुरु हूँ"]');
INSERT INTO clue_riddles VALUES(318,'KAIVALYA','["I am the ultimate goal of the Yoga Sutras of Patanjali", "My name literally means ''Aloneness'' or ''Absolute Isolation'' of the soul", "I am the state where the Self realizes it is distinct from matter", "I am the title of the fourth and final chapter of the Yoga Sutras", "I represent the final liberation from the cycle of birth, death, and suffering"]','["मैं महर्षि पतंजलि के योग सूत्रों का अंतिम और सर्वोच्च लक्ष्य हूँ", "मेरे नाम का शाब्दिक अर्थ आत्मा का ''अकेलापन'' या ''पूर्ण पृथक्करण'' है", "मैं वह अवस्था हूँ जहाँ आत्मा स्वयं को प्रकृति से पूरी तरह भिन्न अनुभव करता है", "मैं योग सूत्र के चौथे और अंतिम अध्याय का शीर्षक हूँ", "मैं जन्म, मृत्यु और दुखों के चक्र से अंतिम मुक्ति का प्रतिनिधित्व करता हूँ"]');
INSERT INTO clue_riddles VALUES(319,'MANU','["I survived the great flood by building a boat at a fish''s command", "I am considered the first man and ancestor of all humans", "The laws governing ancient society are attributed to me", "A fish guided my boat through the deluge to safety", "I am the progenitor of mankind in Hindu tradition"]','["मैंने एक मछली के निर्देश पर नाव बनाकर महाप्रलय से बचा", "मुझे पहला मनुष्य और सभी मानवों का पूर्वज माना जाता है", "प्राचीन समाज को शासित करने वाले नियम मुझे प्रदान किए जाते हैं", "एक मछली ने मेरी नाव को प्रलय से सुरक्षा तक पहुँचाया", "मैं हिंदू परंपरा में मानवजाति का जनक हूँ"]');
INSERT INTO clue_riddles VALUES(320,'SWAYAMVAR','["I am an ancient ceremony where a princess chooses her husband", "Suitors compete in tests of strength, skill, or valor before me", "Draupadi''s famous fish-eye test was a form of me", "Sita''s bow-lifting challenge was another form of me", "I am the self-choice marriage ceremony of ancient India"]','["मैं एक प्राचीन समारोह हूँ जहाँ राजकुमारी अपना पति चुनती है", "मेरे दौरान वर शक्ति, कौशल या वीरता की परीक्षा में प्रतिस्पर्धा करते हैं", "द्रौपदी की प्रसिद्ध मछली-नेत्र परीक्षा मेरा एक रूप थी", "सीता की धनुष उठाने की चुनौती मेरा एक अन्य रूप थी", "मैं प्राचीन भारत का स्वयंवर विवाह समारोह हूँ"]');
INSERT INTO clue_riddles VALUES(321,'PARIKSHIT','["I was born after a devastating war, saved in the womb by divine intervention", "I am the grandson of a great warrior and heir to a legendary lineage", "A sage''s curse led to my death by a serpent king", "I am the king who heard the Bhagavata Purana before my death", "I am the grandson of Arjuna and the son of Abhimanyu and Uttara"]','["मैं एक महान युद्ध के बाद जन्मा और गर्भ में दिव्य कृपा से बचाया गया", "मैं एक महान योद्धा का पौत्र और एक प्रसिद्ध वंश का उत्तराधिकारी हूँ", "एक ऋषि के श्राप के कारण मेरी मृत्यु सर्प राजा द्वारा हुई", "मैं वह राजा हूँ जिसने मृत्यु से पहले भागवत पुराण सुना", "मैं अर्जुन का पोता और अभिमन्यु तथा उत्तरा का पुत्र हूँ"]');
INSERT INTO clue_riddles VALUES(322,'BELARSEN','["I am the son of Ghatotkacha and grandson of Bhima", "I am known as the ''Warrior of Three Arrows''", "I vowed to always fight for the losing side", "I gave my head to Krishna as ''Sheesh Daan''", "I am worshipped today as Khatu Shyam"]','["मैं घटोत्कच का पुत्र और भीम का पौत्र हूँ", "मुझे ''तीन बाणों का धारी'' कहा जाता है", "मैंने हमेशा हारने वाले का साथ देने का वचन दिया था", "मैंने कृष्ण को अपना ''शीश दान'' कर दिया था", "आज मुझे खाटू श्याम के रूप में पूजा जाता है"]');
INSERT INTO clue_riddles VALUES(323,'DHWAJA','["I am seen atop temples", "I symbolize victory, identity, and devotion", "In the Mahabharata, Arjuna’s chariot carried me with Hanuman on it", "I flutter high as a sign of faith and pride", "I mark the presence of divinity at a place"]','["मैं मंदिरों के ऊपर दिखाई देता हूँ", "मैं विजय, पहचान और भक्ति का प्रतीक हूँ", "महाभारत में अर्जुन के रथ पर मैं था, जिस पर हनुमान का चिन्ह था", "मैं आस्था और गौरव का संकेत बनकर ऊँचा लहराता हूँ", "मैं किसी स्थान पर दिव्यता की उपस्थिति दर्शाता हूँ"]');
INSERT INTO clue_riddles VALUES(324,'JARASANDH','["I was born in two halves that were joined by a demoness", "I attacked Mathura seventeen times to avenge my sons-in-law", "I imprisoned ninety-five kings for a grand sacrifice", "I could only be killed by being torn apart", "I am the mighty king of Magadha killed by Bhima"]','["मेरा जन्म दो टुकड़ों में हुआ जिन्हें एक राक्षसी ने जोड़ा", "मैंने अपने दामादों का बदला लेने के लिए मथुरा पर सत्रह बार हमला किया", "मैंने एक महायज्ञ के लिए पंचानवे राजाओं को कैद किया", "मुझे केवल चीरकर ही मारा जा सकता था", "मैं भीम द्वारा मारा गया मगध का शक्तिशाली राजा हूँ"]');
INSERT INTO clue_riddles VALUES(325,'SATYAKI','["I am a Vrishni warrior and Krishna''s close kinsman", "I am the favorite disciple of Arjuna in archery", "I fought for the Pandavas in the Kurukshetra war", "I am one of the few survivors of the great battle", "I am also known by the name Yuyudhana"]','["मैं वृष्णि वंश का योद्धा और कृष्ण का निकट संबंधी हूँ", "मैं धनुर्विद्या में अर्जुन का प्रिय शिष्य हूँ", "मैंने कुरुक्षेत्र युद्ध में पांडवों की ओर से लड़ाई लड़ी", "मैं उन गिने-चुने योद्धाओं में से हूँ जो युद्ध में जीवित बचे", "मुझे युयुधान के नाम से भी जाना जाता है"]');
INSERT INTO clue_riddles VALUES(326,'PARIJATA','["I am a divine tree that emerged from the churning of the ocean", "My flowers bloom at night and fall by dawn", "My fragrance can fill an entire world", "Krishna brought me from heaven to earth for his queen", "I am the celestial wish-fulfilling tree from Indra''s garden"]','["मैं समुद्र मंथन से निकला एक दिव्य वृक्ष हूँ", "मेरे फूल रात में खिलते हैं और सुबह तक गिर जाते हैं", "मेरी सुगंध एक पूरे लोक को भर सकती है", "कृष्ण मुझे अपनी रानी के लिए स्वर्ग से पृथ्वी पर लाए", "मैं इंद्र के बगीचे का दिव्य कल्पवृक्ष हूँ"]');
INSERT INTO clue_riddles VALUES(327,'KAMADHENU','["I can fulfill any wish of my owner", "Armies were created from me to protect a sage''s hermitage", "A king tried to steal me but failed against my power", "I provide unlimited milk and grant all desires", "I am the divine wish-fulfilling cow of sage Vasishtha"]','["मैं अपने स्वामी की कोई भी इच्छा पूरी कर सकती हूँ", "एक ऋषि के आश्रम की रक्षा के लिए मुझसे सेनाएँ बनाई गईं", "एक राजा ने मुझे चुराने का प्रयास किया पर मेरी शक्ति के सामने विफल रहा", "मैं अनंत दूध देती हूँ और सभी इच्छाएँ पूरी करती हूँ", "मैं ऋषि वसिष्ठ की दिव्य कामधेनु गाय हूँ"]');
INSERT INTO clue_riddles VALUES(328,'PUJA','["I involve offerings of flowers, incense, light, and food", "I can be performed at home or in a temple", "A bell is rung and a lamp is waved during me", "I express devotion and gratitude to the divine", "I am the Hindu prayer ritual of worship"]','["मुझमें फूल, धूप, दीप और भोजन का अर्पण शामिल है", "मुझे घर या मंदिर में किया जा सकता है", "मेरे दौरान घंटी बजाई जाती है और दीप घुमाया जाता है", "मैं ईश्वर के प्रति भक्ति और कृतज्ञता व्यक्त करती हूँ", "मैं हिंदू प्रार्थना पूजा अनुष्ठान हूँ"]');
INSERT INTO clue_riddles VALUES(329,'NARAKASUR','["I stole the earrings of the mother of gods", "I imprisoned sixteen thousand princesses in my palace", "I was killed by Krishna and his warrior queen", "I am the demon whose defeat is celebrated on Diwali", "My name means ''hell-dweller''"]','["मैंने देवताओं की माता के कुंडल चुराए", "मैंने सोलह हज़ार राजकुमारियों को अपने महल में कैद किया", "मुझे कृष्ण और उनकी योद्धा रानी ने मारा", "मैं वह राक्षस हूँ जिसकी पराजय दीवाली पर मनाई जाती है", "मेरे नाम का अर्थ है ''नरक का निवासी''"]');
INSERT INTO clue_riddles VALUES(330,'SAPTAPURI','["I represent the holiest pilgrimage destinations", "I refer to seven sacred cities in Hindu tradition", "Visiting me is believed to grant moksha", "Cities like Kashi and Ayodhya are part of me", "My name means ‘seven cities’"]','["मैं सबसे पवित्र तीर्थ स्थलों का समूह हूँ", "मैं हिंदू परंपरा के सात पवित्र नगरों को दर्शाता हूँ", "मेरी यात्रा मोक्ष प्रदान करने वाली मानी जाती है", "काशी और अयोध्या जैसे नगर मेरा हिस्सा हैं", "मेरा अर्थ है ‘सात शहर’"]');
INSERT INTO clue_riddles VALUES(331,'HOLI','["Colors are thrown on everyone without distinction on my day", "A bonfire the night before me marks the triumph of devotion", "I celebrate the eternal love between Radha and Krishna", "A demoness was burned in the fire she meant to kill her nephew in", "I am the festival of colors celebrating spring"]','["मेरे दिन बिना भेदभाव सबके ऊपर रंग फेंके जाते हैं", "मुझसे एक रात पहले होलिका दहन भक्ति की विजय का प्रतीक है", "मैं राधा और कृष्ण के शाश्वत प्रेम का उत्सव हूँ", "एक राक्षसी उसी अग्नि में जली जिसमें वह अपने भतीजे को मारना चाहती थी", "मैं वसंत का उत्सव रंगों का त्योहार हूँ"]');
INSERT INTO clue_riddles VALUES(332,'VARUNA','["I bind sinners with my divine noose", "I know every truth and every lie spoken", "I rule over the vast waters of the world", "My mount is a crocodile called Makara", "I am the god of oceans and cosmic order"]','["मैं पापियों को अपने दिव्य पाश से बांधता हूँ", "मैं हर सत्य और हर झूठ जानता हूँ", "मैं संसार के विशाल जल पर शासन करता हूँ", "मेरा वाहन मकर नामक मगरमच्छ है", "मैं समुद्र और ब्रह्मांडीय व्यवस्था का देवता हूँ"]');
INSERT INTO clue_riddles VALUES(333,'CHINTAN','["I am the silent process where the mind turns inward to examine truth beyond appearances", "Philosophers and sages rely on me to arrive at deeper understanding and wisdom", "I often arise in moments of solitude, guiding one toward clarity and self-realization", "I involve careful thought, reflection, and analysis of ideas or experiences", "I simply mean deep thinking or contemplation"]','["मैं वह शांत प्रक्रिया हूँ जिसमें मन बाहरी रूपों से परे सत्य को समझने के लिए भीतर की ओर जाता है", "ऋषि और दार्शनिक मेरे माध्यम से गहन ज्ञान और समझ प्राप्त करते हैं", "मैं अक्सर एकांत में उत्पन्न होता हूँ और व्यक्ति को स्पष्टता तथा आत्मबोध की ओर ले जाता हूँ", "मैं विचारों और अनुभवों पर गहराई से मनन और विश्लेषण करना हूँ", "मैं सरल रूप में गहरी सोच या मनन हूँ"]');
INSERT INTO clue_riddles VALUES(334,'ATRI','["I was born from the mind of Lord Brahma", "I am the husband of the virtuous Anusuya", "I am one of the Saptarishis", "I am the father of Dattatreya, Durvasa, and Chandra", "The fifth Mandala of the Rig Veda is attributed to me"]','["मेरा जन्म ब्रह्मा जी के मानस पुत्र के रूप में हुआ था", "मैं परम सती अनुसूया का पति हूँ", "मैं सप्तऋषियों में से एक हूँ", "मैं दत्तात्रेय, दुर्वासा और चंद्र का पिता हूँ", "ऋग्वेद का पाँचवाँ मण्डल मुझसे ही संबंधित है"]');
INSERT INTO clue_riddles VALUES(335,'AGNEYA','["I am the South-East direction in Hindu cosmology", "I am ruled by Agni, the God of Fire", "In Vastu, I am the ideal location for a kitchen", "I am also the name of a powerful fire-based weapon", "My name literally means ''relating to Agni''"]','["मैं हिंदू ज्योतिष में दक्षिण-पूर्व दिशा हूँ", "मेरे अधिपति अग्नि देव हैं", "वास्तु में मुझे रसोई के लिए सबसे उत्तम स्थान माना जाता है", "मैं अग्नि से संबंधित एक शक्तिशाली अस्त्र भी हूँ", "मेरे नाम का अर्थ है ''अग्नि से उत्पन्न'' या उनसे संबंधित"]');
INSERT INTO clue_riddles VALUES(336,'SHLOKA','["I am the basic verse form of Sanskrit poetry", "I usually contain thirty-two syllables in two lines", "The first of me was born from a sage''s sorrow at a bird''s death", "The Ramayana and Mahabharata are composed entirely in my form", "I am the sacred verse meter of Hindu scripture"]','["मैं संस्कृत काव्य का मूल छंद रूप हूँ", "मुझमें सामान्यतः दो पंक्तियों में बत्तीस अक्षर होते हैं", "मेरा पहला रूप एक ऋषि के एक पक्षी की मृत्यु पर शोक से जन्मा", "रामायण और महाभारत पूर्णतः मेरे रूप में रचित हैं", "मैं हिंदू शास्त्र का पवित्र श्लोक छंद हूँ"]');
INSERT INTO clue_riddles VALUES(337,'RIGVEDA','["I am the oldest sacred text known to humanity", "I contain over a thousand hymns praising cosmic forces", "I was transmitted orally for thousands of years before being written", "My famous Nasadiya Sukta questions the origin of creation itself", "I am the first and oldest of the four Vedas"]','["मैं मानवता को ज्ञात सबसे प्राचीन पवित्र ग्रंथ हूँ", "मुझमें ब्रह्मांडीय शक्तियों की स्तुति में एक हज़ार से अधिक सूक्त हैं", "लिखे जाने से पहले मुझे हज़ारों वर्षों तक मौखिक रूप से प्रसारित किया गया", "मेरा प्रसिद्ध नासदीय सूक्त सृष्टि की उत्पत्ति पर प्रश्न करता है", "मैं चारों वेदों में सबसे पहला और प्राचीन हूँ"]');
INSERT INTO clue_riddles VALUES(338,'SURASA','["I was sent by the Devas to test Hanuman during his leap to Lanka", "My encounter proved wit is greater than force", "I am known as the Mother of Nagas (Serpents)", "I expanded my mouth to a massive size to swallow the Son of Vayu", "Hanuman outsmarted me by becoming tiny and quickly exiting my mouth"]','["देवताओं ने मुझे लंका जाते समय हनुमान की परीक्षा लेने के लिए भेजा था", "मेरे साथ हुई भेंट ने सिद्ध किया कि बुद्धि बल से श्रेष्ठ है", "मैं नागों की माता (नागमाता) के रूप में जानी जाती हूँ", "मैंने पवनपुत्र को निगलने के लिए अपना मुख कई योजन तक फैला लिया था", "हनुमान ने सूक्ष्म रूप धारण कर चतुराई से मेरे मुख से बाहर निकलकर मुझे मात दी"]');
INSERT INTO clue_riddles VALUES(339,'SAMSKARA','["We are sacred ceremonies marking every stage of life", "We begin before birth and continue even after death", "There are sixteen of us in the traditional Hindu lifecycle", "We include naming, first feeding, initiation, marriage, and last rites", "We are the Hindu sacraments that sanctify life''s journey"]','["हम जीवन के हर चरण को चिह्नित करने वाले पवित्र संस्कार हैं", "हम जन्म से पहले शुरू होते हैं और मृत्यु के बाद भी जारी रहते हैं", "पारंपरिक हिंदू जीवनचक्र में हमारी संख्या सोलह है", "हमारे में नामकरण, अन्नप्राशन, उपनयन, विवाह और अंत्येष्टि शामिल हैं", "हम हिंदू संस्कार हैं जो जीवन यात्रा को पवित्र करते हैं"]');
INSERT INTO clue_riddles VALUES(340,'ARTHA','["I am one of the four goals of human life in Hindu philosophy", "I represent wealth, prosperity, and material success", "I must be pursued along with dharma for balance", "I support the responsibilities of family and society", "I stand alongside Dharma, Kama, and Moksha"]','["मैं हिंदू दर्शन में जीवन के चार पुरुषार्थों में से एक हूँ", "मैं धन, समृद्धि और भौतिक सफलता का प्रतीक हूँ", "मुझे धर्म के साथ संतुलन में प्राप्त करना चाहिए", "मैं परिवार और समाज की जिम्मेदारियों को निभाने में सहायक हूँ", "मैं धर्म, काम और मोक्ष के साथ जुड़ा हूँ"]');
INSERT INTO clue_riddles VALUES(341,'MANTRA','["I am a sacred utterance believed to have spiritual power", "Repeating me purifies the mind and invokes divine energy", "I can be a single syllable or an entire verse", "Om is the most fundamental of all of me", "I am the sacred chant of Hindu worship and meditation"]','["मैं एक पवित्र उच्चारण हूँ जिसमें आध्यात्मिक शक्ति मानी जाती है", "मेरा जाप मन को शुद्ध करता और दिव्य ऊर्जा का आह्वान करता है", "मैं एक अक्षर से लेकर पूरे श्लोक तक हो सकता हूँ", "ओम मेरे सभी रूपों में सबसे मूलभूत है", "मैं हिंदू पूजा और ध्यान का पवित्र जाप हूँ"]');
INSERT INTO clue_riddles VALUES(342,'AVATAR','["I descend to earth whenever evil threatens to overwhelm good", "I take a form suited to the crisis of each age", "Ten of me are the most celebrated in Hindu tradition", "I range from fish and tortoise to princes and warriors", "I am the divine incarnation of Vishnu on earth"]','["जब भी बुराई अच्छाई पर हावी होने लगती है मैं पृथ्वी पर उतरता हूँ", "मैं हर युग के संकट के अनुरूप रूप धारण करता हूँ", "मेरे दस रूप हिंदू परंपरा में सबसे प्रसिद्ध हैं", "मैं मछली और कछुए से लेकर राजकुमार और योद्धा तक हूँ", "मैं पृथ्वी पर विष्णु का दिव्य अवतरण हूँ"]');
INSERT INTO clue_riddles VALUES(343,'DUSHALA','["I am the only sister among 101 siblings", "Arjuna spared my grandson''s kingdom during the Ashvamedha", "I was married to Jayadratha, the King of Sindhu", "I am the sister of the hundred Kaurava brothers", "I am the only daughter of Dhritarashtra and Gandhari"]','["मैं 101 भाई-बहनों में अकेली बहन हूँ", "अर्जुन ने अश्वमेध के दौरान मेरे पौत्र को जीवनदान दिया था", "मेरा विवाह सिंधु के राजा जयद्रथ से हुआ था", "मैं सौ कौरव भाइयों की एकमात्र बहन हूँ", "मैं धृतराष्ट्र और गांधारी की इकलौती पुत्री हूँ"]');
INSERT INTO clue_riddles VALUES(344,'AARTI','["I am performed by waving a flame in circular motions before the deity", "A camphor or ghee lamp is used during me", "I mark the climax of every worship ceremony", "Devotees cup their hands over my flame and touch their eyes", "I am the sacred lamp ceremony performed in Hindu worship"]','["मुझे देवता के सामने लौ को गोलाकार गति में घुमाकर किया जाता है", "मेरे दौरान कपूर या घी के दीपक का उपयोग होता है", "मैं हर पूजा अनुष्ठान का चरम बिंदु हूँ", "भक्त मेरी लौ पर हाथ रखकर अपनी आँखों को छूते हैं", "मैं हिंदू पूजा में किया जाने वाला पवित्र आरती अनुष्ठान हूँ"]');
INSERT INTO clue_riddles VALUES(345,'BRAHMANDA','["I represent the cosmic egg from which the universe emerged", "I contain all worlds, beings, and creation within me", "My concept is described in Puranic cosmology", "I symbolize the origin and totality of existence", "My name combines ‘Brahma’ and ‘anda’ meaning cosmic egg"]','["मैं वह ब्रह्मांडीय अंडा हूँ जिससे सृष्टि की उत्पत्ति हुई", "मैं अपने भीतर सभी लोकों, प्राणियों और सृष्टि को समाहित करता हूँ", "मेरा वर्णन पुराणों की सृष्टि रचना में मिलता है", "मैं अस्तित्व की उत्पत्ति और संपूर्णता का प्रतीक हूँ", "मेरा नाम ‘ब्रह्म’ और ‘अंड’ से मिलकर बना है"]');
INSERT INTO clue_riddles VALUES(346,'BUDDHA','["I left my palace after seeing old age, sickness, and death", "I sat under a tree until I found the ultimate truth", "I taught the middle path between luxury and austerity", "I am considered the ninth avatar by some Hindu traditions", "I am the enlightened teacher born as Prince Siddhartha"]','["बुढ़ापा, बीमारी और मृत्यु देखने के बाद मैंने अपना महल छोड़ा", "मैं एक वृक्ष के नीचे तब तक बैठा जब तक परम सत्य नहीं मिला", "मैंने विलासिता और तपस्या के बीच मध्यम मार्ग सिखाया", "कुछ हिंदू परंपराओं में मुझे नौवाँ अवतार माना जाता है", "मैं राजकुमार सिद्धार्थ के रूप में जन्मा प्रबुद्ध शिक्षक हूँ"]');
INSERT INTO clue_riddles VALUES(347,'RUDRA','["I am a fierce and ancient deity associated with storms and wild nature", "My presence is both destructive and healing in early sacred texts", "I am invoked in Vedic hymns for protection and relief from suffering", "I am considered an early form of a later major Hindu deity", "I am the Vedic precursor to Lord Shiva"]','["मैं एक प्राचीन और उग्र देवता हूँ जो तूफान और प्रकृति की शक्तियों से जुड़ा है", "मेरी प्रकृति विनाशकारी होने के साथ-साथ उपचार करने वाली भी है", "मुझे वेदों में रक्षा और कष्ट दूर करने के लिए पुकारा जाता है", "मुझे बाद के एक प्रमुख देवता का प्रारंभिक रूप माना जाता है", "मैं भगवान शिव का वैदिक रूप हूँ"]');
INSERT INTO clue_riddles VALUES(348,'DHYANA','["I am a deep state of awareness where the mind becomes still and focused inward", "Through me, one transcends distractions and approaches inner clarity", "I am a key step in the path of yoga leading toward higher realization", "Sages practice me to attain peace and spiritual insight", "I simply mean meditation"]','["मैं वह गहन अवस्था हूँ जिसमें मन शांत होकर भीतर की ओर केंद्रित हो जाता है", "मेरे माध्यम से व्यक्ति विचलनों से ऊपर उठकर स्पष्टता प्राप्त करता है", "मैं योग के मार्ग का एक महत्वपूर्ण चरण हूँ जो उच्च अनुभूति की ओर ले जाता है", "ऋषि मुझे शांति और आध्यात्मिक ज्ञान के लिए करते हैं", "मैं आसान भाषा में भीतर की ओर केंद्रित होने की अवस्था हूँ"]');
INSERT INTO clue_riddles VALUES(349,'PRAJAPATI','["I am known as the lord of all creatures", "I am associated with creation in Vedic texts", "Figures like Daksha, Agni, and Indra are counted among me", "I am linked with Brahma, the creator", "My name means ‘master of beings’"]','["मैं समस्त प्राणियों के स्वामी के रूप में जाना जाता हूँ", "मेरा संबंध वेदों में सृष्टि से है", "दक्ष, अग्नि और इंद्र जैसे देव मेरे अंतर्गत माने जाते हैं", "मेरा संबंध सृष्टिकर्ता ब्रह्मा से जोड़ा जाता है", "मेरा अर्थ है ‘प्राणियों का स्वामी’"]');
INSERT INTO clue_riddles VALUES(350,'PANDAVAS','["We are the five sons of King Pandu and Kunti/Madri", "We were born through the blessings of different gods", "We shared a common wife, the princess Draupadi", "We spent thirteen years in exile and one in hiding", "We emerged victorious in the great Kurukshetra war"]','["हम राजा पांडु और कुंती-माद्री के पांच पुत्र हैं", "हमारा जन्म विभिन्न देवताओं के आशीर्वाद से हुआ था", "हमारी एक ही पत्नी थी, जिनका नाम द्रौपदी था", "हमने तेरह वर्ष का वनवास और एक वर्ष अज्ञातवास काटा", "हमने कुरुक्षेत्र के युद्ध में अधर्म पर विजय प्राप्त की"]');
INSERT INTO clue_riddles VALUES(351,'PRASADA','["I am food that has been offered to the deity first", "After being blessed, I am distributed to all devotees", "Refusing me is considered disrespectful", "I can be sweets, fruits, or a full meal", "I am the sacred blessed food from Hindu worship"]','["मैं वह भोजन हूँ जो पहले देवता को अर्पित किया गया है", "आशीर्वादित होने के बाद मुझे सभी भक्तों में बाँटा जाता है", "मुझे अस्वीकार करना अनादर माना जाता है", "मैं मिठाई, फल या पूर्ण भोजन हो सकता हूँ", "मैं हिंदू पूजा से प्राप्त पवित्र प्रसाद हूँ"]');
INSERT INTO clue_riddles VALUES(352,'ATMAN','["I am eternal, unborn, and can never be destroyed", "I merely change bodies like a person changes clothes", "Weapons cannot cut me, fire cannot burn me", "Realizing my true nature leads to ultimate freedom", "I am the individual soul in Hindu philosophy"]','["मैं शाश्वत हूँ, अजन्मा हूँ, और कभी नष्ट नहीं हो सकता", "मैं शरीर बदलता हूँ जैसे व्यक्ति वस्त्र बदलता है", "शस्त्र मुझे काट नहीं सकते, अग्नि मुझे जला नहीं सकती", "मेरे वास्तविक स्वरूप को जानना परम मुक्ति देता है", "मैं हिंदू दर्शन में आत्मा हूँ"]');
INSERT INTO clue_riddles VALUES(353,'RAMBHA','["I am the queen of Apsaras in Indra''s court", "I emerged during the Churning of the Ocean", "I was cursed by Sage Vishwamitra to turn into stone", "I am the wife of Nalakubara, the son of Kubera", "A curse involving me eventually protected Sita from Ravana"]','["मैं इंद्र की सभा में अप्सराओं की रानी हूँ", "मेरा जन्म समुद्र मंथन के दौरान हुआ था", "ऋषि विश्वामित्र ने मुझे पत्थर बनने का श्राप दिया था", "मैं कुबेर के पुत्र नलकुबेर की पत्नी हूँ", "मुझसे जुड़े एक श्राप ने ही आगे चलकर सीता की रावण से रक्षा की"]');
INSERT INTO clue_riddles VALUES(354,'SHIVLING','["I first appeared as an infinite pillar of light to settle a dispute between Brahma and Vishnu", "I represent the inseparable union of the cosmic male and female principles", "I am the aniconic and most sacred representation of Lord Shiva", "I am the primary deity found in the ''Garbhagriha'' of every Shiva temple", "My form consists of three parts, symbolizing the Trimurti (Brahma, Vishnu, and Shiva)"]','["ब्रह्मा और विष्णु के विवाद को सुलझाने के लिए मैं पहली बार अनंत प्रकाश स्तंभ के रूप में प्रकट हुआ था", "मैं शिव और शक्ति के अटूट मिलन और ब्रह्मांडीय ऊर्जा का प्रतीक हूँ", "मैं भगवान शिव का निराकार और सबसे पवित्र स्वरूप हूँ", "मैं हर शिव मंदिर के ''गर्भगृह'' में स्थापित मुख्य विग्रह हूँ", "मेरे स्वरूप के तीन भाग त्रिदेवों—ब्रह्मा, विष्णु और महेश का प्रतिनिधित्व करते हैं"]');
INSERT INTO clue_riddles VALUES(355,'SHANTANU','["I am a king whose life was shaped by love and destiny along a sacred river", "I was a powerful king of the Kuru dynasty and the ruler of Hastinapura", "My first marriage was bound by a mysterious condition I could not question", "I granted my son the boon of ''Ichcha Mrityu''", "I am the father of Bhishma"]','["मैं एक राजा हूँ जिसका जीवन एक पवित्र नदी के किनारे प्रेम और भाग्य से जुड़ा था", "मैं कुरु वंश का एक शक्तिशाली राजा और हस्तिनापुर का शासक था", "मेरा पहला विवाह एक ऐसे वचन से बंधा था जिसे मैं प्रश्न नहीं कर सकता था", "मैंने अपने पुत्र को ''इच्छा मृत्यु'' का वरदान दिया", "मैं भीष्म का पिता हूँ"]');
INSERT INTO clue_riddles VALUES(356,'PADMA','["I symbolize purity as I rise untouched from muddy waters", "I am closely associated with divine beauty and spiritual awakening", "Many deities are depicted seated upon me", "I am a sacred flower often linked with prosperity and enlightenment", "I simply mean a lotus"]','["मैं कीचड़ में उगकर भी निर्मलता का प्रतीक हूँ", "मेरा संबंध दिव्य सौंदर्य और आध्यात्मिक जागृति से है", "कई देवताओं को मुझ पर विराजमान दिखाया जाता है", "मैं एक पवित्र फूल हूँ जो समृद्धि और ज्ञान से जुड़ा है", "मैं सरल रूप में कमल हूँ"]');
INSERT INTO clue_riddles VALUES(357,'KARMA','["I am the universal law of cause and effect", "Every action you take creates me, good or bad", "I determine the circumstances of your next birth", "I cannot be escaped but can be purified through right action", "I am the Hindu principle that every deed has consequences"]','["मैं कारण और प्रभाव का सार्वभौमिक नियम हूँ", "आपका हर कर्म मुझे बनाता है, अच्छा या बुरा", "मैं आपके अगले जन्म की परिस्थितियाँ निर्धारित करता हूँ", "मुझसे बचा नहीं जा सकता पर सत्कर्म से शुद्ध किया जा सकता है", "मैं हिंदू सिद्धांत हूँ कि हर कर्म का फल होता है"]');
INSERT INTO clue_riddles VALUES(358,'SKANDA','["I am a warrior deity born to defeat a powerful demon threatening the cosmos", "My birth is linked to divine energy carried and nurtured in an unusual way", "I am often depicted leading celestial armies into battle", "I am known by many names including Kartikeya and Murugan", "I am the son of Shiva and Parvati"]','["मैं एक योद्धा देवता हूँ जिसका जन्म एक शक्तिशाली असुर के वध के लिए हुआ", "मेरा जन्म दिव्य ऊर्जा से जुड़ा है जिसे विशेष रूप से धारण और पोषित किया गया", "मुझे अक्सर देव सेनाओं का नेतृत्व करते हुए दिखाया जाता है", "मुझे कार्तिकेय और मुरुगन जैसे नामों से भी जाना जाता है", "मैं शिव और पार्वती का पुत्र हूँ"]');
INSERT INTO clue_riddles VALUES(359,'SAMSARA','["I am the endless wheel of birth, death, and rebirth", "Every soul is trapped in me until it achieves liberation", "My cycle is driven by desires and accumulated karma", "Breaking free from me is the ultimate spiritual goal", "I am the cycle of reincarnation in Hindu belief"]','["मैं जन्म, मृत्यु और पुनर्जन्म का अनंत चक्र हूँ", "हर आत्मा मुक्ति प्राप्त करने तक मुझमें फँसी है", "मेरा चक्र इच्छाओं और संचित कर्मों द्वारा चलता है", "मुझसे मुक्ति पाना परम आध्यात्मिक लक्ष्य है", "मैं हिंदू विश्वास में पुनर्जन्म का संसार चक्र हूँ"]');
INSERT INTO clue_riddles VALUES(360,'SADASHIVA','["My five faces represent the five cosmic elements and five directions", "I perform the five sacred functions: creation, preservation, destruction, concealment, and grace", "I am the source from which the five primary Shaktis and Mantras emerge", "I am the highest, eternal form of Lord Shiva in Shaiva Siddhanta", "I am usually depicted with five faces (Panchamukha) and ten arms"]','["मेरे पाँच मुख पाँच तत्वों और पाँच दिशाओं का प्रतिनिधित्व करते हैं", "मैं सृष्टि के पाँच कार्य करता हूँ: सृष्टि, स्थिति, संहार, तिरोभाव और अनुग्रह", "मैं वह स्रोत हूँ जिससे पाँच प्रमुख शक्तियाँ और मंत्र उत्पन्न होते हैं", "मैं शैव सिद्धांत के अनुसार भगवान शिव का सर्वोच्च और शाश्वत स्वरूप हूँ", "मुझे आमतौर पर पाँच मुखों (पंचमुख) और दस भुजाओं के साथ दिखाया जाता है"]');
INSERT INTO clue_riddles VALUES(361,'BRAHMAN','["I am the ultimate reality beyond all form and name", "Everything in the universe is a manifestation of me", "I am both with qualities and without qualities simultaneously", "The Upanishads declare that the individual soul is identical to me", "I am the supreme cosmic spirit of Hindu philosophy"]','["मैं सभी रूपों और नामों से परे परम सत्य हूँ", "ब्रह्मांड में सब कुछ मेरी अभिव्यक्ति है", "मैं एक साथ सगुण और निर्गुण दोनों हूँ", "उपनिषद घोषणा करते हैं कि आत्मा मुझसे अभिन्न है", "मैं हिंदू दर्शन का परम ब्रह्म हूँ"]');
INSERT INTO clue_riddles VALUES(362,'SHIKHANDI','["I am a character in Mahabharata", "I was born a woman and later became a man", "I carried a grudge from my previous life", "I am sibling of Draupadi", "I was born to kill Bhishma"]','["मैं महाभारत का एक पात्र हूँ", "मेरा जन्म स्त्री के रूप में हुआ और बाद में मैं पुरुष बना", "मेरे पिछले जन्म की शत्रुता मेरे साथ थी", "मैं द्रौपदी का भाई हूँ", "मैं भीष्म को मारने के लिए जन्मा था"]');
INSERT INTO clue_riddles VALUES(363,'YOGA','["My name means union of the individual with the divine", "I have eight limbs from ethical rules to ultimate absorption", "I include physical postures but I am much more than exercise", "The Bhagavad Gita describes multiple paths of me", "I am the ancient Indian discipline of mind and body union"]','["मेरे नाम का अर्थ है आत्मा और परमात्मा का मिलन", "मेरे आठ अंग हैं नैतिक नियमों से लेकर परम समाधि तक", "मुझमें शारीरिक आसन शामिल हैं पर मैं व्यायाम से कहीं अधिक हूँ", "भगवद्गीता मेरे अनेक मार्गों का वर्णन करती है", "मैं मन और शरीर के मिलन की प्राचीन भारतीय साधना योग हूँ"]');
INSERT INTO clue_riddles VALUES(364,'OM','["I am the first sound that created the entire universe", "I contain three letters representing creation, preservation, and destruction", "Every sacred chant begins and ends with me", "I am present in every religion though called by different names", "I am the primordial sacred syllable of Hinduism"]','["मैं वह पहली ध्वनि हूँ जिसने पूरे ब्रह्मांड की रचना की", "मुझमें तीन अक्षर हैं जो सृष्टि, पालन और विनाश का प्रतीक हैं", "हर पवित्र मंत्र मुझसे शुरू और मुझ पर समाप्त होता है", "मैं हर धर्म में अलग-अलग नामों से विद्यमान हूँ", "मैं हिंदू धर्म का आदि पवित्र अक्षर ॐ हूँ"]');
INSERT INTO clue_riddles VALUES(365,'GOVINDA','["I danced on the hood of a poisonous serpent as a child", "I lifted an entire mountain on my little finger to protect my people", "I revealed the secret of life and death on a battlefield", "I am dark as the rain cloud yet my smile lights up the universe", "I am the divine cowherd, philosopher king, and eighth avatar of Vishnu"]','["मैंने बचपन में एक विषैले सर्प के फन पर नृत्य किया", "मैंने अपनी छोटी उँगली पर पूरा पर्वत उठाकर अपने लोगों की रक्षा की", "मैंने रणभूमि पर जीवन और मृत्यु का रहस्य प्रकट किया", "मैं वर्षा के मेघ जैसा श्याम हूँ फिर भी मेरी मुस्कान ब्रह्मांड को रोशन करती है", "मैं दिव्य गोपाल, दार्शनिक राजा और विष्णु का आठवाँ अवतार हूँ"]');
INSERT INTO trivia_facts VALUES(1,'The Mahabharata is the longest epic in the world with over 100,000 verses.','महाभारत दुनिया का सबसे लंबा महाकाव्य है, जिसमें 1,00,000 से अधिक श्लोक हैं।');
INSERT INTO trivia_facts VALUES(2,'The Bhagavad Gita is a dialogue between Krishna and Arjuna on the battlefield of Kurukshetra.','भगवद गीता कुरुक्षेत्र के युद्धभूमि में कृष्ण और अर्जुन के बीच संवाद है।');
INSERT INTO trivia_facts VALUES(3,'The Vedas are among the oldest scriptures in the world.','वेद दुनिया के सबसे प्राचीन ग्रंथों में से हैं।');
INSERT INTO trivia_facts VALUES(4,'There are four Vedas: Rigveda, Samaveda, Yajurveda, and Atharvaveda.','चार वेद हैं: ऋग्वेद, सामवेद, यजुर्वेद और अथर्ववेद।');
INSERT INTO trivia_facts VALUES(5,'Zero was developed in ancient India and linked to Hindu mathematical thought.','शून्य का विकास प्राचीन भारत में हुआ और यह हिंदू गणितीय विचार से जुड़ा है।');
INSERT INTO trivia_facts VALUES(6,'The Ramayana was composed by Sage Valmiki in Sanskrit.','रामायण की रचना महर्षि वाल्मीकि ने संस्कृत में की थी।');
INSERT INTO trivia_facts VALUES(7,'The Upanishads explore deep philosophical concepts about the soul and universe.','उपनिषद आत्मा और ब्रह्मांड के गहरे दार्शनिक विचारों का वर्णन करते हैं।');
INSERT INTO trivia_facts VALUES(8,'The Gayatri Mantra is one of the most sacred mantras in Hinduism.','गायत्री मंत्र हिंदू धर्म के सबसे पवित्र मंत्रों में से एक है।');
INSERT INTO trivia_facts VALUES(9,'Lord Vishnu is known as the preserver in the Hindu trinity.','भगवान विष्णु को हिंदू त्रिमूर्ति में पालनकर्ता माना जाता है।');
INSERT INTO trivia_facts VALUES(10,'Lord Shiva is called Mahadev, meaning the greatest god.','भगवान शिव को महादेव कहा जाता है, जिसका अर्थ है महान देव।');
INSERT INTO trivia_facts VALUES(11,'The Puranas contain stories about gods, creation, and cosmic cycles.','पुराणों में देवताओं, सृष्टि और ब्रह्मांडीय चक्रों की कथाएं हैं।');
INSERT INTO trivia_facts VALUES(12,'The concept of karma means every action has consequences.','कर्म का सिद्धांत बताता है कि हर कर्म का फल होता है।');
INSERT INTO trivia_facts VALUES(13,'The Mahabharata includes the Bhagavad Gita as one of its sections.','महाभारत में भगवद गीता एक भाग के रूप में शामिल है।');
INSERT INTO trivia_facts VALUES(14,'Hanuman is known for his unwavering devotion to Lord Rama.','हनुमान भगवान राम के प्रति अपनी अटूट भक्ति के लिए जाने जाते हैं।');
INSERT INTO trivia_facts VALUES(15,'The Rigveda is the oldest of the four Vedas.','ऋग्वेद चारों वेदों में सबसे प्राचीन है।');
INSERT INTO trivia_facts VALUES(16,'The concept of dharma refers to duty and righteousness.','धर्म का अर्थ कर्तव्य और धर्मपरायणता से है।');
INSERT INTO trivia_facts VALUES(17,'The lotus symbolizes purity and spiritual awakening.','कमल पवित्रता और आध्यात्मिक जागरण का प्रतीक है।');
INSERT INTO trivia_facts VALUES(18,'The Saraswati River is mentioned extensively in the Vedas.','सरस्वती नदी का उल्लेख वेदों में व्यापक रूप से मिलता है।');
INSERT INTO trivia_facts VALUES(19,'The Trimurti consists of Brahma, Vishnu, and Shiva.','त्रिमूर्ति में ब्रह्मा, विष्णु और शिव शामिल हैं।');
INSERT INTO trivia_facts VALUES(20,'The Atharvaveda includes hymns related to daily life and healing.','अथर्ववेद में दैनिक जीवन और उपचार से संबंधित मंत्र हैं।');
INSERT INTO trivia_facts VALUES(21,'The Mahabharata was composed by Sage Vyasa.','महाभारत की रचना महर्षि व्यास ने की थी।');
INSERT INTO trivia_facts VALUES(22,'Ganesha wrote the Mahabharata as Vyasa dictated it.','महाभारत को व्यास जी के कथन पर भगवान गणेश ने लिखा था।');
INSERT INTO trivia_facts VALUES(23,'The Kurukshetra war lasted for 18 days.','कुरुक्षेत्र का युद्ध 18 दिनों तक चला था।');
INSERT INTO trivia_facts VALUES(24,'The Mahabharata is divided into 18 parvas or books.','महाभारत 18 पर्वों में विभाजित है।');
INSERT INTO trivia_facts VALUES(25,'There were 18 akshauhinis of armies in the Kurukshetra war.','कुरुक्षेत्र युद्ध में 18 अक्षौहिणी सेनाएं थीं।');
INSERT INTO trivia_facts VALUES(26,'Bhishma had the boon of choosing the time of his death.','भीष्म को अपनी मृत्यु का समय स्वयं चुनने का वरदान प्राप्त था।');
INSERT INTO trivia_facts VALUES(27,'Draupadi was born from a sacred fire ritual.','द्रौपदी का जन्म यज्ञ की अग्नि से हुआ था।');
INSERT INTO trivia_facts VALUES(28,'Karna was born with divine armor and earrings.','कर्ण का जन्म दिव्य कवच और कुंडलों के साथ हुआ था।');
INSERT INTO trivia_facts VALUES(29,'Arjuna won Draupadi in a swayamvara by hitting a rotating target.','अर्जुन ने द्रौपदी को स्वयंवर में घूमते लक्ष्य को भेदकर जीता था।');
INSERT INTO trivia_facts VALUES(30,'Krishna served as Arjuna’s charioteer in the war.','युद्ध में कृष्ण अर्जुन के सारथी बने थे।');
INSERT INTO trivia_facts VALUES(31,'The Pandavas spent 13 years in exile including one year in disguise.','पांडवों ने 13 वर्ष वनवास में बिताए, जिसमें एक वर्ष अज्ञातवास था।');
INSERT INTO trivia_facts VALUES(32,'Yudhishthira was known for his unwavering commitment to truth.','युधिष्ठिर सत्य के प्रति अपनी अटल निष्ठा के लिए जाने जाते थे।');
INSERT INTO trivia_facts VALUES(33,'Bhima possessed immense physical strength among the Pandavas.','भीम पांडवों में अत्यधिक शारीरिक शक्ति के लिए प्रसिद्ध थे।');
INSERT INTO trivia_facts VALUES(34,'Arjuna received the divine bow Gandiva from the gods.','अर्जुन को देवताओं से दिव्य धनुष गांडीव प्राप्त हुआ था।');
INSERT INTO trivia_facts VALUES(35,'Duryodhana was the eldest of the Kauravas.','दुर्योधन कौरवों में सबसे बड़ा था।');
INSERT INTO trivia_facts VALUES(36,'Shakuni was known for his cunning strategies and dice skills.','शकुनि अपनी चतुर चालों और पासों के खेल के लिए प्रसिद्ध था।');
INSERT INTO trivia_facts VALUES(37,'Abhimanyu knew how to enter the Chakravyuha but not exit it.','अभिमन्यु को चक्रव्यूह में प्रवेश करना आता था, लेकिन बाहर निकलना नहीं।');
INSERT INTO trivia_facts VALUES(38,'Bhishma led the Kaurava army for the first 10 days of the war.','भीष्म ने युद्ध के पहले 10 दिनों तक कौरव सेना का नेतृत्व किया।');
INSERT INTO trivia_facts VALUES(39,'Drona was the royal teacher of both Pandavas and Kauravas.','द्रोणाचार्य पांडवों और कौरवों दोनों के गुरु थे।');
INSERT INTO trivia_facts VALUES(40,'The Mahabharata ends with the Pandavas’ journey to the Himalayas.','महाभारत का अंत पांडवों की हिमालय यात्रा के साथ होता है।');
INSERT INTO trivia_facts VALUES(41,'Shantanu was the king of Hastinapura and father of Bhishma.','शांतनु हस्तिनापुर के राजा और भीष्म के पिता थे।');
INSERT INTO trivia_facts VALUES(42,'Bhishma took a vow of lifelong celibacy to fulfill his father''s wish.','भीष्म ने अपने पिता की इच्छा पूर्ण करने के लिए आजीवन ब्रह्मचर्य का व्रत लिया।');
INSERT INTO trivia_facts VALUES(43,'Ganga was the mother of Bhishma.','गंगा भीष्म की माता थीं।');
INSERT INTO trivia_facts VALUES(44,'Kunti received a boon to invoke gods and had sons from different deities.','कुंती को देवताओं को आह्वान करने का वरदान मिला था और उन्होंने विभिन्न देवताओं से पुत्र प्राप्त किए।');
INSERT INTO trivia_facts VALUES(45,'Madri was the mother of Nakula and Sahadeva.','माद्री नकुल और सहदेव की माता थीं।');
INSERT INTO trivia_facts VALUES(46,'Vidura was known for his wisdom and righteousness.','विदुर अपनी बुद्धिमत्ता और धर्मपरायणता के लिए प्रसिद्ध थे।');
INSERT INTO trivia_facts VALUES(47,'Dhritarashtra was born blind and ruled Hastinapura.','धृतराष्ट्र जन्म से अंधे थे और हस्तिनापुर पर शासन करते थे।');
INSERT INTO trivia_facts VALUES(48,'Pandu renounced the throne due to a curse.','पांडु ने शाप के कारण राजगद्दी त्याग दी थी।');
INSERT INTO trivia_facts VALUES(49,'Gandhari blindfolded herself to share her husband''s blindness.','गांधारी ने अपने पति की अंधता को साझा करने के लिए स्वयं पट्टी बांध ली थी।');
INSERT INTO trivia_facts VALUES(50,'Draupadi became the common wife of the five Pandavas.','द्रौपदी पांचों पांडवों की पत्नी बनीं।');
INSERT INTO trivia_facts VALUES(51,'Krishna played a key role as a guide and strategist for the Pandavas.','कृष्ण ने पांडवों के मार्गदर्शक और रणनीतिकार के रूप में महत्वपूर्ण भूमिका निभाई।');
INSERT INTO trivia_facts VALUES(52,'The dice game led to the exile of the Pandavas.','जुए के खेल ने पांडवों के वनवास का कारण बना।');
INSERT INTO trivia_facts VALUES(53,'Dushasana tried to disrobe Draupadi in the Kaurava court.','दुशासन ने कौरव सभा में द्रौपदी का चीरहरण करने का प्रयास किया।');
INSERT INTO trivia_facts VALUES(54,'Krishna protected Draupadi by making her saree endless.','कृष्ण ने द्रौपदी की रक्षा करते हुए उसकी साड़ी को अनंत बना दिया।');
INSERT INTO trivia_facts VALUES(55,'Ekalavya gave his thumb as guru dakshina to Drona.','एकलव्य ने द्रोणाचार्य को गुरु दक्षिणा में अपना अंगूठा दे दिया।');
INSERT INTO trivia_facts VALUES(56,'Karna was the son of Kunti and the Sun god Surya.','कर्ण कुंती और सूर्य देव के पुत्र थे।');
INSERT INTO trivia_facts VALUES(57,'Krishna offered a choice between his army and himself unarmed.','कृष्ण ने अपने और अपनी सेना के बीच चयन का विकल्प दिया।');
INSERT INTO trivia_facts VALUES(58,'Arjuna chose Krishna over his vast army.','अर्जुन ने विशाल सेना के बजाय कृष्ण को चुना।');
INSERT INTO trivia_facts VALUES(59,'Balarama remained neutral during the Kurukshetra war.','बलराम कुरुक्षेत्र युद्ध में तटस्थ रहे।');
INSERT INTO trivia_facts VALUES(60,'Shikhandi was instrumental in Bhishma''s fall.','शिखंडी भीष्म के पतन में महत्वपूर्ण रहे।');
INSERT INTO trivia_facts VALUES(61,'Jayadratha was killed by Arjuna before sunset on the 14th day.','जयद्रथ को अर्जुन ने 14वें दिन सूर्यास्त से पहले मार दिया था।');
INSERT INTO trivia_facts VALUES(62,'Ghatotkacha was the son of Bhima and a Rakshasa princess.','घटोत्कच भीम और एक राक्षसी राजकुमारी के पुत्र थे।');
INSERT INTO trivia_facts VALUES(63,'Karna used his divine weapon Shakti only once in the war.','कर्ण ने अपने दिव्य अस्त्र शक्ति का प्रयोग केवल एक बार किया।');
INSERT INTO trivia_facts VALUES(64,'Ashwatthama was the son of Drona and a powerful warrior.','अश्वत्थामा द्रोणाचार्य के पुत्र और एक शक्तिशाली योद्धा थे।');
INSERT INTO trivia_facts VALUES(65,'Drona was defeated after hearing the news of Ashwatthama''s death.','अश्वत्थामा की मृत्यु का समाचार सुनकर द्रोणाचार्य पराजित हुए।');
INSERT INTO trivia_facts VALUES(66,'Bhima fulfilled his vow by killing Dushasana.','भीम ने दुशासन का वध कर अपनी प्रतिज्ञा पूरी की।');
INSERT INTO trivia_facts VALUES(67,'Bhima defeated Duryodhana in a mace battle by striking his thigh.','भीम ने गदा युद्ध में दुर्योधन की जांघ पर प्रहार कर उसे पराजित किया।');
INSERT INTO trivia_facts VALUES(68,'Krishna revealed his Vishwaroopa to Arjuna in the Bhagavad Gita.','कृष्ण ने भगवद गीता में अर्जुन को अपना विश्वरूप दिखाया।');
INSERT INTO trivia_facts VALUES(69,'The Kurukshetra war ended with the victory of the Pandavas.','कुरुक्षेत्र युद्ध का अंत पांडवों की विजय के साथ हुआ।');
INSERT INTO trivia_facts VALUES(70,'Yudhishthira became the king of Hastinapura after the war.','युद्ध के बाद युधिष्ठिर हस्तिनापुर के राजा बने।');
INSERT INTO trivia_facts VALUES(71,'The Ramayana was composed by Sage Valmiki.','रामायण की रचना महर्षि वाल्मीकि ने की थी।');
INSERT INTO trivia_facts VALUES(72,'Lord Rama was born in Ayodhya as the son of King Dasharatha.','भगवान राम का जन्म अयोध्या में राजा दशरथ के पुत्र के रूप में हुआ था।');
INSERT INTO trivia_facts VALUES(73,'Rama is considered the seventh avatar of Vishnu.','राम को विष्णु का सातवां अवतार माना जाता है।');
INSERT INTO trivia_facts VALUES(74,'Sita was found by King Janaka in a furrow in the field.','सीता को राजा जनक ने खेत की मिट्टी से पाया था।');
INSERT INTO trivia_facts VALUES(75,'Rama broke Shiva’s bow to win Sita’s hand in marriage.','राम ने सीता से विवाह के लिए शिव धनुष को तोड़ा था।');
INSERT INTO trivia_facts VALUES(76,'Rama was exiled to the forest for 14 years.','राम को 14 वर्षों के लिए वनवास दिया गया था।');
INSERT INTO trivia_facts VALUES(77,'Lakshmana accompanied Rama during his exile.','लक्ष्मण वनवास के दौरान राम के साथ गए थे।');
INSERT INTO trivia_facts VALUES(78,'Bharata refused to take the throne and ruled as Rama’s representative.','भरत ने सिंहासन स्वीकार नहीं किया और राम के प्रतिनिधि के रूप में शासन किया।');
INSERT INTO trivia_facts VALUES(79,'Shurpanakha’s insult led to the conflict with Ravana.','शूर्पणखा के अपमान से रावण के साथ संघर्ष शुरू हुआ।');
INSERT INTO trivia_facts VALUES(80,'Ravana abducted Sita and took her to Lanka.','रावण ने सीता का हरण कर उन्हें लंका ले गया।');
INSERT INTO trivia_facts VALUES(81,'Jatayu tried to stop Ravana and sacrificed his life.','जटायु ने रावण को रोकने का प्रयास किया और अपने प्राण न्योछावर कर दिए।');
INSERT INTO trivia_facts VALUES(82,'Hanuman met Rama in Kishkindha and became his devotee.','हनुमान की मुलाकात राम से किष्किंधा में हुई और वे उनके भक्त बने।');
INSERT INTO trivia_facts VALUES(83,'Sugriva helped Rama in the search for Sita.','सुग्रीव ने सीता की खोज में राम की सहायता की।');
INSERT INTO trivia_facts VALUES(84,'Hanuman leapt across the ocean to reach Lanka.','हनुमान ने समुद्र पार कर लंका पहुंचने के लिए छलांग लगाई।');
INSERT INTO trivia_facts VALUES(85,'Hanuman found Sita in Ashoka Vatika in Lanka.','हनुमान ने लंका के अशोक वाटिका में सीता को खोजा।');
INSERT INTO trivia_facts VALUES(86,'Hanuman burned Lanka with his fiery tail.','हनुमान ने अपनी जलती हुई पूंछ से लंका को जला दिया।');
INSERT INTO trivia_facts VALUES(87,'The bridge to Lanka was built by the Vanara army.','लंका तक पहुंचने के लिए वानर सेना ने सेतु का निर्माण किया।');
INSERT INTO trivia_facts VALUES(88,'Vibhishana, Ravana’s brother, joined Rama’s side.','रावण के भाई विभीषण राम की ओर शामिल हो गए।');
INSERT INTO trivia_facts VALUES(89,'Indrajit was a powerful warrior and son of Ravana.','इंद्रजीत रावण का शक्तिशाली पुत्र था।');
INSERT INTO trivia_facts VALUES(90,'Lakshmana was severely injured by Indrajit’s weapon.','लक्ष्मण इंद्रजीत के अस्त्र से गंभीर रूप से घायल हुए थे।');
INSERT INTO trivia_facts VALUES(91,'Hanuman brought the Sanjeevani herb to save Lakshmana.','हनुमान संजीवनी बूटी लाकर लक्ष्मण को बचाया।');
INSERT INTO trivia_facts VALUES(92,'Rama killed Ravana in the battle of Lanka.','राम ने लंका के युद्ध में रावण का वध किया।');
INSERT INTO trivia_facts VALUES(93,'Sita underwent Agni Pariksha to prove her purity.','सीता ने अपनी पवित्रता सिद्ध करने के लिए अग्नि परीक्षा दी।');
INSERT INTO trivia_facts VALUES(94,'Rama returned to Ayodhya after completing his exile.','राम वनवास पूरा कर अयोध्या लौटे।');
INSERT INTO trivia_facts VALUES(95,'The return of Rama to Ayodhya is celebrated as Diwali.','राम के अयोध्या लौटने का उत्सव दीपावली के रूप में मनाया जाता है।');
INSERT INTO trivia_facts VALUES(96,'Rama’s rule is known as Ram Rajya, symbolizing ideal governance.','राम का शासन रामराज्य के रूप में जाना जाता है, जो आदर्श शासन का प्रतीक है।');
INSERT INTO trivia_facts VALUES(97,'Lava and Kusha were the sons of Rama and Sita.','लव और कुश राम और सीता के पुत्र थे।');
INSERT INTO trivia_facts VALUES(98,'Valmiki sheltered Sita during her exile in his ashram.','वाल्मीकि ने अपने आश्रम में सीता को आश्रय दिया।');
INSERT INTO trivia_facts VALUES(99,'Lava and Kusha recited the Ramayana in Rama’s court.','लव और कुश ने राम के दरबार में रामायण का पाठ किया।');
INSERT INTO trivia_facts VALUES(100,'Sita returned to the Earth, her mother, at the end of the Ramayana.','रामायण के अंत में सीता अपनी माता पृथ्वी में समा गईं।');
INSERT INTO trivia_facts VALUES(101,'Time in Hinduism is cyclical, repeating through Yugas over billions of years.','हिंदू धर्म में समय चक्रीय है, जो युगों के माध्यम से अरबों वर्षों तक दोहराया जाता है।');
INSERT INTO trivia_facts VALUES(102,'A day of Brahma is equal to 4.32 billion human years.','ब्रह्मा का एक दिन 4.32 अरब मानव वर्षों के बराबर माना जाता है।');
INSERT INTO trivia_facts VALUES(103,'The universe undergoes endless cycles of creation, preservation, and destruction.','ब्रह्मांड सृजन, पालन और संहार के अनंत चक्रों से गुजरता है।');
INSERT INTO trivia_facts VALUES(104,'There are 108 beads in a traditional japa mala.','पारंपरिक जप माला में 108 मनके होते हैं।');
INSERT INTO trivia_facts VALUES(105,'The sound Om is considered the primordial vibration of the universe.','ॐ को ब्रह्मांड की आदिम ध्वनि माना जाता है।');
INSERT INTO trivia_facts VALUES(106,'There are 14 worlds described in Hindu cosmology.','हिंदू ब्रह्मांड विज्ञान में 14 लोकों का वर्णन है।');
INSERT INTO trivia_facts VALUES(107,'The concept of rebirth is central to Hindu philosophy.','पुनर्जन्म की अवधारणा हिंदू दर्शन का एक मुख्य भाग है।');
INSERT INTO trivia_facts VALUES(108,'Moksha is the liberation from the cycle of birth and death.','मोक्ष जन्म और मृत्यु के चक्र से मुक्ति है।');
INSERT INTO trivia_facts VALUES(109,'The Trimurti represents creation, preservation, and destruction.','त्रिमूर्ति सृष्टि, पालन और संहार का प्रतिनिधित्व करती है।');
INSERT INTO trivia_facts VALUES(110,'The Ganga is considered a sacred river that purifies sins.','गंगा को पवित्र नदी माना जाता है जो पापों को धो देती है।');
INSERT INTO trivia_facts VALUES(111,'The concept of karma extends across multiple lifetimes.','कर्म का सिद्धांत कई जन्मों तक फैला होता है।');
INSERT INTO trivia_facts VALUES(112,'Yoga originated as a spiritual discipline in ancient India.','योग प्राचीन भारत में एक आध्यात्मिक अनुशासन के रूप में उत्पन्न हुआ।');
INSERT INTO trivia_facts VALUES(113,'There are six major schools of Hindu philosophy known as Shad Darshanas.','हिंदू दर्शन के छह प्रमुख स्कूल हैं जिन्हें षड्दर्शन कहा जाता है।');
INSERT INTO trivia_facts VALUES(114,'The Upanishads teach the identity of Atman and Brahman.','उपनिषद आत्मा और ब्रह्म की एकता का उपदेश देते हैं।');
INSERT INTO trivia_facts VALUES(115,'A Kalpa is a day in the life of Brahma and spans billions of years.','कल्प ब्रह्मा के जीवन का एक दिन है जो अरबों वर्षों तक फैला होता है।');
INSERT INTO trivia_facts VALUES(116,'The concept of dharma varies based on one''s role and stage of life.','धर्म की अवधारणा व्यक्ति की भूमिका और जीवन के चरण के अनुसार बदलती है।');
INSERT INTO trivia_facts VALUES(117,'There are four stages of life: Brahmacharya, Grihastha, Vanaprastha, and Sannyasa.','जीवन के चार आश्रम हैं: ब्रह्मचर्य, गृहस्थ, वानप्रस्थ और संन्यास।');
INSERT INTO trivia_facts VALUES(118,'The sacred syllable Om is often chanted at the beginning of prayers.','ॐ का उच्चारण प्रार्थनाओं की शुरुआत में किया जाता है।');
INSERT INTO trivia_facts VALUES(119,'The Bhagavata Purana describes the childhood stories of Krishna in detail.','भागवत पुराण में कृष्ण के बाल्यकाल की कथाओं का विस्तार से वर्णन है।');
INSERT INTO trivia_facts VALUES(120,'Navagrahas represent the nine celestial influences in Hindu astrology.','नवग्रह हिंदू ज्योतिष में नौ ग्रहों के प्रभाव का प्रतिनिधित्व करते हैं।');
INSERT INTO trivia_facts VALUES(121,'The lotus grows in mud but symbolizes purity and detachment.','कमल कीचड़ में उगता है लेकिन पवित्रता और वैराग्य का प्रतीक है।');
INSERT INTO trivia_facts VALUES(122,'The conch shell is used in rituals and symbolizes auspiciousness.','शंख का उपयोग अनुष्ठानों में होता है और यह शुभता का प्रतीक है।');
INSERT INTO trivia_facts VALUES(123,'The trident of Shiva represents creation, preservation, and destruction.','शिव का त्रिशूल सृष्टि, पालन और संहार का प्रतीक है।');
INSERT INTO trivia_facts VALUES(124,'The cow is revered as a symbol of abundance and life.','गाय को समृद्धि और जीवन के प्रतीक के रूप में पूजनीय माना जाता है।');
INSERT INTO trivia_facts VALUES(125,'Tulsi is considered a sacred plant and is worshipped in many homes.','तुलसी को पवित्र पौधा माना जाता है और कई घरों में इसकी पूजा की जाती है।');
INSERT INTO trivia_facts VALUES(126,'Temple architecture often aligns with cosmic geometry principles.','मंदिर वास्तुकला अक्सर ब्रह्मांडीय ज्यामिति के सिद्धांतों के अनुसार होती है।');
INSERT INTO trivia_facts VALUES(127,'The concept of Maya refers to the illusion of the material world.','माया की अवधारणा भौतिक संसार की भ्रमात्मक प्रकृति को दर्शाती है।');
INSERT INTO trivia_facts VALUES(128,'The third eye of Shiva symbolizes higher consciousness.','शिव की तीसरी आंख उच्च चेतना का प्रतीक है।');
INSERT INTO trivia_facts VALUES(129,'The Sudarshana Chakra is a spinning divine weapon of Vishnu.','सुदर्शन चक्र विष्णु का घूमने वाला दिव्य अस्त्र है।');
INSERT INTO trivia_facts VALUES(130,'The Himalayas are considered the abode of the gods.','हिमालय को देवताओं का निवास स्थान माना जाता है।');
INSERT INTO trivia_facts VALUES(131,'Mantras are believed to carry vibrational power that affects the mind.','मंत्रों को ऐसी ध्वनि शक्ति माना जाता है जो मन पर प्रभाव डालती है।');
INSERT INTO trivia_facts VALUES(132,'Fire rituals or Yajnas are used to connect with divine forces.','यज्ञों के माध्यम से दिव्य शक्तियों से जुड़ने का प्रयास किया जाता है।');
INSERT INTO trivia_facts VALUES(133,'The peacock is associated with Kartikeya and symbolizes beauty and pride.','मोर कार्तिकेय से जुड़ा है और सौंदर्य व गौरव का प्रतीक है।');
INSERT INTO trivia_facts VALUES(134,'The swan is associated with Saraswati and symbolizes wisdom.','हंस सरस्वती से जुड़ा है और ज्ञान का प्रतीक है।');
INSERT INTO trivia_facts VALUES(135,'The mouse is the vehicle of Ganesha, symbolizing control over desires.','चूहा गणेश का वाहन है, जो इच्छाओं पर नियंत्रण का प्रतीक है।');
INSERT INTO trivia_facts VALUES(136,'The tiger is associated with Durga and represents power.','बाघ दुर्गा से जुड़ा है और शक्ति का प्रतीक है।');
INSERT INTO trivia_facts VALUES(137,'Sacred ash or Vibhuti symbolizes the transient nature of life.','भस्म जीवन की नश्वरता का प्रतीक है।');
INSERT INTO trivia_facts VALUES(138,'The banyan tree symbolizes immortality and longevity.','बरगद का पेड़ अमरता और दीर्घायु का प्रतीक है।');
INSERT INTO trivia_facts VALUES(139,'The bell in temples is rung to focus the mind during worship.','मंदिरों में घंटी मन को एकाग्र करने के लिए बजाई जाती है।');
INSERT INTO trivia_facts VALUES(140,'The tilak on the forehead represents spiritual awareness.','माथे पर तिलक आध्यात्मिक जागरूकता का प्रतीक है।');
INSERT INTO trivia_facts VALUES(141,'The concept of Ananta means the universe is infinite and without end.','अनंत की अवधारणा बताती है कि ब्रह्मांड अनंत और बिना अंत के है।');
INSERT INTO trivia_facts VALUES(142,'Nataraja, the dancing form of Shiva, represents the cosmic cycle of creation and destruction.','नटराज रूप में शिव सृष्टि और संहार के ब्रह्मांडीय चक्र का प्रतीक हैं।');
INSERT INTO trivia_facts VALUES(143,'The Sri Yantra is a sacred geometric diagram representing the universe.','श्री यंत्र एक पवित्र ज्यामितीय आकृति है जो ब्रह्मांड का प्रतीक है।');
INSERT INTO trivia_facts VALUES(144,'There are 33 Koti devas mentioned in scriptures, often interpreted as types of divine energies.','शास्त्रों में 33 कोटि देवताओं का उल्लेख है, जिन्हें दिव्य शक्तियों के रूप में समझा जाता है।');
INSERT INTO trivia_facts VALUES(145,'The concept of Lila describes the universe as a divine play.','लीला की अवधारणा ब्रह्मांड को ईश्वर की दिव्य खेल के रूप में वर्णित करती है।');
INSERT INTO trivia_facts VALUES(146,'The chakra system describes seven main energy centers in the human body.','चक्र प्रणाली मानव शरीर में सात मुख्य ऊर्जा केंद्रों का वर्णन करती है।');
INSERT INTO trivia_facts VALUES(147,'The sound of a conch is believed to purify the environment.','शंख की ध्वनि को वातावरण को शुद्ध करने वाला माना जाता है।');
INSERT INTO trivia_facts VALUES(148,'The concept of Ahimsa promotes non-violence toward all living beings.','अहिंसा की अवधारणा सभी जीवों के प्रति अहिंसक व्यवहार को बढ़ावा देती है।');
INSERT INTO trivia_facts VALUES(149,'The Kalachakra represents the wheel of time in Hindu philosophy.','कालचक्र हिंदू दर्शन में समय के चक्र का प्रतीक है।');
INSERT INTO trivia_facts VALUES(150,'The third eye of Shiva is said to burn ignorance and illusion.','शिव की तीसरी आंख अज्ञान और भ्रम को नष्ट करने वाली मानी जाती है।');
INSERT INTO trivia_facts VALUES(151,'The Rudraksha beads are associated with Shiva and spiritual protection.','रुद्राक्ष शिव से जुड़े हैं और आध्यात्मिक सुरक्षा का प्रतीक हैं।');
INSERT INTO trivia_facts VALUES(152,'The Gita teaches multiple paths to liberation including karma, bhakti, and jnana.','गीता में मोक्ष के लिए कर्म, भक्ति और ज्ञान जैसे विभिन्न मार्ग बताए गए हैं।');
INSERT INTO trivia_facts VALUES(153,'The concept of Sattva, Rajas, and Tamas describes three fundamental qualities of nature.','सत्त्व, रजस और तमस प्रकृति के तीन मूल गुणों का वर्णन करते हैं।');
INSERT INTO trivia_facts VALUES(154,'The Shivalinga represents the formless aspect of Shiva.','शिवलिंग शिव के निराकार रूप का प्रतीक है।');
INSERT INTO trivia_facts VALUES(155,'The festival of Holi celebrates the victory of good over evil through the story of Prahlada.','होली का त्योहार प्रह्लाद की कथा के माध्यम से अच्छाई की बुराई पर विजय का प्रतीक है।');
INSERT INTO trivia_facts VALUES(156,'The concept of Yugas includes Satya, Treta, Dvapara, and Kali Yuga.','युगों की अवधारणा में सत्य, त्रेता, द्वापर और कलियुग शामिल हैं।');
INSERT INTO trivia_facts VALUES(157,'Kali Yuga is considered the current age marked by moral decline.','कलियुग वर्तमान युग है जिसे नैतिक पतन का समय माना जाता है।');
INSERT INTO trivia_facts VALUES(158,'The sacred river Yamuna is associated with Krishna’s childhood stories.','यमुना नदी कृष्ण की बाल लीलाओं से जुड़ी है।');
INSERT INTO trivia_facts VALUES(159,'The Damru of Shiva symbolizes the rhythm of the universe.','शिव का डमरू ब्रह्मांड की लय का प्रतीक है।');
INSERT INTO trivia_facts VALUES(160,'The concept of Artha refers to material prosperity and purpose in life.','अर्थ जीवन में भौतिक समृद्धि और उद्देश्य को दर्शाता है।');
INSERT INTO trivia_facts VALUES(161,'The concept of Kama represents desire and emotional fulfillment.','काम इच्छा और भावनात्मक संतुष्टि का प्रतिनिधित्व करता है।');
INSERT INTO trivia_facts VALUES(162,'The sacred syllable Om is composed of A, U, and M representing creation, preservation, and dissolution.','ॐ तीन ध्वनियों अ, उ और म से मिलकर बना है जो सृष्टि, पालन और संहार का प्रतीक हैं।');
INSERT INTO trivia_facts VALUES(163,'The cow is often called Gau Mata and is revered as a nurturing mother figure.','गाय को गौ माता कहा जाता है और इसे पोषण देने वाली माता के रूप में पूजनीय माना जाता है।');
INSERT INTO trivia_facts VALUES(164,'The concept of Tapasya involves intense meditation and self-discipline.','तपस्या का अर्थ गहन ध्यान और आत्मसंयम है।');
INSERT INTO trivia_facts VALUES(165,'The Saptarishis are seven great sages associated with cosmic knowledge.','सप्तऋषि सात महान ऋषि हैं जो ब्रह्मांडीय ज्ञान से जुड़े हैं।');
INSERT INTO trivia_facts VALUES(166,'The banyan tree is considered immortal as it continuously expands and grows.','बरगद का पेड़ अमर माना जाता है क्योंकि यह निरंतर फैलता और बढ़ता रहता है।');
INSERT INTO trivia_facts VALUES(167,'The concept of Seva emphasizes selfless service.','सेवा का सिद्धांत निस्वार्थ सेवा पर जोर देता है।');
INSERT INTO trivia_facts VALUES(168,'The festival of Navaratri celebrates the nine forms of Goddess Durga.','नवरात्रि में देवी दुर्गा के नौ रूपों की पूजा की जाती है।');
INSERT INTO trivia_facts VALUES(169,'The Shankha, Chakra, Gada, and Padma are symbols associated with Vishnu.','शंख, चक्र, गदा और पद्म विष्णु के प्रमुख प्रतीक हैं।');
INSERT INTO trivia_facts VALUES(170,'The Himalayas are described as the father of Goddess Parvati.','हिमालय को देवी पार्वती के पिता के रूप में वर्णित किया गया है।');
INSERT INTO trivia_facts VALUES(171,'The concept of Prana refers to the life force energy within all beings.','प्राण सभी जीवों में मौजूद जीवन ऊर्जा को कहा जाता है।');
INSERT INTO trivia_facts VALUES(172,'The practice of Surya Namaskar is a sequence of yoga poses honoring the Sun.','सूर्य नमस्कार सूर्य को समर्पित योग आसनों की एक श्रृंखला है।');
INSERT INTO trivia_facts VALUES(173,'The Sudarshana Chakra is said to move at the speed of thought.','सुदर्शन चक्र को मन की गति से चलने वाला माना जाता है।');
INSERT INTO trivia_facts VALUES(174,'The concept of Shakti represents the divine feminine energy.','शक्ति की अवधारणा दिव्य स्त्री ऊर्जा का प्रतिनिधित्व करती है।');
INSERT INTO trivia_facts VALUES(175,'The sacred fire Agni is considered a messenger between humans and gods.','अग्नि को मनुष्यों और देवताओं के बीच संदेशवाहक माना जाता है।');
INSERT INTO trivia_facts VALUES(176,'The moon is associated with the mind and emotions in Hindu philosophy.','चंद्रमा को हिंदू दर्शन में मन और भावनाओं से जोड़ा जाता है।');
INSERT INTO trivia_facts VALUES(177,'The concept of Samsara describes the cycle of birth, death, and rebirth.','संसार जन्म, मृत्यु और पुनर्जन्म के चक्र को दर्शाता है।');
INSERT INTO trivia_facts VALUES(178,'The peepal tree is considered sacred and associated with Lord Vishnu.','पीपल का पेड़ पवित्र माना जाता है और इसे भगवान विष्णु से जोड़ा जाता है।');
INSERT INTO trivia_facts VALUES(179,'The festival of Raksha Bandhan symbolizes the bond between brothers and sisters.','रक्षा बंधन भाई-बहन के पवित्र संबंध का प्रतीक है।');
INSERT INTO trivia_facts VALUES(180,'The concept of Guru is central, representing the remover of darkness.','गुरु की अवधारणा महत्वपूर्ण है, जो अज्ञानता के अंधकार को दूर करने वाला होता है।');
INSERT INTO trivia_facts VALUES(181,'Panchang is a traditional Hindu calendar used to determine auspicious timings.','पंचांग एक पारंपरिक हिंदू कैलेंडर है जिसका उपयोग शुभ समय निर्धारित करने के लिए किया जाता है।');
INSERT INTO trivia_facts VALUES(182,'Panchang is composed of five elements: Tithi, Vara, Nakshatra, Yoga, and Karana.','पंचांग पाँच अंगों से मिलकर बना है: तिथि, वार, नक्षत्र, योग और करण।');
INSERT INTO trivia_facts VALUES(183,'Tithi is based on the angular distance between the Sun and the Moon.','तिथि सूर्य और चंद्रमा के कोणीय अंतर पर आधारित होती है।');
INSERT INTO trivia_facts VALUES(184,'There are 30 Tithis in a lunar month.','एक चंद्र मास में 30 तिथियाँ होती हैं।');
INSERT INTO trivia_facts VALUES(185,'Vara represents the seven days of the week in the Panchang.','वार पंचांग में सप्ताह के सात दिनों को दर्शाता है।');
INSERT INTO trivia_facts VALUES(186,'Nakshatra refers to one of the 27 lunar constellations.','नक्षत्र 27 चंद्र नक्षत्रों में से एक को दर्शाता है।');
INSERT INTO trivia_facts VALUES(187,'Each Nakshatra spans 13 degrees and 20 minutes of the zodiac.','प्रत्येक नक्षत्र 13 डिग्री 20 मिनट के आकाशीय क्षेत्र में फैला होता है।');
INSERT INTO trivia_facts VALUES(188,'Yoga is calculated by adding the longitudes of the Sun and Moon.','योग सूर्य और चंद्रमा की दीर्घाओं को जोड़कर निकाला जाता है।');
INSERT INTO trivia_facts VALUES(189,'There are 27 Yogas in the Panchang system.','पंचांग में 27 योग होते हैं।');
INSERT INTO trivia_facts VALUES(190,'Karana is half of a Tithi and plays a role in Muhurta selection.','करण तिथि का आधा भाग होता है और मुहूर्त चयन में महत्वपूर्ण होता है।');
INSERT INTO trivia_facts VALUES(191,'There are 11 Karanas in total.','कुल 11 करण होते हैं।');
INSERT INTO trivia_facts VALUES(192,'Panchang is used to determine Muhurta for important rituals and ceremonies.','पंचांग का उपयोग महत्वपूर्ण अनुष्ठानों के लिए मुहूर्त निर्धारित करने में किया जाता है।');
INSERT INTO trivia_facts VALUES(193,'Amavasya marks the new moon day in the Panchang.','अमावस्या पंचांग में अमावस्या का दिन होता है जब चंद्रमा दिखाई नहीं देता।');
INSERT INTO trivia_facts VALUES(194,'Purnima marks the full moon day in the Panchang.','पूर्णिमा पंचांग में पूर्ण चंद्रमा का दिन होता है।');
INSERT INTO trivia_facts VALUES(195,'Paksha is divided into Shukla Paksha and Krishna Paksha.','पक्ष को शुक्ल पक्ष और कृष्ण पक्ष में विभाजित किया जाता है।');
INSERT INTO trivia_facts VALUES(196,'Shukla Paksha represents the waxing phase of the Moon.','शुक्ल पक्ष चंद्रमा के बढ़ने की अवस्था को दर्शाता है।');
INSERT INTO trivia_facts VALUES(197,'Krishna Paksha represents the waning phase of the Moon.','कृष्ण पक्ष चंद्रमा के घटने की अवस्था को दर्शाता है।');
INSERT INTO trivia_facts VALUES(198,'A lunar month is called a Maas in the Panchang.','पंचांग में चंद्र मास को ''मास'' कहा जाता है।');
INSERT INTO trivia_facts VALUES(199,'There are 12 lunar months in a Hindu calendar year.','हिंदू पंचांग में एक वर्ष में 12 चंद्र मास होते हैं।');
INSERT INTO trivia_facts VALUES(200,'Adhik Maas is an extra month added to align lunar and solar years.','अधिक मास एक अतिरिक्त महीना होता है जो चंद्र और सौर वर्ष को संतुलित करने के लिए जोड़ा जाता है।');
INSERT INTO trivia_facts VALUES(201,'The Panchang varies slightly based on regional traditions.','पंचांग क्षेत्रीय परंपराओं के अनुसार थोड़ा भिन्न हो सकता है।');
INSERT INTO trivia_facts VALUES(202,'Sunrise time is crucial in determining the day''s Tithi.','सूर्योदय का समय दिन की तिथि निर्धारित करने में महत्वपूर्ण होता है।');
INSERT INTO trivia_facts VALUES(203,'Nakshatra influences naming ceremonies and astrology charts.','नक्षत्र नामकरण संस्कार और ज्योतिष कुंडली को प्रभावित करता है।');
INSERT INTO trivia_facts VALUES(204,'Certain Yogas are considered highly auspicious for rituals.','कुछ योग अनुष्ठानों के लिए अत्यंत शुभ माने जाते हैं।');
INSERT INTO trivia_facts VALUES(205,'Certain Karanas are avoided for important activities.','कुछ करण महत्वपूर्ण कार्यों के लिए टाले जाते हैं।');
INSERT INTO trivia_facts VALUES(206,'Panchang helps determine festival dates like Diwali and Holi.','पंचांग दीपावली और होली जैसे त्योहारों की तिथियाँ निर्धारित करता है।');
INSERT INTO trivia_facts VALUES(207,'Rahu Kalam is considered an inauspicious time period each day.','राहु काल प्रतिदिन का अशुभ समय माना जाता है।');
INSERT INTO trivia_facts VALUES(208,'Yamaganda is another inauspicious period in the Panchang.','यमगंड पंचांग में एक और अशुभ समय होता है।');
INSERT INTO trivia_facts VALUES(209,'Abhijit Muhurta is considered highly auspicious even during difficult days.','अभिजीत मुहूर्त कठिन दिनों में भी अत्यंत शुभ माना जाता है।');
INSERT INTO trivia_facts VALUES(210,'Gulika Kalam is associated with Saturn and has mixed significance.','गुलिक काल शनि से जुड़ा होता है और इसका मिश्रित महत्व होता है।');
INSERT INTO trivia_facts VALUES(211,'Choghadiya is another system used alongside Panchang for Muhurta.','चौघड़िया मुहूर्त के लिए पंचांग के साथ उपयोग की जाने वाली एक अन्य प्रणाली है।');
INSERT INTO trivia_facts VALUES(212,'Solar months are used in some regional Panchang systems.','कुछ क्षेत्रीय पंचांगों में सौर मासों का उपयोग किया जाता है।');
INSERT INTO trivia_facts VALUES(213,'The Hindu New Year varies based on regional Panchang traditions.','हिंदू नववर्ष क्षेत्रीय पंचांग परंपराओं के अनुसार भिन्न होता है।');
INSERT INTO trivia_facts VALUES(214,'Ekadashi occurs on the 11th Tithi and is considered sacred for fasting.','एकादशी 11वीं तिथि को होती है और उपवास के लिए पवित्र मानी जाती है।');
INSERT INTO trivia_facts VALUES(215,'Pradosh Vrat is observed during the 13th Tithi dedicated to Shiva.','प्रदोष व्रत 13वीं तिथि को शिव को समर्पित होता है।');
INSERT INTO trivia_facts VALUES(216,'Panchang also includes planetary positions for astrology.','पंचांग में ज्योतिष के लिए ग्रहों की स्थिति भी शामिल होती है।');
INSERT INTO trivia_facts VALUES(217,'Nakshatra-based months are used in Vedic rituals.','वैदिक अनुष्ठानों में नक्षत्र आधारित मासों का उपयोग होता है।');
INSERT INTO trivia_facts VALUES(218,'Tithi can change at any time of the day, not just at midnight.','तिथि दिन के किसी भी समय बदल सकती है, केवल मध्यरात्रि पर नहीं।');
INSERT INTO trivia_facts VALUES(219,'Panchang calculations are based on precise astronomical observations.','पंचांग की गणना सटीक खगोलीय अवलोकनों पर आधारित होती है।');
INSERT INTO trivia_facts VALUES(220,'Ancient Panchangs were calculated manually by learned astronomers.','प्राचीन पंचांग विद्वान ज्योतिषियों द्वारा हाथ से गणना करके बनाए जाते थे।');
INSERT INTO trivia_facts VALUES(221,'The idol at Padmanabhaswamy Temple is made of a rare combination called Katusarkara Yogam.','पद्मनाभस्वामी मंदिर की मूर्ति कटुसार्करा योगम नामक दुर्लभ मिश्रण से बनी है।');
INSERT INTO trivia_facts VALUES(222,'The doors of Vault B in Padmanabhaswamy Temple are believed to be opened only with a specific mantra.','पद्मनाभस्वामी मंदिर के वॉल्ट बी के द्वार केवल विशेष मंत्र से ही खोले जा सकते हैं, ऐसा माना जाता है।');
INSERT INTO trivia_facts VALUES(223,'Brihadeeswara Temple’s shadow of the main tower never falls on the ground at noon.','बृहदेश्वर मंदिर के मुख्य गोपुरम की छाया दोपहर में जमीन पर नहीं पड़ती।');
INSERT INTO trivia_facts VALUES(224,'The Jagannath Temple kitchen is considered the largest in the world.','जगन्नाथ मंदिर की रसोई दुनिया की सबसे बड़ी मानी जाती है।');
INSERT INTO trivia_facts VALUES(225,'At Jagannath Temple, food cooks perfectly even when pots are stacked one above another.','जगन्नाथ मंदिर में बर्तनों को एक के ऊपर एक रखने पर भी भोजन पूरी तरह पक जाता है।');
INSERT INTO trivia_facts VALUES(226,'The flag on Jagannath Temple always flows in the opposite direction of the wind.','जगन्नाथ मंदिर का ध्वज हवा की विपरीत दिशा में लहराता है।');
INSERT INTO trivia_facts VALUES(227,'No birds or planes are seen flying directly above Jagannath Temple.','जगन्नाथ मंदिर के ऊपर सीधे पक्षी या विमान उड़ते नहीं दिखते।');
INSERT INTO trivia_facts VALUES(228,'The Sun Temple at Konark is designed as a massive chariot with 24 intricately carved wheels.','कोणार्क का सूर्य मंदिर 24 सुंदर पहियों वाले विशाल रथ के रूप में बनाया गया है।');
INSERT INTO trivia_facts VALUES(229,'Each wheel of Konark Sun Temple can function as a sundial.','कोणार्क सूर्य मंदिर के प्रत्येक पहिए को सूर्य घड़ी के रूप में उपयोग किया जा सकता है।');
INSERT INTO trivia_facts VALUES(230,'The Kedarnath Temple has withstood multiple natural disasters for centuries.','केदारनाथ मंदिर सदियों से कई प्राकृतिक आपदाओं को झेल चुका है।');
INSERT INTO trivia_facts VALUES(231,'The Meenakshi Temple has over 30,000 sculptures.','मीनाक्षी मंदिर में 30,000 से अधिक मूर्तियाँ हैं।');
INSERT INTO trivia_facts VALUES(232,'The musical pillars of Hampi’s Vittala Temple produce different sounds when tapped.','हम्पी के विट्ठल मंदिर के संगीत स्तंभों को थपथपाने पर अलग-अलग ध्वनियाँ निकलती हैं।');
INSERT INTO trivia_facts VALUES(233,'The Somnath Temple has no landmass in a straight line between it and the South Pole.','सोमनाथ मंदिर और दक्षिण ध्रुव के बीच सीधी रेखा में कोई भूभाग नहीं है।');
INSERT INTO trivia_facts VALUES(234,'The Tirupati Balaji Temple receives one of the highest donations in the world.','तिरुपति बालाजी मंदिर दुनिया के सबसे अधिक दान प्राप्त करने वाले मंदिरों में से एक है।');
INSERT INTO trivia_facts VALUES(235,'The hair offered at Tirupati Temple is auctioned globally.','तिरुपति मंदिर में चढ़ाए गए बालों की वैश्विक नीलामी होती है।');
INSERT INTO trivia_facts VALUES(236,'The idol at Tirupati is believed to have real hair that never tangles.','तिरुपति की मूर्ति के बाल वास्तविक माने जाते हैं जो कभी उलझते नहीं।');
INSERT INTO trivia_facts VALUES(237,'The Kal Bhairav Temple in Varanasi offers liquor as prasad.','वाराणसी के काल भैरव मंदिर में शराब को प्रसाद के रूप में चढ़ाया जाता है।');
INSERT INTO trivia_facts VALUES(238,'At Kamakhya Temple, the Ambubachi Mela celebrates the annual menstruation of the goddess.','कामाख्या मंदिर में अंबुबाची मेले के दौरान देवी के वार्षिक ऋतु काल का उत्सव मनाया जाता है।');
INSERT INTO trivia_facts VALUES(239,'The Kamakhya Temple has no idol, only a natural yoni-shaped stone is worshipped.','कामाख्या मंदिर में कोई मूर्ति नहीं है, केवल प्राकृतिक योनि आकार की शिला की पूजा होती है।');
INSERT INTO trivia_facts VALUES(240,'The Lepakshi Temple has a hanging pillar that does not touch the ground.','लेपाक्षी मंदिर में एक लटकता हुआ स्तंभ है जो जमीन को नहीं छूता।');
INSERT INTO trivia_facts VALUES(241,'The Virupaksha Temple in Hampi has a pinhole camera effect projecting the gopuram image inverted.','हम्पी के विरुपाक्ष मंदिर में पिनहोल प्रभाव से गोपुरम की उलटी छवि दिखाई देती है।');
INSERT INTO trivia_facts VALUES(242,'The Sabarimala Temple allows entry only during specific months of the year.','सबरीमला मंदिर में केवल वर्ष के कुछ विशेष महीनों में ही प्रवेश की अनुमति होती है।');
INSERT INTO trivia_facts VALUES(243,'The Chidambaram Temple represents the concept of space among the five elements.','चिदंबरम मंदिर पंच तत्वों में आकाश तत्व का प्रतिनिधित्व करता है।');
INSERT INTO trivia_facts VALUES(244,'The Chidambaram Temple has a secret empty space worshipped as the divine.','चिदंबरम मंदिर में एक खाली स्थान को ही दिव्य रूप में पूजा जाता है।');
INSERT INTO trivia_facts VALUES(245,'The Anantha Padmanabha idol is so large it is viewed through three separate doors.','अनंत पद्मनाभ की मूर्ति इतनी विशाल है कि उसे तीन अलग-अलग द्वारों से देखा जाता है।');
INSERT INTO trivia_facts VALUES(246,'The Golden Temple in Vellore is covered entirely with gold sheets.','वेल्लोर का स्वर्ण मंदिर पूरी तरह सोने की परत से ढका हुआ है।');
INSERT INTO trivia_facts VALUES(247,'The Ramanathaswamy Temple has one of the longest temple corridors in the world.','रामनाथस्वामी मंदिर के पास दुनिया के सबसे लंबे मंदिर गलियारों में से एक है।');
INSERT INTO trivia_facts VALUES(248,'The temple tank at Rameshwaram has 22 wells with water of different tastes.','रामेश्वरम मंदिर के कुंड में 22 कुएं हैं जिनका पानी अलग-अलग स्वाद का है।');
INSERT INTO trivia_facts VALUES(249,'The Udupi Krishna idol is worshipped through a window with nine holes called Navagraha Kitiki.','उडुपी कृष्ण की मूर्ति की पूजा नौ छेद वाली खिड़की से की जाती है जिसे नवग्रह किटिकी कहते हैं।');
INSERT INTO trivia_facts VALUES(250,'The Sringeri Temple was chosen after Adi Shankaracharya saw a cobra shading a frog.','श्रृंगेरी मंदिर का स्थान आदि शंकराचार्य ने तब चुना जब उन्होंने एक सांप को मेंढक को छाया देते देखा।');
INSERT INTO trivia_facts VALUES(251,'The Kashi Vishwanath Temple is one of the twelve Jyotirlingas of Shiva.','काशी विश्वनाथ मंदिर शिव के बारह ज्योतिर्लिंगों में से एक है।');
INSERT INTO trivia_facts VALUES(252,'The Mahakaleshwar Temple is the only Jyotirlinga facing south.','महाकालेश्वर मंदिर एकमात्र दक्षिणमुखी ज्योतिर्लिंग है।');
INSERT INTO trivia_facts VALUES(253,'The Omkareshwar Temple is located on an island shaped like the Om symbol.','ओंकारेश्वर मंदिर ॐ के आकार के द्वीप पर स्थित है।');
INSERT INTO trivia_facts VALUES(254,'The Vaishno Devi shrine is located inside a natural cave in the mountains.','वैष्णो देवी का मंदिर पहाड़ों में एक प्राकृतिक गुफा के अंदर स्थित है।');
INSERT INTO trivia_facts VALUES(255,'The Akshardham Temple showcases intricate carvings without the use of steel.','अक्षरधाम मंदिर में बिना स्टील के अत्यंत जटिल नक्काशी की गई है।');
INSERT INTO trivia_facts VALUES(256,'The Dwarkadhish Temple is believed to stand over the ancient city of Krishna’s Dwarka.','द्वारकाधीश मंदिर कृष्ण की प्राचीन द्वारका नगरी के ऊपर स्थित माना जाता है।');
INSERT INTO trivia_facts VALUES(257,'The Badrinath Temple opens only for six months due to extreme weather conditions.','बद्रीनाथ मंदिर अत्यधिक मौसम के कारण वर्ष में केवल छह महीने खुलता है।');
INSERT INTO trivia_facts VALUES(258,'The Amarnath cave naturally forms an ice Shiva Linga every year.','अमरनाथ गुफा में हर वर्ष प्राकृतिक रूप से बर्फ का शिवलिंग बनता है।');
INSERT INTO trivia_facts VALUES(259,'The Ekambareswarar Temple houses a mango tree believed to be over 3,500 years old.','एकाम्बरेश्वर मंदिर में एक आम का पेड़ है जिसे 3,500 वर्ष से अधिक पुराना माना जाता है।');
INSERT INTO trivia_facts VALUES(260,'The Lingaraj Temple represents Harihara, a combined form of Shiva and Vishnu.','लिंगराज मंदिर हरिहर रूप का प्रतिनिधित्व करता है जो शिव और विष्णु का संयुक्त स्वरूप है।');
INSERT INTO trivia_facts VALUES(261,'Ancient Hindu texts describe the speed of light with surprising accuracy.','प्राचीन हिंदू ग्रंथों में प्रकाश की गति का आश्चर्यजनक रूप से सटीक वर्णन मिलता है।');
INSERT INTO trivia_facts VALUES(262,'The concept of multiverse is hinted in Puranic cosmology.','पुराणों में बहु-ब्रह्मांड की अवधारणा का संकेत मिलता है।');
INSERT INTO trivia_facts VALUES(263,'Time dilation concepts appear in stories where time flows differently in different lokas.','विभिन्न लोकों में समय अलग-अलग गति से बहने की अवधारणा कथाओं में मिलती है।');
INSERT INTO trivia_facts VALUES(264,'The Rigveda contains one of the earliest known philosophical hymns questioning creation.','ऋग्वेद में सृष्टि पर प्रश्न उठाने वाला सबसे प्राचीन दार्शनिक सूक्त मिलता है।');
INSERT INTO trivia_facts VALUES(265,'The concept of zero and decimal system originated in ancient Hindu mathematics.','शून्य और दशमलव प्रणाली की उत्पत्ति प्राचीन हिंदू गणित में हुई।');
INSERT INTO trivia_facts VALUES(266,'Ayurveda is one of the oldest holistic healing systems in the world.','आयुर्वेद दुनिया की सबसे प्राचीन समग्र चिकित्सा प्रणालियों में से एक है।');
INSERT INTO trivia_facts VALUES(267,'Yoga was originally a spiritual path aimed at union with the divine.','योग मूल रूप से ईश्वर से एकता प्राप्त करने का आध्यात्मिक मार्ग था।');
INSERT INTO trivia_facts VALUES(268,'The concept of karma predates many global philosophical systems.','कर्म का सिद्धांत कई वैश्विक दार्शनिक प्रणालियों से पहले का है।');
INSERT INTO trivia_facts VALUES(269,'Hindu cosmology calculates time in trillions of years.','हिंदू ब्रह्मांड विज्ञान समय को खरबों वर्षों में मापता है।');
INSERT INTO trivia_facts VALUES(270,'The idea that everything is one energy is central to Advaita philosophy.','सब कुछ एक ही ऊर्जा है, यह अद्वैत दर्शन का मूल विचार है।');
INSERT INTO trivia_facts VALUES(271,'Sanskrit is considered one of the most scientifically structured languages.','संस्कृत को सबसे वैज्ञानिक रूप से संरचित भाषाओं में से एक माना जाता है।');
INSERT INTO trivia_facts VALUES(272,'Panini’s Sanskrit grammar is one of the most advanced linguistic systems ever created.','पाणिनि का संस्कृत व्याकरण अब तक की सबसे उन्नत भाषाई प्रणालियों में से एक है।');
INSERT INTO trivia_facts VALUES(273,'The concept of atoms was described in Vaisheshika philosophy.','वैशेषिक दर्शन में परमाणु की अवधारणा का वर्णन मिलता है।');
INSERT INTO trivia_facts VALUES(274,'The idea of relativity of time appears in stories of Brahma and other lokas.','ब्रह्मा और अन्य लोकों की कथाओं में समय की सापेक्षता का विचार मिलता है।');
INSERT INTO trivia_facts VALUES(275,'Hindu texts describe cycles of creation and destruction similar to modern cosmology.','हिंदू ग्रंथ सृष्टि और विनाश के चक्रों का वर्णन करते हैं जो आधुनिक ब्रह्मांड विज्ञान से मेल खाते हैं।');
INSERT INTO trivia_facts VALUES(276,'The Sri Chakra is considered a visual representation of the universe’s structure.','श्री चक्र को ब्रह्मांड की संरचना का दृश्य रूप माना जाता है।');
INSERT INTO trivia_facts VALUES(277,'The Upanishads discuss consciousness as the fundamental reality.','उपनिषद चेतना को मूल वास्तविकता के रूप में प्रस्तुत करते हैं।');
INSERT INTO trivia_facts VALUES(278,'The concept of Maya explains the illusionary nature of reality.','माया की अवधारणा वास्तविकता की भ्रमात्मक प्रकृति को समझाती है।');
INSERT INTO trivia_facts VALUES(279,'Hindu philosophy allows multiple paths to truth, not just one.','हिंदू दर्शन सत्य तक पहुँचने के कई मार्गों को स्वीकार करता है।');
INSERT INTO trivia_facts VALUES(280,'The Bhagavad Gita is considered a manual for life and decision-making.','भगवद गीता को जीवन और निर्णय लेने की मार्गदर्शिका माना जाता है।');
INSERT INTO trivia_facts VALUES(281,'Meditation techniques described in Hindu texts are now widely used globally.','हिंदू ग्रंथों में वर्णित ध्यान तकनीकों का आज विश्वभर में उपयोग होता है।');
INSERT INTO trivia_facts VALUES(282,'The concept of chakras aligns closely with modern ideas of energy centers.','चक्रों की अवधारणा आधुनिक ऊर्जा केंद्रों के विचार से मेल खाती है।');
INSERT INTO trivia_facts VALUES(283,'Hindu rituals often incorporate precise astronomical calculations.','हिंदू अनुष्ठानों में सटीक खगोलीय गणनाओं का उपयोग होता है।');
INSERT INTO trivia_facts VALUES(284,'The Mahabharata mentions advanced weapons resembling modern technology.','महाभारत में उन्नत अस्त्रों का वर्णन मिलता है जो आधुनिक तकनीक जैसे लगते हैं।');
INSERT INTO trivia_facts VALUES(285,'The Ramayana describes aerial vehicles like the Pushpaka Vimana.','रामायण में पुष्पक विमान जैसे उड़ने वाले यानों का वर्णन मिलता है।');
INSERT INTO trivia_facts VALUES(286,'Hindu temple architecture encodes cosmic and mathematical principles.','हिंदू मंदिर वास्तुकला में ब्रह्मांडीय और गणितीय सिद्धांत समाहित होते हैं।');
INSERT INTO trivia_facts VALUES(287,'The number 108 is deeply significant in Hinduism across rituals and astronomy.','108 संख्या हिंदू धर्म में अनुष्ठानों और खगोल विज्ञान दोनों में महत्वपूर्ण है।');
INSERT INTO trivia_facts VALUES(288,'The concept of Dharma is dynamic and changes based on context.','धर्म की अवधारणा परिस्थितियों के अनुसार बदलती है।');
INSERT INTO trivia_facts VALUES(289,'The Gita teaches performing actions without attachment to results.','गीता कर्म को फल की आसक्ति के बिना करने की शिक्षा देती है।');
INSERT INTO trivia_facts VALUES(290,'Hinduism has no single founder and evolved over thousands of years.','हिंदू धर्म का कोई एक संस्थापक नहीं है और यह हजारों वर्षों में विकसित हुआ है।');
INSERT INTO trivia_facts VALUES(291,'The concept of reincarnation is central to Hindu thought.','पुनर्जन्म की अवधारणा हिंदू विचारधारा का केंद्र है।');
INSERT INTO trivia_facts VALUES(292,'Hindu texts describe the Earth as spherical in ancient times.','प्राचीन हिंदू ग्रंथों में पृथ्वी को गोल बताया गया है।');
INSERT INTO trivia_facts VALUES(293,'The Surya Siddhanta contains advanced astronomical calculations.','सूर्य सिद्धांत में उन्नत खगोलीय गणनाएँ हैं।');
INSERT INTO trivia_facts VALUES(294,'Hindu festivals are aligned with lunar and solar cycles.','हिंदू त्योहार चंद्र और सौर चक्रों के अनुसार निर्धारित होते हैं।');
INSERT INTO trivia_facts VALUES(295,'The concept of Guru is seen as essential for true knowledge.','गुरु को सच्चे ज्ञान के लिए आवश्यक माना जाता है।');
INSERT INTO trivia_facts VALUES(296,'The idea of inner divinity is emphasized in many Hindu teachings.','कई हिंदू शिक्षाओं में आंतरिक दिव्यता पर जोर दिया गया है।');
INSERT INTO trivia_facts VALUES(297,'The Upanishads explore questions about existence long before modern philosophy.','उपनिषद आधुनिक दर्शन से बहुत पहले अस्तित्व के प्रश्नों का अन्वेषण करते हैं।');
INSERT INTO trivia_facts VALUES(298,'The concept of balance between material and spiritual life is emphasized.','भौतिक और आध्यात्मिक जीवन के संतुलन पर जोर दिया गया है।');
INSERT INTO trivia_facts VALUES(299,'Hinduism embraces both form and formless worship of the divine.','हिंदू धर्म साकार और निराकार दोनों रूपों की पूजा को स्वीकार करता है।');
INSERT INTO trivia_facts VALUES(300,'The idea that truth can be approached in many ways is a core principle.','सत्य को कई मार्गों से प्राप्त किया जा सकता है, यह एक मूल सिद्धांत है।');
INSERT INTO trivia_facts VALUES(301,'Krishna was born in a prison in Mathura.','कृष्ण का जन्म मथुरा के कारागार में हुआ था।');
INSERT INTO trivia_facts VALUES(302,'Krishna was raised by Yashoda and Nanda in Gokul.','कृष्ण का पालन-पोषण यशोदा और नंद ने गोकुल में किया।');
INSERT INTO trivia_facts VALUES(303,'Krishna is considered the eighth avatar of Vishnu.','कृष्ण को विष्णु का आठवां अवतार माना जाता है।');
INSERT INTO trivia_facts VALUES(304,'Krishna killed the demoness Putana as an infant.','कृष्ण ने शिशु अवस्था में ही पूतना का वध किया था।');
INSERT INTO trivia_facts VALUES(305,'Krishna lifted Govardhan Hill to protect villagers from Indra’s wrath.','कृष्ण ने इंद्र के प्रकोप से बचाने के लिए गोवर्धन पर्वत उठाया था।');
INSERT INTO trivia_facts VALUES(306,'Krishna is known as Makhan Chor for stealing butter.','कृष्ण को माखन चोर के नाम से जाना जाता है।');
INSERT INTO trivia_facts VALUES(307,'Krishna subdued the serpent Kaliya in the Yamuna river.','कृष्ण ने यमुना नदी में कालिया नाग को वश में किया।');
INSERT INTO trivia_facts VALUES(308,'Krishna’s flute is believed to enchant all beings.','कृष्ण की बांसुरी सभी प्राणियों को मोहित कर देती है।');
INSERT INTO trivia_facts VALUES(309,'Krishna performed the Raas Leela with the Gopis of Vrindavan.','कृष्ण ने वृंदावन की गोपियों के साथ रास लीला की।');
INSERT INTO trivia_facts VALUES(310,'Radha is considered Krishna’s eternal consort.','राधा को कृष्ण की शाश्वत संगिनी माना जाता है।');
INSERT INTO trivia_facts VALUES(311,'Krishna killed his maternal uncle Kansa.','कृष्ण ने अपने मामा कंस का वध किया।');
INSERT INTO trivia_facts VALUES(312,'Krishna moved from Mathura to Dwarka to establish his kingdom.','कृष्ण ने अपना राज्य स्थापित करने के लिए मथुरा से द्वारका प्रस्थान किया।');
INSERT INTO trivia_facts VALUES(313,'Krishna had 16,108 wives according to the Puranas.','पुराणों के अनुसार कृष्ण की 16,108 पत्नियाँ थीं।');
INSERT INTO trivia_facts VALUES(314,'Rukmini was Krishna’s principal queen.','रुक्मिणी कृष्ण की प्रमुख पत्नी थीं।');
INSERT INTO trivia_facts VALUES(315,'Krishna was a close friend and guide of Arjuna.','कृष्ण अर्जुन के घनिष्ठ मित्र और मार्गदर्शक थे।');
INSERT INTO trivia_facts VALUES(316,'Krishna delivered the Bhagavad Gita on the battlefield of Kurukshetra.','कृष्ण ने कुरुक्षेत्र के युद्धभूमि में भगवद गीता का उपदेश दिया।');
INSERT INTO trivia_facts VALUES(317,'Krishna chose to remain unarmed in the Mahabharata war.','कृष्ण ने महाभारत युद्ध में शस्त्र न उठाने का निर्णय लिया।');
INSERT INTO trivia_facts VALUES(318,'Krishna served as Arjuna’s charioteer during the war.','कृष्ण युद्ध में अर्जुन के सारथी बने।');
INSERT INTO trivia_facts VALUES(319,'Krishna revealed his Vishwaroopa to Arjuna.','कृष्ण ने अर्जुन को अपना विश्वरूप दिखाया।');
INSERT INTO trivia_facts VALUES(320,'Krishna played a key role in the defeat of many Kaurava warriors.','कृष्ण ने कई कौरव योद्धाओं की पराजय में महत्वपूर्ण भूमिका निभाई।');
INSERT INTO trivia_facts VALUES(321,'Krishna guided Bhima to defeat Duryodhana.','कृष्ण ने भीम को दुर्योधन को हराने में मार्गदर्शन दिया।');
INSERT INTO trivia_facts VALUES(322,'Krishna ensured the fall of Bhishma through strategy involving Shikhandi.','कृष्ण ने शिखंडी की सहायता से भीष्म के पतन की योजना बनाई।');
INSERT INTO trivia_facts VALUES(323,'Krishna advised Arjuna to kill Karna when he was vulnerable.','कृष्ण ने अर्जुन को कर्ण को कमजोर स्थिति में मारने की सलाह दी।');
INSERT INTO trivia_facts VALUES(324,'Krishna’s Sudarshana Chakra is his most powerful weapon.','कृष्ण का सुदर्शन चक्र उनका सबसे शक्तिशाली अस्त्र है।');
INSERT INTO trivia_facts VALUES(325,'Krishna protected Draupadi during the disrobing incident.','कृष्ण ने द्रौपदी के चीरहरण के समय उसकी रक्षा की।');
INSERT INTO trivia_facts VALUES(326,'Krishna is often depicted with a peacock feather on his crown.','कृष्ण को अक्सर मुकुट में मोर पंख के साथ दर्शाया जाता है।');
INSERT INTO trivia_facts VALUES(327,'Krishna is called Govinda, meaning protector of cows.','कृष्ण को गोविंद कहा जाता है, जिसका अर्थ है गायों के रक्षक।');
INSERT INTO trivia_facts VALUES(328,'Krishna is also known as Madhava and Keshava.','कृष्ण को माधव और केशव के नाम से भी जाना जाता है।');
INSERT INTO trivia_facts VALUES(329,'Krishna’s birthday is celebrated as Janmashtami.','कृष्ण का जन्मदिन जन्माष्टमी के रूप में मनाया जाता है।');
INSERT INTO trivia_facts VALUES(330,'Krishna spent his childhood in Vrindavan.','कृष्ण ने अपना बचपन वृंदावन में बिताया।');
INSERT INTO trivia_facts VALUES(331,'Krishna killed the bull demon Arishta.','कृष्ण ने अरिष्ट नामक बैल राक्षस का वध किया।');
INSERT INTO trivia_facts VALUES(332,'Krishna defeated the horse demon Keshi.','कृष्ण ने केशी नामक घोड़े रूपी राक्षस को मारा।');
INSERT INTO trivia_facts VALUES(333,'Krishna swallowed a forest fire to save the villagers.','कृष्ण ने ग्रामीणों को बचाने के लिए जंगल की आग निगल ली।');
INSERT INTO trivia_facts VALUES(334,'Krishna showed the entire universe in his mouth to Yashoda.','कृष्ण ने यशोदा को अपने मुख में पूरा ब्रह्मांड दिखाया।');
INSERT INTO trivia_facts VALUES(335,'Krishna’s life teaches a balance of love, duty, and wisdom.','कृष्ण का जीवन प्रेम, कर्तव्य और ज्ञान का संतुलन सिखाता है।');
INSERT INTO trivia_facts VALUES(336,'Krishna is often associated with the color blue symbolizing infinity.','कृष्ण को नीले रंग से जोड़ा जाता है जो अनंत का प्रतीक है।');
INSERT INTO trivia_facts VALUES(337,'Krishna played a role in establishing Yudhishthira as king.','कृष्ण ने युधिष्ठिर को राजा बनाने में भूमिका निभाई।');
INSERT INTO trivia_facts VALUES(338,'Krishna’s teachings emphasize detachment and righteous action.','कृष्ण की शिक्षाएँ वैराग्य और धर्मपूर्ण कर्म पर जोर देती हैं।');
INSERT INTO trivia_facts VALUES(339,'Krishna departed from the world after being struck by a hunter’s arrow.','कृष्ण का देहांत एक शिकारी के तीर लगने से हुआ।');
INSERT INTO trivia_facts VALUES(340,'Krishna’s departure marks the end of Dvapara Yuga and the beginning of Kali Yuga.','कृष्ण के प्रस्थान के साथ द्वापर युग का अंत और कलियुग की शुरुआत मानी जाती है।');
INSERT INTO trivia_facts VALUES(341,'Shiva is known as Mahadev, meaning the greatest of all gods.','शिव को महादेव कहा जाता है, जिसका अर्थ है सभी देवों में महान।');
INSERT INTO trivia_facts VALUES(342,'Shiva is part of the Trimurti as the destroyer and transformer.','शिव त्रिमूर्ति में संहारक और परिवर्तनकर्ता के रूप में शामिल हैं।');
INSERT INTO trivia_facts VALUES(343,'Shiva is also called Neelkanth after drinking poison during Samudra Manthan.','समुद्र मंथन के समय विष पीने के कारण शिव को नीलकंठ कहा जाता है।');
INSERT INTO trivia_facts VALUES(344,'The river Ganga is believed to flow from Shiva’s matted hair.','गंगा नदी को शिव की जटाओं से प्रवाहित माना जाता है।');
INSERT INTO trivia_facts VALUES(345,'Shiva resides on Mount Kailash in deep meditation.','शिव कैलाश पर्वत पर गहन ध्यान में निवास करते हैं।');
INSERT INTO trivia_facts VALUES(346,'Shiva’s third eye represents wisdom and destruction of evil.','शिव की तीसरी आंख ज्ञान और बुराई के विनाश का प्रतीक है।');
INSERT INTO trivia_facts VALUES(347,'Shiva carries a trident called Trishul.','शिव त्रिशूल धारण करते हैं।');
INSERT INTO trivia_facts VALUES(348,'The damru in Shiva’s hand symbolizes cosmic sound and rhythm.','शिव के हाथ का डमरू ब्रह्मांडीय ध्वनि और लय का प्रतीक है।');
INSERT INTO trivia_facts VALUES(349,'Nandi the bull is Shiva’s vehicle and gatekeeper.','नंदी बैल शिव का वाहन और द्वारपाल है।');
INSERT INTO trivia_facts VALUES(350,'Shiva is often depicted with ash smeared over his body.','शिव को अक्सर शरीर पर भस्म लगाए हुए दर्शाया जाता है।');
INSERT INTO trivia_facts VALUES(351,'Shiva is known as Bholenath for his simple and kind nature.','शिव को भोलेनाथ कहा जाता है क्योंकि वे सरल और दयालु हैं।');
INSERT INTO trivia_facts VALUES(352,'Shiva performed the Tandava, the cosmic dance of creation and destruction.','शिव ने तांडव नृत्य किया जो सृष्टि और संहार का प्रतीक है।');
INSERT INTO trivia_facts VALUES(353,'Shiva is Ardhanarishvara, representing the union of masculine and feminine energies.','शिव अर्धनारीश्वर हैं, जो स्त्री और पुरुष ऊर्जा के मिलन का प्रतीक हैं।');
INSERT INTO trivia_facts VALUES(354,'Shiva wears a crescent moon on his head symbolizing time.','शिव अपने मस्तक पर अर्धचंद्र धारण करते हैं जो समय का प्रतीक है।');
INSERT INTO trivia_facts VALUES(355,'The serpent around Shiva’s neck represents control over fear and death.','शिव के गले का सर्प भय और मृत्यु पर नियंत्रण का प्रतीक है।');
INSERT INTO trivia_facts VALUES(356,'Shiva is also called Pashupati, the lord of all living beings.','शिव को पशुपति भी कहा जाता है, जिसका अर्थ है सभी जीवों के स्वामी।');
INSERT INTO trivia_facts VALUES(357,'Shiva’s weapon Pinaka is a powerful divine bow.','शिव का धनुष पिनाक एक शक्तिशाली दिव्य अस्त्र है।');
INSERT INTO trivia_facts VALUES(358,'Shiva burned Kamadeva to ashes with his third eye.','शिव ने अपनी तीसरी आंख से कामदेव को भस्म कर दिया था।');
INSERT INTO trivia_facts VALUES(359,'Shiva is worshipped in the form of a Lingam representing the formless divine.','शिव की पूजा लिंग रूप में होती है जो निराकार ईश्वर का प्रतीक है।');
INSERT INTO trivia_facts VALUES(360,'The Rudraksha beads are believed to have originated from Shiva’s tears.','रुद्राक्ष को शिव के आँसुओं से उत्पन्न माना जाता है।');
INSERT INTO trivia_facts VALUES(361,'Shiva is known as the Adiyogi, the first yogi.','शिव को आदि योगी कहा जाता है, जो पहले योगी हैं।');
INSERT INTO trivia_facts VALUES(362,'Shiva taught yoga to the Saptarishis.','शिव ने सप्तऋषियों को योग का ज्ञान दिया।');
INSERT INTO trivia_facts VALUES(363,'Shiva is also called Mahayogi for his deep meditation.','गहन ध्यान के कारण शिव को महायोगी कहा जाता है।');
INSERT INTO trivia_facts VALUES(364,'Shiva married Parvati, the reincarnation of Sati.','शिव ने सती के पुनर्जन्म पार्वती से विवाह किया।');
INSERT INTO trivia_facts VALUES(365,'Ganesha and Kartikeya are the sons of Shiva and Parvati.','गणेश और कार्तिकेय शिव और पार्वती के पुत्र हैं।');
INSERT INTO trivia_facts VALUES(366,'Shiva is also called Nataraja, the lord of dance.','शिव को नटराज कहा जाता है, जो नृत्य के देवता हैं।');
INSERT INTO trivia_facts VALUES(367,'The ashes on Shiva’s body symbolize the transient nature of life.','शिव के शरीर की भस्म जीवन की नश्वरता का प्रतीक है।');
INSERT INTO trivia_facts VALUES(368,'Shiva is often depicted sitting on a tiger skin symbolizing victory over desire.','शिव को अक्सर बाघ की खाल पर बैठे दिखाया जाता है जो इच्छाओं पर विजय का प्रतीक है।');
INSERT INTO trivia_facts VALUES(369,'The Ganas are Shiva’s attendants and followers.','गण शिव के अनुचर और भक्त हैं।');
INSERT INTO trivia_facts VALUES(370,'Shiva is called Rudra in the Vedas.','वेदों में शिव को रुद्र कहा गया है।');
INSERT INTO trivia_facts VALUES(371,'Shiva is beyond birth and death and is considered eternal.','शिव जन्म और मृत्यु से परे हैं और उन्हें शाश्वत माना जाता है।');
INSERT INTO trivia_facts VALUES(372,'Shiva’s Tandava represents both destruction and regeneration.','शिव का तांडव विनाश और पुनर्निर्माण दोनों का प्रतीक है।');
INSERT INTO trivia_facts VALUES(373,'Shiva granted the Sudarshana Chakra to Vishnu.','शिव ने विष्णु को सुदर्शन चक्र प्रदान किया था।');
INSERT INTO trivia_facts VALUES(374,'Shiva is known to be easily pleased by devotion.','शिव भक्ति से शीघ्र प्रसन्न होने वाले माने जाते हैं।');
INSERT INTO trivia_facts VALUES(375,'The festival Mahashivaratri is dedicated to Shiva.','महाशिवरात्रि का पर्व शिव को समर्पित है।');
INSERT INTO trivia_facts VALUES(376,'Shiva is associated with the element of space or ether.','शिव को आकाश तत्व से जोड़ा जाता है।');
INSERT INTO trivia_facts VALUES(377,'Shiva’s form represents both destruction and compassion.','शिव का स्वरूप विनाश और करुणा दोनों का प्रतिनिधित्व करता है।');
INSERT INTO trivia_facts VALUES(378,'Shiva is worshipped in twelve Jyotirlingas across India.','भारत में बारह ज्योतिर्लिंगों में शिव की पूजा की जाती है।');
INSERT INTO trivia_facts VALUES(379,'Shiva is called Mahakaal as the lord of time.','शिव को समय के स्वामी के रूप में महाकाल कहा जाता है।');
INSERT INTO trivia_facts VALUES(380,'Shiva represents the ultimate reality beyond form and attributes.','शिव निराकार और निर्गुण परम सत्य का प्रतिनिधित्व करते हैं।');
INSERT INTO trivia_facts VALUES(381,'Hanuman is considered an incarnation of Lord Shiva.','हनुमान को भगवान शिव का अवतार माना जाता है।');
INSERT INTO trivia_facts VALUES(382,'Hanuman is the son of Vayu, the wind god.','हनुमान वायु देव के पुत्र हैं।');
INSERT INTO trivia_facts VALUES(383,'Hanuman is also known as Pavanputra.','हनुमान को पवनपुत्र भी कहा जाता है।');
INSERT INTO trivia_facts VALUES(384,'As a child, Hanuman tried to eat the Sun thinking it was a fruit.','बाल्यकाल में हनुमान ने सूर्य को फल समझकर खाने का प्रयास किया।');
INSERT INTO trivia_facts VALUES(385,'Hanuman possesses Ashta Siddhis and Nava Nidhis.','हनुमान के पास अष्ट सिद्धियाँ और नव निधियाँ हैं।');
INSERT INTO trivia_facts VALUES(386,'Hanuman is known for his immense strength and speed.','हनुमान अपनी अपार शक्ति और गति के लिए प्रसिद्ध हैं।');
INSERT INTO trivia_facts VALUES(387,'Hanuman is a lifelong celibate known as Brahmachari.','हनुमान आजीवन ब्रह्मचारी माने जाते हैं।');
INSERT INTO trivia_facts VALUES(388,'Hanuman met Rama in Kishkindha and became his devoted servant.','हनुमान की मुलाकात राम से किष्किंधा में हुई और वे उनके परम भक्त बने।');
INSERT INTO trivia_facts VALUES(389,'Hanuman played a key role in finding Sita in Lanka.','हनुमान ने लंका में सीता को खोजने में महत्वपूर्ण भूमिका निभाई।');
INSERT INTO trivia_facts VALUES(390,'Hanuman leapt across the ocean to reach Lanka.','हनुमान ने समुद्र पार करने के लिए विशाल छलांग लगाई।');
INSERT INTO trivia_facts VALUES(391,'Hanuman set Lanka on fire with his burning tail.','हनुमान ने अपनी जलती हुई पूंछ से लंका को जला दिया।');
INSERT INTO trivia_facts VALUES(392,'Hanuman brought the Sanjeevani herb to save Lakshmana.','हनुमान संजीवनी बूटी लाकर लक्ष्मण को बचाया।');
INSERT INTO trivia_facts VALUES(393,'Hanuman carried the entire mountain when he couldn’t identify the herb.','हनुमान ने जड़ी-बूटी न पहचान पाने पर पूरा पर्वत उठा लिया।');
INSERT INTO trivia_facts VALUES(394,'Hanuman is known as Sankat Mochan, the remover of troubles.','हनुमान को संकटमोचन कहा जाता है, जो संकटों को दूर करते हैं।');
INSERT INTO trivia_facts VALUES(395,'Hanuman is believed to be immortal or Chiranjeevi.','हनुमान को चिरंजीवी माना जाता है।');
INSERT INTO trivia_facts VALUES(396,'Hanuman is mentioned in both Ramayana and Mahabharata.','हनुमान का उल्लेख रामायण और महाभारत दोनों में मिलता है।');
INSERT INTO trivia_facts VALUES(397,'Hanuman appeared on Arjuna’s chariot flag during the Kurukshetra war.','हनुमान कुरुक्षेत्र युद्ध में अर्जुन के रथ के ध्वज पर विराजमान थे।');
INSERT INTO trivia_facts VALUES(398,'Hanuman humbled Bhima by showing his divine form.','हनुमान ने भीम को अपना दिव्य रूप दिखाकर विनम्र किया।');
INSERT INTO trivia_facts VALUES(399,'Hanuman is a master of the nine forms of devotion or Navadha Bhakti.','हनुमान नवधा भक्ति के ज्ञाता माने जाते हैं।');
INSERT INTO trivia_facts VALUES(400,'Hanuman can change his size at will, from tiny to gigantic.','हनुमान अपनी इच्छा से आकार बदल सकते हैं, छोटे से विशाल तक।');
INSERT INTO trivia_facts VALUES(401,'Hanuman is often depicted carrying a gada (mace).','हनुमान को अक्सर गदा धारण किए हुए दिखाया जाता है।');
INSERT INTO trivia_facts VALUES(402,'Hanuman opened his chest to reveal Rama and Sita in his heart.','हनुमान ने अपने हृदय में राम और सीता को दिखाने के लिए अपनी छाती चीर दी।');
INSERT INTO trivia_facts VALUES(403,'Hanuman learned the scriptures from Surya, the Sun god.','हनुमान ने सूर्य देव से शास्त्रों की शिक्षा प्राप्त की।');
INSERT INTO trivia_facts VALUES(404,'Hanuman is considered the symbol of strength, devotion, and courage.','हनुमान शक्ति, भक्ति और साहस के प्रतीक माने जाते हैं।');
INSERT INTO trivia_facts VALUES(405,'Hanuman is worshipped widely across India and Southeast Asia.','हनुमान की पूजा भारत और दक्षिण-पूर्व एशिया में व्यापक रूप से होती है।');
INSERT INTO trivia_facts VALUES(406,'The Hanuman Chalisa is one of the most popular devotional hymns.','हनुमान चालीसा सबसे लोकप्रिय भक्तिपूर्ण स्तोत्रों में से एक है।');
INSERT INTO trivia_facts VALUES(407,'Hanuman is believed to remove fear and negative energies.','हनुमान को भय और नकारात्मक ऊर्जा को दूर करने वाला माना जाता है।');
INSERT INTO trivia_facts VALUES(408,'Hanuman is also called Bajrangbali, meaning strong as a thunderbolt.','हनुमान को बजरंगबली कहा जाता है, जिसका अर्थ है वज्र के समान शक्तिशाली।');
INSERT INTO trivia_facts VALUES(409,'Hanuman’s name is derived from a childhood incident involving his jaw.','हनुमान का नाम उनके बचपन की एक घटना से जुड़ा है जिसमें उनकी ठोड़ी प्रभावित हुई थी।');
INSERT INTO trivia_facts VALUES(410,'Hanuman is one of the central characters in the Sundara Kanda of Ramayana.','हनुमान रामायण के सुंदरकांड के प्रमुख पात्र हैं।');
INSERT INTO trivia_facts VALUES(411,'Hanuman can travel at the speed of thought.','हनुमान मन की गति से भी तेज चल सकते हैं।');
INSERT INTO trivia_facts VALUES(412,'Hanuman is said to reside wherever Rama’s name is chanted.','जहाँ भी राम का नाम लिया जाता है, वहाँ हनुमान का वास माना जाता है।');
INSERT INTO trivia_facts VALUES(413,'Hanuman defeated many powerful demons during the war in Lanka.','हनुमान ने लंका युद्ध में कई शक्तिशाली राक्षसों को पराजित किया।');
INSERT INTO trivia_facts VALUES(414,'Hanuman is known for his humility despite his immense power.','अपार शक्ति होने के बावजूद हनुमान अपनी विनम्रता के लिए जाने जाते हैं।');
INSERT INTO trivia_facts VALUES(415,'Hanuman’s devotion to Rama is considered the highest form of Bhakti.','राम के प्रति हनुमान की भक्ति को सर्वोच्च भक्ति माना जाता है।');
INSERT INTO trivia_facts VALUES(416,'Hanuman protected the Ashoka Vatika while meeting Sita.','हनुमान ने सीता से मिलते समय अशोक वाटिका में अपनी शक्ति दिखाई।');
INSERT INTO trivia_facts VALUES(417,'Hanuman is often invoked before starting any important task.','किसी भी महत्वपूर्ण कार्य से पहले हनुमान का स्मरण किया जाता है।');
INSERT INTO trivia_facts VALUES(418,'Hanuman is believed to grant courage and wisdom to devotees.','हनुमान भक्तों को साहस और बुद्धि प्रदान करते हैं।');
INSERT INTO trivia_facts VALUES(419,'Hanuman is associated with Tuesday and Saturday worship.','हनुमान की पूजा विशेष रूप से मंगलवार और शनिवार को की जाती है।');
INSERT INTO trivia_facts VALUES(420,'Hanuman symbolizes the perfect balance of strength, wisdom, and devotion.','हनुमान शक्ति, बुद्धि और भक्ति के आदर्श संतुलन का प्रतीक हैं।');
INSERT INTO trivia_facts VALUES(421,'Vishnu is known as the preserver in the Hindu Trimurti.','विष्णु को हिंदू त्रिमूर्ति में पालनकर्ता माना जाता है।');
INSERT INTO trivia_facts VALUES(422,'Vishnu is believed to reside in Vaikuntha, his divine abode.','विष्णु वैकुंठ में निवास करते हैं, जो उनका दिव्य धाम है।');
INSERT INTO trivia_facts VALUES(423,'Vishnu rests on the serpent Shesha in the cosmic ocean.','विष्णु क्षीरसागर में शेषनाग पर शयन करते हैं।');
INSERT INTO trivia_facts VALUES(424,'Lakshmi, the goddess of wealth, is the consort of Vishnu.','धन की देवी लक्ष्मी, विष्णु की पत्नी हैं।');
INSERT INTO trivia_facts VALUES(425,'Vishnu is often depicted with four arms holding symbolic objects.','विष्णु को चार भुजाओं के साथ प्रतीकात्मक वस्तुएँ धारण करते हुए दिखाया जाता है।');
INSERT INTO trivia_facts VALUES(426,'Vishnu holds a conch called Panchajanya.','विष्णु पंचजन्य नामक शंख धारण करते हैं।');
INSERT INTO trivia_facts VALUES(427,'Vishnu carries the Sudarshana Chakra, a spinning disc weapon.','विष्णु सुदर्शन चक्र धारण करते हैं जो एक घूमने वाला अस्त्र है।');
INSERT INTO trivia_facts VALUES(428,'Vishnu’s mace is called Kaumodaki.','विष्णु की गदा को कौमोदकी कहा जाता है।');
INSERT INTO trivia_facts VALUES(429,'Vishnu holds a lotus symbolizing purity and creation.','विष्णु कमल धारण करते हैं जो पवित्रता और सृष्टि का प्रतीक है।');
INSERT INTO trivia_facts VALUES(430,'Vishnu has ten major avatars known as Dashavatara.','विष्णु के दस प्रमुख अवतार हैं जिन्हें दशावतार कहा जाता है।');
INSERT INTO trivia_facts VALUES(431,'Matsya, the fish, was Vishnu’s first avatar.','मत्स्य, मछली, विष्णु का पहला अवतार था।');
INSERT INTO trivia_facts VALUES(432,'Kurma, the tortoise, supported Mount Mandara during Samudra Manthan.','कूर्म, कछुआ अवतार ने समुद्र मंथन के समय मंदर पर्वत को सहारा दिया।');
INSERT INTO trivia_facts VALUES(433,'Varaha lifted the Earth from the cosmic ocean.','वराह ने पृथ्वी को समुद्र से उठाया था।');
INSERT INTO trivia_facts VALUES(434,'Narasimha appeared as half-man, half-lion to defeat Hiranyakashipu.','नरसिंह आधा मनुष्य और आधा सिंह रूप में प्रकट हुए और हिरण्यकशिपु का वध किया।');
INSERT INTO trivia_facts VALUES(435,'Vamana took three steps to measure the universe.','वामन ने तीन पगों में ब्रह्मांड को नाप लिया।');
INSERT INTO trivia_facts VALUES(436,'Parashurama is the warrior sage avatar of Vishnu.','परशुराम विष्णु के योद्धा ऋषि अवतार हैं।');
INSERT INTO trivia_facts VALUES(437,'Rama is an avatar of Vishnu known for righteousness.','राम विष्णु के अवतार हैं जो धर्म के लिए प्रसिद्ध हैं।');
INSERT INTO trivia_facts VALUES(438,'Krishna is one of the most popular avatars of Vishnu.','कृष्ण विष्णु के सबसे लोकप्रिय अवतारों में से एक हैं।');
INSERT INTO trivia_facts VALUES(439,'Buddha is considered an avatar of Vishnu in some traditions.','कुछ परंपराओं में बुद्ध को विष्णु का अवतार माना जाता है।');
INSERT INTO trivia_facts VALUES(440,'Kalki is the future avatar who will appear at the end of Kali Yuga.','कल्कि भविष्य के अवतार हैं जो कलियुग के अंत में प्रकट होंगे।');
INSERT INTO trivia_facts VALUES(441,'Vishnu is also known as Narayana.','विष्णु को नारायण भी कहा जाता है।');
INSERT INTO trivia_facts VALUES(442,'The Garuda, a divine eagle, is the vehicle of Vishnu.','गरुड़, एक दिव्य पक्षी, विष्णु का वाहन है।');
INSERT INTO trivia_facts VALUES(443,'Vishnu’s navel is said to give rise to Brahma seated on a lotus.','विष्णु की नाभि से कमल उत्पन्न होता है जिस पर ब्रह्मा विराजमान होते हैं।');
INSERT INTO trivia_facts VALUES(444,'Vishnu maintains cosmic order and balance in the universe.','विष्णु ब्रह्मांड में संतुलन और व्यवस्था बनाए रखते हैं।');
INSERT INTO trivia_facts VALUES(445,'Vishnu is associated with the quality of Sattva.','विष्णु को सत्त्व गुण से जोड़ा जाता है।');
INSERT INTO trivia_facts VALUES(446,'The name Vishnu means one who pervades everything.','विष्णु का अर्थ है जो सबमें व्याप्त है।');
INSERT INTO trivia_facts VALUES(447,'Vishnu is worshipped in many forms across India.','विष्णु की भारत भर में अनेक रूपों में पूजा की जाती है।');
INSERT INTO trivia_facts VALUES(448,'The Vaishnava tradition is dedicated to the worship of Vishnu.','वैष्णव परंपरा विष्णु की भक्ति को समर्पित है।');
INSERT INTO trivia_facts VALUES(449,'Vishnu is often depicted with blue skin symbolizing infinity.','विष्णु को अक्सर नीले रंग के साथ दर्शाया जाता है जो अनंत का प्रतीक है।');
INSERT INTO trivia_facts VALUES(450,'The Sudarshana Chakra is said to move with the speed of thought.','सुदर्शन चक्र को मन की गति से चलने वाला माना जाता है।');
INSERT INTO trivia_facts VALUES(451,'Vishnu protects dharma by incarnating whenever needed.','विष्णु धर्म की रक्षा के लिए समय-समय पर अवतार लेते हैं।');
INSERT INTO trivia_facts VALUES(452,'Vishnu is invoked in many Vedic hymns.','विष्णु का उल्लेख कई वैदिक सूक्तों में मिलता है।');
INSERT INTO trivia_facts VALUES(453,'The Vishnu Sahasranama lists 1000 names of Vishnu.','विष्णु सहस्रनाम में विष्णु के 1000 नामों का वर्णन है।');
INSERT INTO trivia_facts VALUES(454,'Vishnu is associated with preservation of life and harmony.','विष्णु जीवन और सामंजस्य के संरक्षण से जुड़े हैं।');
INSERT INTO trivia_facts VALUES(455,'The conch of Vishnu symbolizes the sound of creation.','विष्णु का शंख सृष्टि की ध्वनि का प्रतीक है।');
INSERT INTO trivia_facts VALUES(456,'The lotus in Vishnu’s hand represents purity amidst chaos.','विष्णु के हाथ का कमल अराजकता में पवित्रता का प्रतीक है।');
INSERT INTO trivia_facts VALUES(457,'Garuda is considered an enemy of serpents and a symbol of speed.','गरुड़ सर्पों का शत्रु और गति का प्रतीक माना जाता है।');
INSERT INTO trivia_facts VALUES(458,'Vishnu’s avatars appear in different Yugas to restore balance.','विष्णु के अवतार विभिन्न युगों में संतुलन स्थापित करने के लिए प्रकट होते हैं।');
INSERT INTO trivia_facts VALUES(459,'Vaikuntha Ekadashi is considered highly sacred for Vishnu devotees.','वैकुंठ एकादशी विष्णु भक्तों के लिए अत्यंत पवित्र मानी जाती है।');
INSERT INTO trivia_facts VALUES(460,'Vishnu represents the sustaining force of the universe.','विष्णु ब्रह्मांड की पालन करने वाली शक्ति का प्रतिनिधित्व करते हैं।');
INSERT INTO trivia_facts VALUES(461,'Ancient Hindu texts calculated the Earth–Sun distance with surprising closeness to modern values.','प्राचीन हिंदू ग्रंथों में पृथ्वी और सूर्य की दूरी का आश्चर्यजनक रूप से सटीक अनुमान मिलता है।');
INSERT INTO trivia_facts VALUES(462,'The concept of infinite universes is described in the Brahmanda Purana.','ब्रह्मांड पुराण में अनंत ब्रह्मांडों की अवधारणा का वर्णन मिलता है।');
INSERT INTO trivia_facts VALUES(463,'Hindu cosmology measures time in Kalpas, each spanning billions of years.','हिंदू ब्रह्मांड विज्ञान में समय को कल्पों में मापा जाता है, जो अरबों वर्षों तक होते हैं।');
INSERT INTO trivia_facts VALUES(464,'The Nasadiya Sukta questions creation itself, showing early scientific thinking.','नासदीय सूक्त सृष्टि पर प्रश्न उठाता है, जो प्रारंभिक वैज्ञानिक सोच को दर्शाता है।');
INSERT INTO trivia_facts VALUES(465,'Sanskrit grammar by Panini is considered comparable to modern computer algorithms.','पाणिनि का संस्कृत व्याकरण आधुनिक कंप्यूटर एल्गोरिद्म के समान माना जाता है।');
INSERT INTO trivia_facts VALUES(466,'The concept of consciousness as the base of reality is central to Vedanta.','वेदांत में चेतना को वास्तविकता का आधार माना गया है।');
INSERT INTO trivia_facts VALUES(467,'Hindu texts describe flying machines called Vimanas.','हिंदू ग्रंथों में विमानों का वर्णन मिलता है।');
INSERT INTO trivia_facts VALUES(468,'The idea of cyclic time contrasts with the linear time of many other cultures.','चक्रीय समय की अवधारणा कई अन्य संस्कृतियों के रैखिक समय से भिन्न है।');
INSERT INTO trivia_facts VALUES(469,'The number 432,000 appears repeatedly in Hindu time calculations.','432,000 संख्या हिंदू समय गणनाओं में बार-बार दिखाई देती है।');
INSERT INTO trivia_facts VALUES(470,'The Mahabharata describes complex political strategies still studied today.','महाभारत में जटिल राजनीतिक रणनीतियों का वर्णन है जो आज भी अध्ययन की जाती हैं।');
INSERT INTO trivia_facts VALUES(471,'The Upanishads discuss self-realization thousands of years before modern psychology.','उपनिषद हजारों वर्ष पहले आत्मबोध की चर्चा करते हैं, जो आधुनिक मनोविज्ञान से पहले की है।');
INSERT INTO trivia_facts VALUES(472,'Hinduism allows questioning and debate as part of spiritual growth.','हिंदू धर्म में प्रश्न और वाद-विवाद को आध्यात्मिक विकास का हिस्सा माना जाता है।');
INSERT INTO trivia_facts VALUES(473,'The concept of Guru-Shishya tradition ensured knowledge transfer for millennia.','गुरु-शिष्य परंपरा ने हजारों वर्षों तक ज्ञान के संचार को सुनिश्चित किया।');
INSERT INTO trivia_facts VALUES(474,'The Surya Siddhanta calculated planetary motions with high precision.','सूर्य सिद्धांत में ग्रहों की गति की अत्यंत सटीक गणना की गई है।');
INSERT INTO trivia_facts VALUES(475,'The idea that sound creates reality is embedded in the concept of Nada Brahma.','नाद ब्रह्म की अवधारणा में ध्वनि को सृष्टि का आधार माना गया है।');
INSERT INTO trivia_facts VALUES(476,'Ancient sages described meditation states similar to modern neuroscience findings.','प्राचीन ऋषियों ने ध्यान की अवस्थाओं का वर्णन किया जो आधुनिक न्यूरोसाइंस से मेल खाता है।');
INSERT INTO trivia_facts VALUES(477,'The concept of inner energy channels called Nadis is described in yoga texts.','योग ग्रंथों में नाड़ियों नामक आंतरिक ऊर्जा मार्गों का वर्णन है।');
INSERT INTO trivia_facts VALUES(478,'Hindu rituals often synchronize with lunar cycles for precision timing.','हिंदू अनुष्ठान सटीक समय के लिए चंद्र चक्रों के अनुसार होते हैं।');
INSERT INTO trivia_facts VALUES(479,'The idea of multiple paths to truth makes Hinduism highly inclusive.','सत्य तक पहुँचने के कई मार्गों की अवधारणा हिंदू धर्म को समावेशी बनाती है।');
INSERT INTO trivia_facts VALUES(480,'The Bhagavad Gita combines philosophy, psychology, and ethics in one text.','भगवद गीता में दर्शन, मनोविज्ञान और नैतिकता का समन्वय है।');
INSERT INTO trivia_facts VALUES(481,'Ancient Indian astronomers knew that the Earth rotates on its axis.','प्राचीन भारतीय खगोलविदों को ज्ञात था कि पृथ्वी अपनी धुरी पर घूमती है।');
INSERT INTO trivia_facts VALUES(482,'The concept of illusion or Maya aligns with modern philosophical skepticism.','माया की अवधारणा आधुनिक दार्शनिक संशयवाद से मेल खाती है।');
INSERT INTO trivia_facts VALUES(483,'The idea of balance between Dharma, Artha, Kama, and Moksha is unique.','धर्म, अर्थ, काम और मोक्ष के संतुलन की अवधारणा अद्वितीय है।');
INSERT INTO trivia_facts VALUES(484,'Hindu temple layouts often mirror the human body structure.','हिंदू मंदिरों की संरचना अक्सर मानव शरीर के अनुरूप होती है।');
INSERT INTO trivia_facts VALUES(485,'The concept of cosmic sound Om is linked to vibration theory.','ॐ की अवधारणा कंपन सिद्धांत से जुड़ी हुई मानी जाती है।');
INSERT INTO trivia_facts VALUES(486,'The Rigveda mentions rivers that no longer exist today.','ऋग्वेद में ऐसी नदियों का उल्लेख है जो आज अस्तित्व में नहीं हैं।');
INSERT INTO trivia_facts VALUES(487,'The idea of universal oneness appears in the phrase Vasudhaiva Kutumbakam.','वसुधैव कुटुम्बकम् में सार्वभौमिक एकता का विचार प्रकट होता है।');
INSERT INTO trivia_facts VALUES(488,'The concept of reincarnation influenced many global philosophies.','पुनर्जन्म की अवधारणा ने कई वैश्विक दर्शन को प्रभावित किया।');
INSERT INTO trivia_facts VALUES(489,'The idea that knowledge leads to liberation is central to Jnana Yoga.','ज्ञान से मुक्ति का विचार ज्ञान योग का मूल है।');
INSERT INTO trivia_facts VALUES(490,'The concept of devotion as a path to liberation is called Bhakti Yoga.','भक्ति के माध्यम से मुक्ति को भक्ति योग कहा जाता है।');
INSERT INTO trivia_facts VALUES(491,'The idea of action without attachment is Karma Yoga.','फल की आसक्ति के बिना कर्म करना कर्म योग है।');
INSERT INTO trivia_facts VALUES(492,'Ancient texts describe eclipses with scientific explanations.','प्राचीन ग्रंथों में ग्रहणों का वैज्ञानिक वर्णन मिलता है।');
INSERT INTO trivia_facts VALUES(493,'The concept of time cycles includes repeating universes and dissolutions.','समय चक्रों में बार-बार सृष्टि और प्रलय का वर्णन है।');
INSERT INTO trivia_facts VALUES(494,'Hindu philosophy integrates science, spirituality, and daily life seamlessly.','हिंदू दर्शन विज्ञान, आध्यात्म और जीवन को सहज रूप से जोड़ता है।');
INSERT INTO trivia_facts VALUES(495,'The idea that the divine exists within every being is fundamental.','हर जीव में ईश्वर का अस्तित्व मूल विचार है।');
INSERT INTO trivia_facts VALUES(496,'The concept of tapas or disciplined effort is key to transformation.','तप या अनुशासन परिवर्तन का प्रमुख साधन है।');
INSERT INTO trivia_facts VALUES(497,'Ancient sages described breath control as a tool to influence the mind.','प्राचीन ऋषियों ने प्राणायाम को मन को नियंत्रित करने का साधन बताया।');
INSERT INTO trivia_facts VALUES(498,'The concept of sacred geometry appears in temple and yantra designs.','मंदिर और यंत्रों में पवित्र ज्यामिति का उपयोग किया गया है।');
INSERT INTO trivia_facts VALUES(499,'The idea of living in harmony with nature is deeply rooted in Hindu thought.','प्रकृति के साथ सामंजस्य में जीने का विचार हिंदू धर्म में गहराई से जुड़ा है।');
INSERT INTO trivia_facts VALUES(500,'The concept of Aham Brahmasmi declares that the self is identical with the ultimate reality.','अहं ब्रह्मास्मि की अवधारणा बताती है कि आत्मा ही परम सत्य के समान है।');
INSERT INTO trivia_facts VALUES(501,'The Kedarnath Temple is believed to be over 1,200 years old and stands at an altitude of 11,755 feet.','केदारनाथ मंदिर को 1,200 वर्ष से अधिक पुराना माना जाता है और यह 11,755 फीट की ऊँचाई पर स्थित है।');
INSERT INTO trivia_facts VALUES(502,'The Badrinath Temple is part of the Char Dham pilgrimage circuit.','बद्रीनाथ मंदिर चार धाम यात्रा का हिस्सा है।');
INSERT INTO trivia_facts VALUES(503,'The Ranganathaswamy Temple in Srirangam is the largest functioning temple complex in India.','श्रीरंगम का रंगनाथस्वामी मंदिर भारत का सबसे बड़ा कार्यरत मंदिर परिसर है।');
INSERT INTO trivia_facts VALUES(504,'The Golden Temple in Vellore has over 1,500 kg of gold used in its construction.','वेल्लोर के स्वर्ण मंदिर के निर्माण में 1,500 किलोग्राम से अधिक सोने का उपयोग हुआ है।');
INSERT INTO trivia_facts VALUES(505,'The Kamakhya Temple is one of the oldest Shakti Peethas in India.','कामाख्या मंदिर भारत के सबसे प्राचीन शक्तिपीठों में से एक है।');
INSERT INTO trivia_facts VALUES(506,'The Meenakshi Temple has 14 towering gopurams decorated with colorful sculptures.','मीनाक्षी मंदिर में 14 विशाल गोपुरम हैं जो रंगीन मूर्तियों से सजे हैं।');
INSERT INTO trivia_facts VALUES(507,'The Tirupati Temple’s Laddu prasadam has a Geographical Indication tag.','तिरुपति मंदिर के लड्डू प्रसाद को भौगोलिक संकेत (GI) टैग प्राप्त है।');
INSERT INTO trivia_facts VALUES(508,'The Somnath Temple has been destroyed and rebuilt multiple times in history.','सोमनाथ मंदिर को इतिहास में कई बार तोड़ा और पुनर्निर्मित किया गया है।');
INSERT INTO trivia_facts VALUES(509,'The Lingaraj Temple in Bhubaneswar is dedicated to Harihara, a fusion of Shiva and Vishnu.','भुवनेश्वर का लिंगराज मंदिर हरिहर को समर्पित है, जो शिव और विष्णु का संयुक्त रूप है।');
INSERT INTO trivia_facts VALUES(510,'The Sun Temple at Modhera is aligned with the equinox sunrise.','मोढेरा का सूर्य मंदिर विषुव के सूर्योदय के साथ संरेखित है।');
INSERT INTO trivia_facts VALUES(511,'The Chennakesava Temple in Belur features intricate carvings with mirror-like polish.','बेलूर का चेनकेशव मंदिर अत्यंत सूक्ष्म और चमकदार नक्काशी के लिए प्रसिद्ध है।');
INSERT INTO trivia_facts VALUES(512,'The Jagannath Temple’s Rath Yatra involves massive chariots pulled by thousands of devotees.','जगन्नाथ मंदिर की रथ यात्रा में हजारों भक्त विशाल रथों को खींचते हैं।');
INSERT INTO trivia_facts VALUES(513,'The Vaishno Devi Temple requires a trek of around 13 kilometers to reach.','वैष्णो देवी मंदिर तक पहुँचने के लिए लगभग 13 किलोमीटर की यात्रा करनी पड़ती है।');
INSERT INTO trivia_facts VALUES(514,'The Ekambareswarar Temple represents the Earth element among the Pancha Bhoota temples.','एकाम्बरेश्वर मंदिर पंचभूत मंदिरों में पृथ्वी तत्व का प्रतिनिधित्व करता है।');
INSERT INTO trivia_facts VALUES(515,'The Arunachaleswarar Temple represents the Fire element among the Pancha Bhoota temples.','अरुणाचलेश्वर मंदिर पंचभूत मंदिरों में अग्नि तत्व का प्रतिनिधित्व करता है।');
INSERT INTO trivia_facts VALUES(516,'The Jambukeswarar Temple represents the Water element among the Pancha Bhoota temples.','जम्बुकेश्वर मंदिर पंचभूत मंदिरों में जल तत्व का प्रतिनिधित्व करता है।');
INSERT INTO trivia_facts VALUES(517,'The Kalahasti Temple represents the Air element among the Pancha Bhoota temples.','कालहस्ती मंदिर पंचभूत मंदिरों में वायु तत्व का प्रतिनिधित्व करता है।');
INSERT INTO trivia_facts VALUES(518,'The Chidambaram Temple represents the Space element among the Pancha Bhoota temples.','चिदंबरम मंदिर पंचभूत मंदिरों में आकाश तत्व का प्रतिनिधित्व करता है।');
INSERT INTO trivia_facts VALUES(519,'The Hoysaleswara Temple is famous for its detailed soapstone carvings.','होयसलेश्वर मंदिर अपनी बारीक सोपस्टोन नक्काशी के लिए प्रसिद्ध है।');
INSERT INTO trivia_facts VALUES(520,'The Dilwara Temples in Mount Abu are known for their marble carvings.','माउंट आबू के दिलवाड़ा मंदिर अपनी संगमरमर की नक्काशी के लिए प्रसिद्ध हैं।');
INSERT INTO trivia_facts VALUES(521,'The Kanchipuram temples are known as the city of a thousand temples.','कांचीपुरम को हजार मंदिरों का शहर कहा जाता है।');
INSERT INTO trivia_facts VALUES(522,'The Dwarkadhish Temple flag is changed multiple times a day.','द्वारकाधीश मंदिर का ध्वज दिन में कई बार बदला जाता है।');
INSERT INTO trivia_facts VALUES(523,'The Mahabodhi Temple in Bodh Gaya marks the place of Buddha’s enlightenment.','बोधगया का महाबोधि मंदिर बुद्ध के ज्ञान प्राप्ति स्थल को दर्शाता है।');
INSERT INTO trivia_facts VALUES(524,'The Nathdwara Temple houses the idol of Shrinathji, a form of Krishna.','नाथद्वारा मंदिर में श्रीनाथजी की मूर्ति स्थापित है, जो कृष्ण का रूप है।');
INSERT INTO trivia_facts VALUES(525,'The Ujjain Mahakaleshwar Temple performs the unique Bhasma Aarti.','उज्जैन का महाकालेश्वर मंदिर विशेष भस्म आरती के लिए प्रसिद्ध है।');
INSERT INTO trivia_facts VALUES(526,'The Srisailam Temple is one of the twelve Jyotirlingas and a Shakti Peetha.','श्रीशैलम मंदिर बारह ज्योतिर्लिंगों में से एक और एक शक्तिपीठ भी है।');
INSERT INTO trivia_facts VALUES(527,'The Pushkar Temple is one of the few temples dedicated to Lord Brahma.','पुष्कर मंदिर भगवान ब्रह्मा को समर्पित कुछ मंदिरों में से एक है।');
INSERT INTO trivia_facts VALUES(528,'The Hampi Virupaksha Temple has been in continuous worship since the 7th century.','हम्पी का विरुपाक्ष मंदिर 7वीं शताब्दी से लगातार पूजा का केंद्र बना हुआ है।');
INSERT INTO trivia_facts VALUES(529,'The Siddhivinayak Temple in Mumbai is dedicated to Lord Ganesha.','मुंबई का सिद्धिविनायक मंदिर भगवान गणेश को समर्पित है।');
INSERT INTO trivia_facts VALUES(530,'The Kalighat Temple in Kolkata is one of the 51 Shakti Peethas.','कोलकाता का कालीघाट मंदिर 51 शक्तिपीठों में से एक है।');
INSERT INTO trivia_facts VALUES(531,'The Dakshineswar Temple is associated with Ramakrishna Paramahamsa.','दक्षिणेश्वर मंदिर रामकृष्ण परमहंस से जुड़ा हुआ है।');
INSERT INTO trivia_facts VALUES(532,'The ISKCON temples are spread across the world promoting Krishna devotion.','इस्कॉन मंदिर विश्वभर में फैले हैं और कृष्ण भक्ति का प्रचार करते हैं।');
INSERT INTO trivia_facts VALUES(533,'The Bhimashankar Temple is located in a dense forest area of Maharashtra.','भीमाशंकर मंदिर महाराष्ट्र के घने जंगलों में स्थित है।');
INSERT INTO trivia_facts VALUES(534,'The Grishneshwar Temple is the smallest Jyotirlinga temple.','घृष्णेश्वर मंदिर सबसे छोटा ज्योतिर्लिंग मंदिर माना जाता है।');
INSERT INTO trivia_facts VALUES(535,'The Trimbakeshwar Temple is associated with the origin of the Godavari river.','त्र्यंबकेश्वर मंदिर गोदावरी नदी के उद्गम से जुड़ा है।');
INSERT INTO trivia_facts VALUES(536,'The Omkareshwar Temple is one of the twelve Jyotirlingas located on the Narmada river.','ओंकारेश्वर मंदिर नर्मदा नदी पर स्थित बारह ज्योतिर्लिंगों में से एक है।');
INSERT INTO trivia_facts VALUES(537,'The Sabarimala Temple follows strict pilgrimage rituals including a 41-day vrata.','सबरीमला मंदिर में 41 दिन के व्रत सहित कठोर नियमों का पालन किया जाता है।');
INSERT INTO trivia_facts VALUES(538,'The Kashi Vishwanath Temple is one of the most revered Shiva temples in India.','काशी विश्वनाथ मंदिर भारत के सबसे पूजनीय शिव मंदिरों में से एक है।');
INSERT INTO trivia_facts VALUES(539,'The Rameshwaram Temple is associated with Lord Rama’s return from Lanka.','रामेश्वरम मंदिर भगवान राम के लंका से लौटने से जुड़ा हुआ है।');
INSERT INTO trivia_facts VALUES(540,'The Annamalaiyar Temple hosts the grand Karthigai Deepam festival.','अन्नामलैयार मंदिर में भव्य कार्तिगई दीपम उत्सव मनाया जाता है।');
INSERT INTO trivia_facts VALUES(541,'The Jagannath Rath Yatra takes place every year in Puri.','जगन्नाथ रथ यात्रा हर वर्ष पुरी में आयोजित होती है।');
INSERT INTO trivia_facts VALUES(542,'The return journey of the chariots during Jagannath Yatra is known as Bahuda Yatra.','जगन्नाथ यात्रा के दौरान रथों की वापसी यात्रा को बहुदा यात्रा कहा जाता है।');
INSERT INTO trivia_facts VALUES(543,'The chariot of Lord Jagannath is called Nandighosha.','भगवान जगन्नाथ के रथ को नंदीघोष कहा जाता है।');
INSERT INTO trivia_facts VALUES(544,'The Jagannath Rath Yatra symbolizes the Lord coming out to meet his devotees.','जगन्नाथ रथ यात्रा भगवान के अपने भक्तों से मिलने बाहर आने का प्रतीक है।');
INSERT INTO trivia_facts VALUES(545,'The Sabarimala pilgrimage requires a strict 41-day vrata before visiting the temple.','सबरीमला यात्रा से पहले 41 दिनों का कठोर व्रत रखना आवश्यक होता है।');
INSERT INTO trivia_facts VALUES(546,'The Brihadeeswara Temple was built using granite without nearby sources of stone.','बृहदेश्वर मंदिर का निर्माण ग्रेनाइट से किया गया, जबकि आसपास पत्थर के स्रोत नहीं थे।');
INSERT INTO trivia_facts VALUES(547,'The Chidambaram Temple uniquely worships empty space as the divine.','चिदंबरम मंदिर में खाली स्थान को ही ईश्वर के रूप में पूजा जाता है।');
INSERT INTO trivia_facts VALUES(548,'The Tirupati Balaji Temple receives tons of hair offerings every day.','तिरुपति बालाजी मंदिर में प्रतिदिन बड़ी मात्रा में बाल अर्पित किए जाते हैं।');
INSERT INTO trivia_facts VALUES(549,'The Meenakshi Temple has a hall with 1,000 pillars, each uniquely carved.','मीनाक्षी मंदिर में 1000 स्तंभों का मंडप है, जिनमें हर स्तंभ अलग नक्काशी वाला है।');
INSERT INTO trivia_facts VALUES(550,'The Padmanabhaswamy Temple is considered one of the richest temples in the world.','पद्मनाभस्वामी मंदिर दुनिया के सबसे धनी मंदिरों में से एक माना जाता है।');
INSERT INTO trivia_facts VALUES(551,'The Udupi Krishna idol is worshipped through a window instead of directly.','उडुपी कृष्ण की मूर्ति की पूजा सीधे नहीं बल्कि एक खिड़की से की जाती है।');
INSERT INTO trivia_facts VALUES(552,'The Ramanathaswamy Temple has corridors stretching over 1,200 meters.','रामनाथस्वामी मंदिर के गलियारे 1200 मीटर से अधिक लंबे हैं।');
INSERT INTO trivia_facts VALUES(553,'The Lepakshi Temple has a pillar that appears to hang without support.','लेपाक्षी मंदिर में एक स्तंभ बिना सहारे के लटका हुआ प्रतीत होता है।');
INSERT INTO trivia_facts VALUES(554,'The Ekambareswarar Temple has a mango tree believed to be thousands of years old.','एकाम्बरेश्वर मंदिर में एक आम का पेड़ है जिसे हजारों वर्ष पुराना माना जाता है।');
INSERT INTO trivia_facts VALUES(555,'The Sringeri Temple was established after witnessing a cobra protecting a frog.','श्रृंगेरी मंदिर की स्थापना एक नाग को मेंढक की रक्षा करते देखकर की गई थी।');
INSERT INTO trivia_facts VALUES(556,'The Annamalaiyar Temple hosts a giant fire ritual visible from miles during Karthigai Deepam.','अन्नामलैयार मंदिर में कार्तिगई दीपम के दौरान विशाल अग्नि अनुष्ठान दूर-दूर तक दिखाई देता है।');
INSERT INTO trivia_facts VALUES(557,'The Murudeshwar Temple has one of the tallest Shiva statues in the world.','मुरुदेश्वर मंदिर में दुनिया की सबसे ऊंची शिव मूर्तियों में से एक स्थित है।');
INSERT INTO trivia_facts VALUES(558,'The Guruvayur Temple follows strict dress codes for entry.','गुरुवायुर मंदिर में प्रवेश के लिए सख्त वस्त्र नियम हैं।');
INSERT INTO trivia_facts VALUES(559,'The Chennakesava Temple carvings are so detailed they appear like jewelry.','चेनकेशव मंदिर की नक्काशी इतनी सूक्ष्म है कि वह आभूषण जैसी दिखती है।');
INSERT INTO trivia_facts VALUES(560,'The Kalady is believed to be the birthplace of Adi Shankaracharya.','कालडी को आदि शंकराचार्य का जन्मस्थान माना जाता है।');
INSERT INTO trivia_facts VALUES(561,'The Srirangam Temple is spread across seven concentric enclosures.','श्रीरंगम मंदिर सात परिधियों में फैला हुआ है।');
INSERT INTO trivia_facts VALUES(562,'The Nataraja form of Shiva originated from Chidambaram Temple traditions.','शिव का नटराज रूप चिदंबरम मंदिर की परंपराओं से उत्पन्न हुआ।');
INSERT INTO trivia_facts VALUES(563,'The Kanchipuram city is known as the city of thousand temples.','कांचीपुरम को हजार मंदिरों का शहर कहा जाता है।');
INSERT INTO trivia_facts VALUES(564,'The Thanjavur Temple dome is made from a single massive stone.','तंजावुर मंदिर का गुंबद एक ही विशाल पत्थर से बना है।');
INSERT INTO trivia_facts VALUES(565,'Ksheer Sagar is the cosmic ocean of milk where Vishnu rests on Sheshanaga.','क्षीर सागर वह दिव्य समुद्र है जहाँ विष्णु शेषनाग पर शयन करते हैं।');
